INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1,'Сначала приготовим все необходимые ингредиенты. Овощи помоем под проточной водой.','https://vkuso.ru/data/cache/data/a1/93d6b58cc8453a1_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1,'Нарезаем огурцы.','https://vkuso.ru/data/cache/data/f7/9a50fc208a313f7_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1,'Шинкуем капусту.','https://vkuso.ru/data/cache/data/13/0f9904e71edc413_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1,'Рубим лук и петрушку, добавляем их к огурцам и капусте.','https://vkuso.ru/data/cache/data/e9/0cbc2d9d3c777e9_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1,'Добавляем сметану, солим и перчим по вкусу.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2,'Положить ягоды малины в кастрюлю, засыпать сахаром, дать чуть постоять, осторожно перемешать, довести до кипения, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2,'Переложить ягоды в чашу блендера, влить охлажденное молоко, добавить мороженое. Взбить молочный коктейль с малиной в течение пары минут до появления пены, разлить по высоким стаканам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3,'Приготовить опару из дрожжей, молока, муки и сахарного песка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3,'Перемешать, разбить комочки, оставить в тепле на сорок минут, емкость прикрыть чистой тканью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3,'Масса должна пениться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3,'Взбить 2 яйца с солью и сахаром, влить растительное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3,'Ввести смесь в опару.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3,'Замесить тесто, муку всыпать порциями.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3,'Тесто должно получиться эластичным, оставить его в тепле на час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3,'Готовое тесто разрезать на равные небольшие кусочки, каждый раскатать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3,'Положить по столовой ложке повидла, свернуть в рулеты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3,'Противень застелить бумагой, выложить рогалики, оставить на полчаса.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3,'Смазать изделия оставшимися взбитыми яйцами, поставить в духовку. Температура выпекания – 180 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4,'Достать из холодильника заранее сыр и масло, чтобы они нагрелись до комнатной температуры. Отделить белки и взбить, всыпать сахар, чуть соли. Положить в миску сливочный сыр, добавить масло, перемешать миксером на низких оборотах в однородную массу. Влить во время взбивания сок лимона, добавить по одному желтки яиц, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4,'Добавить молоко, все смешать в однородную массу, всыпать муку и крахмал, аккуратно перемешать. Порциями к смеси добавить белки, осторожно перемешать все снизу вверх. Подготовить форму, положить  пергамент, обернуть несколькими слоями фольги. Заполнить форму тестом, поставить на противень с высокими бортиками, залить в него горячую воду, чтобы она доходила до половины высоты формы, поставить на час в прогретую до 150 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4,'Достать из духовки, вынуть из формы, дать хорошо остыть, присыпать сахарной пудрой. Повидло из сливы прогреть на небольшом огне, добавить сливовую водку перемешать, полученной пропиткой полить верх десерта. Разрезать японский чизкейк с повидлом лучше только после полного остывания, а еще лучше после часа пребывания в холодильнике.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5,'Чистим и потрошим скумбрию.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5,'Делаем неглубокие надрезы на спинке скумбрии.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5,'Смешиваем соль, перец черный молотый, перец острый и сухой базилик.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5,'Натираем скумбрию специями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5,'Поливаем соком лимона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5,'Жарим на углях по 7 минут с каждой стороны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6,'Растворить дрожжи с сахарным песком на молоке, оставить на несколько минут, до появления пены.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6,'Дрожжи соединить с пшеничной мукой, сахаром, сливочным и растительным маслом, ванильным сахаром из пакетика, солью, мукой, крахмалом и водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6,'Массу хорошо вымесить, оставить при комнатной температуре на час или полтора.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6,'Приготовить начинку: положить в сотейник замороженную вишню, всыпать крахмал, сахар, влить немного воды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6,'Потомить массу на огне до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6,'Когда начинка загустеет – ее нужно охладить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6,'Готовое тесто разделить пополам, раскатать круглые лепешки, разрезать на двенадцать треугольников каждую.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6,'Выложить начинку и скатать рогалики.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6,'Время выпекания: от 25 до 30 минут, температура – от 175 до 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7,'Прессованные дрожжи смешать со 100 г сахара, теплым цельным молоком, мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7,'Оставить в тепле на пятнадцать или двадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7,'Просеять муку горкой, всыпать соль, сформовать углубление, влить опару и взболтанные яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7,'Вымешать массу, в процессе приготовления добавить мягкое сливочное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7,'Тесто оставить в тепле на час, оно должно удвоиться в размерах.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7,'Сухой мак запарить в кипящей воде, время – сорок минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7,'Воду слить, начинку растереть в однородную массу при помощи блендера, оставшийся сахар подсыпать порциями.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7,'Сформовать рогалики: раскатать тесто в лепешки, а затем разрезать на сегменты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7,'Выложить начинку, свернуть маленькие рулеты, изогнуть их подковами.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7,'Печь рогалики до появления корочки, температура – 180 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8,'Маргарин растопить, отдельно подогреть молоко, развести в нем дрожжи и сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8,'В дрожжевую массу ввести муку, вмешать яйца и теплый маргарин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8,'Перемешать массу ложкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8,'Всыпать муку порциями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8,'Масса должна получиться эластичной и мягкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8,'Оставить ее на время.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8,'Вымыть яблоки, очистить кожуру, мякоть нарезать кубиками, посыпать их молотой корицей и сахарным песком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8,'Сформовать рогалики, запечь в духовом шкафу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9,'Согреть молоко, развести в нем сахар, соль, дрожжи, мягкое сливочное масло и взбитые куриные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9,'Вмешать муку, оставить тесто на расстойку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9,'После подъема массу обмять, оставить еще на некоторое время.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9,'Раскатать тесто в пласт толщиной в пять миллиметров.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9,'Нарезать полосками размером 15 на 2 сантиметра.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9,'Каждую молочную сосиску обмотать тестом, запечь до румяной корочки в духовке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9,'По желанию перед выпечкой изделия можно смазать растительным маслом или яйцом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10,'Смешиваем чеснок, зелень и сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10,'Маринад. Смешиваем черный молотый перец, соль, красный острый перец и растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10,'Натираем цыпленка маринадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10,'Жарим на углях 25-30 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10,'Смазываем цыпленка маслом,чесноком, зеленью и жарим ещё 5 минут. Готовьте с удовольствием и приятного аппетита!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11,'Сложить шоколадное печенье в пакет, прокатать скалкой до образования крошки, растопить масло на водяной бане, тщательно перемешать с крошкой, уложить на дно разъемной формы, утрамбовать. Запечь основу для чизкейка в прогретом до 170 градусов духовом шкафу в течение 10 минут, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11,'Для приготовления начинки взбить венчиком сахар со сливочным сыром до состояния крема. Добавить по одному яйца, хорошо перемешать начинку после добавления каждого, влить сметану, перемешать. В крем добавить растопленный шоколад, окончательно перемешать, заполнить полностью остывшую основу, разровнять, запечь при 160 градусах в течение часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11,'Чизкейк можно считать готовым, когда мягкой останется только серединка десерта, тогда отключить нагрев, дать постоять в духовом шкафу еще час, потом достать и окончательно остудить, убрать в холодильник на 4-5 часов. Приготовить из хорошо прогретых сливок и кусочков шоколада глазурь, покрыть нежный чизкейк «Шоколадное наслаждение», поставить на полчаса застыть в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12,'Натерла на мелкой терке твердый сыр. У меня «Российский». Добавила к сыру 3 яйца и майонез и все хорошо перемешала. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12,'Пока «тесто» запекалось, приготовила начинку. Фарш (у меня свиной) с луком.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (23,'Очистить репчатый лук, каждую луковицу разрезать на четыре части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (23,'Размолоть продукты при помощи блендера или мясорубки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (34,'Фарш вымешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12,'Готовому коржу дала немного остыть. Затем выложила на него фарш и равномерно распределила по коржу. Свернула корж в рулет. И поставила выпекаться в разогретую до 180 ° духовку на 40 минут. Рулет при выпекании накрыла пергаментом, можно и не накрывать, тогда у него получится хрустящая румяная корочка.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13,'Яйца, сахар и соль смешать и взбить до пышности и изменения цвета около 5 мин.','https://vkuso.ru/data/cache/data/85/4002dbf6f3d1b85_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13,'Во взбитую массу натереть цедру 1/2 крупного или 1 мелкого лимона и добавить лимонный сок 1/2 крупного или 1 мелкого лимона, все перемешать.','https://vkuso.ru/data/cache/data/bb/19bb8f07a8c31bb_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13,'Добавить сливки и растительное масло, постоянно перемешивая смесь до однородности.','https://vkuso.ru/data/cache/data/35/850ecc8b9d06b35_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13,'Просеять в массу муку и добавить разрыхлитель, все хорошо перемешать.','https://vkuso.ru/data/cache/data/b4/df64b1082681cb4_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13,'Дно формы для запекания застелить пекарской бумагой и хорошо смазать бумагу и стенки формы растительным маслом.','https://vkuso.ru/data/cache/data/0c/90196813332d50c_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13,'Равномерно залить тесто в форму.','https://vkuso.ru/data/cache/data/91/4c2ee9242807791_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13,'Выпекать в заранее разогретой духовке до готовности. Готовность проверить зубочисткой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13,'Готовый пирог остудить и извлечь из формы.','https://vkuso.ru/data/cache/data/08/d4d5bfaa9775708_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13,'Посыпать сахарной пудрой.','https://vkuso.ru/data/cache/data/53/220b3c849098c53_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13,'Вот такой пышный и нежный пирог получился. Подаем его к чаю, кофе или со стаканчиком молока.','https://vkuso.ru/data/cache/data/b5/71ddc3d6e156ab5_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (14,'Разогреть на сковороде сливочное масло, добавить пропущенный через пресс чеснок, слегка прогреть и влить сливки, дать закипеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (14,'Положить в сковороду очищенные креветки, тушить при  слабом нагреве минут 10. Нашинковать мелко зелень, высыпать к креветкам, прогреть еще пару минут',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (14,'Переложить креветки в тарелку, а соус продолжать нагревать до тех пор, пока он не загустеет. В сливочный соус положить креветки, размешать, прогреть минуты три, снять с огня, выложить на блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (15,'Поставить в духовку керамическую форму, включить прогреваться духовку примерно до 250 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (15,'Помыть куриное филе, удалить кожу, обсушить, тщательно обвалять со всех сторон в панировочных сухарях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (15,'Вынуть форму, сбрызнуть аккуратно дно маслом, добавить соль, уложить филе, по верху посолить и вернуть на 10 минут форму в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (15,'Открыть духовку, перевернуть мясо, прикрыть куриное филе пластинками сливочного масла, запекать еще 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (15,'Переложить сочное куриное филе на тарелку, дать полежать минут пять и порезать на порции.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (16,'Для начала приготовим соус. В небольшой миске смешаем крахмал,ананасовый сок , протертый имбирь, чеснок, соевый соус, уксус, сахар, кетчуп, хлопья чили, паприку и все хорошо перемешаем. Уберем в сторону.','https://vkuso.ru/data/cache/data/90/1966113f55b2a90_434x295_notrise.jpeg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (16,'Нарежем курицу,лук, перец, ананас одного размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (16,'Теперь разогреваем масло в сковородке. Сначала обжарим в течение пару минут курицу, после добавим лук и перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (16,'За 4-5 минут до готовности, добавим соус и ананас. Продолжаем готовить на среднем огне до загустения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (16,'В конце добавим порезанный зеленый лук и перед подачей можно посыпать кунжутом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (17,'Включить и разогреть духовку до 190 градусов. Измельчить зубчики чеснока, перемешать с порубленными листиками розмарина, залить маслом, приправить солью и черным перцем, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (17,'Тщательно помыть картофель с помощью щеточки, порезать очень тонкими ломтиками, погрузить в пряное масло, стряхнуть излишки масла и выложить внахлест на противень, как черепицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (23,'Влить в массу молоко, вбить яйца, всыпать соль и муку, влить немного масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (34,'Испечь коржи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (17,'Задвинуть противень в прогретую  духовку, запекать домашние чипсы с зеленью в духовке минут 40 до появления аппетитного цвета. Достать противень, переложить подсушенные ломтики на тарелку в один слой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (18,'Включить духовку и прогреть до 180 градусов. Вскрыть банку с ананасами, сцедить в кружку сок, уложить их на дно формы. Налить в сковородку масло, насыпать сахар, перемешать, варить при помешивании и среднем нагреве около 4 минут, снять с плиты, вылить на ананасы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (18,'Просеять муку, добавить ванилин, разрыхлитель, соль. Взбить размягченное сливочное масло миксером в пушистую массу, частями всыпать сахар, взбивая после добавления каждой порции, повторить с яйцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (18,'Всыпать половину подготовленной муки, переключить миксер на низкие обороты, взбить тесто до однородной массы. Влить сок, добавить вторую порцию муки, взбить в однородную массу миксером, аккуратно залить полученным тестом ананасы в форме.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (18,'Выпекать легкий ананасовый пирог 45 минут, расположив форму на средней полочке духовки, до появления золотистого колера. Вынуть десерт, дать постоять в форме еще 5 минут и можно подавать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (19,'В теплом молоке размешать сахар и дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (19,'Всыпать соль и муку, разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (19,'Массу вымешать, оставить на пятьдесят минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (19,'Разрезать тесто на части, нарезать треугольники, сформовать рогалики с начинкой из вареного сгущенного молока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (19,'Изделия смазать куриным желтком, выложить на противень и запечь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (20,'Говяжью печень промыть, очистить от прожилок, пленок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (20,'Продукт нарезать кусками большого размера, залить молоком, оставить на полчаса для вымачивания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (20,'Пропустить через мясорубку, добавить немного молока, чтобы масса не была сухой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (20,'Соль – по вкусу, вмешать муку и яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (20,'Смесь должна получиться по консистенции похожей на блинное тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (20,'Если масса жидкая – добавить муку, если слишком густая – долить молоко.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (20,'Разогреть сковороду, жарить блинчики по минуте с каждой стороны.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (20,'Коржи должны получиться мягкими.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (20,'Приготовить крем из обжаренного репчатого лука, рубленой зелени, майонеза.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (20,'Промазать коржи полученной смесью, поставить на ночь в прохладу для пропитывания.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (21,'Говяжью печень промыть, очистить от пленок, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (21,'Пропустить продукт через мясорубку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (21,'Всыпать муку, влить молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (21,'Соль – по вкусу, перец молотый – по желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (21,'Массу хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (21,'Испечь на сковороде коржики.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (21,'Приготовить начинку из очищенной и натертой моркови, нарезанного репчатого лука и грибов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (21,'Грибы и овощи обжарить на сковороде по отдельности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (21,'Натереть твердый сыр, чеснок очистить и измельчить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (21,'Майонез перемешать с чесноком и сыром.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (21,'Собрать печеночный торт из остывших коржей, прослоить майонезным кремом, грибной и овощной обжаркой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (22,'Репчатый лук очистить и нарезать на четвертинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (22,'Подготовить говяжью печень, пропустить вместе с луком через мясорубку или измельчить блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (22,'Готовую смесь перемешать с мукой, яйцами, сметаной, солью и перцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (22,'Масса должна получиться однородной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (22,'Испечь коржи на сковороде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (22,'Приготовить начинку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (22,'Отварить куриные яйца, очистить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (22,'Натереть на терке, так же поступить с плавленым сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (22,'Чеснок измельчить, перемешать с майонезом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (22,'Первый печеночный корж намазать майонезным соусом, посыпать тертым сыром.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (22,'Следующий корж намазать чесночным кремом и посыпать яйцами.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (22,'Коржи складывать стопкой, прослаивать разными видами начинки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (22,'Готовый торт поставить на два часа в холодильник.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (23,'Говяжью печень очистить от пленок, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2267,'Воду слить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (23,'Масса должна напоминать тесто средней густоты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (23,'Выпечь блинчики-коржи на сковороде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (23,'Баклажаны запечь в духовом шкафу, очистить, мякоть мелко нарезать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (23,'Ошпарить кипятком помидоры, кожицу снять.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (23,'Мякоть нарезать кубиками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (23,'Соединить все продукты для начинки, добавить майонез.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (23,'Сформовать торт, каждый корж промазать кремом с майонезом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (24,'Нарезать мелкими кубиками лук, смешать с фаршем, добавить сыр, яйца, сухари, перец и соль, очень хорошо перемешать. Сформовать небольшие шарики фрикаделек, скатывать с небольшим усилием, чтобы фрикадельки получились после варки плотными и не потеряли форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (24,'Дать закипеть предварительно сваренному бульону, положить нарезанную небольшими брусочками морковь, довести до кипения, проварить минут 5, всыпать макаронные изделия,  помешивая еще около 5 минут. Положить в суп фрикадельки, варить еще 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (24,'Последний штрих,  добавить в суп с мини-фрикадельками из индейки крупно порезанный шпинат, подержать на огне еще около минуты и выключить, прикрыть крышкой, дать настояться. Приятного аппетита!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (25,'Отвариваем овощи, яйца и куриное филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (25,'Салат будем готовить "вверх ногами". Салат готовим в кастрюле или как я в разъемной форме для выпечки. Застелем посуду пищевой пленкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (25,'1 слой: В емкость складываем маринованные грибы вниз шляпками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (25,'2 слой: нарезанная зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (25,'3 слой: натертая картошка. Солим и перчим. Промазываем майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (25,'4 слой: натертые яйца. Тоже солим и перчим. Смазываем майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (25,'5 слой: натертая морковь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (25,'6 слой: натертые огурцы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (25,'7 слой: нарезанная куриная грудка. Перчим и солим по вкусу. Смазываем майонезом',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (25,'8 слой: натертый сыр. Промазываем майонезом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (25,'Накрываем посуду пищевой пленкой и убираем в холодильник на 5-6 часов, а лучше на ночь.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (25,'Накрываем кастрюлю тарелкой и переворачиваем салат. Снимаем форму и пленку.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (26,'Поставить варить филе, нашинковать луковицу, открыть шампиньоны, сок сцедить и обжарить их с луком. За это время натереть на терке со средними отверстиями сыр. Отделить у вареных яиц белок и желток, натереть по отдельности на такой же терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (26,'На широкое блюдо салат выложить в следующем порядке. Первый слой – кубики курицы, промазанные майонезом. Далее половину грибов с луком и майонез, прикрыть половиной натертого сыра с майонезом, присыпать белком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (26,'Опять положить слой оставшегося мяса с майонезом, затем  грибы с луком и майонез. Посыпать тертыми белками от двух яиц, на них выложить остаток стружки сыра с майонезом. Завершить все слои четырьмя тертыми желтками. Салат «Нежность» с куриным филе и грибами готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (27,'Разрезаем куриное филе вдоль и обе части отбиваем через пленку с обеих сторон.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (27,'Сыр натираем на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (27,'Складываем фольгу вдвоем, смазываем маслом и выкладываем слоями кусочек филе и сыр. Плотно прижимаем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (27,'Плотно заворачиваем фольгу, чтобы слои не сместились.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (27,'Отправляем в духовку на температуру 200 градусов примерно на 35-40 минут. Разрезаем только холодным!
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (28,'Разрезать свинину на кусочки толщиной около 1 см.','https://vkuso.ru/data/cache/data/eb/18ff98ce9e21aeb_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (28,'Посолить и поперчить по вкусу.','https://vkuso.ru/data/cache/data/ab/e7abac0e6537cab_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (28,'Нарезать репчатый лук и шампиньоны полу-кольцами и пластинками.','https://vkuso.ru/data/cache/data/59/4b2ff649f543759_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (28,'На растительном масле на сильном огне быстро обжарить свинину примерно по 10-15 сек с каждой стороны, чтобы запечатать весь сок внутри. Свинину снять с огня и отложить в сторону.','https://vkuso.ru/data/cache/data/6b/c875ad0cf6ba56b_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (28,'На растительном масле на сильном огне обжарить шампиньоны с луком до полного выпаривания жидкости и легкого подрумянивания грибов.','https://vkuso.ru/data/cache/data/e1/3817ce9f7fb49e1_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (34,'Вбить яйцо, посолить, поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (28,'Грибы посолить и поперчить по вкусу, добавить в них сладкую паприку, карри и итальянские травы, все перемешать. Сразу после этого добавить муку и все хорошо перемешать, чтобы мука прихватилась.','https://vkuso.ru/data/cache/data/47/3a47ba025223747_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (28,'Влить в грибы молоко, все перемешать до получения однородного начинающего слегка загустевать соуса. Если соус Вам кажется слишком густым можно добавить еще немного молока или воды.','https://vkuso.ru/data/cache/data/61/726dd443eb09f61_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (28,'Уложить в грибной соус поджаренные кусочки свинины, ложкой равномерно покрыть поверхность мяса соусом.','https://vkuso.ru/data/cache/data/7d/02ae8c89acb347d_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (28,'Накрыть крышкой и держать на слабом огне около 30 мин.','https://vkuso.ru/data/cache/data/5f/8c1454ca6d6965f_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (29,'Протереть творог, перемешать с мукой, разрыхлителем, растопленным маслом и яйцами до получения мягкого однородного теста, отправить на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (29,'Достать колобок теста, раскатать в пласт, но не толще 0,5 сантиметра, вырезать подходящей формочкой кружки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (29,'Присыпать их с одной стороны сахарным песком, сложить полукругом, опять присыпать с одной стороны сахаром и сложить пополам, обмакнуть еще раз в сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (29,'Складывать каждый раз сахаром внутрь. Переложить ',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (30,'Ополоснуть кастрюлю очень холодной водой, залить молоко, дать ему закипеть, разлить в жаропрочные стаканы. Плитку шоколада поломать на длинные полосы, положить в каждый стакан по одной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (31,'Соединяем все сыпучие ингредиенты. В миску добавляем 130 грамм пшеничной муки, 40 грамм кукурузной муки, соль, и паприку по вкусу, сахар 2 ч.л разрыхлитель1 ч.л. Все перемешиваем. Для удобства переливаем кляр в большой стакан.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (31,'В другой миске соединяем 1 кур. яйцо и 250 мл молоко, все хорошо взбиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (31,'В сухую смесь добавляем взбитое молоко с яйцом, и все перемешиваем. Кляр должен быть густым!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (31,'Сосиски делим на 2 части, далее обсыпаем их в муке. И примерно по середине вдоль прокалываем шпажкой, но не до конца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (31,'В кляр отпускаем сосиску на шпажке, достаем и даем чуть стечь кляру.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (31,'После этого отпускаем корн дог, в разогретое подсолнечное масло на 15-20 сек. Нужно обжарить до золотистой корочки, Как только обжарили корн дог перекладываем на бумажное полотенце.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (31,'Можно переложить на тарелку и подаем на стол.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Куриную печень разделать, пленки удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Очистить чеснок и лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Продукты измельчить в блендере, вбить сырое куриное яйцо, положить пищевую соду и муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Ингредиенты перемешать, смесь должна получиться средней густоты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Прогреть сковороду с антипригарным покрытием на среднем огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Влить растительное масло, затем – печеночную смесь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Распределить ее на сковороде равномерно.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Выпечь небольшие блины.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Приготовить крем.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Обжарить на сковороде со сливочным маслом тертую морковь и репчатый лук.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Для соуса перемешать нежирную сметану с майонезом, добавить давленый зубчик чеснока и рубленую зелень.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Сложить торт.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Первый корж намазать морковной обжаркой, второй – соусом, третий – морковью, четвертый – снова соусом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Когда коржи закончатся – полить верх соусом и посыпать зеленью.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (32,'Блюдо поставить в холодильник на несколько часов, можно – на ночь.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (33,'Приготовить фарш из измельченной куриной печени, яиц, муки, лука, пищевой соды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (33,'По желанию вместо соды можно использовать разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (33,'Прогреть на дне чаши мультиварки немного растительного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (33,'Вылить часть теста, испечь корж в режиме «Выпечка».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (33,'Готовые блинчики прослоить любой начинкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (33,'Крем можно приготовить из сыра «Филадельфия».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (34,'Говяжью и куриную печень смешать в равных пропорциях. Можно использовать только куриную печень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (34,'Размолоть продукт в блендере или через мясорубку вместе с хлебным мякишем и луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (34,'Отдельно обжарить нарезанные грибы с луком, жидкость должна выпариться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (34,'Готовые коржи прослоить грибами и сыром «Филадельфия».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (34,'Другой вариант: майонез со сметаной.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (34,'Торт поставить в холодильник на несколько часов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (35,'Готовую печень перемолоть, добавить немного молока, соль, яйцо, муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (35,'Выпечь коржи на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (35,'Собрать торт, коржи промазать майонезом или творожным сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (36,'Копченое мясо (можно заменить при желании на колбасу) вместе с твердым сыром порезать на кубики. Вскрыть банку фасоли, дать стечь соку, высыпать к мясу, добавить измельченную зелень, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (36,'В глубокой миске взбить венчиком майонез с яйцами, всыпать смесь муки с содой, перемешать, объединить с предыдущей смесью, размешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (36,'Переложить все в форму, поставить кекс из копченого мяса с фасолью в духовой шкаф примерно на 35-40 минут с температурой не выше 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (37,'Репчатый лук нарезать полукольцами, филе птицы – полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (37,'Обжарить ингредиенты на заранее разогретом масле до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (37,'Отдельно приготовить подливу из сметаны, муки, свежего или сушеного укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (37,'Мясо выложить в сотейник, залить соусом, добавить бульон и лавровый лист.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (37,'Мелко порубить чеснок, добавить к остальным компонентам, соль – по вкусу, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (37,'Тушить все вместе на огне средней мощности в течение получаса, продукты перемешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (38,'Филе птицы нарезать кусочками небольшого размера, выложить на прогретую с растительным маслом сковороду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (38,'Время тушения – десять минут, огонь – средний, ингредиенты несколько раз перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (38,'Репчатый лук нарезать полукольцами, добавить в основную массу, тушить пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (38,'Нарезать чеснок, также добавить к мясу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (38,'Влить немного соевого соуса, сметану, молотый перец и соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (38,'При необходимости можно добавить немного кипяченой воды.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (38,'Все вместе тушить десять минут, азу должно загустеть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (39,'Духовой шкаф прогреть до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (39,'Охладить сырые куриные яйца, отделить желтки от белков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (39,'Желтки взбить с сахарным песком при помощи миксера в густую массу, белки – в плотную пену с сахаром и щепоткой соли.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (39,'Обе массы осторожно соединить, белки не должны потерять объем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (39,'Муку всыпать порциями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (39,'Бумагу для выпекания смазать маслом, выложить готовое тесто в виде двух кругов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (39,'Удобнее это делать с помощью кондитерского мешка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (39,'Диаметр окружностей – около семи сантиметров.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (39,'Время выпекания – двадцать минут, температура – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (39,'Изделия вынуть и остудить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (39,'Приготовить крем из сахарной пудры и сливок, взбивать до плотной консистенции.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (39,'Растопить в миске поломанный кусочками шоколад и сливочное масло.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (39,'Одну из половинок пирожного обмакнуть в шоколадную массу и присыпать рублеными орехами.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (39,'Прослоить половинки кремом, дать постоять выпечке для пропитывания двадцать или тридцать минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (40,'Сырые куриные белки взбить, сахарный песок добавлять порциями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (40,'Поочередно вбить желтки, всыпать муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (40,'Масса должна получиться однородной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (40,'Противень застелить пергаментом, сформовать лепешки, печь в духовке двадцать минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (40,'Приготовить крем из сметаны с молоком, массу взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (40,'Половинки пирожных промазать сметаной, соединить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (41,'Сырые белки и желтки взбить отдельно, в обе массы добавить сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (41,'В белки всыпать немного лимонной кислоты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (41,'Часть белковой массы перемешать с желтковой, муку всыпать небольшими порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Оставить в тепле на три часа.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (41,'В конце приготовления добавить остатки взбитой белковой смеси.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (41,'Сформовать небольшие круглые лепешки, выпечь в течение пятнадцати или двадцати минут на противне, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (41,'Отдельно приготовить крем из сгущенного молока и мягкого сливочного масла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (41,'Приготовить шоколадную глазурь с маслом на водяной бане.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (41,'Окунуть часть лепешек в шоколад и дать застыть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (41,'Лепешки соединить попарно при помощи молочного крема.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (42,'Перемешать какао с подсоленной смесью муки и разрыхлителя, добавить сахар с маслом, все перетереть руками. Влить в полученную маслянистую крошку разболтанное яйцо, замесить тесто, скатать его в компактный шарик, поставить на полчаса в холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (42,'Переложить охлажденное тесто в подходящую форму, сформовать по краю бортики, прикрыть бумагой, засыпать фасолью или горохом, поставить основу на четверть часа в духовку с температурой чуть ниже 185 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (42,'Сварить сироп, сделать минимальный нагрев, засыпать поломанный на кусочки шоколад, добавить масло, размешать. Разболтать, как для омлета три яйца, осторожно влить к сиропу, нагреть, помешивая до однородности, засыпать муку, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (42,'Заполнить готовую основу для домашнего трюфельного торта шоколадной начинкой, поставить форму на 35-40 минут в духовку, выпекать десерт при 180 градусах. Готовый торт перед подачей остудить, присыпать порошком какао.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (43,'Белки отделить от желтков, взбить с сахаром, масса должна получиться плотной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (43,'Желтки добавить по одному, продолжать взбивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (43,'Всыпать муку, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (43,'Выложить тесто на застеленный пергаментом противень в виде круглых лепешек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (43,'Время выпекания – от пятнадцати до двадцати минут, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (43,'Половину лепешек смазать джемом, соединить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (43,'Приготовить глазурь на водяной бане из шоколада и сливочного масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (44,'Желатин залить 40 мл воды. Оставить набухать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (44,'В сотейник добавить сахар и 40 мл воды. Поставить его на средний огонь. Все перемешать. Кипятить 12-15 минут до состояния сиропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (44,'В глубокую емкость переложить желатин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (44,'Начать взбивать миксером на низкой скорости и постепенно вводить сироп. Важно: сироп нужно добавлять сразу, как только сняли его с огня, не давая ему застыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (44,'Когда весь сироп добавлен, плавно увеличить скорость миксера до максимальной. Взбивать, пока масса не станет пышной и плотной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (44,'В прямоугольную емкость постелить пищевую пленку, смазать ее растительным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (44,'Взбитую массу перенести в подготовленную тару. Убрать в холодильник до застывания. Примерно на 2 часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (44,'Посыпать плоскую поверхность сахарной пудрой, достать готовый маршмеллоу и обвалять в пудре.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (44,'Разрезать на кусочки, обвалять каждый кусочек в сахарной пудре. Маршмеллоу готов! Всем приятного аппетита! Больше кушайте, никого не слушайте!',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (45,'Развести желатин в горячей воде, дать постоять,  приготовить по инструкции на упаковке желе, дать остыть, поломать печенье. Почистить и нарезать сладкий апельсин, выложить его кусочками на дно кастрюли, залить подготовленным желе, дать застыть в холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (45,'В глубокую миску положить сметану, всыпать обычный сахар и ванильный, тщательно взбить, добавить желатиновый раствор и продолжить взбивать, положить кусочки печенья, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (45,'Залить полученной массой застывшее желе в кастрюле, поставить торт «Апельсинка» с крекером в холодильник для полного застывания. Достать кастрюлю, подержать дно несколько секунд в горячей воде, накрыть плоским блюдом и осторожно перевернуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (46,'Для начала нам надо намазать масло на булку, чтобы наш бутерброд не был рассыпчатым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (46,'После нарежьте колбасу небольшими кубиками. Положите эти кубики на нашу булку с маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (46,'После натрите сыр на мелкой терке. И посыпьте сыр на наш будущий бутерброд.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (149,'Время выстойки – полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (46,'Осталось только отправить бутерброд в микроволновку на 40 секунд. Наш горячий бутерброд готов. Приятного аппетита.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (47,'Нашинковать лук кубиками, обжарить на масле, добавить кусочки грибов, обжарить все вместе. Порезать ветчину и яйца мелкими кубиками, сыр измельчить на терке, огурцы нарезать тонкими ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (47,'Огурцы использовать для оформления, все остальное перемешать, подсолить, сдобрить майонезом, аккуратно перемешать и выложить салат горкой на тарелку. Вдавить в макушку салата «Изумрудный» ломтик огурца, продолжить по часовой стрелке вниз со сдвигом до основания салата, чтобы получился цветок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (48,'Куриный фарш, рикотту, соль (1 ч.л.), перец (1/2 ч.л.), мускатный орех (1/4 ч. л.), желток одного яйца, сыр натертый на мелкой терке смешать в глубокой тарелке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (48,'На бумагу для выпечки выложить приготовленную смесь, разровнять сформировав небольшого размера "котлету". Со всех сторон покрыть котлету кусочками ветчины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (48,'Оливковое масло разогреть на сковороде и положить в нее наш рулет вместе с бумагой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (48,'Обжариваем рулет по 15 минут с каждой стороны на среднем огне под закрытой крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (48,'Противень застелить фольгой формируя бортики, выложить на него рулет удалив бумагу и залить вином. Запекаем в духовке 40 минут при температуре 180 градусов',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (49,'Куриную грудку обжариваем на среднем огне по 7 минут с каждой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (49,'В глубокую тарелку сложить консервированную кукурузу, морковку по-корейски, мелко нарезанный зеленый лук, нарезанные соломкой маринованные огурцы, йогурт - перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (49,'На тарелку выложить листья салата, сверху выложить салат заправленный йогуртом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (49,'Поверх выложить кусочки курицы нарезанный полосками, вареное яйцо разрезанное на дольки и листики петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (50,'В сковороду налить масло и разогреть. Свежий имбирь очистить от кожицы и натереть на терке. Чеснок пропустить через пресс. Обжариваем 2 минуты на среднем огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (50,'В тарелке смешать воду, соевый соус, сахар, вино, соус чили – перемешать. Вылить в сковородку. Греем 5 минут на слабом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (50,'Говядину нарезать на кусочки и добавить в сковороду и тушим на медленном огне, пока не выкипит весь соус. Посыпаем кунжутом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (51,'В кастрюлю налить 1 литр воды и довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (51,'Говядину нарезать прямоугольными кусочками. Обжарить на растительном масле на среднем огне 7 минут с двух сторон под накрытой крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (51,'Лук нарезать кубиками, добавить к говядине и готовить 5 минут под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (51,'К говядине добавить паприку, сахар, картофель нарезанный кубиками, морковь соломкой – перемешать. Готовим 7 минут на среднем огне накрыв крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (51,'Болгарский перец очистить от семян и нарезать очень крупными кубиками. Помидоры нарезать крупной соломкой и добавить это все к содержимому сковороды – перемешать. Накрываем крышкой и готовим 15 минут на среднем огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (51,'Содержимое сковороды переложить в кастрюлю и залить кипятком. Посолить (1 ч.л.), поперчить жгучим перцем (1/5 ч.л.) – перемешать. Варим на медленном огне 30 минут накрыв крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (51,'Свежий укроп мелко нарезать и добавить в кастрюлю.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (52,'Масло комнатной температуры соединить с яйцом и сахаром, перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (52,'Натереть цедру апельсина, добавить молотую корицу, соль, муку – перемешать, затем поставить в морозилку на 45 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (52,'Поверхность стола присыпать мукой, раскатать тесто и вырезать звезды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (52,'Противень застелить бумагой и выложить на нее звезды. Духовку прогреть до 180 градусов, выпекаем печенье до золотистого цвета (около 10 минут).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (52,'Печенье сразу посыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (53,'Замесить тесто смешав: муку, сливочное масло комнатной температуры, сметану 20%, соль (1/2 ч.л.). Скатать тесто в шар, завернуть в пленку и убрать в холодильник на 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (53,'Колбасу нарезать кубиками, оливки разрезать пополам сложить в глубокую тарелку. Вбить яйца, мелко нарезанный укроп, сметану 10% - перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (53,'Сыр моцарелла натереть на терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (53,'Тесто достаем из холодильника. Обильно присыпаем мукой и раскатывает, укладываем в форму для выпечки присыпанную мукой формируя борты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (53,'Выкладываем начинку на тесто, затем раскладываем помидорки черри, посыпаем тертой моцареллой. Ставим в духовку на 40 минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (54,'Смешиваем молоко с кефиром в кастрюле с тонким дном. Если использовать кастрюлю с толстым дном, то творог может пригореть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (54,'Далее все перемешиваем и ставим на маленький огонь. После этого творог больше не мешаем и не закрываем крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (54,'Масса начинает нагреваться и расслаиваться. На поверхности образуется шапка. Эту шапку ни в коем случае не трогаем и даем нашей массе кипеть дальше.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (54,'Спустя час проверяем наш творог. Консистенция на поверхности должна быть плотной, а под ней формируется сыворотка. Можно подержать творог еще мин 10-15. Затем мы полностью выключаем огонь. Масса должна остынуть до комнатной температуры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (54,'Когда она остыла мы берем сито или марлю (что у вас есть под рукой) и аккуратно перекладываем верхнюю массу в это сито. Затем остатки можно процедить несколько раз, что бы максимально отжать творог.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (54,'Потом мы убираем творог в холодильник. Очень удобно слить творог на ночь и тогда к утру он уже будет готов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (54,'Когда он полностью отстоялся, мы можем переложить его в герметичную упаковку для хранения.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'На растительном масле на сильном огне быстро обжарить куриный фарш (около 1 мин) до изменения цвета. Посолить и поперчить по своему вкусу, перемешать и снять с огня.','https://vkuso.ru/data/cache/data/f6/43e445e80f66df6_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'На другой сковороде побольше также на растительном масле на сильном огне припустить (около 2-3 мин) нашинкованную капусту, натертую морковь и нарезанный репчатый лук. Посолить по своему вкусу, перемешать и оставить под крышкой на слабом огне на 10 мин, периодически помешивая.','https://vkuso.ru/data/cache/data/f1/385c228f70d76f1_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'Через 10 мин добавить в капусту куриный фарш, все перемешать и снять с огня.','https://vkuso.ru/data/cache/data/ca/2fa92bb830e9fca_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'Слоеное бездрожжевое тесто 350 гр разделить на две части. Присыпать стол и каждую часть теста мукой и раскатать каждую часть теста в тонкий пласт размером около 30х50 см.','https://vkuso.ru/data/cache/data/1e/0025b4a363e061e_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'Выложить на каждый пласт по половине подготовленной ничинки, равномерно распределить ее по тесту.','https://vkuso.ru/data/cache/data/93/bf17e8876f0a193_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'Равномерно посыпать начинку сверху натертым сыром.','https://vkuso.ru/data/cache/data/57/cbcd3de9594e057_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'Свернуть каждый пласт рулетом.','https://vkuso.ru/data/cache/data/9e/486dd78ca11c89e_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'Если тесто порвется в некоторых местах, т.к. оно очень тонкое и нежное, это не страшно.','https://vkuso.ru/data/cache/data/bd/f81060a512212bd_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'Смазать форму для запекания диаметром 23-24 см сливочным маслом и уложить в нее рулеты спиралью.','https://vkuso.ru/data/cache/data/c4/cbbf4f0238161c4_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'Равномерно надрезать рулеты ножницами, чтобы поверхность теста стала текстурной и была видна начинка.','https://vkuso.ru/data/cache/data/da/7a89e577a3239da_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'Смазать рулеты взбитым яйцом.','https://vkuso.ru/data/cache/data/a7/f5408c8da85e8a7_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'Посыпать сверху кунжутом (по желанию).','https://vkuso.ru/data/cache/data/04/3fe76427c6fa804_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'Выпекать в заранее разогретой духовке около 1 часа при 180°С до выраженной румяности.','https://vkuso.ru/data/cache/data/22/cd7d94765fde722_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'Готовый пирог извлечь из формы после остывания.','https://vkuso.ru/data/cache/data/a1/dfb29e7484d30a1_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (55,'Подавать к столу в качестве закуски или как самостоятельное полноценное блюдо на завтрак, обед или ужин.','https://vkuso.ru/data/cache/data/d9/6175291a637e2d9_434x295_notrise.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (56,'Объединить кубики охлажденного масла с мукой, цедрой апельсина, яйцом, солью, смешать при помощи блендера, всыпать сахарную пудру, все тщательно перемешать до однородной массы.  Шар теста обернуть пленкой и убрать на треть часа в морозильную камеру холодильника.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (61,'Края лепешки собрать сверху в центре и слепить вместе.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (61,'Лепешку перевернуть и аккуратно приплюснуть руками, увеличивая диаметр лепешки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (264,'Готовую мойву украсить зеленью.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (56,'Разложить тесто по смазанным маслом небольшим формочкам, убрать их на 10 минут в морозильную камеру холодильника, включить для прогрева до 180 градусов духовку.  Достать формочки, поставить в духовку, тарталетки с взбитыми сливками и ягодами будут готовы примерно через четверть часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (56,'Дать формочкам остыть, облить шоколадом, дать ему застыть, оформить десертные тарталетки  взбитыми сливками и ягодами, посыпать верх сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (57,'Разбить яйцо, добавить кефир или скисшее молоко, посолить и немного взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (57,'Добавить соду и помешивая постепенно добавлять муку, нарезать зелень в моем случае лук, петрушка и укроп, добавить в тесто и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (57,'Натереть сыр на терке, добавить в тесто и тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (57,'Налить масло в сковороду, распределить тесто по сковороде и обжарить по 2 минуты с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (57,'Готовые лепешки смазать сливочным маслом. Приятного аппетита!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (58,'Нарезаем соломкой помидора и сладкий болгарский перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (58,'Крабовые палочки нарезаем не толстыми пяточками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (58,'Сыр натираем на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (58,'Отправляем все нарезанные ингредиенты в миску и добавляем пропущенный через чеснокодавку чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (58,'Заправляем салат майонезом и солим по своему вкусу. Перемешиваем и посыпаем нарезанным зеленым луком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (59,'Для начала приготовим соус Болоньезе. Для этого нам понадобиться разогреть масло в кастрюле, туда добавим лук,морковь, сельдерей, слегка обжарим, добавим бекон и фарш, также слегка обжарим.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (59,'Добавим вино, выпарим, после добавим бульон, соль, перец, затем добавим томаты в собственном соку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (59,'Теперь оставим на час на среднем огне, периодически помешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (59,'Добавим молоко к Болоньезе и еще 5-10 минут готовить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (59,'Теперь все раскладываем в форму. На низ добавим болоньезе и накроем листами (варить листы необязательно).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (59,'Сверху выкладываем опять болоньезе, посыпаем моцарелла и пармезаном, поливаем соусом бешамель. И так делаем 2-3 слоя. Под конец можно залить соус бешамель и посыпать пармезаном.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (59,'И ставим в разогретую духовку до 180 градусов на 35-40 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (59,'Перейдем к соусу бешамель. Для этого нужно растопить сливочное масло, добавим муку и в течение 2-х минут перемешивать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (59,'После залить молоко и миксером или венчиком мешать до загустения.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (59,'После добавить мускатный орех и соль,перемешаем и оставим в сторонку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (59,'Добавим молоко к Болоньезе и еще 5-10 минут готовить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (59,'Теперь все раскладываем в форму. На низ добавим болоньезе и накроем листами (варить листы необязательно).',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (59,'Сверху выкладываем опять болоньезе, посыпаем моцарелла и пармезаном, поливаем соусом бешамель. И так делаем 2-3 слоя.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (59,'Под конец можно залить соус бешамель и посыпать пармезаном. И ставим в разогретую духовку до 180 градусов на 35-40 минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (60,'Мелко нарезать лук и грибы, обжарить лук и грибы на сливочном масле 10 минут, солим и перчим по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (60,'Нарезать отварную курицу, яйца, огурцы, и натереть сыр на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (60,'Смазать дно салатника майонезом, первым слоем выложить курицу, посолить и поперчить по вкусу, далее выкладываем обжаренные грибы с луком, смазываем майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (60,'Затем яйца, перец по вкусу, огурцы, майонез и сыр. Приятного аппетита!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (61,'В глубокую тару добавить кефир комнатной температуры, соду, сахар, соль, 1 яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (61,'Все перемешать. Добавить муку. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (61,'Добавить растительное масло. Начать месить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (61,'Присыпать стол мукой, выложить тесто. Замесить мягкое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (61,'Сформировать из него колбаску. Разрезать ее на 4 равные части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (61,'Из каждой сформировать шарик. Накрыть, дать тесту отдохнуть 10 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (61,'Натереть сыр на крупной терке. К нему добавить 1 яйцо, соль и перец. Перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (61,'Из каждого куска теста сформировать небольшую лепешку, положить на нее сырную начинку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (61,'Обжарить на сухой сковороде с закрытой крышкой на небольшом огне с каждой стороны несколько раз.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (61,'Смазать растопленным сливочным маслом. Хачапури готовы! Всем приятного аппетита! Больше кушайте, никого не слушайте!',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Противень застелить пергаментом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Куриные сырые белки взбить с ванильным сахаром в пену, скорость по мере приготовления увеличивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Желтки взбить отдельно, также с сахаром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Обе смеси соединить, перемешивать осторожными движениями, чтобы масса не опала.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Ввести в несколько приемов крахмал и просеянную муку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Перемешать до однородного состояния.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Тесто переложить в кондитерский мешок, кончик срезать ножницами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Выдавить тесто на пергамент в виде кругов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Печь десять или пятнадцать минут, заготовки должны зарумяниться, температура приготовления – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Лепешки остудить на решетке.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Приготовить крем из охлажденных жирных сливок с сахарной пудрой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Крем положить в холод, а затем поместить в кондитерский мешок с насадкой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Половину лепешек намазать абрикосовым джемом. Сверху – крем.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Растопить шоколад в микроволновой печи или на водяной бане.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (62,'Оставшиеся лепешки окунуть в глазурь одной стороной, дать застыть. Соединить заготовки по две.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Яичные белки отделить от желтков и взбить в пену с сахаром. Масса должна получиться плотной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Желтки растереть с сахаром до изменения цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Продукты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Всыпать просеянную пшеничную муку высшего сорта, молотую корицу и растертый мускатный орех.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Массу вымесить движениями снизу-вверх.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Готовым тестом наполнить кондитерский мешок, отсадить круглые заготовки на застеленный пергаментом противень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Присыпать тесто сахарной пудрой через ситечко, печь в течение десяти минут, температура – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Приготовить сироп из воды с сахарным песком, довести до кипения, влить немного рома или коньяка.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Жидкость остудить, пропитать выпечку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Для приготовления крема растопить горький шоколад, взбить мягкое сливочное масло.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Продукты перемешать, добавить сгущенное молоко.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Все вместе взбить и охладить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Заготовки промазать кремом, накрыть вторыми половинами.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Приготовить ганаш из растопленного горького шоколада, сливок.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (63,'Смесью намазать пирожные и присыпать через ситечко какао-порошком.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Приготовить ганаш для прослойки: мелко порубить белый шоколад, залить кипящими сливками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Смесь на минуту оставить для прогревания и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Остудить в холодильнике, время – два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Застелить противень пергаментом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Яйца взбить со щепоткой соли при помощи миксера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Сахарный песок всыпать порциями, взбивать в пену в течение десяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'После того, как масса станет пышной – всыпать просеянную муку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Вариант: часть муки заменить на какао-порошок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Тесто перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Отсадить лепешки диаметром в пять сантиметров на пергамент с помощью кондитерского мешка.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Время выпекания заготовок в духовом шкафу: от пяти до десяти минут, температура приготовления – 190 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Заготовки остудить, осторожно снять с противня.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Остывший ганаш из белого шоколада взбить, прослоить пирожные с помощью кондитерского мешка.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Сложить половинки.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Для украшения приготовить темный ганаш.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Порубить кусочками темный шоколад, залить кипящими сливками, прогревать две минуты, помешивать.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (64,'Покрыть глазурью пирожные, поставить в холод на два часа.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (149,'Выставить режим «Выпечка» на пятьдесят минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (65,'Положить все ингредиенты для начинки в небольшой сотейник, подогреть, помешивая на среднем огне пока сахар не растворится, а масса не примет золотистый цвет и не загустеет, дать начинке остыть и убрать на 2 часа в холодильник перед использованием.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (65,'Положить в чашку миксера масло, всыпать сахар, установить на миксере среднюю скорость, взбить, всыпать ванилин, добавить яйцо, взбивать все вместе 2-3 минуты. Смешать взбитую смесь с просеянной и подсоленной мукой (добавлять порциями), скорость смешивания постепенно увеличить до средней.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (65,'Полученный ком теста обернуть в пленку и убрать в холодильник на час, достать, раскатать в пласт круглой формы толщиной в 0,5 см. Вырезать крышкой от бутылки кружочки, сделать на пуговицах по 4 дырочки штопором, переложить их на противень, убрать в холодильник на четверть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (65,'Выпекать сахарные пуговки с карамельной соленой начинкой при температуре чуть выше 180 градусов пока они не станут по краям золотистого цвета, дать остыть прямо на противне. Остывшие пуговки промазать начинкой, соединить попарно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (66,'Белки и желтки разделить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (66,'Желтки взбить с сахарной пудрой при помощи миксера до побеления.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (66,'Белки, также с сахаром, взбить в густую пену.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (66,'Белковую и желтковую массу перемешать, всыпать просеянную муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (66,'Отсадить ровные лепешки небольшого диаметра на пергамент.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (66,'Разогреть духовой шкаф, печь заготовки в течение двадцати минут, температура – 180 градусов. Приготовить на водяной бане шоколад со сливками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (66,'Окунуть половину печений с одной стороны в глазурь',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (66,'Взбить сливки с сахарной пудрой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (66,'Прослоить пирожные абрикосовым джемом, далее – крем и вторая половина выпечки с шоколадом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (67,'Наливаем в казан 150 грамм растительного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (67,'Добавляем лук и обжариваем 2-3 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (67,'Добавляем чеснок и обжариваем 1 минуту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (67,'Добавляем морковь, сладкий перец, свеклу и обжариваем 2 - 3 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (67,'Добавляем томатную пасту, черный молотый перец, красный острый, соль и потушим 2 минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (67,'Заливаем свиные кости холодной водой и варим бульон 40 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (67,'Добавляем картофель и варим 10 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (67,'Добавляем капусту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (67,'Добавляем зажарку и варим до готовности картофеля.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (67,'Добавляем зелень.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (68,'Белки взбить с сахарным песком.','https:https://st.vkuso.ru/data/cache/thumb/d4/7a595d35516e5d4_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (68,'Отдельно – растереть желтки, тоже с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (68,'Обе массы соединить, перемешивать лопаткой, аккуратно.','https:https://st.vkuso.ru/data/cache/thumb/e7/2c496bb7cbae3e7_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (68,'Вмешать муку.','https:https://st.vkuso.ru/data/cache/thumb/0c/ed8656ad6136c0c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (68,'Отсадить небольшие кружки на лист пергамента.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (68,'Печь до румяной корочки, время – пятнадцать минут, температура приготовления – 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/c5/7671986d6b7f5c5_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (68,'Приготовить начинку из сливок и сахарной пудры.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (68,'Прослоить кружки, сложить по два.','https:https://st.vkuso.ru/data/cache/thumb/d2/5527f98633b0ad2_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (68,'Верх пирожных смазать горьким растопленным шоколадом, остудить в холодильнике.','https:https://st.vkuso.ru/data/cache/thumb/12/fb4f15a6fb12412_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'В небольшую кастрюлю всыпать сахарный песок, влить воду, коньяк, всыпать цедру лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Ингредиенты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Емкость поставить на огонь, довести до кипения и варить две или три минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Сироп остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'В другую кастрюлю влить молоко, добавить сахар, цедру лимона, ванилин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'В миску влить молоко, вбить желтки, добавить сахар, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Всыпать крахмал, еще раз все перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Поставить кастрюлю с молоком на огонь, довести до кипения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Аккуратно влить горячее молоко в желтковую смесь, массу все время помешивать венчиком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Продукт процедить через сито, снова перелить в кастрюлю.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Варить на тихом огне до появления первых пузырьков.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Снять с огня, положить сливочное масло, перемешать до растворения масла.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Крем должен стать однородным.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Накрыть продукт пленкой в контакт, поставить в холод.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Белки вбить в чашу миксера, посолить, взбивать массу на большой скорости.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Сахар добавить в несколько приемов.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Масса должна быть пышной, увеличиться в объеме в два-три раза.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Добавить желтки, экстракт ванили, перемешать на небольшой скорости.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Отдельно перемешать муку с разрыхлителем, просеять в белковую массу, осторожно перемешать.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Противень застелить бумагой, отсадить заготовки с помощью кондитерского мешка.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Время выпекания – от двенадцати до пятнадцати минут, температура – 180 градусов.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Заготовки остудить.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Приготовить ганаш из горячих сливок с шоколадом и сливочным маслом.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Перемешать.',NULL,24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Заварной крем положить в кондитерский мешок.',NULL,25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Бисквитные лепешки обмакнуть в сироп ровной стороной на две или три секунды, выложить на пергамент.',NULL,26);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'На половину бисквитов нанести заварной крем.',NULL,27);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Вторую часть кружков обмакнуть одной стороной в шоколад.',NULL,28);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (69,'Собрать «Буше» из получившихся заготовок.',NULL,29);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (70,'Подготовить тушку рыбы, разрезать вдоль хребта, вынуть все кости, порезать на небольшие куски, приготовить из смеси соли и сахара засолочную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (70,'На дно лотка выложить слой рыбы, присыпать засолочной смесью, положить горошки душистого перца, повторить операцию со вторым слоем рыбы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (70,'Лоток закрыть и поставить в холодильник, вкуснейшая соленая красная рыба будет готова через сутки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (71,'Подогретую сыворотку посолить, всыпать муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (71,'Перемешивать до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (71,'Влить смесь взбитых с сахаром яиц.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (71,'Ингредиенты еще раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (71,'Всыпать пищевую соду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (71,'Далее влить растительное рафинированное масло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (71,'Массу перемешать и дать ей постоять от пятнадцати минут до часа или двух.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (71,'Выпекать на раскаленной сковороде.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (72,'Сыворотку немного прогреть, всыпать сахарный песок, соль и пищевую соду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (72,'Отдельно смешать яйца и растительное масло, смесь влить в основную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (72,'Тесто должно стать однородным, продукты перемешивать венчиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (72,'Всыпать муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (72,'Хорошо перемешать, в тесте не должно быть комочков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (72,'В небольшой емкости перемешать воду с молоком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (72,'Если молоко нежирное, то воду вливать необязательно.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (72,'Довести до кипения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (72,'Влить кипящее молоко в тесто тонкой струйкой, помешивать венчиком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (72,'Жидкую массу оставить на полчаса.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (72,'Затем выпечь тонкие блины на раскаленной сковороде.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (73,'Сырое куриное яйцо взболтать с сахарным песком и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (73,'Всыпать муку высшего сорта, массу перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (73,'Тесто должно получиться густым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (73,'Полученную смесь развести теплой сывороткой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (73,'Всыпать соду, массу перемешать, влить кипяток.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (73,'Тесто быстро перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (73,'Оставить массу на пять минут для заваривания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (73,'Влить растительное масло, перемешать, выпечь блины.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (74,'Молочную сыворотку подогреть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (74,'В отдельной емкости взбить яйца с сахарным песком и солью до появления мелких пузырьков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (74,'Перелить смесь в сыворотку, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (74,'Всыпать муку, приготовить тесто. Можно использовать погружной миксер.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (74,'Дать смеси постоять десять или пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (74,'Влить растительное масло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (74,'Выпечь тонкие блины на горячей сковороде, наливать тесто в центр, а затем распределять по всей площади.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (340,'Заварить крепкий черный чай.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (75,'В теплой молочной сыворотке растворить соль и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (75,'Всыпать муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (75,'Массу хорошо перемешать, в ней не должно быть комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (75,'Продукт должен постоять, чтобы клейковина набухла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (75,'Всыпать соду или разрыхлитель, массу быстро перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (75,'Влить растительное масло, продукты перемешать еще раз, оставить тесто на час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (75,'Сковороду смазать маслом, выпечь блины.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (76,'Смешать мед, погашенную соду и растопленное масло. Объединить все сыпучие ингредиенты, добавить масло, перемешать в однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (76,'Сделать небольшие шарики, сжать между ладонями, переложить на подготовленный противень с небольшим расстоянием.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (76,'Задвинуть противень примерно на 15-20 минут в духовку, температуру поддерживать в районе 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (76,'Готовое овсяное печенье «Golden Crunch» пока горячее, очень мягкое, поэтому перекладывать на решетку для остывания нужно очень аккуратно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (77,'Манную крупу залить прогретой сывороткой, оставить на полчаса или час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (77,'Взболтать сырые куриные яйца с сахарным песком и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (77,'Влить смесь в манку, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (77,'Всыпать муку, влить растительное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (77,'Пищевую соду погасить лимонным соком или уксусом, влить в тесто, размешать, масса должна постоять пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (77,'Сковороду смазать маслом, раскалить. Влить тесто, обжаривать с двух сторон, до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (78,'Сыворотку прогреть, смешать с мукой до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (78,'Ввести сахарный песок, масло, соль и соду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (78,'Перемешать, оставить на час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (78,'Выпечь блины с двух сторон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (78,'Готовить под крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (79,'Ягоды протереть через мелкое сито.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (79,'Жмых прогреть до кипения вместе с водой, дать постоять до остывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (79,'Процедить через сито или марлю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (79,'Смешать сок и отвар, сахарный песок – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (80,'Клюкву превратить в кашицу при помощи погружного блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (80,'Выложить массу в чашу мультиварки, влить воду, добавить сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (80,'Содержимое емкости перемешать, выставить режим «Пароварка» или «варка на пару» на пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (80,'Оставить морс для настаивания под крышкой на час. Жидкость процедить и остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (81,'Растереть в кастрюле ягоды калины и клюквы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (81,'Всыпать сахарный песок, мед.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (81,'Кашицу залить кипятком, дать постоять под крышкой в течение десяти или двадцати минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (81,'Напиток процедить, жмых протереть через сито.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (82,'Сварить не очищенный картофель до готовности, обдать холодной водой, снять шкурку, чайной ложечкой осторожно, чтобы не повредить бока, вынуть у каждого клубня серединку и порезать ее.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (82,'Для начинки перемешать кубики огурца, лука, картофель, филе форели и измельченную зелень, приправить солью, перцем и майонезом, все смешать, заполнить подготовленные клубни.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (83,'Вымыть и нарезать листья сухой мяты, добавить яблоко, нарезанное дольками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (83,'Влить воду, прогреть напиток до кипения, добавить сахар, варить несколько минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (83,'Приготовить при помощи блендера пюре из брусники и клюквы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (83,'Массу залить отваром, настоять под крышкой до остывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (83,'Процедить через сито, сахар – по вкусу и желанию.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (84,'Картофель нарезаем тонкими пластинами.','https://vkuso.ru/data/cache/data/05/557783d9bcebc05_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (84,'Лук – полукольцами.','https://vkuso.ru/data/cache/data/16/9d3dcc5f0c64416_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (84,'Обжариваем картофель.','https://vkuso.ru/data/cache/data/36/2a3ccc85216c236_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (84,'Добавляем лук.','https://vkuso.ru/data/cache/data/45/24411b24bc53a45_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (84,'Взбиваем яйца.','https://vkuso.ru/data/cache/data/5d/0dfbee42609015d_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (84,'Соединяем обе части.','https://vkuso.ru/data/cache/data/d2/459ce71754675d2_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (84,'Выкладываем в глубокую сковородку.','https://vkuso.ru/data/cache/data/6d/a5076b3c3631a6d_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (153,'Выложить мясо с овощами на тарелку. Полить соусом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (84,'Жарим до корочки на медленном огне.','https://vkuso.ru/data/cache/data/68/e17f055ac423668_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (84,'Переворачиваем.','https://vkuso.ru/data/cache/data/70/c4dfc72c3eb2f70_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (84,'Сервируем зеленым луком.','https://vkuso.ru/data/cache/data/bb/df3f8faa93ad5bb_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (85,'Перемешать манную крупу с кефиром, дать постоять четверть часа, добавить все остальные ингредиенты для приготовления тыквенного манника, заполнить полученным тестом форму, поставить на 40 минут в духовку с температурой 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (86,'В блендер всыпать сахар, влить сметану, положить крахмал, желтки, ванилин, творог, все взбить до однородной массы. Отдельно взбить яичные белки, соединить с творожной массой, перемешать, можно всыпать промытый изюм или любые кусочки сухофруктов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (86,'Переложить в форму, на дно которой уложен смазанный маслом пергамент, выпекать воздушную запеканку из творога при температуре не выше 200 градусов около 35 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (87,'Ягоды клюквы и черники вымыть, обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (87,'Удалить плодоножки, всыпать в чашу блендера, добавить воду и сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (87,'Массу взбить на высокой скорости до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (87,'Долить воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (87,'Через пятнадцать минут напиток процедить, дополнительная порция сахарного песка – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (88,'Из ягод клюквы и свежих апельсинов отжать сок любым доступным способом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (88,'Жмых сохранить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (88,'Нарезать тонкими пластинками очищенный корень имбиря.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (88,'Выложить в емкость с жмыхом, влить воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (88,'Довести до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (88,'Варить пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (88,'Отвар остудить, смешать с клюквенным и апельсиновым соком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (88,'Мед – по вкусу и желанию.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (89,'Сушеный шиповник залить кипятком в термосе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (89,'Время настаивания – двенадцать часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (89,'Из клюквы отжать сок, жмых залить водой и проварить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (89,'Отвар остудить, процедить, соединить настоем шиповника, его также предварительно отцедить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (89,'Долить сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (89,'Всыпать сахар. Вместо него можно использовать мед.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (90,'В глубокую сковороду или кастрюлю влить немного растительного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (90,'Всыпать кукурузу, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (90,'Зерна должны лежать на поверхности сковороды ровным слоем, в один ряд.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (90,'Накрыть емкость крышкой, поставить на сильный огонь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (90,'Через три или четыре минуты зерна начнут взрываться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (90,'Подержать блюдо под крышкой минуту, снять с плиты, не открывать еще две минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (90,'Посыпать сахарной пудрой, солью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (91,'Промыть под проточной водой перловку, залить водой, дать постоять до утра, потом проварить 20 минут. Почистить и порезать на кубики картофель, высыпать к перловке, сварить до готовности. Обжарить до золотистости  измельченный лук на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (91,'Измельчить на терке морковь, высыпать к луку, жарить, не забывая помешивать, 5 минут, добавить томатную пасту, размешать, немного прогреть и переложить эту заправку к крупе и картофелю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (91,'Натереть соленые огурцы, положить в кастрюлю, проварить 10 минут. Готовому рассольнику с перловой крупой без мяса дать постоять немного под крышкой, разлить по тарелкам, положить по ложечке сметаны и присыпать измельченной зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (92,'В глубокую посуду из стекла или керамики влить растопленное сливочное или растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (92,'Всыпать зерна кукурузы, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (92,'Продукт должен лежать в один слой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (92,'Включить микроволновую печь на максимум, время приготовления – три минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (93,'Разогреть духовку до двухсот сорока градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (93,'Налить немного растительного масла в кастрюлю из металла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (93,'Всыпать кукурузу в один слой, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (93,'Кастрюлю накрыть крышкой, поставить в духовку на десять или двенадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (94,'Для классического форшмака необходимо отварить куриные яйца в течение семи или восьми минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (154,'Говядину подморозить, нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (94,'Пропустить через мясорубку яблоко сорта «Антоновка», ржаной хлеб, репчатый лук, филе сельди, яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (94,'Смесь перемешать и взбить с мягким сливочным маслом, выложить в форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (94,'Зеленый лук мелко нарезать, насыпать сверху.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (94,'Готовую закуску убрать в холод на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (95,'Отварить до готовности морковь и яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (95,'Пропустить через мясорубку вместе с сельдью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (95,'Мягкое сливочное масло перемешать с плавленым сыром и основной массой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (95,'Соль и перец – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (95,'Кушанье взбить до получения пышной однородной массы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (96,'Слегка подогреть молоко, перемешать блендером с сахаром, но лучше с сахарной пудрой, влить растительное масло, взбить на большой скорости, всыпать сухое молоко и порошок какао, еще раз, не переключая скорости, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (96,'Завершить приготовление, добавлением большого количества любых дробленых орехов, перемешать шоколадную пасту «Нутелла» с орехами окончательно, убрать в холодильник. После полного охлаждения ни запах, ни вкус подсолнечного масла чувствоваться не будет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (97,'Приготовить говяжий фарш, обжарить на сковороде с растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (97,'Взбить в блендере сметану и сельдь до получения однородной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (97,'Перемешать рыбу и мясо, посолить, поперчить',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (97,'Массу выложить в порционные тарелки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (97,'Нарезать любую зелень, украсить закуску.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (97,'Поставить в холод на двадцать пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (97,'Подать на стол.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (98,'Репчатый лук порубить и обжарить на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (98,'Яйца отварить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (98,'Взбить в блендере смесь из ржаного хлеба, сельди, яиц, малосольных грибов, лука, майонеза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (98,'Время приготовления – десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (98,'Массу поставить в холод на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (99,'Отварить свеклу до полной готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (99,'Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (99,'Ржаной хлеб и репчатый лук измельчить и обжарить на сковороде на масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (99,'Нашинковать соленые огурцы, сельдь и свеклу, продукты перемешать с хлебно-луковой обжаркой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (99,'Добавить специи по вкусу и желанию, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (100,'Пропустить через мясорубку филе сельди.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (100,'Творог перемешать со сметаной, взбить миксером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (100,'Всыпать соль, специи, нарезанную зелень петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (100,'Обе массы соединить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (100,'Поставить закуску на час в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (100,'Подать форшмак на кусочках ржаного хлеба.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (101,'Отварить до готовности картофельные клубни и яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (101,'Мелко нарезать репчатый лук, обжарить на сковороде с растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (101,'Нарезать зеленый укроп, добавить в обжарку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (101,'Измельчить при помощи блендера сельдь, картофель и отваренное яйцо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (101,'Добавить обжарку, перец, соль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (101,'Подать форшмак на большом блюде, украсить зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (102,'Растереть в однородную массу смесь из сахара, творога, кокосовой стружки и желтка, скатать из нее небольшие шарики,  убрать на полчаса в морозильную камеру холодильника. Растереть размягченный маргарин и сахар, разбить яйца, добавить белок, взбить все до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (102,'Добавить сметану, влить молоко, всыпать муку с разрыхлителем, тщательно перемешать, переложить в подготовленную форму половину теста, а к оставшейся части добавить пару ложек порошка какао, перемешать и вылить вторым слоем в форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (102,'Достать застывшие шарики, вдавить в поверхность шоколадного теста, поставить форму в духовку с температурой 180 градусов, основа пирога будет готова примерно через 45 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (102,'Из взбитых яиц с сахаром, мукой и ванилью с добавлением пары стаканов молока приготовить заварной крем, нагрев всю смесь, помешивая венчиком, до густого состояния. На остывшую основу пирога выложить слой из заварного крема и равномерно присыпать какао.  Пирог «Утренняя роса» с творогом и кокосом готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (103,'Гречку варим до готовности. В процессе варки солим по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (103,'Измельчаем лук и морковь, обжариваем их на растительном масле.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (103,'Измельчаем блендером  морковь, лук и печенку в однородную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (103,'В горячую гречку добавляем сливочное масло и даем остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (103,'Яйца взбиваем с солью и добавляем в гречку, перемешиваем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (103,'Форму для запекания смазываем маслом и выкладываем половину гречки, на нее печенку и затем оставшуюся гречку. Слои уплотняем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (103,'Сыр натираем на крупной терке, добавляем сметану, перемешиваем и выкладываем сверху на запеканку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (103,'Отправляем запеканку в разогретую духовку на 180 градусов до образования золотистой корочки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (104,'Промыть цветную капусту, отварить до готовности, в конце приготовления добавить взбитое куриное яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (104,'Мелко нашинковать очищенные грецкие орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (104,'Капусту и филе сельди измельчить в блендере в пюре',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (104,'Добавить орехи, посолить, поперчить и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (105,'Картофель очистить, вымыть, нарезать кубиками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (105,'Поставить вариться в кастрюле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (105,'При закипании воды добавить сухой бульон даси.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (105,'При готовности картофеля добавить водоросли вакаме.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (105,'Снять кастрюлю с плиты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (105,'Добавить светлую пасту мисо, продукт необходимо предварительно разбавить бульоном.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (106,'Свиное мясо нарезать небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (106,'Очистить и нарезать корень пастернака или гобо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (106,'Если используется второй продукт, то залить холодной водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (106,'Дайкон покрошить кубиками со стороной в полтора сантиметра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (106,'Удалить ножки у грибов шиитаке, шляпки разрезать на четыре части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (106,'Коннияку залить кипятком на минуту, выложить на сито, остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (106,'Разрезать продукт на четыре части, а затем поперек – на ломтики.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (106,'Налить в кастрюлю кунжутное масло, прогреть до появления дымка.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (106,'Свинину обжарить, добавить пастернак, дайкон, коннияку, грибы.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (106,'Влить бульон даси, суп довести до кипения, варить на тихом огне пятнадцать минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (106,'Мисо пасту перемешать с небольшим количеством супа, влить в основное блюдо.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (107,'В кастрюлю положить сухие водоросли вакаме, варить до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (107,'Снять с огня, добавить пасту мисо, перемешивать до растворения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (107,'Разлить суп в тарелки, положить кубики тофу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (108,'Приготовить тесто: смешать масло, соль, сметану до однородности. Добавить муку, просеянную вместе с разрыхлителем. Замесить тесто средней густоты. Для начинки: слить жидкость от консервов, рыбу немного размять вилкой. Добавить мелко порубленную зелень петрушки и укропа, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (108,'Смазать маслом форму, выложить тесто так, чтобы получились бортики высотой три сантиметра. Затем выложить начинку и залить яйцом, взбитым со щепоткой соли, сметаной и мукой. Смесь должна быть полужидкой. Печь пирог с начинкой из консервированной горбуши при 180 градусах в течение 40 – 45 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (109,'Заранее достанем масло с холодильника , чтобы оно подтаяло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (109,'Масло в посуде взбиваем до побеления. После, туда добавим сахар, муку, слегка перемешаем, добавим яйца и хорошо все смешаем до однородной массы.','https://vkuso.ru/data/cache/data/87/f5491231a383b87_434x295_notrise.jpeg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (109,'Затем отправим в духовку уже разогретую до 170°C на 50-55 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (109,'Тем временем подготовим пропитку для кекса . В посуду с носиком добавим сахар и лимонный сок, хорошо размешаем, до растворения сахара , если нужно процедить через сито.','https://vkuso.ru/data/cache/data/68/067bcf6aa6d1968_434x295_notrise.jpeg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (109,'Готовому кексу даем остыть немного, затем делаем дырочки в кексе. Заливаем пропитку и даем постоять, чтобы все хорошо пропиталась.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (110,'Подготовим заранее ингредиенты. Рис промыть, залить парой стаканов воды и оставить на 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (110,'Орехи измельчить ножом. На разогретую сковороду выложить масло и когда оно начнет шипеть всыпать орехи с изюмом. Обжаривать их в течении 2-3 минут постоянно помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (110,'В глубокую кастрюлю налить молоко и на умеренном огне довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (110,'Прежде чем молоко закипит, залить шафран 2 ложками горячего молока и дать настояться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (110,'Всыпать рис в кипящее молоко и через 10 минут добавить сахар. Затем варить еще в течении 30-40 минут помешивая.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (110,'За несколько минут до готовности добавить в кастрюлю смесь орехов и изюма, шафрана, кардамон и соль. Подавать пудинг теплым.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (111,'Приготовить начинку: нарезать филе рыбы полосками, натереть солью и перцем, любыми специями для рыбы. Нарезать пучок зеленого лука, отварить, очистить и порубить ножом куриные яйца, смешать с луком, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (111,'Размороженное слоеное тесто раскатать скалкой, потребуется две пластины. Смазать маслом форму с бортиками, выложить тесто, наколоть в нескольких местах вилкой. Сначала выложить смесь зеленого лука с яйцом, посыпать этот слой начинки натертым замороженным сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (111,'Выложить рыбу. Вторую половину теста также раскатать, наколоть вилкой или пройтись по ней специальным валиком, делающим дырочки. Накрыть начинку, защипать края «крышки» и «бортиков». Верх пирога смазать взбитым со сливками яйцом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (111,'Печь пирог из слоеного теста с красной рыбой и яйцом при температуре 180–200 градусов в течение 40–50 минут. Подрумяненный пирог остудить, вынуть из формы, нарезать на порции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (112,'Смешать муку и сливочное масло, так, чтобы получилась крошка, лучше делать это руками, масло должно быть охлажденным и натертым на крупной терке. Отдельно смешать сырое яйцо со сметаной, смесь влить в муку, замесить тесто, нужно делать это довольно быстро, пока масло не растаяло. Разделить тесто на шесть частей, скатать в виде колобков, завернуть в пищевую пленку и заморозить в холодильнике в течение часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (112,'Вынуть «колобки» из морозилки, натереть на терке, высыпать на противень (смазка не нужна). Печь при 200 градусах в течение получаса. Вынуть из духовки, перемешать, снова печь 10 – 15 минут при той же температуре. Снова достать, остудить, измельчить вилкой или руками в крошку. Залить смесью из вареной и простой сгущенки, или одной из двух видов. Сладкую массу перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (112,'Для придания печенью формы «муравейников», взять рюмку, обмакнуть её в воду и наполнить массой до краев, разровнять и выложить, перевернув рюмку. Сформованные «пирамидки» убрать в холодильник, лучше на 12 – 15 часов, чтобы забавное печенье «Муравьиные кучки» хорошо склеилось и пропиталось сгущенкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (113,'Муку просеять в миску, добавить соль, сахар и дрожжи, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (113,'В сухую смесь влить теплую воду, слегка перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (113,'Добавить масло, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (113,'Тесто выложить на рабочую поверхность и вымесить в течении 5-7 минут. Тесто должно быть прилипать к поверхности, чтобы его легко собрать используйте силиконовую лопатку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (113,'Когда тесто готово, смажьте его растительным маслом, положите в миску и накройте. Оставьте подниматься на 30 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (113,'Через 30 минут выложите тесто на рабочую поверхность, присыпанную мукой и с помощью скалки, не сильно надавливая раскатайте тесто в длину. Затем сверните тесто в рулет, поверните другой стороной и снова заверните. Присыпьте мукой и снова раскатайте, затем снова сверните в рулет, края защипните.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (113,'Готовый батон выложите на противень, присыпанный мукой, накройте и оставьте на 20 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (113,'Через 20 мин смажьте батон молоком или водой, сделайте надрезы и по желанию посыпьте сверху мукой или кунжутом. Выпекайте при 180°С 35 мин. Готовому батону дайте время остыть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (114,'Отделить от молодого капустного кочана 6 листьев.','https://vkuso.ru/data/cache/data/00/aec3d8dbc178400_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (114,'Срезать толстые прожилки у основания.','https://vkuso.ru/data/cache/data/be/ce15f70ef9816be_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (114,'Сложить листья в большую кастрюлю, залить водой, добавить соль и варить под крышкой в течение 1 минуты после закипания.','https://vkuso.ru/data/cache/data/26/769af2a0a535126_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (114,'Сразу выложить горячие листья в дуршлаг и быстро промыть их холодной водой.','https://vkuso.ru/data/cache/data/f3/648cc74593331f3_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (114,'Нарезать сыр толстыми кусочка по 0,5-0,7 см. Взбить 2-3 яйца в зависимости от размера.','https://vkuso.ru/data/cache/data/27/0798bd0fa9fc027_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (114,'Высыпать панировочные сухари в глубокую тарелку.','https://vkuso.ru/data/cache/data/ee/1d52a67e14883ee_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (114,'Завернуть в каждый капустный лист по кусочку сыра конвертиком.','https://vkuso.ru/data/cache/data/cb/2cc95585fe3cecb_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (114,'Сложить конвертики швом вниз.','https://vkuso.ru/data/cache/data/cf/79e1dc88c58cbcf_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (114,'Обильно обвалять сначала в яйце.','https://vkuso.ru/data/cache/data/c9/ad42a7dc90128c9_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (114,'Затем в панировочных сухарях.','https://vkuso.ru/data/cache/data/21/3cb6188b5ca1721_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (114,'Обжарить конвертики на растительном масле на среднем огне. Конвертики выкладывать на сковородку швом вниз, масла должно быть достаточно много.','https://vkuso.ru/data/cache/data/8a/71c5a6d09ba758a_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (114,'Жарить по 2 мин с каждой стороны до румяности.','https://vkuso.ru/data/cache/data/b0/a62dc9e81d398b0_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (114,'Сразу подавать капустные конвертики со сметаной, кетчупом или с любым соусом, пока они не остыли.','https://vkuso.ru/data/cache/data/9f/aee39f93ff0b89f_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (114,'Приготовить такие конвертики можно на завтрак, на обед, ужин и просто на перекус.','https://vkuso.ru/data/cache/data/a8/c2ec3bda65d11a8_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (115,'Очистить корень имбиря, нарезать вместе с луком-шалотом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (115,'Добавить давленый чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (115,'Растереть в порошок зерна кунжута.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (115,'Положить в кастрюлю подготовленные продукты, долить кунжутное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (115,'Выложить свиной фарш, жарить до изменения цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (115,'Влить соевый соус, положить мисо-пасту и молотый кунжут, сахарный песок, влить куриный бульон и немного саке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (115,'Соль и молотый перец – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (115,'Довести суп до кипения, варить на тихом огне в течение десяти минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (115,'Отварить лапшу «Рамен», выложить в глубокую тарелку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (115,'Залить супом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (116,'Рыбу нарезать небольшими кусочками. Можно взять судака, палтус, любую другую. Рыба должна быть достаточно жирной. Добавить по вкусу соль, перец, дать постоять 10 – 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (116,'Нарезать кружками картофель, также посолить и поперчить. Выложить в форму тонким слоем, сверху – рыба. Затем кружки спелых помидоров, снова картофель. Смазать майонезом. Сверху традиционную мусаку с рыбой посыпать тертым сыром. Печь 30–40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (117,'Филе форели нарезать небольшими кусочками, положить в кипящую воду на пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (117,'Грибы шиитаке нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (117,'Пасту мисо развести небольшим количеством воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (117,'При готовности форели добавить в суп пасту мисо и нарезанные ломтиками грибы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (117,'Все вместе варить пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (117,'Вместо соли в суп можно влить соевый соус.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (118,'Готовим сырники. В миску отправить рикотту, прованские травы, манку, соль и яйцо – перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (118,'Засыпать муку и снова перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (118,'Пармезан натереть на мелкой терке и добавить в тесто к сырникам – перемешать. Ставим в холодильник на 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (118,'Готовим соус к сырникам. Репчатый лук очистить и нарезать мелким кубиком, обжарить в сковороде на растительном масле на среднем огне в течении 5 минут, перемешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (118,'Помидоры нарезать мелким кубиком и добавить к луку, готовим еще 10 минут, перемешивая.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (118,'Возвращаемся к нашим сырникам. Достать из холодильника и подготовить муку и чистую воду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (118,'Смачиваем руки водой и берем немного теста, формируем сырники и обваливаем в муке со всех сторон. Готовим на медленном огне в сковороде с растительным маслом до золотистого цвета с двух сторон (около 7 минут на каждую сторону).',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (118,'Когда сырники будут готовы, подавайте их к столу с томатным соусом, который приготовили ранее.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (126,'Рисовую лапшу залить кипящей водой на две минуты, затем быстро промыть холодной водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (119,'Понадобится бисквитное тесто, для этого нужно смешать сахар, муку, какао-порошок и крахмал. Все сыпучие ингредиенты просеять, обогатить воздухом, добавить разрыхлитель и перемешать. Отдельно взбить сырые белки, в стойкую пену, добавить сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (119,'Еще раз взбить. Желтки растереть с сахаром добела отдельно. Смешать обе яичные массы, всыпать муку с добавками, осторожно перемешать сверху вниз, чтобы смесь не потеряла пышность, воздушность.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (119,'Небольшие формы для выпечки хорошо смазать растительным маслом, выложить тесто ложкой, по 1,5 столовые ложки массы на одну формочку. Выпечь до готовности, проверить готовность зубочисткой, если она останется сухой – выпечка готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (119,'Заранее приготовить начинку, для этого сварить манную кашу на молоке. Добавить ванилин. Остудить и взбить венчиком, чтобы не было комочков. Отдельно растереть добела сливочное масло с сахаром (масло должно быть подтаявшим), ввести в манку. Снова взбить и добавить кокосовую стружку. Остудить, поставить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (119,'Остывшие бисквиты соединить по два с помощью манной прослойки, хорошо прижать. Украсить выпечку можно, как угодно: взбитыми сливками с сахаром, сгущенкой, сварить глазурь. Полить бисквитные пирожные «Баунти», посыпать шоколадной крошкой или какао. Можно добавить ягоды из варенья или компота, фигурки цветного мармелада.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (120,'Подсолить молоко и вскипятить, следить, чтобы не «убежало». Отдельно смешать сметану с яйцами и осторожно влить в кипящее молоко. Варить смесь в течение 2 – 3 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (120,'Должны образоваться крупные хлопья, на этой стадии приготовления можно добавить рубленый укроп или кинзу. Варить 3–4 минуты, постоянно помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (120,'Выложить сырную массу в сито или марлю, отцедить. Поставить под груз и охладить домашний сыр в холодильнике в течение 12 часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (121,'Смешиваем соль, черный перец, красный острый перец, сухой базилик, чеснок, паприку, горчицу и растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (121,'Делаем надрезы на ребрах и натираем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (121,'Заворачиваем ребра в пергаментную бумагу и в фольгу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (121,'Запекаем на углях 40-50 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (121,'Смазываем ребра смесью из соевого соуса, меда и горчицы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (121,'Запекаем ещё по 7 минут с каждой стороны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (122,'Очистить лимон, корень имбиря и чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (122,'Продукты положить в блендер вместе с помидорами, авокадо, зеленью петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (122,'Взбить до получения однородной массы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (122,'Влить апельсиновый и кокосовый сок, положить красное мисо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (123,'Куриное филе разрезать, мясо отбить, натереть солью и перцем. Противень застелить фольгой, выложить курицу. На филе выложить кружки спелых помидоров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (123,'Отдельно натереть картофель на крупной терке. Взбить сырые яйца со сметаной, рубленым луком и чесноком. Добавить по вкусу соль и перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (123,'Массу добавить в картофель и перемешать. Выложить поверх помидоров. Запекать куриное филе под картофелем до золотистой аппетитной корочки, до готовности. Подать, разрезав на порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (124,'Порезать лосось на кусочки, посолить, оставить на двенадцать часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (124,'Промыть рыбу и обжарить на гриле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (124,'Отварить рис, смешать с лососем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (124,'Нори нарезать мелкими кусочками, залить водой и довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (124,'Вмешать соевый соус, мисо-пасту, сушеный тунец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (124,'Довести бульон до кипения еще раз, влить его в рис с лососем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (125,'Воду в кастрюле довести до кипения, всыпать порошок даси, перемешать, варить на среднем огне несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (125,'Тофу нарезать кубиками, добавить в бульон вместе с заранее размоченными водорослями вакаме.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (125,'Влить разбавленный бульоном мисо, добавить собу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (126,'Тофу разрезать на небольшие кусочки, протереть салфеткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (126,'Перемешать смесь из специй и мисо-пасту, обмазать тофу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (126,'Разогреть на сковороде растительное масло, выложить тофу, жарить сыр в течение пяти или семи минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (126,'Обжарить нарезанную китайскую капусту.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (518,'Натереть твердый сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (126,'Лапшу разложить в тарелки, добавить жареный тофу и капусту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (126,'Залить блюдо горячим овощным бульоном.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (127,'Разогреть духовой шкаф до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (127,'Накрыть пергаментом противень, высыпать арахис.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (127,'Поставить продукт в духовой шкаф, каждые пять минут доставать и перемешивать',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (127,'Общее время приготовления – от двадцати до двадцати пяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (127,'Орехи не должны подгореть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (127,'Продукт остудить и очистить от шелухи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (127,'Арахис высыпать в чашу блендера, перемолоть в течение десяти минут, делать паузы, чтобы прибор не перегрелся.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (127,'В готовую пасту добавить мед, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (127,'Продукт выложить в баночки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (128,'Орехи обжарить на сковороде, можно использовать микроволновую печь или духовой шкаф.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (128,'Время обжаривания – до двадцати пяти минут, температура – 200 градусов, продукт перемешивать и не допускать подгорания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (128,'Удалить шелуху.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (128,'При помощи блендера приготовить пасту из основного продукта с солью, сахарным песком, растительным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (128,'Орехи должны превратиться в крошку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (128,'Делать паузы, чтобы не сгорел прибор.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (128,'Готовую пасту переложить в банки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (129,'Приготовить картофельное пюре: отварить клубни, слить воду и размять, добавив сливочное масло, остудить. В готовое пюре добавить тертый твердый сыр, мелко порубленный укроп. Для густоты добавить муку в достаточном количестве.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (129,'Сформовать нетолстые лепешки. Чтобы пюре не прилипало – делать это мокрыми руками. На середину лепешек положить пластинки сырых шампиньонов, края соединить, панировать в муке. Жарить на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (129,'Приготовить соус, для этого натереть на крупной терке огурец среднего размера. Лишнюю жидкость отжать. Порубить чеснок или пропустить через чеснокодавку, измельчить зелень укропа. Добавить сметану или майонез или то и другое, в равных пропорциях. Все ингредиенты соединить. Соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (129,'Подать фаршированные картофельные котлетки с огуречным соусом, его выложить по ложечке на тарелки или подать отдельно, в соуснике. Для украшения блюда будут очень кстати порезанные малосольные огурцы, выложенные по краю блюда, и веточки укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (130,'Купить в магазине не обжаренный, очищенный арахис.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (130,'Промыть. Обсушить на полотенце.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (130,'Противень застелить пергаментом, выложить орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (130,'Прогреть духовой шкаф до 180 градусов, жарить арахис в течение десяти или пятнадцати минут. Продукт перемешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (130,'Готовый продукт остудить, пересыпать в блендер.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (130,'Добавить соль, растительное масло, мед, взбить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (130,'В процессе приготовления делать паузы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (130,'Готовую пасту выложить в небольшие стеклянные емкости.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (131,'Арахис промыть под проточной водой, выложить на бумажное полотенце.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (131,'Высушить, духовку прогреть до 180 – 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (131,'Орехи выложить на противень, жарить в духовом шкафу в течение пятнадцати минут. Продукт помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (131,'Обжаренные орехи вынуть из духовки, остудить, переложить в чашу блендера, взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (131,'Прибор несколько раз останавливать, пасту перемешивать ложкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (131,'Добавить какао-порошок, сахар, соль, растительное масло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (131,'Ингредиенты перемешать и взбить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (131,'Пасту переложить в банку, поставить в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (132,'Ингредиенты должны быть комнатной температуры. Духовой шкаф прогреть до 185 – 195 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (132,'В отдельной емкости взбить масло с сахаром и ванильным сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (132,'Добавить арахисовую пасту, все вместе еще раз взбить до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (132,'Перемешать соль с мукой, пищевой содой и разрыхлителем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (132,'Продукты просеять и добавить в основную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (132,'Замесить тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (140,'Другой вариант – микроволновая печь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (132,'Застелить противень пергаментом, разделить тесто на небольшие шарики, каждый выложить на противень и раздавить ладонью в лепешку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (132,'Время выпекания – до пятнадцати минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (132,'Готовый продукт вынуть из духовки, выложить печенье на решетку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (132,'Подать к столу в остывшем виде.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (133,'Орехи промыть под проточной водой, выложить ровным слоем на противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (133,'Арахис обжарить в духовом шкафу при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (133,'После того, как верхняя оболочка полопается, орехи вынуть и остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (133,'По желанию можно подержать продукт в духовке еще пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (133,'Орехи очистить, потереть в руках, чтобы отошла шелуха.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (133,'Арахис высыпать в блендер, добавить мед и соль, продукты измельчить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (133,'Пасту соскрести со стенок емкости, добавить растительное масло, измельчать еще две минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (134,'Арахис обжарить на сковороде, в духовке или в микроволновой печи. Время приготовления – десять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (134,'Шелуху убрать или оставить – по желанию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (134,'Взбить орехи в блендере в течение пяти минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (134,'В пасту добавить соль и еще раз взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (134,'Шоколад растопить на водяной бане или натереть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (134,'Добавить натуральный мед или какао-порошок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (134,'Смесь довести до однородного состояния, разлить в баночки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (135,'Сырые орехи очистить, обжарить на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (135,'Продукт измельчить в блендере.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (135,'Добавить соль и мед, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (135,'Пасту можно сделать сладкой или соленой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (136,'Арахис выложить на противень, сушить в духовом шкафу. Время – пятнадцать минут, температура – 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (136,'Остывшие орехи очистить от шелухи, посолить и размолоть в блендере.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (136,'Добавить сироп, продолжать измельчать продукт до получения пасты, время – полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (136,'Пасту выложить в банки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (137,'Стейки лосося натереть солью и перцем, сбрызнуть лимонным соком, его можно не жалеть, плотно уложить в контейнер, полить бальзамическим уксусом, можно обойтись и без него. Дать полежать и пропитаться специями в холодильнике не меньше 12 часов, лучше оставить на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (137,'Использовать готовые панировочные сухари или приготовить домашние. Для этого свежие белые ломтики хлеба, уже подсохшего, немного запечь в духовке или микроволновой печи, измельчить в блендере. Растопить сливочное масло, добавить нашинкованную зелень укропа, петрушки, кинзы, всыпать паприку, любые другие сухие травы по вкусу. Добавить сухари и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (137,'Противень застелить фольгой или бумагой для выпечки, выложить рыбу, запечь при температуре 180 градусов в течение 10–15 минут. На почти готовую рыбу выложить панировочную массу, печь сочный лосось со специями в панировке еще столько же при более низкой температуре – 160 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (138,'Арахис и миндаль обжарить, выложить в чашу блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (138,'Орехи измельчить в крошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (138,'Добавить соль, растительное масло, сахарный песок и какао-порошок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (138,'Часть кусочков орехов можно отложить, а затем перемешать с конечным продуктом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (139,'Почистить и нарезать ломтиками спелые яблоки, сладкие, десертные. Готовые пластинки слоеного теста разрезать по диагонали, положить на каждый кусочек по ломтику яблока и свернуть маленькими рулетами, начинать заворачивать с широкой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (139,'Таким же образом поступить со всеми рулетами, выложить их на смазанный противень или на бумагу для выпечки. Растопить сливочное масло, добавить сахар и ванилин, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (139,'Залить смесью домашние слойки с яблоками. Добавить спрайт, посыпать молотой корицей, гвоздикой. Печь при средней температуре в течение 25 – 30 минут. Подать к чаю, кофе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (140,'Орехи промыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (140,'Выложить на противень в ряд. Время жарки – десять минут, температура – 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (140,'Остывший продукт измельчить в кухонном комбайне или в блендере.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (140,'Растопить на водяной бане сливочное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (140,'Добавить в ореховую массу вместе с сахарным песком, кокосовой стружкой, солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (140,'Влить растительное масло, все еще раз перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (140,'Готовый продукт выложить в банку и поместить в холод.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (141,'Всыпать обжаренные орехи в блендер, размолоть. Скорость – средне-высокая, время – от пяти до шести минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (141,'Добавить целый арахис, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (142,'Перемешать пшеничную и ржаную муку, продукты просеять, сформовать горку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (142,'Растопить сливочное масло, перемешать с солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (142,'Влить в муку в углубление горки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (142,'Воду добавлять порциями, замесить тесто, сформовать шар, завернуть в пищевую пленку, убрать на полчаса в холод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (142,'Мойву очистить от крупных костей и голов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (142,'Рыбу мелко порубить, добавить майонез, лимонный сок, соль и молотый перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (142,'Охлажденное тесто раскатать, толщина овальной лепешки – от пяти до шести миллиметров.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (142,'Зеленый лук промыть, порубить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (142,'Половину рыбы с майонезом выложить посередине, посыпать зеленым луком, выложить оставшуюся часть начинки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (142,'Посыпать луком еще раз.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (142,'Накрыть полосками бекона.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (142,'Собрать края теста, скрепить сверху, пирог перевернуть швом вниз.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (142,'Смазать поверхность яичным желтком, печь в духовке в течение сорока минут, температура – 220 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (142,'Далее температуру уменьшить, пирог обернуть листом фольги, держать в духовке четыре часа.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Просеять ржаную муку через сито в большую емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Добавить сухие дрожжи, соль и сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Влить подогретое молоко и теплую воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Замесить тесто, руки можно смазать растительным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Готовый продукт не должен прилипать к рукам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Миску смазать маслом, выложить тесто, прикрыть полиэтиленом или пищевой пленкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Поставить в тепло на сорок пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Масса должна увеличиться вдвое.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Тесто вынуть, выложить на рабочую поверхность, помять руками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Чашу мультиварки смазать маслом, выставить режим подогрев на две минуты.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'В выключенный прибор выложить тесто.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Подержать под крышкой сорок минут, не открывать.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Далее выставить режим «Выпечка» на час. Температура – 150 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Через сорок минут мультиварку открыть, хлеб перевернуть.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Печь хлеб еще двадцать минут.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (143,'Аккуратно достать продукт из чаши, остудить.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'В большую керамическую или стеклянную емкость влить немного горячей воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Добавить ржаную муку, перемешать ложкой или деревянной лопаткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Накрыть посуду пищевой пленкой или обычным бумажным полотенцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Поставить тесто в тепло на сутки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Добавить еще немного горячей воды в опару.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Всыпать просеянную ржаную муку, перемешать, затянуть пленкой, поставить в тепло еще на сутки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Через сутки процесс повторить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'На четвертый день приготовления добавить половину литра горячей воды, муку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Масса должна стать похожей на густую сметану.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Поставить тесто в тепло на день.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Три четверти массы отделить, выложить в отдельную емкость.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'В оставшуюся опару добавить кипяченую воду и ржаную муку.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'С этой частью массы можно повторять все перечисленные действия для замешивания новых порций хлеба.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Опару можно также добавлять в тесто для выпечки вместо дрожжей.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'В большую часть теста добавить соль, растительное масло, мед, перемешать.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Всыпать муку порциями, замесить тесто, оно должно быть плотным.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'При вымешивании рабочую поверхность посыпать пшеничной мукой.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Чашу мультиварки смазать маслом, выложить тесто, прикрыть бумажным полотенцем.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Смазать изделие подсолнечным маслом силиконовой кистью.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Выставить режим «Выпечка» на полчаса.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Мультиварку выключить, хлеб перевернуть.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Еще раз выставить режим «Выпечка» на полчаса.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (144,'Готовый хлеб положить на решетку для приготовления на пару, дать остыть под полотенцем.',NULL,24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (145,'Натереть крупные клубни, добавить яйцо, соль, перец и муку до густоты. Если после натирания картофеля получилось много жидкости – её лучше слить. Смесь выложить в виде блина средней толщины на смазанную растительным маслом сковороду, жарить 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (145,'Картофельную основу для пиццы осторожно перевернуть, смазать верхнюю, обжаренную сторону, майонезом, выложить кружки спелого помидора, кусочки колбасы, любую рубленую зелень. Посыпать тертым твердым сыром, жарить еще 10 минут под крышкой. Подать картофельную пиццу с колбасой, порезав на порции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (146,'В миску влить теплое молоко, растворить сухие дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (146,'Всыпать соль, сахарный песок, влить немного растительного масла, ингредиенты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (146,'Пшеничную муку просеять, ввести в молоко порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (146,'Доску присыпать мукой, выложить тесто, замесить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (146,'Вернуть массу в емкость, прикрыть бумажным полотенцем, оставить на сорок минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (146,'Мультиварку смазать растительным маслом, выложить тесто, выставить режим «Подогрев» на десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (146,'Прибор выключить, хлеб должен остыть в течение двадцати минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (146,'Выставить режим «Подогрев» еще раз, но на три минуты. Время остывания – пятнадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (146,'Выставить режим «Выпечка» на полтора часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (146,'Хлеб вынуть, перевернуть, выставить режим «Выпечка» на полчаса.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (146,'Общее время выпекания – два часа. Готовое изделие вынуть, остудить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (147,'В большую миску для замешивания всыпать овсяные хлопья, соль, дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (147,'Подогреть немного воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (147,'Залить сухую смесь, перемешать, оставить для набухания на двадцать пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (147,'Пшеничную муку просеять, вводить в основную массу постепенно, порциями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (147,'Тесто перемешивать, оно должно быть жидким.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (147,'Выложить тесто в чашу, закрыть крышку, выставить режим «Мультиповар» на один час, температура – тридцать пять градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (147,'Крышку открыть, посыпать хлеб хлопьями.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (147,'Выставить режим «Выпечка» на пятьдесят минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (147,'Хлеб перевернуть, печь при том же режиме еще пятнадцать минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (147,'Мультиварку выключить, хлеб остудить в течение десяти минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (147,'Открыть крышку, продукт вынуть.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'В большую емкость всыпать солод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Добавить обычный белый или коричневый сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Всыпать соль, семена кориандра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Компоненты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Промыть зелень петрушки или укропа, порубить, добавить в основную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Влить растительное масло, горячую воду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Массу перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Ржаную муку просеять через сито, всыпать в миску.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Ту же операцию проделать с овсяной мукой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Если нет муки – ее можно сделать из хлопьев при помощи кофемолки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Другой вариант – использовать пшеничную муку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Добавить закваску, перемешать вилкой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Тесто мять руками, масса должна быть эластичной.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Форму смазать маслом, выложить хлеб, смазать сверху при помощи кисти.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Закрыть мультиварку, выставить температуру в сорок градусов, время выпекания – шесть часов.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Выставить режим «Выпечка» на час.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (148,'Готовность продукта проверить зубочисткой.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (149,'В миску влить подогретую воду, всыпать соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (149,'Добавить свежие дрожжи, просеянную пшеничную муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (149,'Перемешать лопаткой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (149,'Поставить массу в тепло на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (149,'Чашу мультиварки смазать растительным маслом, выложить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (149,'Хлеб перевернуть, оставить в режиме той же программы на двадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (150,'Продукты для хлеба должны быть комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (150,'Кефир подогреть в небольшой емкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (150,'Снять с огня, добавить в продукт дрожжи, сахар, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (150,'Ингредиенты перемешать, опара должна постоять пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (150,'В другую миску вбить сырое яйцо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (150,'Укроп вымыть, порубить, добавить в яичную массу вместе с зерновой горчицей и подсолнечным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (150,'Влить опару, перемешать ингредиенты при помощи венчика.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (150,'Пшеничную муку просеять через сито, всыпать в основную массу, тесто должно получиться мягким.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (150,'Накрыть продукт полотенцем, поставить в тепло на сорок или пятьдесят минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (150,'Тесто боится сквозняков, форточки не открывать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (150,'Чашу мультиварки смазать растительным маслом, выложить тесто, выставить режим «Выпечка» на сорок пять минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (150,'Хлеб перевернуть, печь еще пятнадцать минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (151,'Говядину положить в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (151,'Нарезать тонкими длинными полосками, как для бефстроганова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (151,'Перемешать соевый соус и оливковое масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (151,'Замариновать говядину на десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (151,'Время обжаривания на сковороде с маслом – пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (151,'Нарезать половинками помидоры черри.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (151,'Выложить мясо на листья хорошо промытой рукколы, сверху – черри.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (151,'Блюдо полить соком, выделившимся при обжаривании мяса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (151,'Побрызгать бальзамическим уксусом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Мясную вырезку натереть ягодами можжевельника и давленым чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Соль и молотый перец – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Смазать оливковым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Сковороду с антипригарным покрытием и толстым дном раскалить, выложить несколько лавровых листочков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Прогреть до появления дымка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Жарить стейк в течение пяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Перевернуть несколько раз.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Репчатый лук нарезать полукольцами, залить огуречным рассолом, поставить в СВЧ-печь на минуту, мощность прогрева – максимальная.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Остудить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'В нижней части мясистых помидоров сделать надрез крестом, залить на несколько минут кипящей водой. Кожицу снять.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Мякоть нарезать дольками, семена удалить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Разноцветный перец печь в течение получаса, температура – 200 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Охладить под крышкой или в пакете.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Разрезать плоды вдоль, удалить кожицу, семена, плодоножку.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Мякоть нарезать клинышками.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Выложить на противень мясо и помидоры, время запекания – от десяти до пятнадцати минут, температура приготовления – 180 градусов.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Не допустить пригорания продуктов, в случае необходимости температуру уменьшить, время – увеличить.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Нарезать мясо тонкими слайсами, сбрызнуть их и помидоры бальзамическим уксусом, встряхнуть.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'На большую тарелку выложить лук, говядину, помидоры, перец слоями.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Украсить маслинами и каперсами, сбрызнуть уксусом еще раз и подать к столу.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (152,'Заправить салат можно соусом «Тартар» или смесью сметаны, горчицы и рубленой зелени.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (153,'Баклажан нарезать соломкой, посолить, дать постоять от десяти до пятнадцати минут, жидкость слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (153,'Такой прием поможет удалить лишнюю горечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (153,'Сладкий болгарский перец также нарезать соломкой, морковь натереть «по-корейски».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (153,'Порубить чеснок, зелень петрушки, перемешать с оливковым маслом, соевым соусом, лимонным соком, сахаром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (153,'Дать постоять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (153,'Говядину нарезать тонкими полосками и обжарить на сковороде с оливковым маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (153,'Добавить овощи – морковь и баклажаны, прогревать две минуты, далее – добавить перец.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (153,'Жарить до готовности, овощи не должны стать излишне мягкими.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (154,'Нарезать кусочками имбирь, выдавить сок из лайма.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (154,'Ингредиенты перемешать, добавить мед, оливковое масло, соевый соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (154,'Залить мясо, поставить на два часа в холод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (154,'Порвать руками листья пекинской капусты, выложить в глубокое блюдо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (154,'Нарезать соломкой свежие огурцы, чили и болгарский перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (154,'Семена кунжута обжарить в течение двух минут на раскаленной сковороде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (154,'Продукт должен приобрести золотистый оттенок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (154,'Из говядины в маринаде убрать имбирь, мясо с жидкостью перелить на сковороду с маслом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (154,'Время обжаривания – от семи до десяти минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (154,'Добавить овощи и мясо к пекинской капусте, посыпать семенами кунжута, перемешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (154,'Дать постоять под крышкой три-пять минут для пропитывания.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (154,'Блюдо подать теплым.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (155,'Перемешать соевый соус с арахисовым маслом и сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (155,'Полить говяжью вырезку, поставить в холод на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (155,'Болгарский красный перец нарезать кубиками среднего размера, свежий огурец – дольками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (155,'Порубить кинзу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (155,'Мясо запечь на листе фольги, температура – 220 градусов, время – от двадцати минут до получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (155,'Готовое мясо нарезать тонкой соломкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (155,'Приготовить соус из сока лайма, давленого чеснока, тертого имбиря, арахисового масла и соевого соуса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (155,'Полить мясо заправкой, добавить остальные ингредиенты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (156,'Обжарить рубленый репчатый лук, чеснок, пропущенный через чеснокодавку, и тертую на крупной терке морковь. В обжарку добавить соломку красного болгарского перца, потушить почти до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (156,'Смесь залить помидорами в собственном соку, их нужно немного размять, кожуры в такой заготовке обычно не бывает, если она есть – удалить. Всё вместе прогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (156,'Отдельно, на другой сковороде, обжарить мясной фарш с рубленым луком. Фарш можно взять говяжий или нежирный свиной с говяжьим, в равных пропорциях. Соединить с морковно-помидорной поджаркой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (156,'Корень имбиря очистить и крупно порезать, добавить в смесь. Залить водой, кипятить несколько минут. Последний ингредиент – лапша, можно использовать домашнего приготовления, доварить острый суп с лапшой и имбирем до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (157,'Нарезать репчатый лук мелким кубиком и обжарить на растительном масле до золотистости. Куриное филе прокрутить через мясорубку 2 раза или пробить блендером, мелко нарезать зелень. В полученный очень мелкий куриный фарш положить остывший обжаренный лук и зелень, выдавить чеснок.','https://vkuso.ru/data/cache/data/4a/8c8a41d4edfcf4a_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (157,'Вбить яйцо, добавить сметану, посолить и поперчить по вкусу. Все перемешать.','https://vkuso.ru/data/cache/data/2c/fb796a2bbc7dd2c_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (157,'Постепенно в 2 захода всыпать муку, хорошо перемешивая ложкой. Масса должна получиться более жидкой и вязкой, чем для котлет.','https://vkuso.ru/data/cache/data/c1/971c7b751f8edc1_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (157,'Нарезать капусту, картошку, репчатый лук, болгарский перец, помидоры и натереть морковь на крупной терке. На растительном масле обжарить помешивая все овощи сразу до уменьшения объема, жарить на среднем огне примерно 5 мин. Переложить все овощи в большую кастрюлю, посолить и поперчить по вкусу, добавить хмели-сунели, лавровый лист и перец горошек.','https://vkuso.ru/data/cache/data/3d/192b522b3421f3d_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (157,'Залить овощи водой, дать закипеть помешивая.','https://vkuso.ru/data/cache/data/79/73e2d6fb4979079_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (157,'Закрыть крышкой и варить на среднем огне около 15 мин.','https://vkuso.ru/data/cache/data/69/8aeaebcc5bb4869_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (157,'Через 15 мин снять крышку и опустить в щи куриные клецки, формируя их двумя ложками, смоченными в воде.','https://vkuso.ru/data/cache/data/21/e09e8f1d6580021_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (157,'Стараться формировать клецки одинакового размера. Суп при этом должен слегка кипеть, чтобы клецки не слипались. Когда все клецки будут опущены, накрыть щи крышкой и оставить на среднем огне еще на 10 мин.','https://vkuso.ru/data/cache/data/03/931c3c6bc341503_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (157,'Подавать щи со сметаной, посыпав их нарезанным зеленым луком.','https://vkuso.ru/data/cache/data/5b/b5cdecc0f05335b_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (158,'Ветчину нарезаем средними брусочками (кубиком, полосками), перекладываем в тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (158,'Сыр нарезаем так же как и ветчину, брусочками (кубиком, полосками) перекладываем в тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (158,'Часть сыра натираем на мелкой терке, перекладываем в тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (158,'Взбиваем 1 кур. яйцо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (158,'Раскатываем слоеное тесто, делим его на равные части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (158,'На одну часть слоеного теста укладываем ветчину, сыр. Края смазываем взбитым кур. яйцом. Заворачиваем в конвертик и края защипляем, и перекладываем на противень. С остальными частями, и 2 пластом теста, поступаем точно так же.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (158,'Смазываем хачапури взбитым кур. яйцом, и часть из них посыпаем натертым сыром. Даем немного подойти, и отправляем в духовку при 180*С на 20-25 мин. Подаем к чаю.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (159,'Нарезаем картофель, огурцы и яйца кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (159,'Нарезаем укроп и зеленый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (159,'Нарезаем куриное филе на кусочки. Добавляем соль, черный молотый перец, красный острый и растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (159,'Обжариваем куриное филе на углях 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (159,'Нарезаем куриное филе кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (159,'Смешиваем все нарезанные ингредиенты и добавляем сыворотку, майонез, соль и все перемешиваем. Готовьте с удовольствием и приятного аппетита! Подробный рецепт приготовления вы можете посмотреть в видео.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (160,'Взбить добела яйца с сахаром. Взбивать можно венчиком или миксером, масса должна увеличиться в три раза по сравнению с первоначальным объемом. На этом этапе приготовления добавить муку и разрыхлитель, который лучше просеять вместе с мукой. Перемешать. Тесто должно быть полужидким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (160,'Приготовить начинку, для этого большое спелое яблоко очистить от кожуры, вырезать сердцевину и разрезать на дольки. Кожуру можно не снимать, если она не слишком грубая. Форму для запекания смазать сливочным или растительным маслом, выложить яблочные дольки, залить тестом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (160,'Печь при температуре 180 градусов в течение 35 – 40 минут. Готовность пирога проверить зубочисткой, при протыкании выпечки она должна остаться сухой и на ней не должны остаться кусочки теста. Выложить классическую домашнюю шарлотку с яблоками на большое блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (161,'Отварить курицу, порезать кусочками, кожицу лучше удалить. Порезать маринованные грибы, если они слишком острые – промыть водой, а затем нарезать. Свежий или маринованный огурец также нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (161,'Отварить, очистить, яйца, порезать дольками. Слить жидкость из банки с консервированной кукурузой. Оливки без косточек можно использовать целиком или разрезать на половинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (161,'Приготовить заправку: смешать майонез (лучше взять легкий, малокалорийный) с апельсиновым соком, добавить немного гранатового бальзамического уксуса наршараб. Соль – по вкусу, добавить любую свежую рубленую зелень. Перемешать, залить салат «Курочка Ряба» при подаче.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (162,'Среднего размера огурец натереть  на терке и отжать лишний сок. Добавить пару зубчиков рубленого чеснока, жирную сметану, мягкий сливочный сыр, рубленый укроп. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (163,'Смешиваем муку, молоко, яйца, масло, соль и сахар.','https://vkuso.ru/data/cache/data/d3/d341cab6bef1cd3_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (163,'Трем сыр.','https://vkuso.ru/data/cache/data/e5/b5e1878ea6c3ee5_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (163,'Добавляем к тесту.','https://vkuso.ru/data/cache/data/06/8c1583053e2b106_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (163,'Кладем укроп.','https://vkuso.ru/data/cache/data/2a/23ace40b7c01d2a_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (163,'Перемешиваем.','https://vkuso.ru/data/cache/data/e0/918332144b4d3e0_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (163,'Выпекаем.','https://vkuso.ru/data/cache/data/e7/9abb9f1b6440de7_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (163,'Смазываем сливочным маслом.','https://vkuso.ru/data/cache/data/8e/bbce58535586c8e_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (163,'Скатываем роллы.','https://vkuso.ru/data/cache/data/48/035088ee5bd0a48_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (164,'Очистить лук и чеснок, нарезать мелкими кубиками. Вареную колбасу нарезать соломкой или небольшими брусочками. Очистить и натереть картофель, другой вариант – попустить кусочки клубней через мясорубку с крупной решеткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (164,'В картофельную массу добавить все нарезанные ингредиенты, плюс муку, соль и перец по вкусу. Масса должна получиться густой, при необходимости нужно слить излишнюю жидкость от натертого картофеля или добавить еще немного муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (164,'Жарить картофельные драники с вареной колбасой на раскаленном растительном масле, с двух сторон. Довести до готовности в духовке. Подать горячими, для украшения использовать свежую зелень, «кудряшки» из зеленого лука (перо порвать на тонкие полоски).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (165,'Манку залить кефиром в равных пропорциях по объему, дать крупе разбухнуть в течение 40 минут. Добавить куриное сырое яйцо, размешать. Соду  погасить уксусом или лимонным соком, добавить в манно-кефирную массу, затем по стакану сахара и муки, порциями, смесь вымешать. Можно воспользоваться блендером или венчиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (165,'Наполнить тестом смазанные маслом формочки для кексов, не до верха, оставить в каждой по одной трети объема, выпечка немного поднимется. Печь кексики из манной крупы при 200 градусах в течение 40–50 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (166,'Приготовить тесто. Для этого разделить яйца на белки и желтки. Белки взбить в пену венчиком или блендером. Желтки взбивать отдельно с сахаром и ванилином до тех пор, пока масса не побелеет. В желтковую массу добавить молоко, растительное масло, жидкий мед, какао. Муку просеять вместе с разрыхлителем, добавить в массу, перемешать. Самый последний ингредиент – взбитые белки, перемешивать осторожно, чтобы тесто осталось пышным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (166,'Тесто разделить на две части, выпечь два коржа поочередно, в течение 12 минут каждый при температуре 180 градусов. Можно выпечь всю массу теста сразу, одним коржом, а затем разрезать на два одинаковых по горизонтали, но времени потребуется больше и масса может не пропечься в середине.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (166,'Приготовить крем, для этого замочить желатин в небольшом количестве воды для набухания. Разбавить его молоком (половиной объема), прогреть на тихом огне до полного растворения. Добавить оставшееся молоко, сгущенку, мед. Отдельно взбить сметану с сахаром, добавить ванилин, взбивать венчиком в течение нескольких минут. Влить молочно-желатиновый крем, перемешать. Поставить смесь в холодильник на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (166,'Готовый охлажденный корж смазать кремом, сверху положить второй и прижать. Можно приготовить глазурь из сметаны, сахара, какао, сливочного растопленного масла. Смесь прогреть на тихом огне, размешать и вылить на коржи сверху. Выпечка должна постоять несколько часов для пропитывания коржей. При подаче очень вкусные пирожные «Киндер милк слайс» порезать на прямоугольные порции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (167,'В глубокой таре взбить сливки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (167,'Добавить сгущенное молоко и какао-порошок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (167,'Хорошо перемешать до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (167,'Добавить маршмеллоу и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (167,'Переложить в емкость для замораживания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (167,'Убрать в морозилку на 4 часа. Мороженое готово! Всем приятного аппетита! Больше кушайте, никого не слушайте!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (168,'Вымыть не очень крупные яблоки, срезать с них верхушки, вырезать сердцевину так, чтобы яблоко внешне осталось целым. Поместить фрукты в сито и отварить на пару в течение 10 – 15 минут, до готовности. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (168,'Для начинки нужны грецкие орехи и вареное сгущенное молоко. Орехи не нужно измельчать мелко, пусть будут кусочки среднего размера, смешать их со сгущенкой и чайной ложкой начинить смесью отваренные яблоки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (168,'Сверху плоды обмазать сметаной, посыпать стружкой кокоса, тертым шоколадом. Охладить десертные яблоки «Рафаэлло» в холодильнике в течение получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (169,'На противень для запекания положить круглый готовый лаваш средней толщины. Лепешку намазать томатным соусом или томатной пастой, выложить сверху полоски ветчины, тонко нарезанной, кружки свежих спелых помидоров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (169,'Посыпать твердым тертым сыром, соль, перец, сухие травы –  по вкусу. Немного сбрызнуть пиццу оливковым маслом и печь в духовке в течение 10 – 15 минут. Подать, порезав на порции.  При подаче  пиццу с ветчиной и помидорами посыпать зеленью кинзы, петрушки, укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (170,'Натереть кабачки на крупную терку и перемешать с солью, что бы он дал сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (170,'Добавить к натертому яблоку отжатый кабачок, яйцо, сахар, корицу, муку. Тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (170,'Пожарить оладьи на разогретой сковороде с растительным маслом, обжаривая с двух сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Включить духовку и разогреть до 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (170,'Подавать можно со сметаной, любым йогуртом или кушать просто так.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (171,'Приготовить бисквит. Яйцо взбить с сахаром, добавить муку, просеянную с разрыхлителем, вымешать однородное тесто. Выпекать в смазанной маслом форме при 180°С в течении 10 минут. Готовый бисквит остудить, дать ему подсохнуть и измельчить в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (171,'Приготовить начинку. Смешать вишню с сахаром и растереть ягоды вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (171,'В высокие стаканы выкладывать слоями бисквитную крошку, йогурт и вишню. Слои повторить до заполнения стакана. Убрать в холодильник на 1-2 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (171,'Перед подачей посыпать десерты рубленными орехами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (172,'Смешать в миске сырые куриные яйца со сметаной, сахаром, щепоткой соли. В готовую однородную массу влить погашенную уксусом или лимонным соком соду, выложить пачку размятого творога. Снова перемешать, добавить муку. Замесить творожное тесто, оно должно быть мягким, но достаточно плотным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (172,'Раскатать тесто в колбасу, нарезать на кусочки, раскатать их скалкой в лепешки, подсыпать муку, чтобы тесто не прилипало. Начинка годится любая – картофельная, капустная, яблочная. Бабушкины пирожки из творожного теста жарить на сковороде, на раскаленном растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (173,'На разогретую с маслом сковородку выкладываем фасоль. Перемешиваем, солим, добавляем специи. Закрываем крышкой на 15 минут и тушим на среднем огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (173,'Перемешиваем фасоль (чтобы не пригорела). Тушим еще 10 мин (прим. в видео).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (173,'Добавляем майонез и чеснок. Тушим 3-5 мин с открытой крышкой. И фасоль готова. Приятного аппетита!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (174,'В теплой воде (30 мл 38 градусов) развести сахар и сухие быстродействующие дрожжи, поставить в теплое место для их активизации и вспенивания примерно на 5-10 мин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (174,'В подошедшие дрожжи залить теплую воду (280 мл 38 градусов), теплое растительное масло (38 градусов), добавить соль и все семечки. Семечки лучше предварительно слегка обжарить на сухой сковороде. Все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (174,'Постепенно ввести в смесь цельнозерновую муку, просеивая ее через сито. Вводить муку в 3 захода, сначала перемешивая тесто ложкой и в последний раз замесить руками. Вымесить тесто на столе около 5 мин. Если оно будет слишком сильно липким, можно смазать стол и руки растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (174,'Слегка липнущее к руками довольно плотное тесто положить в смазанную растительным маслом глубокую миску, накрыть пленкой и поставить в теплое место на 30-45 мин. Тесто должно увеличиться в объеме минимум в 2 раза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (174,'Подошедшее тесто выложить на слегка присыпанный обычной мукой стол, совсем слегка обмять и подмесить, разделить на 2 части и сформировать 2 батона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (174,'Противень застелить пекарской бумагой, присыпать бумагу обычной мукой, выложить на нее батоны на расстоянии друг от друга, слегка присыпать их мукой, накрыть х/б полотенцем и оставить для расстойки на 15-20 мин пока они не увеличатся в объеме примерно в 1,5 раза',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (174,'Через 15 мин сделать на батонах небольшие надрезы острым ножом и поставить в заранее разогретую духовку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (174,'Выпекать хлеб при 190*С 40-45 мин до желаемой румяности корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (174,'Испеченный хлеб остудить на решетке ничем не прикрывая, если Вы хотите получить хрустящую корочку. Если хлеб нужен с более мягкой корочкой можно накрыть его х/б полотенцем и остудить на деревянной доске.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (175,'Нарезаем баклажаны на 2 части. Нарезаем перцы длинными дольками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (175,'Отправляем баклажаны в разогретую на 200°С духовку (кладем разрезанной частью вниз).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (175,'Отправляем на другом противне перцы при этой же температуре предварительно смазав олив. маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (175,'Перцы готовы через 30 мин. Баклажаны готовятся 50 мин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (175,'Мелко крошим чеснок и петрушку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (175,'Режем перцы кубиками и достаем мякоть баклажана вилкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (175,'Смешиваем все ингредиенты и солим по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (176,'Смешайте мёд (растопить если засахарился) с маслом (комнатной температуры или слегка размягченным).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (176,'Добавьте яйцо и перемешайте. После этого добавляем сахар. Перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (265,'Филе разморозить при комнатной температуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (176,'Добавляем воду. Пряности по вкусу. Тщательно перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (176,'Добавляем просеянную муку (сода добавлена в муку).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (176,'Замешиваем тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (176,'Отщипываем понемногу и скатываем шарики с размером чуть меньше грецкого ореха.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (176,'Выкладывем шарики на противень застеленный пергаментной бумагой. Рекомендую посмотреть видео как лучше выкладывать шарики.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (176,'Выпекаем при температуре 210 градусов 15 - 20 мин. до золотистого цвета.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (176,'Охлаждаем и отделяем колобки от друг друга. Выкладываем на тарелку и посыпаем сахарной пудрой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (177,'Размять вилкой яичные желтки, смешать с растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (177,'Добавить уксус и горчицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (177,'Насыпать по вкусу перец, соль, сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (177,'Размешать до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (177,'Налить в посуду сметану, подготовить зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (177,'Ее можно измельчить вручную или через мясорубку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (177,'Можно также смолоть в блендере.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (177,'Оставить мелко порубленную зелень для украшения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (177,'Соединить зелень и сметану, положить в желтковую смесь, размешать до однородности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (177,'Мелко порубить и положить оставшийся белок.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (177,'Отставить минут на шестьдесят, чтобы настоялся, при комнатной температуре.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (178,'Налить воду, молоко, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (178,'Насыпать в яично-молочную смесь просеянную муку и сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (178,'Размешать, чтобы не было комков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (178,'Важно, чтобы тесто не было очень густым, но и не сильно жидким, что-то среднее между молоком и тестом на оладьи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (178,'Если получается очень жидко, то насыпать чуть-чуть муки, если густо, то налить воды.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (178,'Добавить в тесто масло, размешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (178,'Разогреть масло на сковороде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (178,'Зачерпнуть тесто, осторожно вылить на сковороду.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (178,'Перевернуть сковороду таким образом, чтобы тесто растеклось по всей посуде.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (178,'Когда тесто покроется пузырьками, осторожно снять лопаткой и перевернуть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (178,'Жарить до готовности секунд десять.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (179,'Подготовить продукты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (179,'Перетереть творог через ситечки или измельчить в блендере.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (179,'Положить чуть-чуть взбитые яйца, разрыхлитель, цедру, насыпать сахар, налить молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (179,'Размешать до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (179,'Аккуратно ввести муку, мешать, чтобы не было комков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (179,'На среднем огне нагреть сковороду, налить чуть-чуть масла (растительного).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (179,'Положить на сковороду оладьи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (179,'Жарить минуты две до румяной корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (179,'Перевернуть аккуратно творожные оладьи с цедрой апельсина, грейпфрута и лимона, поджарить со второй стороны.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (179,'Таким способом приготовить оладьи из оставшегося теста.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Растворить в большой емкости мед с маргарином или маслом, насыпать соду, перемешать венчиком, убрать с плиты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Вбить яйца по одному, тщательно взбивая, насыпать сахар (1/2 стакана), размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'По частям насыпать муку, мешать лопаткой или руками, пока не получится густое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Поделить тесто на 24 части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Каждую из них тоненько раскатать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Вырезать коржики.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Перенести на противень можно намотав тесто на скалку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Выпекать минут пять, соблюдать температуру 180 градусов, коржики должны стать коричнево-золотистого цвета.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Обрезки, оставшиеся от коржей, понадобятся для присыпки тортика.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Хорошенько измельчить их скалкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Сделать крем: растворить в кипятке кофе.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Можно делать и без кофе.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Соединить сметану, сахар (3 стакана), кофе, загуститель, взбить миксером.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Если сметана жирная, то загуститель можно не добавлять.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Положить на блюдо первый корж, намазать обильно кремом, положить сверху второй коржик и так далее.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Самый верхний коржик намазать кремом, аккуратно намазать кремом бока.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Измельчить орешки.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Посыпать торт полностью крошкой, осторожно посыпать сверху орешками.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Отправить в холодильник на ночь.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (180,'Утром уже можно пробовать.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (181,'Порубить лук-репку и обжарить его на растительном масле, добавить мелко порезанные шампиньоны или другие грибы, жарить еще 15 минут, пока не испарится жидкость. Помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (181,'Картофель очистить и натереть, слить лишнюю жидкость. В массу добавить обжарку с грибами, муку, чтобы увеличить вязкость, перемешать. Влить яйцо, соль, перец молотый – по вкусу, снова перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (181,'На раскаленном масле на сковороде обжарить драники, смесь выкладывать на сковороду с раскаленным растительным маслом в виде круглых лепешек, столовой ложкой. Жарить деревенские драники с луком и грибами с двух сторон по несколько минут, до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (182,'Растереть шоколадное масло, яйца сахар, сливки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (182,'Насыпать такое количество муки, чтобы тесто было эластичным и гладким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (182,'Завернуть тесто в полиэтиленовую пленку, отправить минут на пятнадцать в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (182,'Раскатать тесто, положить в формочку, сделать бортики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (182,'Сделать проколы вилкой, готовить минут пятнадцать, соблюдать температуру 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (182,'Растопить на водяной бане шоколад, позволить остыть до комнатной температуры.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (182,'Взбить яйца, сливки, растопленный шоколад, сахар.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (182,'Помыть виноград, разрезать пополам, убрать косточки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (182,'Подсушить орехи в духовке, смешать с виноградом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (182,'Виноград и орехи добавить в шоколадную смесь.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (182,'Вылить на торт, готовить минут тридцать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (182,'Полить тортик растопленным шоколадом, украсить веточкой мяты и виноградом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (182,'Можно подавать шоколадно-ореховый торт с виноградом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (183,'Картофель тщательно вымыть и отварить в мундире в течении 15 минут в кипящей воде. Вытащить картошку из кастрюли и оставить остужаться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (183,'Телятину залить водой и поставить на огонь, довести до кипения, варить 25 минут на медленном огне. Вынуть телятину из кастрюли и оставить остужаться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (183,'Лук очистить и нарезать полукольцами. Колбаски нарезать колечками.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (183,'Картофель нарезать дольками, чеснок тонкими пластинками. Отправить в сковороду, готовим на среднем огне до золотистого цвета, перемешивая. Посолить и поперчить, добавить тмин и майоран.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (183,'Говядину нарезать небольшими кусочками. Готовим 7 минут на среднем огне, перемешивая.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (184,'Сыр натереть на мелкой терке, добавить творог, добавить белок 1 яйца, соль, разрыхлитель, мука – замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (184,'Зелень (лук, укроп, петрушка) мелко нарезать, добавить к зелени желток 1 яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (184,'Противень застелить бумагой, присыпать мукой, сформировать баранки: руками раскатать кусочек теста в сосиску и соединить в кольцо. В середину баранки выложить смесь зелени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (184,'Баранки отправить в духовку на 30 минут при температуре 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (185,'В тарелке соединить яйца с сахарной пудрой, перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (185,'В отдельной тарелке соединить муку и соль, перемешать, влить яичную смесь. Замесить тесто, добавить растительное масло, смазать им тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (185,'Раскатать тесто толщиной 2-3 миллиметра, разрезать на ромбики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (185,'Прорезать ромбик в середине и протянуть один конец в прорезь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (185,'В сотейнике раскалить растительное масло. Масло должно покрывать хворост либо до середины, либо полностью (т.е. во фритюре). Готовим хворост на сильном огне до золотистого цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (185,'По желанию готовый хворост посыпаем сахарной пудрой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (186,'Начинка.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (186,'Добавляем сливочное масло и делаем картофельное пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (186,'Заправка.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (186,'Тесто.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (186,'Лепим вареники.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (186,'Варим вареники в подсоленной воде 4 - 6 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (186,'Готовые вареники поливаем луковой заправкой. Готовьте с удовольствием и приятного аппетита! Подробный рецепт приготовления вы можете посмотреть в видео.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (187,'Натереть морковь и сыр, выдавить чеснок, посолить поперчить, добавить майонез и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (187,'Протвень смазать маслом, намазать массу на хлеб и выложить на протвень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (187,'Отправить в духовку на 10 минут. Приятного аппетита!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (188,'Натереть на крупной терке твердый сыр. Добавить сырые яйца, майонез и хорошо перемешать. Соль – по вкусу, она может и не понадобиться. Массу вылить на застеленный бумагой противень, печь до готовности в течение 15 минут до расплавления сыра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (188,'Приготовить начинку, для этого порезать или пропустить через мясорубку лук-репку, добавить мясной фарш. Фарш можно использовать любой: говяжий, свиной или смесь нескольких в равных пропорциях. Посолить, поперчить, добавить для вязкости сырое куриное яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (188,'На готовый корж выложить начинку, свернуть его в виде рулета, печь при температуре 180 градусов в течение 40 минут. Остудить и порезать порциями. Закусочные рулетики из фарша при подаче можно выложить на листья зеленого салата, украсить помидорами и зеленью укропа, петрушки',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (189,'Шоколад поломать кусочками, отдельно, в разной посуде. Растереть яйца с сахаром, добавить просеянную муку с содой или разрыхлителем, вымесить. Разделить тесто пополам, в одну половину вмешать кусочки белого, в другую – темный шоколад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (189,'Разложить тесто в небольшие формочки, их нужно смазать маслом и наполнять на две трети объема (тесто поднимется в процессе выпечки и может «убежать»). Печь в духовке в течение 20–25 минут при 180 градусах до золотистого цвета. Готовые маффины с темным и белым шоколадом остудить и посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (190,'Мелко порубить зелень, любую: лук, петрушка, укроп, кинза. Смешать зеленую массу с майонезом, добавить рубленый чеснок или пропущенный через чеснокодавку, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (190,'Сыр нарезать на тонкие пластинки. Острым ножом на бедрышках приподнять шкурку, вложить под нее сыр. Выложить куриные бедрышки с сыром и зеленью в форму для запекания, посолить и смазать зеленым соусом. Печь в духовке в течение 40 минут на среднем огне, до образования золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (191,'Филе рыбы вымыть, обсушить бумажной салфеткой, посолить, поперчить, посыпать специями для рыбы. Для блюда понадобятся два лимона, из одного нужно выдавить сок, другой тонко порезать кружочками для украшения. Лимонным соком полить рыбное филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (191,'Размять маложирный сыр. Лук-репку порезать мелкими кубиками и добавить к сыру. Отварить креветки в чуть подсоленной воде с лавровым листом, очистить от панциря и тоже добавить к сыру. Попробовать на вкус, при необходимости досолить и поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (191,'Рыбу нафаршировать полученной смесью. Брюшко зашить, выложить рыбу на фольгу. Не заворачивать. Печь фаршированный лосось с начинкой из креветок на противне в духовке в течение 20 минут при 180 – 200 градусов, затем температуру уменьшить и печь еще 15 – 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (192,'Нарезать небольшими кубиками дайкон и абураагэ.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (192,'Перед нарезкой абураагэ опустить на минуту в кипящую воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (192,'Приготовить бульон даси, добавить овощи, варить от трех до пяти минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (192,'Смешать немного мисо с даси, добавить в суп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (193,'Нарезаем лук.','https://vkuso.ru/data/cache/data/54/ae5a981923af754_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (193,'Чистим морковь.','https://vkuso.ru/data/cache/data/64/b940e1647886f64_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (193,'Режем перец.','https://vkuso.ru/data/cache/data/ed/1c3246e35b59bed_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (193,'Пассеруем овощи.','https://vkuso.ru/data/cache/data/e4/6e2b521a30bf8e4_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (193,'Измельчаем зелень и чеснок.','https://vkuso.ru/data/cache/data/e9/b433a55324966e9_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (193,'Перебиваем авокадо с лимоном.','https://vkuso.ru/data/cache/data/f1/cffaada66d93df1_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (265,'Вымыть репчатый лук, очистить, нарезать кольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (193,'Соединяем ингредиенты.','https://vkuso.ru/data/cache/data/4c/5db3f7871bb654c_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (193,'Измельчаем блендером.','https://vkuso.ru/data/cache/data/b0/173eb70bc6a80b0_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (193,'Выкладываем в формы.','https://vkuso.ru/data/cache/data/05/ec1437a66b26e05_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (193,'Сервируем тарталетками и зеленью.','https://vkuso.ru/data/cache/data/6b/0dc08c12c5c946b_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (194,'Прогреть заранее приготовленный куриный бульон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (194,'Вмешать пасту мисо до растворения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (194,'Добавить рыбный концентрат «Хон Даши».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (194,'Довести суп до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (194,'Отваренную рисовую лапшу нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (194,'Раздавить фундук, нарезать зеленый лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (194,'Продукты положить в глубокую тарелку, всыпать кунжут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (194,'Довести бульон до кипения, добавить семгу, креветки, мидии, время приготовления – от минуты до двух.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (194,'Выложить морепродукты в лапшу с кунжутом и фундуком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (194,'Влить бульон.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (195,'В толстостенную кастрюлю налить воду и молоко, добавить сливочное масло и немного соли. Довести смесь до кипения, помешивать. Всыпать сразу всю муку и быстро перемешать, не снимая с огня. На дне посуды должна образоваться тонкая пленка, как только она появится – снять кастрюлю с огня. Получившееся гладкое, однородное тесто должно остыть в течение пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (195,'В тесто с помощью миксера вмешать сырые яйца, по одному. Тягучее, полужидкое тесто выкладывать на противень с помощью столовой ложки (чтобы масса не прилипала – окунать ложку в холодную воду). Или воспользоваться для выкладывания теста кондитерским мешком. Печь 20 – 30 минут при закрытой дверце духовки, иначе профитроли могут опасть. Выпечку остудить, верхушки булочек срезать. Приготовить начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (195,'Для этого взбить сливочный сыр (маскарпоне, филадельфия или любой другой аналогичный). Добавить немного лимонного сока, буквально несколько капель, перемешать. Начинить сыром профитроли. Длинными полосками нарезать семгу, свернуть их «розочками» или «рулетиками» и выложить поверх начинки. Украсить закусочные профитроли с начинкой из сыра и семги зеленью укропа, петрушки, каперсами, цедрой лимона, подать в качестве закуски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (196,'Сушеные водоросли протереть чистой и влажной тряпочкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (196,'Выложить в кастрюлю, влить холодную воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (196,'Поставить на тихий огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (196,'Филе трески нарезать на кусочки среднего размера, очистить креветки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (196,'Продукты отправить в кастрюлю, довести суп до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (196,'Вынуть комбу, добавить разведенную мисо-пасту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (196,'Суп довести до кипения еще раз, подать горячим.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (197,'Небольшого окуня обжарить до золотистого цвета на гриле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (197,'Тонко нарезать мёгу, залить водой на несколько минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (197,'Довести до кипения бульон даси, добавить пасту мисо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (197,'Рыбу выложить в пиалу, добавить мёгу, влить суп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (198,'Белую репу с листьями очистить и разрезать на четыре части. Листочки оставить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (198,'Если их нет – добавить хризантему или шпинат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (198,'Влить в кастрюлю бульон даси, добавить соль и сею.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (198,'Выложить нарезанную репу, варить пять минут на тихом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (198,'Перемешать мисо с бульоном, влить в суп, варить блюдо несколько минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (199,'Тоненько порезать мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (199,'Порезать перец любым способом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (199,'Раскалить казан или сковороду, налить масло, положить мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (199,'Чуть-чуть обжарить, потушить в своем соку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (199,'Когда испарится жидкость, налить молоко, поставить на маленький огонь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (199,'Тушить до тех пор, пока все молоко не испарится.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (199,'Положить сладкий перец.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (199,'Когда перчик потушится, добавить соевый соус, карри, соль.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (199,'Тушить еще немного.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (200,'Для начинки натереть твердый сыр. Отдельно нарезать кусочками помидоры, добавить рубленый чеснок.  Порубить любую зелень, заправить зеленую массу майонезом. Через мясорубку два раза пропустить рыбу (рецепт написан для рыбы пангасиуса, но можно использовать и любую другую).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (200,'Посолить, поперчить, добавить «рыбные» специи, яйцо для связки. Хорошо вымешать. Разделить на пять порций. Каждую порцию положить между листами целлофана, прогладить скалкой или руками в тонкую лепешку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (200,'Взбить яйца отдельно, каждую лепешку обмакнуть в яйцо одной стороной (осторожно, чтобы она не разломилась) и жарить на раскаленном масле на сковороде. Можно просто снять верхний целлофан, нанести на лепешку яичную массу, затем аккуратно перевернуть ее на сковороду с маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (200,'Обжарить бризоль из филе пангасиуса с сыром и с другой стороны. Готовые рыбные «блинчики» выложить на блюдо «яичной стороной» вниз, верх смазать майонезом, посыпать сыром, выложить помидоры с чесноком. Свернуть рулетом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (201,'По частям насыпать сахарную пудру, взбивать белки минуты две.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (201,'Соединить белки и миндаль, очень тщательно размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (201,'Положить в массу пищевой краситель, чтобы получился желаемый цвет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (201,'Застелить противень пергаментом, начать творческий процесс.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (201,'Печеньки должны быть диаметром не больше 2 сантиметров.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (201,'Хорошо разогреть духовку, выключить ее, поставить минут на тридцать противень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (201,'Из шоколада сделать начинку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (201,'Зеленые макаруны Angry birds можно подавать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (202,'Порезать куриную грудку на куски размером приблизительно 2 на 4 сантиметра, замариновать в маринаде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (202,'Сделать это можно накануне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (202,'Через несколько часов или на следующий день чуть-чуть отбить кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (202,'Посыпать паприкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (202,'Приготовить кляр: разбить яйца, насыпать чуть-чуть соли.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (202,'Добавить небольшое количество майонеза.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (202,'Насыпать муки столько, чтобы получилось тесто, как на оладьи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (202,'Размешать до однородности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (202,'Обвалять все кусочки в кляре.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (202,'Готовить очень быстро на горячей сковороде до золотистого оттенка.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (203,'Взбить яйца и сахарную пудру до воздушного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (203,'Растопить сливки и шоколад на водяной бане, позволить чуть-чуть остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (203,'Соединить с ванилью, яичной смесью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (203,'Полученную массу положить в форму, лучше использовать силиконовую формочку (если другая формочка, то постелить в нее пленку, чтобы удобней было доставать).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (203,'В формочку с кремом положить вишню, накрыть пленкой или фольгой, отправить часа на три в морозильную камеру до полного застывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (203,'Прежде чем подавать семифредо из белого шоколада и сливок с вишней на стол, подержать тридцать минут при комнатной температуре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (204,'Очистить печень от пленок, промыть холодной водой, залить молоком и оставить минимум на 30 мин',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (204,'Нарезать репчатый лук полу-кольцами и обжарить его на смеси растительного и 1/3 части сливочного масла до золотистости',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (204,'Печень, залитую молоком, откинуть через дуршлаг, чтобы молоко полностью стекло и выложить на сковороду к луку',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (204,'Жарить печень с луком на среднем огне 15 мин, постоянно помешивая',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (204,'Через 15 мин залить печень сливками, чтобы она была почти полностью покрыта и оставить на среднем огне, периодически помешивая, на 15-50 мин. Сливки должны выпариться примерно на половину и загустеть',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (204,'Выключить огонь, посолить и поперчить печень по вкусу, выдавить зубчик чеснока, все перемешать и оставить остывать',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (204,'Остывшую печень вместе с соусом выложить в чашу блендера, добавить оставшееся сливочное масло и перемолоть до состояния мусса',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (204,'Получившийся паштет выложить в прямоугольную форму (в рецепте силиконовая 10х20х6 см), разровнять поверхность, потрясти форму, чтобы убрать пустоты и поставить для застывания в морозильник на 3 часа или в холодильник на ночь',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (205,'Порезать орехи ножом на средние куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (205,'Положить в кастрюльку сахар, налить воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (205,'Готовить на тихом огне, пока сироп чуть-чуть не загустеет и не станет слегка золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (205,'Добавить лимонный сок, чтобы грильяж не был стекловидным, размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (205,'Насыпать орехи, размешать при помощи ложки, чтобы сироп полностью обволакивал орехи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (205,'Используя ложку, сформировать средние шарики, положить на тарелку, намазанную сливочным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (205,'Грильяж не будет прилипать, если обмакивать ложку в емкость с холодной водой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (205,'Позволить минут двадцать постоять, чтобы застыл.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (205,'Растопить на водяной бане шоколад.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (205,'Взять шарики грильяжа, окунуть в шоколад, положить на поверхность, намазанную маслом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (205,'Отправить в прохладное место, чтобы домашний грильяж из грецких орехов в шоколаде полностью застыл.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (206,'Взять мягкий и спелый банан, очистить и поломать его на кусочки. Размять творог ложкой или вилкой, соединить с бананом, измельчить массу в блендере до пюреобразного состояния. Размолоть, также в блендере, геркулесовые хлопья, мелко, в муку. Добавить жидкий мед и растопленное сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (206,'Замесить тесто, остудить в течение часа в холодильнике. Сформовать небольшие комочки-шарики, руки обмакивать в воду, иначе тесто будет прилипать. Выложить на пергамент, печь мягкое банановое печенье в духовке на противне в течение 25 – 30 минут при 180 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (207,'Малину (разморозить) смешать с маслом растительным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (207,'Добавить уксус винный, соль, мед, горчицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (207,'Все взбить в блендере примерно до загустения (25 сек). Соус готов и можно заправлять салат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (208,'Примерно в равных количествах нарезать на мелкие кусочки куриное филе и овощи: кабачки, болгарский сладкий перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (208,'Если при нарезании кабачков выделился лишний сок – его лучше отцедить. Натереть твердый сыр. В куриный фарш с овощами и сыром добавить муку и яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (208,'Соль, перец – по вкусу, соль может не понадобиться, некоторые сорта сыра довольно соленые. Сформовать круглые или овальные куриные котлеты, обжарить на растительном масле с двух сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (209,'Для начала смешаем в блендере муку, молоко, яйца, соль и можно добавить ванильный экстракт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (209,'Далее взбиваем до однородной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (209,'Затем разогреваем сковородку и добавляем кусочек сливочного масла. Растапливаем масло так, чтобы оно было по всей сковородке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (209,'Затем на раскалённую сковородку заливаем готовую смесь и отправляем в уже разогретую духовку до 220°C на 18-20 минут. Лучше всего поставить на среднюю или нижнюю полку. В данном случае мы приготовили базовый рецепт, сюда также можно перед тем как отправить в духовку. Добавить ягоды или овощи. Подавать можно с ягодами или посыпать сахарной пудрой .',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (210,'Нарезать лимоны. Сложить в сотейник. Засыпать сахаром. Налить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (210,'Поставить сотейник на средний огонь до закипания. Уменьшить огонь до минимального, кипятить 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (210,'Переложить лимоны и сироп в графин. Оставить остывать до комнатной температуры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (210,'Убрать в холодильник на пару часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (210,'Готовый сироп разбавлять с газированной водой в соотношении 1 к 3. При желании можно добавить мяту и лед. Лимонад готов!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (211,'Разминаем запечённый картофель.','https://vkuso.ru/data/cache/data/52/83c882a1ce0e352_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (211,'Добавляем яйца.','https://vkuso.ru/data/cache/data/92/10ff2b03905e692_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (211,'Добавляем муку.','https://vkuso.ru/data/cache/data/e4/7e27c89e57ef1e4_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (211,'Вымешиваем тесто.','https://vkuso.ru/data/cache/data/8b/5ba5a93d108c88b_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (211,'Формируем ньокки.','https://vkuso.ru/data/cache/data/8d/b3d4b931a95198d_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (211,'Отвариваем в подсоленной воде.','https://vkuso.ru/data/cache/data/0f/1a7d54dbdee000f_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (211,'Нарезаем лук.','https://vkuso.ru/data/cache/data/29/e663cca844f0129_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (211,'Панчетту - брусочками.','https://vkuso.ru/data/cache/data/29/c8cd646734b4c29_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (211,'Обжариваем лук и панчетту.','https://vkuso.ru/data/cache/data/b4/424410482289eb4_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (211,'Соединяем с соусом.','https://vkuso.ru/data/cache/data/43/3ece152cdfa3f43_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Пропустить мясо через мясорубку, обильно посыпать получившийся фарш перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Лук порезать на тоненькие полукольца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Можно использовать не только обыкновенный репчатый лук, но и зеленый, и красный.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Порезать картофель на тоненькие ломтики, или соломкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Кусочки должны быть не сильно крупными, чтобы успели пропечься.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'В данном пироге довольно легкое тесто – хорошенько перемешать все ингредиенты, должна быть сметанообразная масса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Нет необходимости раскатывать и вымешивать тесто.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Для приготовления замечательно подойдет глубокая формочка, ее необходимо заранее смазать растительным маслом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Выложить первый слой: ½ картофеля, хорошенько посыпать солью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'После этого положить слой лука.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Но можно смешать лук и мясо, так получится сочнее и вкусней.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Затем распределить равномерным слоем фарш.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Чтобы было сочно, можно положить сало или просто несколько кусочков сливочного масла.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'После всего этого положить оставшийся картофель, залить получившийся пирог тестом, осторожно разровнять его лопаткой или ложкой.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Когда пирог будет готов, можно перевернуть его, как шарлотку.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Но в этом случае следует посыпать стенки и дно формочки измельченными сухариками.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Выпекать пирог минут семьдесят, соблюдать температуру 180 градусов.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Верх желательно прикрыть фольгой, чтобы пирог не пригорел. Но это зависит от особенностей духовки.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (212,'Порезать заливной пирог с фаршем и картошкой на майонезе на порционные кусочки, осторожно вытащить их из формочки.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (213,'Раскатать круг, чтобы он по диаметру был больше, чем формочка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (213,'Положить в формочку, сделать бортики приблизительно три сантиметра, наколоть вилкой тесто, чтобы не образовывались пузырьки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (213,'Отправить в духовку минут на десять, соблюдать температуру 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (213,'Тесто должно пропечься наполовину.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (213,'Пока готовится тесто, порезать на кубики куриное филе, обжарить на горячей сковороде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (213,'Посыпать солью, специями.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (213,'Порезать соломкой болгарский перец.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (213,'Если используется замороженный шпинат, то его необходимо разморозить в микроволновой печи и расправить по листику.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (213,'Когда тесто пропечется, положить на него филе курицы, на него болгарский перчик, сверху шпинат.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (213,'Взбить яйца, соединить со сливками, посыпать солью. Осторожно залить киш.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (213,'Готовить минут сорок, соблюдать температуру 190 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (213,'В завершение посыпать тертым сыром, держать в духовке, пока не расплавится.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (213,'Если киш с куриным филе, шпинатом и болгарским перцем постоит несколько часов, то становится еще более вкусным.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (214,'Соединить хлеб, куриный бульон Gallina Blanca для второго блюда, фарш, базилик, сыр пармезан, соль, яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (214,'Сформировать несколько фрикаделек, обжарить до полуготовности на масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (214,'В емкости разогреть оливковое масло, минут пять обжаривать баклажаны, лук, цуккини.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (214,'Помешивая, налить чуть-чуть воды, накрыть крышкой, тушить на очень маленьком огне минуты четыре, помешивая время от времени.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (214,'Положить подготовленные томаты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (214,'Фрикадельки тушить до готовности, крышку не открывать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (215,'Подсушить и слегка поджарить орехи на сухой сковороде, удалить шелуху, измельчить удобным способом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (215,'Печенье нарезать на маленькие прямоугольники.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (215,'Смешать орехи с печеньем, добавить цукаты, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (215,'Для крема вареную сгущенку поместить в чашу блендера взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (215,'Добавить масло, еще раз взбить до образования пышной однородной массы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (215,'Объединить крем и смесь печенья с орехами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (215,'Уложить полученную массу для торта из печенья с арахисом и цукатами в салатницу сферической формы, дно которой выстлать пленкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (215,'Края формы должны свисать, для легкого извлечения торта.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (215,'Убрать минимум на три часа в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (265,'Вымыть зелень, подсушить, мелко нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (215,'Достать, вынуть из формы, украсить орехами, мармеладом и жидким шоколадом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (215,'Дать постоять еще полчаса в холоде, для застывания шоколада.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (216,'Взбить творог с яйцами, вручную или с помощью кухонной техники (миксер, блендер). Добавить сгущенное молоко и горошинки ванили из стручков, снова взбить. Ваниль можно заменить той, что продается в пакетиках.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (216,'Формочки для выпечки хорошо смазать растопленным сливочным маслом, выложить массу, печь 50 – 60 минут. Массу выкладывать не до верха, она поднимется в процессе термообработки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (216,'Ванильную запеканку из творога без муки остудить или подать горячей. Порезать на порции. При подаче можно полить растопленным шоколадом или вареньем, кисловатым джемом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (217,'Нарезать лук и грибы, чеснок и каперсы мелко нарубить ножом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (217,'Масло разогреть на сковороде, обжарить лук до мягкости и добавить грибы. К почти готовым грибам закинуть чеснок и снять с огня через 1 минуту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (217,'Смешать в тарелке обжаренные грибы с каперсами и нарезанным укропом. Посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (217,'Куриную грудку разрезать вдоль не дорезая до конца и отбить молотком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (217,'Выложить грибную начинку на отбитое филе и свернуть в рулет плотно обернув каждое филе в пленку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (217,'Опустить в кипящую воду на 8 минут. Затем вынуть, остудить, снять пленку и тонко нарезать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (218,'Мелко нарежьте огурцы, лук и каперсы. Сложите все ингредиенты (кроме сельди и яблока) в миску и перемешайте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (218,'Очистите и мелко нарежьте яблоко и сельдь. Добавьте их в миску ко всем ингредиентам. Перемешайте и оставьте настояться в холодильнике несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (218,'Подавайте с ржаным хлебом, намазанным маслом и посыпьте рубленным зелёным луком и листочками петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (219,'Шоколад и сливочное масло растопить на водяной бане, перемешать до получения гладкой смеси.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (219,'Орехи порубить. Бисквитную крошку и рубленные орехи добавить в миску с шоколадом и маслом, все тщательно перемешать до однородной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (219,'Слепить из приготовленной массы шарики, выложить их в контейнер застеленный пищевой плёнкой и поставить в холодильник на 3-4 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (219,'Приготовить глазурь соединив все ингредиенты и прогрев до однородности и полного растворения сахара. Немного остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (219,'Покрыть шарики тёплое глазурью и убрать в холодильник до застывания глазури.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (220,'Творог размять вилкой, добавить сахар и сметану, массу взбить блендером или вручную. Очистить бананы и киви, консервированные персики, порезать кружочками, а затем сегментами. Залить желатин молоком и дать набухнуть, затем прогреть до растворения, кипятить не нужно. Влить его в творожную массу и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (220,'В форму для выпечки выложить слой подготовленных фруктов, залить творожно-желатиновой массой, снова слой фруктов, чередовать слои до верха формы. Сверху – любой нежирный крем и кокосовая стружка. Охладить легкий десерт из творога с фруктами в холодильнике в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (221,'Филе хека пропускаем через мясорубку вместе с луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (221,'К фаршу добавляем яйцо, солим, перчим, тщательно перемешиваем и добавляем манную крупу. Даем фаршу постоять в холодильнике 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (221,'Формируем котлеты. У меня из указанного количества ингредиентов получилось 10 шт. котлет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (221,'Обжариваем котлеты с 2 сторон на растительном масле до образования золотистой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (221,'Подавать котлеты можно к любому гарниру или салату. Всем вкусного обеда!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (222,'Готовое слоеное тесто разморозить, раскатать и выложить в форму с высокими бортиками (начинки будет много). Тесто наколоть вилкой в нескольких местах. Приготовить начинку, для этого порезать зеленый и лук-репку, натереть сыр. Порезать грибы. Разогреть сливочное масло, добавить лук-репку, обжарить, добавить грибы, соль, перец и еще обжарить. Немного остудить. Размешать яйца со сливками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (236,'Для соуса мелко нашинкованную луковицу обжарить с добавлением сливочного масла до прозрачности в сковороде, где до этого жарилось мясо.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (297,'Нарезать репчатый лук и морковь, по желанию.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (222,'Можно уменьшить калорийность блюда, если взять нежирные сливки или вместо них использовать смесь яиц и молока, как для приготовления омлета. Эту смесь добавить в обжарку с грибами, затем всыпать сыр, рубленый зеленый лук, молотый перец и любые специи для овощей, например, прованские травы, сухой или свежий тимьян. Выложить массу в форму и выпекать 30–40 минут при температуре 180 градусов. Киш Лорен из слоеного теста с грибами и сыром готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (223,'Нашинковать лук, залить маринадом, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (223,'Сварить в подсоленной воде с добавлением лаврового листа, перца горшком и растертого зубчика чеснока филе, дать остыть, не вынимая из бульона, который в дальнейшем пойдет для изготовления желе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (223,'Бульона потребуется не менее 4 стаканов, если получится меньше, то долить кипяченой воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (223,'Параллельно отварить вкрутую яйца, картофель в мундире.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (223,'Салатник со сферическим дном выстлать пленкой, выложить слой из порезанного на мелкие кубики картофеля, далее - хорошо промаринованный лук, промазать майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (223,'Уложить следующий слой из кубиков соленого огурца, на него – порезанное филе, далее  опять промазать майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (223,'Последним слоем будут порубленные яйца, смазанные майонезом, убрать салат в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (223,'Приготовить на курином бульоне желе, процедить его, добавить кусочки желатина, нагреть, помешивая до растворения, но кипения не допускать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (223,'Вылить раствор на дно небольшого противня с высокими бортиками слоем в 1,5 сантиметра, отправить застывать в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (223,'Аккуратно извлечь желе из формы, опустив дно на пару секунд в нагретую воду, на широкий поднос, разрезать на кубики размером по 1,5 сантиметра.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (223,'Осторожно перевернуть форму с хрустальным салатом с куриным филе и картофелем на плоское блюдо, снять пленку, нанести на бока и верх тонкий слой майонеза, обложить со всех сторон кубиками желе.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (224,'Довести до кипения воду (бульон), подсолить, положить небольшие соцветия капусты, проварить после повторного закипания под крышкой минут 8-10 (зависит от размера соцветий) до готовности, но не переваривать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (224,'Пока варится капуста обжарить на масле мелко натертый или пропущенный через пресс чеснок при слабом нагреве.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (224,'Выловить шумовкой капусту, поместить в блендер, залить стаканом бульона, оставшимся от ее варки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (224,'Добавить чеснок с маслом, приправить солью, перцем, влить молоко, разбить в однородное пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (224,'Если пюре получится чересчур густым, то в сливочный соус из цветной капусты с чесноком можно добавить еще овощного бульона или молока.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (225,'Заполнить блендер дольками апельсина, добавить кусочки очищенного имбиря, влить воду, можно по вкусу добавить еще и сахар, тщательно взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (225,'Процедить ядреный апельсиновый фреш с имбирем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (225,'Слегка охладить и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (226,'В чашу миксера всыпать сахар, вбить яйца, взбить в устойчивую пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (226,'Влить молоко, еще раз взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (226,'К сладкой яично-молочной массе добавить смесь муки (просеянной) с порошком какао, хорошо взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (226,'Всыпать в массу корицу, чуть соли, разрыхлитель, взбить в однородную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (226,'Влить масло и последний раз вымешать тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (226,'Выпекать шоколадные панкейки на молоке с корицей на хорошо разогретой сухой сковороде, как обычные оладьи с двух сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (226,'Готовую выпечку выложить на плоское блюдо, присыпать корицей.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (227,'Натереть сочную морковку на специальной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (227,'Положить в глубокую миску, всыпать соль, кориандр, сахар, перец, раздавить чеснок, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (227,'Влить масло с уксусом, еще раз тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (227,'Убрать морковь по-корейски с кориандром и яблочным уксусом на ночь в холодильник, и утром прекрасная закуска или гарнир к мясу будет готова.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (236,'Всыпать ложку муки, хорошо перемешать, долить молоко, помешивая варить, пока не загустеет соус, присолить, поперчить, размешать.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (673,'Время выпекания – полчаса.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (228,'Взбить вместе вручную, или с помощью кухонной техники (миксер, блендер), нарубленные грецкие орехи с сахаром, мягким сливочным маслом и мукой. Вместо грецких орехов можно взять менее распространенные пеканы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (228,'Форму для запекания смазать растопленным сливочным маслом, выложить массу, хорошо утрамбовать и выпечь в течение 20 минут при температуре 175 градусов. Приготовить ванильный и шоколадный пудинги из продающихся в магазине полуфабрикатов. Готовить на молоке, в соответствии с инструкциями на упаковке продуктов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (228,'Начинка: взбить миксером сливочный сыр со сливками и сахарной пудрой. Крем должен стать легким и воздушным.  Отдельно взбить сливки для украшения и натереть шоколад. На остывшую основу выложить слой со сливочным сыром, затем поочередно: готовый ванильный и шоколадный пудинг. Украсить оригинальный десерт «Секс в сковороде» взбитыми сливками, посыпать тертым шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (229,'Порезать очищенный имбирь на тонкие ломтики, перемешать с сахаром, дать постоять пару часов для выделения сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (229,'За это время очищенные яблоки порезать на дольки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (229,'Переложить имбирь в кастрюлю с толстым дном, влить три стакана воды, добавить сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (229,'Варить как обычное варенье, добавить яблоки, проварить осеннее яблочно-имбирное повидло еще полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (229,'Пюрировать полученную массу блендером до однородности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (230,'Взбить цельные яйца с обычным и ванильным сахаром, добавить кусочки маргарина, влить кефир и растительное масло, взбить все вместе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (230,'Всыпать к кефирно-яичной массе просеянную муку, взбить до получения однородного теста, похожего на крем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (230,'Заполнить тестом подготовленную форму, разложить равномерным слоем ягоды вишни (отверстиями от черешков вверх, чтобы сок не вытек).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (230,'Отправить вишневый пирог "Нежный" на кефире примерно на 45 минут в заранее прогретую до 190 градусов духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (231,'В глубокой миске соединить сахар, ванильный сахар, какао порошок, растворимый кофе (по желанию), соль и растительное масло, хорошо перемешать венчиком.','https://vkuso.ru/data/cache/data/74/b919e6122971074_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (231,'Ввести в смесь строго по одному 3 яйца, после каждого введения взбивать миксером по 1 мин. Можно использовать венчик, тогда взбивать придется чуть дольше.','https://vkuso.ru/data/cache/data/c5/ddcad010f328cc5_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (231,'Ввести в смесь просеянную муку и разрыхлитель.','https://vkuso.ru/data/cache/data/d2/aad1fcc65a8c0d2_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (231,'Все еще раз взбить миксером или венчиком. Смесь получается достаточно жидкой и вязкой.','https://vkuso.ru/data/cache/data/88/3d101662ef65588_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (231,'Накрыть миску пленкой, прижав ее непосредственно к смеси и убрать в морозилку на 35-40 мин. За это время смесь затвердеет и загустеет.','https://vkuso.ru/data/cache/data/d7/da482df05064cd7_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (231,'Из застывшей смеси сформировать печенье руками. На каждое печенье уходит примерно 1 ст л смеси.','https://vkuso.ru/data/cache/data/68/c962fae953f7068_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (231,'Обвалять его в сахарной пудре.','https://vkuso.ru/data/cache/data/f2/0301157611613f2_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (231,'Выложить печенье на противень, застеленный бумагой для запекания, на достаточном расстоянии друг от друга, учитывая, что при выпечке печенье увеличится в размере примерно в 2 раза.','https://vkuso.ru/data/cache/data/40/e6a6c9b0b5e1940_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (231,'Выпекать печенье в заранее разогретой духовке около 15 мин при 180°С до готовности.','https://vkuso.ru/data/cache/data/6b/48f433be71e986b_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (231,'Готовность проверить зубочисткой. Она должна оставаться сухой.','https://vkuso.ru/data/cache/data/7a/b1103c6546c667a_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (231,'Учитывайте особенности своей духовки и что печенье за время остывания еще немного дойдет естественным образом.','https://vkuso.ru/data/cache/data/a1/077d55317dafea1_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (231,'Хранить печенье в плотно закрытой ёмкости, чтобы оно не засыхало на воздухе.','https://vkuso.ru/data/cache/data/f1/ea6bf8a431416f1_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (232,'Натереть на терке две пачки сыра «Дружба».  Лучше это сделать на крупной терке. Несколько стручков разноцветного сладкого перца нарезать мелкими кубиками. Порубить чеснок. Все ингредиенты перемешать, добавить майонез.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (236,'Достать пирог, дать немного остыть, порезать очень острым ножом, подать с соусом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1560,'Порубить зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (232,'Выложить готовую начинку в тарталетки овальной формы, в виде «лодочек». Украсить половинками тонко нарезанных кружков лайма в виде «парусов». Очень острую закуску в тарталетках лучше выложить на листья свежего зеленого салата, украсить веточками укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (233,'Нарежьте шампиньоны и лук кубиками. Чеснок мелко нарубите.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (233,'В сковороду добавьте растительное и сливочное масло. Обжарьте лук и чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (233,'Добавьте грибы и слегка посолите, готовьте 5-7 мин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (233,'Добавьте гречку и воду. Добавьте соль и перец, накройте крышкой и готовьте 25-30 мин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (234,'Натереть сыр чеддер на крупной терке. Моцареллу мелко нарезать. Поставить вариться макароны до состояния аль денте. ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (234,'В другой кастрюле приготовить сырный соус. Добавить сливочное масло в разогретую кастрюлю и ждать, пока оно полностью растопится. Далее добавить муку и хорошо перемешать, немного обжарить на среднем огне, 1-2 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (234,'Добавить молоко и перемешивать, пока мука не растворится. Варить 2-3 минут, пока молоко не загустеет. Добавить чеддер и моцареллу, перемешивать, пока сыр полностью не растворится (2-3 минуты). Соус готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (234,'Отваренные макароны откинуть на дуршлаг и добавить к соусу. Хорошо перемешать. Мак энд чиз готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (234,'Выложить мак энд чиз на круглую форму диаметром 30 см. Это будет основой для пиццы. Запекать в духовке, разогретой до 200°С, 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (234,'Приготовить томатный соус. Поставить сотейник на средний огонь. Добавить томатное пюре, орегано, базилик, сахар, чили перец, соль.Тушить 10 минут, пока не загустеет.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (234,'Когда прошло 20 минут, достать основу для пиццы и перевернуть на другую сторону.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (234,'Нанести на основу томатный соус. Посыпать сыром чеддер. Выложить моцареллу и нарезанную колбасу. Отправить в духовку еще на 10 минут. Мак энд чиз пицца готова! Приятного аппетита! Больше кушайте, никого не слушайте!',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (235,'Взбить растаявшее сливочное масло с сахаром добела. Добавить сырое яйцо, еще немного взбить, всыпать просеянную муку, замесить тесто. Готовый «колобок» завернуть в полиэтилен, охладить в холодильнике в течение часа. Приготовить начинку. Для этого протереть творог через сито, он должен быть пастообразным, без комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (235,'Добавить в массу сахар, ванилин из пакетика, сметану, яйцо и крахмал. Ингредиенты вмешивать постепенно, с помощью миксера или вручную. Масса должна получиться однородной. Взять разъемную форму диаметром около 20 см, смазать растопленным сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (235,'Раскатать в корж тесто из холодильника, выложить в форму так, чтобы получился бортик высотой в несколько сантиметров. Выложить начинку – творожный крем и половинки консервированных абрикосов. Печь пирог с творожным кремом и абрикосами в течение 30 – 40 минут. Выпечку остудить, не вынимая из выключенной духовки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (236,'Подготовить мясо, вымыть, зачистить от пленок, обсушить бумажным полотенцем, можно обвязать для сохранения формы шпагатом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (236,'В хорошо разогретой сковороде с маслом обжарить кусок мяса равномерно со всех сторон до корочки золотисто-коричневого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (236,'Переложить на блюдо, присолить, присыпать прямо из мельнички крупно раздробленным перцем, дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (236,'При среднем нагреве распустить в сковороде сливочное масло с добавлением растительного, обжарить пластинки шампиньонов и лук до изменения цвета на золотистый, сдобрить солью и перцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (236,'Переложить грибную массу в блендер, измельчить, но не в кашу, дать остыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (236,'Раскатать на припушенном мукой столе тесто в 5 миллиметровый пласт.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (236,'По центру разложить грибы, поверх уложить мясо, прикрыть остатками грибной пасты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (236,'Разболтать вилкой яйцо, промазать края теста, тщательно защипать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (236,'Выстлать пергаментом противень, обсыпать мукой или манкой, выложить обернутую тестом говядину «Веллингтон» с шампиньонами в слоеном тесте на противень швом вниз, смазать остатками яйца.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (236,'Задвинуть в прогретую чуть ниже 195 градусов духовку, ориентировочно минут на 40-45.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1575,'Измельчить в крошку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (237,'Поломать на кусочки плитку шоколада, всыпать в хорошо разогретые сливки, перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (237,'Добавить сливочное масло, перемешать, дать остыть и поставить в холодильник на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (237,'Достать, взбить с помощью миксера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (237,'Фисташки порубить ножом в крошку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (237,'Чуть смочить руки, массу скатать в шарики, убрать шоколадно-сливочные конфеты с фисташками в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (237,'Достать конфеты, часть обвалять в орехах (стружке кокоса, вафлях), другую – в порошке какао и оформить целым орешком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (238,'Сырки заморозить, натереть вместе с обычным сыром и маслом на терке с крупными отверстиями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (238,'К сырной массе прибавить взбитые подсоленные яйца, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (238,'Всыпать муку и разрыхлитель, замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (238,'Раскатать его в пласт примерно в полсантиметра толщиной, промазать разболтанным яйцом, присыпать семечками кунжута, разрезать на кусочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (238,'Переложить печенье с плавленым и твердым сыром на противень, выпекать около трети часа при температуре духовки порядка 190 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (239,'Яйца, желательно охлажденные, взбить удобным способом в массу белого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (239,'Масло распустить и остудить, объединить с яйцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (239,'Просеять, перемешанную с разрыхлителем, муку, всыпать измельченную цедру, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (239,'Подготовить форму, переложить тесто, разровнять, готовить полчаса в духовке с температурой в 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (239,'Заняться приготовлением крема, смешать половину стакана апельсинового сока с сахаром, цедрой, нагреть, помешивая до полного растворения сахара.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (239,'Для сгущения крема в небольшой миске перемешать хорошо крахмал и муку, влить порциями, помешивая сок, чтобы комки исчезли.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (239,'Полученный загуститель вылить в сок, перемешать и поставить опять нагреваться (постоянно мешать!) до увеличения густоты, дать крему остыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (239,'Холодный готовый корж разделить на два, каждый смазать теплым кремом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (239,'Верх простой бисквитный торт с апельсиновым кремом оформить сахарной пудрой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (239,'Убрать его до сгущения крема в холодильник.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (240,'Включить для прогрева духовку (примерно до 170 градусов).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (240,'Размягченное масло соединить с сахаром, взбить в гомогенную массу, добавить творог без крупинок, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (240,'Полученную массу перемешать с соком и цедрой лайма, добавить эссенцию ванили, еще раз очень хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (240,'К полученной смеси по одному вмешать все яйца, всыпать муку из миндаля, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (240,'Разрыхлитель, смешанный с мукой, просеять, объединить с яичной смесью, очень тщательно вымешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (240,'Приготовить форму, промазать маслом, притрусить манкой, ссыпать излишки, заполнить тестом, периодически добавляя немного ягод.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (240,'Верхушку творожно-миндального кекса с голубикой присыпать слегка сахаром (коричневым) для получения на готовом изделии аппетитной корочки из карамелезированного сахара.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (240,'Выпекать десерт примерно час.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (241,'Очистить некрупный картофель и нарезать кружками толщиной  5 мм. Отдельно довести до кипения сливки, немного посолить по вкусу и всыпать картофель. Довести до кипения и варить на тихом огне пять минут. Снять с огня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (241,'Натереть сыр на крупной терке (можно «Гауда» или аналогичный). В форму для запекания выложить картофель и сыр слоями, снизу и сверху должен быть картофель, оставить немного сыра для украшения. Залить слоеную запеканку сливками, закрыть форму фольгой. Печь при температуре 180 градусов в течение 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (241,'Фольгу снять, посыпать остатками сыра и печь еще 10 – 15 минут, до расплавления сыра и образования аппетитной золотистой корочки. Подать картофель по-французски с сыром и сливками в форме, в которой картофель запекался. Можно украсить зеленью петрушки, укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (242,'Отварить куриные яйца, очистить, нарезать. Куриное филе отварить со специями, охладить и нарезать кусочками средней величины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (265,'Оттаявшее филе промыть, нарезать на более мелкие куски.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (242,'Нарезать мелкой соломкой ветчину. Лук-репку нарезать тонкими полукольцами и обдать кипятком для удаления излишней горечи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (242,'Все ингредиенты соединить, добавить маринованные опята, их можно не резать, если они мелкие. Часть грибов оставить для оформления. Салат «Мужская мечта» залить майонезом, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (243,'Очистите от шелухи и мелко порежьте репчатый лук, разогрейте на сковороде столовую ложку растительного масла и, выложив лук, обжарьте, постоянно перемешивая, до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (243,'Залейте лук вином и уксусом, перемешайте, добавьте эстрагон, перец горошком и прочие специи, обжаривая пятнадцать-двадцать минут до тех пор, пока количество жидкости не испарится наполовину. Не забываете постоянно помешивать, потому что иначе, лук пригорит, и соус будет испорчен.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (243,'Отделите желтки от белков, добавьте к ним соли, взбейте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (243,'Снимите с огня смесь и влейте к яйцам, постоянно помешивая, чтоб желтки не свернулись.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (243,'Поставьте получившуюся смесь на водяную баню и, продолжая помешивать, постепенно добавьте растопленное сливочное масло. Перемешивайте смесь на водяной бане до тех пор, пока по консистенции она не станет похожа на сливки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (243,'Добавьте красный молотый перец и мелко порезанный болгарский перец. (Можно заменить сушенным болгарским перцем в виде приправы).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (243,'Остудите соус и подавайте к столу. Лучше всего соус «Беарнский» подойдет к рыбным блюдам.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (244,'Приготовить бисквитное тесто. Для этого взбить белки сырых яиц в крепкую, устойчивую пену. Можно добавить щепотку соли, это ускорит процесс. Желтки растереть добела с  коричневым сахаром. Добавить в желтковую массу просеянные муку и какао, перемешать, добавить третью часть взбитых белков и аккуратно перемешать. Затем добавлять порциями оставшиеся белки, перемешивать сверху вниз, осторожно, масса должна остаться пышной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (244,'Смазать маслом разъемную форму для выпечки, вылить полужидкое бисквитное тесто, печь корж при 180 градусах в течение 40 минут. Проверить готовность можно зубочисткой, она должна остаться сухой и без комочков сырого теста. Остудить выпечку в форме, вынуть из формы. Если верх получился не очень ровным – срезать бугорки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (244,'Приготовить мусс. Замочить желатин в холодной воде для набухания. Взбить сливки с сахаром до образования устойчивой пены. Перемолоть свежую клубнику в блендере до пюреобразного состояния, добавить сахар, перемешать. Желатин прогреть на водяной бане, можно воспользоваться микроволновкой. Разделить массу пополам, одну часть добавить в сливки, другую – в клубничное пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (244,'Корж вернуть в форму, сливочно-желатиновую и клубничную смесь выкладывать ложкой, слоями, попеременно. Охладить в холодильнике в течение нескольких часов до полного застывания.  Подать бисквитный торт со сливочно-клубничным муссом, порезав на порции. Украсить половинками свежих ягод клубники, тертым шоколадом или орехами, например, миндалем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (245,'Приготовить крем. Взбить сырые яйца вилкой или венчиком. Отдельно смешать сахар, щепотку соли и крахмал, постепенно влить молоко, размешать и прогреть на среднем огне. Смесь должна загустеть. Довести до кипения, дать покипеть около минуты. Добавить две столовые ложки этой крахмальной смеси в яйца, быстро перемешать, не давая яйцам свернуться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (245,'Перелить яичную смесь обратно в кастрюлю, дать покипеть на тихом огне еще одну минуту. Помешивать. Снять яичную смесь с огня, добавить ванилин и растопленное сливочное масло, перемешать и остудить. Затем поставить кастрюлю в холодильник до полного охлаждения, лучше прикрыть массу пищевой пленкой, чтобы не образовалась корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (245,'Печенье или несоленые крекеры растолочь, лучше это делать в пластиковом пакете, чтобы крошки не разлетались по кухне. Добавить сахар и растопленное сливочное масло. Выложить на противень в виде плотного ровного слоя, печь 10 – 12 минут при температуре 175 градусов. Остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (251,'Берем банку и наливаем в нее воды, ставим банку на жаропрочную сковородку. Курицу помещаем на банку так чтобы она устойчиво сидела.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (265,'Выложить рыбу на дно формы, посыпать солью, перцем, сушеной зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1669,'Массу хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (245,'Выложить бананово-карамельный десерт в креманки. Первый слой – испеченная крошка, утрамбовать с помощью рюмки или придавить пестиком. Второй слой – охлажденный крем, третий – кружки спелого банана, слой взбитых сливок. Затем насыпать еще немного крошек, сбрызнуть карамельным соусом (готовым). Повторить все слои еще раз. Подать десерт можно сразу или дать постоять в холодильнике 2–3 часа, при подаче украсить бананом, листочком свежей мяты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (246,'Мясо хорошо вымыть, обсушить бумажными полотенцами, нарезать ломтиками, соль, перец – по вкусу. Натереть на крупной терке картофель. Порезать лук-репку кольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (246,'Нарезать помидоры кружками, затем каждый разрезать на две части, намазать майонезом. Натереть твердый сыр на крупной терке. Порубить зелень, чеснок пропустить через чеснокодавку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (246,'Противень смазать маслом, выложить мясо, затем лук, картофель, помидоры. Верх запеканки еще немного смазать майонезом. Печь в течение 40 – 50 минут при температуре 200 – 220 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (246,'Незадолго до окончания приготовления (за 5 – 10 минут) смазать свинину под шубой с помидорами давленым чесноком, посыпать сыром и зеленью. Допечь в духовке до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (247,'Куриное филе порезать на мелкие кусочки в 1,5 см толщиной. Приготовить маринад из майонеза, черного молотого перца, соли, лимонного сока. Подержать куриное мясо в маринаде 30 – 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (247,'Лук-репку нарезать полукольцами. Нарезать кружками некрупный картофель, натереть по отдельности сыр и морковь.  Смазать маслом форму для запекания, первый слой – курица.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (247,'Затем выложить лук, морковь, картофель. Верх посолить, смазать майонезом, посыпать тертым сыром. Печь куриное филе под картофельной шубой при температуре 180 градусов в течение 30 – 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (248,'Подтаявшее сливочное масло смешать с рубленой зеленью.  Разделить массу на четыре части и охладить в холодильнике. Куриные грудки разделить на большое и малое филе, посередине сделать продольные надрезы, развернуть и отбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (248,'Соль, перец – по вкусу, натереть мясо. На большое филе положить кусочек масла с зеленью из холодильника, накрыть малым филе, завернуть. Положить в посуду или на доску котлеты швами вниз и убрать в морозильную камеру на 10 – 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (248,'Сырое куриное яйцо взбить с молоком, обмакнуть в смесь котлеты из морозилки. Обвалять в муке, снова обмакнуть в яично-молочную смесь, обвалять в панировочных сухарях. Всю процедуру повторить сначала.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (248,'Обжарить домашние котлеты по-киевски в панировке на большом количестве разогретого растительного масла. Котлеты должны быть в него погружены наполовину. Обжарить с двух сторон, сначала ту сторону, где «шов». Допечь на противне при температуре 200 градусов в течение 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (249,'В любой мясной фарш (или смесь фаршей) добавить лук, чеснок, сырое яйцо. Соль, перец – по вкусу. Затем добавить готовый отваренный рис, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (249,'Сформовать шарики, лучше это делать мокрыми руками, чтобы масса не прилипала. Выложить «ёжики» на противень в шахматном порядке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (249,'Картофель нарезать средними кусочками, заполнить ими свободные места между мясными шариками. Посыпать мясные ежики с картофелем тертым сыром, печь 30 – 40 минут при 190 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (250,'Наливаем в кастрюлю воды для варки. Затем доводим до кипения и солим.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (250,'Выкладываем пастернак в кастрюлю. Доводим до кипения и варим примерно 25 мин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (250,'Оставляем 1-2 стакана бульона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (250,'Перекладываем пастернак в блендер и смешиваем до консистенции пюре с добавлением бульона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (250,'Перекладываем пюре обратно в кастрюлю и добавляем масла и соли по вкусу. Пробуем и сервируем. Приятного аппетита!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (251,'Сначала приготовим маринад. Он состоит из мелко нарезанного чеснока, трав (специи по вкусу), сметаны и перца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (251,'Посолим курицу целиком снаружи и внутри.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (251,'Затем наносим маринад, хорошо покрывая все поверхности и внутри курицы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (251,'Ставим курицу в холодильник на 2 часа впитывать маринад.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (264,'Выложить филе мойвы, спинки должны быть внизу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (346,'Очистить чеснок, пропустить через пресс.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (251,'Затем разогреваем духовку до 200 градусов и отправляем курицу запекаться.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (252,'Отжать апельсиновый сок, отдельно – лимонный.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (252,'Перемешать, добавить молотый перец и соль, немного зерновой горчицы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (252,'Если маринад окажется сладким – добавить еще немного лимонного сока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (252,'Промыть мойву, удалить головы, хвосты, плавники, почистить брюшки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (252,'Красный лук очистить от кожуры, нарезать полукольцами, выложить в маринад.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (252,'Замариновать рыбное филе на полчаса, помешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (252,'Выложить рыбу внахлест в виде солнца на тарелку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (252,'Полить маринадом, украсить маринованным луком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (253,'Добавляем в казан 150 грамм растительного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (253,'Добавляем морковь и обжариваем 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (253,'Добавляем картофель и обжариваем 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (253,'Добавляем свеклу и обжариваем 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (253,'Добавляем квашеную капусту, фасоль, соль, черный молотый перец, красный острый и тушим всё вместе 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (254,'Приготовить фарш из любого мяса с луком-репкой. Можно взять смесь нескольких мясных фаршей. Добавить сырое яйцо и размоченную в молоке или воде черствую булочку. Соль, перец, прованские или любые другие сухие травы – по вкусу. Смочить руки и сформовать небольшие котлеты, панировать в муке, обжарить с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (254,'Порубить чеснок и зеленый укроп, добавить в плавленый сыр. Не возбраняется, если сыр будет с какими-либо вкусовыми добавками (грибы, бекон). Выложить массу в сковороду с котлетами, долить немного воды и тушить котлеты из мясного фарша в сырном соусе до готовности в духовке или на плите под крышкой. В конце тушения можно немного загустить соус мукой, если он остался жидковатым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (255,'Для начала нарежем спаржу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (255,'Растопим сливочное масло в кастрюле и отправим туда спаржу, затем туда же добавим муку, слегка обжарим и зальем бульон, посоли, поперчи и оставим на среднем огне на 25–30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (255,'После выключаем и взбиваем блендером, заливаем сливки и перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (255,'Можно обжарить вершки на гриле или на сковородке и подавать с супом виде украшения а также можно добавить немного гренок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (256,'Мясо (говядину или баранину) нарезать небольшими кусочками. Нарезать кубиками морковь и картофель в равных пропорциях, нашинковать лук-репку, порубить несколько зубчиков чеснока. Нарезать сладкий перец, семечки можно не удалять. В казане или толстостенной кастрюле обжарить мясо на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (256,'К мясу добавить рубленый лук, обжарить вместе. Затем положить остальные ингредиенты, продолжать обжаривать, постоянно помешивая. Лапшу отварить отдельно в подсоленной воде, откинуть на дуршлаг, ломать ее не нужно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (256,'Разложить в глубокие тарелки лапшу, залить мясной подливой с овощами. Если блюдо окажется слишком густым, можно долить мясной бульон. Готовый сытный узбекский лагман посыпать рубленой зеленью петрушки, кинзы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (257,'Натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (257,'Раскатать тесто в одном направлении.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (257,'Посыпать сыром (60 г) одну половину теста, второй половиной накрыть сверху.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (257,'Еще раз раскатать. Выложить бекон, посыпать сыром (60 г).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (257,'Свернуть тесто в колбаску. Нарезать ее на шайбы шириной по 3 см.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (257,'Выложить на противень. Смазать яйцом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (257,'Выпекать в духовке, разогретой до 180°С 20 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (257,'Синнабоны с беконом и сыром готовы!',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (258,'Чистим, потрошим, моем карасей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (258,'Делаем надрезы на спинке карасей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (258,'Маринад. Смешиваем соль,черный молотый перец, красный острый перец и растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (258,'Смазываем карасей маринадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (258,'Жарим на углях по 5 минут с каждой стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (258,'Смазываем карасей маслом, чесноком и зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (258,'Жарим ещё по 2 минуты с каждой стороны.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (264,'Тушить блюдо под крышкой в течение десяти или пятнадцати минут, огонь – слабый.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (259,'Желатин залить холодной водой и дать набухнуть, затем немного прогреть до полного растворения. Остудить, добавить в сметану с сахаром, хорошо перемешать, до состояния однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (259,'В форму вылить половину полученной смеси. Фрукты можно использовать любые: бананы, мандарины, киви, груши. Их нужно почистить и порезать произвольными кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (259,'Выложить в желеобразную смесь и залить оставшейся массой. Диетический сметанный десерт с фруктами поставить в холодильник до полного остывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (260,'Морковь и лук нарезать мелким кубиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (260,'В кастрюле разогреть сливочное масло, отправить нарезанную морковь с луком, добавить хариссу. Готовить на среднем огне 10 минут, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (260,'Помидоры очистить от кожицы, нарезать мелким кубиком, отправить в кастрюлю, добавить фасоль. Залить водой, довести до кипения, варить 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (260,'Спустя 20 минут засыпать макароны и сыр натертый на мелкой терке. Перемешать и готовить еще 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (261,'Готовим тесто. В миску отправить сметану, майонез, сахар, соль и разрыхлитель. Тщательно перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (261,'Всыпать муку и снова перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (261,'Готовим начинку. Лук очистить и нарезать мелким кубиком, залить яблочным уксусом и оставить на 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (261,'С рыбных консерв слить масло и размять рыбу вилкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (261,'Укроп мелко нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (261,'Яйца отварить вкрутую, очистить и нарезать кубиком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (261,'Маленькую форму для выпечки застелить бумагой для выпечки и смазать растительным маслом. Вылить половину тесто на дно, затем выложить начинку: сначала рыбу, затем лук, яйца, укроп.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (261,'Залить второй половиной теста. Пирог посыпать кунжутом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (261,'Разогреваем духовку до 200 градусов. Выпекаем пирог 25 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (262,'Мясо нарезать как можно тоньше (у меня кусочки толщиной 3-4 мм).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (262,'Разогреть на сковороде растительное масло и обжарить мясо с двух сторон на сильном огне в течении 2 минут для каждой стороны. Сложить мясо в тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (262,'Репчатый лук очистить и нарезать четвертькольцами, шампиньоны разрезать пополам и нарезать слайсами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (262,'В сковороде, где жарилось мясо, обжариваем репчатый лук на сильном огне 3 минуты перемешивая, добавляем шампиньоны и готовим на сильном огне 10 минут, перемешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (262,'Добавить сметану и горчицу, перемешать и прогреть 2 минут на медленном огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (262,'Картофель очистить, нарезать соломкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (262,'В чистой сковороде раскалить растительное масло, обжарить картофель на сильном огне до золотистого цвета, перемешивая.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (262,'Добавить к картофелю грибы с луком, мясо, соль и перец – перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (262,'Выложить на противень или в форму скоблянку (если у вас есть чугунная сковорода выкладываем на нее).',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (262,'Разогреваем духовку до 200 градусов и ставим запекаться скоблянку на 20 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (263,'Яйцо взбить с сахаром. Добавить соль, соду и сливочное масло – снова взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (263,'Всыпать муку и замесить тесто. Убрать в морозильную камеру на 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (263,'Спустя 30 минут разогреваем духовку до 200 градусов. Противень посыпать мукой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (263,'Достать тесто из морозильной камеры и пропустить его через мясорубку. Отрывать тесто в зависимости от размера печенья.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (263,'Готовим печенья до золотистого цвета, около 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (264,'Разморозить рыбу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (264,'Удалить все лишнее: плавники, головы, внутренности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (264,'Филе промыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (264,'Очистить репчатый лук, нарезать кубиками, обжарить на растительном масле до прозрачности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (264,'Промыть морковь, корнеплод очистить и натереть, добавить в луковую обжарку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (264,'Прогреть все вместе, соль и перец молотый – по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (264,'Положить лавровый лист, добавить томатную пасту, немного сахарного песка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (264,'Приготовить соус.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (264,'В теплой воде развести пшеничную муку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (264,'Влить в сковороду с овощами, содержимое перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (265,'Вымыть помидоры, удалить плодоножки, мякоть нарезать кружками, выложить поверх рыбы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (265,'Полить блюдо сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (265,'Густой продукт лучше разбавить водой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (265,'Всыпать зелень.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (265,'Твердый сыр натереть на терке, посыпать рыбу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (265,'Время запекания – от двадцати до двадцати пяти минут, температура – 200 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (266,'Замочить желатин в кипяченой воде. Когда набухнет – поставить на огонь и прогреть до кипения. Вымыть апельсины, разрезать пополам. Мякоть  удалить ножом так, чтобы не повредить кожуру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (266,'Из полученной мякоти отжать сок, процедить. Мякоть не выбрасывать. Приготовить отвар: влить в кастрюлю стакан воду, всыпать сахар, положить отжатую мякоть апельсина. Дать закипеть, через пять минут жидкость отцедить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (266,'Смешать отвар и желатиновую массу, долить апельсиновый сок, перемешать. Кожуру апельсинов наполнить полученной смесью, дать застыть в холодильнике (на нижней полке). Подать, порезав красочное желе в апельсинах на дольки вместе с кожурой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Филе тилапии разморозить, промыть и отбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Очистить репчатый лук, нарезать мелкими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Разогреть на сковороде сливочное масло, лук обжарить до получения золотистого оттенка, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Выложить сырые куриные яйца в емкость, залить холодной водой, поставить на огонь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Время варки – семь минут, охладить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Яйца остудить, очистить от скорлупы, натереть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Перемешать луковую обжарку с яйцами и панировочными сухарями.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Соль и перец – по вкусу, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Выложить ложку начинки в кусочек рыбного филе, свернуть в виде рулета, затем обернуть полосками бекона.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Готовые зразы выложить в форму для запекания, посыпать приправами по вкусу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Время выпекания – двадцать или двадцать пять минут, температура – 200 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Вымыть пекинскую капусту, снять верхние листья, овощ нарезать крупной соломкой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Вымыть зелень, огурцы и помидоры, нарезать произвольными кусочками.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Салат заправить лимонным соком и оливковым маслом, соль – по вкусу.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Рулеты выложить на тарелку, полить бальзамическим уксусом.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (267,'Выложить рядом салат.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (268,'Разморозить телапию при комнатной температуре, промыть, нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (268,'Продукт посолить, выложить в чашу мультиварки, готовить на пару. Либо использовать обычную пароварку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (268,'Время приготовления – от пятнадцати до двадцати минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (268,'Куски рыбы выложить на блюдо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (268,'Вымыть помидоры черри, разрезать пополам, выложить к рыбе вместе с салатом «Мангольд».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (268,'Блюдо побрызгать оливковым маслом, апельсиновым соком и бальзамическим уксусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (269,'Размягченное сливочное масло взбить с сахаром венчиком или в миксере. Добавить сырое яйцо, цедру лимона, ванилин из пакетика. Перемешать. Отдельно смешать муку с содой и солью, просеять. Смешать с масляной смесью, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (269,'Выложить тесто в смазанную форму в виде лепешки средней толщины. Печь 10 – 12 минут. Остудить. Приготовить начинку-крем, для этого смешать сливочный сыр, сахар, сахарную пудру, лимонный сок, лимонную цедру. Взбить массу до воздушности и намазать равномерно на остывшую лепешку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (269,'Очистить и нарезать фрукты: киви, персик. Клубнику нарезать половинками, чернику перебрать и промыть. Фрукты и ягоды выложить на крем в любом порядке, например, концентрическими кругами. Поставить сладкую пиццу с фруктами и ягодами в холодильник для охлаждения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (270,'Приготовить тесто для бисквита, для этого взбить в пену яйца до пышности, добавить сахар, ванилин из пакетика. В смесь влить молоко, растительное масло, перемешать. Просеять муку вместе с разрыхлителем и какао-порошком. Вмешать в молочно-яичную смесь порциями, продолжая взбивать вручную или миксером. Смазать форму маслом и вылить массу. Печь в течение часа при температуре 180 градусов до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1766,'Тушить под крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (270,'Приготовить крем: взбить размягченное сливочное масло со сгущенным молоком, добавить растопленный на водяной бане шоколад любого сорта, кто какой любит. Корж остудить и разрезать горизонтально на 3 или 4 части. Для этого понадобится острый длинный нож или специальное приспособление для разрезания коржей. Каждую часть смазать кремом и сложить вместе, дать торту «Шоколадное кухэ» с кремом из сгущенки постоять, пропитаться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (271,'Картофельные клубни вымыть, завернуть в фольгу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (271,'Запечь до полной готовности в духовом шкафу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (271,'Продукт очистить от кожуры, превратить в пюре вручную или при помощи блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (271,'Добавить муку, соль, тертый сыр, мускатный орех, сырой яичный белок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (271,'Приготовить густое тесто, масса не должна прилипать к рукам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (271,'Приготовить длинные тонкие колбаски, диаметр – два сантиметра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (271,'Разрезать на кусочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (271,'По каждому кусочку теста провести вилкой, чтобы получились рельефные полоски.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (271,'Опустить ньокки в кипящую воду, варить до всплытия.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (271,'Далее клецки обжарить на сковороде на оливковом масле, подать к столу с сырным или мясным соусом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Свеклу отварить или запечь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Приготовить свекольное пюре при помощи миксера или блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Картофельные клубни также запечь или отварить вместе с кожурой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Очистить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Мякоть пропустить через пресс.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Всыпать молотый мускатный орех, перец, соль по вкусу, корицу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Свекольное и картофельное пюре перемешать, вбить сырое куриное яйцо, добавить просеянную муку порциями.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Замесить тесто.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Завернуть в пленку, положить в холод на полчаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Посыпать стол мукой, раскатать тесто в тонкие колбаски, нарезать клецки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Провести вилкой, чтобы получились полоски.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Убрать продукт в холодильник.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Приготовить соус.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Нарезать копченую грудинку, обжарить на сковороде в сливочном масле.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'В кипящую воду всыпать соль, отварить ньокки порциями, вынимать шумовкой.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Переложить на сковороду с грудинкой, добавить листья шалфея.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (272,'Прогревать все вместе две минуты. Снять с огня.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (273,'Нарезать репчатый лук кубиками, выложить в чашу мультиварки вместе с фаршем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (273,'Подлить немного растительного масла, выставить режим «Выпечка» на десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (273,'Приготовить обжарку, крышку не закрывать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (273,'Выложить сверху сухие макароны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (273,'Перец и соль – по вкусу, влить кипяток, он должен закрыть продукты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (273,'Выставить режим «Плов».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (274,'Филе посолить и поперчить, натереть раздавленным в чеснокодавке или натертым на мелкой терке чесноком, сбрызнуть свежим лимонным соком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (274,'Отдельно смешать майонез, рубленую зелень, обмазать смесью рыбный стейк с одной стороны. Выложить сверху тонкий ломтик лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (274,'Печь семгу под лимонным соусом в духовке при 180 градусах в течение 30 – 40 минут. Подать в форме, в которой рыба запекалась, украсить веточкой свежего укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (275,'Готовую отваренную говядину пропустить через мясорубку или мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (275,'Выложить в мультиварку макароны твердых сортов, всыпать соль, влить кипящую воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (275,'Жидкость должна покрыть содержимое емкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (275,'Положить кусочек сливочного масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (275,'Готовить в режиме «Паста».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (275,'Налить на сковороду растительное масло, обжарить нарезанную говядину и накрошенный репчатый лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (275,'Макароны промыть, выложить в мультиварку, всыпать фарш.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (275,'Продукты перемешать, прогреть и подать на стол.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (289,'Протереть сыр твердых сортов на мелкой терке и добавить в сметану. Пропустить через пресс очищенный чеснок и смешать с сыром. Закрепить место разреза куриного филе шпажками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (346,'Выложить камбалу противень с луком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (276,'Лук-репку нарезать кольцами, обжарить на растительном масле до золотистого цвета. Сладкий болгарский перец нарезать кубиками, добавить в луковую массу, тушить вместе пять минут. Отварить, очистить и нарезать кубиками картофель. Добавить к перцу и луку и жарить до готовности, соль, перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (276,'Нарезать ветчину мелкими кубиками, добавить к взбитым яйцам. Овощи выложить в форму для запекания, залить яичной смесью. Печь фриттату с ветчиной по-испански в течение 10 – 13 минут при 180 – 200 градусах.  Готовое горячее блюдо посыпать сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (277,'Лук разрезать на 4 части и затем нарезать тонкими пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (277,'В сковороде разогреть оливковое масло, отправить туда лук и пропущенный через пресс чеснок. Обжариваем 7 минут на среднем огне перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (277,'Тушки кальмара нарезать кольцами, креветки очистить и добавить к луку. Готовим 2 минуты, перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (277,'Помидоры черри разрезать пополам, петрушку мелко нарезать сложить в сковороду, так же добавить мидии и залить вином. Перемешать и готовить 3 минуты на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (277,'Добавить отваренные спагетти, перемешиваем, настаиваем 2 минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (278,'На водяной бане растопить шоколад со сливочным маслом, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (278,'В глубокую тарелку вбить яйца (3 шт.), добавить сахар (4 ст.л.) взбить до легкой пены.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (278,'Муку смешать с какао.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (278,'К яйцам с сахаром влить шоколад и просеять муку с какао – перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (278,'Погружным блендером смешать: яйца (2 шт.), творог, сахар (2 ст.л.), бананы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (278,'Форму для выпечки застелить бумагой, смазать сливочным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (278,'Вылить половину шоколадного теста, затем вылить половину творожной смеси, зубочистку опустить до конца провести, что соединить слои и сделать рисунок, шоколадное тесто снова разделить пополам и залить слой, затем всю оставшуюся творожную смесь и сверху шоколадной, так же сделать рисунок при помощи зубочистки. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (279,'Оливковое масло, прованские травы, корицу и бальзамический уксус смешать. Телятину обмазать этим маринадом и оставить на 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (279,'На сковороде гриль разогреваем оливковое масло. Обжариваем стейки на сильном огне по 4 минуты с каждой стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (279,'Выкладываем на противень фольгу и кладем на нее наши стейки. Отправляем в духовку на 15 минут при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (280,'Кефир, соль (1/3 ч.л.), оливковое масло – перемешать. Добавить муку (2 стакана) - перемешать. Выложить тесто на рабочую поверхность, высыпать еще ½ стакана муки и замесить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (280,'Картофель и лук нарезать на кубики, сложить в глубокую тарелку, добавить фарш, соль (1 ч.л.), перец (1/2 ч.л.) – перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (280,'Тесто раскатать кругом. Выложить в центр теста начинку. Один край теста подтянуть к середине и к нему подтягивать оставшееся тесто, перед последним защипыванием теста, выпустить воздух их пирога.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (280,'На противень постелить бумагу, присыпать мукой, переложить пирог и сверху слегка пройтись скалкой. Верх наколоть вилкой, не протыкая дна. В середине сделать дырочку для выхода пара.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (280,'Смазать пирог кефиром, посыпать кунжутными семечками. Ставим в духовку на 40 минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (281,'Разогреть маргарин, а затем немного остудить. Добавить яйца, какао-порошок, сахар, соду. Перемешать, добавить муку постепенно, порциями. Из полученного теста выпечь три коржа. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (281,'Для крема смешать сметану и сахар (соотношение 2:1). Полученной смесью промазать коржи. Приготовить глазурь. Растопить шоколад на водяной бане и полить им торт «Шоколадный». Охладить в течение 1-2 часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (282,'Сварить бульон из куриного филе. Остудить, вынуть мясо и нарезать. Шампиньоны нарезать пластинками, порубить лук-репку. Натереть морковь. Лук и морковь пассеровать на растительном масле, грибы обжарить отдельно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (289,'Выложить на противень. Кармашки должны находиться наверху. Полить соусом. Сверху фаршированные куриные грудки с абрикосами можно посыпать различными приправами по вкусу и тертый сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (290,'Шампиньоны или другие грибы нарезать, обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (282,'Нарезать кубиками картофель, добавить в куриный бульон, варить до готовности, соль по вкусу в конце варки. Добавить морковно-луковую обжарку, грибы, тертые на крупной терке плавленые сырки, перец. Прогревать сырный суп с куриным филе и шампиньонами 10–12 минут до полного растворения сыра, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (283,'Сырой картофель натереть, так же поступить с луком-репкой, смешать. Добавить перец, яйцо, куриный бульон. Смесь должна быть достаточно густой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (283,'Нарезать батон, намазать картофельную смесь, выложить на смазанную сковороду массой вниз, обжарить, затем перевернуть и обжарить с другой стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (283,'Готовые бутерброды с тертым картофелем и яйцом намазать майонезом, по желанию посыпать рубленым укропом и чесноком. Подавать горячими.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (284,'Отварить куриную грудку, мелко порубить. Небольшими кубиками нарезать помидоры, их лучше очистить от кожицы и семян. Так же поступить со сладким болгарским перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (284,'Порубить чеснок, натереть вареное яйцо. Нарезать кубиками черствый белый хлеб, сбрызнуть водой и посолить. Высушить на сковороде на очень тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (284,'Выложить в салатницу слоями: курицу, помидоры, чеснок, яйцо, сладкий перец. Каждый слой промазывать майонезом. Сверху салат «Астра» с куриной грудкой выложить сухарики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (285,'Печень нужно промыть и очистить от пленки. Затем прокрутить через мясорубку. В массу необходимо положить яйца и всыпать муку. Слегка посолить и добавить по вкусу молотого перца. Хорошо смешанная масса должна напоминать тесто на оладушки.  В чугунной сковороде разогреть 1 ст. л. подсолнечного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (285,'После этого вылить печеночную смесь с помощью большой ложки на сковородку. Смесь должна покрыть дно тонким слоем. Прожарить в течение 2-3 минут и перевернуть блин лопатками. На вторую сторону также необходимо 2-3 минуты. Продолжать пока масса не закончится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (285,'Очищенный репчатый лук мелко порезать, обжарить слегка на раскаленном масле. Вынуть лук и дать стечь маслу.  Предварительно промытую зелень мелко нашинковать. Смешать сметану с зеленью и луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (285,'Каждый блин промазать готовой смесью. Выкладывать послойно как коржи для торта. Готовый торт при необходимости можно украсить рубленым грецким орехом и зеленью. Подавать печеночный торт со сметаной и зеленью на стол можно как горячим, так и остывшим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (286,'Заранее подготовить соус из томатного сока и сметаны. При необходимости приправить.  Фарш смешать с очищенным и промытым рисом. Добавить мелко порубленную капусту, яйца, порезанный лук. Все тщательно смешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (286,'Сделать из готовой массы небольшие котлеты. Взять форму для запекания и разложить котлетки, полив их смесью из сока и сметаны. Выпекать ленивые голубцы из мясного фарша в предварительно разогретой духовке в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (287,'Взять говяжий или свиной фарш, смешать его с яйцами и мукой. Очистить и протереть на терке сырой картошки. Смешать с мясным фаршем. Всыпать муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (287,'Готовую смесь приправить по желанию. Обжаривать на раскаленной сковороде с маслом. Переворачивать картофельно-мясной шницель, когда нижняя сторона зарумянится.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (288,'Взять сырокопченый бекон, порезать тонкими пластинами, обжарить на раскаленной сковороде.  Предварительно отваренную куриную грудку порезать мелкими кубиками и тоже обжарить. Готовое мясо должно быть золотистым. Смешать зеленые салаты и выложить на тарелку вместе с кубиками сыра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (288,'Разрезать пополам помидоры черри и положить к салату. Авокадо промыть, очистить. Порезать его на мелкие кубики и положить в тарелку.  На них положить поджаренные мясо курицы и бекон. Полить заправкой и слегка перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (288,'В качестве заправки к салату «Супер Микс» с авокадо рекомендуется использовать смесь из французской горчицы и оливкового масла с добавлением сока половинки апельсина. Смесь можно слегка посолить и поперчить. Для остроты добавить сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (289,'Промытые куриные грудки обсушить. Сделать небольшой разрез с боку филе. Заполнить этот карман консервированными абрикосами. Кусок мяса натереть солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (290,'Это можно сделать в мультиварке в режиме «Жарка».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1781,'Лук нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (290,'Когда влага испарится – всыпать нарезанный репчатый лук, продолжать жарить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (290,'Добавить фарш из куриного мяса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (290,'Перемешать, обжарить все вместе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (290,'Всыпать макароны, влить горячую воду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (290,'Посолить и поперчить по вкусу, выставить режим «Плов» или «Паста».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (290,'По желанию в блюдо можно добавить сливки или сметану, потушить все вместе.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (291,'В муку добавляем соду, пекарский порошок и соль.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (291,'В кефир добавляем лимонный сок и цедру лимона. Теперь в сахарную смесь добавляем в 4 части (чередуя) кефир и муку. Полостью перемешиваем и взбиваем миксером. Добавляем мак (можно сухой, так кекс будет легче).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (291,'Заливаем в форму для выпекания предварительно смазав маслом и посыпав мукой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (292,'В глубокую тару добавить молоко, сливочное масло, яйцо, сахар, соль. Все хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (292,'В муку добавить разрыхлитель, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (292,'Переложить муку с разрыхлителем в глубокую тару.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (292,'Лимонным соком загасить соду, добавить к остальным ингредиентам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (292,'Все хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (292,'Дать тесту отдохнуть 10 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (292,'Перелить его в кулинарный мешок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (292,'Сковороду поставить на малый огонь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (292,'При помощи кулинарного мешка на сковороде сформировать мини панкейки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (292,'Когда на панкейках появятся пузырьки, надо перевернуть их на другую сторону. Жарить еще 20-30 секунд и убрать со сковороды.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (292,'Повторять, пока не закончится тесто. Мини панкейки готовы! Всем приятного аппетита! Больше кушайте, никого не слушайте!',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (293,'Нарезаем сало на пластинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (293,'Натираем картофель на терке и отжимаем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (293,'Добавляем к картофелю зелень петрушки, зелень укропа, зеленый лук, соль, черный молотый перец и красный острый перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (293,'Нарезаем помидор, перец чили и грибы колечками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (293,'Смешиваем соль, черный молотый перец и красный острый.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (293,'Выкладываем послойно на решетку сало, тертый картофель с зеленью, перец чили, помидор, грибы, посыпаем овощи смесью соли и перцев, сверху выкладываем картофель и сало.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (293,'Жарим на углях 20-25 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (294,'Измельчаем пекинскою капусту, огурцы и зеленый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (294,'Добавляем к измельченным ингредиентам тунец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (294,'Готовим заправку: смешиваем венчиком лимонный сок, масло из консервированного тунца (можно заменить на оливковое), горчицу, черный молотый перец и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (294,'Заправляем салат и подаем порционно. Всем добра!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (295,'Копченое куриное мясо нужно очистить от шкурки, косточек и хрящей. После чего разрезать мелкими кубиками. Это первый слой салата. Положить его на тарелку и помазать майонезом.  Свежий чеснок необходимо мелко измельчить. Посыпать поверх майонеза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (295,'Вторым слоем идет кукуруза. Ее необходимо предварительно сцедить от всей жидкости. Слой промазать майонезом. Взять свежие помидоры и порезать на небольшие кубики. После слоя помидоров нужно использовать совсем немного помидоров. Также после этого слоя можно слегка посолить и поперчить салат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (295,'Предварительно отваренные яйца нужно мелко измельчить и положить на слой помидоров. Сыр твердых сортов необходимо протереть через мелкую терку. Его нужно положить на салат в виде красивой шапочки. Дать салату из копченой курицы с кукурузой и сыром настоятся в течение 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (296,'Намазать сливочное масло на ломтики батона и отправить в духовку на 3-4 мин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (296,'Мелко нашинковать отваренную заранее курицу, нарезать помидоры и сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (296,'Достать поджаренный хлеб из духовки, намазать майонез, выложить слоями курицу, помидоры и сыр, по желанию поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (296,'Снова отправить в духовку на 10 минут. Бутерброды готовы, приятного аппетита!.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (297,'На жире от тушенки обжарить овощи в чаше мультиварки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (297,'По необходимости добавить масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (297,'Выставить режим «Жарка», добавить тушенку, готовить все вместе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (297,'Мясо разделить на волокна.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (297,'Всыпать макароны, влить кипяток, добавить специи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (297,'Выставить режим «Паста» или «Плов».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (298,'Первым шагом необходимо взять свежие мягкие пряники и аккуратно разрезать их на две половинки вдоль. Свежие не мягкие бананы нарезать в кружочек.  Сахарную пудру тщательно растворить в сметане. Чищенные грецкие орехи накрошить в среднюю крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (298,'Миску, куда будет выкладываться торт, застелить пленкой. Это позволит извлечь готовый десерт без труда.  Дно миски уложить пряниками. Все пространство между половинками уложить крошками от пряника.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (298,'После этого выложить бананы. Затем снова пряники и еще один слой бананов.  Сверху насыпать орехи. В самом конце выложить еще один слой пряников. Готовый пряничный торт «Вдохновение» должен сначала постоять несколько часов в теплой комнате, затем его необходимо убрать в холод на три часа. Перевернуть миску на тарелку и подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (299,'Обжарить говяжий фарш с репчатым луком в мультиварке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (299,'Добавить консервы «Лечо» или «Краснодарский» соус, домашние или магазинные.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (299,'Всыпать макароны, залить воды, варить в обычном режиме.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (300,'Сварить спагетти до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (300,'Для приготовления соуса растопить сливочное масло на сковороде, обжарить рубленый чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (300,'Добавить нарезанный базилик или петрушку с укропом, через две минуты добавить чищеные креветки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (300,'Подержать смесь на огне, влить сливки, довести до кипения, всыпать тертый сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (300,'Время приготовления соуса – около десяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (300,'В горячий соус добавить макароны, перемешать, накрыть крышкой, прогреть несколько минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (301,'Мякиш батона замочить в молоке, перемолоть вместе с рыбным филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (301,'Отделить желтки от белков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (301,'Фарш соединить с желтками, белки охладить и взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (301,'Всыпать в основную массу манку и соль, дать постоять десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (301,'Ввести белковую массу, постепенно, порциями, перемешивать движениями снизу вверх.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (301,'Запечь суфле в силиконовых формочках, масса должна подрумяниться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (301,'Вынуть в теплом виде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (302,'Сметану перемешать с сырыми куриными желтками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (302,'Натереть твердый сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (302,'Пропустить через мясорубку репчатый лук с рыбой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (302,'Рыбную массу перемешать с рисом, его можно поперчить и посолить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (302,'Всыпать сыр, ароматные травы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (302,'Белки взбить в пену с солью, вмешать в основную массу аккуратными движениями снизу вверх.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (302,'Выложить в форму для запекания, полить сметанной заправкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (302,'Выпечь в духовке до готовности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (303,'Нужно взять свежемороженую скумбрию хорошего качества. Разморозить ее и очистить. Не стоит забывать о черной пленке. Она может испортить весь вкус. Тщательно промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (303,'Нарезать рыбу на кусочки. Сдобрить специями.  Лук нарезать тонкими колечками. Для приготовления соуса понадобится майонез и кетчуп. Их необходимо тщательно размешать. Каждый кусок рыбы обмакнуть в нем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (303,'Противень предварительно нужно застелить бумагой для выпечки. Скумбрию выложить на лист. Колечки лука необходимо положить между кусочками рыбы. На самой рыбе нанести линию из кетчупа и майонеза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (303,'Предварительно разогреть духовку до 160 градусов и поставить противень на полчаса. Готовая скумбрия в соусе, запеченная в духовке, покрывается аппетитной корочкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (304,'Воду налить в кастрюлю. С курицы снять кожу, отправить в кастрюлю с водой, добавить лавровый лист. Накрываем крышкой, доводим до кипения и варим 20 минут на слабом огне, снимая пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (313,'Приготовление крема: масло взбить с сахаром, постепенно добавить сметану не прекращая взбивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (304,'Репчатый лук нарезать кубиком, морковь натереть на крупной терке. В сковороде разогреть растительное масло, отправить в нее лук и морковь. Обжариваем на медленном огне 15 минут, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (304,'В миску разбить яйцо, добавить щепотку соли, перемешать. Всыпать муку, замесить тесто. Замешанное тесто полить растительным маслом (1 ч.л.), замешивать пока масло не впитается. Затем раскатать тесто очень тонко (толщиной 1 мм) и нарезать лапшу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (304,'Из кастрюли вытащить курицу. Немного остудить и отделить мясо от костей. Мясо нарезать небольшими кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (304,'В куриный бульон отправить поджарку из лука и моркови, довести до кипения. Добавляем лапшу, перец и соль (1 ч.л.), перемешиваем. Накрываем кастрюлю крышкой, варим 7 минут на медленном огне. Снимаем с огня и добавляем курицу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (305,'Смешать майонез, яйца и посолить. Постепенно, помешивая добавлять муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (305,'Смазать сковороду растительным маслом, вылить тесто и распределить по поверхности. Смазать майонезом и выложить начинку, посыпать тертым сыром и зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (305,'Поставить на огонь на 15 минут и накрыть крышкой. Приятного аппетита!.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (306,'Взбить и посолить яйца, обжариваем на сковороде 30 сек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (306,'Накрываем кусочком лаваша вырезанным заранее по размеру сковороды и обжариваем еще 30 сек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (306,'Переворачиваем и выкладываем начинку слоями на одну сторону, складываем омлет с лавашем пополам и обжариваем с каждой стороны по 30 сек под крышкой. Приятного аппетита!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (307,'Взять почищенную и выпотрошенную рыбу, сделать надрезы поперек тела рыбы, посолить, обвалять в муке и жарить на сковороде по 5-8 минут с каждой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (307,'Обжарить лук до золотистого цвета и посыпать им готовую рыбу. Приятного аппетита!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (308,'Кабачки нарезать толщиной около 5 мм, посолить, обвалять в муке и обжарить около 1 мин. с каждой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (308,'Соус: в майонез добавить чеснок и мелко порезанный укроп, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (308,'Выложить кабачки на блюдо, смазать соусом и украсить сверху помидором. Приятного аппетита!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (309,'Смешать томатную пасту и майонез, выдавить чеснок. Замариновать курицу получившимся соусом, добавить паприку, перец и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (309,'Смазать емкость для запекания, выложить курицу в емкость и отправить в прогретую духовку запекаться на 40 минут при 180 градусах. Приятного аппетита!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (310,'Нарезать капусту, огурец, помидор, зеленый лук и зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (310,'Добавить майонез и соль, тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (310,'Добавить майонез и соль, тщательно перемешать. Салат готов приятного аппетита!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (311,'Мелко нарезать черемшу, лук и петрушку, на кубики порезать огурец, редис и яйца.','https://vkuso.ru/data/cache/data/77/0c7ff1efe117c77_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (311,'Посолить, добавить майонез и перемешать. Салат готов, приятного аппетита!','https://vkuso.ru/data/cache/data/41/203008b26772841_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (312,'Копченый окорочок очистить от шкурки, костей и нарезать тонкой соломкой. Вымоченный чернослив тоже нарезать мелкой соломкой. Свежие шампиньоны посолить и поперчить. Затем обжарить на медленном огне.  Свежие огурцы порезать мелкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (312,'Салат нужно укладывать послойно. Сначала мясо, затем черносливы, грибочки и огурцы.  Последним слоем будет корейская морковка. Каждый слой промазать майонезом по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (312,'Для украшения праздничного салата «Фиалки» необходимо использовать тонко нарезанный редис, который был предварительно вымочен в соке синей капусты. В качестве листьев фиалки нужно использовать шпинат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (312,'При подаче на стол бока салата украсить соленым печеньем. Чернослив лучше выбрать кислый. Если он окажется сладким, то количество следует уменьшить примерно в два раза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (313,'Яйцо взбить с сахаром до густой пены, добавить кефир, соду и еще раз взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (313,'Затем добавить муку, тесто должно быть похоже на густую сметану. Вылить в смазанную маслом форму и печь при температуре 180°С.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (313,'Готовый бисквит остудить и вытащить из формы, затем разрезать на 3 коржа, смазать кремом, сверху полить шоколадной глазурью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (386,'Время набухания – от семи до восьми минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (313,'Приготовление глазури: смешать все ингредиенты и растопить шоколад импульсивным методов в микроволновой печи до однородной массы.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (314,'Для начала разогреем сковородку, заливаем маслом, выдавить чеснок, добавить молотый кориандр, тмин, паприку и начинаем укладывать креветки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (314,'Посыпаем хлопьями чили, орегано и заливаем пивом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (314,'Затем туда же выжимаем лайм. Для более насыщенного вкуса можно добавить соус Чипотле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (314,'Добавляем кусок масла, выключаем и посыпаем зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (315,'Яйцо разбить добавить соль и оливковое масло. После чего замесить тесто. Оно должно быть эластичным. Скатать шар и оставить на 20 минут, накрыв полотенцем. Картошку вымыть под струей воды, сварить в мундире. Затем сцедить воду и остудить. Промытый рис отварить. необходимо, чтобы он не разварился. После чего откинуть его и процедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (315,'Свежее молоко нагреть до 40 градусов. Отварную картошку залить молоком и сделать пюре.  После чего добивать туда рис и растительное масло. Приправить специями. Картофель залить горячим молоком, тщательно растереть в пюре. Добавить рис, оливковое масло, мускатный орех и мяту, посолить, поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (315,'Взять круглую форму для выпечки. С помощью кисточки обмазать края маслом. Тесто тонко раскатать. Нужно раскатать размером чуть больше чем форма. Аккуратно выложить начинку. Тесто, которое выступает за края формы завернуть. Тщательно взбить одно яйцо и смазать им пирог. Выпекать пататопиту с картофелем и рисом необходимо в разогретой духовке  в течение 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (316,'Потрошим, моем окуньков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (316,'Разрезаем по хребту вдоль всей рыбки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (316,'Маринуем в смеси соли, перца черного молотого, перца красного острого, копченой паприки и растительного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (316,'Жарим на углях по 5 минут с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (317,'Филе трески нарезать полосками толщиной в два или три сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (317,'Кусочки рыбы обвалять сначала в муке с солью и молотым перцем, затем – во взбитых подсоленных яйцах, в заключение – в панировочных сухарях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (317,'Противень застелить фольгой, выложить кусочки филе на расстоянии друг от друга.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (317,'Прикрыть вторым листом фольги, подержать в холоде полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (317,'Жарить на оливковом масле с двух сторон до корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (317,'Рыбные палочки выложить на полотенце из бумаги, оставить для впитывания излишков жира. Другой вариант – блюдо можно запечь в духовке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (318,'Емкость со сливочным маслом поставить в горячую воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (318,'Влить молоко, всыпать муку, перемешать, посолить и поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (318,'Добавить вареную рыбу, желтки, вареный рис, взбитые отдельно белки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (318,'Жаровню застелить фольгой, выложить массу, запечь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (319,'Сырое рыбное филе, нарезанное кусочками, взбить при помощи блендера с сырыми желтками, солью, белым хлебом без корочек, сливками или жирным молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (319,'Отдельно взбить белки, вмешать в основную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (319,'В мультиварку влить два стакана воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (319,'Силиконовые формочки смазать маслом, заполнить на две трети объема, поставить в контейнер на пятнадцать минут, режим – «Варка на пару».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (320,'Брокколи разобрать на соцветия, влить горячую воду, время кипячения – две минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (320,'Перемолоть со шпинатом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (320,'Влить жирные сливки, посолить, перемешать с сырыми яйцами и дополнительными желтками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (320,'Измельчить сыр, добавить крошку в основную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (320,'Взбить белки, ввести в смесь осторожными движениями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (320,'Смазать формы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (320,'Разложить массу для суфле, температура запекания – 200 градусов, время – от получаса до тридцати пяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (321,'Сухие дрожжи разболтать в теплой воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (321,'Перелить в небольшую емкость, всыпать немного просеянной пшеничной муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (321,'Накрыть опару крышкой, оставить на час в тепле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (321,'Масса должна заметно увеличиться в объеме.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1859,'Выложить яблоки ровным слоем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (321,'Перелить опару в большую емкость, посолить, всыпать отруби, влить натуральный мед, теплую воду, всыпать остатки муки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (321,'Замесить тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (321,'Форму смазать маслом, выложить хлебную массу, оставить на час в тепле.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (321,'Время выпекания – пятнадцать минут, температура – 230 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (321,'Под выпечку лучше поставить противень с водой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (321,'Температуру понизить до 200 градусов, печь хлеб еще полчаса.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (322,'Вбить сырое куриное яйцо в емкость хлебопечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (322,'Влить воду, растительное масло, всыпать соль и сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (322,'Добавить отруби и просеянную пшеничную муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (322,'Всыпать сухие дрожжи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (322,'Выставить режим «Основной».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (323,'Овсяные отруби превратить в муку при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (323,'Перемешать с куриным яйцом, пшеничными отрубями, нежирным творогом и разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (323,'Однородную массу перелить в форму, которую можно использовать в микроволновой печи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (323,'Режим – 750 Вт, время – от четырех до пяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (324,'Салат необходимо выкладывать слоями. Каждый слой промазать майонезом. Первым слоем будет отваренное куриное мясо, которое после остывания необходимо порезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (324,'Свежую морковку пропустить через терку, и добавить в ней чеснок, который необходимо пропустить через пресс. После чего слегка прожарить на масле. Предварительно размягченный чернослив нужно нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (324,'Сыр твердых сортов протереть через терку.  Следующий слой — обжаренный репчатый лук.  После этого нужно положить протертые через терку 2-3 вареных яйца. Дать слоеному салату «Ночка» с черносливом слегка настояться. После чего подавать к столу украсив перьями лука.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (325,'Соединить в емкости пшеничную муку с цельнозерновой, добавить отруби, соль, сахар, пищевую соду, семена фенхеля и льна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (325,'Влить порциями кефир, перемешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (325,'Добавить немного растительного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (325,'Готовое тесто оставить на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (325,'Сформовать два изделия.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (325,'Время выпекания в духовом шкафу – от двадцати до двадцати пяти минут, температура – 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (326,'Отруби измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (326,'В подогретой воде развести дрожжи и сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (326,'Ингредиенты соединить с просеянной мукой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (326,'Сформовать шар, оставить под полотенцем на два с половиной часа в тепле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (326,'Сформовать хлебцы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (326,'Смазать молоком сверху, посыпать семенами кориандра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (326,'Время выпекания – сорок минут, температура – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (327,'Картофель отварить в мундире. Мелко покрошить лук. На сковородке нагреть растительное масло и обжарить лук до золотистого цвета. Порезать на некрупные кусочки грибы, выложить на сковородку к луку и жарить еще 5–7 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (327,'Плавленый сыр потереть и добавить на сковородку к грибам с луком. Все перемешать и потушить в течение 15 минут на небольшом огне. Порезать куриную грудку на кусочки, добавить на сковородку к грибам и тушить 10 минут. Дать остыть курино-грибной массе, а потом ее вместе с картофелем прокрутить через мясорубку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (327,'Для фарша на оладьи добавить остальные продукты, за исключением растительного масла, и вымесить тесто. Оладушки «Трио» из курицы, картофеля и грибов пожарить на сковородке с растительным маслом, выкладывая тесто столовой ложкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (328,'Вылить стакан молока в кастрюлю, смешать с 2 пакетами желатина и поставить на несильный огонь. Постоянно взбивая дождаться, когда от молока пойдет пар. Сразу снять с плиты. Охладить. Подготовьте форму размером 20х30 см, смазав ее растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (328,'Сметану, сливки и 1 стакан сахара миксером взбить на средней скорости. Сахар должен полностью разойтись. Влить теплую молочную смесь к сметане и сливкам, продолжая взбивать миксером. Вылить молочно-сливочную смесь в приготовленную форму, поверхность разровнять лопаткой или ножом. Накрыть форму и поместить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (346,'Приготовить смесь из сметаны, соли, специй, чеснока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (328,'Теперь нужно приготовить глазурь. Для этого смешать прямо в кастрюле какао, сахар и желатин. Влить воду и молоко, постоянно взбивая. Довести до кипения, при этом постоянно помешивая. Глазурь должна стать гладкой и однородной. Дать глазури остыть в течение часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (328,'Когда смесь остынет, то равномерно полить ею молочно-сливочную основу. Вновь поставить торт «Птичье молоко» с взбитыми сливками в холодильник примерно на 5 часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (329,'Обычный несоленый миндаль выложить в миску.','https:https://st.vkuso.ru/data/cache/thumb/af/43814f75a9053af_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (329,'Влить воду (75 мл), оставить орехи для вымачивания на время от восьми до двенадцати часов.','https:https://st.vkuso.ru/data/cache/thumb/87/ba3879260b6ba87_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (329,'Орехи процедить и промыть.','https:https://st.vkuso.ru/data/cache/thumb/ea/7fb39c9e0b970ea_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (329,'Влить воду в миску, одна часть миндаля на три части воды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (329,'Соковыжималку отрегулировать, установить лезвия.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (329,'Выложить в чашу миндаль с водой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (329,'Добавлять орехи порциями при работающей соковыжималке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (329,'Готовую смесь пропустить через дуршлаг, затем – через кофейный фильтр.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (329,'Поместить фильтр в контейнер, налить молоко, отцедить.','https:https://st.vkuso.ru/data/cache/thumb/d1/f3f5a82163f4ed1_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (329,'Разлить напиток в стеклянные бутылки, поставить в холодильник, хранить два или три дня.','https:https://st.vkuso.ru/data/cache/thumb/31/370245c26827531_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (330,'Миндальные орехи промыть, залить холодной чистой водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (330,'Оставить на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (330,'Воду слить, залить продукт кипящей водой на пятнадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (330,'Кожицу снять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (330,'Если не снимать, то напиток примет терпкий вкус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (330,'Переложить орехи в блендер, влить стакан воды.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (330,'Перемолоть орехи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (330,'Добавить воду, все еще раз прокрутить в блендере в течение тридцати или сорока секунд.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (330,'Молочко процедить через четыре слоя марли.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (330,'Жмых отжать, его можно использовать для приготовления паштетов, салатов, конфет.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (330,'В молоко добавить корицу, ваниль или немного меда по вкусу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (331,'Приготовить маринад: в пиво добавить соль, зиру и перец, перемешать. Поместить свиное колено в маринад минимум на 12 часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (331,'Маринованное колено обмазать раздавленным чесноком. Поместить на противень и накрыть фольгой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (331,'Жарить колено в разогретой до 180 градусов духовке в течении 3,5 часов периодически переворачивая мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (331,'Гарнир: нарезанную луковицу пассеровать в растительном масле до золотистого цвета. Добавить в сковороду мелконарезанный чернослив и моченое яблоко. Тушить 5-7 минут, затем добавить квашенную капусту и тушить еще 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (331,'Готовое колено выложить на блюдо и добавить гарнир.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (332,'Красный и зеленый сладкий болгарский перец промыть, удалить хвостики и семена.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (332,'Мякоть нарезать кольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (332,'Прогреть на сковороде оливковое масло, обжарить перцы, добавить нарезанные огурцы и помидоры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (332,'Посолить по вкусу, приправить специями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (332,'Прогревать еще две минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (332,'Вымыть лук-порей, нарезать тонкими колечками по три или четыре миллиметра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (332,'Очистить чеснок, нарезать тонкими пластинками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (332,'В отдельной сковороде прогреть оливковое масло, обжарить чеснок с луком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (332,'Разморозить филе телапии, нарезать небольшими кусочками по пять сантиметров, поперчить, посолить, побрызгать свежим лимонным соком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (332,'Рыбу выложить на луковую обжарку, влить белое сухое вино, тушить блюдо под крышкой в течение десяти минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (332,'Продукты аккуратно переложить в сковороду к перцам.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (332,'Вымыть, обсушить и нарезать зелень петрушки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (332,'Добавить в сковороду, тушить все вместе под крышкой в течение пяти или шести минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (339,'Добавить мелко порезанный чеснок, соль, перец, гвоздику.  Запекать охотничьи колбаски с овощами в горшочках в духовке 45 минут. В конце добавить сыр, зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (340,'Рыбу вымыть, удалить головы и внутренности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (333,'Взбить яйца, добавить к ним сахар, какао-порошок и хорошо размешать, пока сахар не растворится. В эту смесь добавить сгущенное молоко, сметану, а после того как хорошо все перемешается, добавить муку, соду и снова тщательно вымешать тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (333,'Приготовить форму для выпечки. Положить в нее бумагу для выпечки, смазанную сливочным маслом. Включить духовку и дать ей нагреться до 180 градусов Вылить тесто в форму, выпекать 30–35 минут. Когда тесто будет готово, то подождать, когда оно полностью остынет, не вынимая из формы. После этого достать и разрезать на 2 равных коржа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (333,'Приготовить крем. Для этого вареную сгущенку смешать с мягким сливочным маслом и взбить миксером. Коржи пропитать сгущенным молоком, а потом промазать кремом из вареной сгущенки и масла. Сверху изысканный «Пражский торт» украсить глазурью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (334,'Разморозить мойву, вымыть, удалить внутренности и головы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (334,'Рыбу посолить, поперчить, полить лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (334,'Застелить решетку пергаментом, смазать растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (334,'Рыбу обвалять в панировочных сухарях, выложить на бумагу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (334,'Время запекания – пятнадцать минут, продукт не должен пересохнуть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (334,'Выложить мойву на тарелку, на гарнир подать картофель в любом виде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (335,'Рыбу разморозить, удалить жабры, внутренности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (335,'Картофель и морковь очистить, вымыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (335,'Нарезать кружочками морковь, репчатый лук – полукольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (335,'Картофель нарезать ломтиками или тонкими дольками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (335,'Морковь и картофель залить небольшим количеством воды, посолить, время приготовления – пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (335,'Противень смазать маслом, выложить лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (335,'Сверху – слой моркови и картофеля, соль – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (335,'Мойву посолить и поперчить, добавить куркуму, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (335,'Рыбу выложить поверх овощей, поставить в разогретый духовой шкаф на полчаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (335,'Готовую рыбу выложить в центре большой тарелки, вокруг – овощи.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (336,'Мойву вымыть, разделать на филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (336,'Отварить картофель в мундире, очистить, нарезать кружками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (336,'Рыбу посолить, обвалять в муке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (336,'Обжарить на сковороде с двух сторон до появления золотистой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (336,'Из плотной фольги свернуть конвертики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (336,'Другой вариант – использовать небольшие сковородки по количеству людей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (336,'Выложить рыбу, закрыть кружками картофеля.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (336,'Смазать блюдо сметаной, посыпать тертым сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (336,'Запечь в заранее прогретой духовке до корочки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (337,'Замочить фасоль на 2 часа, затем выложить в кастрюлю, добавить 2 литра воды, лук, чеснок и лавровый лист. Варить 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (337,'Нарезать картофель, лук, помидор и морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (337,'В фарш добавить яйцо, соль и перец. Перемешать и сформировать фрикадельки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (337,'Разогреть сковороду, смазать немного растительным маслом и обжарить фрикадельки со всех сторон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (337,'Через час достать из кастрюли лук, чеснок и лавровый лист. Выложить в бульон овощи и фрикадельки. Варить 15 минут. В конце варки посолить и поперчить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (338,'Куриное филе нарезать на некрупные кусочки, сложить в миску и замариновать в смеси лука, порезанного кольцами, соли, перца и уксуса. Время маринования мяса 1–2 часа. Картошку почистить, нарезать кольцами и выложить на противень. Куриное мясо нанизать на шпажки из дерева, в промежутках надеть колечки лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (338,'Шпажки с мясом выложить сверху картошки на противень. Поставить его в уже нагретую духовку на 30 минут. В процессе запекания шашлыки перевернуть, чтобы мясо подрумянилось и с другой стороны. Сочный куриный шашлык с картофелем в духовке готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (339,'Очищенную картошку порезать кубиками. Охотничью колбаску нарезать колечками. Морковь обжарить, добавить немного томатной пасты с небольшим количеством воды. В горшочки сложить вперемешку картошку, охотничью колбаску, морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (340,'Посолить, оставить для пропитывания на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (340,'Выложить в глубокий противень или на сковороду слой рыбы, добавить лавровый лист, перец-горошек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (340,'Выложить второй слой мойвы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (340,'Продукт залить чаем, добавить растительное масло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (340,'Закрыть фольгой или крышкой, поставить в духовой шкаф на час, огонь – минимальный.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (340,'Снять крышку, довести блюдо до готовности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (340,'Остудить, подать на стол с зеленью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (341,'Рыбу разморозить в домашних условиях, вымыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (341,'Если есть тушки с икрой внутри, то ее не вынимать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (341,'Удалить головы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (341,'Репчатый лук очистить, нарезать тонкими кольцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (341,'Смазать маслом противень большого размера, выложить лук, затем – рыбу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (341,'Посолить и поперчить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (341,'По желанию добавить другие приправы для рыбы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (341,'Смазать тушки майонезом, поставить в духовку на час, огонь – средний.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (341,'Тушить до появления румяной корочки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (342,'Удалить чешую, удалить плавники, голову, хвост.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (342,'Рыбу разрезать вдоль, удалить кости, хребет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (342,'Снять кожицу, филе порезать на кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (342,'Камбалу натереть солью и специями, побрызгать лимонным соком, оставить при комнатной температуре на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (342,'Репчатый лук нарезать полукольцами, выложить на противень, застеленный фольгой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (342,'Выложить камбалу, полить оливковым маслом, обернуть фольгой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (342,'Прогреть духовку до 190 градусов. Время запекания – от сорока пяти до пятидесяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (342,'Фольгу снять, печь еще десять минут, до появления румяной корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (343,'Нарезать морковь половинками кружков, репчатый лук – полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (343,'Покрошить произвольно корень сельдерея.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (343,'Влить в сотейник немного воды, отварить овощи до полуготовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (343,'Очистить рыбу от чешуи, удалить голову, внутренности, плавники, вынуть кости и хребет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (343,'Снять кожу, лучше это делать резким движением.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (343,'Филе нарезать небольшими кусочками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (343,'Обвалять продукт в муке, жарить на раскаленном растительном масле до румяной корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (343,'Выложить рыбу на овощи, посыпать специями.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (343,'Тушить под крышкой в течение получаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (343,'Подливать воду порциями.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (343,'Порубить укроп и петрушку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (343,'Готовую рыбу с овощами выложить на тарелку, посыпать рубленой зеленью, подать горячей.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (344,'Филе камбалы разморозить, слить лишнюю воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (344,'Очистить репчатый лук, пропустить через мясорубку вместе с рыбой и вчерашним хлебом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (344,'Вбить сырое куриное яйцо, всыпать манную крупу, добавить сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (344,'Мелко порубить укроп, добавить в фарш, посолить, специи – по желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (344,'Массу поставить в холод на полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (344,'Сформовать небольшие котлеты, обвалять в панировочных сухарях, выложить на доску.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (344,'Прогреть сковороду с растительным маслом, котлеты жарить с двух сторон до появления хрустящей корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (344,'Котлеты выложить в сотейник, подлить немного воды и потушить десять минут до готовности, под крышкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (345,'Удалить чешую, плавники и голову.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (345,'Разрезать тушку вдоль, вынуть внутренности, кости, хребет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (345,'Снять кожу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (345,'Филе вымыть под проточной водой, обсушить бумажными полотенцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (345,'Порезать на порционные кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (345,'Перемешать муку с солью и специями.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (345,'Нарезать репчатый лук полукольцами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (345,'Налить масло на сковороду, прогреть. Обвалять рыбу в муке, обжаривать на среднем огне с двух сторон до румянца.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (345,'Время – пять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (345,'Выложить на сковороду лук, прогревать все вместе, помешивать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (346,'Репчатый лук нарезать полукольцами, выложить на противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (346,'Филе камбалы разрезать на кусочки небольшого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (346,'Полить сметанным соусом, он почти полностью должен покрыть рыбу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (346,'Время приготовления – сорок минут, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (346,'Блюдо украсить веточками свежей петрушки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (347,'Панировочные сухари залить молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (347,'Крупно нарезать курицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (347,'В чашу для блендера сложить курицу, панировочные сухари, паприку, мускатный орех, кориандр, соль, черный перец, чеснок, сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (347,'Перемолоть до однородной массы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (347,'Фарш выложить на пищевую пленку, сформировать длинную, плотную сосиску.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (347,'Свернуть пленку, перевязать нитками по краям.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (347,'Придать сосиске округлую форму.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (347,'Визуально разделить сосиску на 6 равных частей и перевязать каждую ниткой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (347,'Ленту из сосисок варить в кипящей воде 5-6 минут. Куриные сосиски готовы! Всем приятного аппетита! Больше кушайте, никого не слушайте!.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (348,'Нарезаем сало на полосочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (348,'Нарезаем грибы, помидор, баклажан, перец чили кольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (348,'Нарезаем черный хлеб на квадратики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (348,'Смешиваем соль, черный молотый перец и красный острый.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (348,'Первая закуска. Выкладываем на сало помидор, перец чили, черный хлеб, чеснок, шампиньон посыпаем специями с солью и заворачиваем в рулет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (348,'Вторая закуска. Выкладываем на сало баклажан, помидор, чеснок, перец чили посыпаем специями с солью и заворачиваем в рулет.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (348,'Третья закуска. Посыпаем шампиньоны специями и солью и заворачиваем в сало.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (348,'Жарим на углях 15 минут. Готовьте с удовольствием и приятного аппетита!',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (349,'Нашинковать капусту на терке. Натереть редис на терке для корейской морковки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (349,'Довести кастрюлю с водой до кипения, добавить лимонный сок и сахар. Размешать и добавить кукурузу. Выключить огонь и накрыть крышкой на 10-15 мин. Достать и остудить.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (349,'Для заправки смешать сметану и майонез. Посолить по вкусу. Салат готов. Приятного аппетита!.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (350,'Этот салат делается очень быстро и просто, но результат при этом получается сытным и вкусным. Все ингредиенты нарезать соломкой или некрупными брусочками. Выложить в миску, добавить майонез и перемешать. Украсить зеленью. Салат «Анастасия» готов!',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (351,'Замаринуйте мясо в соевом соусе на 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (351,'Приготовьте соус: чеснок пропустить через пресс, перчик чили порежьте вместе с семенами кружочками, добавьте оливковое масло, сахар, перемешайте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (351,'В сковороде раскалить сливочное масло. Обжарить стейк по 5 минуты с каждой стороны. Выложить на противень и запечь при температуре 200 градусов в течение 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (351,'На тарелку выложите листья салата, клубнику разрезанную на 4 части, свёклу, полейте соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (352,'В миске соединить сливочное масло комнатной температуры, йогурт и сахар. Взбить при помощи блендера 2 минуты. Вбить яйцо и снова перемешать при помощи блендера в течении 2 минут. Затем добавить молоко, ванильный сахар с кусочками ванили снова перемешать. Всыпать муку, соль и разрыхлитель перемешиваем до однородности и всыпаем белые шоколадные капли - перемешиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (352,'Включаем духовку разогреваться до температуры 180 градусов, а в это время форму для выпечки застелим пекарской бумагой и смажем растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (352,'В подготовленную форму выливаем тесто. Клубнику очистить от хвостиков и нарезать пополам (или на 4 части, если клубника крупная), выложить на тесто, а затем посыпать темными шоколадными каплями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (352,'Выпекать пирог 50 минут до образования в верху золотисто-коричневого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (353,'Индейку нарезать на кусочки посолить, поперчить посыпать травами, и специями по желанию.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (353,'Обжариваем на масле с двух сторон по 6 минут на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (353,'Листья салата нарвать, добавить черешню без косточек, брынзу, индейку и лимонные дольки. Заправить оливковым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (354,'На тарелку выложить мангольд.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (354,'Сливы нарезать дольками и выложить поверх мангольда.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (354,'Выложить кусочки брынзы и посыпать орешками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (354,'Оливковое масло смешать с лимонным соком и медом. Этой заправкой полить салат.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (355,'Нарезать ветчину и обжарить ее на сильном огне с двух сторон до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (355,'Авокадо очистить и нарезать дольками. Сбрызнуть соком лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (355,'Грушу нарезать на дольки, выложить на сковороду, где готовилась ветчина. На груши выложить крупнозернистую горчицу и обжаривать на среднем огне 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (355,'Листья салата нарвать, добавить ветчину, авокадо, груши и полить оливковым маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (356,'Перемолола мясо (у меня свинина) в фарш, добавила молотый лук, соль, перец черный молотый и все хорошо перемешала.','https://vkuso.ru/data/cache/data/09/ef089705225e209_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (356,'Затем мелко порезала капусту и добавила к мясу. Отварила рис до готовности и так же добавила его в фарш. И приступила к формированию голубцов.','https://vkuso.ru/data/cache/data/95/c58fca1d6b37795_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (356,'Из фарша сделала продолговатые котлетки, немного обжарила их с двух сторон на подсолнечном масле без запаха. Жареные голубцы сложила в широкую сковороду.','https://vkuso.ru/data/cache/data/b6/30055e9a1b705b6_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (356,'Порезала 1 среднюю луковицу, натерла на терке 1 среднюю морковь, пожарила до готовности, а затем добавила к ним томатный сок. Тушила все вместе  2 минуты.','https://vkuso.ru/data/cache/data/4b/55ea7e11e94354b_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (356,'Залила голубцы подготовленным соусом и тушила на маленьком огне под закрытой крышкой минут 15.','https://vkuso.ru/data/cache/data/0b/7187825a5de0f0b_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (357,'Лук репчатый нарезаем соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (357,'Помидоры нарезаем ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (357,'Пекинскую капусту нарезаем соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (357,'Сыр натираем на мелкой терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (357,'Тонкий лаваш нарезаем на равные части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (357,'Куриное бедро нарезаем кубиком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (357,'Малосольные огурцы нарезаем полу кружочками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (357,'Соус: В глубокую тарелку, добавляем 2 ч.л кетчупа 4 ч.л сметаны, соль, перец по вкусу . 2 зуб.чеснока. Все перемешиваем и убираем в сторону, что бы соус настоялся.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (357,'Далее: Куриное мясо обжариваем готовности до небольшой корочки. как только обжарили перекладываем на тарелку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (357,'На подготовленный лаваш, намазываем соусом, укладываем немного пекинской капусты, пару долек помидора, немного кур.мяса, лук репчтаый,, малосольные огурцы и сыр, И все это заворачиваем как шаверму.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (357,'Далее, на гриле или сковородке обжариваем шаверму до небольшой корочки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (358,'Соус. Смешиваем чеснок, соевый соус, мед и кунжут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (358,'Маринад. Смешиваем соль, перец черный молотый, копчёную паприку и растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (358,'Чистим, потрошим, моем пеленгаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (358,'Нарезаем на стейки толщиной 2-2.5 сантиметра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (358,'Смазываем рыбу маринадом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (358,'Нанизываем на шампура и жарим на углях по 5 минут с каждой стороны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (358,'Смазываем рыбу соусом и жарим ещё по 2 минуты с каждой стороны.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (358,'Гарнир. Смешиваем сливочное масло, чеснок. зелень петрушки, зелень укропа и соль.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (358,'Выкладываем на фольгу картофель, шампиньоны и смазываем маслом с чесноком, зеленью и солью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (358,'Жарим на углях 20-25 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (359,'Капусту тонко нашинковать. Огурцы разрезать на половинки вдоль и нарезать их тонкими дольками.  В салатник выложить капусту, огурцы, кукурузу, сметану и зелень. Посолить, перемешать. Простой салат из капусты, кукурузы и огурцов готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (360,'Отделить белки от желтков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (360,'Немного посолить и белки, и желтки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (360,'Перемешать желтки до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (360,'Белки взбить миксером до устойчивых пиков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (360,'Глубокую сковородку поставить на медленный огонь. Добавить сливочное масло и растопить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (360,'Сверху вылить желтки. Обжарить 1-2 минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (360,'Когда желтки схватились, выложить белок, распределив его по всей поверхности. Жарить 7 минут на медленном огне под закрытой крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1910,'Духовку прогреть до 220 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (360,'Выложить на тарелку, разрезать омлет на две половины. Одну половину уложить на другую так, чтобы соприкасались белки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (360,'Пышный омлет на сковороде готов! Всем приятного аппетита! Больше кушайте, никого не слушайте!.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (361,'Некрупным кубиком нарезать отварные яйца и огурец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (361,'Нашинковать петрушку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (361,'Слить воду с консерв.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (361,'Смешать все в одной миске, посолить и заправить майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (362,'Разогрейте духовку до 190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (362,'Масло с молоком подогрейте в микроволновке до растворения масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (362,'Взбейте яйца с сахаром и ванильным сахаром до состояния светлой лёгкой массы. В миску всыпьте 1/3 просеянной муку с разрыхлителем. Аккуратно вмешайте муку в яичную смесь, затем добавьте половину молочно-сливочной жидкости, затем половину от оставшейся муки, оставшуюся жидкость и муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (362,'Наполните тестом форму диаметром 23 см смазанную маслом',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (362,'Выпекайте 25-30 минут, почти до полной готовности (не открывайте духовку особенно первые 20 минут, иначе, бисквит осядет).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (362,'Для топпинга поместите все ингредиенты в кастрюлю и на слабом огне прогрейте до растворения сахара.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (362,'Достаньте тор из духовки. Аккуратно полейте топпингом сверху. Верните в духовку. Прибавьте температуру до 200 градусов. Выпекайте ещё 5-10 минут. Перед подачей дайте торты хорошо остыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (363,'Пропустить через мясорубку куриное филе и лук.','https://vkuso.ru/data/cache/data/92/22042333fd6ea92_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (363,'Измельчаем крабовые палочки (можно на терке, можно ножом).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (363,'Измельчаем зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (363,'Готовим фарш: смешиваем все измельченные ингредиенты, добавляем яйцо, овсяные хлопья и специи. Все тщательно перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (363,'Отбиваем фарш, чтобы масса уплотнилась и оставим минут на 20.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (363,'Котлеты формируем влажными руками и обжариваем с 2 сторон до золотистой корочки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (364,'Готовим крем: смешиваем желтки с сахаром. Добавляем 0,5 стакана молока, муку и крахмал. Взбиваем миксером до однородности. Молоко доводим до кипения и постоянно помешивая добавляем приготовленную массу. Варим крем помешивая венчиком пока он не загустеет. Оставим крем остыть.','https://vkuso.ru/data/cache/data/16/cf492462b1eee16_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (364,'Размягченное сливочное масло взбиваем миксером, постепенно добавляем к нему остывший крем. Должна получиться пышная масса. Вмешиваем в крем кокосовую стружку (4 ст.л. оставляем для обсыпки торта).','https://vkuso.ru/data/cache/data/71/9f37407d25ed871_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (364,'Дно формы смазываем кремом (можно использовать кулинарное кольцо). Чередуем слои печенья с кремом. Верхним слоем должен быть крем. Накрываем пищевой пленкой и отправляем в холодильник на ночь.','https://vkuso.ru/data/cache/data/1a/138ff8cf928491a_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (364,'Украшаем верх торта и бока кокосовой стружкой. Для украшения я еще использовала конфеты (можно брать Франческа или Рафаэлло, но это совсем необязательно).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (365,'Мисо-пасту взбить на сковороде, влить порциями рыбный бульон, суп довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (365,'Добавить мелко накрошенный имбирь и перец чили, листья кафферлайма.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (365,'Выложить на сковороду с соусом филе лосося, кожей вниз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (365,'Время приготовления восемь или десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (365,'Рыбу поливать мисо-соусом, огонь – медленный.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (365,'Нарезать тонкими полосками листья Пак Чой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (365,'Брокколи разрезать пополам.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (365,'Готовую рыбу вынуть из соуса, довести его до кипения еще раз.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (365,'В кипящий соус выложить капусту брокколи, через тридцать секунд – стебли Пак Чой, затем, через две минуты, листья.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (365,'Варить соус минуту, перед подачей положить грибы эноки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (365,'Лосось очистить от кожицы, нарезать кусочками.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (365,'Тарелки смазать маслом кунжута, выложить рыбу, вторую половину грибов эноки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (365,'Залить блюдо готовым овощным супом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (366,'Говядину нарезать соломкой и замариновать в соевом соусе, время – от десяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (366,'Стручковую фасоль обжарить на масле с добавлением того же соевого соуса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (366,'Помидоры черри разрезать на четвертинки, обжарить на той же сковороде, фасоль переложить в тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (366,'Мясо обжарить вместе с маринадом, продукт можно потушить под крышкой до полной готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (366,'Приготовить соус из растительного масла, соевого соуса, дижонской горчицы и лимонного сока.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (366,'Выложить на тарелку листья зеленого салата, черри, фасоль, говядину.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (366,'Соль и перец молотый – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (366,'Полить заправкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (366,'Мягкий сыр нарезать кубиками, выложить сверху, подать блюдо на стол.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (367,'Салат выкладывается слоями, при этом каждый слой слегка смазывается майонезом. Первым слоем выложить лук, мелко порезанный кубиками. Лук нужно перед этим обдать кипятком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (367,'Вторым слоем выложить вареный картофель, нарезанный кубиками.  Затем нарезанную куриную грудку. Желательно взять копченую или гриль. Посыпать тертым грецким орехом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (367,'Выложить сверху вареную морковь, порезанную кубиками. Шестым слоем выложить вареное яйцо, мелко покрошенное или натертое на терке. Заключительный слой – тертый сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (367,'В качестве украшения выложить плотным слоем зерна граната. Оставить слоеный салат «Красная Шапочка» с куриной грудкой в холодильнике минимум на час, чтобы все слои пропитались майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (368,'Приготовить заправку из растительного масла, соевого соуса, винного уксуса, рубленого чеснока, зелени.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (368,'Взбить ингредиенты блендером, дать постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (368,'Мясную вырезку полить маслом, обжарить на прогретой сковороде в течение четырех минут, один раз перевернуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (368,'Оставить продукт на пять или десять минут для остывания, затем тонко нарезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (368,'На той же сковороде обжарить измельченный лук-порей или репчатый.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (368,'Отдельно обжарить шампиньоны, нарезанные пластинками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (368,'Перец молотый и соль добавлять по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (368,'Выложить на блюдо листья зеленого салата, на них – мясную соломку, лук и грибы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (368,'Полить блюдо заправкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (369,'Влить воду в кастрюлю, довести до кипения, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (369,'Рис перебрать, промыть, залить кипящей водой, дать постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (369,'Промыть холодной водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (369,'В закипевшую воду всыпать рис, готовить двадцать минут под крышкой в духовом шкафу. Температура – 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (369,'Налить на сковороду немного оливкового масла, положить кусочек сливочного.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (369,'Изюм отцедить, выложить на сковороду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (369,'Прогревать пять минут, помешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (369,'Добавить сахарный песок и немного воды, прогреть, подержать на тихом огне две минуты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (369,'Готовую кашу вынуть из духовки, влить изюм с маслом со сковороды, перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (370,'Промыть рис, вода должна стать прозрачной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (370,'Вскипятить воду в кастрюле, подсолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (370,'Выложить рис, варить до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (370,'Готовый продукт промыть холодной водой, слить жидкость.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (370,'Сухофрукты залить кипящей водой, оставить на пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (370,'Воду слить, плоды порезать кусочками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (370,'Всыпать в рис.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (370,'Приготовить сироп.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (370,'Сахар и мед перемешать, развести водой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (370,'Перемешать все ингредиенты.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (370,'Подать кутью в небольших тарелочках или пиалах.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (371,'Фрикадельки. Добавляем в фарш половину сладкого перца, зелень петрушки, зелень укропа, зеленый лук, три отварных яйца, два сырых яйца, чёрный молотый перец, красный острый перец и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (371,'Хорошо перемешиваем и формируем фрикадельки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (371,'Добавляем в казан 150 грамм растительного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (371,'Добавляем лук и обжариваем 2-3 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (371,'Добавляем морковь, сладкий перец и обжариваем 2-3 минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (371,'Добавляем томатную пасту, черный молотый перец, красный острый перец, соль и тушим 5 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (371,'Добавляем картофель и воду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (371,'Когда вода закипит, добавляем фрикадельки и варим до готовности картофеля.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (371,'Добавляем щавель, отварные яйца, соль и варим ещё 5 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (371,'Добавляем зелень. Готовьте с удовольствием и приятного аппетита!
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (372,'Кабачки нарезать на кружки шириной в полсантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (372,'В одну тарелку добавить муку, соль, перец. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (372,'В другую тарелку разбить яйца. Добавить соль и перец. Перемешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (372,'На сковороду добавить растительное масло и разогреть ее.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (372,'Кабачки обвалять в муке, а затем окунуть в яичную смесь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (372,'Выложить на сковороде в один слой. Жарить на медленном огне по 4 минуты с каждой стороны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (372,'Повторить с оставшимися кабачками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (372,'Приготовить соус. К сметане добавить измельченный чеснок и порезанный укроп. Перемешать. Кабачки в кляре готовы. Можно подавать к столу вместе с соусом!',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (373,'Промыть рис.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (373,'Всыпать в чашу мультиварки, влить воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (373,'Выставить режим «Каша» на двадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (373,'Залить изюм кипящей водой на пять минут, добавить ванильный и обычный сахар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (373,'Смесь всыпать в готовый рис, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (373,'Влить немного молока или воды, выставить режим «Подогрев» на пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (374,'Рис промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (374,'Выложить в кастрюлю, залить водой, варить под крышкой в течение трех минут. Огонь – сильный.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (374,'Температуру уменьшить до средней, варить еще шесть минут, дать постоять – пятнадцать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (374,'Чернослив обдать кипящей водой, дать постоять под крышкой до разбухания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (374,'Воду отжать, чернослив нарезать небольшими кусочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (374,'Разбавить мед водой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (374,'Добавить в пропаренный рис вместе с черносливом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (374,'Ингредиенты перемешать, кутью подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (375,'Отварить рис до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (375,'Орехи и изюм залить кипящей водой, оставить на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (375,'Воду слить, продукты отжать, измельчить при помощи ножа или блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (375,'Смесь всыпать в рис.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (375,'Добавить мед, ингредиенты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (376,'Соединить в миске сырое яйцо, соль, молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (376,'Все вместе взбить при помощи миксера в пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (376,'Всыпать молотые овсяные хлопья, ванилин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (376,'Смесь должна постоять пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (376,'Приготовить пюре из спелого банана при помощи блендера или вилки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (376,'Вмесить продукт в тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (376,'Массу вылить на прогретую сковороду с антипригарным покрытием. Время выпекания блина – около двух минут, огонь – средний.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (376,'Блин перевернуть и допечь с другой стороны.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (376,'Огонь убавить. Подать к столу теплым.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (377,'Сырые куриные яйца взбить с сахарным песком при помощи вилки, миксера или венчика. Масса должна быть однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (377,'Всыпать измельченные овсяные хлопья, добавить пюре из банана, ванилин, кефир, творог.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (377,'Ингредиенты перемешать, оставить на несколько минут: хлопья должны набухнуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (377,'Прогреть сковороду, выложить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (377,'Блин обжарить с двух сторон по две минуты до появления румяной корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (378,'Крупно режем шпинат. Режем клубнику.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (378,'Бланшируем миндаль, если на нем есть шкурка. И потом натираем в форме "лепестков".',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (378,'Мелко нарезаем лук и руколу если есть (она придает хороший вкус).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (378,'Перемешиваем все зеленые ингредиенты и солим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (378,'На шпинат выкладываем клубнику, посыпаем миндалем, посываем сыром и заправляем соусом (я использую малиновый бальзамический соус).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (379,'Все ингредиенты кроме ягод хорошо перемешиваем  и выкладываем в форму для запекания, лучше всего использовать силиконовую.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (386,'Ингредиенты перемешать, блюдо подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (379,'Затем по верх нашей запеканки раскладываем ягоды(можно использовать любые) и отправляем в духовку на 1 час при температуре 190°С',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (380,'Все ингредиенты измельчить с помощью мясорубки.  Добавить лимонный сок и мед. Тщательно перемешать и убрать в холодильник настояться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (381,'Готовим тесто. Соединить муку пшеничную и гречневую, добавить соль, соду. Растопить сливочное масло и влить его в смесь муки, добавить теплую воду. Замесить тесто и оставить на 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (381,'Подготовим начинку. Помидоры нарезать кружочками. Моцареллу нарезать кружочками, а кружочки разрезать на 2-4 части.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (381,'На бумаге для выпечки раскатать круглое тесто, диаметром 28 см. Выложить кружочки помидоров внахлест, чередуя их с кусочками сыра отступив от краев по 3-4 см. Смазать чесночным. Помолоть душистый перец горошком, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (381,'Края теста загибаем на начинку, укладывая их внахлест. Перенести бумагу с галетой на противень. Отправляем в духовку выпекаться при температуре 180 градусов 25 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (382,'Курицу нарезать кусочками (можно отварить целиком, а потом нарезать кусочками, когда она будет готова), отправить в кастрюлю и залить водой. Ставим на огонь, доводим до кипения и варим 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (382,'Картофель очистить и нарезать небольшими кубиками, добавить в кастрюлю с курицей. Доводим до кипения и готовим еще 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (382,'Лук очистить нарезать крупными кубиками, морковь очистить и нарезать тонкой соломкой. В сковороде с растительным маслом на сильном огне обжариваем лук с морковью в течении 5 минут, перемешивая. Затем отправляем в кастрюлю с супом и готовим еще 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (382,'Щавель тонко порезать и отправить в кастрюлю, посолить и поперчить, накрыть крышкой, готовим 3 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (382,'Отварить яйца и очистить от скорлупы. Суп разлить по тарелкам и выложить в каждую тарелку по половине яичка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (383,'Нарезаю морковь соломкой и лук мелким кубиком. Степень нарезки, можете регулировать самостоятельно, но мне нравится, когда овощи чувствуются в блюде. Куриное филе режем маленькими кусочками и обжариваем на оливковом масле. В процессе обжаривания добавляем лук и морковь. Обжариваем все вместе около 5-7 минут.','https://vkuso.ru/data/cache/data/60/f66a849e7fb7e60_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (383,'Добавляем специи по вкусу, у меня соль и смесь перцев. Томатную пасту разводим в 150 мл воды и вливаем в сковороду. Накрываем крышкой и даем потушиться минут 10, периодически помешивая. Добавляем птитим, перемешиваем и вливаем 2 стакана воды (емк.200 мл). Накрываем крышкой и на медленном огне оставляем на 20 минут, периодически открываем крышку и помешиваем.','https://vkuso.ru/data/cache/data/17/d71e7766ecaec17_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (383,'Готовое блюдо посыпаем зеленью. Всем вкусных обедов!','https://vkuso.ru/data/cache/data/e2/e05e4d109c71ce2_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (384,'Воду довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (384,'В стеклянную банку всыпать овсяные хлопья.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (384,'Влить кипяток.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (384,'Составляющие перемешать, оставить для набухания на шесть или семь минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (384,'Всыпать сушеную вишню, чернику, клюкву в любом сочетании.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (384,'Добавить очищенные миндальные орехи, молотую корицу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (384,'Блюдо должно постоять под крышкой несколько минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (385,'Овсяные хлопья прогреть на сковороде в течение трех или четырех минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (385,'На дно стеклянной банки всыпать овсянку, влить воду комнатной температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (385,'Время набухания – от двенадцати до четырнадцати минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (385,'Выложить йогурт сверху, не перемешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (385,'Далее – слой нарезанных фруктов, ягоды. Можно использовать персики, клубнику.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (385,'Смесь поставить в прохладное место на ночь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (385,'Подать к завтраку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (386,'Овсяные хлопья всыпать в банку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (386,'Влить кленовый сироп, смесь лимонного и лаймового сока. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (386,'Влить закипевшее молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (386,'Выложить слой нарезанного кусочками нектарина, косточку и кожицу удалить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (386,'Посыпать кашу рубленым миндалем и зеленью мяты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (387,'Перемешать овсяные хлопья, какао.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (387,'Высыпать в банку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (387,'Залить смесью кефира с медом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (387,'Ингредиенты перемешать, дать постоять в течение ночи в прохладном месте.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (387,'Натереть горький шоколад, посыпать готовую кашу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (388,'Насыпать овсяные хлопья в банку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (388,'Залить смесью молока с натуральным йогуртом и медом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (388,'Емкость закрыть крышкой, встряхнуть, чтобы ингредиенты перемешались.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (388,'Очистить и нарезать банан, добавить в банку, еще раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (388,'Оставить в прохладном месте на восемь часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (388,'Подать охлажденным.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (389,'Овощи отвариваем до полной готовности. и остужаем их.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (389,'Чистим отварные овощи (картошку, морковь, свеклу) и нарезаем их небольшим кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (389,'Мелко нарезаем луковицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (389,'Зеленый лук и укроп мелко нашинкуем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (389,'В миску выкладываем нарезанную свеклу и добавляем в нее немного растительного масла, перемешаем (это нужно если вы хотите чтобы остальные овощи в салате не окрасились от свеклы, так все ингредиенты в салате останутся своим естественным цветом).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (389,'Добавляем к свекле все остальные нарезанные ингредиенты и квашеную капусту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (389,'Заправляем салат растительным маслом и солим по своему вкусу. Все хорошо перемешиваем и можно подавать его на стол гостям.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (390,'Пересыпаем кокосовую стружку в большую миску, добавляем около 100 грамм сгущенного молока, и все хорошо перемешиваем. (Лично у меня сгущенка с клубничным вкусом)',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (390,'Далее, добавляем 15 грамм сливочного масла, и снова перемешиваем. Масса десерта не должна быть сыпучей, надо так что бы получались шарики)',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (390,'Катаем из кокосовой массы шарики, и обсыпаем их в какао порошке, перекладываем на тарелку и можно отправить их холодильник на 10 мин, чтобы они охладились!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (391,'Крупу «Геркулес высыпать в банку, влить молоко, йогурт без добавок, натуральный мед. Все ингредиенты должны быть комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (391,'Если мед слишком густой – его можно растопить в микроволновой печи или на водяной бане.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (391,'Очистить спелый апельсин, удалить косточки и кожицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (391,'Мякоть нарезать кусочками среднего размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (391,'Добавить в банку, закрыть и потрясти, чтобы продукты перемешались.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (391,'Поставить на ночь в прохладное место.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (392,'В банку всыпать хлопья овсянки, добавить джем из апельсина, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (392,'Влить смесь молока и йогурта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (392,'Положить мед, кусочки мандаринов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (392,'Кашу перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (392,'Оставить под крышкой на ночь в прохладном месте.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (393,'Перемешать овсяные хлопья с ванилином.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (393,'Залить смесью йогурта и молока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (393,'Ингредиенты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (393,'Добавить вишню без косточек, натертый горький шоколад.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (393,'Перемешать еще раз.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (393,'Емкость накрыть крышкой и поставить на ночь в прохладу для настаивания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (393,'Кашу можно посыпать дополнительной порцией тертого шоколада, украсить свежими ягодами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (394,'Теплый кефир (температурой 28–30 градусов) смешать с содой, солью, сахаром. Дать постоять 1 минуту. В кефир добавить муку, при этом постоянно размешивая, чтобы не было комочков. Консистенция теста должна быть похожа на домашнюю сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (394,'Мясной фарш смешать с луком, чесноком, солью и перцем. В тесто выложить мясной фарш в пропорции 1:1. Тщательно перемешать и жарить ленивые мясные беляши на горячей сковороде с толстым слоем растительного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (395,'Спелые помидоры и сыр «Моцарелла» нарезать ровными кружками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (395,'Выложить продукты на блюдо, чередуя кружки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (395,'Украсить листочками базилика, всыпать специи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (395,'Полить оливковым маслом и бальзамическим уксусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (396,'Прогреть духовой шкаф.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (396,'Нарезать ломтиками помидоры, выложить на противень, застеленный пергаментом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (396,'На каждый помидор положить тертый сыр «Пармезан» и «Моцареллу».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (396,'Нарезать базилик, посыпать сверху.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (396,'Побрызгать оливковым маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (396,'Время выпекания – десять минут, до расплавления сыра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (396,'Духовку выключить, подержать противень с помидорами еще три минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (396,'Подать сразу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (397,'Помидоры вымыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (397,'Отцедить от рассола сыр «Моцарелла».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (397,'Продукты нарезать кружками, разложить внахлест на двух тарелках.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (397,'Полить соусом «Песто», выложить листочки базилика.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (397,'Сбрызнуть оливковым маслом, бальзамическим уксусом, посыпать специями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (398,'Помидоры разрезать пополам, выложить в емкость с базиликом и сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (398,'Добавить специи, оливковое масло и бальзамический уксус, подержать под крышкой в прохладном месте для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (399,'Для приготовления закуски в виде пингвинов очистить и нарезать кружками и треугольниками морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (399,'Разрезать вдоль крупные маслины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (399,'Вложить в них по маленькому шарику сыра «Моцарелла».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (399,'Наколоть на шпажку маслину небольшого размера, присоединить крупную с сыром и морковью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (399,'Вложить в маленькую маслину треугольник из моркови в виде пингвиньего носа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (400,'Налить майонез в кондитерский шприц.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (400,'У небольших помидоров срезать верхушки, положить внутрь кусочек «Моцареллы».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (400,'Нанизать вместе с кружочком моркови и петрушкой на шпажку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (400,'На помидор нанести капельки майонеза, при подаче украсить луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (400,'Для приготовления закуски в виде божьей коровки: отрезать у помидоров черри верхушки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (400,'Маслину разрезать пополам, вторую половину покрошить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (400,'Снять с помидора кожицу, в углубление положить накрошенные маслины.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (400,'Помидоры надрезать вдоль, вложить по кусочку «Моцареллы», наколоть на шпажки с половинками маслин и базиликом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (400,'Глаза нарисовать майонезом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (401,'Помидоры нарезать ломтиками, выложить в стеклянную емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (401,'Перемешать оливковое масло с красным винным уксусом, специями, нарезанными листочками базилика, давленым чесноком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (401,'Потрясти смесь в плотно закрытой посуде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (401,'Залить помидоры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (401,'Накрыть, поставить в холод на три часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (401,'Выложить закуску на тарелку с салатной зеленью вперемешку с нарезанным сыром «Моцарелла».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (402,'Щавель моем и обсушим, отрезаем толстые ножки при необходимости и мелко его нарезаем. Смешиваем в миске щавель с сахаром и перемешиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (402,'Размороженное слоеное дрожжевое тесто разрезаем на порционные кусочки для пирожков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (402,'Раскатываем нарезанное тесто и выкладываем в серединку необходимое количество начинки. Формируем пирожки, защипнув края.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (402,'На противень застеленный пергаментной бумагой выкладываем пирожки и отправляем в духовку на 5 минут при температуре 50 градусов ( чтобы дрожжевое тесто поднялось), затем переключаем температуру на 200 градусов и выпекаем 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (403,'Смешиваем соль, копчёную паприку, черный молотый перец, сушеный базилик и растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (403,'Начинка.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (403,'Чистим, потрошим, моем щуку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (403,'Наполняем брюшко начинкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (403,'Делаем надрезы на спине щуки и вставляем лимон и помидор.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (403,'Смазываем щуку маринадом и жарим на углях по 10 минут с каждой стороны. Готовьте с удовольствием и приятного аппетита!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (404,'Кефир и муку перемешать. Должно получиться немного жидкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (404,'Перелить тесто в кондитерский мешок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (404,'В сотейнике разогреть растительное масло до 180°С.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (404,'Отрезать кончик у кондитерского мешка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (404,'В сотейник выдавить тесто небольшими горошинами по 1 см и отрезать ножницами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (404,'Жарить до золотистого цвета.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (404,'Пончики перенести в тарелку с салфетками, чтобы стекло лишнее масло.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (404,'При подаче пончики обильно полить любимым сиропом или посыпать сахарной пудрой. Мгновенные пончики готовы! Приятного аппетита! Больше кушайте, никого не слушайте!',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (405,'Измельчить в блендере все ингредиенты за исключением рыбы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (405,'Готовой хлебной крошкой покрываю сверху рыбу и запекаю в духовке при 180°С в течении 20-25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (406,'Смешайте масло с яйцом, сахаром и растопленным сливочным маслом до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (406,'Добавьте кефир, перемешайте снова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (406,'Всыпьте муку, смешанную с ванилином и разрыхлителем. Замесите тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (406,'Присыпьте стол мукой. Сразу поставьте сковородку с маслом нагреваться. Тесто раскатайте толщиной примерно в 1 см. С помощью двух стаканов разного диаметра сделайте пончики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (406,'В горячее масло выкладывайте пончики, обжаривайте их с двух сторон до румяного цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (406,'Готовые пончики снимите со сковороды, бумажными салфетками удалите излишки жира. Остудите пончики, и можно подавать к столу. Приятного аппетита!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (407,'Отварите вкрутую куриные яйца.','https://vkuso.ru/data/cache/data/b4/e1bd0ca652debb4_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (407,'Нарежьте ветчину соломкой.','https://vkuso.ru/data/cache/data/e4/20370e717d6a1e4_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (407,'Нарежьте свежие огурцы соломкой.','https://vkuso.ru/data/cache/data/f5/2c810d5e7211df5_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (407,'Твердый сыр натрите на терке.','https://vkuso.ru/data/cache/data/3f/b0f14252dff153f_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (407,'Предварительно очищенные куриные яйца натрите на терке.','https://vkuso.ru/data/cache/data/94/c4d3e723b859e94_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (407,'Смешайте в салатнике все ингредиенты.','https://vkuso.ru/data/cache/data/62/b031423e113ce62_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (407,'Добавьте черный молотый перец по вкусу.','https://vkuso.ru/data/cache/data/45/55ad69d0ef87945_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (407,'Добавьте соль по вкусу.','https://vkuso.ru/data/cache/data/27/d3cfe2b0c673827_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (407,'Заправьте салат сметаной.','https://vkuso.ru/data/cache/data/c2/927d9d439802dc2_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (407,'Пропустите через пресс или натрите на мелкой терке чеснок и добавьте в салат.','https://vkuso.ru/data/cache/data/e6/b2eba926b0f43e6_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (407,'Тщательно перемешайте салат.','https://vkuso.ru/data/cache/data/e3/0279de869689ee3_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (407,'Салат "Неженка" готов! Приятного аппетита!','https://vkuso.ru/data/cache/data/74/a820bc851d1e974_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (408,'Сыр «Моцарелла» разрезать на половинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (408,'Полить оливковым маслом, оставить для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (408,'Помидоры черри разрезать пополам, вынуть мякоть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (408,'Сбрызнуть бальзамическим уксусом, присыпать специями, положить по кусочку сыра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (408,'Закуску украсить листочками свежего базилика.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (409,'Помидоры черри разрезать пополам, мякоть авокадо – кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (409,'Выложить ингредиенты в миску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (409,'Добавить кусочки свежего сыра «Моцарелла» вместе с порванными листочками базилика.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (409,'Приготовить заправку из бальзамического уксуса, оливкового масла, меда, специй, рубленого чеснока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (409,'Залить салат, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (410,'Срезать с помидоров верхушки, вынуть мякоть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (410,'Перемешать ее со специями и сыром «Моцарелла».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (410,'Нафаршировать помидоры, украсить веточками базилика, побрызгать оливковым маслом, накрыть срезанными верхушками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (410,'Печь в духовом шкафу в течение восьми минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (411,'Перемешать разрезанные красные и желтые помидоры черри, кубики авокадо, рубленый базилик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (411,'Взбить оливковое масло с бальзамическим уксусом, и медом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (411,'Залить салат, посыпать специями, солью, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (411,'Сверху выложить шарики сыра «Моцарелла».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (412,'Очищенный картофель нарезать тонкой соломкой. Убрать лишний крахмал с картофеля, промыв его холодной водой. Обсушить воду салфетками или бумажными полотенцами. Картофель обжарить до золотистого цвета во фритюре или на сковородке с высокими бортиками и большим количеством масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'Сыр «Эмменталь» нарезать прямоугольными ломтиками, «Горгонзол» – кубиками, «Моцареллу» – полукругами, «Пармезан» натереть.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (412,'Каждую порцию картофеля вынуть шумовкой на бумажное полотенце, чтобы стекло масло.  На большое блюдо разложить половинки помидор. Сверху смазать соусом из сметаны, майонеза и раздавленного чеснока. Вторым слоем выложить порезанную соломкой ветчину или колбасу. Нанести соус сверху.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (412,'Посыпать тертым сыром, вновь намазать соусом. Сверху салата выложить картофель фри. Чтобы салат «Блондинка» с ветчиной хорошо пропитался, дать ему постоять в холодильнике 30–40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (413,'В емкость кухонного комбайна выложить часть помидоров, листья свежего базилика, чеснок, влить оливковое масло, соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (413,'Массу взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (413,'Выложить на противень ломтики брускетты, подержать в духовом шкафу три минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (413,'Хлеб должен зарумяниться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (413,'Натереть ломтики чесноком, положить по кусочку сыра «Моцарелла».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (413,'Поставить в духовку на минуту, сыр должен растаять.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (413,'Выложить на бутерброды томатную смесь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (413,'Украсить ломтиками свежих помидоров.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (414,'В небольшую кастрюлю налить воды и довести до кипения. В кипящую воду отправить куриное филе нарезанное тонкими кусочками (толщиной не более 0,5 см), варить 8 минут. Достать из кастрюли и остудить. Нарезать кусочками, какими пожелаете.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (414,'Черешню промыть и отделить от косточек. Листья салата промыть. Отделить листики мяты от стебля, стебель выкинуть, а листики мелко нарубить ножом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (414,'Готовим заправку. В пиалу выдавить из лимона сок, добавить оливковое масло и клубнику очищенную от хвостиков. Перемешать, при этом клубнику раздавить до состояния пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (414,'В тарелку нарвать листья салата, заправить клубничной заправкой, перемешать. Посыпать мятой, выложить черешню и кусочки курицы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (415,'Приготовить маринад из оливкового масла, давленого чеснока, рубленого базилика, петрушки, орегано, красного винного уксуса, рубленого красного перца, других специй.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (415,'Перемешать с сыром «Моцарелла», накрыть пленкой, оставить на сутки в холоде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (415,'Проварить на сковороде бальзамический уксус на среднем огне, охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (415,'Перемешать маринованный сыр с помидорами черри, сбрызнуть маринадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (415,'Соль – по вкусу, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (415,'Побрызгать приготовленным соусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (416,'Приготовить заправку из оливкового масла, бальзамического уксуса, чеснока, специй.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (416,'Половину нарезанного свежего огурца поместить в овальное блюдо для салатов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (416,'Часть огурцов перемешать с помидорами черри, нарезанным кубиками авокадо, сыром «Моцарелла».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (416,'Салат полить заправкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (417,'Свежие зерна кукурузы вырезать из початка, добавить помидоры черри, сыр «Моцарелла», посыпать рубленым базиликом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (417,'Приготовить заправку из свежего лимонного сока, чеснока, оливкового масла, перца и соли.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (417,'Перемешать, полить салат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (418,'Приготовить киноа так, как указано на упаковке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (418,'Добавить нарезанные помидоры черри, сыр «Моцарелла», листочки базилика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (418,'Приготовить заправку из винного уксуса, сахара, специй, оливкового масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (418,'Полить салат, поставить в холод для пропитывания в герметично закрывающейся емкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'Для приготовления теста перемешать муку, дрожжи и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'Залить ингредиенты теплой водой, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'Добавить оливковое масло, продолжать вымешивать массу до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'Дать постоять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'Для соуса надрезать крестом большой помидор, залить кипящей водой и снять кожицу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'Мякоть натереть на мелкой терке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'Добавить в массу соль, специи, оливковое масло.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'Перемешать до однородного состояния.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'Для начинки понадобятся помидоры черри, сыры «Эмменталь», «Моцарелла», «Пармезан», «Горгонзол», базилик.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'Тесто раскатать в тонкую лепешку, смазать томатным соусом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (424,'Нарезать несколько помидоров и четыре вида сыра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'На соус выложить ломтики «Эмменталя», посыпать «Пармезаном».',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'Далее выложить «Горгонзол» и «Моцарелу».',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'Ломтики помидора, базилик.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (419,'Время выпекания – десять минут, температура – 220 градусов.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (420,'Яйца отвариваем и остудив нарезаем их.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (420,'Нарезаем крабовые палочки и помидоры так как вам больше нравиться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (420,'Зелень мелко нашинкуем (я взяла зеленый лук и укроп).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (420,'Чеснок почистим и мелко его нарежем или пропустим через чеснокодавку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (420,'В миску выкладываем консервированную белую или красную фасоль. Добавляем все нарезанные ингредиенты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (420,'Заправляем салат майонезом и про необходимости подсолим. Перемешиваем хорошо и наш салат готов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'В миску вливаем 250 мл кефира.','https://vkuso.ru/data/cache/data/6e/67584d0b840e66e_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'Добавляем 0,5 ч. ложки соды.','https://vkuso.ru/data/cache/data/8c/9077da74d9cbd8c_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'0,5 ч. ложки соли.','https://vkuso.ru/data/cache/data/08/591bc1c56c3fa08_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'1 ст. ложку сахара.','https://vkuso.ru/data/cache/data/49/e8529617ce16149_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'Тщательно перемешиваем.','https://vkuso.ru/data/cache/data/b0/4f6d9dc398700b0_434x295_notrise.png',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'Добавляем 1 куриное яйцо.','https://vkuso.ru/data/cache/data/9d/6089f0ba2e2499d_434x295_notrise.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'2 ст. ложки растительного масла.','https://vkuso.ru/data/cache/data/df/7a51a6f9c4477df_434x295_notrise.png',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'Снова перемешиваем.','https://vkuso.ru/data/cache/data/f9/9e4ac606eb3bdf9_434x295_notrise.png',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'Затем просеиваем в смесь 450 гр пшеничной муки (муки может понадобится немного больше).','https://vkuso.ru/data/cache/data/2e/f8dd9bb3befd22e_434x295_notrise.png',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'Замешиваем тесто.','https://vkuso.ru/data/cache/data/04/a72be05f3802504_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'Рабочую поверхность присыпаем мукой и перелаживаем туда тесто. Разделяем тесто на несколько частей.','https://vkuso.ru/data/cache/data/74/16971743f6e6674_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'Формируем из кусочков теста шарики.','https://vkuso.ru/data/cache/data/9e/d730a3530d97e9e_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'Каждый кусочек теста раскатываем толщиной приблизительно 5-6 мм.','https://vkuso.ru/data/cache/data/53/659354d8079a053_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'Делаем посередине каждой лепешки небольшой разрез.','https://vkuso.ru/data/cache/data/de/cb5f41b2b3b7fde_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'Обжариваем на растительном масле на среднем огне.','https://vkuso.ru/data/cache/data/b7/5578996725b28b7_434x295_notrise.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'Обжариваем лепешки до золотистого цвета с обеих сторон.','https://vkuso.ru/data/cache/data/75/506ce1772194a75_434x295_notrise.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (421,'Лепешки на кефире готовы! Приятного аппетита!','https://vkuso.ru/data/cache/data/08/2279fbe9ffa3408_434x295_notrise.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (422,'Куриное филе отбить, немного посолить. Для начинки отварить вареные яйца. Натереть яйца и твердый сыр на крупной терке. Свежую зелень порезать и добавить в начинку. Чтобы начинка не рассыпалась, добавить жидкий плавленый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (422,'Положить на отбивные начинку, завернуть в рулетик. В форму налить немного масла, рулетики выложить в нее и поместить в духовку. Запекать фаршированные куриные рулетики в духовке 30 минут. Чтобы у них была аппетитная корочка, в конце посыпать тертым сыром и на 15 минут снова поставить в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (423,'Перемешать сухие дрожжи и муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (423,'Мед развести в воде и влить в общую массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (423,'Добавить оливковое масло и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (423,'Массу вымесить. Можно использовать кухонный комбайн. Тесто не должно липнуть к рукам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (423,'Сформовать шар, выложить в смазанную маслом емкость.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (423,'Прикрыть смоченным в теплой воде полотенцем, время выстойки – пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (423,'Разрезать массу на несколько частей, тонко раскатать, выложить на смазанный маслом противень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (423,'Натереть сыры «Моцарелла» и «Тильзитер».',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (423,'Козий сыр и «Горгонзоллу» поломать кусочками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (423,'Тесто посыпать «Моцареллой», выложить «Горгонзоллу» и козий сыр, засыпать тертым «Тильзитером».',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (423,'Побрызгать начинку оливковым маслом, украсить листочками тимьяна.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (423,'Время выпекания – десять минут, температура – 220 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (424,'Для пиццы понадобится дрожжевое тесто, его можно приготовить самостоятельно или купить в магазине.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (424,'Мультиварку включить в режим подогрева, выложить кусочек готового теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (424,'Тесто вынуть, раскатать, поместить в мультиварку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (424,'Выложить нарезанные и тертые сыры.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (424,'Сверху – кружочки помидоров, сушеные помидоры и приправы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (424,'Время выпекания – полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (425,'Муку смешать с сухими дрожжами, долить воду, перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (425,'Всыпать соль, влить растительное масло, вымесить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (425,'Поделить на части, каждый кусок накрыть тканью и оставить на некоторое время для выстойки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (425,'Приготовить соус из консервированных томатов, базилика, специй, оливкового масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (425,'Перемешать при помощи блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (425,'Тесто раскатать, лепешки выложить на смазанные маслом противни.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (425,'Смазать соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (425,'Нарезать кубиками сыры «Моцарелла» и «Горгонзола». Натереть «Эмменталь» и «Пармезан».',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (425,'Выложить начинку на заготовки, время выпекания – восемь минут, температура – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (426,'Для приготовления пиццы используются сыры «Эмменталь», «Моцарелла», «Пармезан» и «Горгонзола». Продукты можно заменить на подобные.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (426,'Приготовить ароматное масло из тертого чеснока и оливкового масла, ароматных трав.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (426,'Раскатать тесто на весь противень, выложить «Пармезан», сбрызнуть маслом с чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (426,'Выложить остальные сыры: твердые натереть, мягкие – нарезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (426,'Время выпекания – двадцать минут, температура – 190 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (427,'Всыпать в емкость соль, дрожжи, немного сахарного песка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (427,'Влить воду, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (427,'Влить оливковое масло, всыпать муку частями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (427,'Вымесить тесто руками, оно не должно прилипать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (427,'Оставить на час, затем разделить на несколько частей, раскатать лепешки скалкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (427,'Края должны быть немного толще середины.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (427,'Противень застелить бумагой для выпекания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (427,'Выложить лепешку, первый слой – сыр «Рикотта», затем – «Горгонзола» кусочками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (427,'Сыр можно поломать руками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (427,'Натереть «Пармезан», насыпать сверху.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (427,'Далее – сыр «Моцарелла», натертый или нарезанный ломтиками.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (427,'Время выпекания – пять минут, температура – 250 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (427,'Готовую выпечку вынуть из духовки, побрызгать оливковым маслом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (428,'Соус.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (428,'Кляр.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (428,'Панировка.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (428,'Гарнир.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (428,'Отбивные.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (429,'Измельчить в блендере печенье до мелкой крошки и добавить к нему масло. Все перемешать. Это будет основа. В форму, выложенную пищевой пленкой или бумагой для выпечки, выложить основу. Плотно утрамбовать ее, выровнять лопаткой, чтобы слой был ровный. Основу для чизкейка поставить в холодильник. Желатин залить холодной водой и оставить разбухать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (429,'Бананы размять в пюре, смешать с апельсиновым соком. Поставить смесь на огонь, нагреть до кипения, снять и немного остудить. Желтки взбить, постепенно подсыпая сахар, чтобы получилась пышная пена. Это займет примерно 10 минут. В желтки аккуратно ложкой или лопаткой ввести крем-сыр. Масса должна после этого остаться воздушной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (429,'В банановое пюре, которое уже немного остыло, добавить желатин, предварительно отжатый от воды. Размешать пока не растворится желатин.  Сливки охладить, взбить до устойчивых пиков. В банановое пюре выложить пару ложек сырной массы, размешать, потом также ввести остальной сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (429,'Добавить к бананово-сырной массе взбитые сливки, аккуратно размешать.  Достать основу их холодильника, выложить на нее суфле, разровнять лопаткой и поставить обратно в холодильник на 3–4 часа, чтобы полностью остыло. Для украшения выложить сверху на банановый чизкейк с сырным суфле тонкие ломтики банана и посыпать стружкой белого или обычного шоколада.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (430,'Смешиваем яйца, молоко и муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (430,'Режем помидору, зеленый лук, трем на терке сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (430,'Все ингридиенты хорошо перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (430,'Жарим наши оладушки на сковородке по 2 минуты с каждой стороны.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (431,'Помидоры промыть и нарезать колечками, если помидоры очень крупные, можно нарезать на 2-4 части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (431,'Маслины нарезать колечками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (431,'Фасоль промыть от жидкости из банки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (431,'Из тунца слить сок/масло и нарезать на кусочки или размять вилкой (как больше нравится).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (431,'Готовим заправку. Выдавить из лимона сок, добавить оливковое масло и прованские травы - перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (431,'Рукколу вымыть, сложить в миску и полить заправкой, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (431,'Разложить рукколу по тарелкам. Добавить в каждую тарелку по немногу фасоли, тунца, маслин, помидоров и кусочки сыра фета. Приправить свежемолотым черным перцем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (432,'Готовим тесто. Муку перетереть со сливочным маслом в крошку. Добавить сахар (1 ст.л.) и вбить яйцо (1 шт.) – замесить тесто, обернуть пленкой и убрать в холод минимум на 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (432,'Спустя 30 минут достаем тесто и распределяем его по форме для выпечки формируя борты (я слегка раскатала, а потом распределила руками по всей форме). Клубнику очистить от хвостиков и выкладываем на тесто (мелкую клубнику оставить целой, крупную – разрезать).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (432,'Готовим заливку. В миске перемешать при помощи миксера сметану с сахаром (130 гр). Добавить муку (3 ст.л.) снова перемешать при помощи миксера, вбить яйца (2 шт.) снова перемешиваем и заливаем этой смесью пирог с клубникой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (433,'Болгарский перец разрезать пополам и удалить семена.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (433,'Холодные плавленные сырки и морковь натереть на терке, чеснок пропустить через пресс и добавить майонез, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (433,'Этой смесью начинать перец и сверху посыпать измельченным укропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (434,'Перепелиные яйца отварить, затем очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (434,'Рыбу без жидкости выложить в тарелку, размять вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (434,'Помидоры нарезать дольками. Добавить к рыбе. Добавляем рукколу и перепелиные яйца (разрезать пополам).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (434,'Смешиваем оливковое масло, бальзамический уксус, выдавливаем сок из лимона, сушеный чеснок, перец, соль. И заправляем салат.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (435,'Мяту с сахаром измельчаем в блендере. Добавляем яйцо и сливочное масло, снова измельчаем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (435,'В миске смешиваем муку и разрыхлитель. Добавляем к муке смесь из блендера, перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (435,'На противень выстелить пергаментную бумагу, руки смачиваем в воде и выкладывает печенье на бумагу, вилкой примять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (435,'Выпекаем 20 минут в разогретой духовке до 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (436,'Картофель хорошо вымыть и отварить до готовности (около 20 минут в кипящей воде). Яйца отварить вкрутую (варим 7 минут после закипания воды). Когда все отравится слить горячую воду и залить холодной до полного остывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (436,'Очистить картофель и яйца. Вымыть редис, зелень и огурцы. Колбасу, картошку, яйца, огурцы нарезать одинаково размера (небольшими кубиками). Редис разрезать пополам и нарезать слайсами. Все нарезанные ингредиенты сложить в глубокую миску или кастрюлю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (436,'Укроп и зеленый лук мелко нарезать, добавить в кастрюлю и перемешать. Раскладываем окрошку по тарелкам и заливаем каждую стаканом кефира. По желанию можно добавить немного соли.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (437,'В кастрюлю налить 1 литр воды. Картофель нарезать кубиками и добавить в кастрюлю. Довести до кипения и варить 7 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (437,'Из фасоли слить жидкость, помидоры нарезать толстыми колечками и добавить в кастрюлю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (453,'Сформовать две лепешки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (437,'Также добавить в кастрюлю томатную пасту и лавровый лист, накрываем крышкой. Довести до кипения и варить 5 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (438,'Взбить сливочное масло с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (438,'Добавить яйцо, ореховую пасту – перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (438,'Всыпать какао и муку снова перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (438,'Добавить разноцветные драже на печенье выложенное на противень или всыпать сейчас и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (438,'На противень выстелить пергаментную бумагу. Ложкой выложить печенье, отправляем в духовку на 15 минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (439,'В пиале смешать оливковое масло, вино, чеснок пропущенный через пресс, мелко нарезанные маслины и петрушка, соль, перец, дижонская горчица – перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (439,'Противень застелить фольгой. На дно выложит стручковую фасоль. Сверху помидорки черри разрезанные пополам, сверху белую рыбу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (439,'Рыбу смазать соусом из первого шага.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (439,'Красный лук нарезать тонкими полукольцами. Выложить последним слоем. Запечатать рыбу фольгой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (439,'Ставим в духовку при температуре 200 градусов на 30 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (440,'В чашу блендера сложить вареные яйца, сыр, крабовые палочки, укроп и сметану. Измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (440,'Выложить измельченную массу в кондитерский мешок и при помощи мешка выложить на крекер смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (441,'Свеклу измельчить погружным блендером. Добавить сахар, яйцо, соль, молоко и ряженку – перемешать. Всыпать муку и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (441,'Сковороду смазать растительным маслом и выпекаем блины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (441,'На край блина намазать сливочный сыр толстым слоем, выложить ряд кусочками сельди в 1 слой и завернуть в рулет. Нарезать на кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (442,'В стакан выложить листья мяты и лимон. Растолочь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (442,'Добавить сахар, лед и воду, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (443,'Курагу нарезаем кусочками, смешиваем с изюмом и заливаем кипятком. Оставляем на 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (443,'Манку перемешиваем со сметаной и оставляем минут на 10-15 для набухания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (443,'К манке со сметаной добавляем ванильный сахар, сахар, яйца, растопленное сливочное масло и творог.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (443,'Всю массу перебиваем блендером до однородного состояния (в видео-рецепте я показала консистенцию).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (443,'С изюма и кураги сливаем воду, и добавляем изюм и курагу к творожной массе и хорошо перемешиваем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (443,'Форму для запекания смазываем сливочным маслом, и в неё переливаем творожную массу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (443,'Отправляем в разогретую до 160 градусов духовку примерно на 40-50 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (444,'Всыпать в миску муку, перемешать с дрожжами, солью и сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (444,'Влить теплую воду, перемешать. В массе не должно быть комочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (444,'Добавить оставшуюся муку, тесто должно получиться тугим и послушным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (444,'Емкость накрыть полотенцем, поставить в холод на час или полтора.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (444,'В кипящую подсоленную воду выложить курицу, отварить до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (444,'Бульон слить и использовать для приготовления первого блюда.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (444,'Мясо остудить, нарезать кубиками небольшого размера.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (444,'Свежие или консервированные ананасы нарезать кубиками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (444,'Тонко раскатать тесто.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (444,'Форму для запекания смазать растительным маслом, выложить лепешку, края удалить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (444,'Смазать поверхность томатной пастой, выложить кружочки свежих помидоров, куриное филе, ананасы.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (444,'Запекать полчаса при температуре 180 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (444,'Натереть сыр, выложить на пиццу, запекать еще десять минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (445,'Приготовить тесто из сырых куриных яиц, кефира, соли, пищевой соды, муки. Должно получиться жидкое тесто, как для оладий.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (445,'Отварить курицу в подсоленной воде, мясо остудить и нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (445,'Нарезать кубиками свежие помидоры и ананасы, нарезать соломкой ветчину.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (445,'Вылить тесто на смазанную сковороду, распределить равномерно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2090,'Можно добавить соду. Размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (445,'Далее – соус «Кетчуп», курица, ананасы и томаты, ветчина, тертый твердый сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (445,'Готовить под крышкой пятнадцать минут, огонь – средний.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (446,'Куриную грудку нарезать кубиками и обжарить до румянца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (446,'Растопить на другой сковороде сливочное масло, обжарить любые грибы и рубленый чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (446,'Продукты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (446,'Намазать на тесто сметану, выложить помидоры, нарезанные кружками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (446,'Далее – курица с грибами, сверху – консервированные ананасы, нарезанные кружками или кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (446,'Натереть сыр, посыпать пиццу сразу или через двадцать минут после начала запекания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (447,'Сначала приготовим тесто. Для этого в емкость выливаем кефир и добавив туда банку майонеза (250 гр) и 4 яйца, перемешиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (447,'Муку смешиваем с содой и щепоткой соли. Высыпаем муку в миску к майонезу с кефиром и перемешиваем все до однородной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (447,'Для начинки. Фарш размораживаем (у меня уже готовый куриный фарш).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (447,'Капусту нарезаем полосками среднего размера, луковицу нарезаю четверть кольцами, а лук и укроп мелко нашинкуем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (447,'Форму смазываем растительным маслом и выливаем в неё половину нашего тесты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (447,'Раскладываем всю начинку (произвольно) разравнивая, при желание подсолим начинку и заливаем сверху оставшимся тестом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (447,'Ставим форму с заливным пирогом в духовку и включаем её на 220 градусов. Выпекаем 20-25 минут, а затем выключив даем пирогу дойти в остывающей духовке примерно 5-10 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (448,'Раскатать тесто для пиццы, поместить в смазанную форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (448,'Намазать лепешку томатной пастой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (448,'Выложить сладкий болгарский перец, нарезанный соломкой, кусочки свежих ананасов, огурец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (448,'Отварить куриную грудку, выложить на овощи, поверх – сырые креветки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (448,'Посыпать тертым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (448,'Выпечь в духовом шкафу до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (449,'На готовое раскатанное тесто намазать томатную пасту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (449,'Далее – копченая курица, нарезанные кусочками ананасы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (449,'Натереть сыр, перемешать со свежей рубленой зеленью, посыпать пирог.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (449,'Выпекать до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (450,'В емкости перемешать нежирный протертый творог с сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (450,'Влить молоко, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (450,'Добавить оставшийся сахар и растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (450,'Муку перемешать с медом и ванилином, содой, добавить в основную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (450,'Вымесить до однородного состояния.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (450,'Сформовать пирог с бортиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (450,'Выложить начинку, выпечь в духовке при температуре до 185 градусов, время – от тридцати до тридцати пяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (451,'Творог перетереть с сахарным песком до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (451,'Вбить сырые куриные яйца, соль, муку, соду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (451,'Вымесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (451,'Присыпать мукой рабочую поверхность.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (451,'Раскатать несколько лепешек, выложить начинку, края защипать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (451,'Обжарить на растительном рафинированном масле с двух сторон, огонь – чуть больше среднего.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (452,'Творог перетереть с тремя яйцами и сахаром, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (452,'Добавить растительное масло, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (452,'Муку соединить с разрыхлителем, всыпать в основную массу порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (452,'Массу скатать в колобок, обернуть пищевой пленкой, оставить на два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (452,'Раскатать тесто в виде колбасок, нарезать, сформовать лепешки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (452,'Выложить начинку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (452,'Защипать, выложить на застеленный бумагой противень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (452,'Одно сырое яйцо взбить, смазать изделие, время выпекания – от двадцати пяти минут до получаса, температура приготовления – 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (453,'Творог размять вместе с кефиром при помощи блендера, миксера или вручную.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (453,'Влить растительное масло, всыпать соль, вбить яйца, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (453,'Муку просеять, перемешать с содой, тесто завернуть в пленку, поставить в холод на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (453,'Выложить начинку и выпечь изделия до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (454,'Мягкое сливочное масло соединить с творогом и сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (454,'Всыпать муку, перемешанную с разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (454,'Сформовать шар, разделить на четыре части, каждую раскатать в круг, разрезать от центра на сегменты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (454,'Выложить начинку на широкую сторону, свернуть рулетом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (454,'Уголки завернуть внутрь, чтобы получились полумесяцы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (454,'Поверхность смазать желтком, время выпекания от двадцати пяти до тридцати минут, температура – 190 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (455,'Творог растереть с сахарным песком, всыпать разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (455,'Массу взбить при помощи миксера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (455,'Влить растительное масло и сливки, посолить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (455,'Муку просеять, ввести порциями. Тесто не должно прилипать к рукам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (455,'Сформовать небольшие булочки, выложить на противень, смазать желтком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (455,'Время выпекания – двадцать пять минут, температура – 190 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (456,'Взбить творог при помощи блендера, добавить маргарин комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (456,'Всыпать соль и соду, муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (456,'Массу скатать в шар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (456,'Вымыть яблоки, очистить от кожуры, разрезать пополам и удалить сердцевину.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (456,'Время отваривания в кипящей воде – пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (456,'Остудить, сбрызнуть лимонным соком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (456,'Перемешать сахар с кокосовой стружкой и корицей.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (456,'В ямки из-под сердцевины каждого плода всыпать немного смеси.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (456,'Тесто раскатать и поделить на шесть частей-квадратов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (456,'Положить по яблоку, уголки собрать и защипнуть узелком.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (456,'Сбрызнуть холодной водой, выпекать в течение сорока пяти минут, температура приготовления – 190 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (457,'Хлопья подсушить в течение минуты в микроволновой печи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (457,'Крупу всыпать в небольшую банку, залить охлажденной водой, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (457,'Если хлопья слишком крупные, то их лучше разбить кофемолкой или блендером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (457,'Емкость закрыть, поставить в холод до утра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (458,'Все ингредиенты кроме кипятка смешать. Смешивать можно венчиком, взбивать миксером не требуется. В самом конце влить прямо с огня стакан кипятка. Размешать, тесто должно стать очень жидким. Вылить его в чашу от мультиварки или форму для духовки, смазанную сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (458,'Если готовите в мультиварке, то выпекать на режиме «выпечка» в течение 1 часа. Если будет недостаточно, то поставить еще на 20 минут. Если готовите в духовке, то поставить на 50–60 минут при температуре 170 градусов. Приготовить крем на основе карамельного соуса. Для этого разогреть сахар в кастрюльке на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (458,'Сахар постоянно помешивать, он должен начать таять через какое-то время.  Когда сахар станет темно-коричневым (но не черным), добавить к нему масло и влить 200 мл. молока. Вместо молока можно использовать сливки. Посолить и всыпать ванильный сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (458,'Убавить огонь и варить, постоянно помешивая, около 20–30 минут. Если использовать сливки вместо молока, то карамель комкуется в комок. Это нормальный процесс, нужно мешать дальше и карамель снова станет жидкой. В конце добавить еще 100 мл. молока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (458,'Смешать муку, яйцо и оставшиеся 100 мл молока. Эту смесь добавить в карамельный соус, поставить на огонь и, постоянно помешивая, довести до загустения. Снять с огня и охладить. Сливочное масло размягчить при комнатной температуре, взбить и добавить к нему заварную основу. Крем для торта готов. Сварить сахарный сироп из 50 мл. воды и 100 гр сахара, в конце в него добавить 50–70 гр водки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (467,'Свинину нарезала соломкой, посолила,посыпала специями для мяса и обжарила на подсолнечном масле до готовности. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (490,'Ингредиенты взбить до однородного состояния, лить зерновое молоко, перемешать при помощи венчика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (458,'Косточки вынуть из вишни и залить ее сахарным сиропом. Оставить настояться на 5 часов. У бисквита срезать верхнюю часть, мякиш бисквита аккуратно вынуть, оставив стенки и дно. Получится коробочка. Мякиш порезать кусочками. Слитым с вишни сиропом пропитать дно коробочки, внутрь положить карамельный крем, мякиш, вишню, снова крем и т. д. Когда бисквитная коробочка будет полной, накрыть ее срезанной верхушкой, пропитанной ликером. Украсить торт «Пьяная вишня» с карамельным соусом можно растопленным шоколадом или шоколадной глазурью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (459,'Хлопья всыпать в банку, добавить замороженные фрукты, ягоды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (459,'Добавить апельсиновый джем, залить смесью из натурального йогурта и молока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (459,'Емкость закрыть, потрясти, чтобы ингредиенты перемешались.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (459,'Поставить кашу в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (460,'Изюм промыть, обдать кипящей водой, высыпать на бумажные полотенца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (460,'Ягоды выложить в банку вместе с хлопьями, встряхнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (460,'Продукты залить горячей водой, оставить на ночь под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (460,'Яблоко очистить от кожицы, удалить семенные камеры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (460,'Плод натереть на терке или нарезать небольшими кубиками, добавить в основную массу вместе с медом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (461,'Овсяные хлопья насыпать на дно стеклянной банки, добавить натуральный цветочный мед и ванилин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (461,'Перемешать йогурт с молоком, залить сухие ингредиенты, банку закрыть, взболтать, поставить в холодильник на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (461,'Утром блюдо согреть в микроволновой печи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (461,'Блюдо украсить тертой шоколадной стружкой и свежей или размороженной вишней.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (462,'Хлопья всыпать в банку, добавить сахарный песок или влить немного меда.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (462,'Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (462,'Влить кефир средней жирности, перемешать компоненты еще раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (462,'Любимые ягоды промыть, обсушить, удалить косточки, если они есть. Выложить в кашу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (462,'Поставить блюдо на ночь в холод.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (463,'Половину стеклянной банки наполнить хлопьями, залить молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (463,'Содержимое банки взболтать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (463,'Апельсин очистить, нарезать небольшими кусочками, добавить в кашу вместе с лимонным джемом или цветочным медом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (463,'Поставить на ночь в холод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (464,'Спелые бананы очистить от кожуры, массу размять вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (464,'Всыпать какао-порошок, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (464,'Заполнить смесью чистую банку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (464,'Хлопья с бананами выложить слоями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (464,'Сверху – арахисовое масло, влить обезжиренное молоко.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (464,'Оставить смесь на ночь в холоде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (465,'Хлопья овсянки всыпать в банку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (465,'Отдельно соединить молоко и натуральный йогурт без добавок, влить в емкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (465,'Добавить жидкий мед, апельсиновый джем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (465,'Емкость закрыть, взболтать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (465,'Мандарин очистить, дольки очистить от прожилок, нарезать мякоть кусочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (465,'Добавить фрукты в кашу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (465,'Банку поставить в холод на ночь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (466,'Чеснок очистить и пропустить через пресс, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (466,'Нарезать мелкими кусочками помидоры, репчатый лук и кинзу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (466,'Разрезать плод авокадо пополам, вынуть косточку, удалить шкурку, мякоть размять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (466,'Добавить сок лимона или лайма, перемешать с авокадо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (466,'Перемешать все ингредиенты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (466,'При подаче украсить зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (467,'Порезала мелко капусту. Посолила и во время перемешивания, слегка обмяла, чтобы из капусты вышел лишний сок.','https://vkuso.ru/data/cache/data/b1/97b0b40ab8757b1_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (467,'В миску разбила яйцо. Размешала его. Добавила кефир, растительное масло, соль, сахар и все хорошо размешала между собой. Просеяла муку с разрыхлителем и замесила тесто, консистенцией как густая сметана.','https://vkuso.ru/data/cache/data/58/54bb34a1b273258_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (472,'Влить оливковое масло, добавить перец чили, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (472,'Добавить зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (472,'Салатную массу выложить в кожуру авокадо.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (498,'Не солить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (467,'В подготовленную форму для выпечки вылила половину теста, сверху на тесто высыпала всю начинку, на начинку вылила яйца со сливочным маслом и закрыла второй частью теста. Сверху посыпала кунжутом','https://vkuso.ru/data/cache/data/ee/583209d7e34a5ee_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (467,'Поставила выпекаться в разогретую до 180°С духовку, примерно на 45-50 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (468,'Вымыть плод авокадо, разрезать, удалить кожуру и косточку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (468,'Мякоть превратить в пюре при помощи блендера, добавить в нее лимонный сок, чтобы продукт не почернел.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (468,'Вымыть и нарезать листья мяты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (468,'Мелко нарезать острый перец чили.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (468,'Семена выбросить, мякоть размолоть в блендере вместе с мятой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (468,'Соль и молотый черный перец – по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (468,'Добавить оливковое масло, взбить массу до однородного состояния.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (469,'Дозревший авокадо очистить, мякоть нарезать мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (469,'Вымыть и натереть помидор.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (469,'Нарезать мелкими кусочками очищенный репчатый лук и чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (469,'Ингредиенты переложить в блендер, взбивать до однородного состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (469,'Другой вариант: взбить авокадо, другие овощи оставить кусочками, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (469,'Соль – по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (470,'Ломтики цельнозернового хлеба обжарить на сковороде без масла с двух сторон до хруста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (470,'Вымыть авокадо, вынуть косточку, мякоть нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (470,'Нарезать очищенный репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (470,'Чеснок измельчить при помощи пресса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (470,'Перец чили очистить от семян, так же пропустить через пресс или нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (470,'Ингредиенты выложить в чашу блендера, добавить лимонный сок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (470,'Взбить массу до получения однородной консистенции.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (470,'Нарезать кубиками томаты, добавить в соус.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (470,'Хлеб нарезать небольшими кусочками, намазать соусом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (471,'Просеять необходимое количество муки в виде горки, сделать лунку и вбить туда яйца. Добавить холодную воду, растительное масло и соль и замесить тесто. Для того чтобы из муки выделилась клейковина следует накрыть тесто влажным кухонным полотенцем и дать ему настояться в течение часа. За это время тесто приобретет нужную эластичность.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (471,'Для приготовления фарша пропустить мясо через мясорубку и добавить специи. Лук нашинковать ножом и слегка припустить на сковороде с растительным маслом. Переложить лук на тарелку остывать, а затем добавить в фарш. В фарш вбить яйцо и тщательно вымешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (471,'Готовим овощной соус: очень мелко нарезать лук и сладкий перец, обжарить на масле до мягкости перца, туда же добавить помидоры предварительно очищенные от кожуры и нарезанные кубиками. Тушить овощи на медленном огне 5 минут. Для того чтобы легко снять кожуру с помидора его необходимо на пару минут окунуть в крутой кипяток, а затем сразу в холодную воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (471,'Если не снять кожуру, то в соусе будут попадаться твердые пленки, которые испортят вкус. Очищенный чеснок измельчить ножом и слегка придавить ребром ножа для того, чтобы эфирные масла выделились. Добавить в соус чеснок, специи и после того как он закипит всыпаем рубленую зелень и выключаем огонь. Для приготовления ленивых пельменей, тесто повторно вымешать и отрезав кусок раскатать его при помощи скалки в пласт толщиной  2мм.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (471,'На листе из теста выложить часть фарша. Скрутить тесто рулетом и разрезать его на порционные кусочки шириной 5см. Для того чтобы сформировать изделия, защипываем каждый мини рулет с одной стороны и выкладываем пельмени стороной с защипом на дно промасленной формы. Полить «розочки» из теста готовым соусом и поставить в нагретый до 200  градусов духовой шкаф на полчаса. Готовые ленивые мясные пельмени подавать, присыпав зеленью и полив сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (472,'Вымыть томаты, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (472,'Нарезать очищенный чеснок и лук-шалот.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (472,'Чеснок можно пропустить через пресс.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (472,'Мякоть авокадо размять вилкой, побрызгать лимонным соком. Такой способ не даст продукту почернеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2090,'Поставить в тепло на 60 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (473,'Начинка. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (473,'Маринад.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (473,'Чистим, потрошим, моем пеленгаса. Наполняем пеленгаса начинкой и смазываем маринадом. Жарим на углях по 10 минут с каждой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (474,'Яйца взбиваем с сахаром миксером до белой пышной массы.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (474,'Добавляем к тесту орехи и изюм. Еще раз перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (474,'Выкладываем тесто на лист, выстланный пергаментной бумагой и смазанный маслом, в виде прямоугольника (толщиной около 1 см).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (474,'Отправляем в разогретую духовку на 200 градусов на 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (474,'Разрезаем на ромбики или квадратики еще горячим. Всем вкусного чаепития!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (475,'Куриные яйца отварите вкрутую: помойте их, переложите в кастрюльку, залейте водой, поставьте на плиту и после закипания воды варите яйца в течение 10 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (475,'Репчатый лук нарежьте четверть-кольцами или соломкой.','https://vkuso.ru/data/cache/data/2c/bf1dc12a798f92c_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (475,'Лук отправляем в миску.','https://vkuso.ru/data/cache/data/92/2a2306f144f2092_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (475,'Заливаем лук кипятком.','https://vkuso.ru/data/cache/data/d8/caf238d33b867d8_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (475,'Добавляем 2 ст. ложки сахара.','https://vkuso.ru/data/cache/data/a1/2990fe6d2dc68a1_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (475,'Добавляем 2 ст. ложки 9% уксуса. Оставляем на 5 минут. Затем сливаем воду из миски с луком.','https://vkuso.ru/data/cache/data/df/dda27d412bf20df_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (475,'Твердый сыр натрите на терке.','https://vkuso.ru/data/cache/data/4d/1d9bd829e74424d_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (475,'Яйца натрите на терке.','https://vkuso.ru/data/cache/data/d0/f83c70e9419c9d0_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (475,'Слейте жидкость с консервированного горошка, откиньте горошек на сито, ополосните проточной водой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (475,'Посолите и поперчите по вкусу.','https://vkuso.ru/data/cache/data/b1/a946dfb37f4ddb1_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (475,'Добавьте по вкусу майонез или сметану.','https://vkuso.ru/data/cache/data/83/0cff5a5aa7f5d83_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (475,'Тщательно перемешайте. Салат готов! Приятного аппетита!','https://vkuso.ru/data/cache/data/ad/4b37c38737018ad_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (476,'Куриное филе промыть под проточной водой и обсушив нарезать на куски. Отбить каждый кусочек с обеих сторон и присыпать черным перцем и солью. Яйца взбить венчиком и обмакивая в них мясо, жарить отбивные с двух сторон. После того, как одна сторона прожарится до золотистой корочки, перевернуть на вторую и, накрыв крышкой, продолжить готовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (476,'Готовые отбивные выложить на смазанное маслом дно и на каждую из них выложить по пластинке ананаса. Натереть сыр на крупной терке и присыпать им сверху отбивные с ананасами. Поставить запекаться на несколько минут духовку, чтобы дать возможность сыру расплавиться и запечатать отбивную с ананасом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (476,'Отбивные из куриного филе с ананасом и сыром готовятся перед подачей на стол. Если нет такой возможности, можно сделать заготовку, пожарив отбивные заблаговременно, а перед застольем добавить остальные ингредиенты, и в горячем виде поставить на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (477,'Лук нарезать мелким кубиком, чеснок (6 зубчиков) мелко нарезать, рис промыть, базилик (оставить 1 веточку) и кинзу нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (477,'В глубокой тарелке соединить лук, чеснок, фарш, рис, базилик, кинзу, воду (100 мл) посолить (1 ч. л.), поперчить (1/2 ч. л.), приправу для долмы (1 ч. л.) – перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (477,'Листья винограда залить кипятком на 3 минуты, вынуть их, отрезать хвостики. На каждый листик винограда выложить начинку из фарша, свернуть в тугой рулет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (477,'На дно кастрюли выстелить 3 листика виноградных листьев во избежание пригорания, выложить половину рулетиков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (483,'Пищевую пленку смазать водой, разложить картофель по всей поверхности. Сверху овощную начинку (с одной стороны отступить от края 4 сантиметра). Свернуть рулет от края с начинкой к краю с отступом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2096,'Развести дрожжи в теплом молоке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (477,'Помидоры измельчить в пюре, вылить в кастрюлю с долмой. Выложить оставшиеся рулетики, залить водой в уровень с долмой, посолить (1 ч. л.). Ставим на медленный огонь на 45 минут нагрузив сверху, чтобы рулетики не раскрутились (я положила съемное дно он формы для выпечки и поставила на него кувшин с водой)',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (477,'Готовим соус. Нарубить по 1 веточки, укропа, петрушки и базилика, залить мацони, добавить чеснок (1 зубчик) пропущенный через пресс – перемешать. Этим соусом полить готовую долму.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (478,'Натереть кабачок на терке, отжать и отставить в сторонку чтоб стекал лишний сок.','https://vkuso.ru/data/cache/data/1c/90afe616305511c_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (478,'Натереть на терке лук, морковь, сыр и чеснок. Мелко порезать укроп. Далее смешать все ингредиенты. Добавить яйцо, муку, посолить и поперчить и тщательно перемешать полученную массу.','https://vkuso.ru/data/cache/data/90/606b8e3adcc5090_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (478,'На разогретую сковороду налить растительное масло. Ложкой выкладываем массу на сковороду и формируем оладьи. Обжаривать по 2-3 минуты с каждой стороны.','https://vkuso.ru/data/cache/data/4a/d946c6122b8ac4a_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (478,'Кабачковые оладьи с морковью и сыром готовы. Подавать лучше всего со сметаной. Приятного аппетита!','https://vkuso.ru/data/cache/data/50/3ff6e413e4be750_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (479,'Для начала в холодном молоке развести желатин и оставить для набухания на 15-20 минут.','https://vkuso.ru/data/cache/data/36/5b9d94297e89836_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (479,'Творог смешать с сахаром, сметаной и ванильным сахаром и пробить блендером в однородную массу без крупинок.','https://vkuso.ru/data/cache/data/67/6b214e79b50b867_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (479,'Персики нарезать не большими кубиками.','https://vkuso.ru/data/cache/data/fe/aaadb5fe7c7b0fe_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (479,'Желатин растворить в микроволновке или на водяной бане, но не кипятить.','https://vkuso.ru/data/cache/data/f9/43ad35edd0320f9_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (479,'Остывший желатин влить в творожную массу, тщательно перемешать.','https://vkuso.ru/data/cache/data/87/d20b9a2bf363d87_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (479,'Добавить кусочки персиков (ягоды) и снова перемешать.','https://vkuso.ru/data/cache/data/46/8df50353a1eb646_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (479,'Выложить массу в форму (или в порционные формы) и поставить в холодильник для застывания минимум на 3 часа. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (480,'Делаем надрезы на голенях.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (480,'Добавляем лук, нарезанный полукольцами, чёрный молотый перец, красный острый перец и растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (480,'Жарим на углях по 10 минут с каждой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (480,'Натираем на терке два помидора, добавляем томатную пасту, чеснок, мед, красный острый перец, горчицу в зернах и всё перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (480,'Смазываем голени глазурью, посыпаем зернами кунжута и держим на углях ещё пару минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (481,'Лук нарезать кубиками, морковь натереть на терке. Обжарить на растительном масле 15 минут при среднем огне, перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (481,'У болгарского перца вырезать хвостик и очистить от семян.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (481,'Фарш поперчить (1/2 ч.л.), посолить (1/3 ч.л.), добавить рис и перемешать. Добавить половину жаренного лука с морковью, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (481,'Перец начинить смесью из фарша
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (481,'Томатную пасту смешать со сметаной и водой, залить этой смесью перцы до середины (если смеси мало, долейте еще воды), засыпать остатки жаренной морковки с луком. Варим 40 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (482,'Бананы очистить, измельчить погружным блендером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (482,'К бананам добавить творог, взбить венчиком.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (482,'Форму смазать растительным маслом. Вылить смесь.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (483,'Картофель очистить от кожуры, заливаем водой и варим до готовности. Затем полностью сливаем воду и измельчаем картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (483,'Баклажан, болгарский перец очищенный от семян, морковь - нарезать кубиками. Обжариваем на растительном масле 20 минут на среднем огне, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (483,'В картофель вбить яйцо (1 шт.) и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (483,'Противень застелить бумагой, смазать сливочным маслом. Переложить наш рулет. Яйцо взбить в пиале и сверху смазать им рулет. Посыпать кунжутными семечками. Выпекаем 40 минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (484,'В кастрюлю налить 1.5 литра воды. Добавить картофель, нарезанный кубиками, довести до кипения и варить 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (484,'Лук нарезать кубиками, морковь натереть на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (484,'В сковороде с растительным маслом обжарить лук в течении 5 минут на среднем огне, перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (484,'Добавить морковь и жарим еще 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (484,'В отдельную кастрюлю положить плавленый сыр и залить водой (100 мл). Варим до полного растворения сыра.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (484,'В кастрюлю с картофелем вылить сыр, обжаренные морковь и лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (484,'Чеснок нарезать тонкими пластинками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (484,'Очищенные креветки измельчить. Добавить в кастрюлю.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (484,'Варим 10 минут на медленном огне',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (485,'Муку соединить с солью (1/5 ч.л.), добавить сахар (50 гр), ванильный сахар, сливочное масло, яйцо (1 шт.), вода (2 ст. л.). Замесить тесто и поставить в холод на 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (485,'Форму для выпечки застелить бумагой. От теста отрезать 1/3 часть, убрать ее в морозильную камеру на 10 минут. Остальное тесто распределяем по дну формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (485,'В отдельной тарелке готовим начинку. Рикотта + яйцо (1 шт.) + сахар (50 гр) + пудинг + сливки – перемешать. Сливы очистить от косточки и нарезать на кусочки, перемешать. Выложить начинку на тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (485,'Разогреваем духовку до 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (485,'Достаем тесто и морозилки, натираем на терке поверх начинки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (485,'Выпекаем торт 50 минут. Остужаем при комнатной температуре, затем ставим в холодильник на 2 часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (486,'Помидоры залить кипятком на 5 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (486,'В сковороду добавить розмарин, лавровый лист и нарезанный лук. Обжариваем 10 минут на среднем огне, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (486,'С помидор слить кипяток и залить холодной водой, снять кожицу, нарезать на кубики. Отправить в сковороду. Накрыть крышкой и тушить 25 минут. Лавровый лист выкинуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (486,'В отдельной сковороде на оливковом масле обжариваем фарш 20 минут на среднем огне, перемешивая.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (486,'В отдельную сковороду кладем сливочное масло и муку, греем пока масло не растает при этом постоянно помешивая.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (486,'В кастрюле с кипящей водой варим листы лазаньи по 2 минуты. Варим по 1 штуке. Чтобы не склеились и чтобы не повредить листы. Вынимаем листы и кладем на дуршлаг, чтобы стекала вода.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (486,'Форму, где будет готовиться лазанья смазываем оливковым маслом. Кладем листы лазаньи в 1 слой, внахлест. Затем выкладываем половину начинки из фарша.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (486,'Моцареллу нарезаем пластинками. Выкладываем на начинку из фарша. Затем еще слой лазаньи, фарша.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (486,'Ставим в духовку на 30 минут при температуре 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (487,'Высыпать хлопья «Геркулес» в посуду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (487,'Залить продукт водой, подождать десять или двенадцать часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (487,'Размягченные хлопья взбить при помощи блендера, массу отфильтровать через сито или марлю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (487,'Продукт хранить в холоде в течение недели.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (488,'Овес промыть, залить кипяченой остывшей водой на двенадцать часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (488,'Взбить блендером и процедить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (489,'Овес перебрать, промыть, подсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (489,'Вылить коровье молоко в сотейник, поставить на огонь, довести до кипения, всыпать зерна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (489,'Огонь уменьшить, потомить жидкость под крышкой два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (489,'Для приготовления напитка можно использовать мультиварку, выставить режим «Тушение».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (489,'Молоко отжать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (490,'В чашу миксера или блендера положить нарезанные кусочками киви, бананы, немного меда.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (491,'Приготовить овсяное молоко по традиционному рецепту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (491,'Добавить немного молотого мускатного ореха, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (492,'В емкость всыпать хлопья, залить водой, подождать до набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (492,'Воду слить, массу отправить в миксер, долить кипяченую воду, взбить в течение минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (492,'Состав отцедить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (492,'Молоко взбить в миксере еще раз, процедить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (493,'Из плодов авокадо вынуть косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (493,'Мякоть без кожуры поместить в блендер.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (493,'Очистить помидоры от кожицы, мякоть выложить в блендер.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (493,'Отдельно перемешать нарезанный лук, сок лайма, красный перец, чеснок, соль, перец, соус «Табаско».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (493,'Смесь перемешать и также добавить в блендер.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (493,'Ингредиенты взбить до однородного состояния, выложить на блюдо, накрыть пищевой пленкой, охлаждать два часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (494,'Промыть рис многократно, сливая воду до полной ее прозрачности. Рис переложить в кастрюлю и залить холодной водой в пропорциях 1 к 2. Для того, чтобы рис не пристал ко дну посуды, в которой он вариться, можно применить одну хитрость, для этого дно кастрюли выстилают фольгой, сверху всыпают рисовую крупу и наливают воду. Когда рис приготовиться его переворачивают на широкое блюдо и  аккуратно снимают фольгу, дно кастрюли же, остается чистым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (494,'Готовый рис пересыпать в широкую миску. Морковь промыть и почистить, снять с лука верхнюю шелуху. Морковь измельчить на терке, лук нашинковать ножом мелко. Обжарить подготовленные овощи на подсолнечном масле до янтарного цвета. Переложить поджарку в рис. Отварной картофель в мундире очистить и натереть на терке. Переложить к рису. Тщательно вымешать рисовый фарш, прибавив к нему молотый черный перец и соль. Сформировать постные котлеты из овощей и риса и обжарить на сильном огне до появления хрустящей, румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (495,'В миску положила размягченное сливочное масло, сахар, соль и творог. Все перемешала до однородности.','https://vkuso.ru/data/cache/data/d7/1a1e2421e12dad7_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (495,'Частями ввела просеянную муку, смешанную с разрыхлителем. Замесила гладкое однородное тесто. Тесто положила в пакет и убрала в холодильник на 15 минут','https://vkuso.ru/data/cache/data/e4/1e778e3fc101ce4_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (495,'Охлажденное тесто раскатала до толщины 2-3 мм. Тесто порезала полосками ножом. Каждую полоску посыпала сахаром. Полоски скатала в рулетик. Выложила печенье на противень, застеленный пергаментом, и отправила в разогретую духовку. Выпекала при 180° приблизительно минут 30 или до румяной корочки.','https://vkuso.ru/data/cache/data/d3/cb93cd58c79ddd3_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (496,'Багет нарезать одинаковыми кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (496,'Каждый смазать тонким слоем сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (496,'Порубить базилик, пропустить через пресс чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (496,'Очистить томаты от кожуры, разрезать на кусочки, перемешать с зеленью и чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (496,'Добавить бальзамический уксус, соль, молотый перец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (496,'Начинку перемешать, выложить на хлеб.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (496,'Противень смазать оливковым маслом, выложить бутерброды.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (496,'Посыпать тертым сыром «Моцарелла».',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (497,'Разрезать помидоры пополам, а затем ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (497,'Чеснок пропустить через пресс, перемешать с оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (497,'Порубить зелень кинзы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (497,'Нарезать хлеб, смазать маслом с чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (497,'Жарить на сковороде до корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (497,'Выложить на ломтики дольки помидоров, сыр, печь до расплавления сыра, огонь – средний.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (497,'Посыпать бутерброды кинзой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (498,'Баклажаны наколоть со всех сторон вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (498,'Не чищеный чеснок разрезать пополам, полить оливковым маслом, завернуть в фольгу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (498,'Выложить овощи на противень, печь полчаса при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (498,'Итальянский хлеб чиабатта нарезать ломтиками в полтора сантиметра толщиной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (498,'Смазать оливковым маслом с обеих сторон, печь в духовом шкафу на решетке до зарумянивания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (498,'Из баклажанов вынуть мякоть, чеснок извлечь из шелухи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (498,'Овощи порубить, полить маслом, поперчить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (498,'Прокалить на сухой сковороде очищенные кедровые орехи.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (498,'Покрошить сыр «Фета» руками или порубить ножом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (498,'Выложить баклажанную пасту на хлеб, посыпать сыром, поперчить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (498,'Украсить кедровыми орехами.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (499,'Нарезать помидоры, лук, зеленый перец чили.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (499,'Потушить овощи до мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (499,'Добавить куриное мясо, сушеную кинзу, жарить до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (499,'Белый хлеб нарезать ломтиками, обжарить до корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (499,'Выложить начинку, подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (500,'Перемешать винный уксус с оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (500,'Порубить зелень укропа, добавить в соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (500,'Соль и перец молотый – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (500,'Свежие огурцы нарезать тонкими ломтиками, выложить в маринад на пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (500,'Красный лук нарезать мелкими кусочками, высыпать в дуршлаг, промыть от лишней горечи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (500,'Филе сельди нарезать мелкими кубиками, добавить красный лук, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (500,'Багет нарезать ломтиками толщиной по полтора сантиметра или тоньше.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (500,'Застелить противень пергаментом, выложить хлеб, запечь до получения хрустящей аппетитной корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (500,'На горячие ломтики выложить огурцы и сельдь с луком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (500,'Полить бутерброды остатками маринада.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (501,'Чиабатту из темной муки нарезать тонкими кусочками, посыпать рублеными пряными травами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (501,'Побрызгать оливковым маслом, поставить в духовой шкаф.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (501,'Репчатый лук мелко нарезать, запечь в духовке или в мультиварке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (501,'Добавить в лук нарезанный перец чили, вяленые помидоры, нарезанные свежие баклажаны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (501,'Приготовить соус из пряных трав, сахарного песка, бальзамического уксуса, оливкового масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (501,'Овощи выложить на чиабатту, далее – лист рукколы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (501,'Сбрызнуть заправкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (502,'Говяжий стейк обжарить до готовности на оливковом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (502,'Огонь выключить, мясо оставить на сковороде до остывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (502,'Остывший продукт нарезать ломтиками толщиной по два или три миллиметра острым ножом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (502,'Ржаной хлеб побрызгать оливковым маслом, обжарить с двух сторон на сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (502,'Намазать соус «Песто», выложить нарезанные вяленые помидоры, далее – мясо и рукколу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (502,'Посолить и поперчить, подать на стол.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (503,'Перец запечь на решетке в духовом шкафу до появления подпалин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (503,'Прогреть сковороду с оливковым маслом, обжарить белый хлеб.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (503,'У запеченного болгарского перца снять кожицу и удалить сердцевину.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (503,'Нарезать овощ длинными кусочками, выложить на хлеб.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (503,'Раскрошить сыр «Фета», выложить сверху на бутерброды, украсить листочками базилика.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (504,'Репчатый лук очистить, нарезать тонкими полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (504,'Прогреть на сковороде оливковое масло, обжарить лук в течение пяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (504,'Добавить в сковороду немного воды и коричневый сахарный песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (504,'Продукты перемешать, жарить десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (504,'Шампиньоны промыть, нарезать пластинками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (504,'Грибы обжарить на сливочном масле, время – восемь минут, огонь – средний.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (504,'Добавить черный молотый перец, соль, винный уксус, немного сушеного перца чили, тимьян.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (504,'Все вместе жарить еще шесть или семь минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (504,'Добавить лук, перемешать, снять с плиты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (504,'Белый хлеб нарезать ломтиками, запечь в прогретой духовке.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (504,'Намазать бутерброды творожным сыром, выложить грибы с луком.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (505,'Крупные и свежие креветки обжарить в панцире со смесью сливочного и оливкового масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (505,'По желанию добавить молотый перец и давленый чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (505,'Готовый продукт полить лимонным соком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (505,'Масло не выливать, на нем можно обжарить ломтики хлеба чиабатта.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (505,'Посолить, посыпать рубленой зеленью петрушки, остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (505,'Выложить очищенные креветки, сбрызнуть соевым соусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (506,'Хлеб чиабатта порезать ломтиками, сбрызнуть оливковым маслом, запечь до готовности в духовом шкафу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (506,'Ветчину «Прошутто» очень тонко нарезать, выложить на хлебные ломтики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (506,'Промыть и обсушить рукколу, выложить по два-три листочка на бутерброд.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (506,'Далее – кусочки сыра с голубой плесенью, посыпать молотыми грецкими орехами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (506,'Молотый перец – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (506,'Бутерброды запечь в духовке, температура приготовления – 180 градусов. Сыр должен расплавиться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (507,'Плод авокадо разрезать пополам, косточку вынуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (507,'Мякоть вынуть, сбрызнуть свежим соком лайма, чтобы она не почернела.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (507,'Размять вилкой, добавить любимые специи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (507,'Хлеб нарезать кусочками, выложить массу из авокадо, посыпать тертым сыром «Пармезан».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (508,'Белый хлеб нарезать ломтиками, смазать оливковым маслом и запечь в духовом шкафу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (508,'Помидоры черри нарезать кружками, добавить рубленый или давленый чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (508,'Полить продукты винным уксусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (508,'Базилик порубить и добавить к овощам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (508,'Нарезать сыр «Моцарелла», выложить на хлеб, сверху помидоры и целые веточки базилика.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (509,'Режем капусту, добавляем в нее 2 яйца, муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (509,'Солим, перчим, все хорошо перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (509,'Сковороду смазываем маслом,выкладываем на нее получившуюся смесь и посыпаем кунжутом. Жарим под крышкой с каждой стороны по 10 минут.','https://vkuso.ru/data/cache/data/c2/30db72aa6f80ac2_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (510,'Отварить свиное сердце, нарезать кубиками, обжарить с желтым или красным сладким болгарским перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (510,'Овощи также нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (510,'Добавить немного острого красного перца, соевый соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (510,'Жарить недолго, перец не должен стать мягким.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (510,'Нарезать огурцы соломкой или кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (510,'Репчатый лук покрошить соломкой, чеснок пропустить через чеснокодавку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (510,'Порубить зелень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (510,'Все ингредиенты перемешать в салатнице.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (510,'Влить немного оливкового масла, перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (511,'Репчатый лук нарезать соломкой, выложить в стеклянную емкость, влить воду, уксус, всыпать сахарный песок, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (511,'Ингредиенты перемешать, оставить на полчаса для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (511,'Отварить сердце, нарезать брусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (511,'Покрошить чеснок и зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (511,'Продукты пересыпать в салатницу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (511,'Добавить молотый перец, любые специи – по желанию.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (511,'Отцедить лук от маринада.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (511,'Добавить в салат, перемешать, заправить майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (511,'Поставить в холод на два часа для пропитывания.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (512,'Отварить и остудить свиное сердце, нарезать соломкой, выложить в салатницу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (512,'Нарезать полукружьями репчатый лук, обжарить на сковороде, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (512,'Очистить и нарезать морковь. Можно использовать терку для приготовления моркови по-корейски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (512,'Обжарить овощ на сковороде, также остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (512,'Покрошить зелень петрушки или укропа, можно использовать несколько трав.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (512,'Добавить все ингредиенты к нарезанному сердцу, посолить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (512,'Перец молотый – по желанию.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (512,'Заправить салат майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (513,'Отварить сердце, нарезать брусками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (513,'Очистить и нарезать морковь на терке для приготовления корейских салатов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (513,'Обжарить на сковороде, остудить и выложить к сердцу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (513,'Репчатый лук нарезать полукольцами, влить воду, столовый уксус, всыпать соль и сахар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (513,'Оставить для пропитывания на полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (513,'Маринад слить, добавить лук в салат.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (513,'Добавить горошек, молотый перец, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (513,'Салат заправить майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (518,'Тонко нарезать полукольцами репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (514,'Отварить и остудить свиное сердце, нарезать небольшими кубиками или соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (514,'Нарезать репчатый лук полукольцами, залить уксусом и водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (514,'Добавить сахарный песок и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (514,'Время маринования – от пятнадцати до двадцати минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (514,'Отварить и очистить куриные яйца, нарезать кубиками, добавить в основную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (514,'Маринованный или соленый огурец нарезать соломкой или небольшими кубиками, выложить в салат вместе с отцеженным луком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (514,'Соль и перец – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (514,'Заправить готовый салат майонезом или сметаной.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (514,'Третий вариант – смесь из майонеза и сметаны в равных пропорциях.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (515,'Свиное сердце отварить до готовности, остудить, нарезать кубиками или брусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (515,'Сыр «Российский» или аналогичный твердый натереть на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (515,'Другой вариант – нарезать соломкой острым ножом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (515,'Продукты соединить, заправить смесью майонеза и столовой горчицы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (515,'Перец и соль – по вкусу и желанию.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (515,'Выложить на большое плоское блюдо листья зеленого салата, выложить массу, украсить зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'В миску вливаем 200 мл кефира.','https://vkuso.ru/data/cache/data/e5/354669e782dc2e5_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'Добавляем 2 куриных яйца.','https://vkuso.ru/data/cache/data/df/c80633eb8fe10df_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'50 мл растительного масла.','https://vkuso.ru/data/cache/data/48/3463e79bbb1b048_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'1 ч. ложку соли.','https://vkuso.ru/data/cache/data/5a/6796ee718bc805a_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'2 ст. ложки сахара.','https://vkuso.ru/data/cache/data/dc/a98862c589efbdc_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'Тщательно перемешиваем.','https://vkuso.ru/data/cache/data/48/f17048fa20fba48_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'Добавляем 1 пачку разрыхлителя.','https://vkuso.ru/data/cache/data/9a/80900390865f39a_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'Затем просеиваем в смесь 500 гр пшеничной муки ( может понадобится немного больше).','https://vkuso.ru/data/cache/data/ff/94dac51299915ff_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'Замешиваем тесто.','https://vkuso.ru/data/cache/data/be/8bc853fa6a2b9be_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'Накрываем пищевой пленкой и оставляем на 10 минут.','https://vkuso.ru/data/cache/data/b4/db6dc5a9bec5eb4_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'Рабочую поверхность присыпаем небольшим количеством муки. Тесто разделяем на несколько частей.','https://vkuso.ru/data/cache/data/f6/15b6afb8547baf6_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'Каждый кусочек теста раскатываем толщиной приблизительно 6-7 мм.','https://vkuso.ru/data/cache/data/fc/a4d09abe745e7fc_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'На каждой лепешке делаем небольшие надрезы.','https://vkuso.ru/data/cache/data/56/ee13d8d9ab7f256_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'Обжариваем на растительном масле на среднем огне.','https://vkuso.ru/data/cache/data/b4/50f469234bc25b4_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'Обжариваем лепешки до золотистого цвета с обеих сторон.','https://vkuso.ru/data/cache/data/a0/af3f6015e9878a0_434x295_notrise.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (516,'Лепешки на кефире готовы! Приятного аппетита!','https://vkuso.ru/data/cache/data/8b/f95d43880ea628b_434x295_notrise.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (517,'Бисквит: в широкой миске взбить яйца с одним стаканом сахара. Добавить 2 стакана сметаны, вымешать и всыпать еще один стакан сахара. Полторы чайных ложки соды погасить лимонным соком и влить в тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (517,'Просеять муку и постепенно добавляя небольшими порциями вмешать в тесто. Разделить тесто на две равные части и в одну из них добавить какао. Выпекать при температуре 200  градусов в формах смазанных сливочным маслом. Готовность бисквитов можно проверить деревянной палочкой, воткнув ее посредине.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (517,'Крем: взбить оставшуюся сметану со стаканом сахара и соком половины лимона. Крем должен получиться в меру густым, но при этом не следует долго взбивать, иначе можно добиться отслоения сыворотки и масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (517,'Глазурь: сахар смешать с какао и добавив две ложки сметаны поставить на медленный огонь. Добавить 30 г масла и постоянно помешивая растопить глазурь до однородности, не дав ей вскипеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (517,'Остывшие коржи разрезать острым ножом с тонким лезвием на две части и перемежевывая белый с коричневым промазать кремом и сформировать торт. Покрыть теплой шоколадной глазурью и поставить на холод пропитываться. Готовый торт «Тающее чудо» со сметаной можно украсить дополнительно кремом или присыпать ореховой крошкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (518,'Свиное сердце отварить в воде до готовности, остудить, нарезать тонкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (518,'Готовую морковь по-корейски нарезать небольшими кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (518,'Перемешать ингредиенты в салатнице, посолить и поперчить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (518,'Другие специи – по желанию.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (518,'Заправить массу майонезом, поставить в холодильник на сорок минут или на час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (519,'Субпродукты отварить и нарезать полосками или кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (519,'Выложить на плоское блюдо в качестве первого слоя.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (519,'Намазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (519,'Консервированные шампиньоны также нарезать мелкой соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (519,'Второй слой завершить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (519,'Нарезать маринованные огурцы кружочками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (519,'Отварить яйца, покрошить кубиками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (519,'Продукты перемешать, выложить третий слой, намазать майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (519,'Натереть твердый сыр, посыпать салат сверху, украсить зеленым горошком и свежей зеленью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (520,'Отварить свиное сердце. Время варки – от тридцати до сорока минут, сменить воду, доварить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (520,'Нарезать тонкими полосками или кубиками небольшого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (520,'Добавить консервированную или отваренную фасоль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (520,'Отварить яйца, остудить, очистить, нарезать, добавить в салат.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (520,'Репчатый лук очистить, мелко нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (520,'Свежий огурец нарезать кубиками или соломкой. Кожуру лучше снять, если она жесткая или горькая.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (520,'Ингредиенты перемешать, салат посолить, поперчить, заправить майонезом или другим соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (520,'Поместить в холод на полчаса для пропитывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (521,'Субпродукт промыть, удалить сосуды и жир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (521,'Сердце отварить, нарезать любым способом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (521,'Желтый или красный сладкий перец нарезать тонкими полосками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (521,'Покрошить зеленый лук, добавить в общую массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (521,'Измельчить чеснок, можно пропустить через чеснокодавку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (521,'Добавить в салат вместе с солью, зеленью, специями.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (521,'Заправить блюдо сметаной или майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (522,'Серый багет нарезать ломтиками, сбрызнуть оливковым маслом, посолить и обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (522,'Вырезать плодоножку у крупного помидора, удалить семенные камеры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (522,'Мякоть нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (522,'Чеснок раздавить, добавить к помидорам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (522,'Смесь посолить и поперчить по вкусу, влить оливковое масло и перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (522,'Красный лук очистить, нарезать тонкими полукольцами, сбрызнуть лимонным соком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (522,'Сыр натереть, промыть веточки петрушки, обсушить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (522,'Листочки измельчить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (522,'Нарезать кружками оливки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (522,'Выложить на теплый хлеб кусочки консервированной рыбы, далее – слой помидоров с чесноком, сверху – лук и тертый сыр.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (522,'Запечь в духовом шкафу до расплавления сыра.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (523,'Багет нарезать ломтиками, выложить на противень, смазать оливковым маслом и запекать в течение шести минут в духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (523,'Сливочное масло комнатной температуры смешать с соусом «Песто».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (523,'Мелко порубить оливки, нарезать очищенные от шкурки помидоры кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (523,'Продукты соединить, добавить томатную пасту, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (523,'Нарезать ломтиками сыр «Моцарелла».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (523,'Хлеб смазать соусом «Песто» с маслом, второй слой – помидоры с оливками, сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (523,'Время запекания в духовке – две минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (524,'Багет нарезать ломтиками, сбрызнуть оливковым маслом и запечь в духовке, температура приготовления – 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (524,'Вынуть, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (524,'Семгу нарезать тонкими полосками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (524,'Вымыть и обсушить базилик и помидоры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (524,'Листочки порубить, помидоры нарезать кубиками небольшого размера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (524,'Продукты перемешать, добавить молотый черный перец и оливковое масло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (524,'Выложить на хлеб овощную смесь, семгу, творожный сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (525,'Багет нарезать ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2096,'Насыпать сахар, муку, масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (525,'Обжарить до корочки на сухой сковороде или на гриле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (525,'Смазать оливковым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (525,'Авокадо разрезать пополам, удалить косточку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (525,'Мякоть нарезать небольшими кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (525,'Выложить в чашу блендера вместе с укропом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (525,'Сбрызнуть соком лайма, влить оливковое масло, всыпать соль и перец.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (525,'Приготовить ароматное пюре.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (525,'Выложить на теплый хлеб, сверху – тонко нарезанный лосось.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (525,'Украсить рукколой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (526,'Тонко нарезать ростбиф.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (526,'Багет нарезать ломтиками, сбрызнуть оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (526,'Температура запекания – 180 градусов, готовить до получения корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (526,'Ломтики остудить, намазать сливочным сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (526,'Лук очистить, нарезать кубиками, обжарить до прозрачного состояния на растительном масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (526,'Выложить на сыр, сверху – ростбиф.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (527,'Приготовить гренки, хлеб жарить с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (527,'Помидоры нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (527,'Смешать с оливковым маслом и базиликом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (527,'Ломтики натереть чесноком, выложить начинку, посыпать тертым сыром «Пармезан».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (528,'Промыть листья базилика, обсушить на бумажном полотенце.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (528,'Раздавить чеснок при помощи пестика вместе с обжаренными на сухой сковороде кедровыми орехами и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (528,'Смесь должна превратиться в крем зеленого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (528,'Натереть пармезан.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (528,'Продукты перемешать, добавить оливковое масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (528,'Намазать смесью бутерброды.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (529,'Хлеб нарезать, побрызгать оливковым маслом, запечь в духовом шкафу при температуре 170 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (529,'Помидоры черри разрезать пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (529,'Ломтики багета смазать творожным сыром и готовым соусом «Песто».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (529,'Выложить помидоры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (530,'Багет нарезать ломтиками, подсушить в духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (530,'Нарезать молодой цуккини кружками по два или три миллиметра толщиной, обжарить на растительном масле или запечь на гриле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (530,'Посыпать рубленым чесноком и зеленью, оставить для пропитывания на десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (530,'Остывшие гренки натереть чесноком, выложить сверху цуккини с зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (530,'Бутерброды сбрызнуть оливковым маслом, выложить по ломтику ветчины.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (531,'Подготовить продукты для салата. Куриные яйца отварить. Для того чтобы при варке яйца не полопались их температура должна совпадать с температурой воды. Предотвратит растрескивание и столовая ложка соли, брошенная в воду. Переложить яйца в холодную воду для остывания. Очистить от скорлупы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (531,'Белки натереть на терке, желтки отдельно размять вилкой. Филе семги нарезать мелкими кубиками. Апельсин очистить и разобрать на дольки, затем с помощью ножниц снять пленки и разрезать мякоть ломтиками. Оливки отцедить от рассола и нарезать тонкими кружками. Твердый сыр натереть на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (531,'Выложить салат слоями в форме горки:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (531,'Каждый слой выложить по диаметру меньше предыдущего. Украсить салат сверху икрой и половинкой перепелиного яйца установленного в центре. По краю праздничного слоеного салата «Жемчужина» с семгой можно украсить кружками оливок и рубленой зеленью лука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (532,'Бекон нарезать, обжарить на растительном масле до хруста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (532,'Выложить продукт на бумажное полотенце для впитывания лишнего жира.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (532,'Лук-порей нарезать кружками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (532,'Багет нарезать ломтиками, обжарить на растительном масле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (532,'В масле, оставшемся после приготовления бекона, обжарить лук до золотистой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (532,'На ломтики хлеба намазать козий сыр, выложить лук, бекон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (533,'Консервированные оливки без косточек выложить в чашу блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (533,'Влить растительное масло, взбить в течение десяти секунд.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (533,'Добавить кедровые орехи, зелень петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (533,'Взбить еще раз, в течение двадцати секунд.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (533,'Если масса получилась суховатой – разбавить оливковым маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (533,'Отдельно приготовить пасту из творожного сыра, лимонного сока и соли.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (533,'Ломтики чиабатты подсушить на сковороде, смазать оливковым маслом, натереть чесноком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (533,'Нанести пасту из оливок, украсить зеленью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (534,'Репчатый лук нарезать и обжарить до прозрачного состояния на сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (534,'Добавить нарезанную куриную печень, влить сладкое десертное вино.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (534,'Выпарить, поместить смесь в блендер, взбить в пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (534,'Залить продукт куриным бульоном, прогревать на сковороде до готовности, посолить и поперчить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (534,'Обжарить ломтики хлеба, намазать паштетом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (535,'Печень нарезать кусочками, репчатый лук – полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (535,'Растопить на сковороде сливочное масло, обжарить лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (535,'Добавить печень, потушить под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (535,'Заправить мускатным орехом, соль и перец – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (535,'Остывшие продукты взбить со сливочным маслом и майонезом в блендере.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (535,'Белых хлеб обжарить на сухой сковороде с двух сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (535,'Отварить и очистить перепелиные яйца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (535,'Выложить паштет и яйца на хлеб.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (536,'Персики нарезать кубиками, выложить в кастрюлю, добавить сахар и воду, варить на среднем огне 5-7 минут, измельчить с помощью блендера в пюре, дать остыть',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (536,'Из 2-х лимонов выжать сок, процедить через сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (536,'Остывшее персиковое пюре процедить через сито.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (536,'В графин влить персиковую смесь, лимонный сок и воду, хорошо перемешать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (537,'Нарезаем свиную грудинку на полоски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (537,'Смешиваем соль, черный молотый перец и красный острый.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (537,'Нарезаем куриное филе, отбиваем и посыпаем смесью соли и перцев.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (537,'Натираем морковь, добавляем чеснок и сметану.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (537,'Натираем копчёный сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (537,'Нарезаем овощи колечками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (537,'Нарезаем зелень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (537,'На решетку выкладываем свиную грудинку, куриное филе, морковь, зелень, сыр, шампиньоны, сладкий перец, помидоры и посыпаем каждый слой смесью соли и перцев.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (537,'Накрываем всё это куриным филе и свиной грудинкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (537,'Жарим на углях по 15 минут с каждой стороны.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (538,'Ломтики хлеба подсушить, побрызгать оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (538,'После того, как масло впитается, натереть хлеб чесноком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (538,'Баклажан нарезать тонкими пластинками, обжарить с двух сторон на оливковом масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (538,'Выложить овощи на хлеб.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (538,'Порубить чеснок, посыпать баклажаны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (538,'Сыр «Фета» нарезать кубиками, украсить бутерброды.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (539,'Разморозьте слоеное тесто. Ветчину нарежьте мелкой соломкой и натрите на крупной терке. Сыр натрите на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (539,'Тесто раскатайте в прямоугольный пласт. Выложите сверху слой сыра и ветчины, сверните в плотный рулет. Нарежьте рулет на небольшие рулетики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (539,'Рулетики выложите на застеленный пергаментом противень. Смажьте желтком и посыпьте зеленью или кунжутом. Выпекайте 25-30 минут при 200°С до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (540,'Смешайте дрожжи, 180 мл теплой воды, сахар и 1 ст. ложку муки. Оставьте на 10-15 минут. Отдельно просейте смесь муки и соли на рабочую поверхность. В центре сделайте лунку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (540,'Добавьте в лунку опару, 4 ст. ложки масла и замесите гладкое упругое и нелипкое тесто. Оставьте в теплом месте на час - тесто должно увеличиться в размере в 2 раза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (540,'Измельчите или протрите рикотту, добавьте 1 ст. ложку масла, специи и базилик.Добавьте тертый пармезан и нарезанную кубиками салями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Вбить яйца. Замесить тесто.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (540,'Тесто растяните в пласт толщиной 5 мм и вырежьте круги при помощи пиалы. Смажьте каждую лепешку оливковым маслом, положите по столовой ложке начинки и скрепите края. Защипните мокрыми пальцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (540,'Оставьте пиццы на 20 минут в теплом месте. Смажьте взболтанным с водой яичным желтком. Посыпьте сушеным розмарином, выпекайте 15-20 минут в духовке при 200-220°С.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (541,'Овощи промойте, обсушите. Морковь и лук очистите. Морковь нарежьте очень тонкими ломтиками или натрите на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (541,'Лук порежьте полукольцами, а редис - тонкими круглыми ломтиками. Помидоры нарежьте кусочками среднего размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (541,'Чеснок пропустите через пресс. Зеленый лук измельчите, базилик разделите на листочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (541,'Смешайте все овощи в салатнике. Приправьте солью и свежемолотым черным перцем. Заправьте оливковым маслом и перемешайте.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (542,'Отделите белки от желтков. Белки и 50 г сахара взбейте в пышную массу. Отдельно смешайте желтки, еще 50 г сахара и 1 ст. ложку горячей питьевой воды. Взбейте при помощи миксера до пышности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (542,'К желтковой смеси подмешайте просеянную муку, крахмал и взбитые белки. Перемешайте. Возьмите прямоугольный лист бумаги для выпечки, поместите на противень и выложите сверху тесто, разровняйте лопаткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (542,'Поставьте противень в духовку, разогретую до 200оС, и выпекайте в течение 10 минут. Чистое кухонное полотенце посыпьте 20 г сахара, откиньте на него бисквитный корж.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (542,'Бумагу для выпечки, которая окажется сверху коржа, слегка смочите питьевой водой и аккуратно снимите с теста. Корж вместе с полотенцем сверните рулетом и дайте остыть в таком виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (542,'Для начинки замочите желатин, как указано на упаковке. Ягоды порежьте, отложите половину, добавьте 30 г сахара, лимонный сок и превратите в пюре блендером.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (542,'Пюре подогрейте и распустите в нем желатин. Когда масса начнет застывать, добавьте в нее взбитые сливки. Разверните рулет, смажьте кремом, выложите кусочки клубники (часть оставьте для украшения).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (542,'Снова сверните рулет, уберите в холодильник на 2 часа. Посыпьте сахарной пудрой, украсьте взбитыми сливками и кусочками ягод.','https://vkuso.ru/data/cache/data/01/1ae6c803a01a501_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (543,'Приготовьте бисквитное тесто: разотрите желтки со 150 г сахара и солью. Белки взбейте в густую пену. Смешайте муку, крахмал и разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (543,'Белки осторожно перемешайте с желтками, сверху просейте сыпучие продукты, перемешайте. Выложите в несколько форм (или одну большую) и выпекайте 20-30 минут в зависимости от размера коржа при 175°С.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (543,'Приготовьте начинку. Желатин замочите в холодной кипяченой воде, дайте набухнуть. Выдавите сок из апельсина, подогрейте в нем желатин, чтобы растворился.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (543,'Взбейте сливки. Смешайте творог и остальной сахар, постепенно добавьте сливки, тертую лимонную цедру и лимонный сок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (543,'3 ст. ложки творога смешайте с апельсиновым соком, затем смешайте с остальным творогом. Несколько красивых ягод отложите, остальные порежьте и смешайте с кремом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (543,'Бисквиты разрежьте пополам. Выложите в кулинарные кольца, покройте кремом и разровняйте. Сверху выложите второй корж теста. Накройте пленкой и уберите в холодильник на ночь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (543,'Перед подачей посыпьте бисквиты сахарной пудрой, украсьте "розочками" из взбитых сливок и целыми ягодами. До подачи держите в холодильнике.','https://vkuso.ru/data/cache/data/f5/3eea3f062537af5_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (544,'Приготовьте заварное тесто: в кастрюлю влейте 250 мл воды, добавьте масло и соль, доведите до кипения. В кипящую воду при постоянном помешивании всыпьте муку и растирайте тесто на слабом огне до гладкой и блестящей массы без комков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (544,'Снимите кастрюлю с огня, дайте тесту немного остыть, а затем по одному вбейте яйца. После каждого яйца вымешивайте массу. В конце добавьте разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (544,'Наполните тестом кондитерский мешок с крупной насадкой в виде звезды. На противень постелите пергаментную бумагу. Выдавите тесто из корнетика на противень на расстоянии друг от друга (во время выпечки пирожные увеличатся).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Украшаем пирожное пеной при подаче на стол. Пирожные готовы! Приятного аппетита!',NULL,24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (544,'Поставьте противень в предварительно нагретую до 225°С духовку на 10-15 минут. Не открывайте дверцу во время выпекания, иначе профитроли опадут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (544,'Для начинки смешайте сливки и ванильный сахар и взбейте при помощи миксера до устойчивых пиков. Ягоды промойте, промокните бумажными полотенцами, удалите плодоножки. Порежьте на кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (544,'Готовые пирожные остудите. При помощи острого ножа срежьте с профитролей "крышечки". Сливками наполните кондитерский мешок и выдавите на пирожные. Ягоды положите в сливки и накройте верхними половинками профитролей. Посыпьте профитроли сахарной пудрой и уберите в холодильник до подачи.','https://vkuso.ru/data/cache/data/50/531168953fb8250_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (545,'Воду и сахар доведите до кипения на небольшом огне, помешивая. Кипятите минуту, затем снимите с плиты и отставьте в сторону на полчаса. Перелейте сироп в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (545,'Промытую клубнику превратите в пюре при помощи блендера. Добавьте к сиропу комнатной температуры клубнику и лимонный сок. Снова взбейте блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (545,'Поставьте массу в морозилку на 5 часов, каждый час перемешивайте. Достаньте, разложите по порционным креманкам и украсьте целыми ягодками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (546,'Ягоды промыть и очистить от плодоножек, банан и киви очистить и хорошенько все заморозить в морозильной камере. Ягоды и фрукты взбить ручным блендером и выложить слоями в широкие стаканы или креманки в такой последовательности: банановое пюре, киви, взбитая клубника.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (546,'Сверху уложить слой пломбира и украсить листочками перечной мяты. Можно украсить взбитыми сливками и долькам клубники. Фруктовый десерт «Прохладная радуга» с пломбиром следует подавать на стол сразу после приготовления.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (547,'Клубнику промойте и очистите от плодоножек. У лимонов выжмите сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (547,'В чашу кухонного комбайна или блендера поместите ягоды, сахар и влейте сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (547,'Взбейте компоненты до получения однородной массы. Влейте охлажденную газировку. Тщательно перемешайте и разлейте по стаканам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (548,'Желатин смешайте с 3 ст. ложками питьевой воды, через пару минут нагрейте в микроволновке или водяной бане, но не до кипения. Желатин должен разойтись.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (548,'Промытую клубнику измельчите в блендере, можно дополнительно протереть. Взбейте сливки, постепенно вводя сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (548,'Аккуратно подмешайте к сливкам пюре из ягод, затем введите растворенный желатин. Разложите массу по креманкам и уберите в холодильник минимум на 4 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (548,'Перед подачей украсьте мусс "шапочками" взбитых сливок и целыми ягодами клубники.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (549,'Сначала приготовьте крем. В чаше миксера смешайте сметану, творог, сахарный песок и сок лимона. Взбейте до получения однородной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (549,'Печенье (можно использовать миндальное Амаретти или другое) сбрызните крепкосваренным сладким кофе или мятным ликером. Поломайте на небольшие кусочки. Клубнику помойте и тонко порежьте. Несколько целых ягод оставьте для украшения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (549,'Подготовьте 4 высоких прозрачных креманки или бокала. На дно бокалов уложите слоями клубнику, творожный крем и кусочки печенья. По возможности сделайте несколько таких слоев.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (549,'Сверху посыпьте небольшим количеством печенья и уберите десерт на час в холодильник. Перед подачей украсьте целыми ягодами клубники, например, насадив их на стенку бокала.','https://vkuso.ru/data/cache/data/1a/f1e6c07c522f51a_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (550,'Смешайте 400 мл молока и сахар, поставьте на огонь и доведите до кипения. Остальное молоко перемешайте с крахмалом. Добавьте желтки, ванильный экстракт и взбейте при помощи миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (550,'Очень тонкой струйкой введите желтковую массу к молочной, интенсивно помешивая. Варите 2 минуты, помешивание не прекращайте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (550,'Немного остудите массу, разлейте по формам, накройте пищевой пленкой "в контакт" и уберите в холодильник на некоторое время. Пудинг должен застыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (550,'Клубнику промойте, нарежьте тонкими ломтиками. Выложите на охлажденный десерт и сразу же подайте к столу.','https://vkuso.ru/data/cache/data/ce/b8f3afc3f9b91ce_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (551,'Несколько листочков мяты отложите для украшения, остальные нарежьте и посыпьте сахаром. Перемешайте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (551,'Из 2-х лаймов выжмите сок, а третий нарежьте тонкими кружочками. Добавьте к мяте и сахару лаймовый сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (551,'Получившуюся массу распределите по 2-м бокалам, добавьте ломтики лайма, влейте яблочный сок и тоник. Подайте с кубиками льда, украсив веточками мяты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (552,'Просейте муку с содой и какао-порошком. Добавьте соль и лимонную кислоту. Масло и сахар взбейте на невысоких оборотах миксера, добавьте яйцо и перемешайте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (552,'Соедините яично-масляную смесь с мучной, добавьте шоколадные капли. Перемешайте до получения вязкого теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (552,'Противень покройте пергаментом, смажьте растопленным сливочным маслом. Мокрой ложкой выложите порции теста на расстоянии друг от друга. Края сформируйте влажными руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (552,'Выпекайте 12-14 минут при 200°С. Дайте немного остыть на противне, затем снимите и полностью остудите. Подайте с чаем или молоком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (553,'Отцедить грибы от маринада, и порезав их напополам, выложить на дно салатника. Нашинкованный лук обжарить на масле. Остудить и выложить слоем на маринованные грибы. Сметану соединить с майонезом в равных пропорциях, по желанию в соус можно добавить ложку дижонской горчицы или пару капель свежего лимонного сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (553,'Полученным соусом смазать каждый слой начиная с лукового. Для удобства, соус можно поместить в кондитерский мешок или за неимением такового в полиэтиленовый кулек с маленьким отверстием в одном из углов, и сделать сетку из соуса на каждом слое салата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (553,'Отварной картофель очистить и натереть на терке. Уложить не плотным слоем на обжаренный лук политый соусом. Четвертым слоем выложить натертую на крупной терке сырую морковь. Не забыть о соусе. Отварное мясо или язык нарезать соломкой, либо же мелкими кубиками и уложить пятым слоем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (553,'Промазать соусом. Верхним слоем уложить сыр, измельченный блендером, или натертый на терке. Украсить слоеный салат с вареным мясом  и грибами можно зеленью петрушки и дольками лимона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (554,'К творогу добавляем желтки, соль, сахар, ванилин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (554,'Все очень хорошо перемешиваем и добавляем муку и перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (554,'Формируем из теста сырники.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (554,'Обжариваем на разогретой сковороде по 2 минуты с каждой стороны, затем отправляем в заранее разогретую духовку при 180 градусах на 5 минут. Сырники готовы! Приятного аппетита!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (555,'Картофель очистите и порежьте тонкими круглыми ломтиками. Форму для запекания смажьте сливочным маслом. Чеснок очистите, разрежьте пополам и натрите дно и борта формы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (555,'Выложите в форму ломтики картофеля словно черепицу в несколько слоев. Приправьте солью, свежемолотым черным перцем и тертым мускатным орехом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (555,'Полейте сливками и выпекайте в духовке при температуре 180°С в течение 45 минут до аппетитной корочки.','https://vkuso.ru/data/cache/data/af/0662aa61551e1af_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (556,'Лук и морковь очистите. Лук измельчите, морковь натрите на терке. Грибы порежьте тонкими ломтиками. Обжарьте лук и морковь в растительном масле, добавьте грибы и мясной фарш. Готовьте 8-10 минут, помешивая. Приправьте по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (556,'Всыпьте муку, перемешайте и готовьте еще минуту. Влейте бульон и тушите под крышкой до загустения. Выложите в жаропрочную форму и поставьте в духовку на 20 минут, температура - 190°С.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (556,'В это время приготовьте картофельное пюре. Разомните горячий картофель, добавьте масло и подогретое молоко. Выложите сверху на мясную начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (556,'Посыпьте слой картофельного пюре сыром. Температуру духовки увеличьте до 200°С. Выпекайте пирог еще 15 минут до золотистой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (557,'Отмерьте 2/3 от общего количества сахара и разотрите с яйцами и ванилью до пышной светлой массы. Разведите охлажденным кипяченым молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (557,'Оставшийся сахар выложите в сотейник, смочите водой и прогрейте на умеренном огне при помешивании до получения карамели красно-коричневого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (557,'Половину карамели добавьте в молочно-яичную массу и перемешайте. Остальную карамель распределите по 6-ти смазанным маслом формочкам - налейте небольшое количество, на донышко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (673,'Выложить овощную начинку, кусочки сливочного масла.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (557,'Формочки заполните кремом, поставьте на противень. Влейте в противень горячую воду так, чтобы доставала до середины высоты формочек. Выпекайте в духовке при 160°С 30-40 минут, пока пудинги не загустеют. Готовность можно проверить зубочисткой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (557,'Дайте готовым пудингам остыть, затем уберите в холодильник на несколько часов. Готовые десерты переверните на тарелку, при помощи ножа освободите от формочек. Сервируйте ягодами и ломтиками фруктов.','https://vkuso.ru/data/cache/data/5f/15ba15d5eebbd5f_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (558,'Куриное филе обмыть под краном и дать стечь лишней жидкости. Изрубить мясо мелкими кусочками. В рубленое мясо добавить пару ложек жирного майонеза, вбить яйцо, хорошенько вымешать смесь. Посолить, добавить специи и давленый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (558,'Тем, кто не особо жалует чеснок, можно попробовать добавить рубленный мелко лук, который при жарке в кляре приобретает сладковатый привкус и придает блюду пикантные нотки. Добавить просеянную муку, можно пополам с крахмалом. Еще раз вымешать смесь, по консистенции она похожа на тесто как на оладьи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (558,'Разогреть растительное масло на сковороде, и зачерпнув столовой ложкой смоченной холодной водой, тесто выпекать его небольшими порциями. Готовые оладьи «Растрепки» из куриной грудки хороши как горячими, так и в холодном виде, их можно подавать на обед или завтрак с гарниром, или сделать бутерброды добавив листочек салата и свежие овощи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (559,'Хлеб порезать небольшими кубиками. Залть теплым молоком и оставить на 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (559,'Лук очистить, мелко порезать и обжарить в масле до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (559,'Петрушку помыть, обсушить и мелко порубить. Смешать хлебные кубики, лук и зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (559,'Яйца взбить венчиком, приправить по вкусу. Добавить хлебную массу и перемешать. Если получилось жидковато, добавить муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (559,'Влажными руками слепить шарики диаметром 6 см из хлебной массы. В большой кастрюле вскипятить 2 литра воды, подсолить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (559,'Осторожно опустить шарики в воду и варить на слабом огне 20 минут. Достать шумовкой.','https://vkuso.ru/data/cache/data/b8/f3d9a3bb453f1b8_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (560,'Яблоки порезать тонкими ломтиками или соломкой. Сбрызнуть 1 ст. ложкой лимонного сока, чтобы мякоть не потемнела. Несколько ломтиков отложить для украшения. У сельдерея снять верхнюю кожицу, мякоть порезать тонкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (560,'Отложить несколько ядер орехов для украшения, остальные орехи мелко порубить. Соединить в одной миске яблоки, сельдерей и орехи, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (560,'В отдельной емкости приготовить соус из майонеза, оставшегося лимонного сока, соли и черного перца. Взбить при помощи венчика и заправить салат. Перемешать, убрать в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (560,'Подавать Вальдорф на стол охлажденным на листьях зеленого салата, украсив ломтиками апельсина, отложенными кусочками яблока и ядрами грецких орехов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (561,'Ягоды клубники аккуратно промойте, обсушите. Листики не убирайте. В верхушку каждой ягоды вставьте зубочистку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (561,'Горький шоколад поломайте, вместе с маслом поместите в сотейник и растопите, помешивая, на водяной бане (можно также это сделать в пароварке).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (561,'Окуните каждую ягоду в растопленный шоколад, дайте слегка остыть,  затем выложите на блюдо до полного остывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (561,'Растопите белый шоколад (например, в микроволновке). С помощью зубочистки нанесите полоски белого шоколада на поверхность горького. Держите десерт в холодильнике до подачи на стол.','https://vkuso.ru/data/cache/data/c2/9d5d81267ccb3c2_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (562,'Клубнику промойте, высушите, удалите плодоножки. Ягоды пюрируйте при помощи блендера. Добавьте молоко, сахар и сок лимона, взбейте венчиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (562,'Получившуюся массу выложите в пластиковый контейнер с крышкой и уберите в холодильник на 1 час. Затем переложите емкость в морозилку на 2-4 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (562,'Смочите круглую ложку для мороженого (или обычную столовую) теплой водой и сформируйте шарики. Выложите в креманки и сразу же подайте к столу.','https://vkuso.ru/data/cache/data/08/6d092615b410c08_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (563,'Шпик и луковицу порежьте, потушите вместе в сковороде. Добавьте мясо, бульон, яблочный сок, очищенные и порезанные помидоры и специи по вкусу. Тушите на среднем огне под крышкой 35 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (563,'На другой сковороде растопите масло, добавьте муку и обжарьте до кремового оттенка. Влейте молоко, добавьте соль, перец и уваривайте соус на медленном огне 10 минут при постоянном помешивании.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (563,'Яблоки очистите, удалите сердцевину, мякоть порежьте ломтиками. В форму для выпечки налейте немного соуса и выложите листы теста. Сверху выложите яблоки, мясную начинку, соус и снова тесто. Повторите слои, пока не закончатся продукты. Верхний слой - тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (563,'Залейте лазанью остатками соуса, посыпьте сыром и поставьте запекаться в духовку на 40 минут при температуре 200°С до румяной корочки.','https://vkuso.ru/data/cache/data/ea/959afc92f46a5ea_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (564,'Черный хлеб выложить на противень, побрызгать постным маслом, обжаривать в духовом шкафу в течение восьми минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (564,'Сливочный сыр заправить молотым черным перцем и лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (564,'Свежие огурцы нарезать вдоль, ломтиками, копченую семгу – кусочками небольшого размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (564,'Намазать бутерброды сливочным сыром, выложить рыбу и огурцы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (565,'Хлеб нарезать ломтиками, обжарить с двух сторон на оливковом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (565,'Шампиньоны очистить и отварить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (565,'Выложить на хлеб сыр, мясо, хорошо промытые листья рукколы, грибы, нарезанные пластинками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (565,'Сбрызнуть оливковым маслом, посолить и поперчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (566,'Хлеб подсушить и подрумянить на сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (566,'Нарезать мелкими кубиками помидоры, приправить соусом «Табаско».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (566,'Продольными пластинами нарезать соленые огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (566,'На готовые тосты намазать сливочный сыр, выложить помидоры и свернутые в трубочку огурцы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (566,'Посыпать толченым черным перцем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (567,'Сделать сухую смесь из просеянной муки, разрыхлителя и какао – порошка. Добавить в нее щепотку соли. Масло размягчить, добавить в него сахар и взбивать миксером на средних оборотах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (567,'Продолжая взбивать масло вбить постепенно яйца. Чередуя добавлять молоко и сухую смесь из муки и какао. Противень застелить пергаментной бумагой и хорошо промаслить сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (567,'Жидкое тесто выложить небольшими порциями в форме круглых блинчиков на небольшом расстоянии друг от друга. Поставить в духовку и выпекать 10 – 15 минут. За это время лепешки поднимутся и немного зарумянятся.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (567,'Приготовление крема: белки соединить с сахарной пудрой,  добавить ванилин и соль. При постоянном помешивании нагреваем смесь на водяной бане до 43 градусов, за непродолжительное время сахар должен раствориться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (567,'Взбиваем белки миксером до увеличения массы втрое. Белковая пена должна быть плотной и не растекаться. При взбивании белков, понемногу добавляем размягченное сливочное масло, которое придает крему плотную и гладкую структуру.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (567,'На половину коржиков нанести яично-масляный крем и прикрыть вторыми половинками слегка придавливая, чтобы крем распространился на края. Нежные шоколадные пирожные с ванильным кремом готовы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (568,'Макароны отварите в подсоленной воде до готовности. Слейте жидкость, оставив пару ложек. Положите макароны в теплое место, накройте крышкой, чтобы не остыли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (568,'Бекон или грудинку нарежьте полосками или кубиками. Обжарьте на сковороде до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (568,'Смешайте сливки, яйца, немного молотого перца, сыр и поставьте на сильный огонь на 40 секунд, постоянно помешивайте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (568,'Убавьте огонь до минимального, влейте пару ложек воды от варки макарон и готовьте соус 2 минуты, помешивая. Следите, чтобы огонь был очень слабым, иначе яйца свернутся.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (568,'Когда сыр растает, добавьте бекон, макароны и базилик. Перемешайте, выключите огонь и дайте блюду постоять пару минут. Разложите по подогретым тарелкам и сразу подайте к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (569,'Форму для выпечки смажьте маслом и выложите пергаментом. Перемешайте муку, соль, корицу, разрыхлитель и коричневый сахар. Добавьте яйца и растительное масло, затем морковь и крупно натертый банан.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (569,'Выложите получившуюся массу в форму, поставьте в разогретую до 175°С духовку и выпекайте 20-25 минут. Охладите в форме.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (569,'Для крема смешайте творог, сахарную пудру, размягченное сливочное масло и лимонный сок. Взбейте при помощи миксера до получения сливочной консистенции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (569,'Пирог извлеките из формы, смажьте толстым слоем крема, украсьте декоративными марципановыми морковками и порежьте на порции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (570,'Лук очистите, тонко нашинкуйте и обжарьте в масле до золотистого цвета. Поперчите, влейте немного воды. Доведите до кипения и добавьте нарезанную кубиками говядину. Посолите.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (570,'Тушите под крышкой до мягкости мяса, периодически подливая воду. В это время помойте перцы и помидоры, обсушите. У помидоров удалите кожуру. У перцев удалите семена и перегородки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (570,'Порежьте перцы и помидоры кусочками. Добавьте к мясу, когда оно станет мягким. Тушите до готовности овощей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (570,'Перемешайте сметану и небольшое количество муки. В самом конце тушения добавьте сметанную смесь к мясу и овощам. Перемешайте и немного подержите на огне, чтобы подливка загустела.','https://vkuso.ru/data/cache/data/f8/7dd53ebd4979af8_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (571,'Луковицы очистите и тонко нашинкуйте. Растопите масло на сковороде, добавьте лук и тушите до полного размягчения 15-20 минут. Добавьте сахар и муку, готовьте 3 минуты при помешивании.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (571,'Переложите лук в кастрюлю. Добавьте вино, бульон, соль и тимьян. Варите суп на умеренном огне под крышкой около 20 минут. Батон порежьте ломтиками, выложите на противень и запеките в разогретой до 200оС духовке до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (571,'Суп разлейте по огнеупорным горшочкам. Сверху положите ломтик хлеба, посыпьте сыром и поставьте в духовку, пока сыр не расплавится. Сразу же подайте к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (572,'Грибы очистить от загрязнений и промыть, нарезать, обжарить на оливковом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (572,'Порубить свежую зелень и чеснок, добавить в грибную обжарку и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (572,'Посолить, поперчить, посыпать нарезанным перцем чили.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (572,'Перемешать, по необходимости долить оливковое масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (572,'Положить немного сливочного масла, влить воду, лимонный сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (572,'Смесь потушить на тихом огне в течение трех или четырех минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (572,'Багет нарезать, обжарить, натереть чесноком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (572,'Выложить грибы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (573,'Бородинский хлеб нарезать поперек, толщина ломтиков – 0,6 сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (573,'Жарить на гриле, перевернуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (573,'Сладкий болгарский перец очистить от семян, нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (573,'Почистить морковь, нарезать небольшими квадратиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (573,'Обжарить овощи вместе с репчатым луком, чесноком, нарезанными помидорами на растительном масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (573,'Приправить смесь сахарным песком, перцем, томатной пастой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (573,'Готовое лечо выложить на хлеб, в середину выложить сметану.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (574,'Картофель почистить и промыть. Перетереть клубни на средней терке и дать немного отстояться. Слить образовавшийся сок. Лук очистить и натереть следом за картофелем. Ветчину и сыр натереть на более мелкой терке и добавить в смесь. Прибавить специи и рубленую зелень укропа. Хорошо вымешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (574,'Вбить яйца и примешать просеянную муку. Тесто на драники получается немного жидковатым, но в процессе жарки изделия прихватываются хрустящей корочкой и не расплываются. Жарить драники, выкладывая их на прогретое растительное масло небольшими порциями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (574,'Воспользовавшись  ложкой или лопаткой необходимо придать правильную форму овала уже не сковороде. Первые пару минут жарить, накрыв крышкой, чтобы драники немного пропарились в середине и картофель не был сырым. Благодаря сыру, который плавится, картофельные драники с сыром и ветчиной имеют более плотную структуру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (575,'Свежий базилик промыть, обсушить, оборвать листочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (575,'Снять кожицу с помидоров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (575,'Мякоть нарезать квадратиками, выложить в салатницу, присыпать базиликом и любимыми специями. Можно использовать итальянские травы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (575,'Порубить чеснок, добавить в помидоры, сбрызнуть оливковым маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (575,'Соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (575,'Массу перемешать и оставить для пропитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (575,'Прогреть на сковороде еще одну порцию оливкового масла, обжарить ломтики хлеба до получения золотистой корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (575,'Выложить помидорную смесь с чесноком и посыпать бутерброды творогом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (576,'Картофель очистите и порежьте тонкими круглыми ломтиками. Разложите на большом полотенце и дайте обсохнуть. Сыр крупно натрите, чеснок очистите и измельчите.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (576,'2/3 сливок приправьте солью, перцем и мускатным орехом. Форму для запекания смажьте маслом и выложите слой картофельных ломтиков. Немного посолите, полейте 2 ст. ложками сливок и посыпьте небольшим количеством сыра. Повторяйте слои, пока не заполните форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (576,'Залейте сверху остатками сливок с приправами. Поставьте в духовку, разогретую до 180°С, на 50 минут. Остальные сливки и яйцо взбейте венчиком, посолите и поперчите.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (576,'Достаньте запеканку из духовки, залейте яично-сливочной массой. Готовьте еще 15 минут, чтобы верх подрумянился. Перед подачей украсьте запеканку веточкой свежего розмарина.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (577,'Нут залить водой и оставить на ночь. Утром воду слить, нут промыть, влить чистую воду и варить на слабом огне до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (577,'Сырой белый кунжут и 0,5 ст. ложки оливкового масла измельчить при помощи пестика в ступке до состояния пасты (тахины).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (577,'Смешать в одной емкости нут, тахину, 6 ст. ложек масла, очищенный чеснок, свежевыжатый лимонный сок, зиру и немного соли. Взбить блендером до получения однородной пасты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (577,'Выложить хумус в тарелку, полить оставшимся оливковым маслом. Подать к столу с овощами и ломтиками хлеба, питы или лаваша.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (578,'Противень покройте пергаментом, выложите миндаль и поставьте в разогретую до 180°С духовку на 10-15 минут. Периодически перемешивайте орехи лопаткой и следите, чтобы не подгорели. Высыпьте в отдельную емкость и дайте остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (578,'Растопленное масло, соль, ванильный экстракт, яйца и желток взбейте при помощи миксера. Добавьте сахар, разрыхлитель с мукой и снова взбейте на низких оборотах миксера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (578,'Добавьте орехи и шоколадные гранулы. Если тесто получилось слишком густым, влейте чайную ложку воды, если жидким - всыпьте немного муки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (578,'Замесите тесто и сформируйте 2 батона размером примерно 25х7 см. Выложите на противень и выпекайте полчаса при 175°С в духовке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (578,'Дайте батонам немного остыть, нарежьте ломтиками толщиной 1,5 см и снова выпекайте 25 минут при 150°С в духовке до золотистого цвета. Переверните на другую сторону и пеките 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (579,'Куриные ножки промойте и обсушите с помощью бумажных полотенец. Поместите в глубокую емкость, приправьте солью и черным перцем. Залейте кефиром. Закройте миску пищевой пленкой и уберите в холодильник на 4-5 часов, можно на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (579,'Перемешайте муку, красный перец, сушеный чеснок и 1 ч. ложку соли. В отдельную миску высыпьте панировочные сухари. Обмакните каждую ножку сначала в муку, затем в сухари. Излишки сухарей стряхните.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (579,'В глубокой сковороде разогрейте растительное масло (налейте слой около 3 см). Опустите ножки и обжарьте до золотистого цвета с обеих сторон в течение примерно 10 минут. Сервируйте свежей зеленью и ломтиками лимона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (580,'Рульку разрежьте на 8 порционных круглых кусков. Морковь нарежьте тонкими кружочками, лук и сельдерей - мелким кубиком. Если используете свежие помидоры, очистите их от кожицы, часть мякоти измельчите в пюре, другую часть - нарежьте кубиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (580,'Зубчики чеснока пропустите через пресс. Муку смешайте с солью и черным перцем. Измельченные морковь, сельдерей, лук и чеснок обжарьте в половине растительного масла в течение 5 минут. Переложите зажарку в жаропрочную толстостенную посуду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (580,'Куски мяса хорошо обваляйте в муке, затем обжарьте до корочки в смеси растительного и сливочного масел. Выложите телятину сверху на овощную зажарку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (580,'В сковороду, где жарилось мясо, добавьте помидоры, бульон, томатную пасту, чайную ложку тимьяна и лавровые листья. Доведите смесь до кипения, затем убавьте огонь и готовьте 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (601,'Ингредиенты перемешать, всыпать специи. Для начинки можно использовать белый перец, чесночный порошок, сушеный орегано.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (580,'Добавьте соус к мясу и зажарке. Накройте емкость крышкой и томите на плите на маленьком огне полтора-два часа, пока мясо не станет мягким. Оссобуко можно также запечь в духовке при 160°С в течение 2,5 часов.','https://vkuso.ru/data/cache/data/27/60c3eeb6a5a9927_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (581,'Мякоть говядины порежьте кубиками среднего размера. Обжарьте мясо в небольшом количестве растительного масла до румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (581,'У болгарского перца удалите перегородки и семена, мякоть порежьте кубиком. Морковь и лук очистите, порежьте лук кубиком, морковь - тонкими полукольцами. Лук добавьте к мясу, всыпьте паприку и обжаривайте в течение 7 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (581,'Переложите мясо с луком в кастрюлю, добавьте болгарский перец, залейте кипящей водой и поставьте на огонь. Когда закипит, закройте крышкой и варите 1 час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (581,'Добавьте нарезанные кубиком помидоры и измельченный острый перец. Готовьте 15 минут, затем добавьте морковь. Готовьте еще 10 минут. Добавьте очищенный и нарезанный картофель. Опустите в суп лавровый лист.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (581,'Варите суп в течение 10 минут, посолите по вкусу. Готовьте еще минут 5 и приправьте измельченным чесноком. Дайте супу потомиться еще 5 минут и выключите плиту. Оставьте суп-гуляш  под крышкой минут на 10, затем разлейте по тарелкам, посыпьте измельченной зеленью и подайте с черным хлебом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (582,'Нарежьте мякоть тыквы крупными кубиками. Лук и морковь очистите, морковь порежьте брусочками, лук - полукольцами. В сковороде с высокими бортами разогрейте масло, добавьте туда овощи и немного обжарьте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (582,'Влейте 100 мл питьевой воды, добавьте звездочку бадьяна и тушите под крышкой на умеренном огне, пока овощи не станут мягкими. Если необходимо, подливайте еще жидкость. В конце варки бадьян извлеките.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (582,'Выложите овощи в глубокую кастрюлю, взбейте при помощи миксера, постепенно вливая подогретые сливки. Приправьте по вкусу солью и перцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (582,'Поставьте кастрюлю с супом на огонь и прогрейте, не доводя до кипения. Разлейте суп по тарелкам, сервируйте сливками или маслом из тыквенных косточек, сделав на поверхности супа красивые разводы. Также отлично подходят для украшения обжаренные на сухой сковороде тыквенные семечки.','https://vkuso.ru/data/cache/data/dd/26942a523f49edd_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (583,'Порезанный кубиками лук, пассировать в растительном масле до прозрачности. И немного отцедив от лишнего жира, остудить. Мясной фарш хорошенько размять и смешать с обжаренным луком. Присолить, добавить черный, свежее смолотый перец и вбить яйцо. Вымешать фарш.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (583,'При тепловой обработке, яичный белок сжимает изделие, вытесняя из него мясной сок, поэтому, рациональнее использовать только желтки, в данном случае нам понадобятся два желтка. В фарш добавить 2/3 тертого сыра и мелкорубленую зелень.  Выбить фарш, придавая ему целостность и более плотную структуру. Смазать подходящую по объему форму и выложить в нее фарш. Верх хлебца промазать кетчупом и застелить дольками помидор.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (583,'Запекать в течение получаса, в предварительно разогретой до 230 градусов духовке. Присыпать верхушку хлебца оставшимся тертым сыром и допекать еще 30 минут. Готовое блюдо остывает в форме, если в процессе запекания образуется некоторая жидкость, ее необходимо слить. Холодный хлебец из мясного фарша с сыром нарезать пластинами и подавать к столу, это отличная замена колбасам из магазина.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (584,'С лимона аккуратно сняла цедру без белого слоя, т.к. он дает горечь, и растерла её с сахаром. Затем к сахару с цедрой добавила яйца, взбила в пышную светлую массу. Взбивала 5 минут.','https://vkuso.ru/data/cache/data/1e/bb6d9c586d7691e_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (584,'К взбитым яйцам добавила соль, лимонный сок, подсолнечное масло без запаха, растопленное сливочное масло и перемешала в однородную массу.','https://vkuso.ru/data/cache/data/20/c320491f1292a20_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (584,'Просеянную муку соединила с разрыхлителем и аккуратно, поэтапно соединила с яичной смесью.','https://vkuso.ru/data/cache/data/88/c1f6bdb9c2eae88_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (584,'В форму размером 22 см вылила большую часть теста, на тесто выложила клубнику и закрыла оставшимся тестом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (601,'Ломтики хлеба поместить на сковороду гриль без жира.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (585,'Растопите масло в сотейнике или в микроволновке. Песочное печенье измельчите при помощи блендера или толкушки для приготовления пюре. Перемешайте с маслом. Выложите в выстланную пергаментом разъемную форму на дно, сформируйте бортик. Уберите в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (585,'Для начинки взбейте на небольших оборотах миксера сахарный песок и сливочный сыр. Добавьте сметану и снова взбейте миксером. По одному введите яйца, затем всыпьте ванильный сахар. Взбейте на небольших оборотах миксера до получения однородной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (585,'Достаньте форму с основой из холодильника, выложите крем поверх печенья. Форму по бокам плотно оберните фольгой. Поставьте форму в противень с высокими бортами. Налейте в противень горячей воды, чтобы она доходила до половины высоты формы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (585,'Выпекайте в разогретой до 180°С духовке в течение часа. Затем дайте чизкейку постоять в выключенной духовке с открытой дверцей минут 20-30. Достаньте из духовки, остудите. Осторожно снимите разъемную форму. Уберите чизкейк в холодильник на 4 часа, а лучше на ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (585,'Перед подачей достаньте чизкейки из холодильника. Миндаль порежьте, обжарьте, посыпьте поверхность чизкейка (таким образом можно замаскировать трещины на поверхности крема, если они появились). Посыпьте сахарной пудрой и подайте к столу.','https://vkuso.ru/data/cache/data/ad/f0c8ae560f900ad_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (586,'Лук очистите, измельчите. Чеснок очистите, разрежьте, извлеките зеленую серединку. Мякоть чеснока пропустите через пресс. Перемешайте дважды пропущенный через мясорубку фарш, овощи, паприку. Добавьте по 1 ч.ложке соды и черного перца, посолите. Кстати, вместо соли можно использовать соевый соус - примерно 4 ст. ложки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (586,'Очень тщательно вымесите фарш, положите в миску, накройте пищевой пленкой или крышкой и уберите в холодильник на несколько часов, в идеале - на всю ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (586,'Сформируйте колбаски - они должны быть достаточно длинными (не менее 10 см), так как во время жарки они уменьшатся в длине, а также достаточно тоненькими (около 1,5 см). Колбаски можно сформировать в руках из лепешки или продавливая фарш через горлышко пластиковой бутылки, ну или картонной упаковки из-под кефира.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (586,'Получившиеся плотные колбаски смажьте растительным маслом и выложите на решетку гриль. Сбоку поместите пару небольших картофелин и накройте решетку верхней частью. Картофелины нужны, чтобы колбаски не расплющило.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (586,'Обжарьте чевапчичи на разогретых углях в течение 12-15 минут, периодически поворачивая решетку, до красивой румяной корочки. Подайте с гарниром из риса и овощей. Также к колбаскам отлично подойдет греческий соус "Дзадзики".','https://vkuso.ru/data/cache/data/57/338e774d91d0957_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (587,'Сахар перемешайте с содержимым стручка ванили. Отмерьте одну треть и отложите в сторону - пригодится для обсыпки. Остальной сахар смешайте с миндалем, мукой, крахмалом и ванильным сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (587,'Добавьте нарезанное хлопьями сливочное масло и быстро замесите тесто. Соберите в ком и отправьте на полчаса в холодильник. Затем скатайте из охлажденного теста колбаску, нарежьте на кусочки величиной с грецкий орех и из каждого сформируйте рогалик-полумесяц.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (587,'Противень покройте пергаментной бумагой и выложите рогалики. Поставьте в разогретую до 150°С духовку на 10-15 минут. Аккуратно снимите с противня, сразу обваляйте в оставшейся сахарно-ванильной смеси.','https://vkuso.ru/data/cache/data/55/76d6942af934355_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (588,'Свеклу промойте, залейте холодной водой, доведите до кипения, убавьте огонь и варите 2 часа до готовности. Остудите, очистите и мелко нарежьте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (588,'Чеснок очистите и измельчите. Базилик вымойте, оборвите листочки. Макароны отварите до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (588,'Масло разогрейте в сковороде, добавьте чеснок и немного подрумяньте. Добавьте свеклу и готовьте 3 минуты. Добавьте макароны и перемешайте. Поперчите по вкусу, солить не нужно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (588,'На сухой сковороде слегка обжарьте орехи. Макароны со свеклой разложите по тарелкам, посыпьте рублеными орехами и листочками базилика.','https://vkuso.ru/data/cache/data/dd/548356e825d79dd_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (589,'Куриное филе моем под водой, и сушим его бумажным полотенцем, после этого его нужно распластать на 2 часть, далее слега отбить,',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2403,'Влить пиво небольшими порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (589,'Перекладываем в глубокую тарелку, и по вкусу добавляем приправы, соль, перец, приправу для курицы, и в конце заливаем кефиром. Убираем в сторону на 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (589,'Картофель чистим, моем, нарезаем на дольки, перекладываем в миску, и так же добавляем приправы по вкусу, красный перец, сушенный чеснок, соль, перец, и немного растительного масло, перекладываем на противень, и отправляем в духовке при 180*С на 20-25 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (589,'Пока картофель в духовке, нужно пожарить куриную грудку, разогреваем сковородку, добавляем немного растительного масла, и укладываем куриное филе. С каждой стороны обжариваем около 4-5 минут. Как только приготовили куриную грудку, перекладываем ее на тарелку, туда же перекладываем картофель, и по желанию ломтики огурца.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (590,'С копченого окорока снять шкуру, удалить хрящи и отделить мясо от костей. Нарезать мясо кубиками довольно крупно. Яйца отварить вкрутую в подсоленной воде. Очистить от скорлупы и нарезать такими же по размеру кубиками как и куриное мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (590,'Корейскую морковь можно приобрести в магазине или на рынке, или же приготовить самостоятельно. Для этого необходимо натереть сочную морковь на терке для моркови по-корейски, добавить смесь приправ с одноименным названием, чеснок, подсолнечное масло и капельку уксуса.  Выдержать салат «Чудо» с морковью по-корейски в прохладном месте пару часов..',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (591,'Лук и чеснок очистите, измельчите. Помидоры надрежьте крест-накрест, опустите в кипящую воду на 30 секунд, затем снимите кожицу. Мякоть порежьте. Базилик мелко порубите. Помидоры мелко порежьте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (591,'В сотейнике разогрейте масло, добавьте лук и чеснок, подрумяньте. Добавьте кусочки помидоров и тушите на умеренном огне 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (591,'Добавьте вино, вяленые томаты и базилик. Посолите, поперчите, готовьте в течение 10 минут. В это время отварите спагетти в подсоленной воде до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (591,'Откиньте макароны на дуршлаг, разложите по тарелкам, сверху выложите томатный соус. Украсьте блюдо зеленью (по желанию) и подайте к столу.','https://vkuso.ru/data/cache/data/4e/a30bf9a07596f4e_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (592,'Два круглых бокала для красного вина охладить, наполнив кубиками льда. Затем лед высыпать. Веточки мяты промыть, обсушить, оборвать листья.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (592,'Добавить в каждый бокал по несколько листиков мяты, по паре ломтиков лайма и апельсина (лимона). Слегка помять ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (592,'Влить бузинный сироп, Просекко и содовую. Добавить кубики льда. Сразу же подать.','https://vkuso.ru/data/cache/data/23/ce0e89f26aba723_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (593,'У яблока отрежьте несколько ломтиков для украшения, сбрызните лимонным соком, отложите. Остальные яблоки очистите, удалите сердцевину. Мякоть порежьте и поместите в кастрюлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (593,'Влейте немного воды, добавьте сахар и проварите на умеренном огне при постоянном помешивании. Когда яблоки станут мягкими, снимите с огня, остудите и протрите через сито. Добавьте остатки лимонного сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (593,'1 ст.ложку желатина залейте небольшим количеством воды, дайте набухнуть, распустите на плите или в микроволновке, а затем добавьте в яблочное пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (593,'Для сметанного мусса взбейте сметану, сахар по вкусу и ванильный сахар. Остальной желатин замочите, дайте набухнуть, распустите и подмешайте к сметанной массе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (593,'В прозрачные креманки выложите слоями яблочную и сметанную массу, можно добавить крупно раскрошенное миндальное печенье. Поставьте в холодильник до полного застывания. Перед подачей украсьте отложенными ломтиками яблок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (594,'В чашу блендера поместите охлажденное молоко, чуть подтаявшее мороженое и ягодный сироп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (594,'Взбейте блендером при помощи насадки-венчика в течение 2-3-х минут до пышной пены.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (594,'Разлейте молочный коктейль по бокалам, дополните трубочками и сразу же подайте к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (595,'Пасту отварить в большом количестве подсоленной воды до готовности «Аль денте» — это когда тесто имеет мягкую оболочку, но не проваренную сердцевину, и немного хрустит при пробе на зубок. Фарш выложить на разогретую сковородку и готовить, постоянно размешивая, не давая мясу запекаться комками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (623,'Измельчить в крошку печенье и грецкие орехи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (595,'Когда фарш почти готов прибавить к нему томатную пасту разведенную с кипяченой водой остуженной до комнатной температуры. Можно использовать и свежие помидоры, предварительно протертые через металлическое сито или томатный сок. В конце приготовления мясную начинку посыпать перцем и посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (595,'Белокочанную капусту нарезать мелкими полосками, лук нашинковать полукольцами. Обжарить овощи на подсолнечном масле до мягкости. Форму для выпекания смазать жиром. Выложить слоями листы лазаньи чередуя начинки – мясную с овощной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (595,'Верхний слой лазаньи щедро присыпать тертым пармезаном или другим острым сыром. Выпекать в течение 20 минут в предварительно разогретой до 180 градусов в духовке. Лазанья с мясным фаршем и капустой хороша как в горячем виде, так и на второй день, когда блюдо настоится, пропитавшись соком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (596,'Яйцо аккуратно разбить в чашку, затем перелить в кипящую воду с уксусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (596,'Огонь убавить до минимального, время варки – две или три минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (596,'Яйцо вынуть, обсушить на бумажном полотенце.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (596,'Помидоры разрезать пополам, удалить семена.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (596,'Застелить фольгой форму, выложить томаты, посолить и поперчить, сбрызнуть оливковым маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (596,'Время запекания в духовом шкафу – пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (596,'Оливковое масло прогреть на сковороде, обжарить хлеб с двух сторон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (596,'Запеченные помидоры измельчить, выложить на хлебные ломтики.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (596,'Сверху – яйцо-пашот, нарезанный тонкими слайсами бекон, петрушку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (597,'В кастрюлю налейте воду, добавьте нарезанное маленькими кусочками сливочное масло. Медленно нагрейте до растопления масла, доведите до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (597,'Снимите с огня, всыпьте муку. Интенсивно помешивая сделайте однородную массу, которая будет отставать от стенок кастрюли и образует комок. Немного остудите и добавьте постепенно яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (597,'Противень смажьте маслом или покройте пергаментом. Тестом наполните мешок, отрежьте уголок. Выдавите на противень небольшие круглые пирожные на расстоянии друг от друга.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (597,'Выпекайте профитроли 15-20 минут при 220°С в духовке. Для соуса смешайте все продукты, поместите на водяную баню и нагревайте, помешивая, до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (597,'Для крема взбейте сливки в пену, смешайте с измельченным бананом, сахаром и ликером. У остывших пирожных срежьте верхушки, наполните кремом. Верхушки верните на место. Сверху полейте шоколадным соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (598,'Хлеб обжарить на сковороде на оливковом масле. Другой вариант – подсушить в тостере, а затем сбрызнуть оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (598,'Натереть бутерброды чесноком с одной стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (598,'Вынуть из помидоров семена, мякоть нарезать кубиками небольшого размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (598,'Нарезать такими же кубиками сыр «Рекотта».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (598,'Покрошить красный лук и зелень базилика.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (598,'Ингредиенты для начинки перемешать, добавить соль и перец, влить немного бальзамического уксуса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (598,'Выложить массу на ломтики хлеба.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (599,'Помидоры черри разрезать на четвертинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (599,'Сладкий болгарский перец разрезать пополам, выложить на гриль, жарить под фольгой в течение восьми минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (599,'Один раз перцы перевернуть, жарить еще шесть минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (599,'Готовый продукт нарезать полосками, перемешать с каперсами, помидорами, красным винным уксусом и оливковым маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (599,'Добавить соль и перец по вкусу, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (599,'Ломтики хлеба чиабатта обжарить с двух сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (599,'Смесь из овощей выложить на хлеб, посыпать тертым сыром «Пармезан», побрызгать оливковым маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (600,'Ломтики хлеба побрызгать оливковым маслом. Выложить на противень или гриль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (600,'Нарезать кольцами томат, порубить базилик.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (600,'Перемешать компоненты для начинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (600,'Выложить на хлеб, добавить по ломтику сыра, сверху – еще немного томатов с зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (600,'Запечь в духовом шкафу до подрумянивания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (601,'Томаты тонко нарезать, покрошить зеленый базилик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (601,'Выложить начинку из томатов, по ломтику сыров «Проволоне» и «Моцарелла». Запечь бутерброды в духовке до расплавления сыра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (602,'Выложить хлебные ломтики на решетку духовки или сковороду гриль, жиром не смазывать. Запечь до золотистых полосок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (602,'Ломтики вынуть, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (602,'Нарезать крупными кусочками листья рукколы. Можно порвать руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (602,'Натереть остывший хлеб чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (602,'Выложить два или три слайса «Прошутто», зелень рукколы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (603,'Нарезать багет ломтиками толщиной в один сантиметр, сбрызнуть оливковым маслом. Посушить до золотистой корочки в духовом шкафу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (603,'Томаты нарезать среднего размера кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (603,'Порубить чеснок, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (603,'Всыпать соль, орегано, специи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (603,'Репчатый лук нарезать тонкими полукольцами, перемешать с лимонным соком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (603,'Измельчить кольцами оливки, натереть сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (603,'Выложить хлеб на противень, сверху – кусочки консервированного тунца, начинку из помидоров, сыр. Время запекания в прогретой духовке – пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (604,'Белый хлеб нарезать ломтиками по полтора сантиметра, лучше использовать багет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (604,'Жарить без масла на сковороде гриль. Другой вариант – подсушить на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (604,'Тушки кальмаров зачистить, вымыть, обсушить. Разрезать на квадратики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (604,'Перец чили покрошить. Острый перец можно заменить на сладкий болгарский.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (604,'Порубить чеснок, натереть цедру лимона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (604,'Перемешать с кальмарами, оливковым маслом, перцем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (604,'Начинку жарить на прогретой сковороде в течение минуты или двух. Остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (604,'Выложить начинку из помидоров, сверху – кальмары. Соль и перец – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (605,'Ломтики хлеба обжарить до золотистого цвета на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (605,'Нарезать кусочками очищенные отваренные креветки. Часть морепродуктов оставить целыми, для украшения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (605,'Измельчить зелень укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (605,'Бока брускетт обмазать сливочным маслом и обмакнуть в укроп. Должна получиться зеленая окантовка закуски.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (605,'Майонез перемешать с дижонской горчицей, перемешать с креветками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (605,'Рикотту посолить и поперчить, взбить при помощи миксера до получения воздушной массы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (605,'Слайсы смазать рикоттой, выложить креветки, небольшие горки икры и по целой креветке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (605,'Украсить веточками зелени укропа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (606,'Разогреть молоко, добавить желатин и размешать, пока не растворится. Не кипятить. Снять с огня и дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (606,'В горячую питьевую воду добавить ягодное желе и размешать до растворения. Ягоды превратить в пюре при помощи блендера, отложив несколько штук для украшения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (606,'Охлажденные взбитые сливки смешать со сметаной, взбить, постепенно всыпая сахар, до пышности. Постепенно добавить остывшее молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (606,'Разделить сметанную массу на 2 части. Одну часть распределить по стеклянным креманкам. Убрать в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (606,'В остальную массу добавить ягодное пюре и желе. Перемешать миксером на слабых оборотах. Выложить в креманки вторым слоем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (606,'Убрать в холодильник минимум на час. Украсить отложенными ягодами и веточками мяты. Подать к столу.','https://vkuso.ru/data/cache/data/73/92389a04f9b3d73_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (607,'Растопить маргарин, вмешать смесь: сахарный песок, соль, ванилин, сырые куриные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (607,'Ввести погашенную уксусом пищевую соду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (607,'Просеять пшеничную муку, порциями добавить в основную массу. Замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (607,'Выложить массу в формочки на треть, половинки сковороды для выпекания «орешков» хорошо прижать. Излишки убрать ножом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (607,'Выпечь, вынуть, охладить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (607,'В качестве начинки использовать любимый джем, любой крем, вареную сгущенку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (608,'Разбить сырые куриные яйца, отделить желтки от белков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (608,'В желтковую массу добавить сахарный песок, тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2658,'В середине готовки посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (608,'Просеять муку, перемешать с ванилином и сахаром, всыпать разрыхлитель, замесить тесто с добавлением рубленого сливочного масла или маргарина.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (608,'Белки взбить в пену.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (608,'В основную массу добавить желтковую массу, перемешать, затем белковую. Тесто не должно быть крутым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (608,'Прогреть орешницу, формочки смазать растительным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (608,'Выложить тесто в виде шариков мокрыми руками. Время выпекания – три минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (608,'Изделия вынуть, излишки обрезать ножом, размолоть и добавить в сгущенное молоко вместе с любыми орехами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (608,'Наполнить орешки, половинки соединить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (609,'Известное печенье можно приготовить и без формы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (609,'При помощи миксера взбить мягкое масло с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (609,'Всыпать смесь муки с разрыхлителем. Тесто должно получиться мягким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (609,'Сформовать шарики, выпечь в течение десяти минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (609,'Вынуть из шариков серединки, положить сгущенное молоко, соединить половинки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (610,'Взбейте яйца, сахар и соль. Добавьте растительное масло, перемешайте. Влейте молоко. Всыпьте муку и разрыхлитель, взбейте при помощи миксера. Слегка смажьте маслом разогретую сковороду, выпеките блинчики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (610,'Для начинки смешайте тонкие кружки бананов, цедру, сок и ликер. Для соуса смешайте какао, крахмал и молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (610,'В сотейник положите кусочки шоколада, влейте кукурузный сироп. Осторожно нагревайте при помешивании, пока масса не станет однородной по консистенции. Добавьте смесь из какао. Проварите в кипящей водяной бане, помешивая, 1 минуту. Снимите с огня и всыпьте ванилин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (610,'Каждый блинчик наполните начинкой, сверните треугольниками или пополам. Полейте небольшим количеством соуса и сразу же подавайте к столу.','https://vkuso.ru/data/cache/data/0a/d8983e4f429c20a_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (611,'В этом сочетании компонентов, горечь лука будет перебивать нежный вкус тунца, поэтому лук стоит предварительно замариновать. Для этого необходимо тонкие кольца лука разобрать руками, переложить в дуршлаг и обдать крутым кипятком. Сразу же промыть под струей холодной воды и замариновать в соке половины лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (611,'Для этих целей можно использовать и уксус, разведенный с водой, но лимон придаст рыбному салату легкий оттенок свежести, тогда как уксус может испортить весь вкус. Промаринованный в течение 15 минут лук перемешать с консервированным тунцом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (611,'Круглый рис проварить в подсоленной воде до мягкости, переложить в сито и промыть под холодной водой. Промытый рис должен распадаться на крупинки. Натереть на терке по отдельности огурец, яйца и сыр. На широкое блюдо установить форму и выложить все слоями, немного утрамбовывая их силиконовой лопаткой и смазывая оливковым майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (611,'1й слой – рис с майонезом. 2й – тертый сыр. 3й – тунец с маринованным луком. 4й – тертый огурец. Верхний слой – тертые яйца. После того как салат «Капля воды» с рисом и тунцом сформирован, формочка снимается. Украсить можно веточкой кучерявой петрушки и ломтиком лимона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (612,'Сливочное масло растопить, всыпать сахарный песок, перемешать, немного остудить, вбить сырые куриные яйца, соль. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (612,'Всыпать муку в несколько приемов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (612,'Пищевую соду погасить уксусом, добавить в основную массу вместе с мукой. Тесто не должно липнуть к рукам, но и не должно быть слишком крутым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (612,'Выпечь на газовой плите в орешнице.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (612,'Приготовить крем при помощи блендера: взбить сливочное масло со сгущенным молоком, добавить обрезки от орешков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (612,'Начинить половинки кремом, соединить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (613,'Сливочное масло комнатной температуры перемешать с сахаром, растереть, вбить желтки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (613,'Далее всыпать муку, добавить соду, погашенную уксусом. Замесить некрутое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (613,'Положить в холод на двадцать минут, раскатать в пласт, вырезать кружочки рюмкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (613,'Разложить в формы, излишки по краям срезать ножом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (613,'Выпечь в форме.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (613,'Для начинки использовать вареную сгущенку или любой крем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (614,'Тесто раскатайте на присыпанном мукой столе и выложите в форму диаметром около 25 см. Сформируйте бортик, тесто наколите вилкой в нескольких местах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (614,'Покройте тесто куском фольги или пергамента, сверху насыпьте сухого гороха или фасоли. Поставьте на 15 минут в духовку, разогретую до 190°С. Фольгу и горох удалите и пеките еще 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (614,'Спаржу отварите в кипящей воде 3 минуты. Порежьте на кусочки. Луковицу измельчите и обжарьте в разогретом масле до мягкости. На тесто выложите спаржу, лук и дробленые орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (614,'Раскрошенный сыр, яйца и сливки взбейте миксером до однородности. Посолите и поперчите, вылейте поверх спаржи. Черри разрежьте пополам, кожицу надрежьте крест-накрест. Выложите половинки черри круглой стороной вверх на пирог.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (614,'Выпекайте пирог в духовке в течение 15-20 минут или до готовности сырной начинки. Подавайте в теплом или холодном виде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (615,'Орехи очистить от кожуры, выложить в один слой на противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (615,'Подержать фисташки в духовом шкафу в течение пятнадцати минут, температура – 150 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (615,'Приготовить сироп. Всыпать в сотейник шестьдесят граммов сахарного песка, влить немного воды, довести до температуры в 115 градусов. Можно всыпать пищевой краситель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (615,'Прогреть до 120 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (615,'Всыпать фисташки с противня, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (615,'Выложить продукт на пергамент или на коврик для выпечки, остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (615,'Всыпать в блендер миндальную муку, приготовленную заранее и орехи. Растолочь в муку. Можно использовать кофемолку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (615,'Ввести немного экстракта миндаля и растительное масло.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (615,'Перемешать до однородного состояния.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (615,'Переложить массу в контейнер, выложить в холод.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (616,'Грецкие и фисташковые орехи подсушить на противне в течение пятнадцати минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (616,'Перемолоть продукт в кофемолке или в блендере.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (616,'Добавить мед, какао, перемолоть еще раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (616,'Влить порциями молоко, взбивать до тех пор, пока паста не станет однородной и густой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Готовим тесто. Соединяем в миске 3 куриных яйца и 120 гр сахара.','https://vkuso.ru/data/cache/data/9d/35a818943c1129d_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Взбиваем яйца с сахаром в пышную белую пену.','https://vkuso.ru/data/cache/data/98/31c331260a9e798_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'В другую миску просеиваем 20 гр какао, 80 гр пшеничной муки и 1 ч. ложку разрыхлителя.','https://vkuso.ru/data/cache/data/8c/91b75de4037e28c_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Перемешиваем сухие ингредиенты.','https://vkuso.ru/data/cache/data/ff/114436a6faaf6ff_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Отправляем сухие ингредиенты в яичную смесь.','https://vkuso.ru/data/cache/data/5a/31e4ba9ff929e5a_434x295_notrise.png',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Аккуратно перемешиваем до однородности.','https://vkuso.ru/data/cache/data/f1/bc981b7683f85f1_434x295_notrise.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Смазываем форму сливочным маслом. (Диаметр формы - 20 см).','https://vkuso.ru/data/cache/data/0c/dd484dce82fb00c_434x295_notrise.png',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Выкладываем тесто в форму и отправляем выпекаться при 190 градусах 30 минут. Готовый бисквит полностью остудить.','https://vkuso.ru/data/cache/data/1d/435093f68409e1d_434x295_notrise.png',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Готовим начинку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Затем добавляем 150 гр кокосовой стружки, перемешиваем. Варим на небольшом огне примерно 10-15 минут, периодически помешивая.','https://vkuso.ru/data/cache/data/35/6a628639ed55a35_434x295_notrise.png',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Масса должна загустеть. Готовую начинку остудить.','https://vkuso.ru/data/cache/data/0f/b137bc1075b060f_434x295_notrise.png',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Бисквит разрезаем вдоль на 2 коржа.','https://vkuso.ru/data/cache/data/e9/303a193e33272e9_434x295_notrise.png',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Пропитываем каждый корж сливками ( приблизительно 5 ст. ложек на 1 корж).','https://vkuso.ru/data/cache/data/b5/beb27847d6a8cb5_434x295_notrise.png',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Затем выкладываем начинку на корж, равномерно ее распределяем. Накрываем вторым коржом, слегка прижимаем.','https://vkuso.ru/data/cache/data/b8/2d9486706615ab8_434x295_notrise.png',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Убираем торт в холодильник.','https://vkuso.ru/data/cache/data/a2/eab329441c169a2_434x295_notrise.png',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (623,'Влить сгущенное молоко, добавить сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (623,'Всыпать какао в основу, перемешать руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Готовим глазурь. В кастрюлю отправляем 4 ст. ложки какао, 4 ст. ложки сахара, 50 гр сливочного масла и 100 мл молока.','https://vkuso.ru/data/cache/data/c5/b5e7b34c76213c5_434x295_notrise.png',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Все время помешивая, доводим глазурь до загустения.','https://vkuso.ru/data/cache/data/e3/444ceb4ab57e2e3_434x295_notrise.png',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Теплую глазурь выливаем на торт, равномерно распределяем. Ставим торт в холодильник на 4-5 часов.','https://vkuso.ru/data/cache/data/5d/6663e92f7ab285d_434x295_notrise.png',18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (617,'Торт "Баунти" готов! Приятного аппетита!','https://vkuso.ru/data/cache/data/62/5979fecc3ea6a62_434x295_notrise.jpg',19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (618,'Натрите имбирь. Чеснок очистите, разрежьте пополам и извлеките зеленую серединку. остальную мякоть измельчите.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (618,'Крылышки промойте, обсушите. Перемешайте кетчуп, мед, соевый соус, имбирь и чеснок. Смажьте крылышки получившимся маринадом, уберите на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (618,'Выложите крылышки в смазанную маслом жаропрочную форму. Запекайте в духовке в течение примерно 20 минут до красивой корочки при температуре 200°C.','https://vkuso.ru/data/cache/data/93/50f0a5a97292293_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (619,'Сливочное масло размягчить при комнатной температуре и смешать с сахаром. Добавить три столовых ложки сметаны и вбить яйцо. Тщательно вымешать, положить щепотку соли и половину чайной ложки  пищевой соды или одну ложку разрыхлителя для теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (619,'Небольшими количествами подмешать просеянную муку и замесить некрутое тесто. Переложить тесто в полиэтиленовый кулек и поставить на холод. Тем временем пока тесто настаивается, приготовить начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (619,'Снять с апельсина цедру. Мякоть освободить от пленок и косточек. Переложить в чашу блендера освобожденную мякоть апельсина, добавить цедру, сахар и столовую ложку крахмала и взбить блендером до однородности. Охлажденное тесто раскатать скалкой на присыпанном мукой столе в корж высотой 4 мм.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (619,'Выложить равномерно апельсиновую начинку и еще раз разровнять лезвием ножа по всей поверхности не доходя пару сантиметров до одного из краев. Скатать тесто с начинкой в виде рулета по направлению к не промазанному краю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (619,'Переложить рулет на плоскую доску и убрать в холодильник на время пока разогреться духовка. Духовку разогреть до 220 градусов. Достать рулет из холодильника и разрезать на небольшие порции острым ножом, который не сминает краев.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (619,'Выложить мягкое печенье с апельсиновой начинкой на промазанный противень на небольшом расстоянии друг от друга, смазать растертым желтком и выпекать около 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (620,'Орехи подсушить в духовом шкафу, время – пятнадцать минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (620,'Перемолоть блендером, добавить сахарный песок, воду и немного ликера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (620,'Перемешать до однородного состояния. Поставить в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (621,'Песочное печенье размолоть на кусочки небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (621,'Еще две трети продукта растереть в муку при помощи толкушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (621,'Сливочное масло подержать до оттаивания при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (621,'Прогреть молоко в сотейнике, всыпать какао-порошок, сахарный песок, добавить сливочное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (621,'Массу перемешать, ода должна стать глянцевой на вид и однородной по консистенции. Смесь не кипятить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (621,'Снять с огня, всыпать крошки, перемешать еще раз.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (621,'Добавить молотое печенье, если масса слишком густая – влить еще немного молока.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (621,'Выложить продукт на пищевую пленку, свернуть колбаской.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (621,'Обернуть поверх махровым полотенцем, выложить в морозилку на три или четыре часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (621,'Перед подачей присыпать десерт сахарной пудрой. Нарезать кружочками острым ножом и подать к чаю.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (622,'Сдобное печенье размолоть в крошку, немного продукта оставить в виде кусочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (622,'Залить чернослив на двадцать минут холодной водой, промыть, залить кипящей водой на пять минут. Измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (622,'Перемешать продукты с какао-порошком, влить подогретое молоко, перемешать. Смесь не должна получиться слишком плотной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (622,'Переложить на пищевую пленку, свернуть колбаской, поставить в холод на два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (622,'Обвалять готовый десерт в кунжутном семени, разрезать на кружки и подать на стол.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (623,'Отдельно смешать кокосовую стружку с половиной нормы сахарной пудры, добавить оставшееся сливочное масло, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (623,'Раскатать тесто пластом, выложить начинку в середину, сформовать рулет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (623,'Обернуть продукт пищевой пленкой, поставить в холодильник, время – от двух до четырех часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (623,'Приготовить крем из сметаны с сахарной пудрой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (623,'Посыпать колбасу кокосовой стружкой, украсить мелкими цветочками, приготовленными из сметанного крема.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (623,'Для получения украшений использовать кондитерский мешок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (624,'Курагу, изюм, чернослив замочить на двадцать минут в холодной воде, промыть, залить кипящей водой на пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (624,'Орехи, сухофрукты и цукаты измельчить, ягоды сушеной клюквы положить целиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (624,'Творог протереть через сито.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (624,'Печенье растолочь в ступке, перемешать крошки с какао-порошком. Ингредиенты перемешать до получения однородной массы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (624,'Сформовать небольшой рулет, обернуть его в пленку, поставить в холод на четыре или шесть часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (624,'Перед подачей посыпать десерт сахарной пудрой',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (625,'Петрушку хорошо промыть, обсушить, мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (625,'Брынзу покрошить, перемешать с зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (625,'Приготовить тесто из муки, кефира, соли и разрыхлителя. Тесто должно быть гладким и однородным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (625,'Дать постоять пятнадцать минут при комнатной температуре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (625,'Поделить массу на шесть частей, сформовать лепешки круглой формы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (625,'Выложить сырную начинку, вокруг собрать тесто, затем верхушку сплющить. Тесто не должно порваться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (625,'Обжарить на сухой раскаленной сковороде. Если тесто начнет вздуваться – его нужно проколоть ножом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (625,'Подрумянить хлебобулочные изделия с двух сторон.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (625,'Смазать топленым маслом, выложить одну на другую.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (626,'Смешать муку с кефиром, солью и пищевой содой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (626,'Замесить тесто, оно должно быть мягким. Отбить об стол, оставить на двадцать или тридцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (626,'Натереть на терке чеснок, нарезать «Адыгейский» сыр мелкими кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (626,'Отварить до готовности картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (626,'Добавить к сыру с чесноком, массу превратить в пюре, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (626,'Тесто раскатать на шарики, затем в лепешки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (626,'Выложить начинку, собрать тесто наверху и раскатать изделие еще раз.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (626,'Время выпекания на сковороде – полчаса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (627,'Влить в емкость кефир комнатной температуры, добавить пищевую соду, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (627,'Оставить на пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (627,'Всыпать соль и сахарный песок. Перемешать, всыпать муку, вымесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (627,'Убрать продукт на двадцать или тридцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (627,'Для начинки натереть ветчину и сыр, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (627,'Раскатать тесто в шесть шариков, сформовать лепешки, выложить начинку, собрать тесто наверх, изделие снова раскатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (627,'Выпечь на раскаленной сковороде до готовности, с двух сторон, смазать маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (628,'Просеять муку, добавить соль, сахар, сухие дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (628,'Влить порциями теплое молоко, замесить мягкое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (628,'Сформовать шар, оставить под кухонным полотенцем на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (628,'Очистить картофель, отварить до полной готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (628,'Остудить, натереть клубни.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (628,'Натереть на терке «Адыгейский» и «Голландский» сыр, брынзу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (628,'Измельчить петрушку, чеснок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (628,'Все компоненты смешать, посолить и поперчить по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (628,'Разделить фарш на две части, сформовать шары.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (628,'Тесто обмять руками, разделить на части.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (628,'Сформовать лепешки, выложить начинку, собрать тесто вверху, раскатать повторно.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (628,'Выпечь на сковороде до готовности, время – около получаса.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (629,'Тонкие свиные стейки приправить солью и перцем, обернуть пленкой и отбить при помощи кухонного молоточка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (629,'Сырое яйцо взбить венчиком с молоком в миске. В другую емкость просеять муку. В третью емкость всыпать сухари.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (629,'Снять пленку с мяса. Каждый кусок окунуть в муку, яично-молочную смесь, а затем - в сухари. Обжарить в разогретом масле 4 минуты с обеих сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (629,'Готовые шницели выложить на бумажные полотенца. Когда впитается жир, переложить на тарелки, сервировать по вкусу ломтиками лимона и зеленью.','https://vkuso.ru/data/cache/data/99/e93678922b96c99_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (630,'Клубнику промойте, обсушите, удалите плодоножки. Отмерьте нужное количество ягод для конфитюра. Из них около 200 г порежьте, остальные измельчите в пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (630,'Мелиссу нарежьте мелкими полосками. Из лимона выжмите сок, перемешайте с клубничным пюре в большой кастрюле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (630,'Желфикс смешайте с 2 ст. ложками сахара. Затем перемешайте со всеми ягодами. Добавьте оставшийся сахар. Поставьте кастрюлю на плиту, при постоянном помешивании доведите до кипения и варите на сильном огне 3 минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (630,'Снимите кастрюлю с огня. Конфитюр разлейте в подготовленные банки и сразу же закройте их навинчивающимися крышками.','https://vkuso.ru/data/cache/data/f6/157ad9db2743af6_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (631,'Кабачки помыть, затем натереть на мелкой терке.','https://vkuso.ru/data/cache/data/7c/77959d682296c7c_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (631,'Далее тертые кабачки слегка отжать от жидкости.','https://vkuso.ru/data/cache/data/9f/6ee53d386ec2e9f_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (631,'Добавить 300 мл кефира, 4 куриных яйца, 1 чайную ложку соли, смесь пряных трав по вкусу (или мелко порезанную свежую зелень).','https://vkuso.ru/data/cache/data/c8/9b75c9fb81d4bc8_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (631,'Перемешать.','https://vkuso.ru/data/cache/data/52/74f2432cc636d52_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (631,'Частями просеять 350 гр пшеничной муки. Перемешать.','https://vkuso.ru/data/cache/data/9d/d9e6a3de303d29d_434x295_notrise.png',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (631,'Добавить 1 столовую ложку растительного масла и 0,5 ч. ложки соды.','https://vkuso.ru/data/cache/data/9d/1c762832e70259d_434x295_notrise.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (631,'Тщательно перемешать. Оставить на 20 минут.','https://vkuso.ru/data/cache/data/57/d42eca47c845b57_434x295_notrise.png',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (631,'Обжаривать на растительном масле с обеих сторон до золотистого цвета.','https://vkuso.ru/data/cache/data/69/80ec24dcfadb969_434x295_notrise.png',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (632,'Куриную печень разобрать, удалить желчь и остатки плевы. Замочить в холодной воде. Слить воду и промыть, откинуть на дуршлаги дать стечь остаткам жидкости. Разрезать большие кусочки напополам. Лук очистить и разрезать кольцами. Пшеничную муку просеять и высыпать на широкую плоскую тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (632,'На дно тарелки предварительно необходимо постелить листок пергамента, который легко убрать с остатками муки, а тарелку легче будет отмыть. Растительное масло влить на сковороду и разогреть. Обмакивать в муке куски печени и выкладывать на разогретую сковороду в один слой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (632,'Все действия должны быть быстрыми и слаженными, так как куриная печень готовиться быстро и закончив выкладывать последний кусочек, первый – уже надо переворачивать на другую сторону. После того, как вся печень будет жариться на другой стороне, добавить в сковородку кольца лука, предварительно разобранные и посолить блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (632,'Пару минут при постоянном помешивании – и накрыть сковороду крышкой, при этом убрав огонь под ней наполовину. Готовить в таком режиме 4 минуты и можно подавать куриную печень, обжаренную в муке с луком на стол.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (633,'Размягченное сливочное масло растереть с сахаром до пышности. Добавить яйца и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (633,'Влить молоко, всыпать цедру и просеянную с разрыхлителем муку. Замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (633,'Форму для кекса смазать растительным маслом или застелить пекарской бумагой. Выложить тесто и поставить в разогретую до 200°С духовку. Выпекать около 1 часа до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (633,'Кекс достать из формы, остудить, посыпать сахарной пудрой или украсить любой глазурью.','https://vkuso.ru/data/cache/data/0a/cfdc1097a0b200a_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (634,'Растворить дрожжи в теплом молоке вместе с ванильным сахаром. Взбить яйца с солью, добавить муку. Влить молоко, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (634,'Добавить размягченное сливочное масло и замесить тесто. Оставить на час в теплом месте. Затем всыпать жемчужный сахар и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (642,'Добавить остальной белок, взбивать 3 минуты до пышности. При взбивании тонкой струйкой влить горячий сироп. Взбивать до устойчивой массы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (634,'Смазать растительным маслом разогретую вафельницу. Выкладывать небольшие порции теста и выпекать вафли 2-3 минуты. Подать к столу со взбитыми сливками.','https://vkuso.ru/data/cache/data/a5/ab16a63b8d6afa5_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (635,'Перемешать муку, сахар и разрыхлитель. Добавить растопленное масло, яйца, йогурт и размятый до состояния пюре банан.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (635,'При помощи миксера замесить тесто, добавить грубо нарезанный шоколад и перемешать. В формы для кексов поместить бумажные капсулы, вылить сверху тесто. Посыпать рублеными орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (635,'Поставить в разогретую до температуры 200°С духовку и выпекать в течение 15-20 минут. Подать в теплом виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (636,'Репчатый лук очистить, нарезать соломкой, выложить на тарелку, залить водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (636,'Добавить сахар и соль, влить уксус. Перемешать, оставить на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (636,'Свиное сердце отварить, нарезать ломтиками небольшого размера, выложить в салатницу, добавить чеснок и рубленую зелень, перец, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (636,'Вынуть лук из маринада, добавить в мясо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (636,'Нарезать тонкой соломкой морковь, добавить в лук и мясо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (636,'Всыпать консервированный зеленый горошек.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (636,'В качестве заправки использовать майонез, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (637,'Отварить сердце, нарезать соломкой или кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (637,'Выложить на сковороду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (637,'Вымыть сладкий болгарский перец, очистить и нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (637,'Добавить его в обжарку вместе с молотым перцем и соевым соусом. Жарить до полуготовности, перец не должен стать мягким.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (637,'Нарезать свежие огурцы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (637,'Чеснок пропустить через пресс, репчатый лук нарезать соломкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (637,'Ингредиенты перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (637,'Зелень порубить, добавить в салат вместе с обжаркой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (637,'Полить оливковым маслом, перемешать еще раз.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (638,'Отваренное сердце остудить и нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (638,'Репчатый лук нарезать полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (638,'Для маринада перемешать уксус с майонезом, добавить сахар и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (638,'Выложить лук в емкость, залить маринадом на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (638,'Яйца отварить, очистить и мелко нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (638,'Добавить к субпродукту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (638,'Соленые огурцы нарезать кубиками небольшого размера, выложить в салатницу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (638,'Вынуть лук из маринада, добавить к другим ингредиентам. Соль – по вкусу, майонез, любимые специи.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (638,'Перемешать, поставить в холодильник на полтора часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (639,'Свиное сердце отварить, остудить, нарезать мелкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (639,'Сыр нарезать кубиками или натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (639,'Репчатый лук очистить и разрезать пополам, затем – полукольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (639,'Компоненты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (639,'Добавить соль и морковь по-корейски, заправить майонезом и еще раз перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (640,'Отварить сердце, нарезать мелкими кубиками. Выложить в салатницу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (640,'Всыпать консервированную или предварительно отваренную фасоль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (640,'Очистить вареные яйца, нарезать кубиками, добавить в общую массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (640,'Репчатый лук мелко порубить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (640,'Свежий огурец нарезать мелкой соломкой. Также добавить в общую массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (640,'Соль и молотый перец – по вкусу, добавить другие специи и майонез.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (640,'Перемешать, подать к столу сразу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (641,'Смазать противень, уложить на него бедра. Запекать полчаса при температуре 220 градусов. Уложить в специальную формочку овощи, сверху курицу, посолить, посыпать зеленью, поперчить, добавить аджику, налить стакан бульона или питьевой воды. Поставить в духовку. Через 20 минут куриные бедрышки с овощами будут готовы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (642,'Смешать агар и 2/3 стакана воды, через полтора часа он набухнет. Поставить на огонь, при помешивании довести до кипения. Всыпать 400 г сахара, варить на умеренном огне 5 минут, помешивая, до пробы на "тонкую нитку".',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (642,'Клубнику промыть, оборвать хвостики, обсушить. Смешать с остальным сахаром и измельчить блендером. Добавить половину белка и взбивать, пока масса не начнет светлеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (642,'Быстро наполнить кондитерский мешок с фигурной насадкой и выложить заготовки на покрытый пергаментом противень. Оставить на сутки, затем склеить зефирки попарно. Посыпать сахарной пудрой.','https://vkuso.ru/data/cache/data/56/358732e49e09256_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (643,'Смешать ряженку, сахар (его количество можно регулировать по своему вкусу) и какао (рекомендую просеять через сито).','https://vkuso.ru/data/cache/data/21/7e45eef4ce12b21_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (643,'Быстрорастворимый желатин залить очень горячей водой и размешать его до полного растворения.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (643,'Массу взбить миксером.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (643,'Украшаем на свой вкус: я посыпала какао и украсила свежими ягодами.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (644,'Малину перебрать, засыпать половиной сахара и оставить, пока ягоды не выделят сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (644,'Сок перелить в кастрюлю. Всыпать остальной сахар и довести смесь до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (644,'Варить, снимая пену, 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (644,'Постепенно добавить к сиропу ягоды, перемешать и варить 25 минут. Огонь плиты - умеренный.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (644,'Всыпать лимонную кислоту и варить 5 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (644,'Разложить джем по стерилизованным банкам, закатать крышками. Перевернуть банки и оставить на 60 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (644,'Перевернуть снова, оставить до полного остывания.','https://vkuso.ru/data/cache/data/e2/1197cde3b2356e2_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (645,'Молоко довести до кипения, остудить, добавить желтки и сахар. Поместить на водяную баню и варить до консистенции сгущенки при помешивании.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (645,'Остудить и аккуратно добавить плотно взбитые сливки. Переложить массу в контейнер, закрыть крышкой и убрать в морозилку на 60 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (645,'Взбить массу блендером на самых низких оборотах. Убрать в морозилку, через час взбивание повторить. Потом заморозить десерт до полной готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (645,'Смочить ложку в теплой воде, набрать порции мороженого и разложить их по креманкам. Украсить по желанию взбитыми сливками, ягодами, орехами, тертым шоколадом и т.д.','https://vkuso.ru/data/cache/data/97/94d6b970faae997_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (646,'Соус.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (646,'Добавляем томатную пасту , перец чили, базилик, соль, чеснок и растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (646,'Разрезаем крылья на три части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (646,'Добавляем лук, соль, перец чили, перец черный молотый, карри и растительное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (646,'Нанизываем крылья на шампура и жарим на углях 20-25 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (646,'Выкладываем крылья в форму для запекания и заливаем соусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (646,'Накрываем фольгой и тушим на углях 15 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (647,'Для белого слоя: 10 г желатина смешать с 50 мл воды, оставить набухнуть согласно инструкции на упаковке. Сливки, молоко, 100 г сахара и ванильный сахар поставить на огонь и варить при помешивании.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (647,'Когда смесь начнет закипать, убрать с плиты. Добавить в горячую массу набухший желатин и хорошо размешать до растворения. Стаканы установить под наклоном, налить массу до середины емкости, убрать в холодильник на 3-4 часа для застывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (647,'Для красного слоя: 8 г желатина залить 50 мл воды, оставить набухать согласно инструкции на упаковке. Малину выложить в сотейник, добавить 100 мл воды и 100 г сахара. Довести до кипения. Варить пару минут, помешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (647,'Снять с огня, немного остудить и взбить блендером до состояния пюре. Протереть сквозь сито при помощи силиконовой лопатки. В горячее пюре добавить разбухший желатин и хорошо размешать до его растворения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (647,'Остудить массу до комнатной температуры и вылить на уже застывший сливочный слой. Убрать в холодильник до полного застывания на 5 часов.','https://vkuso.ru/data/cache/data/69/e4d441df0548169_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (648,'Размягченное сливочное масло взбить с сахаром и ванильным сахаром. Добавит яйца и перемешать миксером на слабых оборотах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (648,'Добавить молоко и просеянную с разрыхлителем муку. Вымесить тесто, разделить поровну, в одну половину добавить какао. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (665,'Тщательно перемешиваем.','https://vkuso.ru/data/cache/data/4b/39a4eaf9b04e34b_434x295_notrise.png',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (648,'Формы для выпечки с отверстием в центре смазать растительным маслом. Вылить сначала светлое, а затем темное тесто. Выпекать около часа при 180°C. Посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (649,'Натереть сыр на мелкой терке. Зелень с чесноком измельчить и растереть в кашицу. Натереть на крупной терке колбасу, ветчину или мясо. Все ингредиенты соединить, добавить желток и хорошенько перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (649,'Лаваш порезать на равнобедренные треугольники и на меньшую сторону каждого из них выложить начинку. Свернуть рулетики, свободные поверхности треугольников смазать разболтанным белком, чтобы во время жарки они не развернулись.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (649,'Обжарить рулеты на растительном масле и положить их на салфетку, чтобы стекло лишнее масло. К столу рулетики из тонкого лаваша с мясной начинкой необходимо подавать горячими.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (650,'Клубнику промыть, обсушить. Уложить в кастрюлю, пересыпая сахаром. Оставить на ночь. Утром, когда ягоды дадут сок, поставить на огонь плиты. Добавить содержимое стручка ванили и сам стручок. Довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (650,'Снять кастрюлю с огня и полностью остудить варенье. Затем снова поставить на слабый огонь, довести до кипения и варить 5 минут, снимая пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (650,'Достать стручок ванили. Разлить варенье по стерилизованным банкам, закрыть крышками и закатать. Если не закатывать, то хранить варенье в холодильнике.','https://vkuso.ru/data/cache/data/92/01a5a1c50787c92_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (651,'Разогреваем масло сковородки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (651,'Далее добавляем лук и выдавливаю чеснок, обжариваем и добавляем грибы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (651,'Обжарим 3-4 минуты и добавим Бурбон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (651,'После добавим кинзу и зальем сливки. Посолим, поперчим и оставим на среднем огне на 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (652,'В миску просеять муку с разрыхлителем, добавить соль и перемешать. Отделить белки от желтков. В отдельной емкости взбить желтки и сахар на средних оборотах миксера, пока сахар не растворится полностью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (652,'Добавить молоко, ванильный экстракт (если нет - заменить ванильным сахаром) и растительное масло. Все время продолжать взбивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (652,'Подмешать желтковую массу к муке. Теперь аккуратно ввести взбитые в пену белки. Осторожно перемешать, стараясь, чтобы белки сильно не опали.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (652,'Выпекать вафли в смазанной маслом электровафельнице до румяного цвета. Готовые вафли выложить на тарелку и щедро посыпать сахарной пудрой.','https://vkuso.ru/data/cache/data/a2/92860916d04dba2_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (653,'Смешать в сотейнике сгущенку, масло и какао. Готовить около 10 минут на среднем огне до загустения, постоянно помешивая. Верный признак готовности - при помешивании будет видно дно емкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (653,'Снять с огня, дать массе остыть и убрать в холодильник на 2 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (653,'Руки смазать растительным маслом и скатать из охлажденной массы 20 шариков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (653,'Обвалять конфеты в любой кондитерской посыпке, измельченных орехах, кокосовых хлопьях и т.п. Поместить в гофрированные бумажные вкладыши каждую конфетку и подать к столу.','https://vkuso.ru/data/cache/data/13/eb031d7bb29c013_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (654,'Шоколад наломать, вместе с маслом положить в керамическую пиалу и растопить в микроволновке. Перемешать, чтобы получилась гладкая масса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (654,'Яйца и сахар взбить миксером добела. Шоколадную массу немного остудить и аккуратно добавить к яйцам. Муку с разрыхлителем просеять и всыпать к остальным компонентам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (654,'Добавить фисташки, перемешать. Прямоугольную форму покрыть пергаментом, выложить тесто и разровнять силиконовой лопаткой. Выпекать 30 минут в разогретой до 190°С духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (654,'Дать брауни полностью остыть, извлечь из формы, порезать на квадратные порции и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (655,'Кабачки помыть и срезать с двух сторон кончики. Порезать продольными пластинами толщиной 6-7 мм.','https://vkuso.ru/data/cache/data/88/7166f9c5e556b88_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (655,'Перекладываем кабачки в миску, добавляем 1 чайную ложку соли и 1 чайную ложку черного молотого перца.','https://vkuso.ru/data/cache/data/48/d3d133d0bf3bf48_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (655,'Тщательно перемешиваем.','https://vkuso.ru/data/cache/data/37/50144a66e3c9d37_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (655,'Отделяем белки от желтков. Желтки взбить.','https://vkuso.ru/data/cache/data/35/36b7c263e439735_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (673,'Сыр натереть, посыпать овощи. Полить майонезом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (655,'Затем добавить 3 столовых ложки кукурузной муки.','https://vkuso.ru/data/cache/data/10/c23bd5df1c96710_434x295_notrise.png',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (655,'Тщательно перемешать.','https://vkuso.ru/data/cache/data/b2/935df2016f69db2_434x295_notrise.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (655,'Понемногу добавляем воду и перемешиваем.','https://vkuso.ru/data/cache/data/1f/de6d9d07d80481f_434x295_notrise.png',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (655,'В миску с белками добавляем щепотку соли. Взбиваем белки до пиков.','https://vkuso.ru/data/cache/data/0c/3630e3b890b060c_434x295_notrise.png',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (655,'Взбитые белки частями добавляем к желткам и перемешиваем.','https://vkuso.ru/data/cache/data/2c/521498ef7e5082c_434x295_notrise.png',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (655,'Вот такой должна быть смесь.','https://vkuso.ru/data/cache/data/2f/15d120720525b2f_434x295_notrise.png',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (655,'Окунаем кабачки в кляр.','https://vkuso.ru/data/cache/data/70/c1dddeae8554f70_434x295_notrise.png',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (655,'Обжариваем на растительном масле с обеих сторон до золотистого цвета. Затем выкладываем готовые кабачки на бумажное полотенце, чтобы избавиться от лишнего масла.','https://vkuso.ru/data/cache/data/cc/91d30595ef0decc_434x295_notrise.png',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (655,'Подавать жареные кабачки можно с соусом из сметаны и чеснока (или майонеза и чеснока). Или просто добавить к кабачкам пропущенный через пресс свежий чеснок.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (656,'Взбить яйца, сливки и тертый сыр. Поперчить и посолить. Отварить пачку спагетти и перемешать их с яичной массой. Массу положить на смазанную формочку. Смешать сырую курицу и маринованные огурцы, посыпать перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (656,'Сверху положить помидоры кружочками и сделать сеточку из майонеза. В последнюю очередь посыпать тертым сыром. Разогреть духовку до 200 градусов и выпекать запеканку «Макароша» из спагетти и курицы до румяно-золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (657,'Перемешать растительное масло, сахарный песок, соль, ванильный сахар, какао-порошок и кофе. Яйца (предварительно достать их из холодильника) ввести по одному, каждый раз перемешивая в течение минуты на невысоких оборотах миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (657,'Просеять муку и разрыхлитель. Подмешать в яично-сахарную массу, замесить однородное по консистенции тесто. Накрыть пищевой пленкой так, чтобы она касалась поверхности теста. Поставить миску с тестом в морозилку на 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (657,'Столовой ложкой набирать порцию теста и скатывать из нее шарик. Каждый шарик обваливать сахарной пудрой и выкладывать на застеленный пергаментом противень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (657,'Духовку разогреть до температуры 180оС. Отправить туда противень с печеньем на 9-12 минут. Во время выпечки заготовки значительно увеличатся, а на поверхности появятся характерные трещинки.','https://vkuso.ru/data/cache/data/c9/31869f1dd63bfc9_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (658,'Вливаем 300 мл молока в кастрюлю.','https://vkuso.ru/data/cache/data/f0/14efaa2245f08f0_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (658,'Сюда же просеиваем пшеничную муку.','https://vkuso.ru/data/cache/data/c5/f88f8a3e2cbbdc5_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (658,'Тщательно перемешиваем.','https://vkuso.ru/data/cache/data/4b/a9e1c1ccf43d24b_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (658,'Добавляем растопленное сливочное масло.','https://vkuso.ru/data/cache/data/46/d1fc1e699341f46_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (658,'Вливаем остальное молоко и снова перемешиваем.','https://vkuso.ru/data/cache/data/eb/f22ca59c032c4eb_434x295_notrise.png',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (658,'Отправляем кастрюлю на плиту. Варим смесь на медленном огне, постоянно помешивая.','https://vkuso.ru/data/cache/data/89/350d59c7b4beb89_434x295_notrise.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (658,'Когда смесь начнет закипать добавляем сахар и варим минут 5, постоянно помешивая.','https://vkuso.ru/data/cache/data/f3/f302b40f26a2df3_434x295_notrise.png',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (658,'За минуту до конца приготовления добавляем предварительно замоченный желатин, хорошо перемешиваем.','https://vkuso.ru/data/cache/data/f2/224938f72f3ccf2_434x295_notrise.png',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (658,'Оставляем немного остыть при комнатной температуре, затем добавляем арахис, перемешиваем.','https://vkuso.ru/data/cache/data/26/08ad4643cbada26_434x295_notrise.png',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (658,'Форму нужно застелить пищевой пленкой, затем выкладываем в смесь и отправляем в холодильник на 4-5 часов.','https://vkuso.ru/data/cache/data/ac/833a29dce1145ac_434x295_notrise.png',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (658,'Спустя время вынимаем лакомство и нарезаем на кубики.','https://vkuso.ru/data/cache/data/ec/8f74b42f14d98ec_434x295_notrise.png',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (658,'Каждый кусочек обваливаем в кокосовой стружке и выкладываем на тарелку.','https://vkuso.ru/data/cache/data/98/b4b56bd609c7f98_434x295_notrise.png',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (658,'Молочный десерт с арахисом готов! Приятного аппетита!','https://vkuso.ru/data/cache/data/a8/cbd09606141b7a8_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Приготовим съедобное мыло. В тарелку отправляем яичный белок, 2 столовых ложки сахара и 0,5 чайной ложки лимонного сока.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (659,'Растаять сливочное масло и размешать его со сгущенным молоком. В смесь добавить разрыхлитель, яйца и муку. Все ингредиенты тщательно перемешать. Должно получиться слегка жидкое тесто. Испечь 3 или 4 коржа, количество будет зависеть от размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (659,'Чтобы крем не получился жидким, сгущенное молоко для него лучше отварить на протяжении часа. Когда молоко остынет, взбить его с маслом. Добавить какао и ром. Каждый корж и их бока смазать кремом. По желанию украсить. Поставить бисквитный торт «Маша» в холодильник на 5 часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (660,'У промытых ягод удалить чашелистики. Сами ягоды поместить в чашу блендера и превратить в пюре. Добавить сахар, поставить на средний огонь и, помешивая, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (660,'Смешать 100 г сливок и крахмал, добавить к ягодам и варить при помешивании до загустения. Снять с огня, дать остыть и добавить остальные сливки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (660,'Положить массу в большой пластиковый контейнер с крышкой, поставить в морозилку. Три раза с интервалом в 30 минут доставать из морозилки и перемешивать на слабых оборотах миксера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (660,'Оставить мороженое в морозилке до полного застывания массы. Смочить ложку в теплой воде, набрать порции мороженого и распределить по вазочкам. Украсить по желанию и сразу подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (661,'Гречку сварить, или любой другой гарнир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (661,'Куриное филе, (в моем случае малое) промыть, просушить, далее по вкусу соль, перец приправа для курицы, все перемешать, далее добавляем кефир снова перемешиваем, и убираем с сторону на 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (661,'Взбить куриные яйца 3-4 шт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (661,'Разогреваем растительное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (661,'Обваливаем малое куриное филе в муке, отпускаем в взбитые куриные яйца, и обваливаем в панировочных сухарях. Осторожно отпускаем в разогретое растительное масло, и жарим до золотистой корочки около 2 минут. Достаем и перекладываем на бумажное полотенце. Подаем к гарниру!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (662,'Растереть яйцо и сахарный песок, добавить молоко и тщательно перемешать. Добавить корицу и разрыхлитель. Насыпать муку и замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (662,'Смазать жиром сковороду или противень. Налить равномерно тесто. Выпекать блюдо при температуре 180 градусов. Простой пирог «Из ничего» будет готов через 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (663,'Ягоды промыть, перебрать, удалить зеленые листочки. Отложить несколько для украшения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (663,'Остальные ягоды засыпать в чашу блендера, добавить йогурт и взбить до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (663,'Добавить сахарную пудру, перемешать. Влить немного ягодного сока, чтобы добиться нужной густоты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (663,'Разлить смузи по бокалам, украсить отложенными ягодами и листочками мяты. Подать с трубочкой.','https://vkuso.ru/data/cache/data/6c/bf1948ef593046c_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (664,'Нарезать крабовые палочки.','https://vkuso.ru/data/cache/data/c5/10b9d1d6bd00dc5_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (664,'Нарезать помидоры.','https://vkuso.ru/data/cache/data/a3/a485dfb8950e3a3_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (664,'Нарезать болгарский перец.','https://vkuso.ru/data/cache/data/c7/c9ad18c9dfab8c7_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (664,'Твердый сыр натереть на терке.','https://vkuso.ru/data/cache/data/0f/fa585ae0831a50f_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (664,'Соединить все ингредиенты в салатнике.','https://vkuso.ru/data/cache/data/c0/b06610520d738c0_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (664,'Пропустить чеснок через пресс и добавить в салат.','https://vkuso.ru/data/cache/data/de/801dd541d41a3de_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (664,'Посолить и поперчить по вкусу.','https://vkuso.ru/data/cache/data/44/9f11a8465f50744_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (664,'Заправить салат майонезом или сметаной. Перемешать. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (665,'Кабачки помыть и срезать с двух сторон кончики, затем натереть на терке.','https://vkuso.ru/data/cache/data/d8/cc174c9ed1101d8_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (665,'Укроп мелко порезать.','https://vkuso.ru/data/cache/data/56/d7dbf40e768b956_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (665,'Чеснок натереть на терке или пропустить через пресс.','https://vkuso.ru/data/cache/data/bf/5581d29b5fb4dbf_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (665,'Соединить ингредиенты.','https://vkuso.ru/data/cache/data/c0/1ac0687284f9ac0_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (665,'Добавляем куриные яйца.','https://vkuso.ru/data/cache/data/e1/4fbda7dde17d8e1_434x295_notrise.png',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (665,'Соль и молотый черный перец.','https://vkuso.ru/data/cache/data/19/cc619e14d29e919_434x295_notrise.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (665,'Рисовую муку.','https://vkuso.ru/data/cache/data/86/c707b53c32e6686_434x295_notrise.png',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Взбиваем миксером до появления пены.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (665,'Обжариваем оладьи на хорошо разогретом растительном масле с обеих сторон до золотистого цвета. Затем выкладываем готовые оладьи на бумажное полотенце, чтобы избавиться от лишнего масла.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (666,'На противень выложить лист пергамента. Белки и соль взбить миксером до пышности. Небольшими порциями всыпать сахар, не прекращая взбивания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (666,'3/4 получившейся массы выложить на противень в виде круга диаметром около 20 см. Оставшиеся белки выложить по кромке, чтобы получилось "гнездо".',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (666,'Выпекать основу при 135°С в течение 75 минут. Оставить торт до остывания в выключенной духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (666,'Сливки слегка взбить, выложить на меренгу. Затем добавить свежие ягоды, промытые и обсушенные.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (667,'Смешать соль и сахар с минеральной водой и растительным маслом. Все перемешать. Очень медленно насыпать в смесь муку. Должно получить густое тесто, похожее на сметану. Снова перемешать. Блины на минеральной воде необходимо выпекать на тефлоновой сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (668,'Отбить с двух сторон свинину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (668,'Посолить, поперчить, обвалять в муке, затем в яйце и после в панировочных сухарях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (668,'Разогреть в сковороде масло (нагрев можно проверить кинув кусочек панировочных сухарей, если будет шипеть на поверхности, значит можно жарить)',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (668,'Выложить свиные отбивные и обжарить 2 мин с одной стороны, затем 2 мин с другой на сильном огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (668,'Перевернуть отбивные, убавить огонь на минимум и обжарить еще по 1-2 мин с каждой стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (668,'Выложить готовые отбивные на бумажное полотенце, чтобы дать лишнему жиру впитаться.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'В миску отправляем размягченное сливочное масло.','https://vkuso.ru/data/cache/data/91/2b4bb96b2409591_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Затем добавляем сахар.','https://vkuso.ru/data/cache/data/99/9b1881dd19daf99_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Тщательно перемешиваем до однородности.','https://vkuso.ru/data/cache/data/68/4063e6ceffae668_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Добавляем цедру 2 лимонов.','https://vkuso.ru/data/cache/data/07/541e42f68d56f07_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Ванильный сахар.','https://vkuso.ru/data/cache/data/b8/fcdcbd9936748b8_434x295_notrise.png',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Тщательно перемешиваем.','https://vkuso.ru/data/cache/data/b4/af186e2edc179b4_434x295_notrise.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Добавляем куриные яйца и хорошенько перемешивая массу.','https://vkuso.ru/data/cache/data/3f/2ce20772672723f_434x295_notrise.png',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Затем добавляем лимонный сок и соль.','https://vkuso.ru/data/cache/data/fc/7107e161e3b49fc_434x295_notrise.png',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Просеиваем в смесь пшеничную муку. Добавляем в смесь разрыхлитель.','https://vkuso.ru/data/cache/data/d8/b10fbb892240bd8_434x295_notrise.png',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Перемешиваем. Отделяем треть теста в другую емкость.','https://vkuso.ru/data/cache/data/6d/d5e5d96bab0a06d_434x295_notrise.png',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'В меньшую часть теста добавляем зеленый пищевой краситель. Тщательно перемешиваем.','https://vkuso.ru/data/cache/data/09/193415b86e68209_434x295_notrise.png',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'В большую часть теста добавляем желтый пищевой краситель. Тщательно перемешиваем.','https://vkuso.ru/data/cache/data/59/96ad57d59714959_434x295_notrise.png',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Квадратную форму (у меня форма 26*26 см) выстилаем пергаментом и выкладываем в нее желтое тесто. Выпекать в разогретой духовке до 160 градусов 35-40 минут.','https://vkuso.ru/data/cache/data/77/4853b72a9b20877_434x295_notrise.png',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Квадратную форму выстилаем пергаментом и выкладываем в нее зеленое тесто. Выпекать в разогретой духовке до 160 градусов 15-20 минут.','https://vkuso.ru/data/cache/data/80/6dfc640306b8280_434x295_notrise.png',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Готовый желтый корж достаем из формы, смазываем сгущенкой. (Вместо сгущенки можно использовать джем, например абрикосовый).','https://vkuso.ru/data/cache/data/6d/b71ca27f5d3e16d_434x295_notrise.png',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Готовый зеленый корж достаем из формы, выкладываем сверху на желтый корж, немного придавливаем.','https://vkuso.ru/data/cache/data/9a/18445b97690929a_434x295_notrise.png',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Отрезаем края.','https://vkuso.ru/data/cache/data/96/c2524cb405b6e96_434x295_notrise.png',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Разрезаем на 2 равные части.','https://vkuso.ru/data/cache/data/5c/da66770da2ef95c_434x295_notrise.png',18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Очень тонко срезаем верхний слой.','https://vkuso.ru/data/cache/data/31/348616ce00fd831_434x295_notrise.png',19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Разрезаем на 6 равных частей.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (669,'Перекладываем готовые пирожные на тарелку.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (670,'Промыть куриное филе под проточной водой, нарезать его на маленькие кусочки. Нарезать лук как можно мельче, положить его жариться на сковороду с разогретым растительным маслом. После того как лук станет прозрачным, положить к нему филе курицы, посыпать перцем, солью, перемешать и жарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (670,'Хорошо вымыть капусту, тонко нашинковать и сложить в емкость. Поперчить, посолить, перемешать, добавить майонез. Курицу в готовом виде переложить на отдельную тарелку. Приступить к приготовлению соуса. Взять несколько мисочек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (670,'В одну выдавить 5 столовых ложек кетчупа и посыпать любой приправой, хорошо перемешать. Во вторую вылить столько же кефира, добавить майонез приблизительно 4 столовые ложки, добавить несколько долек чеснока. Тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (670,'Сделать нарезку из огурцов и помидоров, порезать их тонкими дольками и выложить на тарелку. Чтобы было удобно, ингредиенты, предназначенные для шаурмы, поставить на столе рядом. Взять большую доску, выложить на нее ½ одного лаваша.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (670,'Густо намазать его соусами, выложить ближе к краю в ряд куриное филе, предварительно разделенное на четыре части. Выложить около мяса в ряд капусту. Сверху положить огурцы и помидоры. Готовую шаурму свернуть так, чтобы начинка не вытекла. Остальную шаурму делать таким же образом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (670,'Разогреть масло на сковороде. Обжарить вкусную шаурму с курицей в домашних условиях со всех сторон, пока не появится золотистая корочка. Если стались соусы, то выложить их по ложечке в открытую часть шаурмы перед тем, как подавать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (671,'Свиную корейку поделить на порционные куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (671,'Накрыть продукт пленкой, отбить молотком до толщины около пяти миллиметров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (671,'Противень застелить пергаментом, смазать сливочным маслом, выложить мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (671,'Посолить, поперчить по вкусу. По желанию добавить сушеные травы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (671,'Репчатый лук очистить, нарезать полукольцами, обжарить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (671,'Другой вариант термообработки: залить кипящей водой на пять минут, затем отжать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (671,'Натереть на крупной терке твердый сыр: «Швейцарский», «Эмменталь», «Радомер».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (671,'На каждый кусочек мяса положить по кусочку сливочного масла, лук, посыпать сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (671,'Блюдо полить сметаной или сливочным соусом, майонезом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (671,'Время выпекания – от тридцати до сорока минут, температура – 180 градусов. Признак готовности – аппетитная корочка.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (672,'Шампиньоны вымыть, нарезать тонкими пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (672,'Репчатый лук вымыть и очистить, нарезать тонкими полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (672,'Прогреть сковороду со сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (672,'Выложить грибы и половину луковой нарезки. Потушить под крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (672,'После испарения влаги продукты переложить в миску для остывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (672,'Говяжью вырезку нарезать поперек волокон ломтиками толщиной в один сантиметр. Отбить ломтики молотком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (672,'Соль и перец – по вкусу, выложить мясо стопкой на некоторое время для пропитывания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (672,'Прогреть духовку до 190 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (672,'Противень застелить пергаментом, выложить слой лука, сверху – мясо.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (672,'Далее – кусочки сливочного масла, грибная начинка. Разложить ингредиенты равномерно.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (672,'Натереть сыр, посыпать блюдо сверху.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (672,'Полить сметаной или майонезом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (672,'Время запекания в духовом шкафу – от тридцати до сорока минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (673,'Репчатый лук и сладкий болгарский перец вымыть, лук нарезать полукольцами, перец – соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (673,'Прогреть на сковороде сливочное масло, обжарить овощи до полуготовности, не допускать пригорания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (673,'Промыть куриное филе, промокнуть салфетками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (673,'Разрезать мясо на порции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (673,'Прогреть духовку до 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (673,'Порции выложить на доску для разделки, отбить молотком под пищевой пленкой. Использовать деревянный молоток.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (673,'Филе выложить на противень, застеленный пергаментом, смазанным сливочным маслом. Соль и перец молотый – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (673,'Всыпать куркуму.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (674,'Свеклу, огурец, морковь промыть, корнеплоды очистить от кожуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (674,'Свеклу отварить целиком, остудить и нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (674,'Огурцы нарезать тонкими короткими полосками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (674,'Репчатый лук измельчить и перетереть вместе с солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (674,'Продукты переложить в кастрюлю, влить квас, свекольный отвар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (674,'Добавить лимонный сок, соль, сахарный песок и мелко нарубленную зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (675,'Говядину промыть, нарезать кусками среднего размера, выложить в небольшую кастрюлю, влить холодную воду. Варить до полуготовности. Пену собирать шумовкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (675,'Вымыть свеклу и отварить отдельно, корнеплод нарезать тонкой соломкой после остывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (675,'Очистить лук, морковь и картофель, нарезать овощи кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (675,'К мясу в бульоне добавить картофель, варить пятнадцать или двадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (675,'Приготовить заправку из обжаренного на сковороде репчатого лука.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (675,'После появления золотистой корочки влить томат-пасту, уксус, соль и сахар.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (675,'Продукты перемешать, потушить около пяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (675,'Обжарку добавить в картошку с мясом вместе со свеклой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (675,'Положить перец-горошек, лавровый лист и свежую зелень.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (675,'Блюдо подать со сметаной и рубленой зеленью, зеленым луком-пореем.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (676,'Вымыть свеклу, отварить до готовности, остудить и натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (676,'Картофель очистить и нарезать кубиками, репчатый лук – полукольцами, морковь – полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (676,'Потушить морковь и лук в сотейнике с маслом и водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (676,'Влить немного воды в кастрюлю, довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (676,'Выложить свеклу, еще раз довести до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (676,'Добавить картофель.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (676,'Довести будущий суп до кипения в третий раз, добавить лук с морковью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (676,'Посолить блюдо в конце приготовления по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (676,'Выложить сметану, перемешать, еще раз прокипятить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (677,'В емкости перемешиваем венчиком молоко, яйца, соль, перец.','https://vkuso.ru/data/cache/data/92/acef528b105b092_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (677,'На крупной терке натираем сыр.','https://vkuso.ru/data/cache/data/ff/4f525740e0b20ff_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (677,'Измельчаем зелень.','https://vkuso.ru/data/cache/data/ea/1d689702eca52ea_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (677,'Ножницами нарезаем лаваш небольшими кусочками, еще раз перемешиваем.','https://vkuso.ru/data/cache/data/6b/1a62edaf7db4f6b_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (677,'Отправляем в форму для запекания, предварительно смазанную растительным маслом. Помещаем в разогретую духовку на температуру 180 градусов примерно на 30-35 минут. Всем добра!','https://vkuso.ru/data/cache/data/1e/d9f77bca4f21d1e_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (678,'Капусту нашинкуем тонкой соломкой. Морковь я натираю на терке для корейской моркови. Отправляем эти ингредиенты в миску и немного посолив перемешаем и помнем руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (678,'Помидор и колбасу нарезаем не толстой соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (678,'Зелень мелко нашинкуем. Я взяла по небольшому пучку свежего укропа, зеленого лука и немного петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (678,'Отправляем все оставшиеся нарезанные продукты и нашинкованную зелень в миску к капусте. Заправляем по своему желанию сметаной или майонезом, подсолим при необходимости и перемешаем все ингредиенты в салате.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (679,'Говядину с косточкой хорошо промыть. Выложить продукт в кастрюлю, залить водой, довести до кипения, пену снять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (679,'Огонь убавить, варить два часа или больше, до готовности. Жидкость должна увариться в два раза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (679,'Мелко нарезать и обжарить на растительном масле морковь и репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (679,'В почти готовую обжарку добавить уксус и томатную пасту.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (679,'Вымыть свеклу, картофель. Отварить в кожуре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (679,'Охладить, очистить, нарезать ломтиками небольшого размера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (679,'Бульон процедить, перелить в кастрюлю.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (679,'Отделить мясо от костей, нарезать полосками, выложить обратно в бульон вместе с обжаркой, картофелем, нарезанным кубиками, свеклой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (679,'Варить суп до готовности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (679,'Лавровый лист положить в конце приготовления.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2682,'Крупно потереть любой сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (679,'Время настаивания – от десяти до пятнадцати минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (680,'Молодую свеклу вымыть, очистить, снять шкурку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (680,'Варить вместе с семенами тмина в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (680,'Овощ остудить, нарезать мелкими кубиками, побрызгать лимонным соком для сохранения цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (680,'Отварить картофель, яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (680,'Очистить и нарезать мелкими кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (680,'Порубить зелень и чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (680,'Нарезать свежий огурец, редис, колбасу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (680,'Ингредиенты выложить в порционные тарелки поровну.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (680,'Смешать отдельно процеженный свекольный отвар с кефиром в пропорции один к двум.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (680,'Смесью залить овощи с колбасой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (680,'В каждую тарелку положить по ложке сметаны.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (681,'Куриное мясо вымыть, залить водой, варить в течение часа или полутора.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (681,'Процедить бульон, влить его в мультиварку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (681,'Очистить и мелко нарезать картофель, выложить в бульон вместе с нарезанным мясом. Соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (681,'Закрыть крышку мультиварки, выставить режим «Тушение» на час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (681,'Отварить и остудить яйцо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (681,'Очистить морковь и свеклу, натереть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (681,'Нашинковать репчатый лук.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (681,'Обжарить овощи на сковороде, добавить томатную пасту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (681,'Продукты перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (681,'Влить в бульон готовую обжарку, потушить еще пять минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (681,'Всыпать в готовый суп нарезанную зелень, дать постоять.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (681,'Блюдо разлить в тарелки, добавить по половинке яйца, сметану.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (682,'Поставить на огонь кастрюлю с сывороткой или водой, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (682,'Свеклу, лук и морковь вымыть, очистить, мелко нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (682,'Выложить продукты в сотейник, влить кипящую воду, положить сахарный песок, томатную пасту, влить лимонный сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (682,'Потушить все вместе до готовности свеклы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (682,'Долить кипяток. Довести суп до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (682,'Всыпать рубленую зелень, накрошенный чеснок, поварить две минуты, огонь погасить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (683,'Воду довести до кипения, охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (683,'Свеклу вымыть, нашинковать, залить кипяченой холодной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (683,'Добавить корочку черного хлеба.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (683,'Емкость поставить в тепло на несколько дней для закисания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (683,'Процедить готовый квас через мелкое сито или марлю.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (683,'Выставить на холод.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (684,'Говядину вымыть, нарезать кусочками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (684,'Очистить и нарезать четвертинками колец репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (684,'Натереть на терке морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (684,'Порезать соломкой свеклу, картофель и сладкий болгарский перец.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (684,'Прогреть казанок с растительным маслом, выложить говядину, обжарить под крышкой на сильном огне. Когда появится жидкость от мяса – огонь убавить, тушить продукт несколько минут на среднем огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (684,'Добавить лук, перемешать, тушить еще некоторое время под крышкой до готовности, лук должен стать прозрачным.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (684,'Всыпать морковь, тушить пять минут, добавить перец, прогревать еще пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (684,'Заправить массу солью, сахарным песком, томатной пастой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (684,'Перемешать, тушить десять или пятнадцать минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (684,'Всыпать картофель, перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (684,'Влить воду, довести до кипения.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (684,'Очистить чеснок, порубить вместе с зеленью.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (684,'Добавить в суп в конце приготовления.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (684,'Поварить еще две или три минуты, выключить.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (685,'Слегка обжарить грибы с луком и мясным фаршем, посолить, поперчить. Смазать формочку маслом и выложить слои: лаваш, фарш, лаваш, грибы, лаваш и так далее.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (685,'Приготовить молочный соус: размешать муку в молоке, посолить и довести до кипения, убрать с огня и подождать пока соус загустеет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (685,'Полученной смесью залить лазанью, посыпать сыром и поместить в духовку. Готовится ленивая мясная лазанья с грибами около 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (686,'Свеклу вымыть, очистить, варить в большой кастрюле. Довести до кипения, добавить лимонную кислоту, варить на тихом огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (686,'Нарезать соленую свиную грудинку. Обжарить в казанке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (686,'Очистить овощи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (686,'Мелко нарезать чеснок, репчатый лук, черешки сельдерея и укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (686,'В готовую поджаристую грудинку добавить овощи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (686,'Перемешать, прогреть под крышкой на тихом огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (686,'Картофель очистить, нарезать кубиками небольшого размера, добавить в казанок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (686,'Порезать малосольные огурцы, добавить в основную массу вместе с горошинами черного перца.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (686,'Очищенную морковь и отваренную свеклу нарезать соломкой или натереть на терке для моркови по-корейски.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (686,'Выложить продукты в казанок, добавить аджику и томатную пасту.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (686,'Влить чистую воду или свекольный отвар, соль и перец – по вкусу и желанию.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (686,'Положить несколько листочков лавра, варить при умеренной температуре.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (686,'Измельчить хорошо промытую зелень укропа, лука.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (686,'Натереть зеленые яблоки, добавить продукт за пять минут до готовности, через три минуты – зелень.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Фасоль залить водой с вечера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Промыть ребра с мясом, нарубить порционно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Залить также холодной водой, довести до кипения. Снять пену шумовкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Варить полтора часа на тихом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Фасоль отварить до полуготовности в сотейнике, залив холодной водой и доведя ее до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Очистить свеклу и картофель, вымыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Картофель нарезать кубиками, свеклу натереть на крупной терке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Очистить перец болгарский, чеснок и лук.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Прогреть сотейник, потушить перец с луком и сливочным маслом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Через три или пять минут добавить свеклу, нарезанный чеснок, томатную пасту.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Влить лимонный сок для сохранения цвета. Время тушения – от десяти до пятнадцати минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Через полтора часа к ребрышкам добавить картофель.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Фасоль отцедить и положить к остальным ингредиентам.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Через пятнадцать минут добавить в кастрюлю обжарку, соль, перец-горошек, лавровый лист. Время варки – около пятнадцати минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Хлеб нарезать ломтиками.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Очистить и пропустить через пресс чеснок.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Добавить рубленую зелень, воду и растительное масло, соль, перец молотый, перемешать.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (687,'Окунуть в полученный соус ломтики хлеба. Подать к супу на блюдечке.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (688,'Филе хека или минтая вымыть и нарезать порционными кусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (688,'Влить холодную воду, поставить на огонь. В процессе варки удалять пену. Довести до кипения, варить при полузакрытой крышке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (688,'Очистить свеклу, натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (688,'Прогреть на сковороде сливочное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (688,'Выложить свеклу, влить лимонный сок для сохранения цвета, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (688,'Добавить рыбный бульон, потушить свеклу под крышкой в течение пятнадцати минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (688,'Очистить болгарский перец, морковь и репчатый лук. Овощи измельчить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (688,'Обжарить на другой сковороде вместе с рубленым чесноком и маслом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (688,'Нарезать крупной соломкой очищенный картофель.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (688,'Переложить в рыбный бульон, довести до кипения. Варить от десяти до пятнадцати минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (688,'Добавить обе обжарки со сковородок.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (688,'Соль и перец молотый – по вкусу. Перемешать.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (688,'Все вместе варить семь – десять минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (688,'Огонь погасить.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (689,'Смешать сахар, ваниль, яйца и молоко. Добавить растительное масло, затем гашеную соду и просеянную муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (689,'При помощи венчика взбить до однородной массы, по густоте похожей на сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (689,'Выложить тесто в смазанные маслом формы, добавив по 1/2-1 ч. ложке ягод из варенья в каждый кекс.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (694,'Влить растительное масло, взбить еще раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9357,'Вылить его на карамель.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (689,'Выпекать в разогретой до 200°С духовке около 30 минут. Готовые кексы посыпать сахарной пудрой.','https://vkuso.ru/data/cache/data/c5/e5c08f4826c0cc5_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (690,'Говядину промыть и обсушить. Отбить продукт под пищевой пленкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (690,'Нарезать тонкими ломтиками толщиной в полсантиметра поперек волокон. Далее – соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (690,'На сковороду налить растительное масло, прогреть, обжарить мясо небольшими порциями. Продукт должен покрыться корочкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (690,'Не солить, обжаривать одну порцию в течение двух или трех минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (690,'Выложить мясо в отдельную миску.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (690,'Нарезать репчатый лук кольцами, а затем – четверть кольцами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (690,'Обжарить до золотистого цвета на растительном масле на той же сковороде, где жарилось мясо.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (690,'Когда лук станет золотистым – присыпать овощ мукой, перемешать и жарить еще минуту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (690,'Добавить томатную пасту, сметану, соль, перец, воду, молотый мускатный орех.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (690,'Ингредиенты перемешать, добавить мясную обжарку к луковой, все вместе тушить пять минут под крышкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (690,'Прогревать до готовности мяса. Соус не должен загустеть, при необходимости можно подлить немного воды.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (691,'Печень промыть и обсушить. Удалить желчные протоки и пленки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (691,'Продукт нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (691,'Нарезать репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (691,'Налить на сковороду растительное масло, прогреть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (691,'Жарить лук на среднем огне в течение двух или трех минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (691,'На другой сковороде большего размера прогреть еще немного растительного масла. Выложить печень, соль и молотый перец – по вкусу. Время обжаривания – от десяти до пятнадцати минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (691,'Добавить луковую обжарку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (691,'В стакане воды разболтать муку, в подливке не должно быть комочков.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (691,'Влить на сковороду с печенью, потушить продукт в течение пяти минут, помешивать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (691,'Добавить специи и жирную сметану.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (691,'Заправить томатной пастой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (691,'Содержимое сковороды перемешать, тушить на тихом огне в течение десяти минут под крышкой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (691,'Если подлива окажется слишком жидкой – все можно исправить путем дополнительного выпаривания.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (692,'Приготовить тесто: в муку добавить корицу, соду, мягкое сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (692,'Натереть морковь, добавить в основную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (692,'Вбить яйца, всыпать сахар, добавить ванильный пудинг.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (692,'Продукты перемешать до однородного состояния. Масса должна быть липкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (692,'Разделить тесто на две части, обе завернуть в пленку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (692,'Одну часть положить в холодильник, другую заморозить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (692,'Приготовить начинку из ванильного пудинга, яиц и творога.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (692,'Влить лимонный сок, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (692,'Тесто из холодильника выложить в смазанную маслом форму для выпекания. Руки лучше намочить водой, чтобы тесто не липло.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (692,'Выложить на тесто творожную массу. Сверху посыпать натертым замороженным тестом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (692,'Выпечь пирог в течение пятидесяти минут, температура приготовления – 160 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (692,'Пирог перед подачей немного остудить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (693,'Очистить и вымыть морковь, залить растительным маслом, всыпать сахарный песок, вбить сырые куриные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (693,'Продукты взбить в блендере до получения однородной массы. Можно обойтись мелкой теркой для моркови.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (693,'Пшеничную муку перемешать с разрыхлителем, всыпать в морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (693,'Ингредиенты перемешать, конечный продукт – тесто приятного желтого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (693,'Готовое тесто выложить, печь при температуре 180 градусов, время приготовления – сорок минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (693,'Приготовить глазурь из сахарного песка, воды и какао-порошка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (693,'Смесь довести до кипения, выключить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (693,'Теплый морковный пирог полить глазурью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (694,'Вбить сырые куриные яйца в миску, взбить с сахаром в пену при помощи миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (694,'Всыпать муку и ванильный сахар, продолжать взбивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (694,'Натереть морковь на мелкой терке, всыпать в общую массу, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (694,'Добавить погашенную уксусом или лимонным соком соду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (694,'Смазать форму растительным маслом, влить тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (694,'Печь в течение 45 минут, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (695,'Кабачок почистить, разрезать вдоль и убрать сердцевину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (695,'Творог перемешиваем с солью, перцем, чесноком, сыром, укропом и яйцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (695,'Творог выкладываем в лодочки и отправляем в духовку на 30 минут при 180 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (696,'Морковь очистить, измельчить при помощи блендера или терки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (696,'Промыть изюм, залить водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (696,'Вымыть лимон, цедру снять. Мякоть поделить пополам, из одной половины отжать сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (696,'Растереть в ступке зерна кардамона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (696,'Приготовить тесто с манкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (696,'Перемешать морковь с лимонным соком, ванильным сахаром, цедрой и кардамоном.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (696,'Влить воду, оставить массу на пять или десять минут. Основной продукт должен пустить сок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (696,'Положить изюм, добавить масло, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (696,'Всыпать манную крупу, оставить до набухания на десять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (696,'Погасить пищевую соду лимонным соком.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (696,'Тесто вымесить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (696,'Форму смазать маслом, присыпать манкой края и дно.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (696,'Выложить тесто, разровнять. Время выпекания – один час, температура – 180 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (697,'Овощ очистить, натереть на мелкой терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (697,'Вымыть апельсины, цедру также натереть на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (697,'Отдельно приготовить пышную массу из взбитых яиц с сахарным песком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (697,'Перемешать с морковью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (697,'Добавить молоко, масло, яйца, перемешать еще раз.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (697,'Муку соединить с разрыхлителем, ввести основную массу, приготовить тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (697,'Выложить в форму для выпекания, температура приготовления – 180 градусов, время – сорок минут. Корж не должен потрескаться.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (698,'Яйца взбить с сахарным песком, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (698,'Морковь очистить, натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (698,'Добавить в яйца подсолнечное масло, взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (698,'Всыпать морковь, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (698,'Добавить просеянную муку, разрыхлитель, какао-порошок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (698,'Замесить тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (698,'Вылить массу в смазанную маслом форму.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (698,'Время выпекания – сорок минут, температура – 180 градусов. Пирог остудить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (699,'Для приготовления соуса сложить в блендер кусочки авокадо, влить сок лимона, чуть подсолить, измельчить до состояния пюре, если получится слишком густым, то добавить немного воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (699,'Хорошо прожарить пластинки бекона, выложить его на многослойное бумажное полотенце, перейти к приготовлению яйца пашот.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (699,'Закипятить в кастрюле воду, прикрутить газ до минимума, аккуратно разбить яйцо в половник, окунуть его в кипяток, проварить около 4 минут, повторить все с остальными яйцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (699,'Нарезать хлеб или взять готовую нарезку, приготовить тосты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (699,'Собрать для подачи к столу в следующем порядке: разложить по ластинке бекона на каждый кусочек хлеба, а сверху положить по яйцу, полить соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (700,'Нарезать на куски булку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (700,'Яйцо разболтать (не взбивать) вилкой, налить в миску молоко, обмакнуть в него булку, а потом в яичную болтушку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (700,'Хорошо разогреть масло в сковороде, обжарить куски с 2 сторон до образования корочки соломенного цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (700,'Переложить их на несколько слоев бумажного полотенца для удаления излишков масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (700,'Сварить яйца-пашот.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (700,'Вымыть, обсушить шпинат, нарезать, обжарить в разогретом сливочном масле.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (700,'Переложить на булочку, а на него уложить слайсы лосося, чуть-чуть поперчить, завершить яйцом-пашот.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (700,'По желанию можно полить голландским соусом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (700,'Для его приготовления перемешать 4 желтка со столовой ложкой сока лимона, прогреть на водяной бане.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (829,'Сложить изделия в чашу мультиварки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (700,'Добавить в смесь за 3 раза, хорошо вымешивая, после каждой добавленной порции, 120 г масла.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (700,'Варить до загустения, убрать с плиты, подсолить, поперчить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (700,'Существует второй способ приготовления соуса.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (700,'Желтки дополнительно взбить (миксером, венчиком) прямо на водяной бане с соком лимона до пышного состояния, влить заранее растопленное и охлажденное масло, взбивать не переставать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (700,'Должна получиться густая масса, снять с плиты, чуть подсолить, поперчить, взбить еще раз и сразу подать к столу.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (701,'Авокадо разрезать вынуть семечку, очистить от кожицы и нарезать дольками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (701,'Рукколу вымыть, выложить на тарелку, добавить авокадо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (701,'Клубнику очистить от хвостиков, разрезать пополам, отправить в тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (701,'Из пачки шариков моцарелла слить жидкость, шарики разрезать пополам, добавить в тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (701,'Полить соусом терияки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (701,'Кедровые орешки отправить в сковороду и слегка обжарить, добавить в тарелку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (702,'Нарежьте ветчину и болгарский перец небольшими кубиками, сложите в миску. Добавьте яйца (5 шт.), соль и перец – перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (702,'Разогрейте на сковороде сливочное масло. Вылейте в сковороду яичную смесь и готовьте на сильном огне 2–3 минуты перемешивая. Добавьте сливочный сыр перемешивайте пока сыр не растает. Снимите сковороду с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (702,'Раскатайте тесто в прямоугольник размером, выложите на противень, застеленный пекарской бумагой. В центр теста выложите начинку из яичного омлета. На омлет натрите сыр на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (702,'Сделайте надрезы на тесте перпендикулярно начинке, на расстоянии 2– 3 см друг от друга по длинным сторонам прямоугольника, немного не доходя до начинки. Затем заворачиваем край на начинку и поочередно накрываем начинку кусочками теста, будто заплетая косу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (702,'Взбиваем оставшееся яйцо и смазываем им тесто, затем посыпаем маком. Разогреваем духовку до 180 градусов, выпекаем 25 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (703,'В миску отправить сахар и сливочное масло комнатной температуры, перемешать и взбить миксером. Вбить яйцо и снова перемешать при помощи миксера. Всыпать овсяные хлопья, муку и разрыхлитель перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (703,'Орехи и шоколад нарубить ножом на мелкие кусочки, отправить в тесто. Добавить в тесто шоколадные капли.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (703,'Противень застелить пекарской бумагой. Смачиваем руки водой, чтобы тесто не липло к рукам. Отщипнуть кусочек теста и сформировать печенье.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (704,'В глубокой сковороде разогреть на среднем огне оливковое масло. Чеснок нарезать слайсами и добавить в сковороду, обжарить 30 секунд на сильном огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (704,'Помидоры нарезать мелким кубиком, добавить в сковороду готовить 15 минут на среднем огне, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (704,'Початки кукурузы нарезать кусочками толщиной в 2-3 см, выложить в сковороду, влить куриный бульон и посыпать зафараном, готовить 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (704,'Выложить кусочки рыбы, влить вино накрыть крышкой и готовить 8 минут на медленном огне. Посолить (1/3 ч. л.), добавить паприку (щепотка).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (705,'Лук порей нарезать кольцами. Морковь очистить и натереть на мелкой терке. В кастрюле разогреть растительное масло и отправить туда морковь с луком. Готовим на среднем огне 10 минут, перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (705,'Помидоры залить кипятком на 2 минуты, затем слить воду и снять кожицу. Нарезать помидор на мелкие кубики, отправить в кастрюлю. Готовим 5 минут, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (705,'Картофель очистить, нарезать на мелкие кубики, отправить в кастрюлю. Влить в кастрюлю сливки, воду, соль – перемешать. Накрываем крышкой, доводим до кипения и варим 15 минут на медленном огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (705,'Красную рыбу очистить от костей и кожи. Нарезать небольшими кубиками. Отправить в кастрюлю с супом, греем 7 минут',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (706,'Смешать яйца, сахар и молоко. Добавить просеянную муку и соль. Взбить миксером до однородности и влить масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (706,'Испечь 16 блинчиков на хорошо разогретой сковороде. Перед выпечкой первого смазать сковороду маслом, дальше - не обязательно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (706,'После приготовления блины складывать друг на друга, промазывая тонким слоем сливочного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (706,'Смешать творожную массу со сметаной. Смазать тонким слоем начинки каждый блин и собрать торт.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (706,'Убрать в холодильник, чтобы пропитался, на пару часов. Перед подачей украсить вишневым вареньем.','https://vkuso.ru/data/cache/data/ed/619d4e93653b0ed_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (707,'Приготовить тесто: просеять муку холмиком, сделать лунку в центре. Перемешать теплое молоко, дрожжи и пару чайных ложек сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (707,'Добавить смесь в углубление, немного смешать. Присыпать столовой ложкой муки, накрыть пленкой и убрать в теплое место до появления трещинок на поверхности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (707,'С лимона снять цедру, измельчить. Добавить в тесто яйца, размягченное масло, остальной сахар, соль и цедру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (707,'Перемешать, накрыть пленкой и убрать в тепло до увеличения объема в два раза. Тесто выложить на присыпанный мукой стол и обмять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (707,'Скатать колбаску, разрезать на кусочки среднего размера, из которых скатать шарики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (707,'Смешать в сотейнике стакан молока, 50 г сахара и 50 г сливочного масла. Подогреть на плите, перемешать и вылить в форму для запекания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (707,'Выложить в форму шарики из теста близко друг к другу, накрыть чистым полотенцем и оставить на 20 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (707,'Духовку разогреть до 180°С, поставить туда форму с клецками и выпекать в течение 25 минут, пока тесто не зарумянится.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (707,'В это время приготовить соус: смешать молоко и ванильный сахар, довести до кипения. Тонкой струйкой влить взбитую смесь желтков, яиц и обычного сахара.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (707,'Процедить смесь через сито, перелить в сотейник, поставить на водяную баню и взбить при помощи венчика.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (707,'Клецки достать из духовки, дать немного остыть. Соус перелить в керамическую пиалу, подать вместе с клецками.','https://vkuso.ru/data/cache/data/4c/06cca954cb1a54c_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (708,'Филе промыть и порезать небольшими продолговатыми кусками. Посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (708,'Выложить в миску, залить сметаной и убрать в холодильник на 2 часа. В другой емкости перемешать сырой белый кунжут и пшеничные сухари.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (708,'Каждый кусок курицы обвалять в смеси сухарей и кунжута. Обжарить на сковороде в растительном масле до золотисто-коричневого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (708,'Подать кусочки куриной грудки с салатом из свежих сочных овощей, рисом или картофелем.','https://vkuso.ru/data/cache/data/dc/945db15a155dadc_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (709,'Развести дрожжи водой с комнатной температурой в большой миске, добавить разрыхлитель, смешанный с мукой, перемешать до однородности, дать постоять минут 5-7.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (709,'Взбить пару яиц до образования устойчивых пиков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (709,'Объединить с тестом, аккуратно перемешать, всыпать стакан подсоленной муки, слегка перемешать, переложить на стол, вымесить тесто до гладкого состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (709,'Смазать миску маслом, положить тесто, комок несколько раз перевернуть, прикрыть без зазоров пленкой, оставить в тепле на час.','https:https://st.vkuso.ru/data/cache/thumb/c7/6d58b65d5c9ffc7_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (709,'Готовое тесто раскатать, вырезать кружочки стаканом (около 7 см диаметром). Заготовки разложить на столе, присыпанном кукурузной мукой, притрусить из сверху тоже мукой, прикрыть их пленкой, дать постоять около 45 минут.','https:https://st.vkuso.ru/data/cache/thumb/13/2414085d6862513_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (709,'Выпекать кексы, в прогретой до 170 градусов на застланном пергаментом противне до полной готовности.','https:https://st.vkuso.ru/data/cache/thumb/c3/49fe6bec2b4a5c3_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (709,'Для начинки обжарить бекон со шпинатом и помидорами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (709,'Разложить на кекс обжарку, сверху положить яйцо пашот, прикрыть сыром, поместить примерно на 4 минуты в духовку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (709,'Вынуть, сразу поставить на стол.','https:https://st.vkuso.ru/data/cache/thumb/3f/9706c9b0db56f3f_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (710,'Соус приготовить из смеси взбитого (на водяной бане) желтка с 5 мл воды, влить лимонный сок, поперчить, посолить, добавить растопленное масло, взбить до пышности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (710,'Нашинковать шпинат, обжарить на масле с порубленным чесноком, посолить, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (710,'В тостере обжарить хлеб.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (724,'Перебрать ягоды, промыть, выжать сок, замочить и вымыть чернослив.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (710,'В сотейнике довести до кипения воду, влить чуть-чуть уксуса, энергично перемешать, чтобы получить воронку, осторожно разбить в нее яйцо, проварить 3 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (710,'Переложить на тарелку хлеб, разложить сверху шпинат и яйцо пашот, оформить верх соусом, украсить веточкой молодого базилика, икрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (711,'Сварить курицу в подсоленной воде с лавровым листом и горошками перца.','https:https://st.vkuso.ru/data/cache/thumb/d2/78c0bd6fbd11ed2_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (711,'Вынуть мясо, порезать на 4 части, подсолить кусочки, поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (711,'Приготовить в тостере поджаренные кусочки батона.','https:https://st.vkuso.ru/data/cache/thumb/d4/7d68b0f43ad36d4_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (711,'У яиц тщательно отделить желтки.','https:https://st.vkuso.ru/data/cache/thumb/cc/678701afea21acc_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (711,'Выдавить из лимона столовую ложку сока.','https:https://st.vkuso.ru/data/cache/thumb/48/0126251042a4348_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (711,'Довести до кипения в маленькой кастрюльке воду, чуть присолить, добавить уксус, нагрев сделать минимальным, быстро размешать воду до получения воронки, влить в нее яйцо осторожно, чтобы не разорвать пленку желтка, варить чуть больше 2 минут (до полного сворачивания белка).','https:https://st.vkuso.ru/data/cache/thumb/24/20839366d412c24_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (711,'Приготовить соус «голландез». В маленькой кастрюльке, желательно с толстым дном, растопить масло, добавить желтки с солью и перцем, влить лимонный сок, взбить прямо на водяной бане венчиком до пышности, вливая порциями растопленное масло.','https:https://st.vkuso.ru/data/cache/thumb/3c/901f05c6d64693c_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (711,'Собрать все ингредиенты в единое блюдо. Разложить по тарелочкам ломти батона, на них положить курицу, а потом – яйцо и соус, аккуратно проткнуть желток, украсить веточкой какой-нибудь зелени, подать сразу к столу.','https:https://st.vkuso.ru/data/cache/thumb/34/71a6aa28a9ad134_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (712,'Выложить ножки в пакет, для запекания. В емкости положить все ингредиенты и размешать, чтобы получилась однородная масса. Полученным маринадом залить ножки и на час оставить мариноваться, желательно на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (712,'Духовку нагреть до 175 градусов, выложить ножки куриные по-грузински в форму для запекания так, чтобы между ними было место. Запекать приблизительно 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (713,'Для приготовления соуса отделить желтки у 3 яиц, поместить их в миску.','https:https://st.vkuso.ru/data/cache/thumb/f9/3a79c62c321fff9_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (713,'Ломти белого хлеба для тостов или батона подрумянить в тостере или на сковороде.','https:https://st.vkuso.ru/data/cache/thumb/de/8e9acfbf4804fde_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (713,'Поместить желтки в блендер, взбить в однородную массу с солью и перцем.','https:https://st.vkuso.ru/data/cache/thumb/c1/5f49003978558c1_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (713,'Растопить масло на сковороде, влить тонкой струйкой, обязательно помешивая, яйца, столовую ложку сок лимона, перемешать, соус готов.','https:https://st.vkuso.ru/data/cache/thumb/c9/b59c8ac7f4f83c9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (713,'Пластинки бекона обжарить до корочки с 2 сторон.','https:https://st.vkuso.ru/data/cache/thumb/ec/2603ca855b37bec_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (713,'Пока готовится бекон сварить яйца пашот, в подсоленной кипящей воде, с добавкой уксуса, «закрутить» ложкой воронку, разбить в нее очень осторожно яйцо, проварить около 3 минут, достать с помощью шумовки.','https:https://st.vkuso.ru/data/cache/thumb/bc/b7e8f67d54754bc_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (713,'Положить тосты на тарелку, на хлеб уложить бекон, яйцо, полить соусом, присыпать зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (713,'Перед подачей очень аккуратно проткнуть белок яйца, сразу поставить на стол.','https:https://st.vkuso.ru/data/cache/thumb/ed/adb73312eb028ed_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (714,'Подготовить фрукты, помыть, порезать на половинки, удалить семечки, разрезать каждую еще на 4 дольки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (714,'Переложить яблоки в подходящую кастрюлю, залить водой, добавить половину нормы сахара, размешать, поставить на плиту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (714,'Дать компоту закипеть, сделать минимальный огонь, всыпать оставшийся сахар, перемешать, чтобы сахар растворился.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (714,'Снять кастрюлю с плиты, дать постоять под крышкой треть часа, перелить в кувшин, хорошо охладить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (715,'Шоколад порубить мелкими кусочками (размером около 5 мм). Размягченное сливочное масло и сахар растереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (715,'Добавить взбитые венчиком яйца, кусочки шоколада и перемешать. Всыпать просеянную с разрыхлителем муку и замесить не очень густое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (715,'Выложить ложкой в порционные формочки для кексов на 2/3 высоты и выпекать 25 минут при 180°С.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10007,'Чеснок пропустить через пресс.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (715,'Готовые кексы достать из форм, дать немного остыть и посыпать сахарной пудрой. Сразу же подать к столу.','https://vkuso.ru/data/cache/data/22/197ffe171d37422_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (716,'Сливочное масло растереть с сахаром (масло должно быть мягким, комнатной температуры).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (716,'Добавляем 5 яиц (вводим по одному) и перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (716,'Добавляем корицу с разрыхлителем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (716,'Всыпаем муку, перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (716,'Осталось только добавить тёмный шоколад и всё тщательно перемешать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (716,'Форму для выпечки смазываем маслом ( я использовала подсолнечное), сливаем тесто, распределяем по форме.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (716,'Грушу нарезаем на небольшие полоски (как показано в видео) и выкладываем сверху на тесто по круга (можно слегка вдавить в тесто).',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (716,'Выпекаем 35 минут при 180°С.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (717,'Растерите мягкое сливочное масло с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (717,'Добавьте мед и хорошо перемешайте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (717,'Добавить яйца и ещё раз перемешайте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (717,'Добавляем разрыхлитель и муку (муку вводим постепенно).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (717,'Грецкие орехи мелко рубим.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (717,'Из теста формируем шарики и одной ложим на орехи, при этом вдавливая в тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (717,'Выпекать 20-25 минут при температуре 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (718,'Лук репчатый нарезаем тонкой соломкой, далее на разогретой сковороде с добавлением растительного масла обжариваем лук, до золотистой корочки! Как только появилась золотистая корочка, сдвигаем лук в 1 сторону, и посыпаем сахаром, что бы лук в закарамелизовался. Как только посыпались слегка еще обезжириваем и далее перекладываем на тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (718,'На этой же сковороде до небольшой корочки обжариваем сосиски. Как только обжарили перекладываем в отдельную тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (718,'Далее нужно обжарить полоски бекона до корочки. Как только обжарили, перекладываем на тарелку с бумажным полотенцем или же салфеткой, что бы часть масла стекла. Далее бекон нарезаем на более мелкие кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (718,'Натираем сыр на мелкой терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (718,'Приступим к хот догу. Булочку для хот дога нарезом не до конца. Во внутрь укладываем лист салата, на него укладываем сосиску, добавлением немного подготовленного бекона, добавлением немного подготовленного лука, по вкусу добавлением горчицы. и посыпаем сыром. Отправлением в духовку при 180°С на 5 минут. Все готово.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (719,'Шоколад растопить. Бананы почистить и порезать на кусочки. Насыпать в миску кокосовую стружку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (719,'Каждый кусочек банана наколоть на шпажку и обмакнуть в шоколаде, а затем в кокосовой стружке. Положить на тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (719,'Готовый десерт «Бананы в шоколаде» поставить в холодильник на полчаса, чтобы застыл шоколад.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (720,'Для начала необходимо измельчить печенье с грецким орехом в мелкую крошку (я использовала Блендер).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (720,'Добавляем сгущенное молоко (смотрите по консистенции).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (720,'Лепим небольшие шарики (влажными руками).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (720,'Готово! По желанию можно обвалять в какао, кокосовой стружке или сахарной пудре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (721,'В воду трем цедру с фруктов, затем выжимаем сок и добавляем сахар, либо сахарозаменитель. Перемешиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (721,'Процеживаем наш лимонад.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (722,'Вымыть ревень, порезать на кусочки вместе с яблоками, закипятить воду с добавлением гвоздики и сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (722,'Всыпать в кастрюлю ломтики яблок и ревеня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (722,'Проварить компот из яблок и ревеня с гвоздикой примерно 25 минут при слабом нагреве, хорошо охладить, подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (723,'блоки помыть, сердцевину удалить вместе с семенами специальным приспособлением или, разрезав на четвертинки, вырезать ножом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (723,'Нарезать яблоки и вымытые апельсины в кожуре на дольки, сливы разломить пополам и вынуть косточки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (723,'Сложить фрукты в кастрюлю, залить водой, дать закипеть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (723,'Огонь сделать минимальным, проварить компот из яблок и апельсинов со сливой несколько минут, добавить фруктозу, либо сахар, либо мед, тщательно размешать до полного растворения сахара.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (723,'Дать остыть, подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (724,'Залить жмых клюквы водой, закипятить, проварить около 10 минут, процедить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (724,'Всыпать в отвар сахар, положить чернослив, варить четверть часа, добавить ломтики яблок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (724,'Проварить яблочно-клюквенный компот с черносливом еще четверть часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (724,'Влить отжатый сок, проварить до закипания, размешать, дать остыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (725,'Вымытые яблоки порезать на дольки, вымытую клубнику – на пластинки, а лимон – на тонкие колечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (725,'Сложить все в кастрюлю, добавить сахарный песок, залить водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (725,'Поставить на плиту, варить после кипения компот из яблок и клубники с лимоном 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (725,'Дать остыть под крышкой, процедить, убрать в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (726,'Порезать очищенные яблоки без косточек на небольшие ломтики, сложить в кастрюлю с толстым дном (идеально в казан), залить малым количеством воды, только чтобы не пригорели фрукты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (726,'Протушить при слабом нагреве примерно час, до образования пюреобразной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (726,'Снять с плиты, процедить, густую часть протереть сквозь сито до однородной массы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (726,'Разложить пюре тонким слоем на противень, выстланный пергаментом, разровнять, поместить в уже прогретую до 120 градусов духовку, подсушить с открытой дверцей около часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (726,'Достать, перевернуть пласт диетической пастилы из яблок без сахара в духовке на другую сторону, вернуть в духовку, уменьшив температуру на 30 градусов, держать 2-2,5 часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (726,'Хорошо подсушенную пастилу разрезать на ленты или фигурки, предварительно удалив пергамент.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (727,'Сварить сироп: смешав 200 мл воды с сахаром, довести до кипения и добавить мяту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (727,'Через 5 минут влить оставшуюся воду, довести до кипения и слить сок лимона с апельсином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (727,'Процедить, добавить мед и остудить до комнатной температуры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (727,'Поставить смесь в морозилку на 3-4 часа. Один раз в процессе заморозки, достать и размешать вилкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (727,'Перед подачей граниту измельчить вилкой до состояния крупинок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (728,'Подготовить яблоки, почистить, убрать семена, порезать дольками, поместить в кастрюлю, влить немного воды (1/3 стакана), прикрыть крышкой, тушить около 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (728,'Убрать с плиты, дать немного остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (728,'Протереть сквозь сито, добавить белок яйца, взбить в однородную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (728,'Залить водой (60 мл) агар-агар, дать постоять четверть часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (728,'Всыпать сахар, прогреть, помешивая, на медленном огне до 105 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (728,'Дать сиропу остыть градусов до 65, добавить пюре, переложить в чашу миксера, взбить на малых оборотах в однородную смесь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (728,'Пищевой пленкой застелить противень, поставить яблочную пастилу на агар-агаре с сахаром на солнце, но на сквозняке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (728,'Когда достаточно подсохнет аккуратно перевернуть на другую сторону, дать окончательно высохнуть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (728,'Практически готовый лист пастилы нарезать ромбами или полосками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (728,'Досушить можно за пару дней на солнце, или в прогретой до 100 градусах духовке у которой открыта дверца.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (729,'Вымыть айву и обсушить, разделить на четвертинки, убрать косточки, уложить в сотейник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (729,'Яблоки очистить, удалить семена, нарезать дольками, отправить к айве.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (729,'Влить воду, проварить час на малом огне, остудить, чтобы не обжечься, протереть до состояния пюре через сито.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (729,'Добавить в пюре лимонный сок из пары плодов и сахар, размешать, варить четверть часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (729,'Густую пастилу из айвы с яблоками и лимоном намазать тонким слоем на большую влажную доску, разровнять с помощью широкого ножа, накрыть марлей, поставить в теплое помещение с хорошей вентиляцией на сутки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (729,'Выстлать противень пергаментом, переложить на него, подсушенной стороной вниз, пласт пастилы, убрать в духовку с температурой 110 градусов (прогреть заранее) на 3 часа, дверцу не закрывать плотно.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (730,'Заполнить чашу блендера повидлом, хорошо взбить, протереть через мелкое сито.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (739,'За полчаса до окончания бульон посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (730,'Добавить белки, еще раз взбить в однородную массу на низкой скорости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (730,'На противень постелить пекарскую бумагу, вылить массу из повидла, разровнять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (730,'Подсушить пастилу из повидла и яичных белков в уже прогретой до 120 градусов духовке по часу с каждой стороны, дверцу при готовке не закрывать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Просеять муку, всыпать соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Отдельно взбить венчиком яйца, влить массу в углубление в муке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Добавить любое растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Замесить тесто, время приготовления – от пяти до десяти минут. Должен получиться гладкий, однородный продукт.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Завернуть в пленку, оставить на полчаса или на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Говядину пропустить через мясорубку, очистить и измельчить репчатый лук и чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Бланшировать помидоры, снять шкурку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Лук обжарить до прозрачности на подсолнечном масле.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Добавить мясной фарш, жарить все вместе на тихом огне пять или шесть минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Помидоры измельчить, добавить в фарш. Овощи можно заменить томатной пастой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Начинку остудить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Приготовить соус: положить в кастрюлю сливочное масло, всыпать муку, перемешать до однородного состояния.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Влить молоко, продолжать помешивать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Всыпать остатки муки, влить еще немного молока. Соль – по вкусу.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Довести соус до кипения, огонь убавить.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Варить до сгущения.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'По желанию добавить тертый мускатный орех.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Перемешать, снять с огня.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Тесто разделить на четыре части.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Использовать одну, остальную массу оставить в пленке.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Раскатать тонкий пласт, он должен быть полупрозрачным.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Разрезать на прямоугольники.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'На противень вылить половину соуса «Бешамель». На прямоугольники выложить фарш, скрутить трубочки, выложить на противень швом вниз.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Так же поступить со всем приготовленным тестом и начинкой.',NULL,24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Выкладывать каннеллони рядами.',NULL,25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Залить второй половиной соуса, печь полчаса в духовке, температура приготовления – 180 градусов.',NULL,26);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (731,'Сыр «Пармезан» или аналогичный натереть, посыпать почти готовое блюдо, запекать еще десять минут.',NULL,27);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (732,'Все ингредиенты в сухом виде смешать. Размешать в кефире яйцо, налить масло. Добавить сухую смесь, осторожно размешать. Если размешивать сильно, то блины могут получиться резиновыми. Мука разойдется в любом случае.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (732,'Сковороду небольшого размера разогреть, смазать один раз маслом. В дальнейшем этого делать не надо. Выложить тесто, чтобы тесто получилось толщиной 50 миллиметров, выравнивая ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (732,'Накрыть крышкой и жарить на среднем огне. Когда тесто схватится, перевернуть пышные американские панкейки на кефире и жарить без крышки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'Капусту брокколи промыть, обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'Нарезать кубиками небольшого размера сельдерей и репчатый лук, натереть морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'Овощи обжарить на масле, тушить на тихом огне в течение десяти минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'Добавить говяжий фарш, посолить по вкусу, жарить пятнадцать минут на тихом огне. Снять с плиты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'На другую сковороду влить масло, положить один или два очищенных зубчика чеснока, потушить, затем извлечь и выбросить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'Выложить соцветия брокколи, тушить пять минут, снять с огня.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'В небольшую емкость с крышкой, влить воду, посолить, выложить соцветия капусты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'Варить десять минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'Слить воду, размять овощи вилкой, несколько соцветий оставить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'Добавить размятую капусту в фарш и перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'Сыр «Рикотта» выложить в миску, влить молоко, массу взбить при помощи венчика.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'Две ложки рикотты отделить, остальную массу перемешать с брокколи и фаршем.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'Форму для запекания смазать отложенной рикоттой.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (739,'Мясо вынуть, жидкость процедить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'Трубочки начинить фаршем, выложить заготовки рядами, оставить небольшие зазоры.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'Сверху – остатки рикотты, мясное рагу, отложенные соцветия брокколи.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'Духовку прогреть до 170 градусов, время запекания – полчаса.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (733,'На двадцать минут блюдо можно накрыть фольгой для лучшего пропекания.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (734,'Пропустить индюшатину и свинину через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (734,'Очистить и измельчить чеснок и лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (734,'Выставить режим «Жарка».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (734,'Влить в чашу немного подсолнечного масла, прогреть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (734,'Обжарить овощи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (734,'Добавить фарш, перемешать',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (734,'Соль, молотый перец, итальянские травы – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (734,'Нарезать томаты, лучше использовать черри.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (734,'Добавить в фарш, прогревать до готовности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (734,'Остудить в миске.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (734,'Начинку выложить в кондитерский мешок, наполнить трубочки сырые каннеллоне.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (734,'Чашу смазать сливочным маслом, выложить трубочки, залить, посолить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (734,'Выставить режим «Выпечка», температура – 110 градусов, время – полчаса.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (734,'Любой твердый сыр натереть, посыпать блюдо незадолго до конца приготовления.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (735,'С куриных бедер снимаем шкурку и вырезаем косточку (это совсем необязательный шаг, просто мне так нравится больше).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (735,'Смешиваем соль, черный молотый перец, молотую паприку и половину оливкового масла, натираем полученной смесью бедра и оставляем мариноваться на 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (735,'Капусту нарезам ломтями, толщиной 2-3 см.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (735,'Форму для запекания обильно смазываем сливочным маслом и выкладываем в нее плотно капусту.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (735,'Смазываем капусту смесью чеснока, прованских трав, соли и оливкового масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (735,'Сверху на капусту выкладываем маринованные бедра отправляем в разогретую духовку на 200 градусов примерно на 60-70 минут. Ориентируйтесь на свою духовку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (736,'Кабачок разрезаем пополам и ложкой вынимаем мякоть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (736,'Смазываем кабачки подсолнечным маслом, переворачиваем кожурой вверх и выпекаем 20 минут при 180 С. (Используйте конвекцию, так кабачки быстрее станут мягкими).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (736,'Тем временем на сковороде обжариваем лук, чеснок, фарш в течении 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (736,'Добавляем мякоть кабачком (предварительно мелко нарезав, я пользовалась блендером), мелко нарезанную петрушку, соль, перец по вкусу. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (736,'Заполняем кабачки начинкой и сверху выкладываем помидор, нарезанный дольками
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (736,'Достаём кабачки, посыпаем натёртым сыром и оставляем в духовке ещё на пару минут, пока сыр не расплавится.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (737,'При помощи тарелку обрезаем по кругу лаваш. Из 1 лаваш, у меня получилось 8 штук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (737,'Сыр нарезаем на ломтики, или же просто натираем на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (737,'Колбасу нарезаем на ломтики. или же произвольно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (737,'Помидор нарезаем так же на ломтики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (737,'На лаваш укладываем сыр, далее помидор, далее колбасу, и снова сыр и снова лаваш.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (737,'Отправляем в духовку при 180°С на 5-7 минут. Нужно чтобы сыр подплавлялся.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (737,'Достаем из духовку, даем немного остыть, и нарезаем на несколько частей. у меня получилось в сумме 8.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (738,'Грудинку нарезать небольшими кусочками, положить в кастрюлю, добавить воду, она должна покрыть мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (738,'Варить на сильном огне в течение пяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (738,'Порубить лук, кинзу, чеснок, добавить томатную пасту, растительное масло и хмели-сунели.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (738,'Прогревать на сильном огне две минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (738,'Добавить к мясу полученную смесь, тклапи, перец, чернослив, рис.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (738,'Долить воду, посолить по вкусу, варить суп десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (738,'Перед подачей посыпать харчо рубленой петрушкой и укропом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (739,'Сварить бульон из говяжьего мяса на косточке в большой кастрюле с крышкой. На приготовление отвара понадобится не менее двух часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (739,'Нарезать репчатый лук, обжарить его на растительном масле до прозрачности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (739,'Добавить на сковороду мясо, обжарить с луком в течение пяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (739,'Огонь уменьшить, налить в сковороду бульон, потушить еще 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (739,'Помидоры вымыть, надрезать кожицу крестом, залить кипящей водой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (739,'Через несколько минут воду слить, кожуру снять, мякоть нарезать и переложить на сковороду с мясом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (739,'Все вместе потушить еще десять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (739,'Поставить бульон на огонь, при закипании добавить обжарку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (739,'Довести до кипения, всыпать рис, огонь убавить, кипятить пять минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (739,'Всыпать специи.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (739,'В конце добавить мелко нарезанную зелень и толченый чеснок.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (739,'Блюдо должно постоять под крышкой примерно полчаса.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (740,'Картофель почистить. Взять столовую ложку, в нее положить картофель. Левой рукой придерживать картофелину, ножам резать ее до упора в ложку. Должны получиться надрезы. Ложка не позволяет разрезать картофель до конца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (740,'Положить картофель в формочку, полить растительным маслом, сверху посыпать различными приправами. Запекать невероятно вкусную картошечку при температуре 190 градусов до готовности. Время от времени поливать маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (741,'Смешайте муку, дрожжи, соль, сахар, растительное масло, воду (тёплую). Замесите тесто и оставьте в тепле на 30-40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (741,'Подготовим начинку. Куриное филе необходимо обвалять в муке (предварительно добавив в муку соль, перец и другие специи по вкусу), затем в яйце и панировочных сухарях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (741,'Обжариваем куриное филе на растительном масле до золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (741,'Раскатываем тесто в форме треугольника (как показано на видео). На широкую часть теста выкладываем натёртый сыр, затем нарезанное куриное филе и посыпаем оставшимся сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (741,'Заворачиваем тесто и выпекаем в духовке 25 минут при температуре 200 градусов (используйте конвекцию).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (742,'Курицу нарезать кусочками, выложить в кастрюлю, варить до полуготовности, жир снимать по мере всплывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (742,'Репчатый лук мелко нарезать, потушить в другой емкости с тем жиром, который был снят с куриного мяса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (742,'Добавить отваренную курицу, потушить под крышкой в течение 15 минут, периодически помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (742,'Влить в кастрюлю готовый куриный бульон, все вместе кипятить десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (742,'Добавить помидорное или сливовое пюре, муку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (742,'Кипятить пять минут, положить специи: корицу, гвоздику, толченые грецкие орехи с чесноком, стручковый, душистый, черный перец, хмели-сунели, имеретинский шафран, семена и нарезанную зелень кинзы, соль, лавровый лист.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (742,'Кипятить харчо десять минут, дать постоять.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (743,'Промыть говядину, нарезать кусочками, выложить в кастрюлю и залить холодной чистой водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (743,'Варить два часа на умеренном огне. Пенку снимать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (743,'Залить горячей водой тклали на два или три часа, чтобы сушеное сливовое пюре стало мягким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (743,'Переложить массу в бульон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (743,'Тклали можно заменить ткемали или соком граната.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (743,'Очистить репчатый лук, нарезать тонкими полукольцами. Выложить в бульон тогда, когда он вновь закипит.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (743,'Вымыть рис несколько раз, пока вода не станет прозрачной, всыпать в суп. Дать покипеть десять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (743,'Размять грецкие орехи вместе с нарезанным чесноком в ступке до появления масла.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (743,'Заправку добавить в суп.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (743,'При следующем закипании всыпать остальные специи: кориандр, лавровый лист, соль, шафран, хмели-сунели.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (743,'Перемешать, варить пять или семь минут при тихом кипении.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (743,'Нашинковать зелень, чеснок, добавить в суп в конце приготовления, огонь погасить, накрыть крышкой, дать постоять десять минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (744,'Баранью грудинку с косточкой нарезать на кусочки средней величины, выложить в толстостенный чугунный казан.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (744,'Залить холодной водой, варить два часа, пенку снимать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (744,'Через час бульон посолить и выложить нарезанный чернослив.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (744,'При готовности мяса положить в суп следующие продукты: тонко нарезанные полукольца репчатого лука, заранее промытый рис, кинзу, петрушку. Все вместе кипятить 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (744,'Дольки очищенного чеснока растереть с солью в ступке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (744,'Добавить измельченный зеленый перец, остатки рубленой петрушки и кинзы, все вместе растолочь в пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (744,'Положить очищенные и перетертые помидоры, молотые грецкие орехи, влить часть бульона, перемешать до однородности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (744,'Из казана вынуть веточки зелени, долить горячую пряную заправку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (744,'Перемешать, поперчить, попробовать на вкус, досолить, если нужно.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (744,'За десять минут до окончания приготовления лавровый лист, размягченный тклапи 10х10 см, нарезанную зелень петрушки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (745,'Сварить куриный бульон из порционных кусочков мяса, суповых корнеплодов, неочищенной луковицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (745,'Варить полтора часа после закипания, пену снимать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (745,'Приготовить заправку из нашинкованного репчатого лука, натертого корня петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (745,'Ингредиенты спассеровать на масле до золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (745,'Присыпать мукой и еще пожарить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (745,'Выложить из кастрюли почти готовые овощи и мясо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (745,'Бульон процедить через марлю или сито, а затем вместе с кусочками курицы вернуть в кастрюлю.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (745,'Соль – по вкусу, всыпать хорошо промытый рис.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (745,'Растереть в ступке перец и кориандр.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (745,'Через десять минут после закипания риса в суп положить обжарку, молотые грецкие орехи, специи, аджику и соус ткемали.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (745,'Влить бульон, варить до готовности риса.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (745,'Перед подачей положить в харчо протертый чеснок, заправить рубленым базиликом, сельдереем, кинзой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (746,'Курицу помыть, обсушить, натереть солью и перцем. В миске смешать половину растительного масла, горчицу, свежевыжатый сок лимона, паприку, соль, перец. Бедрышки положить в миску с маринадом и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (746,'Картофель очистить и порезать ломтиками. Если молодой и некрупный, то можно не очищать, нарезать на половинки или четвертушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (746,'Лук порезать. Чеснок помыть, но не очищать. В противне или форме для выпекания смешать картошку, лук и чеснок. Приправить по вкусу, полить оставшимся растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (746,'Выложить на овощи курицу, веточки розмарина и полить остатками маринада. Выпекать 30 минут в духовке при температуре 200°С.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (746,'Добавить порезанные помидоры черри и запекать еще 25 минут до готовности блюда. Достать из духовки и сразу подать к столу.','https://vkuso.ru/data/cache/data/d0/8e9e3f7def49ad0_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (747,'Мягкое сливочное масло (комнатной температуры) смешать с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (747,'Добавить сметану, растительное масло, яйцо, соль, муку, соду и замесить тесто. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (747,'Апельсин варить 4-7 минут (чтобы он не был горьким).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (747,'Апельсин нарезаем, добавляем крахмал, сахар и измельчаем погружным блендером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (747,'Полученную смесь варим 5 минут до загустения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (747,'Раскатываем тесто в форме прямоугольника (толщина теста около 0,5 мм). Смазываем апельсиновой начинкой и заворачиваем в рулет.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (747,'Нарезаем и выпекаем в духовке в течении 15-20 мин. при температуре 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (748,'Кладем сметану, добавляем сгущенку и хорошо перемешиваем, режем клубнику и выкладываем на лаваш добавляем крем, делаем такие слои со всем лавашом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (748,'Режем шоколадку и посыпаем ей получившийся торт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (748,'Отправляем в холодильник на 3 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (749,'Абрикосы разделить на половинки и каждую разрезать на 3 части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (749,'Приготовить тесто: размягченное масло взбить с сахаром и ванилином. Затем добавить яйца и еще раз взбить. Всыпать муку с солью и разрыхлителем. Вымешать тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (749,'В форму смазанную маслом выложить и разровнять тесто. Сверху разложить абрикосы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (749,'Выпекать при 180 градусах 30 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (749,'Остывший пирог посыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (750,'Взять формочку диаметром около 25 сантиметров, постелить на нее пергаментную бумагу для запекания или смазать ее маслом. Духовку разогреть до 180 градусов. Подготовить емкость побольше и поменьше. В маленькой смешать первые пять ингредиентов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (750,'В емкости побольше немного взбить яйца, добавить ванильный сахар и растительное масло. После этого добавить муку, молоко и так далее поочередно. Начинать и заканчивать нужно с муки. В конце влить стакан кипятка и быстро перемешать. Должно получиться жидкое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (750,'Перелить тесто в формочку, выпекать приблизительно 40 минут при температуре 180 градусов. Проверять необходимо при помощи зубочистки, она должна быть сухой или слегка влажной. При этом нужно следить, чтобы бисквит не пересушился. Тесто должно увеличиться в несколько раз. Время выпекания корректировать по духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (750,'Для крема: все ингредиенты смешать в кастрюле с толстым дном, варить на маленьком огне пять минут, непрерывно помешивая. Больше 5 минут варить не стоит – тесто будет густым. Желток не должен свернуться. В итоге получается густой крем. Разрезать бисквит на два коржа. Когда они остынут смазать их кремом, украсить бисквитный шоколадно-кокосовый торт шоколадной глазурью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (751,'Молоко переливаем в чистую кастрюлю и оставляем примерно на сутки при комнатной температуре.','https://vkuso.ru/data/cache/data/2f/ca620219f46042f_434x295_notrise.jpeg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (751,'Кислое молоко отправляем в холодную духовку, включаем температуру 120 градусов и оставляем примерно на 1,5 часа.','https://vkuso.ru/data/cache/data/fe/d7341e25e847ffe_434x295_notrise.jpeg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (751,'Оставляем при комнатной температуре до полного остывания.','https://vkuso.ru/data/cache/data/d2/4ecf5390f611ed2_434x295_notrise.jpeg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (751,'Творог остыл, переливаем в марлю, которой я предварительно застелила дуршлаг.','https://vkuso.ru/data/cache/data/f7/fb4bf938e64caf7_434x295_notrise.jpeg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (751,'Марлю завязываем в узел и подвешиваем. Творог готов если сыворотка перестала капать.','https://vkuso.ru/data/cache/data/79/17140b2a959ff79_434x295_notrise.jpeg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (752,'Говядину с хрящиками избавить от пленок, порезать кусочками, залить холодной водой, два часа варить под крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (752,'Вынуть готовое мясо, бульон процедить через сито, добавить в него рис и мясо, соль, дать покипеть в течение десяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (752,'Репчатый лук нарезать четвертинками, обжарить с добавлением муки, положить в бульон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (752,'Следующие ингредиенты – лавровый лист, корень петрушки, черный перец и кориандр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (752,'При полуготовности риса всыпать в суп орехи, размоченный тклапи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (752,'Добавить хмели-сунели, петрушку, шафран, измельченный перец чили.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (752,'Варить все вместе пять или шесть минут, несколько минут настаивать под крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (752,'Зелень кинзы или базилика, петрушки положить в тарелки вместе с толченым чесноком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (753,'Свинину с прослойками жира нарезать кусочками среднего размера, залить холодной водой, соль – по вкусу. Варить полчаса, пену снять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (753,'Промыть рис для удаления лишнего крахмала, очистить картофель, нарезать его брусками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (753,'Все продукты переложить в бульон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (753,'Измельчить репчатый лук, натереть морковь, жарить на сливочном или растительном масле до мягкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (753,'Грецкие орехи измельчить в ступке, при помощи блендера или ножом, перемешать с измельченным чесноком, соусом ткемали, хмели-сунели.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (753,'Заправку положить в суп при готовности мяса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (753,'Харчо вскипятить еще раз, снять с огня.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (753,'Всыпать рубленую зелень и дать постоять полчаса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (754,'Нарезать молодую телятину поперек волокон, репчатый лук – четвертинками колец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (754,'Очистить острый перец от семян, нарезать тонкими колечками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (754,'Натереть на терке корневище петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (754,'Потолочь чеснок, перец и орехи в ступке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (754,'Выставить в мультиварке режим выпекания, спассеровать корень петрушки и лук в течение шести или семи минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (754,'Добавить мясо, жарить десять минут, помешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (754,'Развести муку водой, добавить в обжарку, тушить одну минуту.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (768,'Нарезать пластинками по сантиметру, немного отбить с обеих сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (754,'Налить в чашу сок граната и воду, добавить орехи и протертые помидоры без кожицы, травы, лавровый лист, соль.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (754,'Закрыть мультиварку, готовить суп в режиме тушения в течение полутора часов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (754,'В ступке перетереть кинзу с чесноком, добавить в готовый суп, дать постоять.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (755,'Репчатый лук очистить и нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (755,'Потушить в кастрюле на сливочном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (755,'Размять в ступке зубчики чеснока, порубить ножом острый перец без семян, нашинковать зелень кинзы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (755,'Грецкие орехи измельчить ножом в крошку, соединить все ингредиенты и переложить в кастрюлю к обжаренному луку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (755,'Влить кипящую воду, всыпать тщательно промытый рис.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (755,'Посолить, варить до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (755,'Ошпарить томаты, снять кожицу, мякоть измельчить, тушить в сотейнике в течение пяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (755,'Добавить хмели-сунели и соус ткемали.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (755,'Перемешать, газ выключить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (755,'Переложить в суп оба соуса, все вместе поварить пять минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (755,'В готовый суп положить много рубленой зелени, дать постоять.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (756,'Делаем начинку: творог, зелень, чеснок, яйцо 2 штуки перемешиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (756,'На сковородку выливаем растопленное масло, затем яйцо сверху кладем лаваш потом слой начинки, закрываем лавашом и делаем таких 5-6 слоев.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (756,'Сверху заливаем яйцом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (756,'Обжариваем на сковородке по 5 минут с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'Вымыть мясо, залить холодной водой и поставить на огонь. Пену снимать по мере появления.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'Когда пена перестанет появляться – положить в бульон луковицу с неснятой кожурой, перец-горошек, морковь, лавровый лист, сушеные травы, корни петрушки и сельдерея, бадьян, соль, веточки зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'Убавить температуру кипения до минимальной величины, томить суп под крышкой не менее трех часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'Нарезать или пропустить через пресс чеснок, нашинковать лук кубиками среднего размера, ошпарить и очистить помидоры, измельчить мякоть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'Порубить и перетереть в ступке острый перец и чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'Рис промыть несколько раз, замочить в свежей воде на 30 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'Потолочь зиру, кориандр, ароматные перцы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'Прогреть на огне казан, положить топленое коровье масло, всыпать лук, прогреть до прозрачности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'Добавить жир, собранный с бульона, немного самого отвара. Потушить пять или семь минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'Всыпать помидоры, положить мясо из бульона, прогреть все вместе пять минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'Добавить перетертые пряности, потомить десять минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'Влить в казан заранее процеженный бульон, насыпать рис.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'Томить харчо в течение 20 минут на слабом огне.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'В конце положить смесь чеснока и зелени.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (757,'Погасить огонь, дать супу постоять, подать к столу.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (758,'В глубокую посуду налить подогретую воду, всыпать соль, сахар, влить подсолнечное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (758,'Муку просеять, добавить сухие дрожжи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (758,'Замесить мягкое тесто, сформовать шар, оставить на час в тепле под льняной тканью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (758,'Приготовить любую начинку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (758,'Раскатать массу в тонкий пласт, выложить на противень, разложить начинку, выпечь в духовом шкафу до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (759,'Нагреть сковороду. Одну сторону всех кусочков хлеба смазать маслом. Один ломтик хлеба положить на сковороду вниз маслом. Посыпать сыром и положить  сверху второй кусок хлеба маслом вверх.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (759,'Сделать огонь тише, готовить сырный сэндвич на сковороде приблизительно 3 минуты до коричневатого цвета. Перевернуть и обжаривать столько же с другой стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (760,'Налить в емкость подогретую кипяченую воду, растворить в ней натуральный мед и дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (760,'Всыпать заранее просеянную муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (760,'Добавить растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (760,'Положить немного чесночного или лукового порошка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (760,'Ингредиенты перемешать, масса должна быть эластичной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (760,'Дать постоять в тепле, сформовать пироги, выложить начинку и выпечь до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (761,'В миску насыпать соль и муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (761,'Отдельно перемешать подсолнечное масло с сырыми куриными яйцами и водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (761,'Смесь взбить при помощи блендера или венчика.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (761,'Жидкую смесь порциями влить в муку, помешивать, в тесте не должно быть комков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (761,'Месить до тех пор, пока масса не перестанет прилипать к рукам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (761,'Блюда смазать маслом, переложить в него колобки из теста, накрыть, дать постоять полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (761,'Раскатать, разложить начинку и выпечь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (762,'Яйца с солью взбить при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (762,'Отдельно перемешать густую сметану с содой, влить яичную смесь и еще раз хорошо взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (762,'Растопить сливочное масло, влить в основную массу, добавить просеянную муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (762,'Тесто замесить быстро, до эластичного состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (762,'Присыпать мукой, раскатать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (762,'Если масса получилась мягкой – тесто можно раскатать прямо на смазанном маслом противне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (762,'Выпекать, как обычно.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (763,'Насыпать на рабочую поверхность горкой просеянную пшеничную муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (763,'Сделать углубление, всыпать соль, разведенные дрожжи, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (763,'Добавить теплую воду и нарезанное кусочками сливочное масло или маргарин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (763,'Поставить в тепло на два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (763,'Раскатать, выложить начинку, выпечь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (764,'Просеять муку на деревянную поверхность, в углубление вбить сырое яйцо, перемешать, доливая подогретую воду. В массе не должно быть комков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (764,'Добавить сахарный песок, мягкое сливочное и растительное масло, французские гранулированные дрожжи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (764,'В результате должна получиться не густое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (764,'Переложить его в эмалированную посуду, присыпанную мукой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (764,'Сверху тесто также посыпать мукой, накрыть тканью и поставить в тепло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (764,'Как только тесто подойдет – добавить муку, вымесить до состояния, когда масса перестанет прилипать к рукам.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (764,'Выпечь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (765,'Муку просеять в емкость, в углубление накрошить дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (765,'Добавить муку и немного теплой воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (765,'Закваску посыпать мукой, накрыть и оставить до тех пор, пока смесь не начнет пузыриться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (765,'Скатать два шара, сверху сделать надрезы крестом, накрыть салфеткой, поставить на час в теплое место.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (765,'Затем раскатать, выложить начинку и испечь пироги.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (766,'Противень смазать растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (766,'Очистить головки репчатого лука, нарезать кольцами, выложить на противень первым слоем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (766,'Нарезать свинину пластинками, отбить молотком с двух сторон, присыпать  специями и выложить поверх лука ровным слоем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (766,'Очистить клубни картофеля, вымыть, нарезать соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (766,'Смешать с молотым перцем, солью, выложить поверх мяса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (766,'Перемешать сметану с майонезом и развести водой. Полученный соус вылить поверх мяса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (766,'Натереть сыр, посыпать блюдо, накрыть фольгой и поставить его в духовой шкаф, температура приготовления – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (766,'При готовности картошки фольгу снять, блюдо допечь до аппетитной корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (767,'Смазать противень маслом, выложить нарезанный полукольцами репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (767,'Сверху положить посоленные и поперченные отбивные.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (767,'Нарезать кружками помидоры и выложить их третьим слоем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (767,'Нарезать кружками заранее отваренный почти до готовности картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (767,'Блюдо посолить и поперчить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (767,'Прогреть сливочное масло на сковороде, всыпать муку, смесь обжарить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (767,'Ввести сметану, перемешать, чтобы не было комков.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (767,'Влить воду, ввести специи.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (767,'Готовым соусом залить блюдо, присыпать тертым сыром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (767,'Запекать в течение сорока минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (768,'Свинину хорошо промыть, пленки удалить, жир оставить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (768,'Посолить и поперчить по вкусу, переложить в миску и дать пропитаться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (768,'Нарезать пластинками свежие грибы, обжарить в течение десяти минут на сковороде с растительным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (768,'Добавить специи, сметану, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (768,'Лук очистить, нарезать полукольцами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (768,'Противень смазать маслом, выложить две трети нарезанного лука.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (768,'Сверху – мясо, оставшийся лук, грибы со сметаной.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (768,'Посыпать крупно натертым сыром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (768,'Печь в духовом шкафу до готовности при температуре 190 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (769,'Растопить в сотейнике сливочное масло, обжарить муку до изменения цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (769,'Добавить молоко, вливать его нужно тонкой струйкой и сразу размешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (769,'Соус проварить до загустения, огонь выключить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (769,'Отварить картофель почти до готовности, остудить, очистить, нарезать тонкими пластинками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (769,'Репчатый лук нашинковать полукольцами, выложить на противень с растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (769,'Свиные отбивные присыпать специями, выложить на луковую подушку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (769,'Поверх – кружки картофеля, полить соусом «Бешамель».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (769,'Посыпать тертым сыром, запечь в духовке при температуре 200 градусов, время приготовления – около сорока минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (770,'Нарезать мясо тонкими пластинами, отбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (770,'В соевый соус положить сметану, кетчуп, молотый перец, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (770,'Смесь перемешать и натереть ею телятину.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (770,'Сложить кусочки в миску, полить оставшимся соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (770,'Оставить для пропитывания час или дольше.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (770,'Лук нарезать кольцами, положить на заранее смазанный маслом противень, сверху – мясо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (770,'Третий слой – картофельный, клубни нарезать соломкой, посолить, смешать со сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (770,'Посыпать блюдо тертым сыром, «Голландским» или аналогичным.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (770,'Поставить противень в духовой шкаф на 50 минут, накрыть фольгой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (770,'Через полчаса фольгу снять.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (770,'В конце приготовления можно немного добавить температуру.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (771,'Отварить в подсоленной воде картофель, морковь и яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (771,'Очистить, нарезать маленькими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (771,'Отваренной моркови должно быть в два раза меньше картофеля, нарезать ее и соленый огурец такими же кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (771,'Накрошить на выбор вареную колбасу, говядину или курицу, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (771,'Всыпать зеленый горошек из банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (771,'Заправить майонезом, посолить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (772,'Порезать лук кубиками. Одну луковицу ошпарить кипятком и отложить на 15 минут, вторую обжарить с порезанными грибами. Порезать курицу на небольшие кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (772,'Выложить салат на плоскую тарелку слоями: картофель тертый с половиной ошпаренного лука, майонез, куриное мясо со второй половиной ошпаренного лука, обжаренные грибы с луком, снова соус, сыр тертый, майонез, морковь тертая, майонез, желтки измельченные, майонез, белки измельченные.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (772,'По краям украсить зеленью рубленной, зеленым луком и цветами из вареной моркови. Салат «Весенний день» с курицей и грибами готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (773,'В миску отправляем 250 гр мягкого творога.','https://vkuso.ru/data/cache/data/a1/7c21563ce4d27a1_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (773,'1 куриное яйцо.','https://vkuso.ru/data/cache/data/78/9b2ea39d0479578_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (773,'10 гр ванильного сахара.','https://vkuso.ru/data/cache/data/c5/6a8c4e4e0aca8c5_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (773,'80 гр рисовой муки.','https://vkuso.ru/data/cache/data/9c/ba19f463a2a539c_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (773,'2 чайных ложки сахара.','https://vkuso.ru/data/cache/data/05/834d12600ab4205_434x295_notrise.png',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (773,'Тщательно перемешиваем.','https://vkuso.ru/data/cache/data/13/ea79cf2e4844813_434x295_notrise.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (773,'Выкладываем тесто в формы для кексов.','https://vkuso.ru/data/cache/data/a5/79bae9d3dd2cba5_434x295_notrise.png',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (773,'Посыпаем кунжутом. Выпекаем при температуре 180 градусов 20-30 минут.','https://vkuso.ru/data/cache/data/29/14e72ae020f7d29_434x295_notrise.png',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (773,'Творожные кексы готовы! Приятного аппетита!','https://vkuso.ru/data/cache/data/e5/49716b87ff7a7e5_434x295_notrise.png',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (774,'Яйца разделить на белки и желтки. Белки отправить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (774,'Желтки, творог и сахар (без 1 ст. л.) взбить блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (774,'Добавить молоко и муку, замешать тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (774,'Охлажденные белки взбить с щепоткой соли в пышную массу и добавить к тесту, аккуратно их вмешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (774,'Абрикосы порезать и добавить к ним оставшуюся столовую ложку сахара.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (774,'Сковороду смазываем растительным маслом и хорошо нагреваем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (774,'На разогретую сковороду вылить 1/3 часть теста и через несколько секунд на одну половину выложить 1/3 часть абрикосов. Как только тесто снизу схватится, осторожно завернуть на абрикосы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (774,'Обжариваем еще минуту на другой стороне.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (775,'Смешайте свиной и куриный фарш, рис (отварной), мелко нарезанный лук, измельчённый чеснок, яйцо, соль, перец, петрушку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (775,'Сформируйте небольшие шарики и выложите на противень предварительно смазав растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (775,'Выпекайте 20 минут при температуре 180-200°С.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (775,'Достаём фрикадельки, поливаем сливками и посыпаем натёртым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (775,'Выпекаем ещё 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (776,'Колбасу и свежие огурцы нарезаем тоненькой соломкой для красоты салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (776,'Отварные куриные яйца чистим и нарезаем небольшими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (776,'Плавленный сырок я натираю на крупной терке, при желание его можно просто мелко нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (776,'Зелень выбирайте по своему вкусу и мелко ее нашинкуем. Я взяла укроп и зеленый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (776,'Смешиваем все подготовленные продукты в миске и добавляем консервированную кукурузу без жидкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (776,'Заправим наш салатик майонезом и посолив по своему вкусу все перемешаем. Салат готов и можно его подавать на стол гостям.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (777,'Отварить картофель, морковь, яйца, нарезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (777,'Отварить и покрошить куриное мясо, свежие и соленые огурцы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (777,'Все ингредиенты перемешать, посолить по вкусу и заправить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (778,'Отварить нежирное филе в подсоленной воде, нарезать кубиками поперек волокон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (778,'Отварить морковь, картофель, куриные яйца, также нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (778,'Нашинковать репчатый и зеленый лук, свежие помидоры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (778,'Слить жидкость из банки с зеленым горошком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (778,'Заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (778,'Ингредиенты можно перемешать или выложить слоями.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (778,'Во втором случае порядок слоев должен быть такой: говядина, лук репчатый, картофель, отваренная морковь, горошек, яйца, зеленый лук, сверху – помидоры.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (778,'Украсить блюдо веточками зелени.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (779,'Нарезать зеленый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (779,'Отварить свиную вырезку, морковь, яйца, картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (779,'Нарезать кубиками вместе с соленым и свежим огурцом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (779,'Все ингредиенты хорошо перемешать, добавить кукурузу из банки, заправить майонезом по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (779,'Поперчить, украсить зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (780,'Отварить картофель и морковь, куриное мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (780,'Ингредиенты нарезать кубиками вместе с соленым огурцом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (780,'Отцедить зеленый горошек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (780,'Белые грибы промыть, нарезать ломтиками и обжарить до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (780,'Все составляющие перемешать, заправить майонезом, в который подмешан тертый хрен.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (780,'Перемешать, украсить веточками укропа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (781,'Отварить морковь, яйца, картофель, охладить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (781,'Измельчить свежие и соленые огурцы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (781,'Отварить креветки, отцедить зеленый горошек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (781,'Ингредиенты перемешать, заправить по вкусу майонезом, украсить веточками укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (782,'Разделить куриные ножки на несколько частей, убрать кости и кожу, со всех сторон посыпать солью и перцем. Нагреть сковороду с растительным и сливочным маслом. Положить на раскаленное масло мясо и обжаривать по несколько минут с каждой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (789,'В тарелку выложить рукколу, полить заправкой. Выложить персик, авокадо, чечевицу и креветки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10007,'Репчатый лук измельчить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (782,'Когда мясо подрумянится, накрыть крышкой, сделать тише огонь и готовить еще приблизительно 10 минут. Когда из мяса начнет выделяться прозрачный сок, переложить его в емкость и накрыть, чтобы сохранить тепло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (782,'Вымыть шампиньоны, порезать на тонкие пластинки. Мелко нарезать лук. Обжарить на сковороде грибы с луком. Добавить к обжаренным шампиньонам с луком муку и жарить минуту. Налить воду и довести до кипения, постоянно помешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (782,'Соус варить на протяжении 3 минут, после этого налить сливки. Снова положить на сковороду мясо курицы с соком, который скопился на тарелке. Жарить куриные ножки в грибном соусе еще несколько минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (783,'Отварить и очистить картофель, яйца и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (783,'Красную рыбу нарезать соломкой, зеленый лук нашинковать, свежий огурец покрошить кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (783,'Добавить отцеженный зеленый горошек, заправить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (783,'Соль может не понадобиться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (784,'Для начала возьмем два ломтика хлеба и сделаем по середине отверстие ножом.','https://vkuso.ru/data/cache/data/6a/98aaccf20f4ad6a_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (784,'Вливаем растительное масло в сковороду и прогреваем, выкладываем хлеб и поджариваем до золотистого цвета с одной стороны около 1 минуты. В дырочку обжаренного хлеба вбиваем яйцо, солим и перчим.','https://vkuso.ru/data/cache/data/d6/4f5249e9d88ead6_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (784,'Через две минуты переворачиваем хлеб на другую сторону и жарим еще пару минут, посыпаем чесноком и зеленью. Яичница готова, приятного аппетита!','https://vkuso.ru/data/cache/data/5d/300c2d991c8d95d_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (785,'Сначала делаем зажарку: нарезаем лук, морковь натираем на тёрке и обжариваем 5 минут на сковороде.','https://vkuso.ru/data/cache/data/a7/d58316e055999a7_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (785,'Затем в заранее приготовленный бульон бросаем нарезанную кубиками картошку. После того как будет готов картофель, добавляем зажарку и сыр, после чего варим ещё 5-7 мин, помешивая до полного растворения сыра.','https://vkuso.ru/data/cache/data/63/9f409139c26aa63_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (785,'В конце взбиваем погружным блендером. Подавать с сухарями и зеленью. Приятного аппетита!','https://vkuso.ru/data/cache/data/86/03c5bc91f98b886_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (786,'Камбала на углях. Добавляем в сливочное масло чеснок, острый перец и укроп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (786,'Маринад. Смешиваем соль, черный молотый перец, копченую паприку и растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (786,'Чистим, потрошим, моем камбалу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (786,'Натираем маринадом и жарим на углях по 7 минут с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (786,'Смазываем маслом с чесноком, острым перцем и укропом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (786,'Жарим ещё на углях пару минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (786,'Кукуруза на углях. Добавляем в сливочное масло чеснок и соль.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (786,'Смазываем кукурузу маслом и заворачиваем в фольгу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (786,'Жарим на углях 20 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (786,'Натираем сыр и делим на две части.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (786,'В одну добавляем мелко нарезанный укроп, а во вторую копченую паприку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (786,'Посыпаем сыром кукурузу.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (787,'Кабачки очистить от кожуры, натереть на мелкой терке и отжать сок.В глубокой миске смешать все ингредиенты для брауни.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (787,'Выпекать в смазанной маслом форме при 180 градусах 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (787,'Готовый брауни залить смесью из арахисовой пасты и молока и украсить натертым шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (788,'Начинка. Натираем плавленый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (788,'Нарезаем сладкий перец .',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (788,'Маринад. Смешиваем соль,черный молотый перец, сушёный базилик, копченую паприку и растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (788,'Чистим, потрошим, моем сома. Наполняем брюшко начинкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (788,'Делаем надрезы по бокам сома и вставляем лимон и помидор.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (788,'Смазываем маринадом и жарим на углях по 7-10 минут с каждой стороны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (789,'В сотейник налить воды и засыпать чечевицу. Варим до полного выкипания воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (789,'Креветки разморозить, если не разморозите придется варить больше. В кастрюлю налить воды, довести до кипения. В кипящую воду засыпать креветки, соль, варить 3 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (789,'Персики и авокадо очистить от косточки и нарезать тонкими слайсами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (789,'Готовим заправку. Выдавить сок половины лайма смешать с оливковым маслом, майораном и горчицей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (790,'Готовим тесто. Сливочное масло комнатной температуры соединить с сахаром и взбить венчиком. Влить растительное масло и вбить яйца, снова сбить при помощи венчика. Влить кефир, добавить разрыхлитель, соль, корицу и муки, перемешать до однородности при помощи венчика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (790,'Форму для выпечки застелить пекарской бумагой и смазать сливочным маслом, выложить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (790,'Для начинки очистить вишню от косточек, выложить на тесто. Шоколад натереть на мелкой терке, посыпать вишню шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (790,'Готовим штрейзель. Сливочное масло комнатной температуры смешать с сахаром и мукой, перетереть в крошку. Этой крошкой посыпать пирог. Отправляем пирог с разогретую духовку до 180 градусов на 50 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (791,'Кабачки нарезать наискось толщиной около 0,5 см, посолить и поперчить, добавить растительное масло (1 ст. л.). Оставить на 15 минут, чтобы кабачки пустили сок. Затем Смазать сковороду гриль растительным маслом (1 ст. л.) и обжарить кабачки на сильном огне с двух сторон до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (791,'Болгарский перец очистить от семян. Болгарский перец и помидор нарезать мелким кубиком. Репчатый лук нарезать тонкими кубиками. Сложить все в тарелку, полить бальзамическим уксусом, добавить паприку и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (791,'Ножом мелко нарубить укроп и базилик.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (791,'На дольку обжаренного кабачка намазать сыр фета, посыпать укропом и базиликом, сверху выложить овощную начинку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (792,'Взбиваем 2 яйца выливаем их на сковороду с растопленным маслом, кладем 2 ломтика хлеба, обжариваем с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (792,'На один ломтик кладем помидорку и сыр сверху закрываем 2-м ломтиком! Приятного аппетита!','https://vkuso.ru/data/cache/data/db/6a3ed2175dc6edb_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (793,'Примерно треть абрикосов (более плотных) отложить, а остальные плоды измельчить в пюре при помощи мясорубки или кухонного комбайна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (793,'Выложить пюре в кастрюлю. Поставить на умеренный огонь и варить 15-20 минут, время от времени помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (793,'Остальные абрикосы очень мелко порезать. Когда пюре немного загустеет, всыпать сахар и перемешать до растворения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (793,'Добавить порезанные абрикосы и варить на умеренном огне 10 минут, снимая пену. Разложить джем по стерилизованным банкам, закрыть крышками, укутать пледом и оставить до полного остывания.','https://vkuso.ru/data/cache/data/33/6f3de009f3c3c33_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (794,'Развести крахмал в воде, мелко порезать бамбуковые побеги, немного размочить в воде креветки. Смешать фарш с луком, кориандром, имбирем, сливками, корицей, водой, соевым соусом, измельченной зеленью, крахмалом, креветками, острым перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (794,'Из смеси сделать маленькие шарики, обвалять в крахмале, жарить со всех сторон на сковороде. Выложить в емкости листья салата, положить шарики из мясного фарша с пряностями чха-ван-тси.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (795,'Отрываем листики, и маленькие веточки мяты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (795,'Промываем под водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (795,'Обсушиваем бумажным полотенцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (795,'Далее, перекладываем листики, и веточки мяты в ёмкость блендера, добавляем сахар, и измельчаем до однородной массы.
(Большие веточки мяты, или выкидываем или засушиваем)',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (795,'Перекладываем в маленькую баночку и закрываем крошкой. Убираем в холодильник. Спустя время, мятный сахар может потемнеть, но это не страшно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (796,'Положить в блендер масло, порезанное кубиками, добавить смесь просеянной подсоленной муки с какао, разбить до образования маслянистой крошки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (796,'Всыпать сахар, вбить яйцо, влить частями воду, вымесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (796,'Завернуть его в пленку, убрать на 40 минут в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (796,'Достать, раскатать (с небольшим запасом для формирования бортиков) по размеру формы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (796,'Заполнить тестом форму, прикрыть пленкой, убрать в холодильник на четверть часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (796,'Из взбитого в блендере творога и сахара, с добавлением ванильного сахара, яиц и, в конце, крахмала приготовить начинку (перемешивать все руками).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (796,'Для присыпки просеять муку, какао, положить небольшие кусочки масла и сахар, перетереть все в крошку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (822,'Вымыть шампиньоны, добавить в обжарку, прогреть все вместе, перец и соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (796,'Достать из холодильника форму, снять пленку, заполнить начинкой, присыпать верх творожно-ванильного пирога на шоколадном тесте шоколадной крошкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (796,'Убрать форму в уже прогретую до 180 градусов духовку, готовить 50 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (796,'Чуть приоткрыть духовку, дать постоять пару часов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (796,'Достать, дать хорошо остыть, подать к столу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (797,'Почистить кабачок, молодой можно оставить со шкуркой, натереть на крупной терке, отжать массу от лишнего сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (797,'Измельчить зелень, красный сладкий перец порезать на кубики, добавить к кабачкам, вбить яйцо, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (797,'Чеснок раздавить прессом, добавить к массе, всыпать муку и специи, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (797,'Обжарить диетические оладьи из кабачков и болгарского перца с обеих сторон до слегка коричневой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (798,'Напечь тонких блинов по любому рецепту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (798,'Перетереть творог с сахаром, вбить яйцо, добавить ванильный сахар, измельченную курагу, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (798,'Смазать каждый блин начинкой из творога, свернуть в трубочку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (798,'Промазать форму маслом, уложить по спирали блины, залить блинный пирог с творогом и курагой в духовке взбитой с яйцом и сахаром сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (798,'Выпекать пирог 30-35 минут в духовке (предварительно разогреть) при температуре 190 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (799,'Мелко нашинковать чеснок, обжарить в масле около минуты, добавить пасту, перемешать, прогреть еще минуту, всыпать рис.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (799,'Помешивая постепенно влить бульон, после впитывания жидкости добавить еще пару половников, варить полчаса при помешивании.','https:https://st.vkuso.ru/data/cache/thumb/94/723fe7dc69d9494_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (799,'Убрать с плиты, положить сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (799,'Содержимое сковороды выложить в миску, дать остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (799,'Порезать баклажан на тонкие полосы, присолить, сложить в дуршлаг, опустить в воду, оставить на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (799,'Достать из воды, обсушить полоски бумажным полотенцем, побрызгать их маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (799,'Обжарить на гриле.','https:https://st.vkuso.ru/data/cache/thumb/f1/09331270bd41af1_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (799,'Налить на дно формы несколько ложек соуса маринара.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (799,'Скрутить из баклажана рулетики, середину заполнить рисовой начинкой.','https:https://st.vkuso.ru/data/cache/thumb/cc/e78168e67d64fcc_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (799,'Уложить баклажанные рулетики на гриле с ризотто в форму, полить верх соусом.','https:https://st.vkuso.ru/data/cache/thumb/d1/c67a1ed38d7edd1_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (799,'Выпекать блюдо под крышкой треть часа при температуре 175 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (799,'Открыть форму, готовить еще 10 минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (800,'Растереть масло с сахаром, вбить яйца, добавить сметану с содой, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (800,'Всыпать небольшими порциями всю муку, вымесить мягкое тесто, убрать в холодильник на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (800,'Колобок теста разделить на 12-15 шариков, раскатать каждый, прямо на бумаге для выпечки в тонкий пласт, наколоть несколько раз вилкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (800,'Выпекать примерно по 4 минуты (передерживать не надо, иначе коржи сильно подсохнут) до чуть видного зарумянивания в духовке с температурой 190 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (800,'Пока коржи еще не остыли обрезать их по шаблону.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (800,'Приготовить из взбитой вареной сгущенки и сметаны крем средней степени густоты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (800,'Промазать коржи армянского торта «Микадо» со сметанным кремом, сложить в стопку, верх можно присыпать измельченной крошкой из обрезков.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (800,'Дать постоять 3 часа, убрать на сутки в холодильник, чтобы коржи пропитались равномерно кремом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (801,'Мягкое сливочное масло смешайте с сахаром до однородной консистенции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (801,'Добавьте 2 яйца и перемешайте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (801,'Добавьте разрыхлитель, муку и ещё раз перемешайте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (801,'Возьмите банан и измельчите (я использовала блендер).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (801,'Влейте в тесто молоко, перемешайте.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (801,'Молочный шоколад измельчите используя нож или натрите на мелкой тёрке. Добавьте в готовое тесто и перемешайте.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (801,'Выложите тесто в форму (предварительно смазав маслом).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (801,'Приготовим сахарную глазурь. Для этого в миске необходимо смешать сахарную пудру, лимонный сок и белок (при взбивании используйте миксер). По желанию можно добавить жёлтый краситель.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (801,'Готовый кекс смазываем получившейся глазурью и украшаем по желанию бананом и шоколадом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (802,'В глубокой миске смешать венчиком яйца, подсоленное молоко, сахар, всыпать небольшими порциями всю муку, перемешать до получения теста похожего на жидкую сметану.','https:https://st.vkuso.ru/data/cache/thumb/3c/180b47ffb66003c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (802,'Влить растопленное масло, перемешать, пожарить блины.','https:https://st.vkuso.ru/data/cache/thumb/da/921a9ac35d8b5da_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (802,'Бланшировать молодую крапиву 2 минуты.','https:https://st.vkuso.ru/data/cache/thumb/6d/03d8887e188c16d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (802,'Переложить на полотенце из бумаги.','https:https://st.vkuso.ru/data/cache/thumb/00/e7ac47ce7cf8900_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (802,'Размять брынзу в крошку с помощью вилки.','https:https://st.vkuso.ru/data/cache/thumb/fc/68fe149078e67fc_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (802,'Разложить на блинчик крапивные листики, присыпать крошкой брынзы.','https:https://st.vkuso.ru/data/cache/thumb/c9/d4bccd958ee4ac9_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (802,'Свернуть в рулет, поступить так со всеми блинчиками.','https:https://st.vkuso.ru/data/cache/thumb/25/d03bae452254125_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (802,'Уложить в смазанную форму рулетики в два слоя, прикрыть колечками помидора.','https:https://st.vkuso.ru/data/cache/thumb/99/586309a625b8399_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (802,'Приготовить из перемешанной сметаны с яйцами, молоком, тертым сыром, нашинкованным укропом заливку.','https:https://st.vkuso.ru/data/cache/thumb/29/dde816fc125c829_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (802,'Вылить в форму на блины.','https:https://st.vkuso.ru/data/cache/thumb/a0/d1a7bd389916ea0_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (802,'Готовить блинную запеканку с крапивой и брынзой в прогретой заранее до 200 градусов духовке полчаса.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (802,'Достать, дать чуть остыть, подать со сметаной.','https:https://st.vkuso.ru/data/cache/thumb/7f/aa9ccad3fa42e7f_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (803,'Взять желатин и развести его в небольшом количестве сока и нагреть, чтобы растворились кристаллики желатина, только не кипятить. Добавить горячий желатин к остальному соку и налить в стаканчики. Поставить их в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (803,'Развести желатин в небольшом количестве сока и готовить так же. Приготовленный желатин смешать с любым йогуртом, выложить его на желейный сок, который должен уже застыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (803,'После застывания желе, положить сверху взбитые сливки и полить шоколадом, предварительно разбавленным на водяной бане.  Поставить в холодильник. Через 15 минут десерт «Желейная фантазия» с взбитыми сливками будет готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (804,'Подготовить грудки, промыть, промокнуть бумажным многослойным полотенцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (804,'Для маринада перемешать оливковое масло с лимонным соком, паприкой, раздавленным чесноком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (804,'Залить маринадом грудки на 15 минут, очистить груши порезать на дольки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (804,'Маринованные грудки начинить дольками груши, обернуть полосками бекона.','https:https://st.vkuso.ru/data/cache/thumb/bd/ff126cd3034bcbd_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (804,'Обжарить маринованные куриные грудки с грушей в беконе на сильном огне до коричневой корочки на беконе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (804,'Влить в сковороду вино, положить розмарин, нагрев уменьшить, тушить 10 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (805,'Включить для прогрева до 175 градусов духовку, формочки выстлать пергаментом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (805,'Перемешать сахар, муку, соду, соль, какао, разрыхлитель.','https:https://st.vkuso.ru/data/cache/thumb/42/f42f0d8870ea242_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (805,'Взбить кислое молоко с яйцами и небольшим количеством теплой воды, маслом, ванилью в однородную массу.','https:https://st.vkuso.ru/data/cache/thumb/31/6cb332ac55a6431_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (805,'Заполнить тестом на 2/3 формочки.','https:https://st.vkuso.ru/data/cache/thumb/b5/47e2fb82eb6a1b5_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (805,'Выпекать шоколадные капкейки с начинкой на кислом молоке 25 минут, дать остыть.','https:https://st.vkuso.ru/data/cache/thumb/be/d83e657348b42be_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (805,'Растопить шоколад на водяной бане, добавить сливки, перемешать, дать остыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (805,'Сделать в капкейках зубочисткой отверстия, заполнить из кондитерского мешка начинкой.','https:https://st.vkuso.ru/data/cache/thumb/b1/0390209846f0fb1_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (805,'Верх покрыть глазурью.','https:https://st.vkuso.ru/data/cache/thumb/a9/798e77cf08409a9_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (806,'В сотейнике с толстым дном нагреть практически до кипения молоко, всыпать поломанный на небольшие кусочки шоколад, перемешивая дать ему растопиться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (822,'Положить начинку на подготовленное филе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (806,'Желтки и 130 г сахара взбить в густой крем миксером, постепенно небольшими порциями влить молоко, продолжая взбивать, всыпать в конце какао и окончательно взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (806,'Поставить глубокую миску с джелато на водяную баню, прогреть, постоянно мешая, до 80 градусов, убрать с плиты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (806,'Нагреть до состояния темной карамели по 2 ст. л. сахара и воды, перемешивать покачиванием, а не лопаточкой или ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (806,'Вылить карамель в джелато, тщательно перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (806,'Когда шоколадное джелато с карамелью станет холодным, убрать в холодильник до застывания, а потом в морозилку на несколько часов (несколько раз перемешать).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (807,'Взбить полстакана сахара и пару яиц, влить сметану, растопленное масло.','https:https://st.vkuso.ru/data/cache/thumb/05/4ee7160da181805_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (807,'Добавить муку с содой, хорошо перемешать, тесто должно походить на густую сметану.','https:https://st.vkuso.ru/data/cache/thumb/5b/0cb846a3c11795b_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (807,'Для начинки манку, творог, полстакана сахара смешать с 3-мя яйцами в однородную смесь с помощью блендера.','https:https://st.vkuso.ru/data/cache/thumb/3b/806f46244137c3b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (807,'Смазать бока и дно формы маслом, заполнить тестом, уложить по центру начинку из творога, присыпать вишней или другими ягодами.','https:https://st.vkuso.ru/data/cache/thumb/a6/56aaa4c847257a6_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (807,'Поставить пирог-ватрушку с вишней на сметане в холодную духовку, потом задать температуру в 180 градусов, выпекать 40 минут.','https:https://st.vkuso.ru/data/cache/thumb/e2/31c85fc713579e2_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (808,'Яйцо комнатой температуры взбить любым способом, всыпать 5 ст. л. (без горки) сахара, взбить все вместе.','https:https://st.vkuso.ru/data/cache/thumb/2e/b2843364df30c2e_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (808,'Добавить сметану, разрыхлитель, муку, растительное и сливочное масло.','https:https://st.vkuso.ru/data/cache/thumb/0e/0bf3f4a6a60f00e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (808,'Вымесить тесто до эластичности.','https:https://st.vkuso.ru/data/cache/thumb/ba/e3ecd9aba88fbba_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (808,'Разделить его шарик на 4 части, обернуть пленкой убрать в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/65/695359bd4a29d65_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (808,'Помыть апельсин горячей водой, вытереть насухо, пропустить через мясорубку вместе с кожурой.','https:https://st.vkuso.ru/data/cache/thumb/fb/ebe902badb9d1fb_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (808,'Массу перемешать с крахмалом и 100 г сахара, переложить в сковороду, варить 2 минуты до загустения, дать остыть.','https:https://st.vkuso.ru/data/cache/thumb/2a/16548c89136552a_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (808,'Раскатать каждый кусочек теста в прямоугольник, смазать четвертью начинки из апельсина, разровнять, свернуть по большей стороне в рулет.','https:https://st.vkuso.ru/data/cache/thumb/4e/7b2613d000ffb4e_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (808,'Нарезать острым ножом на кусочки по 3 см.','https:https://st.vkuso.ru/data/cache/thumb/43/b5396c6f90de743_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (808,'Переложить печенье с апельсиновой начинкой на масле на противень, выпекать 20 минут при температуре 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (809,'Протереть творог.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (809,'Тщательно взбить сахар с яйцами комнатной температуры.','https:https://st.vkuso.ru/data/cache/thumb/ee/1a60ee5fef272ee_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (809,'Всыпать крахмал, размешать.','https:https://st.vkuso.ru/data/cache/thumb/96/4080e0069d8c596_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (809,'Добавить к смеси творог, йогурт, ванильную эссенцию.','https:https://st.vkuso.ru/data/cache/thumb/f1/11fc955b48ebef1_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (809,'Тщательно вымесить до однородного состояния.','https:https://st.vkuso.ru/data/cache/thumb/a4/75255a97c7d25a4_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (809,'Подготовить формочки, смазать маслом, разложить ягоды клубники, присыпать сахаром, заполнить тестом.','https:https://st.vkuso.ru/data/cache/thumb/35/5d0475fa7085835_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (809,'Выпекать творожную запеканку с клубникой в формочках полчаса до корочки песочного цвета.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (809,'Приготовить из взбитой с сахарной пудры и клубники соус.','https:https://st.vkuso.ru/data/cache/thumb/c2/1a7d3bba0ea10c2_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (809,'Перелить в соусник, поставить в холодильник до готовности запеканки, подавать вместе с блюдом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (810,'Вы привыкли, что традиционная шарлотка готовится с яблоками? Но ведь никто не запрещает вам экспериментировать. Так что смело идите на кухню и приготовьте шарлотку с мандаринами. Будьте уверены: вашим родным и гостям понравится пирог с орехами, шоколадом и легким цитрусовым вкусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (810,'Масло растопить, добавить сахар и взбить миксером, порциями добавить яйца, сметану, ванилин и муку. Мандарины очистить и разобрать на дольки, по отдельности измельчить блендером шоколад и грецкие орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (810,'Аккуратно подмешать в тесто мандарины, орехи и шоколад и тщательно его вымесить. Выстелить дно формы пекарской бумагой, смазать ее маслом и равномерно распределить по форме приготовленное тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (810,'Поставить форму с тестом в духовку, нагретую до 180 градусов, и печь шарлотку с мандаринами и грецкими орехами в районе 45-60 минут: при прокалывании изделия спичка должна остаться сухой. Готовую шарлотку достать из духовки, остудить, перевернуть на блюдо и подать либо целиком, либо порезав кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (811,'Перемешать с йогуртом тандури, влить сок лимона, всыпать порубленные перья зеленого лука, соус хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/6c/f12e3c9ec221e6c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (811,'Курицу смазать соусом, переложить на противень, выстланный пергаментом, запекать 30-40 минут в духовке с температурой в 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/3e/1bd3990fd15c93e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (811,'Нарезать кабачки на крупные кубики.','https:https://st.vkuso.ru/data/cache/thumb/56/ee3354a06acbf56_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (811,'Уложить в форму, присолить, присыпать третью натертого сыра и сухарями, побрызгать маслом, запекать до готовности около получаса.','https:https://st.vkuso.ru/data/cache/thumb/85/59774089aab7b85_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (811,'Для приготовления соуса к куриным ножкам тандури с кабачками в сливочном соусе прогреть в кастрюле с толстым дном сливки на медленном огне до кипения.','https:https://st.vkuso.ru/data/cache/thumb/0c/770e51bbd009e0c_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (811,'Всыпать сырную стружку, посолить, добавить специи, варить пока не загустеет (около 5 минут), залить готовые кабачки, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/d6/51ff2fab86e5bd6_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (812,'Прогреть молоко, залить мак, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (812,'Добавить две ложки меда, прогреть на очень слабом огне 7 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (812,'Взбить мелкий сахар с яйцами, влить масло, йогурт, всыпать муку с пекарским порошком, ванильный сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (812,'Тесто хорошо вымешать до получения массы похожей на густую сметану.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (812,'Процедить распаренный мак, объединить с тестом, тщательно перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (812,'Форму для выпечки макового кекса на йогурте с мёдом выстлать пергаментом, смазанным маслом, заполнить тестом, отправить на 10 минут в духовку с 200 градусами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (812,'Снизить температуру до 175 градусов, выпекать 25 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (812,'Готовый кекс остудить, присыпать сахарной пудрой, оформить по своему желанию.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (813,'Закипятить воду, отварить почти до готовности грудку (20 минут), дать остыть.','https:https://st.vkuso.ru/data/cache/thumb/b3/2db6997b1a771b3_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (813,'Порезать мякоть на средние кубики.','https:https://st.vkuso.ru/data/cache/thumb/33/3a946af204e6f33_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (813,'Обжарить на сливочном масле кубики лука до полупрозрачного состояния.','https:https://st.vkuso.ru/data/cache/thumb/fe/1cfe99d1785bcfe_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (813,'Добавить мясо, перемешать, обжарить пару минут.','https:https://st.vkuso.ru/data/cache/thumb/1f/47ab2837eef461f_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (813,'Залить сливками, размешать, прикрыть крышкой, тушить 4 минуты.','https:https://st.vkuso.ru/data/cache/thumb/17/4ced399d445e517_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (813,'Отварить спагетти, сцедить через дуршлаг, обдать холодной водой.','https:https://st.vkuso.ru/data/cache/thumb/33/3bd099340db9e33_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (813,'Переложить к курице, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/d8/e1536d34b3f9cd8_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (813,'Спагетти с курицей в сливках с прованскими травами посыпать смесью прованских трав и черным перцем, добавить порубленную зелень, перемешать прогреть несколько минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (814,'Посолить и поперчить филе, посыпать молотой паприкой, дать постоять четверть часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (814,'Обжарить в разогретом масле до светлой корочки (5 минут), закрыть крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (814,'Обжарить на малом огне 3 минуты, дать остыть, порезать на тонкие пластинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (814,'На широкое блюдо уложить филе, моцареллу, половинки черри, присыпать измельченным базиликом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (814,'Приготовить к салату из куриного филе и моцареллы с творожным соусом соус из крупно натертого огурца (сок отжать) с творогом, натертым чесноком, горчицей и солью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (814,'Если он получился густым, то можно развести сметаной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (815,'Измельчить блендером до состояния мелкой крошки куски лука, сушеные грибы, розмарин, сельдерей.','https:https://st.vkuso.ru/data/cache/thumb/b5/d5bd7e406c24ab5_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (822,'Заготовки скрутить в виде рулетов, обернуть полосками бекона и заколоть зубочистками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (815,'Обжарить в сотейнике, помешивая полученную смесь на растительном масле при сильном нагреве.','https:https://st.vkuso.ru/data/cache/thumb/3b/1977282ce79993b_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (815,'Залить вином, добавить сухой рис, тушить при среднем нагреве пару-тройку минут.','https:https://st.vkuso.ru/data/cache/thumb/dd/6eafd25c27d47dd_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (815,'Добавить стакан горячего бульона или воды, варить, помешивая, после впитывания влить еще один стакан.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (815,'Положить шампиньоны, порезанные на четвертинки, посолить, продолжить готовить 30 минут с доливанием бульона по мере его впитывания.','https:https://st.vkuso.ru/data/cache/thumb/eb/9d67d9089e8daeb_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (815,'В конце приготовления в ризотто с шампиньонами, белыми грибами и пармезаном добавить кусочки сливочного масла, тертый сыр, порубленную петрушку.','https:https://st.vkuso.ru/data/cache/thumb/f6/890777d1882bbf6_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (815,'Тщательно перемешать, чтобы сыр хорошо расплавился.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (816,'Для начинки: куриное филе нарезать кубиками, морковь очистить и натереть на терке, лук мелко нарезать. Сложить подготовленные ингредиенты в большую миску, добавить соль, специи и молотый перец, влить яблочный уксус и тщательно все перемешать. Слоеное тесто раскатывать в одном направлении до тех пор, пока не получится длинная тонкая прямоугольная полоска.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (816,'Разрезаем каждый тестяной пласт на 8 одинаковых (по возможности) квадратов – должно получиться 16 заготовок. В центр каждого тестяного квадратика положить немного начинки и сформовать конвертики. Противень смазать маслом, выложить на него все заготовки и запекать конвертики с начинкой из куриного филе в духовке в районе 25-30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (817,'Хорошо смешать куриный фарш, манную крупу, нашинкованный мелко лук и чеснок, вбить яйцо, поперчить, посолить.','https:https://st.vkuso.ru/data/cache/thumb/54/e4a5c47559e3d54_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (817,'Скатать фрикадельки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (817,'В плоскую тарелку высыпать панировку, обвалять фрикадельки.','https:https://st.vkuso.ru/data/cache/thumb/0d/2279ad41097dc0d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (817,'Обжарить в растительном масле, переложить в форму, промазанную маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (817,'Смешать сметану, томатный соус, бульон, подсолить, поперчить, перемешать, залить куриные фрикадельки со сметанным соусом полученным соусом.','https:https://st.vkuso.ru/data/cache/thumb/ba/56f5484bef1bdba_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (817,'Поместить форму на полчаса в прогретую до 180 градусов духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (818,'Бруснику размолоть, сок отцедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (818,'Свеклу очистить, натереть и перемешать с ягодной мезгой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (818,'Смесь залить водой, всыпать сахарный песок по вкусу, довести до кипения, варить три или пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (818,'Жмых процедить, жидкость смешать с ягодным соком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (819,'Бруснику и сладкие яблоки вымыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (819,'Яблоки разрезать на четыре части, удалить сердцевину.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (819,'На огонь поставить емкость с водой, выложить яблоки и ягоды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (819,'Всыпать сахар, довести до кипения, напиток помешивать деревянной ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (819,'После закипания кастрюлю накрыть крышкой, огонь погасить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (819,'Готовый напиток остудить и перелить в графин или в бутыль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (820,'Бруснику вымыть, измельчить и отжать сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (820,'Листочки свежей мяты вымыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (820,'Мезгу присыпать сахаром, размешать оставить на пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (820,'Влить воду, положить мяту, довести до кипения и снять с огня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (820,'Морс остудить, отцедить, перемешать с соком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (821,'Куриное филе нарезать кусочками, размер – средний. Мясо должно быть чистым, без пленок и жира.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (821,'Тонко нарезать заранее охлажденный бекон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (821,'Чеснок очистить и нарезать соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (821,'Нашпиговать куриное филе через надрезы острым ножом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (821,'Мясо посолить и поперчить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (821,'Кусочки завернуть в бекон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (821,'Получившиеся рулеты выложить на сковороду, жарить до румянца с добавлением масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (822,'Куриное филе разрезать поперек на несколько частей, отбить молотком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (822,'Нарезать тонкими длинными полосками бекон, также немного отбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (822,'Очистить репчатый лук, покрошить, спассеровать на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (829,'Заготовки скрутить в рулеты, обмотать полосками бекона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (822,'Готовые полуфабрикаты выложить в посуду, подержать около получаса в духовом шкафу, температура – 190 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (823,'Куриное филе вымыть, разрезать вдоль на четыре части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (823,'Кусочки посолить и поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (823,'Твердый сыр натереть на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (823,'Грецкие орехи очистить и порубить ножом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (823,'На кусочки мяса положить смесь сыра и орехов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (823,'Свернуть мясо с начинкой рулетами, каждый обернуть тонко нарезанным беконом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (823,'Жарить на сковороде или на гриле, со всех сторон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (824,'Приготовить начинку из пропущенного через пресс чеснока, смешать со сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (824,'Куриное филе нарезать тонкими пластинками, отбить молоточком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (824,'Каждый кусочек намазать чесночной сметаной, свернуть рулетами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (824,'Заготовки обернуть тонкими длинными полосками бекона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (824,'Огнеупорную форму застелить фольгой изнутри, смазать маслом, выложить рулеты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (824,'Накрыть емкость крышкой или еще одним листом фольги, поставить в духовой шкаф на четверть часа. Температура запекания – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (824,'Фольгу снять, блюдо подержать в духовке еще пятнадцать или двадцать минут, температура – та же.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (825,'Куриное филе хорошо промыть, обсушить при помощи бумажных салфеток.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (825,'Если куски крупные, их лучше разрезать пополам вдоль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (825,'Отбить заготовки при помощи молотка, присыпать солью и специями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (825,'На каждый кусочек положить по два плода чернослива, свернуть рулетом, обмотать тонкими полосками бекона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (825,'Готовые изделия выложить на сковороду с разогретым до кипения маслом, жарить с каждой стороны по три минуты. Огонь – средний.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (825,'Влить вино, тушить блюдо восемь минут, температуру уменьшить до минимальной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (825,'Горячие рулеты подать сразу, полить соусом со сковороды.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (826,'Грудки промыть, снять кожицу, кости удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (826,'Мякоть разрезать вдоль на восемь одинаковых кусочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (826,'Заготовки отбить, посолить и поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (826,'Каждый кусочек смазать творожным сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (826,'Свернуть рулеты, обмотать беконом, перевязать его нитью или закрепить зубочистками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (826,'Форму для запекания смазать маслом изнутри, выложить рулеты вплотную друг к другу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (826,'Время запекания в духовке – полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (826,'Чтобы на рулетах образовалась корочка, в конце запекания выставить режим «Гриль» на шесть или семь минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (827,'Огурцы порезать брусочками, посыпать солью и оставить на 15 минут, чтобы пустили сок. Сок слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (827,'К огурцам добавить измельченный на мелкой терке или через чеснокодавилку чеснок, красный острый перец, соевый соус, уксус. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (827,'В сковороде раскалить растительное масло и всыпать кунжут на 10 секунд. Сразу же добавить к огурцам и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (827,'Накрыть крышкой или пищевой пленкой и дать настояться 30 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (828,'Творожный или любой другой мягкий сыр посыпать перцем и другими острыми специями, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (828,'Куриное филе надрезать посередине не до конца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (828,'В разрез положить сырную начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (828,'Кусочки курицы замотать в бекон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (828,'Изделия жарить на сливочном масле на сковороде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (828,'Приготовить сливочный соус.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (828,'Прогреть сливки в сотейнике, добавить остатки сыра, подлить масло и соевый соус, специи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (828,'Массу перемешать, довести до кипения и снять с огня.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (828,'Готовые рулеты переложить в огнеупорную форму, влить сливочный соус, поставить блюдо в духовку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (828,'Время запекания – 20 минут, температура – 200 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (829,'Куриное филе обсушить, отбить молотком, посыпать по вкусу солью и перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (829,'Нарезать соломкой твердый сыр и ветчину.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (829,'Порубить ножом укроп и чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (829,'На каждое куриное филе выложить слоями ветчину и сыр, посыпать специями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (829,'Выставить режим «Жарка», время приготовления – по пять минут с каждой стороны.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (829,'Влить немного заранее приготовленного мясного бульона.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (829,'Выставить режим «Выпечка» на полчаса, готовить под крышкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (830,'Все ингредиенты должны быть комнатной температуры, в противном случае тесто получится жестким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (830,'При помощи миксера взбить яйца с сахарным песком, добавить творог, сливочное мягкое масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (830,'Муку с разрыхлителем всыпать порционно, частями, продукт просеять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (830,'Готовое тесто вымесить до однородного состояния. Масса должна быть мягкой, но не липкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (830,'Продукт поместить в прохладу на полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (830,'Охлажденное тесто раскатать в пласт толщиной в три миллиметра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (830,'Мармелад нарезать тонкими пластинками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (830,'Лепешку разрезать на сегменты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (830,'Начинку разложить в треугольники и скатать рогалики, начинать от широкой стороны.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (830,'Время выпекания – около двадцати минут, температура приготовления – 200 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (830,'Использовать промазанный маслом пергамент или силиконовый коврик.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (831,'Сливочное масло растопить на водяной бане.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (831,'Остальные продукты должны быть комнатной температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (831,'Перемешать масло с сахарным песком и сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (831,'Пшеничную муку просеять вместе с содой, всыпать ванилин из пакетика.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (831,'Добавить воду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (831,'Вымесить тесто, оно не должно прилипать к рукам.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (831,'Поставить тесто в холодильник на полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (831,'Кусковой мармелад нарезать небольшими кусочками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (831,'Тесто переложить на рабочую поверхность, раскатать в лепешку толщиной четыре миллиметра.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (831,'Пласт теста промазать яичным белком.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (831,'Нарезать лепешку сегментами от центра.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (831,'Выложить на поверхность кубики мармелада, скатать рулеты, начиная с широкой стороны.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (831,'Печь в течение двадцати минут, температура – 200 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (832,'Разморозить тесто так, как написано на упаковке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (832,'Рабочую поверхность посыпать мукой или смазать маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (832,'Раскатать тесто в виде квадрата.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (832,'Разрезать крест-накрест, а затем сегментами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (832,'Готовый мармелад нарезать пластинками и выложить на треугольники с широкой стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (832,'Каждый кусочек теста свернуть в виде рогалика.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (832,'Противень смазать маслом, выложить заготовки так, чтобы они не соприкасались.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (832,'Время выстаивания – от пятнадцати до двадцати минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (832,'Смазать рогалики взбитым желтком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (832,'Печь в духовке, время – пятнадцать минут, температура – 200 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (833,'Для теста: кефир хорошенько перемешать с солью, сахаром, содой и растительным маслом, просеять сверху муку и вымесить тесто. Для начинки: чеснок и зелень измельчить, сыр и очищенные яйца крупно натереть на терке. Ингредиенты для начинки смешать, заправить смесь майонезом и тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (833,'Разделить подготовленное тесто на желаемое количество кусков и раскатать каждый в тонкую лепешку. На середину каждой лепешки выложить небольшое количество начинки и хорошо скрепить края изделий.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (833,'Каждый хачапури с вареным яйцом и сыром слегка раскатать и обжарить на сковородке без масла на несильном огне до появления золотистой корочки. Готовые лепешки разложить по тарелкам и обильно смазать их сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (834,'Отделите белки от желтков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (834,'Желтки перемешайте, добавьте молоко и снова перемешайте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (834,'Просейте муку с разрыхлителем в желтки и перемешайте до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (834,'Белки слегка взбейте и добавьте часть сахара, взбивайте еще секунд 30.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (834,'Постепенно добавляйте взбитые белки к желткам и аккуратно перемешивайте.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (839,'Крупную крошку пересыпать в миску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (834,'Разогрейте антипригарную сковороду на слабом огне и смажьте еще немного растительным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (834,'Выложите тесто на сковороду, накройте крышкой и готовьте 3 минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (834,'Через 3 минуты влейте 1 ст.л воды, накройте крышкой и готовьте 1 минуту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (834,'Аккуратно переверните панкейки, добавьте в сковороду 2 ст.л воды, накройте крышкой и готовьте 4 минуты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (835,'Мармелад, приготовленный на пектине или агар-агаре, нарезать тонкими полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (835,'Всыпать муку через сито в глубокую емкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (835,'Перемешать минеральную воду с содой и маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (835,'Ингредиенты перемешать, тесто должно быть мягким.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (835,'Массу раскатать в лепешку толщиной в пять миллиметров.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (835,'Нарезать от центра треугольниками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (835,'Выложить кусочки мармелада с широкой стороны, свернуть рогалики.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (835,'Выложить заготовки на коврике из силикона',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (835,'Время приготовления в духовом шкафу – пятнадцать минут, температура – 200 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (836,'Мягкий маргарин комнатной температуры перемешать со светлым пивом, солью и пищевой содой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (836,'Добавить просеянную муку через сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (836,'Готовое тесто должно быть пластичным, выложить его в холодильник на два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (836,'Продукт вынуть, прогреть до комнатной температуры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (836,'Разделить на части, раскатать лепешки толщиной в пять миллиметров.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (836,'Каждый круг разрезать треугольниками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (836,'В качестве начинки использовать любимый джем или мармелад.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (836,'Свернуть рогалики.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (836,'Заготовки обмакнуть во взбитое яйцо и сахарный песок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (836,'Пергамент смазать маслом, застелить противень.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (836,'Выложить рогалики, печь в течение 20 минут, температура приготовления – 190 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (837,'Сырые желтки, сахарный песок, сметану и мягкое сливочное масло комнатной температуры перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (837,'Пшеничную муку просеять, добавить к основной массе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (837,'Вымесить, влить погашенную соду или всыпать разрыхлитель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (837,'Раскатать готовое тесто в круг небольшого размера, разрезать острым ножом на треугольники.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (837,'Каждый сегмент смазать мармеладом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (837,'Если продукт твердый, то его нарезать и выложить на широкую сторону треугольников. Скатать рогалики.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (837,'Прогреть духовой шкаф до 180 градусов, печь на коврике из силикона в течение двадцати минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (837,'Готовую выпечку посыпать сахарным песком или пудрой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Сливочное масло подержать при комнатной температуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Перемешать с сырым яйцом, массу взбить при помощи миксера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Влить молоко и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Пшеничную муку перемешать с разрыхлителем, всыпать в жидкую массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Замесить тесто, оно должно быть мягким и податливым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Разделить на четыре части, сформовать шарики, обернуть пленкой, положить в морозильную камеру на полтора часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Застелить противень пергаментом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Натереть замороженное тесто, два куска.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Поставить противень с крошками теста в духовку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Температура выпекания – 180 градусов, время – 20 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Готовить до появления золотистого цвета.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Вынуть из духовки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Оставшиеся два куска теста также натереть и выпечь в духовке.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Отдельно взбить в небольшой емкости мягкое сливочное масло, добавить сгущенное молоко, все вместе взбить до получения однородной массы.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Тесто поломать кусочками, выложить в крем, перемешать.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Выложить массу горкой на блюдо, посыпать маком.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (838,'Десерт оставить для пропитывания в холодильнике на ночь.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (839,'Сливочное масло подержать в тепле до размягчения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (839,'Готовое печенье поломать на куски, размолоть при помощи блендера в емкости, предназначенной для льда.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (848,'В это время взбить яйца и йогурт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (839,'В блендер загрузить шоколад и очищенные грецкие орехи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (839,'Перемолоть, соединить продукты с печеньем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (839,'В сливочное масло влить вареную сгущенку, взбить крем до однородного состояния.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (839,'Перемешать с сухими ингредиентами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (839,'Массу выложить на тарелку, посыпать тертым шоколадом, орехами или маком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (840,'Сливочное масло размягчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (840,'Орехи грецкие очистить, прогреть на сухой сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (840,'Готовое печенье «К кофе» поломать на мелкие кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (840,'Масло перемешать с вареной сгущенкой, массу взбить при помощи миксера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (840,'Орехи порубить ножом, всыпать в крем, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (840,'Добавить печенье, перемешать еще раз.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (840,'Массу выложить в виде горки на большую тарелку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (840,'Обернуть десерт фольгой, поставить на ночь в холодильник для пропитывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (841,'Сливочное масло нарезать кубиками, выложить в кастрюлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (841,'Добавить поломанные конфеты «Ириски».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (841,'Емкость подержать на тихом огне до растворения продуктов. Помешивать. Огонь выключить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (841,'Массу перелить в миску, насыпать кукурузные палочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (841,'Сформовать горку на большой тарелке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (841,'Раздробить очищенные грецкие орехи, перемешать с тертым темным шоколадом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (841,'Ингредиенты перемешать, посыпать торт.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Смазать противень растительным или сливочным маслом, присыпать мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'В миску положить мягкое сливочное масло, сахар, влить сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Продукты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Отдельно муку перемешать с разрыхлителем, всыпать в сметанную смесь. Тесто должно получиться мягким.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Разделить массу на шесть шариков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Обернуть каждый пищевой пленкой, положить на час в морозильную камеру.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Два шарика вынуть, натереть, насыпать крошку на противень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Массу разровнять, время выпекания – двадцать минут, температура – 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Процесс повторить еще два раза.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Выпечку остудить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'В кастрюлю влить молоко, всыпать ванильный и обычный сахар (2,5 стакана).',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Поставить на тихий огонь.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Яйца взбить с сахаром (1/2 стакана) при помощи миксера, всыпать муку.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Смесь вылить в кипящее молоко, перемешать.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Взбить крем миксером, масса должна быть пышной. Остудить.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Выпечку поломать кусочками, всыпать в крем, перемешать.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Массу выложить на тарелку горкой.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Готовый торт посыпать маком, дроблеными грецкими орехами.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (842,'Поставить в холод на два часа.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (843,'Чернослив хорошо вымыть, выложить в емкость и залить вином на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (843,'Жидкость слить, сухофрукты нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (843,'Готовое печенье поломать кусочками среднего размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (843,'Очищенные грецкие орехи выложить в пакет и прокатать скалкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (843,'Отдельно перемешать сгущенное молоко с мягким сливочным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (843,'В крем добавить частями орехи и чернослив, продукты перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (843,'Выложить порциями печенье, перемешать еще раз.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (843,'Массу выложить горкой на тарелку, посыпать рублеными орехами и тертым шоколадом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (843,'Время настаивания торта в холодильнике – от трех до четырех часов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Сливочное масло подержать при комнатной температуре, добавить сахарный песок и сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Массу взбить при помощи венчика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Муку перемешать с разрыхлителем, всыпать порциями в масло, помешивать. Тесто должно быть мягким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Массу завернуть в пленку, выложить в морозильник на полчаса или чуть больше.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Разделить тесто пополам, часть пропустить через мясорубку, часть положить в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Смазать чашу мультиварки растительным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Выложить тесто, пропущенное через мясорубку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Выставить режим «Выпечка» на час.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Через полчаса полуготовый корж перевернуть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Готовую выпечку поломать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Выложить в миску, охладить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Выпечь второй корж из оставшегося теста точно так же, как и первый.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Выпечку поломать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Приготовить крем из сгущенного молока и сливочного масла.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Массу взбить при помощи миксера.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Всыпать в крем печенье, перемешать, выложить торт горкой.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (844,'Время настаивания в холодильнике – несколько часов.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (845,'Свежие листья шалфея промыть, обсушить и жарить в районе 1 минуты на сливочном масле, после чего достать листочки из масла и выложить их на бумажное полотенце. Сыр Чеддер натереть на терке, пересыпать в чашу блендера, добавить к нему «Маскарпоне» и  сливочный сыр и взбить все в однородную массу. Миндаль очистить, нарезать, поджарить и добавить в сырную массу вместе с шалфеем, молотым перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (845,'Тщательно взбить содержимое чаши до однородности, скатать из получившейся массы шар, завернуть его пленкой и положить на 30 минут на полку холодильника. Гранат очистить и тщательно обсушить целые, неповрежденные зерна бумажными салфетками. По прошествии получаса вынуть шар из холодильника, снять с него пленку и полностью покрыть изделие зернами, слегка вдавливая их в массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (845,'Подавать закуску «Сырный шар в гранатовых зернах» с соленым крекером на большом блюде. При желании по предложенному рецепту можно сделать порционные шарики желаемого размера и подавать их на небольших тарелочках с крекером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Отделить белки от желтков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Желтки не понадобятся, их можно убрать в холодильник и приготовить другое блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Растопить сливочное масло, всыпать сахарный песок, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Масло немного охладить, ввести белки, массу взбить в пену при помощи миксера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Пшеничную муку смешать с крахмалом, добавить в масляную смесь порциями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Тесто размять, скатать в шар.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Охладить в течение двадцати минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Прогреть духовой шкаф до 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Тесто пропустить через мясорубку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Противень смазать сливочным маслом, выложить «колбаски».',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Корж печь до готовности. Остудить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Сварить сгущенное молоко в банке в течение двух часов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Остудить, перемешать с мягким сливочным маслом, взбить миксером.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Корж поломать кусочками.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Свежие абрикосы мелко нарезать, выложить в крем.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Массу перемешать.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Добавить кусочки выпечки.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (846,'Сформовать торт-горку. Поставить в холод на несколько часов.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (847,'Семечки очистить и обжарить на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (847,'Взбить куриные яйца с сахаром, перемешать со сливочным маслом, прогретым при комнатной температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (847,'Погасить уксусом пищевую соду, влить в основную смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (847,'Просеять муку, быстро замесить тесто. Масса должна быть мягкой и податливой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (847,'Разделить тесто на четыре шарика, завернуть в пленку, положить на час в морозильную камеру.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (847,'Противень смазать любым маслом, выложить лист пекарской бумаги.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (847,'Половину теста из холодильника натереть или пропустить через мясорубку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (847,'Выпечь полученную стружку в духовом шкафу до готовности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (847,'Точно так же поступить со второй частью теста.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (847,'Выпечку поломать на кусочки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (847,'Взбитое сливочное масло перемешать до однородного состояния со сгущенным молоком.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (847,'В кусочки выпечки добавить семечки и мак.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (847,'Сухие ингредиенты всыпать в жидкую смесь, перемешать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (847,'Сформовать торт в виде высокой горки, поставить в холод на несколько часов для пропитывания.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (848,'Порезать бекон и зубчик чесночка. Чеснок можно порезать как угодно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (848,'Положить бекон и чеснок на горячую сковороду без масла, обжарить на небольшом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (848,'Позволить бекону как следует подрумяниться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (848,'Налить в сковороду яйца, взбитые с йогуртом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (848,'Посыпать перцем, солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (848,'Сделать огонь минимальным.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (848,'Положить сверху помидоры, порезанные на кружочки, посыпать зеленым луком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (848,'Накрыть омлет с йогуртом и беконом крышкой, готовить минут пять.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (849,'С помощью миксера или в кухонном комбайне соединить сливочный сыр со сметаной до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (849,'Измельчить каперсы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (849,'В сырную смесь положить каперсы, сок лимона, перец, соль, зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (849,'Отрезать от хлеба корочки, сложить кусочки в несколько слоев.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (849,'Намазать сырной смесью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (849,'Огурцы порезать на тоненькие кружки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (849,'Положить их на сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (849,'На них выложить тоненькие ломтики лосося.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (849,'Повторить процедуру еще раз.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (849,'Обмазать торт из лосося со сливочным сыром сырной смесью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'С обеих сторон натереть стейки перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'Обжарить на сковороде или гриле на большом огне до необходимой степени готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'Подождать, пока стейки отдохнут, прикрыв фольгой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'Протереть и порезать грибы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'В сковороде нагреть растительное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'Положить измельченный лук, жарить минуты три, пока он не станет мягким, чуть-чуть золотистым, полупрозрачным.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'Положить чесночок, обжаривать секунд шестьдесят, чтобы чесночок стал ароматным.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'Сделать огонь выше среднего, положить грибы, размешать, чтобы они распределились равномерно.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'Жарить грибы, пока не станут мягкими, румяными, примерно минут пять. Время готовки зависит от размера и толщины грибов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'Посыпать перцем, солью, приправить мускатным орехом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'Налить виски, бальзамический уксус, позволить смеси чуть-чуть покипеть, чтобы часть алкогольного напитка сожглась.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'Выключить огонь, налить кокосовое молоко/сливки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'Позволить покипеть секунд тридцать, попробовать на соль.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'Положить измельченную зелень, полить соусом.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (850,'Можно подавать говяжий стейк со сливочно-грибным соусом из сморчков.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (851,'Растопить на тихом огне сливочное масло, можно использовать маргарин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (851,'Это практически не повлияет на вкусовые качества печенья.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (851,'Взбить яйца, ванилин, сахар, разрыхлитель в пену.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (851,'Снять цедру с лимона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (851,'Положить цедру во взбитую яичную смесь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (851,'Насыпать просеянную муку, налить растопленное масло, взбить все до однородности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (851,'Отправить получившуюся смесь часа на два в холодильник, чтобы тесто пропиталось вкусом лимона.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (851,'Консистенция теста должна быть похожа на жидкую сметану.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (851,'Когда пройдет несколько часов, заполнить тестом силиконовые формочки, отправить в нагретую духовку на десять минут, соблюдать температуру 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (851,'Необходимо наблюдать, чтобы печенье не подгорало.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (851,'В первые минут шесть духовку желательно не открывать, тогда печенье поднимется и хорошенько пропечется.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (851,'Формочки смазывать не нужно.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Приготовить начинку: измельчить лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Положить на сковороду говяжий фарш, добавить топленое масло, измельченный лучок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Тушить, пока фарш не будет готов, непрерывно мешать, чтобы он получился рассыпчатый.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'В конце посыпать перцем, солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Отставить, чтобы фарш остыл.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Отварить рис на пару до готового состояния. Желательно использовать длиннозерный рис.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Промыть изюм, залить крепким чаем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Приготовить тесто: растопить масло.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'В емкости соединить яйца и кефир (сметану или молоко), соль, сахар.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Добавить растопленное масло.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Насыпать просеянную муку, замесить тесто.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Оно должно получиться эластичным и жирным.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Сделать крошку: соединить мягкое масло и просеянную муку, протереть в крошку.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Собрать уенчеки: поделить тесто на четырнадцать кусочков.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Каждый раскатать в сочень диаметром пятнадцать сантиметров.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Во время раскатывания муку использовать не нужно, потому что тесто само по себе жирное.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Положить начинку: сначала положить фарш, на него слой риса, сверху слой изюма.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'По периметру сделать прищипы, как на беляши, но без крышечки.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Отверстие посыпать крошкой.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Положить пирожки на противень, смазывать его не нужно, можно постелить пергамент.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Отправить в духовку минут на 25, соблюдать температуру 190 градусов.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (852,'Достать уенчек, позволить чуть-чуть остыть.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Вымыть картофель хорошенько при помощи щетки, просушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Сделать со всех сторон проколы вилкой, чтобы картофель быстрей пропекся, намазать растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Все картофелины посыпать перцем и солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Присыпать сухими травами по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Завернуть картофель в фольгу, каждый клубень отдельно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Выложить подготовленный картофель в мультиварку в два ряда.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Выбрать режим «Выпечка», поставить таймер на шестьдесят минут. Закрыть мультиварку крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'В период готовки переворачивать картофель несколько раз.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Через шестьдесят минут сделать в картофеле проколы деревянной шпажкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Если картофель не стал мягким, то поставить таймер еще минут на двадцать-сорок, в зависимости от размера.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Во время запекания картофеля приготовить сметанный соус.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Измельчить укроп, пропустить через пресс почищенный чесночок.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Смешать в емкости чеснок, сметану, зелень.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Насыпать молотый черный перец, соль. Размешать.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Приготовленный картофель осторожно, чтобы не обжечься, переложить в емкость.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (853,'Разрезать каждый клубень, не снимая фольги, на четыре части, краешки фольги завернуть, в центр положить по кусочку сливочного масла.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (854,'Порезать на тоненькие кружочки промытые огурцы, редис, морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (854,'Положить овощи на кусочек хлеба, намазанного хумусом, полить ингредиенты смесью сока лимона, соли, оливкового масла, перца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (854,'Порезать помидор на кружочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (854,'Намазать второй кусочек хлеба хумусом, положить его сверху бутерброда, намазанной стороной на овощи, полить ¾ столовой ложки песто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (854,'Выложить на песто дольки томата, накрыть ломтиком тоста, намазанного песто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (854,'Разрезать двухэтажный сэндвич с помидорами и хумусом пополам по диагонали.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Отмерить четыре столовых ложки воды и отправить в морозилку, понадобится ледяная вода.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Заняться приготовлением теста: соединить муку, соль, сахарную пудру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Масло порезать на кубики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Положить в муку ½ масла, осторожно перетереть в крошку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Остальное масло положить, окончательно перетереть. Должны образоваться маленькие комочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Взбить яйца, добавить ледяную воду, лимонный сок. Размешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'В середине сделать ямку, влить по частям жидкость.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Растереть тесто, пока из него не получится плотный комок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Положить тесто на стол, чуть-чуть посыпанный мукой, перемешать до однородности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Сделать шарик.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Завернуть в пленку, отправить минут на шестьдесят в холодильник.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'В это время приготовить начинку.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Почистить груши или яблоки, обрезать сердцевину, порезать на небольшие кубики.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Насыпать белый сахар, положить цедру лимона, налить лимонный сок, осторожно размешать.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'В сковороде растопить масло, положить коричневый сахар.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Добавить груши, яблоки, размешать.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Положить корицу, можно использовать как палочки корицы, так и порошковую.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Томить на среднем огне минут десять.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Отставить в сторону, позволить начинке остыть.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Достать тесто, раскатать, порезать на кружки по размеру формочек.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Один кружочек должен быть в диаметре на несколько сантиметров больше, второй должен в диаметре совпадать с размером формочки – он будет закрывать пирог.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Намазать формочку маслом, положить тесто, которое побольше.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Положить на тесто начинку, сверху положить кружок тесто поменьше, с помощью него плотно запечатать верх пирога.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Намазать пирожки чуть-чуть взбитым яйцом.',NULL,24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Можно использовать остатки теста: прикрепить их сверху на пирожки, сделав из них листочки.',NULL,25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Их тоже следует намазать яйцом.',NULL,26);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Обязательно необходимо сделать в каждом пирожке дырочку, чтобы через нее выходил пар.',NULL,27);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Убрать в нагретую духовку, соблюдать температуру двести градусов.',NULL,28);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Готовить минут пятнадцать, пирожки должны стать золотистыми.',NULL,29);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (855,'Перед подачей подождать, пока остынет формочка.',NULL,30);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Смешать муку, сливочную мазилку, сливочное масло, яйцо, соль. Смешивать можно миксером или вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Масло не растирать, необходимо быстро собрать все в комочек и отправить в холодильник на шестьдесят минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'В результате этого получается эффект слоеного теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Пока тесто замерзает, сделать начинку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Разрезать порей вдоль, вымыть, порезать поперек на кусочки по 1 сантиметру.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Натереть на терке сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Взбить мазилку, яйца, сливки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Посыпать яичную смесь перцем, солью, добавить мускат.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Соли добавлять чуть-чуть, так как бекон соленый.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Обжарить бекон минут пять на сковороде, положить ложку сливочного масла, добавить порей.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Тушить на среднем огне минут восемь.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Намазать формочку для киша сливочным маслом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Посыпать стол мукой, раскатать тесто.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Переложить тесто в формочку.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Лишнее тесто по краям обрезать.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'На тесто положить бекон с пореем.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Сверху посыпать тертым сыром.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Полить начинку сливочно-яичной смесью.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (856,'Отправить киш в горячую духовку, готовить минут 35, соблюдать температуру 200 градусов.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (857,'Тоненько порезать красный лук, посыпать половиной чайной ложки соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (857,'Отставить минут на двадцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (857,'Промыть водой, положить в ситечко, чтобы стекла жидкость.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (857,'Порезать огурцы на кубики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (857,'С помощью острого ножа срезать с початков зерна кукурузы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (857,'Соединить лук, кукурузу и огурцы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (857,'Положить к овощам сладкий перец, порезанный на квадратики, измельченную петрушку и укроп.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (857,'Соединить в средней посуде пахту или кефир, йогурт, уксус, измельченный шалот, прессованный чесночок, щепотку соли.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (857,'Медленно ввести оливковое масло, непрерывно взбивать, посыпать перцем, солью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (857,'Заправить салат с кукурузой, огурцами и сладким перцем соусом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (858,'Соус. Смешиваем зелень укропа, цедру лайма, чеснок, карри, горчицу в зернах, перец чили, соль, сухой базилик и растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (858,'Нарезаем мясо на порционные кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (858,'Добавляем лук, соль, черный молотый перец, сок лайма и растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (858,'Жарим на углях 20-25 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (858,'Смазываем соусом и жарим ещё по 3 минуты с каждой стороны.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (859,'Моем кабачок и натираем его на терке вместе с кожурой. Посыпаем половинкой чайной ложки соли и перемешаем. Даем постоять чтобы кабачки пустили лишний сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (859,'Хорошо отжимаем натертый кабачок и выкладываем его в миску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Тыкву порезать брусочками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (859,'Добавляем к натертому кабачку ложку сметаны, 1 куриное яйцо, щепотку нарезанного укропа и 400 гр. фарша. Чтобы драники получились остренькими я добавляю сушенного измельченного чеснока по вкусу. Размешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (859,'Далее в эту массу добавляем 3 ст. л. манной крупы и солим по вкусу. Хорошо перемешиваем нашу кабачковую массу. Даем постоять минут 10 для набухания манки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (859,'В сковороду наливаем растительное масло и разогреваем его.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (859,'Ложкой выкладываем в разогретое масло нашу кабачковую смесь. Обжариваем до готовности на среднем огне с обеих сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (860,'Спелые и сладкие бананы очищаем от кожуры, нарезаем кружочками и отправляем на несколько часов в морозилку, бананы должны замёрзнуть.','https://vkuso.ru/data/cache/data/2b/a178b06ae965c2b_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (860,'Клубнику нужно порезать и тоже заморозить.','https://vkuso.ru/data/cache/data/fe/bf6722b5d7523fe_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (860,'Замороженные бананы и клубнику отправляем в чашу блендера и добавляем молоко.','https://vkuso.ru/data/cache/data/24/c8b403f4b1f0824_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (860,'С помощью блендера превращаем к кремоорбразную массу.','https://vkuso.ru/data/cache/data/f9/5eb83098c8facf9_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (860,'Массу перекладываем в емкость для заморозки, это может быть судок, контейнер, миска, специальные формочки.','https://vkuso.ru/data/cache/data/60/e95188366fb5760_434x295_notrise.png',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (860,'Контейнер вынимаем из морозилки примерно раз в пол часа и перемешиваем. Так повторяем несколько раз.','https://vkuso.ru/data/cache/data/e1/d70e21d26a73fe1_434x295_notrise.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (861,'Подготовьте ингредиенты для приготовления блюда. Почистите лук и промойте грибы.','https://vkuso.ru/data/cache/data/a3/58dbe8ee884f6a3_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (861,'Нарежьте лук кубиками и обжарьте на среднем огне около 5-10 минут до золотистого цвета.','https://vkuso.ru/data/cache/data/83/5d374a59b144d83_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (861,'Порежьте шампиньоны вдоль на 4 части. Как лук поджарится, высыпьте грибы в сковороду и периодически помешивая жарьте 5 минут.','https://vkuso.ru/data/cache/data/ac/a6e333d7ec1adac_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (861,'Далее необходимо добавить специи и посолить. Продолжайте жарить шампиньоны до тех пор, пока не выкипит большая часть воды, которую выделили грибы. Это займет около 10 минут. После чего добавьте 3 столовые ложки сметаны. Когда она закипит накройте крышкой и тушите 10 минут до готовности. Приятного аппетита!','https://vkuso.ru/data/cache/data/d7/8dc6025b25b25d7_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (862,'Очищенный лук измельчить, пропустить чеснок через пресс, кедровые орешки измельчить. На среднем огне разогреть оливковое масло, высыпать на сковородку лук, орехи и чеснок и обжаривать смесь, периодически перемешивая, около 8 минут (до мягкости лука), после чего дать ей остыть. Яйцо слегка взбить, листья петрушки и базилика промыть, обсушить и измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (862,'Далее смешать куриный фарш с остывшей луковой массой, хлебными крошками, яйцом, зеленью, перцем и солью. Глубокую форму для запекания смазать небольшим количеством масла, ровным слоем распределить по ней мясную массу и слегка прижать ее руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (862,'Духовку нагреть до 180 градусов, поставить в нее форму и запекать хлеб из куриного фарша с базиликом 40-45 минут, пока он не станет золотистым. Готовую запеканку оставить в форме на 10 минут, после чего аккуратно переложить ее на разделочную доску, нарезать порционными кусками и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (863,'Вымыть зелень. Листья салата нарвать, смешать с рукколой и отправить в тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (863,'Рыбу нарезать на небольшие кусочки. Манго очистить от кожицы и нарезать кубиками. Отправить в тарелку к зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (863,'Сыр фета нарезать кусочками, отправить в тарелку. Полить бальзамическим кремом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (864,'В 50 мл воды замочить желатин на 10 минут при этом иногда перемешивать, чтобы желатин не прилип ко дну.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (864,'Спустя 10 минут доливаем 100 мл воды и ставим желатин на огонь. Греем до полного растворения, но не доводить до кипения. Затем снимаем с огня и сразу же приступаем к следующему шагу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (864,'В глубокую миску отправить мягкий творог, какао, малину (100 гр) и заливаем желатиновой смесью, перемешиваем миксером (можно погружным, легче будет измельчить малину) до однородности. Насыпать сахара и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (864,'Разлить получившуюся массу по пиалам, убрать в холод минимум на 2 часа. Застывший десерт украсить: посыпать какао и выложить малину.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (865,'Картошку очистить, разрезать картофель на 4 части и нарезать крупными кусками. Отправить в кастрюлю с водой и поставить на огонь. Доводим до кипения, варим 5 минут, затем сливаем воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (865,'Болгарский перец очистить от семян и нарезать крупными кубиками. В глубокой сковороде разогреть оливковое масло, отправить туда болгарский перец и обжаривать на сильном огне в течение 3 мину, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (865,'Чеснок очистить и пропустить через пресс к обжаренному болгарскому перцу. Готовим 2 минуты на сильном огне, перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (865,'Мелко нарубить базилик, отправить в сковороду к болгарскому перцу и добавить отваренную картошку, посолить и поперчить. Готовим на сильном огне 10 минут, перемешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (865,'Спустя 10 минут снимаем картофель с огня. Из лимона выдавить сок и добавить сыр фета, тщательно перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (866,'Кабачок натереть на крупной терке и дать постоять, чтобы он пустил сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (866,'В емкость поместить фарш, рис, отжатый от жидкости кабачок, яйца, порезанные мелко лук и чеснок, добавить измельченную зелень. Массу посолить, поперчить и тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (866,'Форму для выпечки смазать растительным маслом и выложить в нее подготовленную массу для запекания, разровнять и отправить в разогретую духовку на 200 градусов примерно на 30-40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (866,'За 15 минут до окончания запекания, посыпать тертым на крупную терку сыром, чтобы образовалась румяная корочка.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (867,'Куриное филе моем под водой, обсушиваем при помощи бумажного полотенца, далее куриное филе нужно распластать на две половинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (867,'Далее перекладываем в глубокую тарелку, добавляем 150 мл кефира, соль, перец, приправу для курицы, паприку по вкусу. Все перемешиваем. Убираем в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (867,'В другую тарелку, нарезаем мелко укроп, при помощи чеснокодавилки добавлением чеснок 4 зуб, и 140 грамм плавленого сыра, лично у меня был голландский, добавлением 1-2 ч. л майонеза. Все перетираем до однородной массы. Убираем в сторону.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (867,'Куриное филе обжариваем на разогретой сковороде до корочки около 3 5 минут с каждой стороны',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (867,'Как только обжарили, намазываем плавленым сыром с чесноком и укропом куриное филе с одной стороны. Все готово.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (868,'Сварить манную кашу, добавить в нее сливочное масло и оставить немного под остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (868,'В сотейник всыпать ягоды, сахар и 50 мл воды. Варить 5 минут затем ввести тонкой струйкой разведенный в оставшейся воде крахмал. Варить еще пару минут прежде чем снять с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (868,'В теплую кашу добавить яйцо и 3 ст.л. муки, хорошо все вымесить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (868,'Мокрыми руками формировать шарики из манной смеси, обвалить в оставшейся муке и слегка приплюснуть что б получились по форме биточки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (868,'Обжарить биточки на растительном масле с двух сторон до золотистого цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (868,'Перед подачей дать манным биточкам с кисельным соусом настояться в течении 10-15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (869,'Налить молоко в кастрюлю небольшого размера, прогреть до кипения на тихом огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (869,'Всыпать соль и сахарный песок, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (869,'Добавить овсяные хлопья, варить блюдо на минимальном огне около пяти или семи минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (869,'Кашу помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (869,'Снять с огня, положить кусочек сливочного масла, дать постоять под крышкой в течение пяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (870,'Апельсины вымыть, один ошпарить кипящей водой, натереть цедру, выдавить сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (870,'Второй апельсин очистить и поделить на дольки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (870,'В кастрюлю влить сок, выложить цедру, всыпать овсяные хлопья, влить молоко, варить блюдо на тихом огне, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (870,'В готовую кашу положить мед, изюм, выложить в тарелки, украсить дольками апельсина.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (871,'Крупу промыть, залить водой на пять часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (871,'Еще раз промыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (871,'Поставить емкость на тихий огонь, варить сорок минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (871,'Перемешать молоко с солью и сахаром, влить в кашу, варить до загустения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (871,'Переложить продукт в глиняный горшок или в казанок, поставить в прогретую духовку на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (871,'Готовую кашу выложить в тарелки, добавить по кусочку сливочного масла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (872,'Воду довести до кипения, всыпать заранее промытый рис, варить около восьми минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (872,'Отцедить воду через дуршлаг, рис промыть холодной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (872,'В кастрюле довести до кипения молоко, положить по вкусу сахар и соль, переложить рис.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (872,'Варить до загустения, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (873,'Всыпать рис в кипящую воду, варить семь или восемь минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (873,'Воду слить, рис откинуть на сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (873,'Нарезать кубиками или ломтиками тыкву, залить молоком на два сантиметра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (873,'Всыпать немного соли.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (873,'Довести до кипения, варить пять или семь минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (873,'Перемешать с рисом и сахарным песком, варить до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (873,'Слишком густую кашу можно разбавить горячим молоком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (873,'В конце приготовления добавить сливочное масло, молотую корицу, ванильный сахар из пакетика.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (874,'Подготовьте ингредиенты для салата. Заранее отварите яйца вкрутую.','https://vkuso.ru/data/cache/data/49/342be6acfb46449_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (874,'Расправьте крабовые палочки на пласты и нарежте их соломкой.','https://vkuso.ru/data/cache/data/b3/22d18e0d42828b3_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (874,'Яйца тоже нарежьте соломкой.','https://vkuso.ru/data/cache/data/2d/60dad94a1026a2d_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (874,'Чеснок пропустите через пресс или натрите на тёрке. Сыр натрите на мелкой тёрке. По желанию посолите и поперчите салат.','https://vkuso.ru/data/cache/data/1a/4b3af29def2d51a_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (874,'Добавьте 2 столовые ложки майонеза и тщательно перемешайте. Приятного аппетита!','https://vkuso.ru/data/cache/data/6b/48f8f9736322d6b_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (875,'Красный лук нарезаем четверть кольцами. Яблоко нарезаем кубиками. К луку добавляем яблоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (875,'Нарезаем также соленые огурчики. Добавляем их к яблоку и луку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (875,'Нарезаем лук и всю зелень. Зелень добавляем к нашему салату.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (875,'И займемся теперь селедкой. Обязательно очищаем селедку от тонкой шкурки. Удаляем все кости. Нам понадобится только очищенное филе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (875,'Филе сельди нарезаем кубиками. Селедку добавляем к салату. Также добавляем молотый черный перец по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (875,'Для заправки салата будем использовать сметану. Хорошо перемешиваем немецкий салат. Наша селедка по-баварски готова. Приятного аппетита!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (876,'Для начала нарежем все овощи примерно одного размера, и перейдём к соусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (876,'Для соуса нам нужно будет разогреть масло, добавим мелко нарезанный лук, чеснок и перец, обжарим и добавляем томатную пасту и зальём небольшим количеством воды, затем добавляем тимьян, посолим, поперчим и добавим паприку. Проварить пару минут, затем снять с плиты и залить готовый соус на дно формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (876,'После раскладываем овощи по очереди.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (876,'Сверху заливаем немного оливково масла, подсолим, поперчим и добавим свежего тимьяна. Накроем фольгой и отправим в духовку разогретую на 200 градусов на 50 минут, после, снять фольгу и оставить ещё на минут 10.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (877,'Твердый сыр натереть на терке, смешать с фаршем, яйцом и специями по вкусу. Плавленый сыр перемешать до однородности с творогом. Из получившейся мясной массы сделать «гнезда» желаемого размера и заполнить их сырно-творожной начинкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (877,'Запекать мясные ватрушки с сырно-творожной начинкой в нагретой до 180 градусов духовке 40 минут. Перед подачей посыпать готовые ватрушки измельченной зеленью или колечками зеленого лука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (878,'Перцы освободить от семян, баклажаны разрезать вдоль пополам, чеснок очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (878,'Запечь все овощи сбрызнутыми маслом до мягкости при 190-200 градусов до мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (878,'Запеченный перец переложить в емкость и плотно крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (878,'Через 10 минут снять с него кожуру.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (878,'Ложной выскрести мякоть баклажанов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (878,'Сложить все овощи в миску, добавить остатки растительное масло, посолить, влить уксус и измельчить блендером.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (879,'Просейте муку через сито. Добавьте сахар и соль, перемешайте.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (879,'Присыпьте рабочую поверхность мукой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (879,'Сформируйте круг из каждого кусочка теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (879,'Раскатайте тесто в тонкую лепешку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (879,'Разогрейте сковороду на сильном огне и по желанию смажьте ее немного растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (879,'Выложите лепешку на сковороду и жарьте около 30 секунд с каждой стороны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (880,'Рис отварить. На часть крупы взять две части воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (880,'Довести жидкость до кипения, всыпать рис, варить десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (880,'Закрыть крышкой, подержать на огне еще столько же.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (880,'По желанию при варке в кастрюлю можно положить кусочек сливочного масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (880,'Вымыть сухофрукты, крупные плоды нарезать кусочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (880,'Переложить в сливочное масло, растопленное в небольшой кастрюле.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (880,'Потушить до мягкости на тихом огне, добавить мед, влить кипящую воду, варить около десяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (880,'Переложить рисовую кашу в тарелки, залить подливой с сухофруктами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (880,'Другой вариант: в уже приготовленные сухофрукты добавить рис, кипятить несколько минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (881,'Рис промыть, залить кипятком, дать настояться в течение пятнадцати минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (881,'Измельчить морковь и репчатый лук, выложить на сковороду вместе с консервированным или замороженным зеленым горошком, подлить воду, добавить масло, подержать смесь под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (881,'Припущенные овощи переложить в сотейник или в кастрюлю с толстым дном.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (881,'Сверху выложить полуготовый рис, влить кипяток, всыпать соль и специи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (881,'Потомить на тихом огне до выпаривания влаги.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (882,'Молоко перемешать с водой, поставить жидкость на плиту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (882,'Довести до кипения, всыпать сахарный песок, соль, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (882,'Всыпать манную крупу тонкой струйкой, в каше не должно быть комков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (882,'Довести до кипения, добавить кусочек масла, хорошо промытые сухофрукты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (882,'Подержать блюдо под крышкой при выключенной плите в течение десяти или пятнадцати минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (883,'Кедровые, грецкие орехи, фундук очистить от скорлупы, залить на три минуты кипящей водой. Очистить от кожицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (883,'Подсушить в микроволновой печи, затем измельчить в ступке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (883,'Влить немного воды и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (883,'Приготовить молочные пенки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (883,'Вылить молоко в эмалированную или чугунную посуду, поставить в разогретый духовой шкаф, снимать пенки по мере их появления.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (883,'На оставшемся молоке поварить манную крупу, добавить в нее сахарный песок, растертые орехи, пряности, масло. Ингредиенты перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (883,'В сковороду с высокими стенками влить слой каши, сверху – часть пенок, процесс повторить несколько раз.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (883,'В предпоследний слой положить бадьян и красное варенье.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (883,'Поставить блюдо под крышкой в горячую духовку на пять или семь минут, температура приготовления – 150 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (883,'Блюдо вынуть, полить остатками варенья, посыпать орехами.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (884,'Молоко довести до кипения, положить соль и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (884,'Всыпать манную крупу тонкой струйкой, отварить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (884,'Нарезать мелкими кубиками банан, потереть на средней терке шоколад.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (884,'В кипящую кашу положить кусочек сливочного масла, подержать на плите.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (884,'Добавить бананы, шоколад, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (884,'Огонь погасить, блюдо подержать под крышкой в течение десяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (885,'Кукурузную крупу насыпать в кастрюлю, влить воду, варить при постоянном помешивании.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (885,'Добавить молоко тогда, когда вода почти вся выкипит.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (885,'Соль и сахар – по вкусу. Варить полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (886,'Промыть в теплой воде изюм без косточек и курагу. Другой вариант – залить кипятком на несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (886,'Курагу обсушить и нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (886,'Смешать воду со свежим молоком, довести до кипения, добавить сахарный песок, соль, всыпать кукурузную крупу порциями. В каше не должно быть комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (886,'Варить в течение пятнадцати минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11012,'Крупно нашинковать лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (886,'Затем переложить почти готовый продукт в чугунный или глиняный горшок, добавляя курагу, изюм, кусочки сливочного масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (886,'Горок закрыть, запечь в духовке в течение часа. Температура приготовления – около ста градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (887,'Крупу обжарить на сухой сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (887,'Залить продукт горячим молоком, оставить на полчаса для набухания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (887,'Очистить тыкву семян и кожуры, твердую часть плода нарезать кубиками небольшого размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (887,'Посыпать сахаром, прогреть до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (887,'Соединить тыкву с кукурузой, посолить и довести до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (887,'Снять с огня, завернуть кастрюлю в плед для упревания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (888,'амочить изюм, затем отцедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (888,'Перемешать с кукурузной крупой, оливковым маслом, сахаром и солью, влить горячую воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (888,'Выложить смесь в емкость для запекания, поставить в духовку на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (889,'Пшеничную крупу промыть, залить холодной водой, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (889,'Огонь уменьшить, варить пятнадцать или двадцать минут, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (889,'Заправить блюдо сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (890,'Муку смешать с солью, сахаром и подсолнечным маслом, влить в смесь крутой кипяток, тщательно все перемешать и дать массе остыть. Затем добавить в остывшую массу 50 г. свежих дрожжей, влить теплую воду, всыпать 4 ст. муки и замесить тесто (как на пирожки). Далее разделить получившееся тесто на желаемое количество частей, оставить кусочки на 5 минут, после чего сформовать из них пирожки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (890,'Обжарить приготовленные пирожки на сковородке с большим количеством растительного масла. В качестве начинки для пирожков можете использовать все, что любите: картошку, картошку с печенью, картошку с жареным луком и чесноком, рис с вареным яйцом, капусту, жареную с луком и т.д. Пирожки из быстрого безопарого дрожжевого теста также можно испечь и со сладкой начинкой: например, с вишней, яблоками, творогом, вареньем и т.п.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (891,'Мелко нашинковать лук и пассеровать его в растительном и сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (891,'Затем добавить муку и пассеровать ее некоторое время.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (891,'Размешать в вводе бульонный кубик и влить в сковороду. Вместо бульонного кубика можно использовать любой другой бульон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (891,'Варить соус на слабом огне, постоянно помешивая, до загустения. Поперчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (891,'Готовый соус процедить через сито или воспользоваться погружным блендером.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (892,'Сметану (680 г), с помощью миксера, тщательно перемешаем с сахаром до его полного растворения. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (892,'Кулинарное кольцо диаметром 18-20 см выстелем пищевой пленкой (дно и бока) так, чтобы концы пленки свисали с краев кольца и выложим печенье со сметанным кремом. Верх разровняем и накроем пищевой пленкой. Отправляем в холодильник на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (892,'Готовим шоколадную глазурь. Смешиваем сахар, какао и кофе. В кастрюлю добавляем сметану (120 г) и добавляем смешанные сухие ингредиенты для глазури, перемешиваем. Поставим на медленный огонь до растворения сахара, но не доводим до кипения, чтобы сметана не свернулась. Снимаем глазурь с огня и добавляем сливочное масло, перемешиваем и отставляем остывать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (892,'Снимаем форму и освобождаем от пищевой пленки. Наносим глазурь на торт и украшаем на свое усмотрение, я украсила кофейным печеньем. Всем добра!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (893,'Заранее подготовим слоеное тесто. Вынимаем слоеное тесто из упаковки. Перекладываем его на тарелку. Если у вас в упаковке 2 пласта, то их нужно разделить. Даем ему разморозиться. У меня тесто разморозилось за 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (893,'Также нужно подготовить мак. Перекладываем мак в глубокую тарелку, и заливаем его теплой водой из чайника. Мак нужно залить водой, что бы он набух. Оставляем на 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (893,'Спустя 15 минут, сливаем воду через сито, так же через сито при помощи ложки слегка «выжимаем мак» что бы часть воды так же отделилась. Мак перекладываем в другую тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (893,'Мак можно перетереть с сахаром. Просто в мак добавляем сахар, и перетираем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (893,'Куриное яйцо нужно взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11503,'Изделия отварить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (893,'Слоеное тесто раскатывать не надо так как в духовке оно лучше подойдет. Так вот берем слоеное тесто, и на него добавляем мак тонким слоем, мак нужно распространить по всей поверхности теста. Сверху на мак укладываем ещё 1 пласт слоеного теста, далее его смазываем куриным взбитым яйцом, посыпаем сахаром, далее при помощи обычного ножа, или ножа для пиццы нарезаем на полоски. Перекладываем на противень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (893,'Я снова взял пласт теста, так как их у меня было 4. Снова добавил на тесто мак, и нарезал на полоски. И переложил на противень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (893,'Так вот у меня получились закрытые язычки (это где слоеное тесто и снизу и сверху) и открытые язычки ( это где слоеное тесто только снизу) Все это я отправил в духовку на 30 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (893,'Если вы будете готовить данные язычки в то время, как они находятся в духовке следите за ними. Так как когда я первый раз вытащил слойки спустя 15 мин тесто не пропеклось, пришлось ждать еще примерно минут 15. Тесто должно подрумянится до золотистой корочки. Все готово.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (894,'Довести молоко до кипения, всыпать крупу, сахарный песок, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (894,'Довести до кипения еще раз, огонь убавить, оставить на сорок минут под крышкой. Не перемешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (894,'Огонь погасить, добавить кусочек сливочного масла, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (894,'Подержать под крышкой еще десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (895,'Грибы отварить, откинуть на сито или дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (895,'Отвар сохранить, грибы нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (895,'Сливочное масло растопить, добавить растительное.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (895,'На этой смеси обжарить мелко нарезанный репчатый лук, в конце приготовления влить грибной бульон. Довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (895,'Промыть пшеничную крупу, всыпать в закипевший бульон, добавить масло, соль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (895,'В загустевшую кашу добавить грибы, луковую заправку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (895,'Ингредиенты перемешать, поставить в духовой шкаф на сорок минут. Температура приготовления – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (896,'Натереть морковь, нашинковать кубиками небольшого размера мясо и лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (896,'Раздавить зубчики чеснока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (896,'Поочередно обжаривать в казане лук, морковь. Овощи должны приобрести золотистую корочку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (896,'В конце добавить чеснок и мясо, жарить все вместе до испарения влаги.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (896,'Влить воду, добавить лавровый лист, любимые специи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (896,'Тушить все вместе двадцать пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (896,'Вынуть и выбросить чеснок и лавровый лист.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (896,'В оставшиеся продукты добавить промытую пшеничную крупу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (896,'Довести до кипения, огонь уменьшить, варить до мягкости крупы, помешивать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (896,'Огонь погасить, дать каше постоять пятнадцать минут, разложить в тарелки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (897,'Промыть половинчатый горох, залить холодной водой на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (897,'Утром промыть продукт еще раз, воду слить, добавить чистую или свиной бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (897,'Поставить на средний огонь, довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (897,'Огонь убавить, в кашу всыпать соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (897,'Варить до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (897,'Горох должен развариться, жидкость – выпариться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (897,'Растолочь массу толкушкой, пюре отставить в сторону.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (897,'Свинину промыть и нарезать пластинками, очистить и нашинковать репчатый лук.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (897,'Раскалить на сковороде растительное масло, обжарить лук, выложить мясо, тушить под крышкой до готовности. Соль – по вкусу, добавить специи.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (897,'Свиную обжарку добавить в гороховую кашу, поставить в духовку на десять минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (898,'Горох замочить на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (898,'Воду слить, продукт промыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (898,'Куриные окорочка или свиные копченые ребрышки, отделить от костей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (898,'Мясо залить водой, довести до кипения, варить десять минут. Ребрышки варить сорок минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (898,'Вынуть мясо из бульона, залить им горох.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (898,'Жидкость должна покрывать горох на два сантиметра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (898,'Довести до кипения, огонь убавить, варить горошницу под крышкой в течение полутора часов. Помешивать. Горох должен развариться. При необходимости добавить воду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (898,'Натереть морковь, нарезать лук. Продукты обжарить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (898,'Добавить отваренное копченое мясо, жарить несколько минут, огонь – сильный.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (898,'За пять или семь минут до готовности гороха добавить в него мясную обжарку, соль, шинкованную зелень.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (898,'Плиту выключить, блюдо должно постоять под крышкой для упревания.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (899,'Куриную грудку и яйца отвариваем до готовности. Остужаем и нарезаем всё мелким кубиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (899,'Красный болгарский перец чистим и нарезаем его мелкой соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (899,'Огурцы и луковицу я нарезаю тонкими четверть кольцами. Зелень мелко нашинкуем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (899,'В салатнике смешиваем все ингредиенты и добавляем красную консервированную фасоль без жидкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (899,'Заправляем салат майонезом и солим по своему вкусу. Перемешиваем все ингредиенты и наш салатик из фасоли с курицей готов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (900,'Залить водой горох, набухший и промытый продукт отварить на мясном бульоне с солью до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (900,'Превратить в пюре толкушкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (900,'Срезать с тыквы крышку, семена убрать ложкой, оставить стенки толщиной в два сантиметра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (900,'Нарезать и обжарить репчатый лук, добавить к нему нарезанные пластинками белые грибы или шампиньоны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (900,'Пассеровать все вместе до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (900,'В конце добавить зелень и пропущенный через пресс чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (900,'Пюре перемешать с обжаркой, выложить продукты в тыкву, сверху – кусочек сливочного масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (900,'Закрыть крышкой, поставить в духовой шкаф на пятнадцать или двадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (900,'Температура – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (901,'Лососевое филе нарезать длинными полосками шириной в четыре или шесть сантиметров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (901,'Рыбу хорошо натереть молотым перцем и солью, побрызгать лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (901,'Выложить продукт в форму для запекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (901,'Сырые куриные желтки смешать со сливками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (901,'Промыть и порубить зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (901,'Натереть лимонную цедру, добавить в сливки вместе с дижонской горчицей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (901,'Массу перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (901,'Готовым соусом залить рыбу, поставить в горячую духовку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (901,'Время запекания – от двадцати до двадцати пяти минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (902,'Сок перелить в антипригарную кастрюльку или сотейник. Муку смешать с манкой и всыпать тонкой струйкой в сок, тщательно размешивая, чтобы не образовались комки. Затем поставить емкость с «кашей» на небольшой огонь и, иногда помешивая, варить смесь до закипания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (902,'После закипания сделать огонь минимальным и варить «кашу» при периодическом помешивании в районе нескольких минут до полного загустения. Снять готовую массу с огня, разложить по формочкам, креманкам или десертным стаканчикам и убрать десерт «Изабелла» с виноградным соком в холодильник на несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (903,'Подготовим начинку:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (903,'В чашке смешиваем творог и яйцо. Можно немного посолить. Добавляем сыр и зелень. Все перемешиваем. Добавляем помидоры и снова перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (903,'Лаваш нужно нарезать широкими полосками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (903,'Столовой ложкой выкладываем начинку, подворачиваем края и сворачиваем пару раз. Один конвертик готов. Таким же образом готовим и все остальные.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (903,'Жарим на сухой сковороде и медленном огне буквально 2-3 минуты!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (904,'Заливаем кускус кипятком и оставляем на 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (904,'Обжариваем наши овощи, после того как крупа завариться, добавляем ее к овощам и далее добавляем мяту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (904,'Для соуса все ингредиенты отправляем в блендер и перемалываем. Соус подаем либо отдельно,либо поливаем сверху. Приятного аппетита.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (905,'У баклажана срезаем плодоножку и нарезаем вдоль пластинками толщиной примерно 4-5 миллиметров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (905,'Помидоры режем мелкими кубиками. Также мелкими кубиками нарезаем перец. Измельчаем лук и зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Выложить в салатницу, влить соус, перемешать.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11802,'Очистить плоды от кожуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (905,'Выкладываем лук на сковороду, добавляем помидоры и перец. Солим. И все нужно тушить одновременно до выкипания жидкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (905,'Баклажаны выкладываем на раскаленную сковороду с небольшим количеством масла. Солим и обжариваем с двух сторон на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (905,'На первый лист лаваша выкладываем овощи. Второй лист смазываем сметаной или майонезом и выкладываем баклажаны. Добавляем специи и свежую зелень. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (906,'Гречневую крупу обжарить на сковороде без масла, затем продукт измельчить в кофемолке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (906,'Изюм без косточек замочить в теплой воде на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (906,'Перемешать гречневую и льняную муку, добавить соль по вкусу и набухший изюм.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (906,'Влить кипяток, укутать теплой тканью для распаривания на час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (906,'Заправить готовую кашу маслом и медом, подать порционно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (907,'Льняную муку залить кипящей водой и посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (907,'Емкость завернуть в полотенце, подержать в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (907,'Натереть морковь, мелко нарезать репчатый лук, покрошить кубиками кабачки и тыкву.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (907,'Выложить овощную смесь в посуду с толстым дном, далее – слой каши и снова овощи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (907,'Продукты залить водой, она должна покрыть ингредиенты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (907,'Кастрюлю накрыть крышкой, поставить в духовку на сорок минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (907,'Другой способ приготовления – газовая плита.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (907,'Подать с домашним майонезом из сметаны, горчицы и яиц, тертого чеснока.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (908,'Залить горячим молоком льняную муку, перемешать, в каше не должно быть комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (908,'Добавить сахарный песок и нарезанную клубнику, бананы, киви.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (909,'Льняные хлопья залить чистой водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (909,'Оставить емкость в тепле на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (909,'Утром в кашу добавить подливку из растительного масла первого отжима, специй и соли.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (909,'Смесь взбить вилкой в пену.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (909,'Ингредиенты перемешать, выложить кашу в тарелки, посыпать рубленой зеленью кинзы, петрушки, укропа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (910,'Куриное филе пропустить через мясорубку, решетка – с крупными ячейками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (910,'Залить молоком и поставить на полчаса или больше для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (910,'Затем массу превратить в пюре при помощи блендера.','https:https://st.vkuso.ru/data/cache/thumb/55/638f81be162c655_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (910,'Добавить соль, специи, столовую горчицу, чеснок – по желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (910,'Выложить на стол коврик из соломки, поверх постелить пищевую пленку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (910,'Выложить пюре полосками при помощи пакета со срезанным уголком или кулинарного шприца.','https:https://st.vkuso.ru/data/cache/thumb/93/6e87a3305f06693_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (910,'Свернуть пленку, завязать кончики, желательно, чтобы внутри не остались пузырьки.','https:https://st.vkuso.ru/data/cache/thumb/06/36c12f9ee18cd06_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (910,'Сосиски положить в холодильник на час или два.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (910,'Отварить до готовности в кипящей воде.','https:https://st.vkuso.ru/data/cache/thumb/d1/ebcbcec2f3192d1_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (911,'Взбить вместе творог, сырые куриные яйца, сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (911,'Влить натуральный йогурт, немного ванильной эссенции, еще раз взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (911,'Всыпать муку, еще раз все взбить до однородного состояния. Должна получиться пышная масса, насыщенная воздухом.','https:https://st.vkuso.ru/data/cache/thumb/64/ca8a58684c52264_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (911,'Всыпать ягоды, свежие или замороженные, можно использовать землянику, малину, ежевику, чернику, голубику. Осторожно перемешать.','https:https://st.vkuso.ru/data/cache/thumb/12/21e740082d28612_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (911,'Порционные формочки смазать растопленным сливочным маслом, разложить смесь и поставить в духовой шкаф на 40 минут.','https:https://st.vkuso.ru/data/cache/thumb/32/995e288f4de5732_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (911,'Запеканка должна хорошо подрумяниться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (912,'В миску со сметаной всыпать манную крупу, хорошенько все перемешать и оставить на 1 час, чтобы манка набухла. В отдельной посудине взбить яйца с сахаром, добавить в яичный крем сметанно-манную смесь и тщательно все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'По желанию предварительно блюдо смазать чесноком.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (912,'Затем всыпать в жидкую массу муку, смешанную с разрыхлителем, и замесить негустое тесто. Форму для запекания смазать маслом, перелить в нее приготовленное тесто и разровнять поверхность. Выпекать манник в духовке, разогретой до 180 градусов, на протяжении 40-50 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (912,'Готовый классический манник на сметане достать из духовки, перевернуть на блюдо, слегка остудить и подать. Готовить ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (913,'Лососевый стейк натереть молотым перцем, солью, побрызгать лимонным соком, смазать оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (913,'Тем же маслом смазать форму для запекания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (913,'Выложить рыбу, готовить двадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (913,'Нарезать тонкими пластинками свежие шампиньоны, нашинковать репчатый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (913,'Лук обжарить на растительном масле до появления золотистой корочки, добавить грибы, потушить все вместе несколько минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (913,'Всыпать муку и соль по вкусу, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (913,'Долить сливки, перемешать еще раз, в обжарке не должно быть комочков.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (913,'Довести до кипения, огонь уменьшить, потушить продукты несколько минут. Соус должен быть густым.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (913,'Порубить зелень укропа, добавить в соус.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (913,'Перец и соль – по вкусу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (913,'Оставить для настаивания на несколько минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (913,'Выложить рыбу на тарелки, полить соусом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (914,'Филе рыбы натереть перцем и солью, любимыми приправами для рыбы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (914,'Обжарить на сухой сковороде муку, пересыпать в миску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (914,'Прогреть на той же сковороде сливки, всыпать муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (914,'Продукты перемешать до однородности, прогреть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (914,'Добавить сок половины лимона, рубленый укроп.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (914,'Рыбу обжарить на сковороде с двух сторон по несколько минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (914,'Выложить рыбу на тарелки, полить соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (915,'Промыть рыбу в проточной воде, обсушить, натереть перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (915,'Отдельно смешать сливки со сливочным маслом, тмином, перцем, солью, рубленым укропом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (915,'Порубить репчатый лук, добавить в соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (915,'Форму для выпекания застелить фольгой, выложить рыбу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (915,'Залить соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (915,'Фольгу завернуть, печь в течение получаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (915,'При подаче рыбу побрызгать лимонным соком, полить остатками соуса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (916,'Филе лосося хорошо промыть в холодной воде, обсушить, натереть приправами и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (916,'Налить немного масла на сковороду-гриль, прогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (916,'Время обжаривания рыбы – от десяти до пятнадцати минут. Продукт должен подрумяниться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (916,'Снять с огня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (916,'Прожарить отдельно муку до легкого потемнения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (916,'Добавить кусочек сливочного масла, влить сливки, прогреть до закипания. В соусе не должно быть комков.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (916,'Добавить красную икру, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (916,'Выложить рыбу на сковороду, влить соус, прогревать пять минут на тихом огне.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (916,'Огонь погасить, блюдо оставить на пятнадцать минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Креветки вымыть, очистить и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Выложить в небольшую мисочку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Добавить лимонный сок, натуральный мед, соль, перец, растительное масло. Продукты перемешать, оставить на полчаса для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Морепродукты вынуть, обсушить полотенцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Прогреть масло на сковороде, выложить креветки, жарить по две минуты с каждой стороны. Остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Покрошить чеснок, перемешать с маслом, оставить на два или три часа для настаивания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Хлеб для гренок нарезать кубиками, обжарить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Выложить на бумагу для выпекания, посолить и приправить специями.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Поставить на несколько минут в духовой шкаф.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Яйцо взбить, добавить любое растительное и оливковое масло, «Вустерский» соус, горчицу, филе анчоусов, лимонный сок, перец и соль.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Продукты хорошо перемешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Листья салата положить в холодную воду на час, жидкость слить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Листья обсушить и порвать руками.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (917,'Сверху – пшеничные гренки, тертый сыр. Украсить креветками, побрызгать соусом.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (918,'Креветки очистить и замариновать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (918,'Приготовить смесь из рубленого чеснока, перца, лимонного сока, оливкового масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (918,'Продукты перемешать, залить креветки, оставить на двадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (918,'Приготовить гренки из белого хлеба.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (918,'Продукт нарезать кубиками, обжарить на масле с чесноком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (918,'Креветки обжарить на сковороде, остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (918,'Твердый сыр натереть или тонко нарезать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (918,'Порвать руками листья салата.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (918,'Выложить на плоскую тарелку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (918,'Посыпать сухариками, сыром, украсить креветками, полить соусом «Цезарь».',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (919,'Печенье необходимо измельчить. Можно сломать руками или поместить печенье в пакет и пройтись по нему скалкой. Но важно, чтобы в общей массе были и мелкие крошки, и кусочки покрупнее.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (919,'В кастрюльку или ковшик выкладываем масло, сахар, какао, и выливаем молоко. Доводим до кипения тщательно размешивая. Получится наподобие горячего шоколада. Ждать, пока смесь загустеет не нужно, сразу снимаем с огня и добавляем к печенью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (919,'Далее все хорошо перемешиваем. Если вы понимаете, что смесь получилась жидкой, просто добавьте еще немного печенья. Если наоборот густой – добавьте немного молока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (919,'Выложите все в целлофановый пакет и сформируйте продолговатую колбаску. Тщательно уплотните, чтобы внутри не осталось пустот. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (919,'Поместите в морозильную камеру на пару часов. И можно подавать на стол.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (920,'Подготовить все ингредиенты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (920,'Отварить в подсоленной воде 5 минут.','https://vkuso.ru/data/cache/data/ce/d44dbb1377f15ce_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (920,'Сварить соус бешамель на основе муки, сливочного масла и молока.','https://vkuso.ru/data/cache/data/6c/f3f94e044b6b86c_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (920,'Разместить капусту в форму для выпекания.','https://vkuso.ru/data/cache/data/3f/f12e07e4e510e3f_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (920,'Сверху полить соусом и посыпать сыром.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (921,'Маринад.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (921,'Глазурь.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (921,'Делаем надрезы в свином битке. Смазываем маринадом и заполняем разрезы сыром, сладким перцем и авокадо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (921,'Связываем ниткой и заворачиваем в пергаментную бумагу и в фольгу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (921,'Жарим на углях 40-50 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (921,'Смазываем глазурью и жарим ещё пару минут с каждой стороны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (922,'Для маринада: перемешать лимонный сок, мед, оливковое масло, смесь перцев и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (922,'Смесью залить очищенные креветки на два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (922,'Порезать очищенные зубчики чеснока, залить рафинированным растительным маслом, оставить тоже на два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (922,'Белый батон или багет без корочки нарезать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (922,'Сушить при 200 градусах в духовом шкафу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (922,'Сухарики натереть чесноком и присыпать прованскими травами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (922,'Вынуть креветки из маринада, жарить по две-три минуты с каждой стороны на сухой сковороде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (922,'Яйца отварить всмятку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (922,'Желток вынуть, добавить к нему горчицу, чесночное и оливковое масло, «Вустерский» соус, соль – по желанию и необходимости.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (922,'Выложить листья салата в холодную воду на десять или двадцать минут, обсушить и порвать руками.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (922,'Выложить на блюдо, побрызгать соусом «Цезарь».',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (922,'Сверху – креветки, еще раз сбрызнуть соусом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (922,'Натереть сыр «Чеддер», посыпать салат.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (922,'Далее – гренки, салат перемешать.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12385,'Разложить в банки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (923,'Сыр «Пармезан» натереть на мелкой терке, добавить «Вустерский» соус, анчоусы, дижонскую горчицу, перец и греческий йогурт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (923,'Заправить рубленым чесноком, лимонным соком, влить оливковое масло, перемешать при помощи миксера или вручную.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (923,'Красный лук нарезать полукольцами, залить половиной соуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (923,'Авокадо очистить, нарезать дольками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (923,'Черри разрезать на четвертинки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (923,'Нарезать кубиками хлеб.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (923,'Сковороду смазать растительным маслом, креветки жарить на огне средней мощности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (923,'Добавить розмарин, перец и соль.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (923,'Хлеб жарить вместе с креветками, снять с огня.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (923,'Хлеб продолжать жарить до получения корочки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (923,'Салатный микс выложить на тарелку, добавить гренки, помидоры, маринованный лук.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (923,'Украсить креветками и авокадо.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (923,'Салат заправить соусом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (924,'Очищенные креветки отварить в воде готовности, подсолить, добавить черный перец-горошек, лавровый лист, нарезанный лимон, чеснок, гвоздику и немного томатной пасты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (924,'Любой твердый сыр нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (924,'Яблоко очистить от кожицы, мякоть также нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (924,'Полить лимонным соком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (924,'Очистить от шелухи арахис, порубить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (924,'Маслины нарезать половинками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (924,'Все продукты соединить, перемешать и заправить по вкусу майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (924,'Смесь выложить на блюдо с листьями салата, присыпать сухарями.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (925,'Рыбу нарезать кубиками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (925,'Очистить креветки, жарить на оливковом масле с чесноком и розмарином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (925,'Влить немного вина, выпарить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (925,'Снять продукт с огня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (925,'Зеленый салат полить соусом «Цезарь». Выложить на тарелку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (925,'Сверху – помидоры черри, разрезанные пополам, отваренные и разрезанные перепелиные яйца, лосось.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (925,'Сверху – розмарин, креветки, тертый сыр, гренки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'Чеснок мелко нарезать, перемешать с оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'Нарезать хлеб для гренок кубиками, посолить и побрызгать чесночным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'Перемешать, жарить на смазанной маслом сковороде с чесноком до золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'Для приготовления соуса выложить в блендер желтки, влить лимонный сок, винный уксус, ингредиенты перемешать венчиком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'Влить оливковое масло, массу взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'Сменить насадку на ножи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'В чашу добавить сыр «Пармезан», анчоусы, каперсы, зубчик чеснока. Смесь довести до однородного состояния.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'Влить холодную воду, перемешать, поперчить, соль – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'Креветки вымыть и обсушить, очистить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'На сковороду положить нарезанный чеснок, обжарить в течение десяти-пятнадцати секунд, добавить подготовленные креветки, соль, перец, лимонный сок. Жарить до готовности.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'Стейк из тунца посолить и поперчить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'Жарить на растительном масле до готовности.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'Рыбу остудить и нарезать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'Листья «Романо» порвать руками крупными кусочками, застелить блюдо.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'Выложить гренки, сбрызнуть соусом, перемешать, посыпать сыром «Пармезан».',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (926,'Сверху выложить рыбу и креветки.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (927,'Куриные грудки нарезать небольшим кубиком, сыр натереть на мелкой терке, нарезать укроп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (927,'Смешать все ингредиенты с глубокой миске и тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (927,'Обжарить на котлетки с двух сторон на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (928,'Куриное филе нарезать кубиком.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (928,'Смешать с молоком и перебить в блендере.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (928,'Вареную свеклу перебить с растительным маслом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (928,'Все смешать и заправить фарш.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (935,'Добавляем натёртый сыр и ещё раз перемешиваем. Паста готова!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (928,'Завернуть в пищевую пленку, создавая форму сосисок.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (929,'Нарезать средние по величине помидоры на одинаковые по толщине кружочки, чтобы они равномерно пропитались маринадом и были одинаково вкусны. Приготовить из всех представленных ингредиентов маринад, тщательно его перемешать и хорошо промазать каждый кружочек томата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (929,'Сложить башенки из трех колечек, слегка сдавить, переложить на широкое блюдо, поставить закусочные помидоры по-итальянски за 30 минут хорошо пропитаться в холодильник. В это время порезать зелень, достать закуску, присыпать зеленью и поставить охлажденные ароматные  помидорчики сразу на стол, в летнюю жару это придется, как нельзя кстати',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (930,'Белый хлеб нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (930,'Обжарить на сковороде с маслом и давленым чесноком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (930,'Для соуса перемешать горчицу, майонез, соевый соус, мелко нарезанный чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (930,'Нарезать или натереть сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (930,'Порвать руками или нарезать листья салата.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (930,'Выложить на плоское блюдо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (930,'Сверху – сухарики, сыр, морепродукты, полить соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (931,'Застелить плоскую тарелку листьями зеленого салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (931,'Сверху – тертый свежий огурец, тертое отваренное яйцо, тертый сыр «Пармезан» или  аналогичный.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (931,'Полить майонезом или соусом «Цезарь».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (931,'Выложить крабовые палочки, нарезанные соломкой, тертое яйцо, еще раз побрызгать соусом «Цезарь».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (931,'Посыпать блюдо тертым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (931,'Далее – крабовые палочки, нарезанная зелень укропа или петрушки, сухарики и отваренные креветки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (932,'Куриные яйца отварить, очистить и покрошить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (932,'Свежий огурец очистить от кожуры и нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (932,'Порвать руками зеленый салат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (932,'Мелко порезать крабовые палочки и отваренные креветки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (932,'Ингредиенты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (932,'Блюдо сбрызнуть свежим соком лимона, приправить майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (933,'Приготовить маринад для креветок из давленого чеснока, соуса «Песто», лимонного и лаймового сока, черного молотого перца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (933,'Залить креветки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (933,'Приготовить соус из горчицы, майонеза, рубленого чеснока, соуса «Песто» и оливкового масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (933,'Ингредиенты взбить венчиком, подлить куриный бульон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (933,'Всыпать тертый сыр «Пармезан».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (933,'Соль – по вкусу и желанию.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (933,'Можно влить белое сухое вино.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (933,'Листья зеленого салата порвать большими кусочками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (933,'Помидоры очистить от кожуры, вынуть семенные камеры, мякоть нарезать небольшими кубиками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (933,'Разрезать хлеб для тостов на треугольники, обжарить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (933,'Листья салата перемешать с готовым соусом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (933,'Креветки и тонко нарезанный бекон обжарить на гриле.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (933,'Ингредиенты перемешать или выложить слоями.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (934,'Приготовить соус из мандаринового сока, майонеза и специй.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (934,'Разрезать отваренные креветки на несколько частей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (934,'Нашинковать стебли сельдерея.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (934,'Очистить и мелко нарезать яблоки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (934,'Очистить, разобрать дольками мандарины. Вынуть косточки, если они есть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (934,'Порубить очищенные грецкие орехи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (934,'Продукты перемешать, добавить мандариновую заправку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (934,'Выложить салат порциями.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (935,'На сливочном масле обжарьте мелко нарезанный лук в течении 1 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (935,'Добавляем нарезанное кубиками куриное филе, соль, перец по вкусу. Обжариваем ещё 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (935,'Добавляем брокколи, пасту, воду, молоко 
(Если использовать только воду, паста не будет иметь характерного сливочного вкуса)
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12425,'Ингредиенты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (936,'Мелко нарезаем лук, морковь, чеснок. Жарить на растительном масле в течении 4-5 минут. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (936,'Добавляем горошек (я использовала консервированный) в конце жарки',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (936,'Картофель разрезаем пополам (чтобы быстрее сварился) и варим до готовности
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (936,'Делаем картофельное пюре. С отваренного картофеля сливаем воду, добавляем молоко и растопленное сливочное масло (при желании можно добавить яйцо).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (936,'На противень выкладываем фарш с овощами, а сверху равномерно распределяем картофельное пюре
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (936,'Достаём пирог и посыпаем натёртым сыром
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (937,'Для начала нужно подготовить печенье. Ломаем печенье в блендер, и далее при помощи блендера измельчаем печенье в крошку. Печенье которое не измельчилось в крошку, можно измельчить еще раз, или же оставить для десерта.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (937,'1 из 4 бананов, нужно порезать на кружочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (937,'В миску перекладываем творог, и ломаем туда 3 банана и все хорошо перемешиваем до однородной массы. Далее, добавляем 3 ч.л сахара, и часть крошки печенья (оставьте немного) снова перемешиваем. Далее разделяем творожно банановую муссу с печеньем, на две части. 1 часть убираем в сторону. А ко 2 части добавляем 3 ч.л какао, перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (937,'Далее, нам нужны стаканы, или бокалы, или креманки. На дно укладываем кусочки печенья, которые не измельчились, и банан. Далее примерно до середины добавляем творожно банановую муссу с какао, по бакам добавляем бананы, далее уже добавляем творожно банановую массу, но уже ту в которой нет какао. У меня получилось 4 стакана. В последнею очередь нужно посыпать мусс крошкой печенья которая осталась. И если остался банан то его тоже можно положить сверху.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (937,'Можно положить в холодильник на 30 минут, но это не обязательно!
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (938,'Замочить желатин в воде и оставить набухать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (938,'Яичные желтки взбить миксером до бела. Добавить ванилин и влить теплое молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (938,'Поместить молочную массу на водяную баню и прогревать до загустения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (938,'Смешать приготовленную массу со сметаной, разлить по креманкам и поместить в холодильник для застывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (938,'Перед подачей дополнить каждый десерт ложкой джема.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (939,'Очистить картофель, отварить до полной готовности в воде с солью и лавровым листом.','https:https://st.vkuso.ru/data/cache/thumb/c0/8159ba466395dc0_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (939,'Нашинковать мелко лук, обжарить до прозрачности, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/d9/f835471320dcdd9_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (939,'Добавить фарш, подсолить, поперчить, перемешать, жарить до готовности.','https:https://st.vkuso.ru/data/cache/thumb/21/43bc2630224e321_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (939,'Готовый отварной картофель размять в пюре.','https:https://st.vkuso.ru/data/cache/thumb/65/11fa5fdcd434165_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (939,'Половину его переложить в форму, смазанную маслом, поверх выложить фарш.','https:https://st.vkuso.ru/data/cache/thumb/74/588dad9ab55bf74_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (939,'Прикрыть оставшимся картофелем, разровнять, промазать сметаной.','https:https://st.vkuso.ru/data/cache/thumb/81/9aaf9b96c7bf981_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (939,'Присыпать верх картофельной запеканки с говяжьим фаршем сыром, отправить на 40 минут в духовку, прогретую до 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/62/aa3661974edf562_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (940,'Манку залить на полчаса кефиром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (940,'Взбить сахар с яйцом, положить творог, тщательно перемешать, добавить мелко натертую морковь, еще раз все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (940,'Заполнить массой смазанную маслом форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (940,'Запекать творожно-морковную запеканку с кефиром в прогретой до 200 градусов духовке полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (941,'Размять вилкой пару бананов до состояния пюре.','https:https://st.vkuso.ru/data/cache/thumb/71/98198497437b771_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (941,'Добавить сметану, размешать, влить ром, перемешать, дать постоять.','https:https://st.vkuso.ru/data/cache/thumb/81/1c74b2aad6a2c81_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (941,'Перемешать просеянную муку с содой, корицей и порошком какао.','https:https://st.vkuso.ru/data/cache/thumb/42/5f7ee3fc8513942_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (941,'Взбить сахар и яйца до состояния пены, добавить смесь бананов, всыпать остатки муки, тщательно перемешать.','https:https://st.vkuso.ru/data/cache/thumb/c4/059e24a53c63fc4_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12599,'Натереть твердый сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (941,'Заполнить этой массой форму, смазанную маслом.','https:https://st.vkuso.ru/data/cache/thumb/1a/0618f9b54b6121a_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (941,'Выпекать банановый кекс с ромом и корицей 40 минут в духовке с температурой 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (942,'Достать заранее масло, чтобы было удобнее работать, дать постоять в комнате до полного размягчения. Смешать его со сметаной и перетертыми с сахаром яйцами. Постепенно, перемешивая после каждого добавления, всыпать просеянную муку с добавлением разрыхлителя и небольшого количества соли, вымесить тесто до состояния пластичности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (942,'Для вкусной начинки протереть сквозь сито творог, всыпать сахар, добавить манку, сметану, чуть муки и ванильный сахар вбить яйцо, очень хорошо перемешать, начинка должна стать нежной и однородной, как густая паста. Колобок теста раскатать в 3 мм пласт, формочкой с диаметром в 10 см вырезать кружочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (942,'Положить на каждый примерно по столовой ложке (с небольшой горкой) начинки, сложить вдвое, место соприкосновения полукружий слегка сдавить. Переложить сочники на подготовленный металлический лист.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (942,'Влить в кружку к желтку чуть молока, разболтать, смазать верхушку выпечки, для получения в дальнейшем аппетитной и манящей светло-золотистой поверхности. Отправить пышные творожные сочники в духовой шкаф минут на 25, температуру поддерживать в районе 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (943,'Порезать сыр на брусочки.','https:https://st.vkuso.ru/data/cache/thumb/57/ffaa27a9164ff57_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (943,'Перемешать масло с соевым соусом, раздавленным прессом чесноком и травами.','https:https://st.vkuso.ru/data/cache/thumb/64/c50529b34cc8564_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (943,'Смешать с сыром, дать пропитаться и обжарить 5 минут на сковороде.','https:https://st.vkuso.ru/data/cache/thumb/83/208b98818f94b83_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (943,'Разрезать листы нори на две части, погрузить на пару-тройку секунд в соус для размягчения, обернуть в них каждый кусочек сыра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (943,'Адыгейские сырные палочки в водорослях обжарить с обеих сторон до появления коричневой корочки.','https:https://st.vkuso.ru/data/cache/thumb/77/2442c2377c67b77_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (944,'Порезать лимон с кожурой на крупные куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (944,'Перемешать все ингредиенты, переложить в банку с винтовой крышкой, убрать в холодное затемненное место на две недели, ежедневно взбалтывать.','https:https://st.vkuso.ru/data/cache/thumb/6b/a3c1695703dd56b_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (944,'По окончанию срока процедить молочный ликёр с лимоном через марлю 3 раза, а можно и больше, тогда ликер будет более чище.','https:https://st.vkuso.ru/data/cache/thumb/9b/224041cdb072d9b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (945,'Чечевицу залить водой, довести до кипения. Варим 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (945,'Морковь и лук очистить и нарезать небольшими кубиками. В кастрюле разогрейте масло, обжарьте морковь 3 минуты на среднем огне, перемешивая. Затем добавить лук и готовить еще 3 минуты, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (945,'Куриную печень нарезать произвольными кусочками. Добавить в кастрюлю к луку и моркови, обжариваем 5 минут, перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (945,'Влейте куриный бульон, доведите до кипения, добавьте чечевицу, лавровый лист, соль и перец. Варим 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (946,'Картофель очистить и отварить до готовности. Затем слить воду и остудить при комнатной температуре. Нарезать на дольки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (946,'Помидоры вымыть и нарезать дольками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (946,'Готовим заправку. Смешать бальзамический уксус, оливковое масло и зернистую горчицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (946,'В тарелку нарвать листья салата, полить заправкой. Выложить помидоры и картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (946,'Кусочки консервированного тунца размять вилкой, отправить в тарелку с салатом, посыпать консервированной фасолью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (947,'Подготовить все продукты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (947,'Заправить соль, перцем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (947,'Сыр натереть на терке.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (947,'Затем яичную смесь и сверху начинку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (948,'Баклажаны мою, отрезаю хвостики и нарезаю их тонкими пластинами. Подготовленные баклажаны кладу в холодную соленую воду на 30 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (948,'Подготовлю помидоры. Надрезаю их, заливаю горячей водой и оставляю на 30 секунд, затем перекладываю в холодную воду. Снимаю с них кожицу. И нарезаю мелкими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (948,'Нарезаю листья базилика.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (948,'Подготовленные продукты отправляю в посуду и ставлю тушиться в собственном соку солю, перчу. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (948,'Сливаю воду с баклажанов, промакиваю их салфеткой, обваливаю в муке и обжариваю до золотистого цвета с обеих сторон. Выкладываю на салфетку, даю лишнему жиру стечь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (948,'Форму для запекания смазываю масло, на дно наливаю немного подготовленного соуса, затем кладу баклажаны, покрываю их тонко нарезанными ломтиками моцареллы.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (948,'Посыпаю натертым сыром, по рецепту идет пармезан, но я не люблю его, поэтому использую любой твердый сыр.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (948,'Последним слоем выкладываю баклажаны, поливаю их соусом и посыпаю натертым сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (948,'Ставлю запекаться в разогретую духовку до 180 градусов на 30 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (948,'Готовые баклажаны достаю, нарезаю на порции и выкладываю на тарелку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (949,'Натереть на терке очищенный кабачок, подсолить, убрать в холодильник на четверть часа, чтобы выделился сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (949,'Нашинковать зелень укропа и петрушки, добавить измельченный чеснок, смешать с взбитым яйцом и черным перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (949,'Отжать кабачки от сока, смешать с яичной смесью, всыпать муку, перемешать. Чашу мультиварки смазать маслом, выложить полученную смесь, выставить режим «Выпечка».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (949,'Через полчаса оладьи из кабачка в мультиварке будет готовы, подавать со сметаной или кетчупом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (950,'Включить для разогрева до 175-210 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (950,'В глубокой миске перемешать топленое масло, пахту, сахар, яйца, ванилин.','https:https://st.vkuso.ru/data/cache/thumb/ac/0755f423eee2cac_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (950,'Когда растворится сахар добавить подсоленную муку и пекарский порошок, тщательно перемешать до образования эластичного теста, разделить его на 7 кусочков, разложить по мисочкам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (950,'Добавить к каждой порции разные красители, хорошо перемешать до равномерного прокрашивания.','https:https://st.vkuso.ru/data/cache/thumb/35/3453b8e11f95135_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (950,'Подготовить формочки для мини-пончиков «Радуга» в духовке, смазать маслом, заполнить разноцветными кусочками кондитерский мешок (каждый цвет в свой).','https:https://st.vkuso.ru/data/cache/thumb/20/19d225ae9cbaf20_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (950,'Выдавить по кругу из каждого мешка по небольшой дуге до замыкания круга.','https:https://st.vkuso.ru/data/cache/thumb/7b/6c5ad4fe6d3f17b_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (950,'В прогретой духовке выпекать пончики 4-8 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (950,'Дать остыть прямо в формочках около 5 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (950,'Приготовить из молока с ванилью и сахарной пудры глазурь.','https:https://st.vkuso.ru/data/cache/thumb/a5/42d0c7f94d949a5_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (950,'Смазать каждое колечко, а можно вылить ее в креманку и подать к мини-пончикам.','https:https://st.vkuso.ru/data/cache/thumb/44/c09abb17c28fa44_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Измельчить печенье блендером или сложить в пакет и прокатать скалкой, перемешать с маслом, добавить яйцо, перемешать еще раз до образования маслянистой крошки, убрать на 5 минут в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Прогреть духовку до 200 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Взять форму 20 см в диаметре, выстлать пергаментом, заполнить охлажденным тестом, сформовать высокие бортики, отправить на полчаса в холодильник или, при недостатке времени, на 10 минут в морозильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Достать форму, выпекать основу для творожного чизкейка из печенья с двойной глазурью в уже достаточно прогретой духовке 8–10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Достать, дать остыть, довести температуру духовки до 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Для начинки взбить блендером творог, сахар, яйца, влить сметану, взбить все вместе до исчезновения комочков.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Заполнить начинкой основу, готовить на водяной бане в духовке около 40–50 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Вынуть из духовки, сделать круг вдоль стенки ножом, чтобы отделить корж и не дать ему треснуть, дать хорошо остыть, убрать на 4 часа в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (955,'Перемешать масло, измельченный чеснок и травы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Обернуть форму фольгой, поставить в сковороду, наполненную горячей водой, чтобы она доходила до половины формы, поместить в духовку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Когда творожник хорошо остынет полить его глазурью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Для ее приготовления в сотейник влить сливки, положить масло и сгущенку, прогреть, постоянно помешивая до тех пор, пока масса не превратится в жидкость.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Дать остыть вылить на творожник, разровнять, дать хорошо застыть в холодильнике.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Приготовить другую глазурь из растопленного шоколада, сливок, масла.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Дать остыть, вылить сверху первой глазури, дать застыть.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (951,'Осторожно вынуть творожник из формы, подать к столу.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (952,'В широкую миску всыпать горкой муку, сделать на вершине углубление, влить в него полстакана нагретой воды, перемешать, а потом добавить одну треть холодной воды с маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (952,'Перемешать до образования эластичного и мягкого теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (952,'Взять небольшую порцию, раскатать в длинную колбаску, разрезать на кусочки по размеру крупной вишни.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (952,'Раскатать из каждого тонкий кружок примерно в 5 см.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (952,'Из порубленных креветок и ростков бамбука приготовить фарш, влить в него 4 ст. л. воды и добавить остальные ингредиенты, исключив только кукурузную муку, вымесить до однородного состояния.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (952,'Всыпать по порциям кукурузную муку, перемешать, разделить на порции.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (952,'По центру каждого сочня выложить начинку, хорошо скрепить пальцами края.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (952,'Уложить дим-самы с креветками и ростками бамбука на влажную салфетку, которая выстлана на дно пароварки, варить при сильном нагреве 5 минут, блюдо подавать на стол горячим.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (953,'Залить дрожжи теплым молоком, всыпать сахар, вбить яйцо, добавить масло, муку, соль, вымесить эластичное тесто, обернуть его пленкой, убрать на 3 часа в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (953,'Из подошедшего теста раскатать пласт чуть больше 0,5 см толщиной, выстлать его полосками лосося, отступив от края примерно по 3-4 см.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (953,'Прикрыть вторым пластом теста, тщательно залепить, чтобы получился валик.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (953,'Нарезать его полосками шириной по 4 см, повернуть каждый кусочек, чтобы рыба оказалась сверху.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (953,'Остатки рыбы порезать на кусочки и положить по центру пирога.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (953,'Уложить по верху кружочки помидоров и перца, поперчить, присолить, прикрыть кружочками моцареллы, присыпать каперсами, дать постоять 25 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (953,'Выпекать рыбный пирог с лососем и моцареллой полчаса в прогретой заранее до 180 градусов духовке до появления чуть коричневатой корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (953,'За 10 минут до окончания запекания смазать верх разболтанным желтком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (954,'Баклажаны порезать на ломти, присолить, дать постоять пару часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (954,'Разогреть в сотейнике 40 мл масла, обжарить измельченный чеснок, добавить кусочки помидора, дать смеси закипеть, прогреть четверть часа, поперчить, подсолить, всыпать базилик, убрать сотейник с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (954,'Натереть сыр, смешать с панировочными сухарями, поместить в широкую миску, яйца – в другой, мука – в третьей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (954,'Духовку прогреть до 180 градусов, на лист для выпечки 20 мл масла, обсушить ломтики баклажана полотенцем (бумажным).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (954,'Обмакнуть каждый сначала в муку затем в яйца, а потом в смесь сухарей с сыром, разложить на лист, полить маслом, поставить в духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (954,'Запекать баклажаны с чесноком в сыре около 20 минут, периодически переворачивая, остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (954,'Выложить на дно кастрюли немного соуса, разложить треть ломтиков баклажанов, присыпать половинками сыра Моцарелла, присыпать стружкой пармезана.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (954,'Присыпать третьей частью натертого сыра ломтики баклажанов, полить соусом, присыпать оставшейся стружкой пармезана.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (954,'Выложить следующий слой ломтиков баклажана, полить соусом, присыпать оставшейся сырной стружкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (954,'Запекать баклажаны примерно 35 минут при 180 градусах.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (954,'Достать из духовки, дать 10 минут остыть и подать к столу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (955,'Разморозить готовое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (955,'Выстлать дно корзины мультипечи пергаментом, смазанным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (955,'Заполнить тестом, разровнять его, из излишков сделать бортики, чуть смазать их водой, промазать ароматным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (955,'Уложить сверху порезанную моцареллу, сыр с плесенью, присыпать стружкой пармезана и эмменталя.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (955,'Поместить слоёный пирог «4 сыра» с прованскими травами на 10 минут в мультипечь с температурой 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (955,'Достать, нарезать и подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (956,'Порезать на тонкие дольки очищенные яблоки, чуть присыпать мукой и корицей с мускатным орехом, аккуратно перемешать.','https:https://st.vkuso.ru/data/cache/thumb/e8/d0cf65ce8f9ebe8_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (956,'Взбить сахар с яйцами до побеления с помощью миксера, добавить цедру лимона и растопленное масло, взбить все на малой скорости.','https:https://st.vkuso.ru/data/cache/thumb/27/35af4c673837727_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (956,'Всыпать в смесь муку, тщательно перемешать до получения теста похожего на густую сметану.','https:https://st.vkuso.ru/data/cache/thumb/80/28902ec20893e80_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (956,'Промазать форму маслом, заполнить на половину тестом.','https:https://st.vkuso.ru/data/cache/thumb/06/9bad02a99232e06_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (956,'Далее выложить яблоки, прикрыть тестом.','https:https://st.vkuso.ru/data/cache/thumb/ae/53e0e8ba5df98ae_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (956,'Как вариант можно сразу перемешать тесто с яблоками и выпекать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (956,'Поместить форму с заливным яблочным пирогом «Шарлатанка» примерно на 50 минут в прогретую до 180 градусов духовку.','https:https://st.vkuso.ru/data/cache/thumb/36/d8c1dff923e2236_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (956,'Вынуть пирог из духовки, присыпать сахарной пудрой и подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (957,'Замочить в теплой воде курагу, порубить в блендере вместе с орехами, перемешать с размятым творогом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (957,'Скатать из массы небольшие шарики, убрать в холодильник на пару часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (957,'Поломать шоколад, растопить его на водяной бане, влить молоко, очень хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (957,'Убрать с плиты, обмакнуть в нее шарики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (957,'Убрать творожные шарики с курагой и орехами в шоколаде в холодильник до полного застывания шоколадной корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (958,'Поместить в блендер творог, половину сливок, кусочки банана, мед (сахарную пудру), ванильный сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (958,'Тщательно перемешать до однородного состояния, по консистенции должно напоминать хорошую сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (958,'Переложить массу в контейнер, поставить банановое мороженое из творога и сливок в морозилку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (958,'Для мягкого мороженого держать 3 часа, для обычного – 5 часов (или оставить в морозилке на всю ночь).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (959,'Приготовление теста. Муку смешаем с солью и сахаром. Влить ледяную воду, уксус и добавить охлажденное сливочное масло. Перемешать все до однородной массы и замесить тесто в шар. Отправить в холодильник, пока готовится начинка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (959,'Лук нарезать тонкими четвертькольцами. В сковороде разогреть оливковое масло, выложить лук и посыпать сахаром (1 ч. л.). Постоянно помешивая, доводим до золотистого-коричневого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (959,'Натереть пармезан и полутвердый сыр на мелкой терке. Добавить в сыр майонез и перемешать, поставить эту массу в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (959,'Помидоры нарезать на кольца толщиной 3-4 мм. Отложить немного колечек на украшение (около 20 шт.), положить их на салфетку, чтобы стекал сок. Оставшиеся помидоры посолить (1/2 ч.л.) и посахарить (1 щепотка), откинуть на дуршлаг на 20 минут, чтобы стекал сок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (959,'На противень расстелить фольгу, выложим томаты из дуршлага (те что на салфетке пока не трогаем). Запекаем под грилем 20 минут при температуре 200 градусов. Остудить 5 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (959,'Остывшие помидоры добавляем к луку, также добавить сушеный тимьян, мелконарезанный базилик, оливковое масло (1 ч.л.), перец (1/3 ч.л.), бальзамический уксус.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (959,'Немного раскатать тесто (у меня форма 22 см), а далее распределить по форме руками, формируя борты, наколоть дно вилкой, чтобы не вздулось при выпекании. Выпекаем в разогретой духовке 15 минут при температуре 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (966,'Зубки чеснока разрезать пополам, обжарить в масле, добавить листики петрушки.','https:https://st.vkuso.ru/data/cache/thumb/ce/98db3ff33580dce_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (966,'Развести ложку бульонного кубика стаканом кипятка, залить в кастрюлю, долить остаток воды, варить примерно 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (959,'Достаем тесто из духовки, выкладываем начинку из томатов с луком. Достаем сырную начинку и раскатываем ее на пекарской бумаге. Сырной лепешкой накрываем томатную начинку (не выходить за борты основы пирога). Украшаем ломтиками помидоров, которые остались на салфетке. Выпекаем 30 минут при 180 градусов. На готовый пирог помолоть черный перец.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (960,'Нарезать томаты, болгарский перец, перец чили и корень хрена.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (960,'В большую кастрюлю добавить томаты. Перемолоть погружным блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (960,'Тоже самое повторить с болгарским перцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (960,'Добавить в кастрюлю перец чили, корень хрена, чеснок, сахар, соль, белый молотый перец и кориандр. Все тщательно перемолоть. Аджика готова.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (961,'Размягченное сливочное масло взбить миксером с сахаром (2 ст. ложки оставить на посыпку пирога).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (961,'Добавить по одному яйцу, продолжая взбивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (961,'Муку смешать с разрыхлителем и добавить ее в яично-масляную смесь. Замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (961,'Форму (у меня диаметр формы 24 см) смазать сливочным маслом и выложить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (961,'Разровнять и выложить сверху половинки слив срезом вниз.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (961,'Оставшийся сахар смешать с корицей и посыпать пирог сверху. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (962,'Баклажаны чищу вдоль полосками - зеброй, подготовленные таким способом баклажаны нарезаю толстыми кружками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (962,'Помидоры можно натереть на терке, а можно просто взбить блендером, что я и делаю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (962,'Наливаю на разогретую сковороду подсолнечное масло, добавляю сюда куркуму, перемешиваю и обжариваю баклажаны до оранжевой корочки с обеих сторон.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (962,'Выливаю в кастрюлю подготовленную томатную массу, нагреваю и кипячу ее в течение 3-5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (962,'Добавляю в томат чеснок и обжаренные баклажаны. Солю. Перчу. Накрываю крышкой и тушу на среднем огне до готовности 10-15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (962,'Готовые баклажаны выкладываю в глубокую посуду.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (963,'До готовности отварить картофель, морковь и яйца, после чего все остудить и очистить. Воду вскипятить, слегка подсолить, положить в нее куриное филе и варить мясо после закипания 20-30 минут. Небольшими пластинками нарезать грибы, очищенный лук измельчить и обжарить вместе с грибами на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (963,'Натереть картофель и морковь на крупной терке, яйца на мелкой. Порвать на маленькие кусочки и порезать небольшими кубиками мясо курицы. На плоское блюдо выложить в форме 5-6 морковок тертый картофель и смазать его майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (963,'Далее выложить луково-грибную массу и также промазать ее майонезом. Затем на грибы уложить куриное филе, поверх которого распределить вареные яйца. Украсить салат «Морковки» с курицей и грибами со всех сторон тертой морковью и петрушкой (она сыграет роль хвостиков морковок).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (964,'Отварить пасту до полуготовности, сварить грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (964,'Измельчить лук, обжарить на масле в сотейнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (964,'Всыпать грибы, тонкие ломтики куриного филе, залить белым вином, слегка выпарить.','https:https://st.vkuso.ru/data/cache/thumb/49/921f233f7e48f49_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (964,'Положить в сотейник половинки черри, влить несколько ложек воды, в которой варилась паста, проварить пару-тройку минут.','https:https://st.vkuso.ru/data/cache/thumb/20/b9e91251288be20_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (964,'Готовую пасту прогреть с соусом пару минут.','https:https://st.vkuso.ru/data/cache/thumb/17/412edcd442ef317_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (964,'Разложить пенне с куриным филе, грибами и пармезаном по тарелкам, присыпать натертым сыром и измельченной петрушкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (965,'Заварить кофе в молоке, добавить порошок какао, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (965,'Растопить кусочки шоколада в микроволновке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (965,'Взбить масло и сахар ложкой до однородности, влить кофейную смесь, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (965,'Добавить яйца, жидкий шоколад, бренди и муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (965,'Тесто хорошо вымесить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (965,'Заполнить им формочки, выпекать шоколадный кекс с бренди примерно треть часа в разогретой духовке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (966,'Уложить кусочки батона в форму, побрызгать маслом, присыпать тертым сыром.','https:https://st.vkuso.ru/data/cache/thumb/4b/4e52e1b7b50e04b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (966,'Запекать до появления корочки светлокоричневого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (966,'Взбить блендером чеснок и зелень, поставить на плиту.','https:https://st.vkuso.ru/data/cache/thumb/70/abdc107b8f0d570_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (966,'Взбить вилкой бульон с желтками, влить тоненькой струйкой в чесночный суп на овощном бульоне с крутонами, проварить до сгущения.','https:https://st.vkuso.ru/data/cache/thumb/f4/09d817ea86ceaf4_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (966,'Подать к столу с крутонами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (967,'Для приготовления блинов перемолоть овсяные хлопья в муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (967,'Взбить сырое яйцо с солью, подлить воду, теплый кефир, всыпать муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (967,'Ингредиенты взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (967,'Печь блинчики на сухой сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (967,'Для приготовления начинки растереть творог с яйцом, ванилином и подсластителем, всыпать курагу, нарезанную кусочками, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (967,'Начинку выложить на блин, свернуть его в виде рулета.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (967,'Круглую форму для выпекания смазать маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (967,'Блинчики с начинкой выкладывать по спирали.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (967,'Для приготовления заливки сырые куриные яйца взбить с еще одной порцией подсластителя, влить натуральный йогурт, перемешать до однородности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (967,'Залить пирог, поставить форму в заранее разогретый духовой шкаф. Время приготовления – от 30 до 35 минут, температура – 190 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (968,'Растереть творог с яйцами, добавить мякоть помидоров, нарезанную кубиками, зелень, перец, тертый твердый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (968,'Массу выложить в формочки для кексов, идеальный вариант – силикон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (968,'Заполнить емкости доверху.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (968,'Поставить изделия на 20 минут в духовой шкаф, температура приготовления – 200 градусов. Запеканки должны зарумяниться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (968,'Вынуть, немного остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (969,'Взбейте размягченное при комнатной температуре масло с майонезом, добавьте яйцо, соль, сахар и еще раз взбейте до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (969,'Добавьте муку, предварительно просеянную через сито вместе с разрыхлителем, и замесите гладкое тесто. Положите тесто в кулинарный мешок с фигурной насадкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (969,'Выстелите противень пергаментом и отсадите небольшие печенья на расстоянии 1 см друг от друга.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (969,'Выпекайте в разогретой до 200°С духовке, пока не зарумянятся, 15–20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (970,'Вырезать всю середину из багета.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (970,'Смешать сыр, творог и яйца и сделать начинку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (970,'Поместить сырную начинку во внутрь багета.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (970,'Запечь в духовке 5 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (971,'Куриные грудки отварить, мясо нарезать кубиками небольшого размера или прокрутить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (971,'Очистить и мелко нарезать репчатый лук, обжарить на масле до румяного цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (971,'Добавить в мясо, посолить и поперчить по вкусу, добавить рубленую зелень петрушки, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (971,'Кабачковую мякоть натереть, если кожица грубая – ее лучше очистить, семена удалить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (971,'Влить обезжиренный кефир, вбить сырое куриное яйцо, всыпать цельнозерновую муку, вымешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (971,'Сковороду хорошо смазать оливковым маслом, нагреть, вылить порцию кабачкового теста, равномерно распределить по поверхности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (971,'Как только масса немного схватится – выложить начинку на край, аккуратно поддеть лопаткой вторую половинку блина, накрыть мясо.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (971,'Прижать лепешку так, чтобы края сцепились, жарить до румянца.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (972,'Груши хорошо вымыть, обсушить и разрезать на четыре или шесть частей.','https:https://st.vkuso.ru/data/cache/thumb/d9/2f53c724b2d52d9_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (972,'Налить немного воды в небольшую кастрюлю, поставить фрукты на огонь, варить до мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (972,'Измельчить при помощи блендера или обычной толкушкой. Если мармелад готовить из ягод – вода может не потребоваться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12608,'Нарезать небольшими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (972,'Мякоть протереть через сито.','https:https://st.vkuso.ru/data/cache/thumb/27/812dc5a9b5b8127_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (972,'Готовое пюре снова переложить в кастрюлю и поставить на огонь, всыпать сахар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (972,'Варить в течение пяти минут до растворения сахарного песка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (972,'Замочить в воде желатин на несколько минут, влить в грушевое пюре и перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (972,'Если желатин полностью не растаял – можно немного прогреть на огне, но не кипятить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (972,'Массу вылить в форму, застеленную бумагой для выпекания, дождаться застывания.','https:https://st.vkuso.ru/data/cache/thumb/f5/0ff1bc2c7bb9af5_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (972,'Доску присыпать сахарным песком, выложить желе, посыпать еще одной порцией сахара с другой стороны.','https:https://st.vkuso.ru/data/cache/thumb/a1/50170993c6018a1_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (972,'Нарезать конфеты острым ножом или формочками для печенья. Подать к чаю или другому горячему напитку.','https:https://st.vkuso.ru/data/cache/thumb/2a/f0ee48c4ca3332a_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (973,'Креветки промыть и очистить, чеснок очистить и мелко порубить. В сковородке на слабом огне разогреть оливковое масло, добавить паприку, хлопья красного перца и рубленый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (973,'Обжаривать чеснок в районе 1 минуты, пока он не начнет источать аромат. Затем огонь увеличить, добавить к чесноку подготовленные креветки, залить их вином и лимонным соком и перемешать. Обжаривать креветки примерно 3-5 минут: они должны пропечься и приобрести оранжево-розовый оттенок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (973,'Готовые креветки посолить, поперчить и хорошо перемешать. Подавать жареные креветки с чесноком и петрушкой, выложив на большое блюдо или порционные тарелки. При желании креветки перед подачей можно слегка остудить и украсить дольками лимона или апельсина.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (974,'Картофель очистить и быстро натереть на терке, пока мякоть не потемнела. Если сорт такой, что быстрого изменения цвета трудно избежать – блюдо лучше готовить небольшими порциями.','https:https://st.vkuso.ru/data/cache/thumb/51/818d54edc9a0e51_434x295.jpeg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (974,'Репчатый лук очистить и натереть или измельчить при помощи блендера, добавить в основную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (974,'Лишний картофельный сок слить или вычерпать столовой ложкой.','https:https://st.vkuso.ru/data/cache/thumb/dc/c66dd6b45e66edc_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (974,'Готовое тесто поперчить и посолить по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/50/bf97e838ca35250_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (974,'Разогреть на сковороде растительное масло, выложить оладьи ложкой.','https:https://st.vkuso.ru/data/cache/thumb/96/a9978eb84f15296_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (974,'Жарить с обеих сторон до золотисто-коричневой корочки.','https:https://st.vkuso.ru/data/cache/thumb/01/e9cc383f3a76001_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (975,'Отварить куриную грудку или использовать копченую.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (975,'Замороженные шампиньоны выложить на сковороду и прогревать без крышки для выпаривания влаги.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (975,'В конце приготовления добавить мелко нарезанный репчатый лук, огонь убавить, добавить немного оливкового масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (975,'Смесь потомить до полной готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (975,'В большую емкость вбить сырые куриные яйца, добавить перец и соль, цельнозерновую муку, разрыхлитель, влить молоко.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (975,'Ингредиенты взбить до полного перемешивания, должно получиться жидкое тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (975,'Добавить в него грибную обжарку, отваренное и нарезанное мелкими кусочками куриное филе.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (975,'По желанию можно добавить сухую зелень, специи.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (975,'Все еще раз перемешать и вылить в тефлоновую или силиконовую форму для запекания.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (975,'Поверхность предварительно смазать маслом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (975,'Температура приготовления – 200 градусов, время – от 35 до 40 минут, это зависит от возможностей духовки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (976,'Перемешать соевый соус и «Кетчуп».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (976,'Рыбное филе разрезать на порции, вынуть косточки.','https:https://st.vkuso.ru/data/cache/thumb/72/6d42668ce6d7e72_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (976,'Каждый кусочек обмакнуть в полученную смесь, положить в отдельную посуду.','https:https://st.vkuso.ru/data/cache/thumb/b0/ea4329973c7bbb0_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (976,'Присыпать рубленым чесноком или готовым сухим чесночным порошком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (976,'Поставить в холодильник на два часа для маринования.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (976,'Филе обвалять в муке с солью, жарить на заранее раскаленном масле до золотистой корочки, с двух сторон.','https:https://st.vkuso.ru/data/cache/thumb/64/d5379537ec23064_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Помыть все ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (977,'Баклажаны нарезать брусочками среднего размера.','https:https://st.vkuso.ru/data/cache/thumb/df/2798172a13725df_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (977,'Посолить и обжарить на растительном масле, огонь – сильный, помешивать лопаткой так, чтобы кусочки приобрели темную корочку со всех сторон.','https:https://st.vkuso.ru/data/cache/thumb/89/dfca8f359144689_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (977,'Если овощ ощутимо горчит, дать постоять полчаса, отцедить и слить выделившийся сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (977,'За две-три минуты до окончания приготовления влить соевый соус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (977,'Продукт соленый сам по себе, соль можно не добавлять или добавить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (977,'Такими же брусками нарезать адыгейский сыр и мякоть помидоров, семенные камеры лучше удалить.','https:https://st.vkuso.ru/data/cache/thumb/4d/30ff659b0b0594d_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (977,'В остывшие баклажаны переложить остальные составляющие.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (977,'Ингредиенты перемешать, масло можно не добавлять.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (977,'Если салат готовить не хочется, а закуска на стол нужна – баклажаны можно нарезать кружками, точно так же обжарить, а затем сложить башенками вместе с кружочками помидоров и сыром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (978,'Куриное филе нарезать небольшими кубиками со стороной в один или полтора сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (978,'Остальную часть мяса пропустить через мясорубку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (978,'Мелко нарезать шампиньоны, жарить на растительном масле до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (978,'Грибы перемешать с солью и молотым перцем, сырыми куриными яйцами, измельченным чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (978,'Фарш хорошо вымешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (978,'Свиные кишки промыть, наполнить смесью, сформовать колбаски длиной от 15 до 20 сантиметров.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (978,'По всей длине сделать проколы для выхода пара.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (978,'Запекать в духовом шкафу до готовности, время зависит от особенностей духовки, величины и плотности колбасок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (979,'Смешать картофельное пюре со слегка взбитыми яйцами и мукой до однородности. Влить в сковородку растительное масло и дать ему нагреться. Из получившегося теста сформовать небольшие котлетки и обжарить их со всех сторон до получения хрустящей коричневой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (980,'В миске смешайте специи и подсолнечное масло. Добавьте куриное филе и хорошо перемешать со специями (Мариновать не нужно, филе всё равно получается невероятно сочным).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (980,'Обжарить куриное филе по 5 минут с каждой стороны до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (980,'Готовое филе нарежьте ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (980,'Обжарить лук на сливочном масле в течении 3-4 минут, добавьте томатную пасту, воду и хорошо перемешайте. Добавьте нарезанное куриное филе и еще раз перемешайте, чтобы соус впитался.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (980,'Положите тортилью на сковороду, посыпьте сверху сыром (по середине), а сверху выложите нарезанное куриное филе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (980,'Готовую лепёшку положите на фольгу и сложите, чтобы она приняла форму (как показано в видео). Ждем пока остынет.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (980,'Добавьте рукколу и готово!',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (981,'В миске смешать овсяные хлопья, муку, соду и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (981,'Влить воду и слегка перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (981,'Добавить сливочное масло и мед, все хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (981,'Противень застелить бумагой для выпечки и выложить на него тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (981,'Выпекать печенье в разогретой до 180°С духовке 25-30 мин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (982,'Баклажаны нарезать кольцами слегка посолить (1/2 ч.л.) и оставить на некоторое время, чтобы вышла горечь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (982,'Лук очистить и нарезать мелким кубиком. В сковороде разогреть оливковое масло и отправить жариться лук, периодически перемешивая. Жарим 7 минут на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (982,'Телятину (а в идеале баранину) нарезать мелким кубиком и добавить к обжаренному луку. Готовим на сильном огне 10 минут, перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (982,'Томаты залить кипятком на 2 минуты, затем слить воду и обдать холодной водой. Снять с помидор кожицу, натереть на терке. Добавить томатную пасту. Накрыть крышкой и тушить на среднем огне до полного выкипания жидкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (982,'В это время обжарить баклажаны с двух сторон на оливковом масле до слегка золотистого цвета. В форму для запекания выложить обжаренные баклажаны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (982,'Сыр натереть на крупной терке, разделить на 3 части. 1/3 часть от натертого сыра выложить на баклажаны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (982,'К этому времени приготовится мясо. Пропустить через пресс зубчик чеснока и добавить щепотку мускатного ореха, майорана, соль (1 ч. л.), перец (1/2 ч. л.) – перемешать. Эту смесь выложить на баклажаны.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (982,'В микроволновку отправить греться сливки. В это время в сотейнике растопить сливочное масло, затем добавить муку и вымешивать до однородной массы, чтобы не было комочков. Влить теплые сливки снова перемешиваем и греем на медленном огне до загустения. Когда соус загустеет добавляем 1/3 части сыра и греем пока он полностью не растает. Заливаем этим соусом мясную начинку. Сверху посыпаем оставшимся сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (982,'Отправляем мусаку в разогретую духовку до 180 градусов на 45 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (983,'Правильно очистить арбузные корки от мякоти и кожуры.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (983,'Нарезать кубиком.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (983,'Добавить сахар и варить на медленно огне.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (983,'Можно кушать уже в таком виде, тогда это напоминает мармелад.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (984,'Сливочное масло комнатной температуры перетереть с сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (984,'Вбить сырые куриные яйца, соединить все при помощи миксера до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (984,'Отдельно перемешать муку с какао-порошком, разрыхлителем, ванилином из пакетика, сахаром, солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (984,'Затем соединить обе массы все тем же миксером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (984,'Тесто переложить в форму для выпекания, выровнять поверхность, поставить в духовой шкаф на полчаса, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (984,'Проверить готовность зубочисткой. Вынуть выпечку из формы и приготовить любой торт.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Для приготовления бисквита размягчить сливочное масло, растереть с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Вбить в массу сырые яйца, взбить смесь миксером до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'В другой емкости перемешать муку с сахаром и какао-порошком, добавить разрыхлитель, ванилин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Соединить миксером обе массы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Тесто перелить в форму, время выпекания – 30 минут, температура – 180 градусов. Проверить готовность спичкой или зубочисткой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Для приготовления крема охлажденные сливки (100 мл) взбить с сахарной пудрой, добавить сливочный сыр (400 г), продолжать взбивать до тех пор, пока масса не станет однородной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Накрыть крем пленкой, поставить в холод на час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Готовый корж вынуть из формы, верхушку срезать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Разделить на три коржа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Каждый промазать кремом из холодильника.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Приготовить еще один крем: из сливочного сыра (250 г) и сгущенного молока.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Ингредиенты взбить, охладить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Намазать массу на торт лопаткой.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Поставить торт в холод на час.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Приготовить глазурь.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Растопить в микроволновой печи жирные сливки с темным горьким шоколадом.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (985,'Украсить торт в виде подтеков.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (986,'Нам потребуется соковыжымалка. Отжать огурцы, яблоки и мяту на соковыжымалке',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (986,'Коктейль расслаивается поэтому стоит его перемешать. Украсить мятой и охладить! Приятного аппетита!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (987,'Из вишни удалить косточки, фрукты порезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (987,'Желатин замочить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (987,'Порубить в блендере сухари с кокосовой стружкой, влить сгущенку, положить масло, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (987,'Массой заполнить кольцо или разъемную форму, пометить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (987,'В сотейник влить молоко, добавить сахар, какао, перемешать, нагреть до кипения, добавить набухший желатин с шоколадом, размешать в однородную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (987,'Порциями перемешать с маскарпоне, осторожно вмешать взбитые сливки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (987,'Достать основу вишневого торта с кремом из маскарпоне без выпечки, выложить на него полученную массу, убрать в холодильник для застывания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (988,'Мелко нашинковать лук, обжарить на масле до золотистости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (988,'Грибы отварить в кипятке 5 минут, положить к луку, жарить до испарения влаги.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (988,'Сырой картофель с луком и грибами пропустить сквозь мясорубку, фарш присолить, поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (988,'Выпекать картофельные драники с любимыми грибами, как обычные оладушки с 2 сторон в разогретом масле до появления корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (989,'На кусочки поломать шоколад и растопить 2/3, не перемешивая, на водяной бане. Желтки взбить, чтобы они стали немного светлыми, и ввести в растопленный шоколад. Взбить белки со щепоткой соли в плотную пену и аккуратно подмешать в шоколадно-желтковую массу – должно получиться что-то типа суфле или мусса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (989,'Смазать форму диаметром 10-15 см маслом (сливочным или растительным) и застелить пекарской бумагой. Ровным слоем выложить в подготовленную форму шоколадное тесто и выпекать торт при 250 градусах ровно 8 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (989,'Достать готовый шоколадный торт без муки и маргарина из духовки, остудить в районе 30 минут, после чего убрать в холодильник на 12-24 часа. Оставшийся шоколад растопить, полить им полностью весь торт и убрать его на 10 минут в холодильник. Перед подачей разрезать торт ножом, опущенным в кипяток, и разложить по тарелкам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (990,'Для заправки салата смешать масло, сок лимона, перец, сахар, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (990,'Тонко нарезать лук, порубить чеснок и зелень, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (990,'На решетку гриль положить перец, поместить ее на горелку плиты, обжарить перец со всех сторон до обгоревшей корочки, переложить в пакет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (990,'Так же испечь и баклажаны, разрезать вдоль, аккуратно вынуть мякоть ложкой, измельчить, переложить в салатницу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (990,'Очистить перец, порезать соломкой, смешать с остальными компонентами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (990,'Вылить в салат из баклажанов и болгарского перца на гриле подготовленную заранее заправку, аккуратно перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (991,'Из яиц поджарить тонкий омлет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (991,'Лаваш промазать сыром, присыпать мелко порезанной колбасой, уложить колечки помидора, посыпать ровным слоем зелени, закончить омлетом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (991,'Все разложить в виде тонкой полосы, отступив от края.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (991,'Прикрыть начинку лавашем, завернуть, порезать на квадраты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (991,'Разогреть сухую сковороду, обжарить бутерброды с колбасой и сыром в лаваше с двух сторон до хрустящей корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (992,'Просеем муку и все сухие ингредиенты, добавим йогурт и растительное масло, замесим тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (992,'Раскатаем в пласт и придадим форму, после отправим в разогретую духовку до 190 градусов на 9-10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (992,'Готовность проверяем на сухую палочку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (992,'Для ганаша горячие сливки заливаем на шоколад и перемешиваем до однородности. Остывшие пончики обмакиваем в готовой глазури и посыпаем кондитерской посыпкой.','https://vkuso.ru/data/cache/data/34/53bb20d9ab98534_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (993,'К белкам комнатной температуры добавить щепотку соли и взбить миксером до мягкой пенки, после добавить сахарную пудру и продолжать взбивать до устойчивых пиков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (993,'Как только масса стала устойчивой добавляем лимонный сок и крахмал и перемешать чтобы ингредиенты вмешались.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (993,'После перекладываем на противень застеленной пергаментной бумагой и выпекаем при 150 градусов 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (993,'Для крема к сыру добавим сахарную пудру и сливки и нужно взбить до устойчивых пиков.','https://vkuso.ru/data/cache/data/b3/9917ab2c77f8ab3_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (993,'После остывания рулета покрываем кремом по всей поверхности и украшаем ягодой по желанию, у меня клубника.','https://vkuso.ru/data/cache/data/39/e1b139a68d99939_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (994,'Нарезать под углом хлеб.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (994,'Разогреть сковороду и обжарить гренки с одной стороны.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (994,'Сделать яично-чесночную начинку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (994,'Выложить начинку сверху и присыпать зеленью.','https://vkuso.ru/data/cache/data/67/de827950f458967_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (995,'Сыр натираем на мелкой терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (995,'Укроп мелко нарезаем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (995,'Лук зеленый так же мелко нарезаем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (995,'Все перекладываем в миску.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (995,'Далее, добавляем 2 ку.яйца и муку 2 ст.л. снова перемешиваем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (995,'Далее из полученной массы катаем шарики и панируем их в панировочных сухарях.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (995,'Далее отправляем сырные шарики в морозилку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (995,'Спустя 15 минут, достаем сырные шарики.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (996,'Почистить яблоки, порезать на небольшие кубики, обрызгать соком лимона, чтобы они остались светлыми.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (996,'Тыкву мелко натереть (можно порубить в блендере).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (996,'Влить к тыкве кефир с маслом, вбить яйца, добавить сахар, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (996,'Порциями всыпать муку с разрыхлителем, вымесить тесто, почти в самом конце добавить яблоки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (996,'Разложить тесто по формочкам, выпекать около трети часа при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (997,'Подготовить грибы, почистить, порезать, минут 5 прокипятить, обжарить в масле до тех пор, пока не выпарится вся жидкость, подсолить жарить еще 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (997,'Почистить овощи, крупно нарезать, обжарить в сотейнике с добавлением масла, влить воду, тушить до полной готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (997,'Переложить овощи в блендер, сделать пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (997,'Влить сливки, положить грибы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (997,'Грибной суп-пюре с картофелем и морковью подсолить, поперчить, дать закипеть, снять с плиты, дать постоять под крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (998,'Помидоры и лук крупно нарезать, помидоры переложить в кастрюлю, поставить на слабый огонь, если сока нет, то влить чуть-чуть воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (998,'Когда выделится много сока, добавить помидоры, тушить кетчуп еще полтора-два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (998,'Всыпать соль, перец, приправы, перемешать блендером, переложить опять в кастрюлю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (998,'Варить еще полтора часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (998,'Влить уксус, перемешать, разлить по баночкам, завинтить крышками, перевернуть, укрыть теплым, дать остыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (999,'Подготовить овощи, крупно порезать перец с помидорами, переложить в блендер, добавить чеснок, измельчить до состояния пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (999,'Добавить в мелко тертый хрен, присолить, добавить чуть сахара, перемешать, попробовать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1000,'В миску разбить яйца, всыпать к ним сахар и соль, взбить все венчиком. Влить в яичную смесь молоко и растопленное масло, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1000,'Далее всыпать в жидкую массу муку и тщательно перемешать тесто, чтобы не было комков. Сухую сковородку нагреть и выпекать нежные блинчики, тающие во рту, до подрумянивания (жарятся они быстро).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1001,'В теплое молоко добавляю соль, сахар и дрожжи. Оставляю на 10 минут. Теперь вливаю растопленное сливочное масло, добавляю муку и замешиваю мягкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1001,'Обмазав тесто со всех сторон растительным маслом накрываю миску с ним пищевой пленкой и оставляю подниматься в теплом месте на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1001,'Готовлю сырную корочку. Смешив в миске натертый сыр, чеснок и растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1001,'Подошедшее тесто делю на 2 части, формирую батоны и укладываю на противень, застеленный пергаментом. В середине каждого батона по всей длине делаю небольшое углубление (как борозда на грядке).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1001,'Сначала выкладываю нарезанную петрушку, затем посыпаю батоны подготовленным сыром и оставляю подходить еще минут на 20.Переед выпеканием смазываю их молоком и выпекаю в духовке при температуре 190 градусов до румяности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1002,'Смешать творог, сметану, сахар, крахмал и яйца. Взбить погружным блендером до однородности. Начинка готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1002,'На стол высыпать муку, какао, сахар, соль. Перемешать все руками.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1014,'Желатин замочить в ¼ стакана воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1041,'Массу взбить при помощи венчика до растворения сахара.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1002,'В форму (22 см), застеленную пергаментной бумагой, высыпать 2/3 крошки. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1002,'Выпекать в духовке при 180°С 40 минут. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1003,'Вымыть овощи, крупно порезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1003,'В кастрюлю с толстым дном влить масло, прогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1003,'Положить лук, чуть обжарить, добавить морковь, а потом картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1003,'Размешать овощи, положить кабачок, тушить пару-тройку минут, добавить тыкву, содержимое кастрюли посолить, залить овощи на 1/3, закрыть крышкой, тушить до полного размягчения овощей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1003,'Погружным блендером превратить овощи в суп-пюре из тыквы, кабачка и картофеля, если надо, то можно добавить воды до нужной густоты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1003,'Зелень порубить, чеснок измельчить, положить в суп, размешать, нагреть его до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1003,'Закрыть крышкой, снять с плиты, подавать со сливками или сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1004,'Савойскую капусту и всю зелень мелко нашинкуем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1004,'Колбасу нарежем небольшими полосками или кубиками (кому как больше нравиться).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1004,'С гороха сливаем всю жидкость, я ее сливала через сито.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1004,'В салатнике смешиваем все подготовленные ингредиенты и зеленый горошек. Солим по своему вкусу и заправляем салат майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1004,'Все хорошо перемешиваем и наш быстрый салатик из савойской капусты с колбасой готов. Приятного Вам аппетита.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1005,'Количество баклажан зависит от количества банок. На 2 литровые банки я брала 8 небольших баклажан. Их нужно помыть, обрезать хвостик.','https://vkuso.ru/data/cache/data/a2/4f31c6970047ba2_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1005,'Кипящую воду посолить и отправить в нее баклажаны. Варить 5 минут. Достаем баклажаны и даем немного остыть.','https://vkuso.ru/data/cache/data/50/7560a9cc2eebe50_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1005,'На дно стерильной баночки выкладываем чеснок, потом укладываем плотненько баклажаны, они стали мягкими и их удобно утрамбовывать. Сверху еще кладем чеснок, добавляем соль, сахар, уксус и заливаем кипятком. Закрываем крышкой и закатываем.','https://vkuso.ru/data/cache/data/3d/7b1ee70b23a493d_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1005,'Потом переворачиваем вниз крышкой, укутываем чем-то теплым и оставляем до полного остывания. Потом убираем в прохладное темное место. Рецепт проверенный, уже много лет так делаем, баночки стоят хорошо. Очень вкусно зимой добавить к ним острую аджику, или лук, чеснок, масло растительное, салат готов. приятного аппетита!','https://vkuso.ru/data/cache/data/f6/b4330b29243d7f6_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1006,'Подготовить сперва все ингредиенты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1006,'Обжарить куриное филе и нарезать мелким кубиком.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1006,'Натереть сыр на терке.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1006,'Смешать всю начинку и завернуть в лаваш конвертиком (смотрите в видео).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1006,'Обжарить готовые треугольнички на сковороде.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1007,'Количество ингредиентов я указала из своих личных предпочтений, вы можете добавить или убрать по своему вкусу.','https://vkuso.ru/data/cache/data/c8/367ee39cfa64cc8_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1007,'Овощи моем, чистим и нарезаем произвольными кусочками, только морковь режьте помельче, так как ей требуется больше всего времени для запекания. На помидорах я сделала надрез, чтоб не лопнули. Посолим все, посыпем любимыми специями, я брала итальянские травы, сбрызнем растительным маслом, перемешаем. Запекаем при 180 градусах примерно 40-50 минут до готовности все овощей.','https://vkuso.ru/data/cache/data/1d/f67dd0e58cfbd1d_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1013,'Влить молоко, добавить ванильный сахар, подсыпать небольшими порциями муку, вымесить тесто для Французского пирога Клафути с вишней на молоке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1013,'Ягоды выложить на дно формы, сок от нее вылить в тесто, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1013,'Залить вишню, поместить форму в прогретую до 180 градусов духовку минут на 40-50.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1014,'Форму выстлать пергаментом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1007,'Готовые овощи перекладываем в миску, помидоры очищаем от шкурки. Баклажаны можно почистить сразу еще перед запеканием, можно сейчас снять шкурку, а можно и так оставить, на ваш вкус. Если вы не любите пюреобразную икру, можете так все оставить или немного измельчить, заправить и подавать на стол, я мужу так и сделала, запекла такую же вторую порцию, съел с удовольствием.','https://vkuso.ru/data/cache/data/71/e8885f436dbec71_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1007,'Юшечку, которая образовалась при запекании тоже добавляем в миску, она очень вкусная!','https://vkuso.ru/data/cache/data/22/e5963de3ca9df22_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1007,'Измельчаем удобным для вас способом миксером или через мясорубку.','https://vkuso.ru/data/cache/data/1d/37180a4790e0f1d_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1007,'Пробуем на вкус и добавляем, чего нам не хватает - соль, сахар, масло растительное, специи, сок лимонный или уксус. Если хотите закатать на зиму, раскладываем в стерильные баночки, простерилизуем. Если храните в погребе, достаточно после стерилизации сверху налить тонким слоем подсолнечное масло и закатать. Если при комнатной температуре, добавляем 1 ст. л. 9% уксуса и закатываем.','https://vkuso.ru/data/cache/data/68/674ebc0fb89a968_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1007,'Икра получается очень вкусная, полезная, масла мы используем намного меньше, чем когда жарим, овощи запеченные намного полезнее. И готовить такую икру намного быстрее. Приятного вам аппетита!','https://vkuso.ru/data/cache/data/5d/9a3e450687f7a5d_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1008,'Размять консервированную горбушу (она должна быть без костей и кожи) вилкой. Картофель и морковь очистить и натереть на средней терке. Очищенное яйцо и огурец мелко порезать, сыр натереть на терке (любой).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1008,'Шампиньоны нарезать и обжарить в растительном масле до полной готовности. Выложить салат «Лисья шуба» слоями: горбуша, морковь, картофель, обжаренные шампиньоны, огурец. Последний слой смазать майонезом, посыпать измельченным яйцом и тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1009,'Отварить яйца и куриную грудку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1009,'Натереть сыр на терке.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1009,'Смешать сыр с рубленным укропом и чесноком.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1009,'Мясо пропустить через мясорубку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1009,'Смешать с тертым яйцом, финиками и заправить йогуртом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1010,'Сыр натираем на мелкой терке и перекладываем в тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1010,'Сосиски очищаем от заводской плёнки, и на разогретом растительном масле обжариваем их до корочки около 2-3 минут. Как только обжарили, перекладываем на тарелку с бумажным полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1010,'Даём сосискам остыть, и далее нарезаем сосиски на 4 кусочка, сначала пополам, потом вдоль. Так же, сосиски можно порезать на маленькие кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1010,'На тостовый хлеб укладываем тонким слоем сыр, прижимаем его, далее подготовленную сосиску, снова сыр, и сверху ломтик тостового хлеба, хорошо прижимаем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1010,'Снова разогреваем сковороду, и обжариваем сэндвичи с каждой стороны до золотистой корочки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1011,'Подготовить ножки, замариновать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1011,'Включить для разогрева на 200 градусов духовку, подготовить противень, выстлать его фольгой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1011,'Достать ножки, обвалять со всех сторон в сухарях, выложить на противень, запекать маринованные куриные ножки в панировочных сухарях минут 40 в уже разогретой духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1012,'Просеять муку, перемешать с ванильным сахаром, солью, разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1012,'Мягкое масло взбить с сахаром, ввести по 1 яйцу, хорошо перемешивая после каждого добавления.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1012,'Влить молоко, замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1012,'Разделить массу пополам, добавить в одну часть какао, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1012,'Подготовить форму, смазать маслом, попеременно выкладывать в центр темное и светлое тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1012,'Выпекать мраморный кекс на молоке и сливочном масле 50-90 минут (зависит от размеров формы) при температуре порядка 170 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1013,'Форму смазать маслом, присыпать сахаром, стряхнуть его излишки, поставить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1013,'В сахар вбить яйца и желток, перемешать хорошо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1014,'Масло и шоколад растопить и перемешать с кукурузными хлопьями, заполнить дно формы, слегка утрамбовать, поставить в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1014,'Подготовить фрукты или ягоды, если плоды крупные, то нарезать на кусочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1014,'Блендером смешать сахар, творог и ванильный сахар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1014,'Подогреть молоко до кипения, залить желатин, растворить его, перемешать с творожной смесью, добавить растопленный шоколад, еще раз перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1014,'Хорошо взбить сливки, аккуратно смешать с массой из творога.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1014,'На основание Творожного торта «Пломбир» с клубникой без выпечки ровным слоем выложить кусочки фруктов или ягоды.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1014,'Залить сверху шоколадно-творожной смесью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1014,'Убрать торт для полного застывания в холодильник.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1015,'Перемешать сгущенку с молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1015,'Добавить к взбитым в крепкую пену сливкам, аккуратно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1015,'Переложить массу для Мороженого крем-брюле на молоке и сливках в контейнер.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1015,'Поставить до полного застывания в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1016,'Натереть хорошо замороженное масло, перемешать его с подсоленной мукой, корицей, сахаром и разрыхлителем до состояния маслянистой крошки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1016,'По центру уложить творог, вымесить тесто, скатать из него колбаску, положить на час-полтора в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1016,'Нарезать на кусочки по 1 см толщиной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1016,'Обжарить Творожное печенье с корицей на сковороде без масла на слабом огне с двух сторон до появления соломенного цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1017,'Подготовить овощи, вымыть обсушить перцы, вдавить хвостик, потянуть за него и удалить семечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1017,'Разложить их в форме (смазать предварительно ее маслом), запечь в прогретой до 190 градусов духовке около трети часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1017,'Достать форму, перевернуть перцы вернуть в духовку еще на треть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1017,'Готовые овощи достать закрыть в форме фольгой, дать остыть, снять кожицу, порезать на полоски.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1017,'Выложить в салатницу, залить через ситечко оставшимся в форме соком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1017,'Нарезать тонкими полукольцами лук, добавить к перцу, подсолить, влить смесь масла и уксуса, аккуратно перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1017,'Готовый Салат из запеченных перцев и репчатого лука поставить на пару-тройку часов в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1018,'Достать заранее масло, положить вместе с мукой в миксер, взбить в мелкую маслянистую крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1018,'Влить 0,5 стакана молока, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1018,'Присыпать стол мукой, выложить на него тесто, вымесить руками до готовности, убрать в холодильник минут на 30, завернув в пищевую плёнку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1018,'Порезать лук полукольцами и обжарить на масле до мягкости, рыбу слегка размять вилкой, но не до состояния каши, перемешать с луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1018,'Дно формы выслать пергаментом, смазать маслом, заполнить дно тестом, сформовать бортики, выложить ровным слоем начинку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1018,'Для заливки разболтать яйца со сметаной до однородного состояния, поперчить, посолить, добавить порубленную зелень, перемешать, всыпать столовую ложку муки, хорошо перемешать до исчезновения комочков, залить равномерно рыбную начинку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1018,'Заранее прогреть до 180 градусов духовку, поставить Заливной пирог с рыбными консервами и зеленью на 40 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1019,'В большую миску всыпать муку, фруктозу, разрыхлитель, соль и ванилин, вбить яйца и все перемешать. Влить в яичную смесь горячее молоко и взбить, затем добавить оливковое масло и еще раз все хорошенько взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1019,'Сковородку разогреть, смазать оливковым маслом и вылить на нее 1/2 половника получившегося теста. Жарить блинчик 1 минуту, перевернуть его на другую сторону и жарить 30 секунд. Описанным выше образом испечь из оставшегося теста очень тоненькие блинчики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1020,'Тесто разморозить, разложить на противне, выстланном пергаментом, проколоть в нескольких местах вилкой, смазать разболтанным желтком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1020,'Выпекать около четверти часа в прогретой до 200 градусов в духовке, должна появиться румяная корочка, также испечь и второй корж, дать им остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1046,'Перемешать ингредиенты, добавить сахарный песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1020,'Из взбитых миксером жирных сливок и сахарной пудры приготовить для Клубничного торта из слоеного теста со взбитыми сливками плотный крем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1020,'Для ускорения процесса венчики и чашу миксера подержать четверть часа в морозилке (сливки брать тоже холодные, простоявшие сутки в холодильнике).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1020,'Ягоды вымыть, обсушить, удалить хвостики, порезать пластинками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1020,'Наполнить кремом кондитерский мешок, выдавить ровным слоем на холодный корж, прикрыть вторым, смазать верх кремом, разложить пластинки клубники.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1021,'Баклажаны нарезаем кубиками, сложим их в миску и немного посолим чтобы они дали сок. Пока отставим в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1021,'Нарезаем все остальные овощи. Лук четверть кольцами, помидоры небольшим кубиком, морковь натираем на крупной терке, а сладкий болгарский перец нарежем соломкой среднего размера предварительно убрав из перца семена.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1021,'Растительное масло наливаем в кастрюльку и отправляем в нее все нарезанные овощи. Добавим соль и сахар, отправляем на огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1021,'Доводим овощи до закипания и тушим на среднем огне периодически перемешивая, чтобы не пригорели. У меня полное время варки заняло 50 минут, при этом я раза 3-4 перемешивала.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1021,'Минут за 5 до окончания варки добавим в кастрюлю половинку чайной ложки уксуса (70%) и нарезанные зубчики чеснока.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1021,'Вот и все можно закатывать в стерилизованные банки наш закусочный салат из баклажанов с помидорами и болгарским перцем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1022,'Хорошо замороженное масло крупно натереть, перемешать до состояния маслянистой крошки с мукой, всыпать сахар, еще раз перемешать, влить пиво (или газировку), еще раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1022,'Переложить тесто на стол, окончательно вымесить, обернуть пленкой, убрать на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1022,'Достать, разрезать пополам, скатать оба колбаской, порезать на кусочки, каждый свернуть колечко, накручивая на палец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1022,'Обвалять заготовки печенья на пиве и масле в сахаре, разложить их на противень, выстланный бумагой для выпечки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1022,'Отправить в прогретую до 200 градусов духовку примерно на 35 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1023,'В чашу всыпать 130 г муки, чуть подсолить, добавить какао, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1023,'Взбить в однородную массу 110 г мягкого масла с желтком и 70 г сахара, перемешать со смесью муки и какао в однородную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1023,'Из теста скатать «колобок», обернуть пленкой, убрать на треть часа в холодильник, а за это время обжарить орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1023,'Взять кастрюльку с толстым дном, влить 65 мл воды, добавить столовую ложку мёда, всыпать 200 г сахара, размешать, прогреть до полного его растворения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1023,'Положить в сироп 60 г масла, размешать, влить 125 мл. сливок, проварить пару-тройку минут, всыпать орехи, варить около 5 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1023,'Подготовить форму, смазать маслом, заполнить тестом, разровнять, сделать бортики, проколоть 3-4 раза вилкой, поставить на 20 минут в прогретую до 180 градусов духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1023,'Вынуть форму, дать остыть, заполнить основу Шоколадно-сливочного тарта с орехами сливочно-ореховой массой, верх разровнять, вернуть на 20 минут в духовку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1024,'Хорошо перемешать смесь просеянной муки с разрыхлителем, какао порошком, сахарной пудрой, влить 4 ст. л. молока, добавить масло, вымесить тесто, завернуть его в пленку, положить на час морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1024,'Для начинки смешать миксером сливочный сыр с сахарной пудрой в однородную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1024,'Всыпать ванильный сахар, по столовой ложке крахмала и цедры лимона, добавить пару желтков, все взбить еще около 3 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1024,'В другой емкости до устойчивых пиков взбить белки, аккуратно перемешать с предыдущей массой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1024,'Подготовленную форму выслать пергаментом, смазать маслом, заполнить половиной крупного натертого теста, разровнять, положить крем, сверху натереть оставшуюся половину теста.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1024,'Поставить Тертый чизкейк со сливочно-лимонной начинкой в прогретую до 180 градусов духовку примерно на 50 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1024,'Выпечку достать, дать ей остыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1029,'В кастрюлю переложить обжаренные овощи, добавить муку – перемешать. Влить сливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1025,'Клубни картофеля хорошо помыть, почисти (молодой можно не чистить), сделать параллельные надрезы через 1 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1025,'В каждый положить по пластинке бекона, чуть подсолить, поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1025,'Завернуть картофель в фольгу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1025,'Запекать Картошку-гармошку с беконом и чесночным соусом около часа (зависит от размера клубня) при температуре 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1025,'Растопить сливочное масло, смешать его с чесноком, пропущенным через пресс, всыпать измельченную зелень, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1025,'Достать клубни, аккуратно развернуть, полученным соусом хорошо смазать картофель, поставить ещё минут на 10 в духовку для зарумянивания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1026,'Подготовить подчеревок, очистить ножом шкурку, вымыть мясо, обсушить, разрезать прямоугольный кусок вдоль, раскрыть его наподобие книги.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1026,'Положить щепотку кориандра, три поломанных лавровых листа в ступку, растереть в порошок, добавить чеснок, столовую ложку смеси «5 перцев», всыпать пару щепоток соли, хорошо растереть все пестиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1026,'На развернутом куски мяса сделать слегка насечки, натереть приготовленной смесью специй, прикрыть плёнкой, отбить молотком с 2 сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1026,'Свернуть мясо в трубочку, несколько раз обернуть в пищевую пленку, обвязать нитью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1026,'Переложить рулет в подходящую по размеру кастрюлю, влить воду, варить около 3 часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1026,'Для гарнира очистить молодой картофель, сварить в подсоленной воде, слить воду, всыпать измельченную зелень укропа, положить масло, закрыть крышкой, прижать ее, несколько раз встряхнуть для перемешивания содержимого.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1026,'Из смеси пары ложек соевого соуса и столовой ложки оливкового масла с черным перцем приготовить маринад.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1026,'Вылить его в плотный пакет, положить грибы, завязать, несколько раз хорошо встряхнуть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1026,'Дать постоять четверть часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1026,'Разноцветный перец вымыть, очистить от семян, нарезать на полоски, перемешать с небольшим количеством масла, обжарить на гриле.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1026,'Вынуть мясо, снять с осторожностью пленку, дать чуть остыть, развернуть рулет, со стороны шкурки сделать насечки в виде небольших ромбиков, свернуть кусок в трубочку, обвязать нитью.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1026,'На противень, выстланный фольгой поставить решетку, уложить рулет, смазать горчицей с медом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1026,'Грибы насадить на шампуры, положить рядом с рулетом, отправить всё на полчаса в прогретую до 200 градусов духовку.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1026,'Достать Праздничный рулет из подчеревка с картофелем и грибами, удалить нить, положить на блюдо, выложить рядом картофель, перец и шампиньоны.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1027,'Куриную грудку отварить в подсоленой воде до готовности (около 30 мин), дать остыть.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1027,'Куриную грудку, шампиньоны, ветчину и соленые огурцы нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1027,'Сыр натереть на мелкой терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1027,'Все ингредиенты хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1027,'При подаче посолить и заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1028,'В сотейник всыпать сахар, какао. Влить молоко и добавить сливочное масло (желательно комнатной температуры, так оно быстрей растает, но не обязательно). Ставим на медленный огонь и постоянно помешивая доводим до кипения. Как доведете до кипения продолжайте варить еще 2 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1028,'Снимаем сотейник с огня и добавляем ванильный сахар, кокосовое масло и овсяные хлопья – перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1028,'На поднос или доску (желательно не деревянную) выкладываем получившую массу по размеру желаемого печенья. По желанию украшаем рубленными орехами. Отправляем в холодильник на 1-2 часа для застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1029,'В кастрюлю налить воды, отправить туда курицу. Поставить на огонь, довести до кипения, затем вари 25 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1029,'Лук, картофель очистить, нарезать кубиками (не обязательно очень мелко). Морковь очистить и нарезать полукольцами. Сельдерей нарезать кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1029,'В сковороде разогреть сливочное масло. Обжарить все нарезанные овощи на среднем огне, перемешивая 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1041,'Сливочное масло размягчить, перетереть с сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1029,'К этому моменту как раз сварилась курица. Вынимаем ее из кастрюли, а бульон переливаем к овощам. Накрыть кастрюлю крышкой и отправить на огонь. Доводим до кипения, варим 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1029,'Спустя 10 минут, снимаем с огня. С помощью погружного блендера превращаем содержимое кастрюли в пюре. Добавляем соль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1029,'Курицу нарезаем небольшими кусочками, отправляем в кастрюлю с супом, перемешиваем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1030,'Порезать мясо на пластины (1 см толщиной), поперчить, посолить, хорошо отбить со всех сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1030,'Выложить мясо на смазанный маслом противень, присыпать луком, смазать майонезом, посыпать крупно натертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1030,'Запекать около получаса в прогретой до 200 градусов духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1031,'Очистить селедку, снять кожу, удалить тщательно все кости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1031,'Порезать кусочками, морковь отварить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1031,'Масло и сырки порезать на кусочки, перекрутить вместе с морковью и селедкой в мясорубке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1031,'Закуску «Ложная икорка» из сельди и плавленого сыра хорошо вымешать, намазать на хлеб, украсить зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1032,'Порезать на квадраты размороженное тесто, каждый потом разрезать по диагонали.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1032,'Очистить яблоки, порезать на дольки, выложить на каждый треугольник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1032,'Противень с высокими бортиками смазать маслом, выложить слойки на расстоянии друг от друга.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1032,'Растопить в кастрюльке полпачки масла, всыпать полстакана сахара, перемешать смесь до его растворения, смазать Дрожжевые слойки со спрайтом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1032,'Вылить на противень спрайт так, чтобы его уровень доходил до половины высоты слоек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1032,'Выпекать в разогретой до 200 градусов духовке около получаса, чтобы появилась золотистая корочка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1033,'Порубить тушку на порционные куски, посолить, поперчить, кусочки обвалять в муке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1033,'Порезать чеснок на пластинки, лук – полукольцами, чернослив – на половинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1033,'Обжарить лук да светло-золотистого цвета. Переложить в кастрюлю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1033,'Обжарить на оставшемся масле куски курицы со всех сторон, переложить к луку, добавить половинки чернослива и чеснок, посолить, размешать, тушить около трети часа, несколько раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1033,'Перед окончанием положить пару ложек варенья из слив, размешать, тушить, прикрыв крышкой 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1034,'В миску вылить сгущенное молоко, вбить яйцо, всыпать муку, добавить соду, гашенную уксусом, и замесить однородное тесто без комков. Разделить тесто на 8 одинаковых кусков, раскатать каждый в очень тонкий круг. Разогреть сковородку без масла и поочередно обжарить коржи до готовности со всех сторон. Готовые коржи слегка остудить, края подровнять, измельчить обрезки в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1034,'Для крема: взбить яйцо с сахаром, всыпать муку, небольшое количество молока и ванилин, хорошо перемешать. Оставшееся молоко перелить в кастрюльку и влить в него тонкой струей яичную смесь. Поставить кастрюльку на небольшой огонь и, все время мешая, варить крем до загустения. Дать готовому крему немного остыть, добавить мягкое сливочное масло и взбить миксером до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1034,'Собрать торт перемазывая каждый корж остывшим заварным кремом, и украсить его подготовленной посыпкой. Убрать торт «Минутка» с молочным кремом в холодильник на всю ночь, перед подачей можно нарезать его порционными кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1035,'Почистить рульки под струей воды, положить в большую кастрюлю, добавить морковь, чеснок, горошки черного перца, тмин, лавровый лист, посолить, залить смесью из литра темного пива и воды, чтобы жидкость полностью покрыла голяшки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1035,'В луковицу воткнуть гвоздички и тоже положить в кастрюлю, закрыть крышкой варить 2-3 часа, снимая пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1035,'За это время потушить квашеную капусту, лук измельчить на кубики, обжарить на масле, положить капусту, отжатую от рассола, добавить кориандр, тмин, протушить минут 40, периодически подливать бульон или воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1035,'Для соуса смешать 2 cт. л. бульона от рульки, 1 ст. л. меда и 1 ст. л. французской горчицы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1035,'Смазать маслом противень, выложить слой квашеной капусты, на нее – решетку, а потом рульку, которую смазать соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1035,'Запекать Рульку в пиве с тушеной квашеной капустой в духовке, прогретой до 200 градусов, около 40 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1036,'Лук и фенхель нарезать небольшими кубиками. В сковороде разогреть оливковое масло, обжариваем лук и фенхель в течении 10 минут на среднем огне, перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1036,'Морковь нарезать небольшими кубиками. Перец чили нарезать тонкими колечками. Отправляем в сковороду к луку и фенхелю, обжариваем еще 10 минут, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1036,'Спустя 10 минут добавляем говяжий фарш и тщательно перемешиваем, чтобы фарш не превратился в котлету. Готовим на среднем огне пока не выпариться вся жидкость периодически перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1036,'Добавить в сковороду паприку, зиру, чеснок пропущенный через пресс, красный жгучий перец и корицу, перемешиваем. Готовим 2 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1036,'Спустя 2 минуты добавляем кукурузу и фасоль, вливаем соус из томатов и нарезаем сами томаты на маленькие кубики, посыпаем сахаром. Перемешиваем и накрываем крышкой. Готовим 10 минут на медленном огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1037,'В глубокую емкость вбиваем яйца, добавляем щепотку соли, сахар, ванильный сахар и взбиваем миксером чтобы яйца посветлели и увеличились в объеме.','https://vkuso.ru/data/cache/data/6e/cd37b20ec23586e_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1037,'Добавляем растительное масло, кефир, просеиваем муку, какао и разрыхлитель. Хорошо перемешаем ложкой или миксером в однородную массу.','https://vkuso.ru/data/cache/data/e4/494ae4175ce42e4_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1037,'Пергамент смажем маслом. Форму для выпечки застилаем пергаментом и выливаем тесто. Выпекаем в разогретой до 180 градусов духовке 25-30 минут.','https://vkuso.ru/data/cache/data/0e/4337150d3ff880e_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1037,'Пока печется пирог, приготовим глазурь. В сотейник выкладываем масло, сахар, молоко и какао. Помешивая, доводим до кипения, убавляем огонь, на маленьком огне проварим 3-4 минуты.','https://vkuso.ru/data/cache/data/80/f509a674957d580_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1037,'Готовый горячий пирог нарежем острым ножом квадратиками или ромбиками как вам нравится.','https://vkuso.ru/data/cache/data/d5/4b7c3d1ae677fd5_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1037,'Заливаем горячий пирог горячей глазурью. Можно ещё наколоть его зубочисткой, чтобы глазурь лучше проникала и лучше пропитала его. Оставляем его до полного остывания.','https://vkuso.ru/data/cache/data/6d/3777004db7d1b6d_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1037,'Остывший пирог подаем к чаю и наслаждаемся. Приятного аппетита!','https://vkuso.ru/data/cache/data/f3/96f33f065ffeef3_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1038,'Отрезать шляпку у тыквы. Очистить от семечек тыкву.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1038,'Нарезать картофель, мясо, чеснок кубиком и немного тыквы.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1038,'Замариновать все и нафаршировать тыкву начинкой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1038,'Запечь в духовке при 200 градусов.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1039,'Муку перемешать с какао-порошком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1039,'Куриные яйца взбить со щепоткой соли, всыпать сахарный песок, ванилин, влить растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1039,'В массу всыпать муку с какао.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1039,'Замесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1039,'Поставить массу в холодильник на два часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1039,'Из теста скатать небольшой шар, обвалять в сахарной пудре, переложить на пергамент.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1039,'Форму с печеньем поставить в духовку на 15 минут, температура приготовления – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1040,'Кабачки натереть на средней или крупной терке. Если овощи старые, то кожицу лучше снять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1040,'Массу посолить и перетереть руками, чтобы лишняя влага вышла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1040,'Натереть морковь, нарезать кольцами томаты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1040,'Свежую зелень мелко порубить, всыпать в сметану, посолить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1040,'Полученный соус влить в творог, массу перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1040,'С кабачков слить жидкость, всыпать муку и немного пищевой соды, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1040,'Обжарить на растительном масле морковь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1040,'Выпечь блинчики из кабачкового теста.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1040,'На первый блин выложить часть творожной массы, кусочки томатов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1040,'Слои повторять, пока не закончатся продукты.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1040,'Верх торта также намазать творожным кремом, украсить овощами на свой вкус.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'Отварить картофель, охладить, натереть на терке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1041,'Муку просеять вместе с разрыхлителем, добавить немного воды, вымесить тесто. Масса должна получиться мягкой и рыхлой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1041,'Подготовить противень, заселить его пергаментом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1041,'Выложить тесто в виде небольших лепешек, каждую украсить миндальной стружкой или миндальными орехами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1041,'Противень поставить в духовку, время приготовления выпечки – от 15 до 20 минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1042,'Сливочное масло заморозить, натереть на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1042,'Всыпать пищевую соду, муку, сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1042,'Массу растереть. Тесто должно напоминать мокрый песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1042,'Для приготовления начинки взбить сырые куриные яйца с сахаром, добавить в творог.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1042,'Положить кусочки фруктов или ягод, например, клубнику, абрикос.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1042,'Подготовить форму для выпекания, выложить песочное тесто, сверху налить творожную начинку, верх посыпать оставшимся песочным тестом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1042,'Время выпекания в духовом шкафу – час, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1043,'Репчатый лук и кабачки натереть на средней терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1043,'Отделить желтки от белков, желтки добавить в кабачки вместе с луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1043,'Перец и соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1043,'Муку просеять с разрыхлителем, замесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1043,'Белки взбить и также добавить в тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1043,'Противень застелить пергаментом, выложить тесто ровным слоем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1043,'Поставить в духовой шкаф на 30 или 40 минут, температура приготовления – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1043,'Любые грибы потушить или обжарить на сковороде, в конце положить сметану.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1043,'Натереть сыр.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1043,'Готовый корж немного остудить, выложить начинку из грибов, посыпать сыром, осторожно свернуть рулет.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1043,'Блюдо остудить, подать на стол, разрезав на порционные кусочки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1044,'Пожалуй, мало что может быть вкуснее торта с шоколадным кремом. Тонкие ванильные коржи, промазанные нежным кремом из шоколада, – просто мечта для сладкоежки. Так что если вы не прочь побаловать себя или своих родных чем-то вкусненьким, вам стоит приготовить этот торт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1044,'Тщательно размешать до однородности желтки с сахаром, маслом и ванильной пудрой. Всыпать в масляную массу муку и хорошо все перемешать, чтобы не было комков. Белки взбить в плотную пену и аккуратно ввести в тесто, которое затем разделить на 6-8 равных частей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1044,'Смазать форму для выпечки сливочным маслом, присыпать дно небольшим количеством муки и вылить в нее первую часть теста. Убрать форму в духовку, предварительно нагретую до 200 градусов, и испечь корж. Повторить то же самое с оставшимися частями теста: всего должно получиться 6-8 тонких коржей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1044,'Все коржи полностью остудить, самый лучший бисквит отложить для верха будущего торта. Для крема: размягченное масло размешать с сахарной пудрой, какао-порошком, яйцами, растопленным шоколадом и небольшим количеством рома. Взбивать получившуюся массу, пока не получится однородный крем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1044,'Собрать ванильный многослойный торт с шоколадным кремом, промазывая коржи и аккуратно укладывая, их друг на друга. Оставшимся кремом смазать бока и поверхность торта и убрать изделие в холодильник до подачи. Ром в крем можно не добавлять. Для более праздничного вида можно присыпать уже охлажденный торт кокосовой стружкой или сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1045,'Нарезать лук и обжарить на масле. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1045,'Нарезать все грибы, добавлять к луку и чесноку постепенно, обжаривая на среднем огне.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1045,'Добавить соевый соус и сливочное масло.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1045,'В конце добавить воду и заправить специями.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1045,'Порционно сверху добавить свежую зелень.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1046,'Печенье измельчить в крошку, это можно сделать с помощью скалки и полиэтиленового пакета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1046,'Растопить на водяной бане сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1046,'Выложить в форму, печь десять минут, температура – 170 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1046,'Для сырной начинки взбить куриные яйца с сахаром, влить жирные сливки, всыпать цедру половины лимона и ванилин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1046,'Добавить сливочный сыр, все еще раз взбить до однородности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1046,'Массу вылить на основу и поставить в духовой шкаф на водяную баню. Температура – 150 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1046,'Готовую выпечку убрать в холод.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1046,'При подаче украсить красиво нарезанными ягодами клубники.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1047,'Молоко разогреть с ванилином и сахарным песком. Сахар должен раствориться, до кипения сироп не доводить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1047,'Добавить сливочное масло, оно должно растаять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1047,'Смесь перелить в другую емкость, остудить до комнатной температуры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1047,'Часть взбитого куриного яйца добавить в остывшую смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1047,'Просеять муку и разрыхлитель, замесить тесто. Масса должна получиться рыхлой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1047,'Раскатать тесто толщиной в сантиметр, вырезать коржики при помощи формочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1047,'Сверху смазать изделия оставшимся взбитым яйцом, поставить в духовку, время – от 10 до 12 минут. Температура приготовления – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1048,'На плиту поставить кастрюлю с любым бульоном или подсоленной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1048,'Сформовать фрикадельки из мясного фарша, соль и молотый перец – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1048,'Опустить в кипящую воду мясные изделия, время варки – от 15 до 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1048,'Очистить картофель, нарезать кубиками, всыпать в кастрюлю с супом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1048,'Овощную смесь добавить за пять минут до полной готовности супа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1049,'Отварить клубни картофеля, кожуру не снимать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1049,'Приготовить пюре, вбить сырое куриное яйцо, рубленую зелень и растопленное сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1049,'Нашинковать репчатый лук, нарезать свежие шампиньоны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1049,'То и другое обжарить на сливочном масле, лишняя жидкость должна испариться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1049,'В небольшие формы для кексов выложить часть картофельного пюре, равномерно распределить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1049,'Выложить грибную начинку, сверху – еще один слой картофельного пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1049,'Посыпать запеканки тертым сыром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1049,'Время приготовления – от 10 до 15 минут, температура – 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1050,'Мелко нашинковать репчатый лук, сырой картофель нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1050,'Обжарить овощи на растительном масле, время – 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1050,'Посолить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1050,'Отдельно взбить молоко с яйцами, посолить и поперчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1050,'Залить овощи полученной смесью, прогревать на тихом огне до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1050,'Выложить на поверхность сыр, дать расплавиться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1051,'Куриную грудку или филе отварить до готовности, достать из воды, остудить и нарезать небольшими ломтиками. Огурец, ветчину и помытый помидор нарезать таким же образом что и куриное мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1051,'Сложить курицу, ветчину, помидор и огурец в большую миску, добавить соль и майонез и хорошенькое все перемешать. Получившийся салат «Русская красавица» с курицей и ветчиной выложить на большое блюдо в виде горки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1052,'Для начала я приготовил «обмазку» для тостового хлеба. В тарелку добавил кусочек сливочного масла, далее отправил в микроволновку, чтобы масло растопилось. Спустя минуту достал тарелку с растопленным маслом и добавил туда по вкусу соль, перец, смесь приправ, сушеный чеснок, красную паприку, все хорошо перемешал.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1052,'Далее подготовил ингредиенты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1052,'Далее, обмазкой смазал 1 сторону тостового хлеба, (10 ломтиков)
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1059,'Расстелить на столе лаваш, намазать его смесью майонеза с томатной пастой или соусом «Кетчуп».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1059,'Выложить измельченные продукты, морковь по-корейски, сыр – сверху.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12817,'Готовить минут сорок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1052,'Далее берем фольгу, на неё укладываем наши бутерброды, после этого нужно завернуть фольгу так, чтобы получились небольшие бортики. Далее, я добавил ингредиенты, которые остались, и сверху посыпал сыром. Отправил в духовку при 180°С на 5-7 минут! Все готово!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1053,'Разрежьте тыкву пополам, уберите семечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1053,'Нарежьте тыкву на крупные куски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1053,'Положите кусочки тыквы на противень, застеленный фольгой, налейте немного воды и накройте фольгой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1053,'Выпекайте при 200°С 40-60 мин. Если нож легко входит в тыкву, значит она готова.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1053,'Отделите остывшую тыкву от кожуры.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1053,'С помощью блендера взбейте тыкву до состояния пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1053,'Разложите пюре по контейнерам. Пюре можно хранить в холодильнике или заморозить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1054,'Куриное филе нарезать небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1054,'Смешать сметану, паприку, белый молотый перец и соль.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1054,'В это время подготовить панировку. Несладкие кукурузные хлопья перемолоть блендером. Натереть сыр. Перемешать с кукурузными хлопьями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1054,'Каждый кусочек куриного филе обвалять в панировке. Выложить на противень, застеленный пергаментной бумагой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1054,'Запекать в духовке, разогретой до 200°С, 30 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1055,'Приготовить голландский соус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1055,'Отделить белок от желтка, второй прогреть на водяной бане, помешивать, чтобы продукт не свернулся.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1055,'Добавить топленое сливочное масло, лимонный сок, перец молотый и соль по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1055,'Перемешать, снять с водяной бани.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1055,'В кипящую с солью воду влить яблочный уксус, помешивать жидкость ложкой или венчиком так, чтобы получилась воронка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1055,'Осторожно опустить яйца без скорлупы, варить до всплытия.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1055,'Булочку разрезать на две части, обжарить на сковороде, выложить на половину бутерброда яйцо, полить голландским соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1056,'Вскипятить воду, положить куриное мясо с косточками, варить 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1056,'Мелко нашинковать репчатый лук и морковь, жарить на сковороде с растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1056,'Промыть в воде рис, всыпать в суп за 20 минут до его готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1056,'Нарезать кубиками картофель, положить в суп за 10 минут до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1056,'Когда продукты станут мягкими – добавить овощную обжарку, томатную пасту, аджику, хмели-сунели, чеснок, соль, перец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1056,'Снять готовое блюдо с огня.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1057,'Отварить печень и яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1057,'Лук и натертую морковь обжарить до мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1057,'Подготовить все составляющие салата натерев как и морковь на крупной терке.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1057,'Сборка (Между слоями майонезная сеточка) :
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1057,'Украсить бока нарезанным укропом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1057,'Можно пробовать,но лучше дать несколько часиков настояться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1058,'Просушить куриное филе с помощью кухонных полотенец.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1058,'Замариновать мясо.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1058,'Затем поместить в пакет для запекания.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1058,'Запекать 2 часа при температуре 65 градусов по цельсию.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1058,'Затем достать, слить воду, убрать пергамент и запечь 3-4 минуты при 200 градусов.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1058,'Охладить и подавать к столу.','https://vkuso.ru/data/cache/data/8c/465488c43fa7d8c_434x295_notrise.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1059,'Нарезать небольшими кусочками свежие помидоры и маринованные огурцы, куриную грудку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1059,'Сыр натереть на мелкой терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1059,'Накрыть изделие еще одним лавашем, промазать соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1059,'Свернуть рулет, выложить на противень, верх смазать яйцом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1059,'Запекать в течение 20 минут, температура в духовке – от 170 до 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1060,'В большой посудине хорошенько перемешать творог с яйцами, сметаной, манкой, сахаром, ванилином, содой и солью. Бананы очистить от кожуры, нарезать кубиками размером 1х1 см и аккуратно подмешать ложкой в творожную массу. Сливочным маслом смазать форму для запекания, переложить в нее получившееся тесто и разровнять поверхность.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1060,'Поставить форму в духовку, прогретую до 180 градусов, и запекать творожно-банановую запеканку 50-60 минут, пока корочка не станет коричневого цвета. Готовую простую творожную запеканку с бананом достать из духовки, остудить прямо в форме и либо выложить на блюдо, либо разложить по тарелкам, нарезав порционными кусками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1061,'Маринованные или соленые огурцы натереть на мелкой терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1061,'Нашинковать чеснок и зелень укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1061,'Все ингредиенты добавить в сметану, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1061,'Соль – по вкусу, она не понадобится, если огурцы – соленые.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1062,'Репчатый лук очистить и нашинковать, жарить на растительном или сливочном масле в течение нескольких минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1062,'Добавить рыбное филе, прогревать все вместе еще десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1062,'Для приготовления омлета взбить сырые яйца с молоком, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1062,'Залить смесью рыбу с луком, потушить до свертывания омлета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1063,'Приготовить пельменное тесто: просеять муку, влить соленую воду, вымесить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1063,'Дать массе постоять полчаса для набухания клейковины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1063,'Для приготовления начинки добавить в мясной фарш соль, молотый перец, нашинкованный репчатый лук. Перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1063,'Готовое тесто тонко раскатать, промазать заранее растопленным сливочным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1063,'Скрутить в колбасу, разрезать на части, каждую прокрутить несколько раз и положить в морозильную камеру.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1063,'Тесто вынуть, разрезать на одинаковые части, раскатать лепешки. На поверхности лепешек должен получиться рисунок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1063,'Перевернуть лепешки рисунком вниз.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1063,'Выложить начинку, концы слепить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1063,'Пирожки переложить на застеленный пергаментом противень.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1063,'Намазать яйцом, поставить в духовой шкаф на 30 – 40 минут. Температура приготовления – 200 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1064,'Нашинковать зеленый лук, потушить на сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1064,'Отварить куриные яйца, нашинковать, посолить, добавить в лук, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1064,'Для приготовления теста взбить сырые куриные яйца с сахарным песком и солью, влить кефир, продолжать взбивать венчиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1064,'Просеять муку и разрыхлитель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1064,'Замесить тесто, оно должно получиться густым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1064,'Подготовить форму для выпекания, вылить большую часть теста, сверху – начинка, затем – оставшееся тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1064,'Поставить пирог в духовой шкаф на 30 или 40 минут, температура приготовления – 180 градусов. Проверить готовность пирога спичкой или зубочисткой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1065,'Рябину провариваем в 100 мл воды в течении 10-15 минут после закипания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1065,'Добавляем чеснок, листики базилика без веточек и измельчаем до однородного состояния погружным блендером или измельчителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1065,'Добавляем все специи и доводим массу до кипения, даем прокипеть 1-2 минуты и вливаем лимонный сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1065,'Снимаем с огня и расфасовываем по стерильным сухим баночкам.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1066,'Отварить сперва цветную капусту в течении 5 минуты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1066,'Сделать заправку для овощей, смешав помидор, специи и масло.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1066,'Выложить на противень все овощи и залить заправкой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1066,'Сверху посыпать сухариками.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1066,'Запечь в духовке при 200 градусов 20 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1067,'Отварить куриную грудку и яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1067,'Филе нарезать кубиками небольшого размера, выложить в салатник, подсолить и заправить майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1067,'Свежий огурец и сельдерей нарезать небольшими кусочками, выложить на курицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1067,'Этот слой также подсолить и намазать майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1067,'Третий слой – тертые яйца с солью и майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1067,'Сверху насыпать кукурузу из банки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1068,'Сливочное масло перетереть с половиной нормы сахарного песка ванилином, это можно сделать венчиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1068,'Добавить творог, массу еще раз взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1068,'Отдельно перемешать и взбить оставшийся сахар и куриные яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1068,'Добавить творожную массу, еще раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1068,'Муку просеять вместе с разрыхлителем, всыпать немного пищевой соды, перемешать массу лопаткой, всыпать промытый изюм.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1068,'Тесто переложить в смазанную форму для выпекания, время приготовления – один час, температура – 170 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1069,'Отделить белки от желтков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1069,'Белки взбить при помощи миксера в течение нескольких минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1069,'Всыпать порциями сахар с ванилином, продолжать взбивать. Сахар должен раствориться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1069,'Те же операции проделать с сырыми желтками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1069,'В массу просеять муку и разрыхлитель, ингредиенты перемешать с помощью лопатки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1069,'Готовое тесто перелить в форму для выпекания, время приготовления – от 30 до 40 минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1069,'Для крема взбить жирные сливки, сгущенное молоко добавлять постепенно, ложками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1069,'Измельчить очищенный арахис, всыпать в крем и перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1069,'Испеченный бисквит разрезать поперек на три части, каждую промазать кремом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1069,'Готовый торт поставить в холодильник на ночь.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1070,'В стакане кефира растворить пищевую соду, соль, сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1070,'Смесь взбить при помощи венчика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1070,'Просеять муку, всыпать тертый сыр, замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1070,'Скатать массу в колбасу, разрезать на одинаковые части, раскатать в лепешки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1070,'Выложить начинку из тертой ветчины, накрыть второй лепешкой, концы скрепить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1070,'Раскатать лепешку скалкой несколько раз.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1070,'Жарить изделия с двух сторон на растительном масле.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1071,'Промыть и нарезать любым способом огурцы, помидоры, сельдерей, сладкий болгарский перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1071,'Добавить кубики сыра «Фета».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1071,'Блюдо посолить и поперчить, заправить растительным маслом, сбрызнуть лимонным соком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1072,'Лук, морковь и картофель очистить, промыть и вместе с сельдереем мелко нарезать. Нарезать тонкие ломтики бекона мелкими кусочками, переложить в толстодонную кастрюлю, поставить на средний огонь и обжаривать кусочки в районе 15 минут – бекон должен стать хрустящим, а жир полностью вытопится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1072,'Готовый бекон вынуть из кастрюли, почти весь жир слить и поставить немытую емкость обратно на средний огонь. Всыпать в кастрюлю подготовленную морковь, лук и сельдерей и, помешивая, обжаривать овощи примерно 2 минуты. Добавить к овощам картофель, жарить все вместе 5 минут, добавить молотый перец , соль и смесь специй по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1072,'Затем залить овощи бульоном, довести его до несильного кипения и варить около 10 минут – картофель должен начать размягчаться. В отдельной мисочке смешать молоко с мукой (комочков быть не должно!), влить эту смесь в суп и варить его 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1072,'Налить в чашу блендера 2/3 супа, перебить его до однородности, перелить обратно в кастрюлю, подогреть, добавить специи (если нужно), сливки и рубленую петрушку. Подавать домашний картофельный суп-пюре с кусочками обжаренного бекона, посыпав каждую порцию тертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1073,'Отварить курицу, нарезать кубиками небольшого размера. Лучше всего подойдет грудка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1073,'Нарезать кубиками свежий огурец и болгарский перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1073,'Репчатый лук перед нарезанием лучше обдать кипятком, чтобы не горчил.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1082,'Противень застелить пергаментом, выложить булочки, смазать яйцом и присыпать кунжутным семенем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1073,'Открыть банку с консервированной кукурузой, слить жидкость, добавить к остальным ингредиентам, посолить, заправить сметаной или майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1074,'Отжать сок от половины лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1074,'Добавить горчицу в зернах, мёд, оливковое масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1074,'Перемешать, не солить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1074,'Мясо должно полежать в этом маринаде несколько часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1075,'Разбить сырые куриные яйца, всыпать сахарный песок, влить молоко, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1075,'Отдельно перемешать муку с сахарным песком и разрыхлителем, добавить соль и ванилин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1075,'Всыпать в молочную смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1075,'Перемешать массу венчиком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1075,'Печь блинчики на сухой горячей сковороде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1076,'Налейте в кастрюлю воды на половину и доведите до кипения, убавьте огонь до минимума. В небольшой миске смешайте желтки, воду и лимонный сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1076,'Поставьте миску на кастрюлю. Важно, чтобы миска не касалась воды, а находилась на водяной бане. Непрерывно помешивайте желтки венчиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1076,'Когда они начнут густеть и приобретут консистенцию густой сметаны, добавьте небольшие кусочки сливочного масла. Оно должно быть мягким, но немного холодным, чтобы сразу забрать температуру соуса на себя.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1076,'Варим соус еще 1 минуту на водяной бане, постоянно помешивая, затем снимаем миску с кастрюли и продолжаем перемешивать соус еще 1 минуту, добавляем соль. Подаем соус теплым.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1077,'Смешать творог, сметану, яйца, сахар кукурузный крахмал соль и ванилин до однородности и перелить в форму для выпекания 20 см диаметром,отправляем в разогретую духовку до 180 градусов на 50 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1077,'После выпекания оставляем в форме до полного остывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1077,'Для крема смешаем сметану и сахарную пудру до однородности.','https://vkuso.ru/data/cache/data/44/2a342b3e54b6444_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1077,'После того как запеканка остыла покрываем сметанным кремом и украшаем ягодой.','https://vkuso.ru/data/cache/data/6b/5c168cadf977b6b_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1078,'Промыть лимон, снять кожицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1078,'Выдавить сок из мякоти.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1078,'Отдельно перемешать сахарный песок и мягкое сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1078,'Всыпать муку, пищевую соду, соль, вбить яйца, добавить несколько капель лимонного сока, разбавленного водой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1078,'Тесто перемешать, разложить в формы. Время выпекания – 20 минут, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1078,'Для приготовления лимонного сиропа разбавить водой оставшийся сок, варить его вместе с цедрой и сахаром в течение пяти или десяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1078,'Полить горячие кексы, подать к столу влажными.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1079,'Ветчину и помидоры нарезать кубиками небольшого размера, пересыпать в салатницу. Если томаты слишком сочные – лишнее лучше слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1079,'Всыпать фасоль из банки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1079,'Для соуса: добавить в майонез давленый чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1079,'Заправить салат, подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1080,'Очистить куриную печень от пленок, разрезать на средние кусочки, кровяные сгустки удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1080,'Почистить и нашинковать репчатый лук и морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1080,'Овощи обжарить на сковороде с растительным маслом, добавить кусочки печени, прогревать все вместе две или три минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1080,'Влить немного воды, потушить еще десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1080,'Очистить от кожуры большое яблоко, натереть, добавить к печени, тушить от семи до восьми минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1081,'Нарезать помидоры колечками поперек, толщина – полсантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1081,'Точно также нарезать сыр «Моцарелла».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1081,'В центр тарелки выложить красный базилик и рукколу, вокруг – помидоры и сыр, кружочки чередовать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1081,'Закуску посолить и поперчить, сбрызнуть оливковым маслом, посыпать семечками кунжута.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1082,'Приобретенное в магазине слоеное тесто немного раскатать, нарезать полосками, ширина – от семи до восьми сантиметров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1082,'Сыр «Сулугуни» натереть на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1082,'Выложить начинку посередине, плотно защипать края.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1082,'Перевернуть изделие швом вниз, смочить водой один бок, свернуть «улитку».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12899,'Укроп нашинковать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1082,'Поставить в духовой шкаф. Время выпекания – от 20 до 25 минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1083,'Мелкими кубиками нарезать крабовые палочки, томаты и красный болгарский перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1083,'Натереть сыр на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1083,'В глубокую тарелку переложить все ингредиенты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1083,'Выдавить чеснок. Добавить майонез. Все хорошо перемешать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1084,'Смешать муку и щепотку соли.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1084,'Натереть слиовчное масло.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1084,'Добавить яйцо и замешать тесто.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1084,'Раскатать тесто, поместить в форму для выпечки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1085,'Нарезать курицу на порционные куски, смазать солью и молотым перцем и выложить в сотейник с растительным маслом. Обжарить кусочки курицы до золотисто-коричневой корочки со всех сторон (займет это примерно 15 минут) и переложить на тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1085,'Морковь очистить, промыть и нарезать по диагонали шайбами толщиной 10-15 мм, нарезать пастернак небольшими кубиками. Перец очистить от семян и нарезать квадратиками размером 2х2 см, очищенный лук мелко порубить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1085,'В сотейник положить измельченный лук, половину перца, 1 ст. л. рубленой петрушки, лаврушку, орегано и тимьян и жарить, помешивая, примерно 5 минут – лук должен стать прозрачным. Далее влить в сотейник воду или вино и тщательно все размешать – все имеющиеся комки должны полностью раствориться. Томаты размять, положить вместе с соком в сотейник и довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1085,'Положить в сотейник куриное мясо, морковь, оставшийся перец и пастернак и влить воду – она должна еле-еле покрывать мясо с овощами. Довести содержимое сотейника до кипения, накрыть крышкой и на маленьком огне тушить 15 минут. Затем крышку снять и готовить фрикасе по-креольски из курицы в томатном соусе еще 15-20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1086,'Для начала нужно разделить мак. Я его разделил по 50 грамм. Одну часть отставил для обсыпки. Вторую часть я пересыпал в глубокую тарелку, и залил чуть горячей водой. Это нужно для того чтобы мак набух. Заливаем мак и убираем в сторону на 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1086,'Также, нам будет нужно измельчить крекеры, для этого ломаем их в блендер, и измельчаем крекеры в крошку, и пересыпаем в миску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1086,'Спустя 15 минут, через сито сливаем воду от мака, также через сито продавливаем мак, чтобы вся вода отделилась. Мак перекладываем в другую тарелку, добавляем 1 ч.л. сахара и перетираем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1086,'В другую миску перекладываем творог, добавляем 4 ч.л. сахара и подготовленный мак, все хорошо перемешиваем. Можно добавить сироп по вкусу. Я добавил апельсиновый сироп Далее добавляем подготовленную крошку крекеров и снова перемешиваем. Часть крошки можно оставить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1086,'Из полученной массы делаем шарики, и обсыпаем их в маке, который вы должны были оставить. Все конфеты укладываем на тарелку, и можно отправить в холодильник на 15 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1087,'Вымыть виноград, грушу, манго, яблоки, киви и мандарины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1087,'Манго очистить от кожуры, нарезать кубиками небольшого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1087,'Виноградины разрезать пополам, они должны быть без косточек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1087,'Киви, грушу и яблоки очистить от кожуры и нарезать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1087,'Дольки мандарина очистить и нарезать кусочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1087,'Слить сок от консервированных ананасов, измельчить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1087,'Все составляющие перемешать в большой емкости.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1087,'Разложить в стеклянную посуду, охладить и подать к столу. Полить шампанским.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'Мелко нарезать красный лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'Залить кипящей водой, добавить немного уксуса, через десять минут жидкость слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'Куриную грудку натереть солью и, по желанию, карри.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'Приготовить в пароварке, другой вариант – отварить в подсоленной воде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'Мясо охладить, нарезать кубиками небольшого размера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'Так же поступить с куриными яйцами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'Нарезать мелкими кубиками маринованные огурцы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'«Российский» сыр натереть на крупной терке.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'Выложить на тарелку первый слой – картофельный.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'Смазать майонезом, второй слой – лук, майонез.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'Следующие – куриное филе, майонез, огурцы, майонез.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'Выложить оставшееся куриное филе.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'Сделать сеточку из майонеза, посыпать сыром, еще раз смазать майонезом и посыпать тертыми яйцами.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1088,'В качестве чешуек использовать нарезанные маринованные шампиньоны, хвостик – из перьев зеленого лука.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'Для приготовления соуса перемешать венчиком до однородного состояния сырой яичный желток с солью, перцем и горчицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'Каплями ввести оливковое масло, взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'Добавить раздавленный зубчик чеснока, подлить лимонный сок, всыпать тертый сыр «Пармезан».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'Соус должен получиться средней густоты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'На сковороду налить масло, положить раздавленные ножом зубчики чеснока, прогреть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'Подрумяненные зубчики вынуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'Обжарить нарезанное кусочками куриное филе. Соль и перец – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'Переложить мясо на тарелку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'Батон нарезать кубиками и обжарить в том же масле, посолить и поперчить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'Промыть салат «Айсберг», подсушить, порвать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'Полить соусом и перемешать, дать пропитаться.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'Нарезать на половинки помидоры черри.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'В центр блюда положить зеленый салат, затем куриное филе, продукты посыпать сыром «Пармезан».',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'По краям выложить помидоры.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'Посыпать сухариками, еще раз приправить соусом.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1089,'Украсить отваренными перепелиными яйцами.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1090,'Все пропустить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1090,'Кипятить около 2-х часов, перемешивая',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1090,'В конце варки за 15 минут добавить чеснок и зелень. Доварить, разлить в горячие банки и закрыть. Получается примерно 7.5 литров.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1091,'Печенье измельчим скалкой или в блендере, добавим растопленное масло перемешаем, 1\3 части отделим большую часть переложим в форму равномерно распределим и с помощью стакана утрамбуем дно и бортики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1091,'К сметане добавим пудру, ванилин, яйцо, крахмал и поставим на средний огонь, постоянно помешивая доведем до густоты, оставим остывать до комнатной температуры, после переливаем в форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1091,'Оставшуюся крошку посыпем сверху, отправим в холодильник на ночь для стабилизации. Торт готов, приятного аппетита!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1092,'Яйца отварить, очистить, желтки отложить для украшения, белки натереть  или измельчить и перемешать с майонезом. По отдельности измельчить желтки и зеленый лук, сайру в масле смешать с майонезом. Сыр мелко натереть и смешать с пропущенным через чесночницу чесноком и майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1092,'Собрать торт-салат, выкладывая ингредиенты слоями: крекеры, тертые белки, крекеры, майонез, сайра с майонезом, зеленый лук, крекеры, сырно-чесночная смесь, крекеры, майонез, измельченные желтки. Оставить торт-салат с сыром и крекером при комнатной температуре на 2 часа, затем убрать изделие в холодильник на 1 час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1093,'К теплому молоку добавим сахар дрожжи перемешаем, добавим сахар , соль и яйца перемешаем после просеем муку замесим тесто оставим на 15 минут под полотенцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1093,'После добавим масло и вмешаем его в тесто , месить придется до тех пор пока масло не вмешается. После оставим на час на отдохнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1093,'После тесто делим на 8 частей и закатаем в колобок переложим на противень застеленной пергаментом накроем полотенцем оставим на час ,после смазываем желтком перемешанным с водой и по желанию присыпаем кунжутом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1094,'Сварить кофе эспрессо, охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1094,'Отделить белки от яичных желтков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1094,'Взбить белковую массу, добавить сахарную пудру, продолжать взбивать до получения пышной массы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1094,'Желтки также смешать с сахарной пудрой, взбивать до побеления.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1094,'В эту массу частями вмешать сыр «Маскарпоне», затем добавить белки в несколько приемов. Получится крем однородной консистенции.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1094,'В остывший кофе добавить ликер.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1094,'Печенье «Савоярди» окунуть в смесь, выложить на дно формы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1094,'Следующий слой – крем, повторить несколько раз.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1094,'Посыпать торт сверху какао-порошком, закрыть пищевой пленкой и поставить в холодильник на ночь для пропитывания.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1095,'Спелый банан очистить и размять вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1095,'Влить растопленное сливочное масло, всыпать сахарный песок, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1095,'Взбить сырое куриное яйцо в пену и добавить в основную смесь. Перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1095,'Овсянку измельчить в блендере, подмешать в тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1095,'Часть шоколада порубить ножом, добавить в массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1095,'Сформовать шарики при помощи столовых ложек, выложить на бумагу для выпекания, смазанную маслом. Время выпекания – от 20 до 25 минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1096,'Просеять муку, добавить охлажденное сливочное масло и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1096,'Растереть массу вилкой, а затем руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1096,'Вбить яйцо, вымесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1096,'Раскатать лепешку толщиной от трех до четырех миллиметров.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1096,'Смазать форму маслом, выложить тесто и поставить в холодильник на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1096,'Для приготовления начинки мелко нарезать репчатый лук, обжарить на сковороде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1096,'Следом нарезать шампиньоны, добавить в лук, обжарить, соль – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1096,'Отварить в подсоленной воде куриную грудку, нарезать кусочками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1096,'Натереть твердый сыр, нарезать зелень укропа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1096,'Отдельно перемешать яйца со сливками, поперчить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1096,'Всыпать укроп и сыр.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1096,'Выложить в форму для запекания отваренную куриную грудку, затем грибы с луком, залить сливочной массой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1096,'Поставить киш в духовой шкаф, температура приготовления – 190 градусов, время – от 45 до 50 минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1096,'Готовый пирог остудить, подать к столу.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1097,'Спелые плоды разрезать пополам, вынуть косточку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1097,'Отделить ложкой мякоть от кожицы. Нарезать кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1097,'Помидоры черри разрезать на дольки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1097,'Залить кипящей водой замороженные креветки на три – пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1097,'Жидкость слить, креветки очистить, нарезать кусочками, добавить в овощную смесь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1097,'Нашинковать листья китайской капусты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1097,'Нарезать укроп.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1097,'Все перемешать, посолить и поперчить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1097,'Перемешать сметану и майонез в равных количествах, добавить лимонный сок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1097,'Готовый салат переложить в половинки авокадо.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1098,'Растопить сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1098,'Отдельно перемешать муку с какао-порошком, пищевой содой, сахаром, разрыхлителем и ванилином из пакетика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1098,'Натуральный йогурт перемешать с яйцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1098,'Влить масло в сухие продукты, перемешать, добавить йогурт с яйцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1098,'Порубить ножом темный шоколад, вмешать в тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1098,'Наполнить одноразовые или силиконовые формочки тестом на две трети объема.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1098,'Время выпекания – от 20 до 25 минут, температура – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1098,'Готовность проверить спичкой или зубочисткой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1098,'Готовую выпечку смазать растопленным на водяной бане шоколадом, посыпать орешками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1099,'Приготовить тонкие блинчики по любимому рецепту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1099,'Протереть через сито творог, добавить сметану, сахарную пудру, перемешать до однообразной консистенции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1099,'Нарезать соломкой грушу, киви и манго. Другой вариант – ананас и клубника.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1099,'Подготовить циновку для суши, сверху – пакет или пленка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1099,'Выложить блин, намазать творогом, выложить полоски фруктов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1099,'Скрутить в рулет, уплотнить, нарезать порционно.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1100,'Раздавить зубчики чеснока, обжарить на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1100,'Чеснок вынуть и выбросить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1100,'На сковороду выложить репчатый лук, нарезанный маленькими кубиками, жарить до прозрачности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1100,'Нарезать такими же кубиками морковь, добавить в лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1100,'Нарезать красный сладкий болгарский перец, добавить в обжарку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1100,'По желанию положить измельченный сельдерей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1100,'Овощи жарить в течение пяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1100,'Добавить фарш из постной говядины.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1100,'Жарить все вместе в течение 20 – 25 минут до состояния гранул.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1100,'Всыпать специи, потушить десять минут под крышкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1100,'Влить массу из нарезанных томатов в собственном соку. Другой вариант – свежие нарезанные помидоры со снятой кожурой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1100,'За три минуты до готовности добавить давленый чеснок.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1100,'Отварить спагетти так, как указано на упаковке, добавить оливковое масло, чтобы продукт не слипся.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1100,'Сформовать на тарелке гнезда небольшого размера, выложить мясной соус и посыпать тертым сыром «Пармезан».',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'Аккуратно отделить белки от желтков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'Белки взбить с сахарным песком в плотную пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'Добавить желтки и перемешать массу при помощи миксера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'Всыпать муку небольшими порциями, ввести разрыхлитель и какао-порошок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'Разъемную форму смазать сливочным маслом, вылить тесто, поставить в духовой шкаф на 40 минут. Температура приготовления – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'Вишню разморозить, посыпать сахаром и дать постоять.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'Для приготовления сметанного крема взбить продукт с сахарным песком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'Слить сок от вишни, добавить немного коньяка.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'Измельчить ножом кешью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'Бисквит немного остудить, вынуть из формы и разрезать по горизонтали на две неравные части.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'Меньшую часть пропитать вишневым соком, большую нарезать кусочками-кубиками.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'Пропитанный корж намазать сметанным кремом, посыпать орешками и вишней.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'Кусочки нарезанного бисквита окунать в сметанный крем и выкладывать горкой, чередуя слои с орехами и ягодами.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'По желанию между слоями можно добавить растопленный шоколад.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1101,'Залить торт остатками крема, украсить растопленным шоколадом, орехами и вишней.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1102,'Сварить вкрутую яйца, хорошо их остудить, очистить и натереть на мелкой или средней терке. Натереть сырки на средней терке, очищенный чеснок пропустить через чеснокодавку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1102,'Все подготовленные ингредиенты соединить и перемешать с майонезом. Получившуюся массу разделить пополам: из первой половины скатать шарики побольше, из второй – поменьше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1102,'Собрать из шариков закуску «Сырные снеговики»: большой шарик – туловище, маленький – головка. Из сыра вырезать пуговки и шляпки, из сырой морковки сделать носик и глазки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1103,'Грецкие орехи измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1103,'Свеклу запечь в фольге или отварить, затем нарезать кусочками небольшого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1103,'Промыть и обсушить рукколу, выложить на блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1103,'Сверху – часть свеклы, шарики, сформованные из творожного сыра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1103,'Посыпать орехами, кунжутными семечками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1103,'Заправить бальзамическим соусом, оливковым маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1104,'Замороженные креветки посолить, залить кипящей водой для оттаивания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1104,'Нарезать кусочками, несколько штук оставить для украшения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1104,'Отварить куриные яйца, очистить, нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1104,'Ингредиенты перемешать, добавить нарезанную морскую капусту, заправить майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1104,'Поместить в разъемную форму на тарелке, уплотнить, снять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1104,'Украсить капельками майонеза и оставшимися креветками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1105,'Молодой картофель вымыть, разрезать каждый клубень на несколько частей, кожуру не снимать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1105,'Для приготовления маринада смешать измельченный чеснок с маслом, молотым перцем, солью, паприкой и карри.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1105,'Залить картофель, перемешать, оставить для пропитывания на 10 – 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1105,'Выложить дольки в форму для запекания или на противень в один слой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1105,'Время приготовления – полчаса, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1105,'Затем температуру прибавить до 200 – 220 градусов, печь еще 20 – 25 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1105,'Соус приготовить из сметаны, измельченного чеснока и рубленой зелени укропа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1106,'Баклажаны нарезать на небольшие пласты вдоль, толщина – от трех до четырех миллиметров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1106,'Налить оливковое масло на разогретую сковороду, выложить овощи, посолить и поперчить по вкусу, обжарить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1106,'Для начинки перемешать рикотту с солью и перцем, давленым чесноком и рубленым укропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1106,'Выложить начинку на баклажановые слайсы, свернуть рулетами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1107,'Отварить куриное филе в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1107,'Нарезать кусочками, переложить в салатницу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1107,'Слить жидкость от консервированных ананасов, нарезать их кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1107,'Натереть сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1107,'Порубить ножом грецкие орехи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1107,'Нарезать зелень укропа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1107,'Все ингредиенты перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1107,'Для заправки использовать смесь из равных частей сметаны и майонеза.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1107,'Выложить на блюдо в разъемную форму, уплотнить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1107,'Форму снять.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1107,'Украсить башенку ананасами, маслинами, оставшимися кусочками грецких орехов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1108,'Яблоки вымыть, очистить от кожуры, вынуть сердцевину, нарезать мякоть кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1108,'Присыпать фрукты молотой корицей и сахарным песком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1108,'Для приготовления теста сырые куриные яйца взбить в пену при помощи миксера, сахар добавлять постепенно, порциями. Время взбивания – от пяти до семи минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1108,'Всыпать просеянную муку, ванильный сахар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1108,'Форму для запекания смазать сливочным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1108,'На дно вылить часть теста, выложить начинку, поставить пирог в духовку на 40 или 45 минут, температура выпекания – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1108,'Шарлотка должна подрумяниться, духовой шкаф не открывать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1108,'Пирог вынуть, немного остудить и посыпать сахарной пудрой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1109,'В большую емкость положить мягкое сливочное масло, натуральный мед, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1109,'Смесь поставить в микроволновку на 30 или 40 секунд.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1109,'Всыпать какао-порошок, измельченный имбирь, молотую корицу. Еще раз перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1109,'Вбить сырые куриные яйца, ванильный и обычный сахар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1109,'Взбивать до пышности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1109,'Обе смеси соединить, всыпать просеянную муку, разрыхлитель, половину цедры лимона.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1109,'Тесто вымешивать до тех пор, пока оно не перестанет прилипать к рукам.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1109,'Выложить на присыпанную мукой поверхность, раскатать до толщины в полсантиметра, нарезать печенье при помощи формочек.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1109,'Застелить противень бумагой для выпекания, выложить изделия, в пряниках проделать дырочки, чтобы их потом можно было повесить на новогоднюю елку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1109,'Печь в заранее разогретой духовке, температура – 180 градусов, время – от 10 до 12 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1109,'Для приготовления глазури понадобится сахарная пудра, лимонный сок, белок.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1109,'Смазать пряники кулинарной кистью, украсить цукатами, орехами, кондитерскими посыпками, оставить до застывания.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1110,'Куриное филе отварить, нарезать кусочками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1110,'Измельчить грецкие орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1110,'Чернослив нарезать полосками, добавить в салатницу вместе с остальными ингредиентами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1110,'Апельсин вымыть и фигурно нарезать по кругу, удалить мякоть ложкой, нарезать ее кусочками, добавить в основную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1110,'Твердый сыр натереть, листья зеленого салата порвать кусочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1110,'Салат посолить и поперчить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1110,'Для заправки перемешать сметану с майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1110,'Выложить закуску в апельсиновые формочки, украсить листочками зеленого салата, посыпать грецкими орехами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1125,'Отварить клубни картофеля, свеклу, морковь, яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1111,'Залить кипятком замороженные креветки на две или три минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1111,'Жидкость слить, морепродукты очистить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1111,'Раздавить ножом чеснок, положить в заранее разогретое масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1111,'Сладкий болгарский перец нарезать соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1111,'Очистить от пленок шампиньоны, нарезать крупными кусочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1111,'Жарить три минуты на огне средней мощности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1111,'Добавить сладкий перец, жарить еще три минуты, помешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1111,'Отварить фунчозу по инструкции на этикетке.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1111,'Слить воду, лапшу промыть холодной водой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1111,'Добавить креветки в обжарку, все вместе прогреть две минуты, поперчить, посолить, подлить соевый соус.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1111,'Добавить лапшу и зеленый горошек из банки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1111,'Перемешать, прогревать три минуты.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1112,'Филе индейки промыть, нарезать кусочками толщиной в один сантиметр поперек волокон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1112,'Мясо отбить через полиэтиленовый пакет с двух сторон, посолить, поперчить, добавить другие специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1112,'Форму или противень смазать маслом, выложить филе в один слой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1112,'Для соуса перемешать сметану с майонезом, поперчить, подлить немного воды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1112,'Выложить на мясо нарезанный репчатый лук, сверху – соус, тонкие кружочки картофеля, снова соус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1112,'Следующий слой – грибная обжарка, еще один слой картофеля, соус.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1112,'Блюдо по желанию можно подсолить и поперчить послойно.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1112,'Сверху – полукольца помидоров, сметанный соус.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1112,'Форму затянуть фольгой, печь в духовом шкафу в течение часа, температура – до 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1112,'За 10 минут до окончания приготовления фольгу снять, присыпать запеканку сыром.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1113,'Картофель отварить, натереть, выложить на блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1113,'Смазать смесью из сметаны и майонеза в равных пропорциях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1113,'Отварить морковь, натереть, выложить вторым слоем, смазать той же заправкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1113,'Третий слой – картофель, соус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1113,'Отварить куриное мясо, нарезать кубиками, выложить на картофель, соус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1113,'Следующий слой – сыр, соус.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1113,'Посыпать измельченными грецкими орехами, выложить еще один слой куриного филе, смазать соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1113,'Следующий слой – тертые отваренные яйца, соус.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1113,'Присыпать салат зернышками граната, оформить кайму.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1114,'Нарезать мелкими кубиками репчатый лук, залить кипящей водой с уксусом на десять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1114,'Жидкость слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1114,'Отварить свиной язык в подсоленной воде, охладить, снять пленки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1114,'Мясо нарезать брусками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1114,'Порубить зелень петрушки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1114,'Отварить и нарезать кубиками куриные яйца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1114,'Открыть банку с фасолью, слить жидкость.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1114,'Все ингредиенты соединить, посолить и поперчить, заправить майонезом, хорошо перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1114,'Выложить салат на блюдо в разъемную форму, утрамбовать, стенки снять.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'Отварить куриные и перепелиные яйца, остудить в холодной воде, снять скорлупу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'Репчатый лук очистить, тонко нарезать, залить кипящей водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'Очистить картофель, нарезать тонкой стружкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'Обжарить во фритюре, время приготовления – от четырех до пяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'Стружки выложить на бумажное полотенце, чтобы впитался лишний жир.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'Плавленый и обычный сыр натереть на крупной терке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'То же проделать с куриными яйцами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'Укроп порубить ножом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'Филе курицы нарезать кубиками или соломкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'Нарезать соломкой свежие огурцы.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'На большое блюдо плоской формы выложить лук, заранее слив жидкость. На лук выложить куриное филе и смазать майонезом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'Второй слой – огурцы, майонез.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'Третий – куриные яйца, майонез.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'Посыпать тертым сыром, в середине сделать углубление.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'Смазать майонезом.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'В середину выложить зелень, бока обложить жареным картофелем.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1115,'На зелень положить очищенные перепелиные яйца.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1116,'Слоеное тесто разрезать на полоски желаемого размера, выложить их на небольшом друг от друга расстоянии на противень, смоченный холодной водой, и оставить на 10 минут. По прошествии отведенного времени поместить противень с тестом на 15 минут в духовку, нагретую до 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1116,'Готовые полоски достать из духовки и полностью охладить. Кофе сварить или приготовить в кофеварке, дать ему немного остыть. Желтки тщательно взбить с сахаром, чтобы последний полностью растворился. Смешать яичную смесь с мукой и порциями влить в нее теплый кофе. Аккуратно подмешать получившуюся массу в теплое молоко. Поставить кастрюльку со смесью на маленький огонь и варить, пока она не загустеет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1116,'Отдельно взбить в кремообразную массу размягченное масло с 2 ст.л. сахарной пудры, частями подмешать в нее остывший крем и добавить коньяк. Слоеные полоски разрезать пополам по горизонтали: нижнюю часть смазать кофейным кремом и накрыть верхней.  Выложить полоски из слоеного теста с кофейным кремом на большое блюдо, присыпать сахарной пудрой и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1117,'Картофель очистить и нарезать небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1117,'Отварить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1117,'Нарезать репчатый лук, обжарить на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1117,'Нарезать шампиньоны, добавить к луку, обжарить все вместе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1117,'Посолить и поперчить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1117,'Картофель истолочь в пюре, добавить грибы, измельчить все вместе при помощи погружного блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1117,'Влить куриный бульон, еще раз взбить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1117,'Влить молоко, сливки, перемешать до однородного состояния.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1117,'Поставить суп на плиту, довести до кипения.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1117,'Несколько пластинок грибов обжарить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1117,'Приготовить домашние сухари, обжарить батон на чесночном масле.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1118,'Репчатый лук нарезать мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1118,'Измельчить чеснок и обжарить то и другое на масле до прозрачного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1118,'Добавить говяжий фарш, жарить все вместе десять минут, перец и соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1118,'Добавить томатный сок, кубики свежего томата.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1118,'Потушить под крышкой десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1118,'Начинить каннелони.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1118,'Для соуса растопить сливочное масло, добавить муку, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1118,'Влить порциями холодное молоко, продолжать помешивать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1118,'Добавить соль и мускатный орех.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1118,'Перемешать, снять с огня.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1118,'Вылить в форму для запекания половину соуса, выложить каннелони с фаршем, посыпать тертым сыром «Пармезан».',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1118,'Вылить оставшийся соус, присыпать остатками сыра',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1118,'Время запекания – от 30 до 40 минут, температура – 180 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1119,'Подогреть молоко, перелить в глубокую мисочку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1119,'Всыпать сахарный песок и соль, влить растительное масло, вбить сырое яйцо. Хорошо перемешать, можно использовать блендер.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1119,'Добавить разрыхлитель или погасить 1 ч. л. пищевой соды лимонным соком и добавить в смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1119,'Просеять пшеничную муку, замесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1119,'Блинчики жарить на заранее прогретой сковороде, масло не использовать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1119,'Перевернуть при появлении пузырей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1119,'Выложить панкейки стопочкой, полить любимым вареньем, сгущенным молоком или сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1119,'Подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1120,'Для приготовления блюда подойдет зернистый творог.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1120,'Вбить яйцо, всыпать соль и сахар, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1120,'Просеять муку, добавить в основную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1120,'Выложить тесто на присыпанную мукой поверхность.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1120,'Раскатать колбаски, нарезать их кусочками под углом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1120,'Каждый кусочек обвалять в муке, сделать рельеф при помощи вилки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1120,'Отварить в подсоленной воде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1120,'Подать с вареньем или со сметаной.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1143,'Продукт подсушить в духовом шкафу при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1121,'Ветчину нарезать кубиками среднего размера, точно также поступить с огурцами, очищенными от кожуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1121,'Добавить сладкую кукурузу и фасоль из банки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1121,'Посыпать рубленым укропом, заправить майонезом, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1121,'Сухарики добавить перед подачей, чтобы они не успели размокнуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1122,'Две трети нормы муки просеять в емкость через сито, сделать углубление, вбить яйцо, посолить и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1122,'Влить подогретое молоко с водой, еще раз перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1122,'Досыпать остатки муки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1122,'Тесто выложить на присыпанный мукой стол, месить еще пять или семь минут, переложить в пакет и убрать в холодильник на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1122,'Для приготовления начинки прокрутить мясо через мясорубку, можно только говядину или говядину с добавлением свинины.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1122,'По желанию использовать блендер.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1122,'Добавить по вкусу соль и молотый перец, мелко нарезанный репчатый лук, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1122,'Если начинка слишком сухая – влить немного воды или молока.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1122,'Тесто вынуть из холодильника и еще раз вымесить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1122,'Отрезать небольшой кусочек, сформовать колбаску, нарезать кружочками, раскатать лепешки',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1122,'Выложить начинку, защипать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1122,'Пельмени отварить сразу или приготовить впрок и заморозить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1122,'В воду для варки добавить луковицу, соль, перец-горошек, лавровый лист.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1122,'После всплытия варить от трех до пяти минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1123,'Красный лук очистить, мелко нарезать, залить кипящей водой на десять минут. Жидкость слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1123,'Отварить картофель и морковь, очистить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1123,'Натереть овощи на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1123,'Отварить яйца, отделить желток.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1123,'Белки натереть на мелкой терке, желтки размять вилкой или руками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1123,'Натереть сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1123,'Открыть банку с консервированным тунцом, слить жидкость, рыбу размять вилкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1123,'Выложить на тарелку отварной картофель, примять, нанести майонезную сеточку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1123,'Второй слой – красный лук, затем рыба, майонез.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1123,'Посыпать белком, еще раз смазать майонезом, морковь, майонез, желток.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1123,'Поставить салат в холодильник на пять часов, можно на ночь, ингредиенты должны пропитаться.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1123,'Перед подачей украсить петрушкой, маслинами, укропом, кукурузой, перцем, яйцом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1123,'Из яйца можно сделать снеговика, из укропа – елочку, из кукурузы – елочные игрушки, звездочка на елке – из красного болгарского перца или яблока с кожурой.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Для приготовления опары понадобятся сухие дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Добавить сахарный песок, муку, влить теплую воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Ингредиенты перемешать и дать постоять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Для теста взять сырые куриные яйца, соль и сахар, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Поднявшуюся опару добавить в яичную смесь, перемешать, влить подогретое молоко, маргарин или растопленное сливочное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Еще раз перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Всыпать муку небольшими порциями.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Вымесить тесто.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Накрыть тканью, оставить на час в тепле без сквозняков.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Нарубить капусту, потушить на сковороде вместе с нарезанной или крупно натертой морковью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Тесто еще раз вымесить, разделить на две неравные части.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Раскатать большую часть в тонкую лепешку, переложить на застеленный пергаментом противень.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Выложить начинку, разровнять, оставить края по два сантиметра.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Накрыть меньшей частью теста, также раскатанной в лепешку.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Края красиво защипать.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Сырой желток развести водой, смазать пирог.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Время выпекания – от 30 до 40 минут, температура – 180 градусов.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Первые 20 – 25 минут духовку не открывать.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1124,'Пирог должен подняться и подрумяниться.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1125,'Слабосоленую селедку очистить от косточек, нарезать мелкими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1125,'Нарезать мелкими кубиками репчатый лук, залить на десять минут кипятком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1125,'Остальные овощи натереть на крупной терке по отдельности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1125,'Белок натереть на мелкой терке, желток раскрошить вилкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1125,'Первый слой – рыба, затем лук и майонез.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1125,'Следующий слой – картофель, затем морковь, белок, картофель, морковь, свекла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1125,'Все слои и верх намазать майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1125,'Края салата посыпать желтком. Блюдо поставить на ночь в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1126,'Репчатый лук очистить, мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1126,'Измельчить чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1126,'Лисички промыть и нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1126,'Филе курицы нарезать поперек волокон небольшими кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1126,'Поставить на огонь кастрюлю с водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1126,'Посолить, отварить макароны тельятелле или фетучини так, как написано на упаковке, до полуготовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1126,'Готовую пасту процедить, добавить оливковое масло, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1126,'Обжарить чеснок и лук, добавить куриное мясо, прогревать от пяти до семи минут, помешивать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1126,'Всыпать лисички, готовить 15 минут под крышкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1126,'Грибы должны уменьшиться в объеме и приобрести коричневатый оттенок.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1126,'Сливки разогреть в микроволновой печи и добавить в основную массу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1126,'Потомить несколько минут на тихом огне, посолить и поперчить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1126,'Добавить готовую пасту, перемешать, посыпать тертым сыром «Пармезан».',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1127,'Раздавить зубчик чеснока и обжарить его с оливковым маслом на заранее разогретой сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1127,'Чеснок вынуть и выбросить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1127,'В масло положить чищенные замороженные креветки, выпарить лишнюю жидкость в течение пяти минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1127,'Посолить и поперчить, приправить розмарином.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1127,'Рукколу и базилик выложить в глубокую салатницу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1127,'Нарезать помидоры дольками, свежие огурцы – соломкой. Кожуру можно не очищать, если она не горькая.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1127,'Выложить креветки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1127,'Полить блюдо оливковым маслом, посолить по вкусу, сбрызнуть лимонным соком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1127,'Ингредиенты перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1128,'Продукт промыть в холодной воде, удалить пленки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1128,'Поставить на плиту сковороду с растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1128,'Прогреть, выложить печень, обжаривать в течение пяти или семи минут. Можно под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1128,'Нарезать репчатый лук, добавить его к печени, жарить еще четыре минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1128,'Влить стакан кипящей воды, посолить, поперчить, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1128,'Время тушения – от 20 до 25 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1128,'Сливки разогреть в микроволновой печи в течение 30 секунд.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1128,'Подлить в печень, перемешать, подержать пять минут под крышкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Для приготовления соуса «Болоньезе» раздавить зубчик и прогреть его разогретом оливковом масле, затем выбросить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Нарезать репчатый лук кубиками, обжарить в чесночном масле до прозрачного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Мелкими кубиками нарезать морковь, положить в лук, затем туда же добавить кубики болгарского перца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Нарезать сельдерей и также добавить в овощную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Все вместе жарить пять минут, добавить фарш, приготовленный из постной говядины.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Жарить от 20 до 25 минут, всыпать любимые специи, потушить под крышкой еще десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Добавить нарезанные томаты в собственном соку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Другой вариант: свежие нарезанные помидоры без кожуры.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'За три минуты до готовности добавить давленый чеснок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Для приготовления соуса «Бешамель» понадобится посуда с толстым дном.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Растопить в ней сливочное масло, всыпать муку, перемешать до однородного состояния.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Влить тонкой струйкой холодное молоко, постоянно помешивать, в соусе не должно быть комочков.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Добавить соль и молотый мускатный орех.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Перемешать, снять с огня. Соус должен быть средней густоты.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'На дно жаропрочной стеклянной формы налить немного соуса «Бешамель».',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Выложить сухие листья лазаньи, которые не требуют предварительного отваривания.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Поверх выложить мясной соус, разровнять.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Присыпать тертым сыром «Пармезан» или любым другим твердым.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Поверх налить соус «Бешамель».',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Слои повторять до тех пор, пока ингредиенты не закончатся.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Поставить лазанью в духовой шкаф на 35 или 40 минут, температура выпекания – 180 градусов.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1129,'Готовое блюдо должно легко протыкаться вилкой.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1130,'Нарезать крупными кубиками огурцы, выложить в салатницу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1130,'Помидоры черри разрезать пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1130,'Сладкий болгарский перец очистить от семян, нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1130,'Сыр «Фета» нарезать крупными кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1130,'Все ингредиенты перемешать, добавить красный лук, нарезанный кольцами, и маслины.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1130,'Приправить специями, полить оливковым маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1131,'Спелые плоды авокадо разрезать пополам, вынуть косточку и выскрести мякоть ложкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1131,'Нарезать кубиками, сбрызнуть лимонным соком, чтобы не почернела.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1131,'Размять вилкой консервированную рыбу, добавить к авокадо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1131,'Красный лук нарезать, залить кипятком на несколько минут, воду слить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1131,'Посолить, поперчить, влить оливковое масло, посыпать рубленым укропом, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1131,'Начинить смесью лодочки авокадо, украсить зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1132,'Подготовить ягоды: помыть, обсушить, аккуратно удалить чашелистики, смешать с сахарным песком, переложить в мультиварку, всыпать измельченные грецкие орехи, залить небольшое количество воды. Выставить режим «Тушение», готовое варенье из клубники в мультиварке можно будет пробовать через час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1133,'Макароны-спиральки отварить до готовности, охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1133,'Отварить и очистить креветки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1133,'Перемешать продукты в большой миске, добавить мелко нарезанный зеленый лук, половинки консервированных оливок без косточек, молодой зеленый горох.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1133,'Порвать руками листья салата.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1133,'Выложить на тарелку, сбрызнуть лимонным соком, посыпать сухариками и тертым сыром «Пармезан».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1134,'Нарежьте бекон небольшими кусочками. В сухой сковороде обжарьте бекон на сильном огне до золотистого цвета перемешивая. Переложите на бумажное полотенце. Мелко нарежьте зеленый лук. Натрите сыр на мелкой терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1134,'В одной миске смешайте муку с содой и разрыхлителем. В другой миске смешайте кефир, сметану, яйцо (1 шт.) и растительное масло. Соедините жидкую часть с сухой, добавьте бекон и перемешайте. Затем всыпьте лук и сыр и снова перемешайте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1134,'Формы для запекания смажьте растительным масло, затем в формы выложите по 1 столовой ложке теста, в центре сделайте углубление и вбейте по 1 яйцу в каждую формочку. Поверх яиц выкладываем оставшееся тесто, так что бы не повредить яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1134,'Разогрейте духовку до 180 градусов и отправьте маффины выпекаться до золотистого цвета (около 45 минут).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1135,'Огурцы нарезать колечками. Авокадо очистить от кожуры и нарезать тонкими слайсами (слайсы можно нарезать поменьше).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1135,'В тарелку выложить рукколу, огурцы, авокадо и ежевику. Посыпать кунжутными и тыквенными семечками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1135,'Заправить салат оливковым маслом и соком лайма.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1136,'Филе курицы надрезать поперек волокон, хорошо натереть молотым перцем и солью, оливковым маслом и измельченным корнем имбиря',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1136,'Выложить в духовой шкаф, запекать в течение 20 минут, температура – 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1136,'Вынуть из духовки, охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1136,'Белый хлеб нарезать кубикам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1136,'Жарить на сковороде с маслом и давленым чесноком до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1136,'Гренки должны приобрести золотистый цвет.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1136,'Отварить всмятку яйцо, отделить желтки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1136,'Добавить к желткам уксус, горчицу, растительное масло и сахарный песок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1136,'Соус хорошо перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1136,'Порвать руками салат «Ромэн». Выложить в емкость, сбрызнуть горчичным соусом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1136,'Добавить отваренные креветки и филе курицы.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1136,'Салат залить соусом, посыпать гренками и тертым сыром «Пармезан».',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1137,'Креветки отварить, очистить и охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1137,'Выложить на тарелку листья зеленого салата, приготовить яйца-пашот.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1137,'На салатные листья выложить креветки, яйца, посыпать сыром «Пармезан», заправить соусом «Цезарь».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1138,'Филе курицы посолить, поперчить, посыпать любимыми специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1138,'Жарить на сковороде по семь-десять минут с каждой стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1138,'Переложить в миску, подержать под крышкой десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1138,'Нарезать свежий хлеб кубиками, выложить на противень, добавить целые зубчики чеснока, полить растительным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1138,'Поставить в духовку, печь до румянца, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1138,'Пекинскую капусту нарезать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1138,'Натереть сыр «Пармезан».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1138,'Готовую куриную грудку нарезать ломтиками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1138,'Приготовить заправку из соевого соуса, майонеза, сметаны, лимонного сока, измельченного чеснока.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1138,'Продукты выложить в миску, полить готовым соусом, перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1138,'Выложить салат на тарелку, украсить сухариками, нарезанными помидорами, посыпать сыром.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1139,'Куриную грудку нарезать кусочками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1139,'Залить маринадом: измельченный зубчик чеснока, специи для куриного мяса, лимонный сок, соевый соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1139,'Ингредиенты перемешать, оставить для пропитывания на два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1139,'Белый батон нарезать кубиками, жарить на оливковом масле с рубленым чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1139,'Обжарить маринованную курицу, по две-три минуты с каждой стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1139,'Выложить на тарелку порванный руками салат «Латук».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1139,'Сверху – кусочки обжаренной курицы, соус «Цезарь», гренки, тертый сыр «Пармезан», помидоры черри, разрезанные пополам.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1140,'Приготовить салатную заправку из майонеза, тертого твердого сыра, тертого чеснока, лимонного сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1140,'Ингредиенты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1140,'В миске смешать нарезанный салат «Латук», кубики заранее отваренной курицы, ломтики шампиньонов, половинки помидоров черри.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1140,'Залить соусом, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1140,'Посыпать сухариками и сыром «Пармезан».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1141,'Приготовить заправку из растительного масла, лимонного сока и майонеза, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1141,'Смесь налить в соусник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1141,'Серый хлеб нарезать кубиками, жарить на растительном масле до появления золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1141,'Соль и перец – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1141,'Порвать капусту, добавить отваренную курицу, сухари, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1141,'Подать салат отдельно от соуса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1142,'Приготовить заправку из сырого куриного желтка, горчицы, красного винного уксуса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1142,'Соус взбить до густоты, добавить оливковое масло, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1142,'Анчоусы измельчить вместе с чесноком, добавить в заправку, всыпать тертый сыр «Пармезан», влить лимонный сок, добавить воду, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1142,'Приготовить гренки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1142,'Батон нарезать кубиками, посолить и поперчить, насыпать на сковороду с прогретым оливковым маслом, жарить до золотистого цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1142,'Всыпать на сковороду тертый сыр, перемешать. Гренки не должны слипнуться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1142,'Куриную грудку нарезать бабочкой, посолить и поперчить, выложить на горячую сковороду-гриль, жарить по три или четыре минуты с каждой стороны.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1142,'Готовую курицу обмазать заправкой, остудить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1142,'Нарезать мясо соломкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1142,'Покрошить салат, побрызгать лимонным соком, полить заправкой, всыпать кусочки курицы и гренки, ингредиенты перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1142,'Украсить блюдо оставшимися гренками и посыпать тертым «Пармезаном».',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1143,'Тонкий лаваш намазать оливковым маслом, присыпать специями, нарезать небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1143,'Филе курицы замариновать, нарезать кубиками, жарить на сковороде до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1143,'Выложить на тарелку нарезанные или порванные листья салата, куриное мясо, помидоры черри, разрезанные пополам, полить соусом «Цезарь», перемешать, посыпать сыром «Пармезан», выложить кусочки лаваша.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1144,'Добавить к яйцам сахар с ванилью, взбить, влить сметану, ром и йогурт (кефир), еще раз взбить. Приготовить смесь муки с разрыхлителем, всыпать в полученную смесь и размешать. Нарезать на небольшие кусочки зефир в шоколаде, добавить к тесту, перемешать до однородности. Смазать чашу мультиварки маслом, переложить подготовленное тесто. Кекс в мультиварке с зефиром готовить на режиме «Выпечка»  полтора часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1144,'Вынуть готовый корж, дать ему остыть. Приготовить из сахара с какао глазурь. Для этого смешать сахар с растопленным маслом и молоком в небольшой емкости до однородности, добавить кусочки зефира, нагреть до растворения зефира, растирая его ложкой о стенки кастрюльки. После чего проварить глазурь еще 15 минут, дать чуть остыть и смазать остывший кекс. Мягкий кекс с зефиром в мультиварке готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1145,'Куриное филе отварить в течение получаса в подсоленной по вкусу воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1145,'Отдельно отварить куриные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1145,'Батон нарезать кубиками, жарить без масла на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1145,'Филе нарезать кубиками, яйца разрезать на четыре части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1145,'Помидоры покрошить кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1145,'Продукты выложить в тарелку, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1145,'Посыпать салат тертым сыром «Пармезан» или «Российским».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1145,'Перемешать майонез с рубленым чесноком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1145,'Соус выложить поверх салата вместе с сухариками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1146,'Порезать кубиками куриное мясо, подержать в маринаде, обжарить на сковороде, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1146,'Порвать листья салата, перемешать с курицей, частью сухариков, крупно нарезанным редисом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1146,'Блюдо заправить готовым соусом «Цезарь», перемешать и посыпать сыром «Пармезан».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1147,'Поставить на маленький огонь сливочное масло, чтобы оно полностью растопилось. Оставить остывать, масло не должно быть очень горячим.','https://vkuso.ru/data/cache/data/25/f5bc1e503518125_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1147,'Взбить яйца с сахаром с помощью миксера.','https://vkuso.ru/data/cache/data/a5/b5b81baa44c1ca5_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1147,'Затем, продолжая взбивать, влить остывшее растопленное сливочное масло и молоко.','https://vkuso.ru/data/cache/data/47/ae0b98cb5178747_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1147,'Соединить муку, какао и разрыхлитель.','https://vkuso.ru/data/cache/data/0f/baf248aae258b0f_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1147,'Просеять смесь сухих ингредиентов и порционно добавить ко взбитой массе. Должно получиться негустое тесто.','https://vkuso.ru/data/cache/data/ef/bac44f12e08abef_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1147,'Наполнить формочки тестом на 2/3 объема. Выпекать шоколадные кексы в духовке, разогретой до 160 градусов, 20 минут. Готовые кексы достать из формочек и дать полностью остыть.','https://vkuso.ru/data/cache/data/f5/95575de2d9db0f5_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1147,'Приятного аппетита!','https://vkuso.ru/data/cache/data/ab/9653b0e8e2f4eab_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1148,'В муку добавить соль, сахар, перемешать',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1148,'Холодное сливочное масло натереть на терке и перетереть с мукой до состояния крошки',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1148,'Добавить ледяную воду, вымесить тесто. Завернуть тесто в пищевую пленку и убрать в холодильник на 30 мин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1148,'Раскатать тесто толщиной около 3-4 мм. Уложить в форму, обрезать края.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1148,'Лишнее тесто завернуть в пищевую пленку и убрать в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1148,'Сверху застелить бумагу для выпечки, засыпать груз (рис, фасоль). Выпекать при 180°С 25 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1148,'Вытащить форму, убрать груз, дать немного остыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1148,'Оставшееся тесто раскатать, вырезать листочки, смазать их яичным белком и выпекать при 180°С до золотистого цвета.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1148,'Смешать в миске тыквенное пюре и сгущенное молоко. Добавить корицу, имбирь, соль, мускатный орех, перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1148,'Добавить яйца, перемешать до однородности. Залить начинку в форму, выпекать при 180°С 55-60 мин.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1148,'Дать готовому пирогу остыть, затем убрать в холодильник минимум на 3 часа.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1149,'На сковороде с растительным маслом обжариваем фарш до изменения цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1149,'Консервированную фасоль потушить до мягкого состояния и добавить в нее кукурузу и фарш. Если сока в фарше много его нужно процедить. И тушим 10 минут. Посолить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1149,'В тарелке сложить мелко нарезанный лук и перец чили, добавить лимонный сок и промять все ложкой до тех пор, пока лук не порозовеет. Затем добавить нарезанные помидоры и специи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1149,'Фарш с кукурузой и фасолью откинуть на дуршлаг.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1149,'На лепешку тортилью выложить сначала фарш, затем овощи и завернув все прогревать на сухой сковороде по несколько минут с каждой стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1150,'Баклажаны нарезать длинной соломкой, посолить и оставить на 30 минут. Затем откинуть баклажаны на дуршлаг и дать стечь соку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1150,'Обжарить баклажаны на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1150,'Перец нарезать соломкой, лук нарезать полукольцами, морковь натереть на тёрке для корейской моркови. Чеснок почистить и пропустить через пресс.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1150,'Соединить тёплые баклажаны, перец, лук, морковь, чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1150,'Добавить сахар, соевый соус, уксус, кунжут. Всё хорошо перемешать и поставить в холодильник на пару часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1151,'Сегодня мы приготовим лосося в чесночно-медовой глазури. Для начала приготовим соус. Для этого смешаем в посуде растопленное сливочное масло, оливковое масло, сахар, соевый соус, мед, горчицу, чеснок, хлопья Чили и сок лайма, все хорошо перемешаем и положим лосося в соус и оставим его там на минут 20-30.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1151,'После положим в форму для запекания и зальём тем же соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1151,'Поставим в духовку разогретую до 200 градусов на 15-17 минут. Периодически можно поливать соусом сам лосось. Готовую рыбу подавать с рисом',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1152,'Хлеб нарезать кубиками, прогреть в духовке при температуре 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1152,'Вынуть подрумяненные гренки, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1152,'Нарезать кубиками куриную грудку и ветчину, жарить на растительном масле до получения золотистого оттенка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1152,'Пекинскую капусту нарезать кубиками, высыпать в миску.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1152,'Выложить курицу, часть сухариков и ветчину.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1152,'Перец молотый и соль – по вкусу, заправить салат майонезом. Перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1153,'Курицу нарезать кубиками, мариновать до пропитывания, жарить до готовности. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1153,'Порвать листья любого салата, перемешать с куриным мясом, сухариками, заправить соусом «Цезарь», перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1153,'Сверху выложить сыр «Моцарелла», выложить остатки сухариков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1154,'Для начала крабовые палочки нужно распластать, должны получиться тонкие пластинки. Просто осторожно надрываете крабовую палочку, и так же осторожно раскручиваете ее.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1154,'Сыр нарезаем тонкими полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1154,'Для приготовления кляра делаем такие действия. В миску добавляем 2 яйца, соль, перец, гранулированный чеснок и паприку по вкусу. Все хорошо взбиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1154,'Далее добавляем молоко, снова взбиваем, и постепенно добавляем муку, я добавил около 6 ст.л. Перемешиваем до консистенции сметаны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1154,'Берем подготовленную крабовую палочку, в неё укладываем тонкую полоску сыра, заворачиваем. Так же поступаем с остальными крабовыми палочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1154,'Подготовленную крабовую палочку с сыром, отпускаем в кляр. Крабовая палочка должна быть полностью в кляре. Достаём встряхиваем и перекладываем на разогретую сковороду с добавлением растительного масла. Обжариваем до корочки, и перекладываем на тарелку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1155,'В муку всыпаем соль, сахар, соду, погашенную уксусом или лимонным соком.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1155,'Готовим начинку: нарезаем кружочками помидоры.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1155,'Тесто раскатываем тонко скалкой по диаметру формы. У меня форма 28 см.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1162,'Сверху – сыр «Фета», нарезанный небольшими кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1163,'Сперва смять правильно мясо рукой и создать форму медальона.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1155,'Затем вынимаем форму с тестом из духовки и смазываем его майонезом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1156,'Поломать шоколад на небольшие кусочки. Добавить к нему 50 мл сливок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1156,'Растопить шоколад на водяной бане. Дать шоколадной микстуре остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1156,'В это время в глубокую тару вылить 150 мл сливок. Взбить миксером до консистенции крема.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1156,'К взбитым сливкам порционно добавить растопленный шоколад. Перемешивать миксером на медленной скорости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1156,'Готовый мусс разложить по формам.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1157,'Разбить в глубокую миску яйца, всыпать сахар, хорошо взбить, влить сметану, хорошо перемешать. Добавить по частям смесь муки и разрыхлителя, перемешать. Разделить тесто на 2 части (одну чуть больше), добавить в большую часть какао.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1157,'Смазать чашу сливочным маслом, присыпать мукой (манкой).  Налить в центр часть «шоколадного» теста, а на него (тоже по центру) светлого и так пока не закончится все тесто. Готовить нежный кекс «Зебра» в мультиварке  час в режиме «Выпечка»',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1158,'Куриные грудки замариновать и обжарить на прогретой сковороде, время – по семь-восемь минут с каждой стороны. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1158,'Приготовить заправку из яичных желтков, рубленых анчоусов, горчицы, винного уксуса, тертого чеснока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1158,'Перемешать, добавить оливковое масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1158,'Влить немного «Вустерского» соуса, лимонного сока, посолить, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1158,'Нарезать кубиками хлеб, выложить на противень, посолить, побрызгать оливковым маслом, поставить в духовой шкаф.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1158,'Печь при температуре 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1158,'Нарезать куриное мясо, салат «Латук».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1158,'Пересыпать в миску, добавить курицу, сухарики, заправить соусом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1158,'Салат выложить на порционные тарелки. Украсить оставшимися гренками, анчоусами, посыпать тертым сыром «Пармезан».',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1159,'Посолить и посыпать специями куриное филе, поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1159,'Жарить с двух сторон на сковороде по семь минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1159,'Переложить в миску, подержать под крышкой десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1159,'Нарезать кубиками свежий хлеб, выложить на противень, добавить целые зубчики чеснока, полить растительным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1159,'Прогреть духовку до 180 градусов, печь сухарики до румянца',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1159,'Вынуть продукт и остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1159,'Пекинскую капусту нарезать, спелое авокадо покрошить кубиками, куриное мясо нарезать ломтиками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1159,'Натереть сыр.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1159,'Приготовить заправку из соевого соуса, сметаны, лимонного сока, давленого чеснока. Продукты перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1159,'Выложить в салатницу сыр, пекинскую капусту, куриное мясо, авокадо, полить заправкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1159,'Выложить салат на тарелку, украсить нарезанными помидорами, сухарями и тертым сыром.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1160,'Куриную грудку отварить и нарезать кубиками вместе с отваренным картофелем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1160,'Покрошить репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1160,'Выложить на дно салатницы картофель, посыпать луком, смазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1160,'Далее – куриное мясо, тертый сыр «Пармезан».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1160,'Все слои промазывать майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1161,'Нарезать кубиками куриное филе, полить маринадом, далее – обжарить на сковороде и остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1161,'Порвать руками листья салата, добавить куриное мясо, часть сухарей, полить соусом «Цезарь», перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1161,'Поверх салата выложить оставшиеся сухарики и тертый сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1162,'Обезжиренный йогурт перемешать с тертым чесноком, готовой горчицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1162,'Курицу обжарить без масла на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1162,'Выложить на тарелку листья салата, курицу, нарезанную кубиками, кусочки помидоров, полить соусом, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1182,'Добавить яйцо, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1163,'Замариновать мясо, желательно дать постоять.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1163,'Раскалить гриль и жарить по 1,5 минуты с двух сторон дважды до прожарки медиум.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1163,'Время жарки зависит от температуры и желаемой степени прожарки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1164,'Каждый кусок хлеба намазать горчицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1164,'На 1 кусок хлеба положить по 2 куска ветчины и сыра, затем накрыть вторым куском хлеба.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1164,'В миске смешать яйцо с молоком и вымачивать в этой смеси сэндвичи после чего обжарить их на разогретой сковороде в сливочном масле с двух сторон до золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1164,'Готовые сэндвичи посыпать сахарной пудрой и подать с вареньем или джемом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1165,'Смешать бараний фарш с приправами, добавить измельченный лук, посолить, как следует вымесить. Сформовать колбаски желаемого размера, нанизать на шпажки, дать постоять полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1165,'Переложить в мультиварку, выставить режим «Выпечка», готовить сочный кебаб из баранины в мультиварке 40 минут. За время жарки кебабы пару раз перевернуть. Подавать к столу с зеленью и овощами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1166,'Куриную грудку нарезать мелкими кусочками. Кожицу можно оставить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1166,'Обжарить продукт на сильном огне с растительным маслом. Мясо не должно получиться сухим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1166,'Мелко нарезать репчатый лук. Обжарить его на той же сковороде, на которой жарилось мясо. Признак готовности – золотистый цвет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1166,'Натереть морковь, добавить к луку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1166,'В готовую обжарку добавить птитим.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1166,'Добавить немного сливочного масла, каждая крупинка макаронных изделий должна пропитаться жиром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1166,'Влить куриный бульон или воду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1166,'Тушить блюдо в течение двадцати минут, помешивать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1166,'Добавить молотый белый перец, соль и куриную обжарку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1166,'Бульон должен полностью впитаться, огонь погасить, подержать кушанье под крышкой в течение десяти или пятнадцати минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1167,'Репчатый лук тонко нарезать, покрошить чеснок, лучшая нарезка – полоски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1167,'Вылить на сковороду часть растительного масла, выложить чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1167,'Добавить на сковороду куркуму, паприку, лук, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1167,'Куриную грудку нарезать полосками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1167,'Ингредиенты обжарить, всыпать птитим, не перемешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1167,'Влить кипяченую воду, подержать блюдо под крышкой на тихом огне в течение получаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1167,'На вторую сковороду влить оставшееся масло, обжарить мясо, соль и перец – по вкусу, добавить то и другое в конце приготовления.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1167,'Птитим выложить на тарелку, сверху – мясо курицы. Украсить зеленью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1168,'Цветную капусту разбираем на соцветия и отвариваем в кипящей подсоленной воде 5-8 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1168,'Готовим заливку: взбиваем венчиком яйца, молоко, добавляем соль, перец и сухие травы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1168,'В форму, смазанную маслом выкладываем капусту, предварительно отцедив ее от жидкости, заливаем ее приготовленной заливкой. Сверху выкладываем нарезанные кружочками помидоры и посыпаем натертым на крупную терку сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1168,'Отправляем в духовку на температуру 190 градусов на 30 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1169,'Залейте овсяные хлопья молоком. Добавьте начинку на Ваш вкус, перемешайте и уберите в холодильник минимум на 4 часа или на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1170,'Чеснок очистить и нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1170,'Промыть свинину, обсушить полотенцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1170,'Кончиком ножа сделать надрезы, нашпиговать чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1170,'Натереть солью и молотым перцем, полить соевым соусом, натуральным медом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1170,'Оставить на час в холоде для пропитывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1170,'Растительным маслом смазать форму для запекания, выложить мясо, готовить в духовом шкафу, температура – 220 градусов, время 40-60 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1170,'Мясо поливать выделившимся соком каждые десять или пятнадцать минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1171,'Нарезать кусочками чеснок и репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13638,'Повторить со всеми макаронами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1171,'Свинину промыть холодной водой и обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1171,'Сделать надрезы, нашпиговать чесноком и луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1171,'Присыпать продукт специями, солью, перцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1171,'Выложить в глубокую емкость, залить квасом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1171,'Приправить уксусом, мятой, лавровым листом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1171,'Прикрыть пищевой пленкой или крышкой, оставить в холоде на двенадцать часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1171,'Время запекания – от сорока до шестидесяти минут. Температура – 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1172,'Перемешать коричневый сахарный песок с дижонской горчицей, перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1172,'Натереть смесью свинину.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1172,'Выложить в форму для запекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1172,'Влить яблочный сидр и светлое пиво, приправить лавровым листом и гвоздикой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1172,'Время приготовления в духовке – один час, температура – 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1172,'Время от времени продукт поливать выделившимся соком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1172,'Вынуть из духового шкафа, накрыть фольгой, подержать пятнадцать минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1173,'Замесить тесто на чебуреки, смешав все ингредиенты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1173,'Смешать все ингредиенты для мясной начинки, заправить фарш.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1173,'Раскатать тесто, на одну половину положить фарш.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1173,'Разогреть масло до 140 градусов, не меньше? и жарить чебуреки с двух сторон до золотистой корочки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1173,'Подавать со сметаной.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1174,'Корень имбиря мелко нарезать ножом, покрошить чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1174,'Листочки розмарина отделить от стебля.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1174,'Приготовить маринад из соевого соуса, растительного масла, молотого перца и имбиря.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1174,'В куске свинины сделать надрезы, нашпиговать розмарином и чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1174,'Мясо положить в пакет, влить соус, встряхнуть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1174,'Смесь должна равномерно покрыть свинину.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1174,'Пакет завязать, положить в холод на ночь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1174,'Маринованную свинину вынуть из пакета, обсушить полотенцем.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1174,'Натереть яблоко на мелкой терке, перемешать с зерновой горчицей и остатками маринада.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1174,'Сковороду смазать растительным маслом, прогреть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1174,'Жарить свинину со всех сторон до получения корочки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1174,'Мясо остудить, покрыть яблочным соусом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1174,'Выложить продукт в рукав для запекания, печь в духовом шкафу в течение часа. Температура приготовления – 200 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1174,'Пакет вскрыть, оставить мясо еще на пятнадцать или двадцать минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1175,'В воду всыпать соль, тимьян, положить лавровый лист и душистый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1175,'Выжать сок из одного мандарина, мякоть и цедру нарезать кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1175,'Рассол довести до кипения, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1175,'Положить мясо, накрыть пищевой пленкой или крышкой, оставить в холоде на ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1175,'Часть чеснока пропустить через пресс или нарезать острым ножом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1175,'Перемешать с горчицей, паприкой, кориандром, смесью разных перцев, пряности залить соком второго мандарина.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1175,'Вынуть мясо из рассола, обсушить полотенцами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1175,'Вторую часть чеснока покрошить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1175,'В куске свинины сделать надрезы, нашпиговать чесноком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1175,'Продукт смазать маринадом с горчицей, завернуть в лист фольги.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1175,'Время выпекания в духовом шкафу – два часа. Температура – 160 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1175,'Мясо вынуть из духовки, оставить до остывания на полчаса или чуть дольше, затем развернуть.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1176,'Измельчить чеснок любым способом, перемешать с вином, кориандром, гранатовым соусом, солью, перцем и мускатным орехом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1176,'Промыть свинину в воде, обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1176,'Выложить в глубокую емкость, залить маринадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1176,'Блюдо накрыть крышкой или пленкой, оставить в холоде на сутки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1176,'Мясо несколько раз перевернуть, чтобы оно пропиталось специями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1176,'Выложить продукт вместе с маринадом в рукав, завязать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1176,'Выложить в форму для запекания. Время приготовления – от часа до полутора, температура – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1176,'Пакет разрезать, мясо оставить на двадцать минут для подрумянивания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1177,'Довести воду до кипения, выложить репчатый лук и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1177,'Еще раз довести до кипения, выложить кусок свинины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1177,'Жидкость должна покрывать мясо полностью. Время варки – от сорока до сорока пяти минут, огонь – средний.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1177,'Всыпать соль, черный и душистый перец-горошек, лавровый лист и кориандр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1177,'Варить еще двадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1177,'Огонь погасить, мясо оставить до остывания в бульоне, затем вынуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1177,'Измельчить очищенный чеснок, перемешать с молотым красным и черным перцем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1177,'Смесью натереть мясо, продукт завернуть в лист фольги.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1177,'Поставить в холод на десять или двенадцать часов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1178,'Свинину промыть в холодной воде, обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1178,'Нарезать чеснок, размочить в теплой воде изюм без косточек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1178,'Сделать в куске мяса надрезы, нашпиговать изюмом и чесноком, натереть перцем с солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1178,'Продукт оставить в холоде на час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1178,'Прогреть на сковороде растительное масло, жарить мясо по две или три минуты с каждой стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1178,'В посуду для микроволновой печи выложить лавровый лист и мясо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1178,'Влить кипящую воду, поставить в печь, накрыть крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1178,'Время приготовления – от пятнадцати до двадцати пяти минут. Мощность – максимальная.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1178,'Мясо перевернуть, подержать в печи еще двадцать минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1179,'Обработайте и отделите мякоть арбуза от корочек. Мелко покрошите корочки примерно 1 см на 1 см. Далее залейте водой и кипятите на маленьком огне примерно 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1179,'Слейте воду и процедите корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1179,'Далее готовим сахарный сироп. В кастрюлю добавляем воду и разогреваем. В это время маленькими количествами добавляем сахар всё время помешивая. Сахар должен сразу же растворяться. Как только весь сахар был утилизирован, добавляем корочки и варим еще примерно 1 час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1179,'Затем лимон можно натереть или расмельчить на блендере и добавить к варенью. Поварить ещё 15 мин. Вы увидите как варенье загустеет и станет похожим на цукаты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1180,'В миску вбить яйца (3 шт.), сахарную пудру и муку (80 гр) - смешать при помощи венчика до однородной массы. Влить молоко (50 мл) и растительное масло, всыпать ванильный сахар, корицу и разрыхлитель, натереть цедру половины лимона, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1180,'Яблоки очистить от кожуры и сердцевины. Нарезать тонкими пластинками и сбрызнуть соком лимона (чтобы не потемнели).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1180,'В форму для выпечки выложить яблоки, равномерно залить тестом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1180,'Разогреть духовку до 200 градусов, а затем поставить выпекаться пирог на 35 минут. Спустя 35 минут',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1180,'Замешать заливку для теста. Яйцо взбить с 30 гр муки - перемешать, добавить 50 мл молока, снова перемешать. Заливаем этой смесью пирог. Сверху выложить орешки, выпекаем еще 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1181,'Приготовить маринад из соевого соуса, растительного масла, горчицы и куркумы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1181,'Дополнительно в смесь можно добавить и другие приправы для мяса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1181,'Промыть кусок свинины, обсушить при помощи бумажных полотенец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1181,'Смазать продукт маринадом, оставить для пропитывания на четыре или пять часов в холодильнике.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1181,'Чашу мультиварки смазать растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1181,'Выложить мясо, печь в течение полутора часов, режим «Тушение».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1181,'Другой вариант – использовать скороварку, время приготовления – сорок минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1181,'Мясо вынуть, остудить под фольгой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1182,'Бананы раздавить вилкой в пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1182,'Влить молоко, добавить мед, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1182,'В отдельной миске смешать муку, разрыхлитель, соль, корицу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1182,'Всыпать сухие ингредиенты в бананово-яичную смесь и перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1182,'Формы для кексов смазать растительным маслом. Заполнить формы тестом. Выпекать при 180°С 35-40 мин. Готовым кексам дать остыть',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1183,'Печень измельчить в блендере или пропустить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1183,'Затем добавить яйцо, молоко, муку, соль, перец, всё хорошенько перемешать и дать настояться примерно полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1183,'Тем временем жарим лук с морковью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1183,'Берем глубокую форму для запекания, кладем половину жареных овощей̆, сверху половину сыра, затем половину смеси из печени, и в таком же порядке выкладываем другую половину овощей̆, сыра и печени.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1183,'Запекаем в разогретой̆ духовке примерно 70-80 минут при 170-180°C.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1184,'Креветки в чесночно-устричном соусе. Для начала приготовим соус, добавим устричный соус, мёд, оливковое масло, хлопья Чили, соль, перец, все хорошенько перемешаем и оставим в сторонке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1184,'Теперь разогреем сковородку, добавим туда сливочное масло и оливковое и выдавим чеснок, слегка обжарим чеснок и положим креветки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1184,'Затем обжарим с одной стороны, перевернём, добавим белое вино, слегка выпарим и добавим наш соус, пару минут обжарим, после, добавим острый перец, зелёный лук и кинзу. Готово.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1185,'Обжарить в мультиварке на режиме «Выпечка» мелко нашинкованный лук и фарш 20 минут. Всыпать горох (замоченный), залить водой, добавить любимые приправы, посолить, перемешать, выставить режим «Молочная каша».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1185,'Время варки гороховой каши с мясным фаршем в мультиварке задается автоматически,  готовить до сигнала, попробовать. Если горох будет слегка еще жестким, то готовить еще 30 минут в режиме «Подогрев».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1186,'Для начала нужно подготовить помидоры. Лично я выбрал средние помидоры. У помидоров отрезаем вверх, и можно еще слегка отрезать низ, чтобы помидор на падал на бок. Как только отрезали вверх, нужно убрать мякоть. Мякоть можно убрать при помощи чайной ложки. Мякоть убираем осторожно, и перекладываем в глубокую тарелку убираем, она больше нам не понадобится. Как только убрали всю мякоть, перекладываем помидоры в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1186,'Приступим к приготовлению начинки. Крабовые палочки нарезаем мелко, и перекладываем в миску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1186,'Вареную колбасу, или можно использовать докторскую, нарезаем маленьким кубиком, также перекладываем в тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1186,'Вареную колбасу, или можно использовать докторскую, нарезаем маленьким кубиком, так же перекладываем в тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1186,'Укроп мелко нарезаем, маленькую часть его перекладываем на тарелку, а другую часть в миску.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1186,'Сыр натираем на мелкой терке, часть сыра тоже перекладываем на тарелку, а другую часть в миску.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1186,'Начинку нужно посолить, поперчить и добавить сметану, все хорошо перемешать. Даем начинки настоятся.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1186,'Далее берем 1 помидору и начиняем начинкой, и сверху посыпаем оставшимся укропом. Берем следящею помидорку, начиняем начинкой, но уже посыпаем оставшимся сыром, Точно так же поступаем с оставшейся начинкой, и помидорами. Все готово.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1187,'Яйца взбить с сахаром минуты 2 до посветления, после добавить растительное масло, продолжая взбивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1187,'К муке добавить соль, разрыхлитель, ванилин и корицу и просеять к яичной смеси перемешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1187,'Бананы превратить в пюре, с помощью вилки добавить в тесто, также добавить нарезанные орехи, перемешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1187,'Переложить в форму для выпекания и отправить в разогретую духовку до 180°C на 60 минут до сухой шпажки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1187,'К сливочному сыру добавить сгущенное молоко, перемешать до однородности, в чистой чаше взбить холодные сливки, постепенно добавляя сыр довести до устойчивых пиков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1187,'Готовый корж делим на три равные части и собираем торт.','https://vkuso.ru/data/cache/data/32/03a19030323e932_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1188,'Закипятить литр воды.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1188,'Обжарить на медленном огне.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1188,'Помидоры очистить от кожуры и нарезать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1188,'Подсушить сухарики в духовке несколько минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1188,'Подавать суп с сухариками.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1189,'Картофель очистить и отварить до готовности в подсоленной воде. Полностью слить воду и растолочь его до однородной массы. ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1189,'Лук нарезать мелким кубиком и обжарить до золотистости на растительном масле. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1189,'Картофелю дать остыть до чуть теплого состояния и добавить к нему лук, приправу для картофеля, взбитые венчиком яйца, тщательно перемешать и частями добавить муку, еще раз перемешать и добавить бекон. ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1189,'Полученную массу поместить в форму, смазанную маслом или жиром и отправить в разогретую духовку на температуру 180 градусов на 40 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1189,'Вынув из духовки дать остыть до теплого состояния и извлечь из формы.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1190,'Нарезать кусочками очищенный чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1190,'Растолочь перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1190,'Перемешать с зернами тмина, розмарином, красным перцем, солью и сахарным песком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1190,'Промыть свинину, обсушить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1190,'Надрезать кончиком ножа, нашпиговать чесноком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1190,'Остатками смеси натереть мясо со всех сторон, оставить на полчаса для пропитывания при комнатной температуре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1190,'Прогреть на сковороде растительное масло, огонь – максимальный.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1190,'Обжарить свинину по две минуты с каждой стороны.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1190,'Продукт выложить на решетку пароварки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1190,'Время приготовления – от получаса до сорока минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1190,'Остудить, не вынимая из пароварки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Подогреть молоко в микроволновой печи до теплого состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Свежие дрожжи выложить в жидкость, растворить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Добавить сахарный песок, смесь перемешать, дать постоять при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Время приготовления закваски – от двадцати до двадцати пяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Прогреть сливочное масло, остудить. Продукт должен быть жидким.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Вбить яичные желтки, перемешать. Масса должна напоминать крем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Влить готовые дрожжи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Отдельно перемешать муку с солью, два раза просеять.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Сделать в горке углубление, влить жидкую смесь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Замесить тесто, оно должно быть мягким и эластичным.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Накрыть продукт полотенцем, оставить в теплом месте на час или полтора. Масса должна подняться.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Продукт вымесить еще раз, затем раскатать лепешку толщиной в один сантиметр.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Нарезать заготовки формочками или стаканом и рюмкой разных диаметров.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Плюшки выложить на присыпанный мукой стол, дать постоять двадцать минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Заготовки увеличатся в размерах.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Прогреть в глубокой сковороде растительное масло, выложить пончики.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Жидкость должна скрывать будущую выпечку наполовину.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Жарить с двух сторон до поучения золотистой корочки.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1191,'Изделия выложить на бумажное полотенце для удаления излишков жира.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1192,'Муку просеять два раза, продукт должен насытиться кислородом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1192,'Добавить в кефир сахар и соль по вкусу, немного пищевой соды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1192,'Влить воду небольшими порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1192,'Всыпать муку, тоже порциями, каждый раз массу размешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1192,'Влить растительное масло, тесто вымесить руками. Масса должна быть мягкой и липкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1192,'Оставить продукт на полчаса или чуть больше.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1192,'Вымесить еще раз, раскатать в лепешку толщиной в один сантиметр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1192,'Нарезать изделия с дырочкой посередине.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1192,'Жарить пампушки в большом количестве растительного масла на сковороде. Продукт должен быть раскаленным.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1192,'Выложить выпечку на лист бумаги, остудить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'Вымыть крупные и сладкие яблоки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'Каждый плод разрезать пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'Вынуть косточки, половинки выложить в микроволновую печь или на противень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'Запечь в течение пятнадцати или двадцати минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'Агар-агар залить водой, оставить для набухания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'С яблок сныть шкурку, мякоть перемолоть в блендере.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'В пюре добавить ванильный и обычный сахар.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'Вымешать, остудить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'Противень застелить пергаментом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'Пюре взбить миксером, добавить часть яичного белка, продолжать взбивать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'При увеличении объема добавить оставшийся белок.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'Взбивать до плотного состояния.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'Сотейник с агар-агаром поставить на плиту, прогреть, довести до кипения, добавить сахарный песок, варить в течение нескольких минут без бурного кипения.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'Влить агар в основную массу, продолжать взбивать. Должна получиться пышная масса.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1193,'Переложить продукт в кондитерский мешок с подходящей насадкой, отсадить изделия на пергамент, оставить зефир на ночь в кухне, при комнатной температуре.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1194,'Ягоды перебрать, оторвать хвостики, вымыть и просушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1194,'Приготовить пюре при помощи блендера и сита.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1194,'Массу протереть, чтобы удалить косточки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1194,'Пюре поставить на огонь, довести до кипения, варить, помешивая. Время приготовления – от пяти до десяти минут. Пюре должно быть темным и плотным по текстуре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1194,'Всыпать половину нормы сахарного песка, перемешать, снять с огня и остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1194,'В сотейник всыпать агар-агар, влить воду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1194,'Довести до кипения, всыпать оставшийся сахар, перемешивать до растворения. Готовая масса начнет пузыриться.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1194,'Огонь убавить до минимального, проварить загуститель при температуре 110 градусов. Масса должна быть однородной и тягучей.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1194,'В остывшее пюре добавить белок. Взбивать на небольших оборотах, затем добавить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1194,'В пышную смесь влить агар-агар, продолжать взбивать. Объем массы увеличится. Заготовка должна быть плотной по консистенции.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1194,'Выложить зефирную массу в конверт или мешок, отсадить зефир, оставить на ночь для подсушивания.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1195,'Желатин залить водой для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1195,'Малину протереть через сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1195,'Добавить сахарный песок, массу перемешать и оставить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1195,'Желтки отделить от белков, последние охладить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1195,'Малину варить до закипания, затем огонь убавить, тушить еще десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1195,'Снять с огня и остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1195,'Холодные белки взбить при помощи миксера на небольших оборотах.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1195,'Затем скорость увеличить, ввести остывшее ягодное пюре.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1195,'Взбить еще раз.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1195,'Ввести желатин тонкой струйкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1195,'Разлить массу в формочки, оставить для застывания на несколько часов или на ночь.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1196,'Перемешать агар-агар с водой, оставить на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1196,'Испечь яблоки до мягкости, сердцевину удалить заранее.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1196,'Снять шкурку, мякоть вместе со свежей клубникой взбить в блендере в пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1196,'Массу протереть через мелкое сито, удалить косточки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1196,'Пюре перелить в сотейник, всыпать 200 г сахарного песка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1196,'Варить до растворения сахара на тихом огне, общее время приготовления – до полутора часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1196,'Массу остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1196,'Довести до кипения агар-агар с водой, добавить 300 г сахара, варить при температуре 110 градусов. Масса должна загустеть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1196,'Добавить белок в пюре, взбить на средней скорости, затем переключить блендер на высокую. Масса должна получиться пышной и плотной. Общее время взбивания – десять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1196,'Выложить зефир, оставить на ночь.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1196,'Готовое лакомство полить растопленным шоколадом, оставить на час.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1197,'Филе нарезать небольшими кубиками, шкурку удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1197,'Покрошить очищенный чеснок, обжарить на сливочном масле, добавить кусочки форели два на два сантиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1197,'Жарить под крышкой до полуготовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1197,'Влить сливки, довести массу до кипения. Огонь – тихий, блюдо должно тушиться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1197,'Всыпать тертый сыр «Пармезан», потушить блюдо до загустения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1197,'Всыпать специи для рыбы, тушить еще две минуты, огонь погасить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1197,'Отварить отдельно макароны фетуччини, перемешать с рыбой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1198,'Картофельные клубни хорошо промыть, разрезать пополам, кожуру не снимать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1198,'Выложить продукт в смазанную оливковым маслом форму, время запекания – 25 минут, температура – 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1198,'Разделить тушки на два или три куска, посолить и поперчить, побрызгать оливковым маслом. Оставить для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1198,'Запеченный картофель вынуть из духовки, сверху посыпать розмарином, солью, перцем по вкусу, выложить ломтики чеснока, рыбу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1198,'Поставить блюдо в духовой шкаф на 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1198,'Блюдо подать к столу горячим.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1199,'Рыбу промыть, снять кожицу, нарезать филе порционными кусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1199,'Побрызгать лимонным соком, посолить и поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1199,'Оставить для пропитывания на десять или пятнадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1199,'Приготовить кляр. Смешать крахмал с минералкой, содой, яйцами и мукой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1199,'Смесь хорошо перемешать, она должна стать однородной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1199,'В конце приготовления добавить лед.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1199,'Кусочки рыбы обмакнуть в кляр, обжарить на заранее прогретом растительном масле, кусочки переворачивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1199,'Готовый продукт выложить на бумагу для впитывания излишков жира.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1200,'Приготовить тесто из просеянной муки, сухих или прессованных дрожжей, соли, сахарного песка, теплой воды, яйца, сливочного масла или маргарина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1200,'Можно воспользоваться хлебопечкой, режим «Обычное тесто». На замес уходит два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1200,'Тесто должно два или три раза хорошо подойти.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1200,'Продукт обмять, консистенция должна быть чуть более жидкая, чем для пирогов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1200,'Смазать руки растительным маслом, чтобы не прилипало тесто. Сформовать пышки из шариков, выложить на доску, также смазанную маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1200,'Дать постоять полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1200,'Налить в кастрюлю с толстым дном рафинированное растительное масло.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1200,'Пышки должны тонуть на половину толщины или больше.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1200,'Прогреть масло до 160 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1200,'В лепешках сделать дырочки, опустить во фритюр.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1200,'Обжарить с одной стороны, перевернуть, все операции делать быстро.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1200,'Румяные пышки выложить на бумажную салфетку.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1200,'Масло для фритюра можно использовать несколько раз.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1201,'Влить в емкость теплую воду, всыпать соль, сахарный песок, вбить сырое куриное яйцо, немного растаявшего сливочного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1201,'Ингредиенты перемешать, оставить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1201,'Просеять в глубокую миску муку, всыпать сухие дрожжи, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1201,'Сделать в муке углубление, влить воду с дрожжами, замесить тесто лопаткой или ложкой. Тесто должно быть жидковатым.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1201,'Продукт прикрыть крышкой, оставить в тепле на полтора или два часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1201,'Можно поставить в духовой шкаф, выставить температуру в пятьдесят градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1201,'За это время обмять массу два раза.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1201,'Общее время для подъема – полтора часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1201,'Смазать руки и стол растительным маслом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1201,'Тесто поделить на части размером с грецкий орех.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1201,'Оставить на двадцать минут под пищевой пленкой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1201,'Влить на сковороду растительное масло, оно должно скрывать пышки наполовину.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1201,'В лепешках сделать дырочки, растянуть, выложить в масло.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1201,'Пышки жарить с двух сторон до получения золотистой корочки.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1202,'Печенье «Топленое молоко» измельчить. Вариантов несколько: поломать руками, при помощи скалки в пакете, воспользоваться блендером или мясорубкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1202,'Сливочное масло и шоколад нарезать кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1202,'Выложить в емкость с толстыми стенками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1202,'Продукты растопить на тихом огне, сахарный песок подсыпать порциями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1202,'Крошку залить шоколадной массой, хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1202,'Сформовать колбаски, обернуть в пленку, положить в холод.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1202,'Сахар в «колбасной» массе должен раствориться.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1203,'Печенье размолоть в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1203,'Сливочное масло нарезать кусочками, растопить, добавить сахарный песок, растворить при нагреве и постоянном помешивании.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1203,'В кастрюлю всыпать какао, влить молоко, перемешать и убрать с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1203,'Влить полученную глазурь в крошку, перемешать, вбить яйцо, еще раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1203,'Сформовать колбаски, обвернуть пищевой пленкой, положить в холод.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1204,'Печенье измельчить, влить сгущенное молоко, вымешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1204,'Масло сливочное нарезать, растопить, всыпать какао-порошок или обычный шоколад.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1204,'Залить печенье, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1204,'Сформовать десерт, обернуть пленкой, охладить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1205,'Измельчить цукаты и печенье, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1205,'На плите прогреть молоко с сахарным песком, добавить кусочки сливочного масла, всыпать какао-порошок, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1205,'Жидкую массу влить в печенье с цукатами, остудить, сформовать десерт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1205,'Завернуть колбаски в пленку, положить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1206,'Для начала нужно приготовить омлет. Для этого нужно взять яйца и перемешать их с майонезом. После чего протереть через мелкую терку твердый сыр и всыпать его в смесь. Добавить манку и все тщательно перемешать. Оставить смесь постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1206,'В это время приготовить начинку. Для этого мелко порубить лук и прожарить его на раскаленном масле, пока он не станет прозрачным. Затем измельчить его в пюре в блендере. Приготовить куриный фарш. Для этого прокрутить в мясорубке грудку или филе бедра курицы. Посолить, поперчить. Смешать его с луковым пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1206,'За это время манка в омлете разбухла и можно выложить его на противень, который предварительно нужно застелить бумагой для выпечки. Слегка смазать лист маслом и вылить тесто. Противень поставить в предварительно разогретую духовку. Как только тесто зарумянится, сразу вытащить готовый омлет из духовки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1206,'Осторожно убрать бумагу, а на омлет выложить фарш. Равномерно распределить его по всей поверхности. Завернуть в рулет. Чтобы все слои равномерно пропеклись нужно обернуть его фольгой.  Поставить в духовку закусочный куриный рулет в омлете на 40 минут. После чего вытащить и остудить прямо в фольге.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1207,'Печенье поломать кусочками, добавить рубленые орехи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1207,'Растопить в небольшой емкости сливочное масло, влить сливки, всыпать сахар, он должен полностью раствориться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1207,'Всыпать какао, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1207,'Смесью залить печенье с орехами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1207,'Колбаски завернуть в пленку, отправить в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1208,'Печенье поломать, всыпать пропущенные через мясорубку сухофрукты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1208,'Влить сгущенку, массу вымесить до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1208,'Отдельно растопить сливочное масло, всыпать какао, жидкой смесью залить сухую смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1208,'Ингредиенты перемешать, сформовать порции, выставить на холод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1209,'Орехи и бисквит измельчить, переложить в глубокую емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1209,'Довести до кипения молоко, выложить в него сливочное масло и шоколад.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1209,'Массу перелить к бисквитной крошке с орехами, перемешать и сформовать несколько колбасок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1210,'Печенье раскрошить любым способом, порубить фисташки, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1210,'Отдельно, в небольшой емкости растопить горький шоколад с сахарным песком и маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1210,'Смесь перелить к сухим ингредиентам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1224,'Ядра перебить в муку с помощью кофемолки или блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1210,'Массу вымешать, колбаски посыпать кунжутным семенем, выложить на пленку, завернуть, поставить в холод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1211,'Вареное сгущенное приготовить самостоятельно или купить в магазине.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1211,'Содержимое банки перелить в миску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1211,'Перемешать с измельченными орехами и печеньем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1211,'Горький шоколад растопить на водяной бане.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1211,'Все продукты соединить, перемешать, сформовать колбаски, обернуть полиэтиленом и охладить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1212,'Часть печенья поломать руками, вторую измельчить в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1212,'Натереть на терке горький шоколад.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1212,'В чашу блендера налить йогурт, добавить тростниковый сахар, шоколад, массу взбить до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1212,'Готовой смесью залить печенье, перемешать, раскатать колбаски, охладить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1213,'Смешиваем все ингредиенты. Не нужно вымешивать до гладкости. В процессе брожения тесто станет однородным само по себе. Ставим в тепло на 45 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1213,'Складываем тесто (как на видео). Периодически смачивая руки водой. Муку не добавлять!!! Отправляем еще 30 мин. Потом снова сворачиваем тесто. Затем на 40 мин. Сворачиваем и еще на 30 мин. Получается 45+30+40+30 мин (каждые 30-40 мин очень аккуратно сворачиваем тесто).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1213,'Очень густо присыпьте рабочий стол мукой. Не жалейте муки, так как тесто очень липкое. На подготовленную поверхность выложите тесто. Разделите аккуратно на две части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1213,'Возьмите плотную хлопковую ткань (например, вафельное или льняное кухонное полотенце), густо присыпьте ее мукой и уложите на нее чиабатту, образовывая между буханками складки, которые будут удерживать тесто от излишнего расплывания. Накрыть заготовки на еще мин 20. За это время они не сильно увеличатся в размере, но станут пышнее.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1213,'Прогреть духовку до 220°C (вместе с противнем). Аккуратно переложить хлеб на противень, застеленный пергаментом (не бросайте тесто). На дно духовки поставить емкость с водой (если духовка электрическая).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1213,'Выпекаем 30-35 минут до очень румяной, зажаристой корочки. Даем остыть минут 20, нарезаем и наслаждаемся! Приятного аппетита!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1214,'Очищенную и нарезанную тыкву с водой потушить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1214,'Слить жидкость с тыквы и измельчить в пюре при помощи блендера',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1214,'Смешать сливочный сыр с корицей и сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1214,'В пюре вмешать сыр и замесить густую и не сильно липнущую к рукам смесь добавляя постепенно измельченное печенье.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1214,'Сформировать из смеси тыквы с печеньем конфеты с размером в грецкий орех. Затем поставить в холодильник хорошо охладиться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1214,'Прогреть шоколад со сливками,тщательно размешать. И обмакивать холодные конфеты в помадку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1214,'Годовым конфетам дать немного охладиться  перед подачей.Так же можно украсить орехами или кокосовой стружкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1215,'Очищенные и нарезанные тонкими пластинами яблоки засыпаем сахаром и оставляем на 2 часа, чтобы яблочки пустили сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1215,'Спустя 2 часа пересыпаем яблоки в емкость, в которой мы будем готовить яблочное варенье.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1215,'Включаем огонь, доводим до кипения, добавляем пару ломтиков лимона и через 5 мин выключаем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1215,'Яблочное варенье должно полностью остыть, на это уходит 2-3 часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1215,'Затем снова включаем огонь, доводим до кипения, добавляем дольки лимона. Готовим на большом огне 5 мин и выключаем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1215,'Даем остыть и наслаждаемся. Если планируете закрывать в баночки, разливайте варенье пока оно горячее.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1216,'Для этого блюда нужно взять любое готовое рыбное филе. Тщательно промыть его и уложить на дно противня. Приправить по вкусу и выдавить на него сок половину лимона. Оставить на время мариноваться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1216,'Очищенную картошку отварить в соленой воде вместе с брокколи. Вод должна покрывать овощи лишь на пару миллиметров. Как только овощи будут готовы нужно слить воду. Из отварных овощей приготовить пюре. Слегка остудить и положить туда сырые яйца. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1224,'Арахис или другие орехи обжарить на сухой сковороде в течение десяти минут. Перемешивать по мере необходимости. Удалить шелуху.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1216,'Лук очистить порубить мелкими кусочками и прожарить на масле. После чего положить его на рыбу. Выложить сверху овощное пюре.  Поставить в разогретую духовку на 40 минут. Рыба, запеченная под овощной шубой в духовке  должна покрыться румяной корочкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1217,'Клаб Сэндвич.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1217,'Сырный сэндвич.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1217,'Яичный сэндвич.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1218,'В небольшую емкость насыпать сахарный песок, какао-порошок и просеянную муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1218,'Ингредиенты перемешать при помощи венчика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1218,'Молоко прогреть до кипения, влить в сухие компоненты тонкой струйкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1218,'Перемешать до однородного состояния, в смеси не должно быть комочков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1218,'Массу уваривать на плите до загустения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1218,'Снять с огня, добавить сливочное масло комнатной температуры и кусочки темного шоколада.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1218,'Перемешивать до тех пор, пока масло и шоколад не разойдутся.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1218,'Остудить, взбить немного при помощи миксера.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1218,'Переложить массу в стеклянную баночку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1219,'Сливочное масло из холодильника нарезать кубиками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1219,'Подождать, пока они не согреются до комнатной температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1219,'Размолоть в порошок любые орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1219,'Молоко перемешать с мукой, сахарным песком и какао-порошком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1219,'Довести до кипения на тихом огне. Масса должны быть однородной, без комочков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1219,'Всыпать в кипящую смесь ореховую муку, немного соли.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1219,'Пасту уварить до нужной густоты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1219,'Остудить массу до температуры в сорок или пятьдесят градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1219,'Положить масло, перебить миксером до однородности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1220,'В чашу для погружного блендера всыпать сахарный песок, влить молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1220,'Взбить до растворения сахара.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1220,'При максимальной мощности работы прибора влить тонкой струйкой рафинированное растительное масло. Масса должна постепенно загустеть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1220,'Дробленые грецкие орехи и какао-порошок добавить в конце приготовления.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1220,'Готовую массу хранить в небольшой емкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1221,'Растопить сливочное масло, положить кусочки темного шоколада, перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1221,'Влить в смесь сгущенку, немного пшеничной муки, просеянной с какао-порошком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1221,'Довести массу до кипения, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1221,'Снять с огня, всыпать ореховое ассорти, хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1222,'В емкость с толстым дном всыпать просеянный какао-порошок и муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1222,'Добавить растворимый кофе, сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1222,'Все ингредиенты перемешать при помощи венчика.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1222,'Влить молоко, перемешать еще раз, разбить комочки, положить сливочное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1222,'Массу прогреть на среднем огне, варить до нужной густоты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1222,'Пасту охладить под пищевой пленкой, выложить в баночки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1223,'Нарезать кубиками сливочное масло, добавить кусочки белого шоколада.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1223,'Прогреть ингредиенты на паровой бане до жидкого состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1223,'Влить сгущенное молоко, всыпать миндальную муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1223,'Перемешать до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1223,'Прогреть две минуты, пасту снять с огня. Остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1224,'Поставить на огонь воду, всыпать сахарный песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1224,'Сироп варить пять минут с момента закипания. Снять с плиты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1224,'В горячий сироп всыпать какао-порошок, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1224,'Далее положить сливочное масло, перемешать еще раз.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1224,'Сухое молоко ввести небольшими порциями, перемешивать, в пасте не должно быть комочков.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1224,'Всыпать орехи.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1224,'Продукт можно сразу подать к столу или охладить в баночках для хранения.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1225,'Черную фасоль замочить на двенадцать часов в холодной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1225,'Отварить бобы до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1225,'Отдельно обжарить орехи на сухой сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1225,'Продукты пропустить через мясорубку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1225,'Выложить в блендер, добавить мед, какао-порошок и кокосовое масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1225,'Перебить в однородную массу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1226,'Жирные сливки налить в емкость с толстым дном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1226,'Всыпать коричневый тростниковый сахар, ванилин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1226,'Массу прогреть на тихом огне. Помешивать. Не давать сливкам закипеть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1226,'Желатин растворить в воде так, как написано на упаковке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1226,'Влить готовый продукт в горячие сливки через сито, чтобы в десерт не попали комочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1226,'Другой вариант – использовать марлю.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1226,'Влить коньяк без ароматизаторов в том случае, если блюдо не готовится для детей.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1226,'Массу разлить в формочки из силикона, поставить в холод для застывания на несколько часов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1227,'Растворить желатин по прилагаемой инструкции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1227,'Растворимый ароматный кофе залить крутым кипятком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1227,'Растворить в жирных сливках тростниковый сахарный песок. Прогреть на среднем огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1227,'В горячую смесь положить кусочки горького шоколада.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1227,'Снять с огня, добавить кофе с желатином, массу перемешать и процедить, разлить в формочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1227,'Охладить панакоту в холодильнике.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1228,'Агар-агар залить для набухания чистой водой на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1228,'Отдельно перемешать чуть взбитые белки с молоком, каплями стевии, кукурузным крахмалом и ванилином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1228,'Смесь взбить на минимальной скорости в миксере.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1228,'Готовую массу поставить на водяную баню, прогреть до загустения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1228,'Агар-агар прокипятить в течение минуты и влить в крем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1228,'Массу взбить до остывания миксером.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1228,'Готовую массу перелить в формы, остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1229,'Жирное молоко довести до кипения, снять с огня, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1229,'Влить сливки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1229,'Всыпать желатин в небольшую мисочку, добавить теплую кипяченую воду. Ингредиенты перемешать, оставить на шесть или семь минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1229,'Отдельно растопить шоколад, влить в молочную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1229,'Всыпать обычный и ванильный сахар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1229,'Влить заранее растворенный желатин.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1229,'Смесь прогреть при постоянном помешивании, не кипятить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1229,'Разлить массу в креманки, поставить в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1230,'Растворить в кипящей воде желатин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1230,'Перемешать, оставить на пять минут для набухания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1230,'Всыпать в кастрюлю с толстым дном обычный и ванильный сахар, влить сливки и молоко. Прогреть смесь в течение двух минут. До кипения не доводить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1230,'Снять с плиты емкость, влить желатин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1230,'Компоненты перемешать, охладить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1230,'Очистить от хвостиков и стебельков свежую клубнику, превратить в пюре любым доступным способом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1230,'Разлить массу в креманки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1230,'Сверху – сливочная смесь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1230,'Слои перемешать вилкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1230,'Креманки поставить в холод до полного застывания.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1231,'Мандарины ошпарить кипящей водой, выжать сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1231,'Залить желатин кипятком, оставить на четыре или пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1231,'Перелить сливки в сотейник, прогреть до появления пузырьков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1252,'Остудить, чашу перевернуть и вынуть пирог.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1231,'В горячий молочный продукт всыпать сахарный песок, добавить несколько капель ванильной эссенции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1231,'Ввести часть желатина.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1231,'Массу перемешать, вылить в стаканы на две трети объема.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1231,'Емкости убрать на полчаса в холод.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1231,'После того, как масса загустеет – вылить сверху смесь из желатина и мандаринового сока с сахаром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1231,'Десерт снова поставить в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1232,'Бананы очистить от кожуры и нарезать мелкими кубиками. С киви нужно поступить аналогично.  Сливы промыть, удалить косточки и тоже порезать мелкими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1232,'Мандарины очистить от кожуры, поделить на дольки и порубить на несколько кусков.  Из яблока извлечь сердцевину, очистить от кожуры и нарезать мелко.  Все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1233,'Залить холодной водой желатин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1233,'Перемешать, оставить на двенадцать или четырнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1233,'Влить молоко и сливки в емкость с толстыми стенками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1233,'Поставить на огонь средней мощности. Прогреть. До кипения не доводить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1233,'Всыпать ванильный и обычный сахар, ввести желатин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1233,'Перемешивать смесь в течение минуты, процедить через мелкое сито.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1233,'Жидкость разлить в формочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1233,'Остудить сначала при комнатной температуре, покрыть пищевой пленкой, выставить на холод.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1234,'Высыпать желатин в небольшую мисочку, залить молоком комнатной температуры. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1234,'Добавить несколько капель ванильной эссенции в сливки, всыпать тертую лимонную цедру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1234,'После закипания массы ее процедить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1234,'Остатки сливок взбить с сахарным песком, влить ром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1234,'В эту смесь влить горячие, заранее процеженные сливки, добавить желатин и молоко.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1234,'Чтобы не допустить попадания мелких комочков – пропустить смесь через мелкое сито.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1234,'Разлить десерт в формочки из силикона, убрать в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1235,'Развести желатин водой и оставить для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1235,'Перемешать в сотейнике сахарный песок со сливками, добавить лимонную цедру. Прогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1235,'В начале закипания смесь снять с огня. Цедру выбросить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1235,'Влить ванильный экстракт, процедить, разлить в формы, охладить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1235,'Превратить в пюре свежие ягоды малины, добавить сахар и лимонный сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1235,'Готовую застывшую массу полить ягодным соусом, украсить листочками мяты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1236,'Залить холодной водой хлопья желатина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1236,'Молоко перемешать со сливками, добавить выскобленную мякоть и семена ванили из стручка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1236,'Всыпать сахар по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1236,'Массу довести до кипения и сразу снять с огня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1236,'Перемешать кефир с мелкотертой апельсиновой цедрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1236,'Отжать листочки желатина, выложить в смесь в кефирную смесь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1236,'Ваниль выбросить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1236,'Взбить массу при помощи блендера.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1236,'Ввести прогретые сливки с молоком и все остальные ингредиенты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1236,'Разлить массу в стаканы, убрать в холод до остывания.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1237,'Перемешать жирные сливки с молоком, всыпать сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1237,'Смесь довести до кипения, ввести содержимое ванильного стручка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1237,'Желатин замочить в холодной воде на несколько минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1237,'Добавить в слегка остывшую молочную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1237,'Массу остудить и взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1237,'Разлить состав в бокалы, поставить в холод.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1237,'Клубнику превратить в пюре, перемешать с сахаром по вкусу, поварить до загустения, охладить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1237,'Соус соединить с кусочками свежей клубники.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1237,'Полить застывшую панакоту клубничной массой, подать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1238,'Нашинковать капусту белокочанную, нарезать репчатый лук, все вместе обжарить до мягкости на горячей сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1238,'Отдельно соединить соль, сахарный песок и взбитые яйца, муку и разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1253,'Груши вымыть, промокнуть, очистить, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1238,'Густую массу соединить с капустной обжаркой, тесто с начинкой влить в огнеупорную форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1238,'Прикрыть пирог фольгой, печь в течение сорока минут при температуре 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1238,'Фольгу снять, подождать десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1239,'Смешать венчиком мягкое сливочное масло с сахарной пудрой, яичными желтками и лимонной цедрой. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1239,'Тесто разделить на 2 части, в одну из которых добавить какао и вмесить его в тесто. Оба теста отправить в холодильник на 1 час.','https://vkuso.ru/data/cache/data/90/4a14ac7f993da90_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1239,'По истечению этого времени слепить из белого и темного теста шарики величиной с грецкий орех. Выложить их на застеленный бумагой для выпечки противень. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1239,'После того, как печенье остынет, темное посыпать сахарной пудрой, а углубления в каждом печенье заполнить повидлом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1240,'Подготовить все ингредиенты, помыть и очистить овощи.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1240,'К капусте добавить половину картофеля.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1240,'Добавить молоко и перебить массу блендером.','https://vkuso.ru/data/cache/data/45/0e0fd1cf9440245_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1240,'Подавать суп, в сочетании цельных нарезнных овощей и кремообразной консистенции супа.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1241,'Сливочное масло растопить, смешать с сахарным песком, сырым яйцом и нашинкованной белокочанной капустой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1241,'Всыпать муку и разрыхлитель, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1241,'Массу перелить в форму, печь в течение тридцати пяти минут, температура – 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1242,'Шампиньоны нарезать кусочками небольшого размера, обжарить на сковороде, добавить рубленую зелень и нашинкованную белокочанную капусту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1242,'Посолить по вкусу, всыпать любимые специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1242,'Отдельно взбить сырые яйца, перемешать со сметаной, разрыхлителем, мукой, досолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1242,'Влить в форму для выпекания половину жидкого теста, начинку с грибами, сверху – оставшееся тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1242,'Температура выпекания – 190 градусов, время приготовления – сорок пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1242,'Пирог остудить и подать на стол.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1243,'Взять две крупные луковицы, нашинковать их и обжарить на масле.  Взять жирную баранину или говядину, отварить его в 3 литрах воды. После чего порезать небольшими кусочками и положить его к луку. Бульон нужно процедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1243,'Промыть все овощи. Картофель очистить.  Морковь протереть через крупную терку.  Помидоры и болгарский перец нарезать соломкой. Положить их к мясу. К мясу с овощами положить томатную пасту и залить небольшим количеством бульона. Тушить на среднем огне полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1243,'Очищенный картофель также нарезать соломкой.  Тушеные овощи и мясо вложить обратно в кастрюлю, положить туда картошку, залить оставшимся бульоном.  Приправить густой суп «Шурпа» с говядиной и варить еще минут 10. Как только картошка отварилась положить измельченный чеснок и зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1244,'Готовый фарш перемешать с рубленым репчатым луком, обжарить на заранее прогретой сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1244,'Всыпать нашинкованную белокочанную капусту, довести начинку до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1244,'Взбить сырые куриные яйца, перемешать с мукой, сметаной, разрыхлителем и специями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1244,'Влить в форму часть массы, выложить мясо с капустой, добавить остатки теста.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1244,'Выпечку довести до готовности при температуре 190 градусов, время приготовления – сорок минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1245,'Нарезать свежую белокочанную капусту полосками, обжарить со специями на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1245,'Сметану или майонез досолить, вбить сырые куриные яйца, мукой и разрыхлителем. Масса должна получиться густой и однородной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1245,'Влить часть теста в форму, выложить капусту, сверху залить остатками теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1245,'Пирог выпечь в течение тридцати пяти минут, температура – 190 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1245,'Готовность определяется румяной корочкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1246,'Нарезать белокочанную капусту и зелень, перемешать, высыпать в форму для выпекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1246,'Залить растопленным сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1246,'Отдельно перемешать сырые куриные яйца с кефиром, мукой, разрыхлителем, соль – по вкусу. Должна получиться однородная масса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1246,'Влить в форму на капустную начинку, поставить в духовой шкаф на сорок минут. Температура выпекания – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1247,'Нарезать капусту, всыпать в чашу мультиварки, выставить режим «Жарка». Начинка должна стать мягкой, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1247,'Отдельно взбить сырые куриные яйца с мукой и разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1247,'Готовую однородную массу влить к начинке, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1247,'Выставить режим «Выпечка» на час или чуть больше.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1248,'Белокочанную капусту нарезать полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1248,'Обжарить на сковороде, посолить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1248,'Остудить и перемешать с тертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1248,'В другой емкости взбить куриные яйца с разрыхлителем и мукой. Масса должна получиться однородной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1248,'Влить в форму часть теста, выложить начинку, сверху – оставшееся тесто. Время выпекания – полчаса. Температура приготовления – 190 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1248,'Довести до румяной корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1249,'Форму для запекания застелить пекарской бумагой, дно смазать маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1249,'Яблоки очистить, удалить семенные камеры, нарезать дольками, выложить на дно формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1249,'Отдельно сырые куриные яйца перемешать и взбить с сахарным песком. Масса должна увеличиться в три раза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1249,'Перемешать разрыхлитель с мукой, просеять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1249,'Всыпать в яйца, перемешать движениями снизу-вверх.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1249,'Массу перелить в форму на яблоки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1249,'Мандарины очистить, удалить мякоть, обвалять кусочки в крахмале.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1249,'Выложить на пирог, утопить наполовину.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1249,'Время выпекания – пятьдесят минут, температура – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1250,'В воду всыпать соду, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1250,'Вымыть в этой жидкости яйца, протереть полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1250,'Отделить желтки от белков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1250,'В желтковую массу всыпать часть сахарного песка, взбить до побеления при помощи миксера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1250,'Всыпать оставшийся сахар в белки, перемешать, взбить до получения плотной массы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1250,'В желтки всыпать муку с содой и ванилином, перемешать лопаткой, ввести белковую массу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1250,'Смазать разъемную или целую форму маргарином, перелить тесто.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1250,'Промыть и очистить груши, нарезать кубиками, добавить в тесто.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1250,'Поставить в печь. Время запекания – сорок минут, температура – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1250,'Проверить готовность шпажкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1251,'Взбить сырые желтки с сахаром при помощи миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1251,'Всыпать заранее просеянную муку с разрыхлителем, корицу молотую. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1251,'Белки взбить отдельно также при помощи миксера, всыпать сахар в процессе приготовления.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1251,'Ввести массу в желтки с мукой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1251,'Форму смазать кусочком сливочного масла, вылить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1251,'Всыпать нарезанные груши и яблоки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1251,'Печь шарлотку в духовке, время – от тридцати пяти до сорока минут, температура – 185 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1252,'Чашу прибора смазать маргарином.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1252,'Вымыть и очистить груши, тонко нарезать, выложить в емкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1252,'Охладить и взбить сырые куриные яйца с обычным и ванильным сахаром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1252,'Всыпать муку и разрыхлитель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1252,'Перемешать, влить в чашу с фруктами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1252,'Поставить емкость в мультиварку, выставить режим «Выпечка» на сорок минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1253,'Бананы очистить, мелко нарезать, присыпать мукой, чтобы кубики не слиплись.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1253,'Сырые куриные яйца подержать при комнатной температуре, взбить с сахарным песком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1253,'Просеять и добавить муку с разрыхлителем и ванилин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1253,'Замесить тесто при помощи лопатки. Масса должна быть тягучей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1253,'Переложить тесто в форму для запекания со смазанными маргарином стенками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1253,'Выложить фрукты, печь при температуре до 175 градусов. Время приготовления – от сорока до сорока пяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1253,'Готовность определяется наличием румяной корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1254,'Нарезать белый хлеб ломтиками, а затем пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1254,'Выложить на дно кастрюли, залить качественным свежим кефиром. Жирность – любая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1254,'Массу прикрыть пленкой и оставить на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1254,'Натереть очищенную грушу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1254,'Перемешать сырые куриные яйца с сахарным песком при помощи миксера. Сахар должен раствориться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1254,'Фруктовую массу переложить на батон, залить яйцами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1254,'Сверху – кусочки сливочного масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1254,'Печь в духовом шкафу при температуре 180 градусов, время – сорок минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1254,'Десерт оставить в духовке на ночь для настаивания.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Ромашковый чай в пакетиках выложить в сотейник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Залить горячими сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Через час пакетики вынуть и выбросить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Сливки довести до слабого кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Желтки распустить с сахарным песком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Перелить в сливки, прогреть на тихом огне до загустевания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Прикрыть пленкой в контакт с поверхностью крема, массу охладить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Отдельно в воду влить натуральный мед, лимонный сок, цедру, сахарную пудру и корицу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Состав довести до кипения.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Всыпать промытый изюм, нарезанную кубиками грушу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Нагрев уменьшить, варить от десяти до пятнадцати минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Готовый сироп процедить через марлю или сито, остудить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Емкость для запекания смазать сливочным маргарином.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Дно и бортики выложить кусочками сдобной булки.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Полить остывшим сиропом, всыпать грушевую массу с изюмом.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Сделать крышку из остатков хлеба.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Выставить изделие в холодильник на ночь.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1255,'Пирог переложить на большое блюдо, залить десерт чайным ромашковым кремом, массу можно взбить миксером.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1256,'При помощи миксера перемешать сырые куриные яйца с сахарным песком, добавить немного ванильной эссенции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1256,'В воздушную массу просеять муку, какао-порошок и разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1256,'Перемешать круговыми движениями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1256,'Массу перелить в форму для выпекания, смазанную маргарином.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1256,'Выложить нарезанные груши, кусочки молочного шоколада.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1256,'Поставить пирог в духовой шкаф, печь при температуре от 175 до 180 градусов, время приготовления – от сорока до сорока пяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1257,'Свежую вишню промыть, удалить косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1257,'Плоды помесить на дуршлаг, сок должен стечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1257,'Сырые яйца взбить с сахаром при помощи миксера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1257,'Просеять муку с пищевой содой или разрыхлителем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1257,'Всыпать в яичную массу. Замесить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1257,'Емкость для выпекания застелить пергаментом, равномерно рассыпать ягоды.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1257,'Вылить тесто, разровнять.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1257,'Время выпекания – сорок минут, температура – 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1258,'Сначала нужно приготовить тесто. Для этого смешать все ингредиенты. Хорошо вымешать. После чего разделить его на три куска. В одну вмешать мак, в другую – курагу, а в третью – измельченные орешки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1258,'Раскатать все три куска на коржи и выпекать в духовке, которая предварительно разогрета до 200 градусов. Для выпекания потребуется 20-25 минут. Готовность определить с помощью спички или шпажки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1280,'Взбить яйца с сахарным песком, влить растопленное сливочное масло и кефир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1258,'Пока пекутся коржи можно приготовить крем. Взбить сметану с сахаром. Иногда можно добавить желатин, заранее разведенный в воде.  Слегка остудить готовые коржи и промазать кремом. Верх оригинального торта «Бедный еврей» украсить тертым шоколадом или орешками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1259,'Взбейте масло с сахаром и яйцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1259,'Просейте муку, смешайте с разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1259,'Соедините масляную смесь и муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1259,'Морковь натрите на терке (или морковный жмых), добавьте в тесто, перемешайте до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1259,'Разогрейте духовку до 180 градусов. Подготовьте форму для выпечки, смажьте ее маслом (можно сделать один кекс или несколько кексиков в маленьких формочках для маффинов). Выложите тесто в форму.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1259,'Поместите в разогретую духовку и выпекайте морковный кекс примерно 45 минут. (Если вы делаете маффины, то выпекайте их в духовке около 20 минут.)',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1259,'Выньте готовый морковный кекс из духовки, оставьте минут на 15, затем выньте кекс из формы (или маффины из формочек). Посыпьте морковный кекс сахарной пудрой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1260,'Подготовить все ингредиенты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1260,'Затем смешать все вместе и замешать тесто на печенье.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1260,'Запечь в духовке при температуре 180 градусов в течении 10 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1260,'Время выпечки зависит от размера ваших печенюшек.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1261,'Сахарный песок перемешать с яйцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1261,'Всыпать просеянную муку с разрыхлителем, перемешать. Масса должна получиться полужидкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1261,'Замороженные ягоды вишни перемешать с крахмалом, добавить в основную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1261,'Смазать сливочным маслом форму для запекания, застелить бумагой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1261,'Вылить тесто, поставить в духовой шкаф. Температура выпекания – 180 градусов. Время приготовления – полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1261,'Пирог остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1262,'Приготовить тесто из яиц, сахарного песка, соды, просеянной муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1262,'Вымыть и очистить яблоки, мякоть тонко нарезать пластинками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1262,'Жаропрочную форму присыпать панировкой или манкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1262,'Выложить фрукты, посыпанные сахарным песком и молотой корицей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1262,'Тесто вылить поверх яблок, распределить ягоды вишни без косточек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1262,'Дать постоять пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1262,'Температура приготовления – 180 градусов, время – сорок минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1263,'Перемешать при помощи миксера яйца с сахарным песком, объем должен увеличиться в два раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1263,'Всыпать соль и специи, просеянную муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1263,'Емкость для выпекания смазать внутри растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1263,'Вылить тесто, выложить ягоды вишни в любом порядке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1263,'Выставить режим «Выпечка» на час или полтора.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1263,'Пирог остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1264,'Ягоды вымыть, удалить косточки, поместить в дуршлаг, лишняя жидкость должна стечь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1264,'При помощи миксера взбить сырые яйца с сахарным песком, можно добавить ванилин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1264,'Муку просеять с пищевой содой или разрыхлителем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1264,'Всыпать в яичную массу, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1264,'Емкость для запекания застелить пергаментной бумагой, выложить ягоды в один слой, вылить тесто. Начинка должна быть полностью покрыта.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1264,'Поверхность разровнять, время выпекания – сорок минут, температура – 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1265,'В миске смешать тыквенное пюре, сахар, масло и молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1265,'Добавить яйцо, соду, соль, корицу, имбирь и мускатный орех, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1265,'Всыпать часть муки, перемешать до однородности. Добавить оставшуюся муку и хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1265,'В тесто добавить рубленые грецкие орехи, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1280,'Погасить соду уксусом, добавить в яичную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1265,'Формы для кексов смазать растительным маслом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1266,'Вишню засыпать сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1266,'Добавить творог, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1266,'Вбить яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1266,'Добавить соду и манную крупу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1266,'Растопить сливочное масло, добавить его в смесь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1266,'Смазать маслом форму для выпекания. Другой вариант – застелить бумагой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1266,'Налить тесто, поставить в духовой шкаф. Время выпекания – полчаса, температура – до 220 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1267,'Яйца перемешать с сахаром, смесь взбить в пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1267,'Перемешать муку с какао-порошком и разрыхлителем, всыпать в яичную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1267,'Бортики формы для запекания смазать маслом, дно застелить пергаментом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1267,'Вылить коричневое тесто в емкость, всыпать вишню в один слой, ягоды утопить. Время выпекания – около получаса, температура приготовления – около 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1268,'Сырые куриные яйца разделить на желтки и белки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1268,'Белки взбить на средней, а затем на максимальной скорости в течение минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1268,'Всыпать сахарный песок, продолжать взбивать до плотного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1268,'В желтковую массу всыпать муку и сахар, перемешать до однородного состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1268,'Влить в белковую массу, осторожно перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1268,'Дно формы для выпекания смазать растительным маслом и застелить пергаментом. Вместо растительного можно использовать сливочное масло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1268,'Тыкву нарезать или натереть на терке, выложить в форму.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1268,'Влить тесто.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1268,'Пирог поставить в духовку, температура выпекания – 220 градусов, время от двадцати пяти минут до получаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1268,'Выпечку перевернуть. Бумагу удалить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1269,'Сырые яйца взбить со сливками и сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1269,'Просеять муку, всыпать в яичную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1269,'Добавить разрыхлитель, перемешать до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1269,'Тыквенную и яблочную мякоть нарезать кубиками, выложить на дно смазанной емкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1269,'Залить начинку тестом, печь в течение сорока минут, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1270,'Тыкву очистить от семян и кожуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1270,'Муку просеять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1270,'Перемешать кефир с яйцом, содой или разрыхлителем или содой, сахарным песком. Масса должна получиться однородной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1270,'Ввести муку порциями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1270,'Добавить по вкусу ванилин из пакетика. Тесто должно постоять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1270,'Всыпать кубики мякоти тыквы, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1270,'Массу перелить в смазанную форму для выпекания. Другой вариант – застелить емкость пергаментом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1270,'Выпечь до готовности, дать постоять в выключенной духовке.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1271,'Для начала грецкий орех нужно измельчить почти в крошку. Это можно сделать при помощи блендера, или ножика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1271,'Как только измельчили грецкий орех, перекладываем его в тарелку, и добавляем сахар, перемешиваем и убираем в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1271,'Далее нужно раскатать тесто, сильно раскатывать не нужно. Как только раскатали посыпаем тесто подготовленным грецким орехом, и при помощи скалки вдавливаем в тесто грецкий орех (сильно довить не нужно) после чего закатываем одну часть теста до середины, потом другую часть до середины. У вас должны получится заготовки печенья в виде «ушек» Далее нарезом на равные части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1271,'Перекладываем на протвинь, и смазываем взбитым куриным яйцом, далее посыпаем сверху сахаром',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1271,'Отправляем в разогретую духовку при 180°C, до тех пор пока не подрумянится корочка. Лично у меня печенье выпекалось около 20-25 минут. Осторожно достаем из духовки, перекладываем на тарелку и подаем к чаю.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1272,'Куриную грудку нужно очистить от кожи и костей. Лук, чеснок очистить, зелень промыть в холодной воде. Очистить от мусора гречку, промыть ее и отварить в подсоленной воде. Прокрутить мясо вместе с луком и чесноком. Перемешать фарш с гречкой и яйцом. Посолить и поперчить. Убрать в холод на 15 минут.  Половину сыра твердых сортов нарезать мелкими кубиками. Остальное нужно будет для соуса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1272,'Сделать небольшие тефтели. В середине оставить кубик сыра. Аккуратно выложить в форму.  Сделать соус из сметаны, сливок и тертого сыра. Добавить зелень, соль. Все тщательно перемешать. Залить соусом готовые тефтели. Поставить тефтели с начинкой в духовку на 35 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1273,'Пищевую соду всыпать в кефир, перемешать, добавить сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1273,'Яйца перетереть, массу влить в кефир.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1273,'Влить растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1273,'Всыпать просеянную муку с разрыхлителем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1273,'Слепить шарики из творожной массы, сахар – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1273,'Тыкву нарезать пластинками среднего размера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1273,'Форму застелить пергаментом, влить тесто.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1273,'Выложить на поверхность творожные изделия и тыкву.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1273,'Время выпекания – от сорока до сорока пяти минут, температура – 200 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1274,'Тыкву измельчить на крупной терке, добавить сахарный песок, натуральный мед и коньяк.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1274,'Специи перетереть, всыпать в основную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1274,'Влить апельсиновый сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1274,'Всыпать муку и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1274,'Соду погасить уксусом, добавить соль и цукаты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1274,'Массу выложить в форму для выпекания. Температура приготовления – от 180 до 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1275,'Яйца взбить, всыпать сахарный песок, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1275,'Всыпать просеянную муку и разрыхлитель. Масса должна получиться однородной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1275,'Тыквенную мякоть нарезать мелкими кубиками, выложить в емкость для выпекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1275,'Насыпать изюм.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1275,'Вылить тесто. Печь при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1275,'Готовность выпечки проверить деревянной шпажкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1276,'Сырые куриные яйца взбить в пену с сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1276,'Растопить на водяной бане или в микроволновой печи сливочное масло, влить в яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1276,'Все вместе взбить миксером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1276,'Погасить соду уксусом, перелить в основную смесь, всыпать муку порциями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1276,'Массу хорошо перемешать, выложить в смазанную форму.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1276,'Выложить сверху свежие или замороженные ягоды клубники. Если ягоды крупные – разрезать их на две или четыре части.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1276,'Время выпекания в духовом шкафу – тридцать пять минут. Температура приготовления – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1277,'Сырые куриные яйца взбить с ванилином и разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1277,'В густую пышную массу всыпать сахар и муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1277,'Продукты взбить при помощи миксера до однородного состояния. Тесто должно быть полужидким и напоминать сметану.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1277,'Форму для выпекания присыпать манной крупой и сахаром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1277,'Выложить ягоды клубники, разрезанные пополам. Если плоды мелкие – оставить их целыми.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1277,'Залить тестом начинку, пирог поставить в горячий духовой шкаф. Печь до получения румяной корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1278,'Недозрелые ягоды промыть под краном, обсушить бумажным полотенцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1278,'Приготовить тесто из сырых яиц с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1278,'Массу взбить при помощи блендера, обороты увеличивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1278,'Ввести муку порциями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1278,'Перемешивать до исчезновения комочков. Лучше использовать деревянную ложку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1278,'Смазать чашу мультиварки маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1278,'Выложить часть теста.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1278,'Второй слой – ягодная начинка, сверху – оставшееся тесто.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1278,'Выставить режим «Выпечка» на сорок пять минут, затем «Подогрев» на пятнадцать минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1278,'Приготовить крем из сметаны, сахара, клубники. Украсить пирог.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1279,'Смазать сливочным маргарином противень с высокими бортами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1279,'Выложить яблоки, нарезанные дольками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1279,'Присыпать корицей и крахмалом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1279,'Выложить тонко нарезанную клубнику.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1279,'Приготовить тесто: сырые куриные яйца взбить с сахарным песком, всыпать ванилин, муку с содой или разрыхлителем. Масса должна получиться однородной, без комочков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1279,'Залить начинку, поставить пирог в духовой шкаф. Время выпекания – сорок минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1280,'Всыпать муку небольшими порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1280,'Форму смазать маслом, посыпать манной крупой, вылить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1280,'Выложить нарезанные ягоды клубники, утопить их в тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1280,'Время выпекания – около пятидесяти минут, в последние пятнадцать минут температуру в духовке уменьшить до 160 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1281,'Перетереть творог с частью сахарного песка, перемешать с мягким сливочным маслом. Масса должна получиться однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1281,'Желтки и белки взбить по отдельности в пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1281,'Яичные желтки ввести в творог, добавить муку и оставшийся сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1281,'По желанию всыпать ванильный сахар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1281,'Время выпекания десерта – сорок минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1282,'Перемешать муку, манную крупу, соль, сахар, разрыхлитель. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1282,'Влить кефир и растительное масло, довести массу до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1282,'Из яблок извлечь семенные камеры, мякоть нарезать ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1282,'В форму для выпечки выложить начинку, а затем вылить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1282,'Поставить пирог на десять минут в духовку, температура выпекания – 200 градусов, затем понизить до 180, готовить полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1283,'Размягченное масло взбить миксером с сахаром, постепенно добавляя яйца до пышной массы. Добавить сметану. Соду погасить лимонным соком или уксусом и тоже добавить к взбитой массе. Всыпать муку и замесить тесто.','https://vkuso.ru/data/cache/data/4f/260eeb77e14624f_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1283,'Яблоки очистить от кожицы и удалить сердцевину. Разрезать их пополам.','https://vkuso.ru/data/cache/data/d0/148b761f1f9e8d0_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1283,'Разъемную форму для выпечки смазать маслом и выложить в нее тесто. Поверх выложить половинки яблок слегка утопив их в тесте. Отправить в разогретую духовку на 15-20 минут при температуре 180 градусов.','https://vkuso.ru/data/cache/data/33/ff22c93aa6a1333_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1283,'Для заливки: взбить миксером сметану с сахаром, яйцами и крахмалом.','https://vkuso.ru/data/cache/data/63/8bb3bb1a2077763_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1283,'Вынуть пироги из духовки и залить заливкой. Снова отправить в духовку примерно на 30 минут, ориентируйтесь по своей духовке. Сверху должна образоваться блестящая золотистая корочка.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1284,'Взять филе говядины, промыть, отварить в соленой воде и остудить. После чего разрезать его мелкими кусочками. Свежие огурцы нарезать в виде соломки.  Масло перемешать с давленым чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1284,'Свежий батон хлеба разрезать на кубики и обжарить в чесночном масле до золотистой корочки. Слить воду с консервированной фасоли.  Перемешать все ингредиенты в глубокой миске.  Добавить в мясной салат с фасолью и сухариками соль и заправить майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1285,'Перемешать сахар с мукой и манной крупой, солью и разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1285,'Влить растительное масло и кефир.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1285,'Массу перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1285,'Яблоки очистить от кожуры и сердцевины, нарезать дольками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1285,'Вылить к тесту, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1285,'Прогреть сковороду на плите, смазать растительным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1285,'Вылить тесто с начинкой, нагрев – средний.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1285,'Готовить сорок минут под крышкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1286,'В емкость всыпать соду или разрыхлитель, мягкое сливочное масло и муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1286,'Перемешать руками в крошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1286,'Влить сметану, перемешать массу еще раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1286,'Обернуть тесто в пищевую пленку и убрать в холод на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1286,'Очистить кислые яблоки, удалить сердцевину, мякоть нарезать ломтиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1286,'Побрызгать лимонным соком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1286,'Форму застелить пергаментом, выложить тесто так, чтобы сформировать бортики.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1286,'Разместить начинку из яблок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1286,'Остатки сметаны взбить с сахарным песком, всыпать муку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1286,'Массой покрыть начинку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1286,'Выставить температуру в духовке в 180 градусов, время приготовления – двадцать минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1286,'На подрумянивание – еще двадцать минут, температура – 140 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1303,'Полить остатками апельсинового сока.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1287,'Растительное масло перемешать с молоком, всыпать муку, перемешанную с сахаром и разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1287,'Яблоки очистить, вырезать семенные камеры, мякоть нарезать тонкими ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1287,'Выложить начинку в форму, залить тестом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1287,'Поставить пирог в духовку, время приготовления – около сорока минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1288,'Перемешать сахарный песок с манной крупой, пальмовым или кокосовым сахаром, корицей, цельнозерновой крупой, молотым имбирем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1288,'Влить в сухую смесь воду и кокосовое молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1288,'Всыпать соду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1288,'Насыпать в силиконовую форму манку, влить часть жидкого теста, выложить яблоки, очищенные и нарезанные пластинками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1288,'Сверху – остатки теста, время выпекания – сорок минут, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1289,'Манную крупу перемешать с сахарным песком, влить кефир, оставить для набухания на двадцать минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1289,'Перемешать соду с мукой, ванильным сахаром, медом, растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1289,'Смесь добавить в манку с кефиром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1289,'Очистить яблоки от кожуры, удалить сердцевину, мякоть нарезать дольками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1289,'Поместить яблоки в чашу мультиварки, влить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1289,'Выставить режим «Выпечка» на час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1289,'Пирог остудить в мультиварке, вынуть и подать на стол.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1290,'Замариновать мясо целиком.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1290,'Разогреть гриль и жарить мясо с двух сторон до полной готовности.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1290,'Мясо получается очень сочным и гораздо вкуснее, чем любая буженина.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1291,'Маршмеллоу помещаем в емкость, добавляем лимонный сок  и ставим на водяную баню или отправляем в микроволновку. Растапливаем.','https://vkuso.ru/data/cache/data/98/cceeb04a0182d98_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1291,'Всыпаем сахарную пудру и замешиваем мастичное тесто.','https://vkuso.ru/data/cache/data/f2/95938837afe67f2_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1291,'Раскатываем мастику скалкой до нужной вам толщины и можно вырезать украшения из нее или использовать для обтяжки тортов.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1292,'Лук, картофель, морковь очистить от кожуры, болгарский перец очистить от семян. Лук нарезать тонкими четвертькольцами, морковь, болгарский перец и картошку – маленькими кубиками. Сельдерей нарезать размером с морковь.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1292,'В глубокой сковороде разогреть растительное масло, выкладываем мясо и жарим 7 минут на сильном огне перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1292,'Помидоры нарезать кубиками. Добавить к мясу помидоры, лук и морковь. Готовим на среднем огне 10 минут, перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1292,'Нарезаем чеснок тонкой соломкой. Спустя 10 минут обжарки мяса с овощами добавляем болгарский перец, сельдерей и чеснок. Посыпаем паприкой, солью и добавляем томатную пасту, готовим 10 минут на среднем огне, перемешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1292,'Спустя 10 минут посыпаем мукой и перемешиваем, после заливаем водой, снова перемешиваем и готовим 15 минут. Спустя 15 минут засыпаем картофель, перемешиваем и готовим 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1292,'Мелко нарезать базилик и укроп. Отправить в сковороду. Готовить 5 минут, а в это время отварить лапшу для лагмана.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1293,'Свинину нарезать небольшими кусочками, охотничьи колбаски – колечками, вешенки –маленькими кусочками, шампиньоны дольками, лук – четвертькольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1293,'В сковороде с растительным маслом обжарить на сильном огне свинину в течении 5 минут, перемешивая. Добавить лук, грибы, колбаски, томатную пасту, капусту и перец – перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1293,'Добавить лавровый лист и влить воду. Накрыть крышкой и убавить огонь до минимума. Тушим 1,5 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1294,'Очистите болгарский перец от семян. Нарежьте мелким кубиком. Лук репчатый очистите и нарежьте полукольцами. Оливковое масло разогрейте на сковороде и обжарьте перец и лук до золотистого цвета (около 15 минут) на среднем огне. Переложите в отдельную миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1294,'Куриную грудку порежьте на мелкие кусочки. На той же сковороде, где готовился перец и лук разогреть еще немного оливкового масла и обжарить куриную грудку в течении 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1294,'Оливки нарежьте кольцами, помидоры черри мелким кубиком. Отправить к курице, также добавьте лук с перцем. Добавить специи: соль, сахар, тмин, помолоть перец горошком. Чеснок пропустить через пресс и отправить в сковороду, добавить фасоль, кукурузу, Перемешайте и готовьте 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1294,'В чистой сковороде раскалить растительное масло. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1295,'Смешать манную крупу с кефиром, добавить 2 яйца, сахар, сливочное масло, соду и муку, после каждого ингредиента необходимо тщательно перемешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1295,'Затем смазать форму для запекания сливочным маслом и выложить в нее тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1295,'Отправить в духовку на 40 мин. при 180 градусах. Приятного аппетита.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1296,'Для этого супа нужно взять говядину на косточке, так бульон будет наваристее и сытнее. Кроме этого понадобятся лук, грецкие орехи, чеснок, морковка, сельдерей, томаты, хмели-сунели, зелень петрушки и кинзу. Мясо промыть и положить в большую кастрюлю. Туда же бросить сельдерей и морковь, которые нужно нарезать крупными кусочками, и одну четвертую часть лука. Залить содержимое кастрюли 2 литрами воды и варить в течение часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1296,'В это время нужно приготовить суповую заправку. Для этого ошпарить кипятком томаты и очистить их от кожицы. После этого мелко нашинковать.  Слегка отварить и пропустить через сито. Оставшийся лук нашинковать мелко. Грецкие орешки измельчить вместе с чесноком. При этом подлить немного бульона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1296,'Смешать орехи и чеснок с приправами. Можно взять готовую приправу хмели-сунели или же приготовить самостоятельно из черного, душистого перца и корицы. Готовое мясо вынуть из кастрюли, дать остыть. После этого нарезать небольшими кусками. Бульон процедить через сито, чтобы избавиться от мелких осколков костей. Удалить морковь и сельдерей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1296,'Взять глубокую сковороду и прожарить на жире лук. Жир можно использовать тот, что вышел при варке мяса. Как только лук стал прозрачным снять с огня.  Положить к нему мясо, залить небольшим количеством бульона и тушить 10 минут. Добавить пюре из томатов. Потушить в течение 10 минут. Просеянную муку развести слегка остывшим бульоном, тщательно растереть. Важно, чтобы получалась однородная масса без комочков. Соединить смесь с мясом и овощами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1296,'Довести массу до кипения и тушить еще 5 минут. Оставшийся бульон прогреть и налить к тушеным овощам и мясу. Снова дать вскипеть и положить чеснок с орехами. Туда же бросить лавровый лист, убавить огонь и держать еще немного.  В самую последнюю очередь положить в грузинский суп «Харчо» зелень и дать настоятся под закрытой крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1297,'Перемешать сахарный песок с апельсиновым соком, влить яблочный уксус, растительное масло, положить соду и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1297,'Ингредиенты перемешать до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1297,'Всыпать муку, приготовить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1297,'Яблоки очистить, удалить семенные камеры, мякоть нарезать тонкими ломтиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1297,'Выложить начинку в форму, залить тестом, время выпекания пирога – около пятидесяти минут, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1297,'Остудить и вынуть из формы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1298,'Перемешать сахарный песок с сырыми куриными яйцами, перебить при помощи миксера. Масса должна увеличиться в два раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1298,'Муку всыпать порциями, продолжать взбивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1298,'Нарезать кружками очищенные бананы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1298,'Противень смазать растительным маслом, присыпать манной крупой или панировочными сухарями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1298,'Вылить часть жидкого теста, выложить часть начинки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1298,'Залить остатками теста. Можно сделать два слоя начинки и три – теста.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1298,'Прогреть духовой шкаф до 180 градусов, поместить пирог на противне, печь до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1298,'Шарлотка должна стать румяной. Пирог остудить, посыпать сахаром или пудрой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1299,'Белки сырых яиц отделить от желтков, взбить в пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1299,'Всыпать сахарный песок, взбивать до растворения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1299,'Влить желтки, всыпать муку, перемешать массу еще раз. В ней не должно быть комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1299,'Дно и бортики чаши мультиварки смазать кусочком сливочного масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1299,'Вылить тесто, выложить нарезанные бананы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1299,'Выставить режим «Выпечка» на сорок минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1299,'Готовность проверить зубочисткой. Оставить пирог в мультиварке до остывания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1300,'Яйца перемешать с сахарным песком, взбить при помощи миксера так, чтобы объем массы увеличился в два раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1300,'Перемешать отдельно муку с разрыхлителем, всыпать в яичную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1300,'Перемешать все вместе миксером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1300,'Яблоки нарезать дольками, можно снять кожуру.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1300,'Бананы превратить в кашицу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1300,'Смазать маслом форму для выпекания, выложить на дно яблоки, второй слой – бананы, третий – тесто. Время выпекания – двадцать пять минут, температура – 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1300,'Пирог должен приобрести коричневатую корочку, готовность выпечки проверить зубочисткой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1300,'Десерт вынуть из формы, остудить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1301,'Подготовить все ингредиенты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1301,'Добавить к луку фарш и также обжарить.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1301,'Расскатать тесто, сделать надрезы посередине в виде солнышка.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1301,'Завернуть правильно пирог, заворачивая надрезанные края.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1301,'Запечь в духовке на максимальной температуре до готовности.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1302,'Филе куриной грудки нарезаю крупными кусочками. Очищенную тыкву, картофель и перец нарезаю мелкими кубиками. Лук и чеснок мелко нарубить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1302,'В сковороде разогрев растительное масло, выкладываю лук, обжариваю 3-4 минуты до прозрачности. Добавляю сладкий перец, чеснок, тыкву, картофель и обжариваю 10-15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1302,'Затем добавляю к овощам кукурузу и горошек, перемешав, заливаю сливками, добавляю молотый красный перец, солю по вкусу и тушу 5 минут на слабом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1302,'В отдельной сковороде хорошо разогреваю оставшееся масло, выкладываю куриную грудку и обжариваю со всех сторон (5-6 минут).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1302,'Выложив грудку в сковороду с овощным соусом, еще раз все перемешать, прогреваю 3-4 минуты на слабом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1302,'Перед подачей готовое блюдо посыпаю сверху нарезанным укропом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1303,'Нарезать спелый банан кружками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1303,'Апельсин вымыть, очистить от кожуры, нарезать мякоть кусочками небольшого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1303,'Сок слить в отдельную емкость.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1303,'Взбить при помощи миксера яйца с сахаром, ванилином. Общее время приготовления – пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1303,'Всыпать муку порциями, тесто перемешивать ложкой. Масса должна получиться полужидкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1303,'Смазать чашу мультиварки растительным маслом, вылить все тесто, сверху – фруктовая начинка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1303,'Выставить режим «Выпечка» на пятьдесят минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1303,'После окончания выпекания оставить пирог внутри прибора на десять минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1303,'Чашу перевернуть на большую тарелку, через пять минут емкость снять.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1304,'Взбить сырые куриные яйца при помощи венчика, добавить сахарный песок, пищевую соду и муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1304,'После добавления каждого ингредиента массу взбивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1304,'Нарезать кругляшками очищенные киви и бананы. Толщина – средняя.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1304,'Треть готового полужидкого теста влить в силиконовую форму, выложить часть фруктов в произвольном порядке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1304,'Влить еще часть теста, вновь выложить начинку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1304,'Сверху – остатки теста, кусочки начинки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1304,'Форму с пирогом поставить в духовой шкаф, температура – 180 градусов, время выпекания – пятьдесят минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1304,'Готовый пирог перевернуть на тарелку, остудить и подать к чаю.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1305,'Сырые куриные яйца и сахарный песок взбить в пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1305,'Муку всыпать порциями, тесто перемешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1305,'Нарезать кусочками очищенные бананы и груши.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1305,'Пересыпать к тесту, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1305,'Часть бананов оставить для украшения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1305,'Смазать растительным маслом противень, вылить смесь с фруктами, сверху – кусочки бананов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1305,'Время выпекания пирога – сорок минут, температура – 180 градусов. Готовность определяется наличием золотистой корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1305,'Готовую шарлотку вынуть из духового шкафа, подать к чаю или кофе.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1306,'Бананы очистить и нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1306,'Яйца взбить с сахарным песком в густую пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1306,'В отдельной емкости перемешать муку с разрыхлителем, всыпать соль и какао-порошок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1306,'Сухую смесь порциями добавить в жидкую, вымесить. Должна получиться масса средней густоты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1306,'Дно и стенки формы смазать маслом, посыпать манной крупой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1306,'В форму выложить половину бананов, вылить тесто, сверху украсить остатками бананов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1306,'Готовить в духовке при температуре 170 градусов, время – сорок минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1306,'Другой вариант – готовить в мультиварке в течение часа, режим «Выпечка».',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1306,'Готовый пирог перевернуть на блюдо, посыпать сахарной пудрой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1307,'Подготовить все ингредиенты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1307,'Жарить на гриле, сковороде-гриль или запечь в духовке.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1307,'Подавать сыр горячим, с пылу-жару.','https://vkuso.ru/data/cache/data/02/ba10fa8479a1b02_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1308,'Свинину нарезать на небольшие кусочки. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1308,'Разогреть сковороду, добавить растительное масло.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1308,'Добавить лук, жарить 2 мин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1308,'Добавить мирин, затем выложить кимчи, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1308,'Добавить сахар, черный перец, красный перец, соль. Хорошо перемешать и готовить еще 5-6 мин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1308,'На тарелку с одной стороны выложить обжаренную свинину с кимчи, с другой стороны тарелки выложить тофу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1309,'Маринад. Смешиваем черный молотый перец, красный острый перец, хмели-сунели, чеснок, горчицу, соль и растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1309,'Нарезаем корейку на порционные кусочки и разрезаем вдоль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1309,'Смазываем маринадом и сверху кладем полосочку бекона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1309,'Заворачиваем корейку с беконом и смазываем маринадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1309,'Жарим на углях 30-40 минут. Готовьте с удовольствием и приятного аппетита! Подробный рецепт приготовления вы можете посмотреть в видео.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1310,'Для салата потребуется промыть и отварить постную говядину в соленой воде. Остудить. После чего нарезать его в виде соломки.  Репчатый лук очистить и нарезать в виде полуколец. Все это положить в глубокую посуду и залить 9% уксусом. Желательно развести его водой в пропорции две части уксуса и одна часть воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1317,'Вбить сырые куриные яйца, ванильный сахар, мякоть банана, размятую при помощи вилки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1317,'Всыпать муку для торта вместе с пищевой содой и разрыхлителем, молотой корицей, влить молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1310,'Дать замариноваться в течение 15 минут. Огурцы вынуть из маринада и порезать также в виде соломки.Помидоры промыть в холодной воде и порезать на половинки. Зелень и листья салата промыть, хорошо обсушить. В глубокой посуде смешать все ингредиенты. Приправить солью и перцем и заправить любым оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1310,'На блюдо положить листья зеленого салата сверху положить готовый мясной салат «Шемахинский» с луком. Помидорки черри и зелень использовать в качестве украшений.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1311,'Для крема необходимо смешать творог, сахар и сметану до однородной консистенции. Если под рукой не окажется блендера, сахар можно заменить сахарной пудрой. Бананы нарезаем кружочками, а киви дольками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1311,'Теплое молоко наливаем в чашку, так чтобы было удобно опускать печенье. И начинаем выкладывать первый слой. Для этого каждую печеньку опускаем в молоко и сразу выкладываем на блюдо. Выкладываем часть творожного крема. Поверх крема выкладываем бананы и посыпаем орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1311,'Повторяем слой с печеньем и кремом и выкладываем поверх киви.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1311,'Затем повторяем слой с печеньем, кремом, бананом и орехами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1311,'Последний слой мы также покрываем кремом и украшаем. Для этого несколько печенек измельчаем в крошку и смешиваем с орехами. Также торт можно украсить шоколадной крошкой или фруктами. Чтобы торт хорошо пропитался убираем его в холодильник на несколько часов. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1312,'Помидор нужно нарезать кубиками. Также необходимо измельчить зелень. В глубокой чашке смешиваем творог с тертым сыром, и ранее подготовленными зеленью и помидорами. По желанию можно добавить соль.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1312,'Половину листа лаваша смазываем сметаной и посыпаем тертым сыром. Накрываем сверху второй частью лаваша, смазываем сметаной и выкладываем начинку. ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1312,'Аккуратно сворачиваем в рулет и выкладываем на противень. Смазываем желтком и посыпаем кунжутом. Выпекаем в предварительно разогретой духовке 15 минут при 180 градусах. ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1312,'Даем рулету немного остыть и нарезаем на порции. Такое блюдо можно готовить как на завтрак, так и в качестве закуски! Обязательно попробуйте приготовить! Приятного аппетита!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1313,'Грибы вымыть и обжарить с репчатым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1313,'Пшеничную муку также обжарить до золотистого цвета, добавить давленый чеснок, влить заранее приготовленный куриный бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1313,'Соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1313,'Выложить в суп грибы, довести до кипения, положить кусочки курицы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1313,'После того, как блюдо закипит, влить сливки, еще раз довести до кипения, огонь выключить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1314,'Нарезать крупными кусками очищенный картофель, кабачок, помидоры и сладкий перец, репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1314,'Мясное филе нарезать кубиками, полить растительным маслом, добавить сладкую паприку, тимьян, базилик, петрушку, соль, молотый черный перец, чеснок, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1314,'На дно формы для запекания выложить мясо, сверху – подготовленные овощи, кушанье залить водой, перемешанной с томатной пастой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1314,'Накрыть влажным листом пекарской бумаги, запекать от 40 до 45 минут, температура приготовления – от 200 до 220 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1315,'Подготовит все ингредиенты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1315,'Смешать все остальные ингредиенты и перебить до однородной консистенции.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1315,'Нарезать укроп, посыпать серху на бутерброды.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1315,'Все очень просто и быстро, а главное вкусно.','https://vkuso.ru/data/cache/data/70/1f2b8fa32032970_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1316,'Капусту  тонко нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1316,'Перец  нарезать тонкими полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1316,'Лук нарезать тонкими полукольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1316,'Фету нарезать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1316,'Для заправки: смешать измельченный чеснок, лимонный сок, соль, сахар и растительное масло. Перемешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1316,'Заправить салат и аккуратно перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1316,'Салат украсить зеленью и обжаренными семечками подсолнечника.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1317,'Размягченное сливочное масло взбить с сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1317,'Если тесто получилось слишком жидким – всыпать остатки муки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1317,'В последнюю очередь добавить измельченные грецкие орехи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1317,'Время выпекания – от 40 до 50 минут, это зависит от возможностей духовки. Температура – 170 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1317,'Приготовить глазурь из растопленного белого шоколада, сливочного масла, крема-чиз.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1317,'Можно поступить проще и использовать только шоколад, растопленный на водяной бане.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1317,'Украсить готовый кекс полосками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1318,'В подогретую воду добавить свежие дрожжи, сахарный песок, немного муки, смесь оставить на несколько минут, дрожжи должны «заработать».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1318,'В оставшуюся муку всыпать соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1318,'Все перемешать, должно получиться жидкое тесто, оставить его на час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1318,'Для приготовления начинки измельчить при помощи мясорубки или блендера куриную печень и сердечки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1318,'Субпродукты обжарить, пока не остыли, добавить молотый репчатый лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1318,'Сформовать пирожки масляными руками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1318,'Обжарить во фритюре.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1319,'Перемешать пастообразный творог с сахаром, простоквашей, мягким сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1319,'Взбить ингредиенты при помощи миксера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1319,'В другую емкость просеять муку с разрыхлителем и содой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1319,'Все соединить, замесить тесто. Если оно получилось жидковатым – добавить муку, вымесить, оставить на столе на десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1319,'Раскатать в лепешку, намазать размягченным сливочным маслом, посыпать смесью молотой корицы с коричневым сахаром и любыми молотыми орехами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1319,'Свернуть тесто в рулет, нарезать на части.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1319,'Время выпекания – от 25 минут до получаса. Температура – от 180 до 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1319,'Приготовить соус из сметаны и сахарной пудры, полить готовые булочки или смазать маслом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1320,'Натереть на средней терке сыр памезан.  В глубокой миске перемешать готовый фарш из филе индейки, крошки хлеба, белок, 1 зубчик чесночка, неполную чайную ложку соли, четверть чайной ложки молотого перца и немного орегано.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1320,'Тщательно смешать все ингредиенты и сделать небольшие фрикадельки. После чего поставить их на холод. В это время разогреть духовку примерно до 170-80 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1320,'В сотейнике разогреть растительное масло на небольшом огне. Положить туда лук с чесноком и слегка потушить их в течение 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1320,'Туда же положить морковку и сельдерей. Протушить еще 5 минут.  Залить смесь бульоном и посолить. Сделать огонь сильнее. Сразу после того как смесь закипела бросить туда измельченную капусту. Варить на среднем огне примерно 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1320,'Достать фрикадельки из холодильника и выложить их на противень. Поставить в духовку на 12 минут. Готовые фрикадельки положить в суп и отварить их еще 5 минут. Приправить итальянский свадебный суп с фрикадельками из индейки. Готовое блюдо разлить по тарелкам и посыпать протертым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1321,'Перемешать сухие ингредиенты: соль, сахарный песок, муку, ванильный сахар из пакетика, разрыхлитель, корицу, молотый мускатный орех, гвоздику, имбирь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1321,'Добавить охлажденное сливочное масло и перетереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1321,'Вбить сырое куриное яйцо, влить молоко, готовое тыквенное пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1321,'Замесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1321,'Раскатать, сложить конвертом один или два раза и раскатать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1321,'Нарезать сконы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1321,'Время выпекания – от 12 до 15 минут, температура – 220 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1321,'Готовую выпечку покрыть глазурью, приготовленной из сахарной пудры и молока.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1322,'Перемешать мягкое сливочное масло с сахарным песком, массу взбить, добавить яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1322,'Просеять разрыхлитель, какао-порошок и муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1322,'Замесить тесто, большую его часть выложить в смазанную маслом форму для выпекания, сформовать бортики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1322,'Небольшой кусочек оставить для украшения, положить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1322,'Для начинки перемешать творог с сахаром и сметаной, добавить ванилин из пакетика, крахмал, сырые яйца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1322,'Ингредиенты взбить и выложить поверх теста. Коричневые пятна из оставшейся массы расположить произвольно.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1322,'Время выпекания – один час, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1323,'Просеять пшеничную муку, всыпать соль и разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1323,'В другой емкости перемешать растительное масло с молоком и простоквашей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1323,'Соединить жидкие ингредиенты с сухими.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1323,'Замесить гладкое тесто, разделить его на части, должны получиться лепешки размером с небольшую мисочку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1323,'Приготовить смазку из растительного масла, простокваши и нигеллы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1323,'Время выпекания – полчаса при температуре от 180 до 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1324,'Перемешать молоко с простоквашей и растительным маслом, смесь прогреть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1324,'Добавить сырое куриное яйцо, сахар и соль, свежие дрожжи, просеянную муку и разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1324,'Тесто вымесить, оставить на час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1324,'Поделить на две части, дать постоять еще 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1324,'Тесто не обминать, растянуть руками каждую часть в лепешку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1324,'Через 15 минут смазать верх смесью простокваши с яйцом, посыпать семенами чернушки и сыром «Фета».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1324,'Время выпечки – от 18 до 20 минут, температура приготовления – от 180 до 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1325,'Просеять муку, добавить разрыхлитель и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1325,'Отдельно перемешать жидкие ингредиенты – воду с яйцом, уксусом и растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1325,'Соединить то и другое, замесить тесто, оставить его на час в холодном месте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1325,'Раскатать массу в пласт, выложить заранее приготовленное картофельное пюре, сформовать пирожки-кныши.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1325,'Для смазывания перемешать сырой желток с молоком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1325,'Температура выпекания – от 190 до 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1326,'Соединить соль, сахарный песок, сырые куриные яйца, воду, растопленное сливочное масло и ром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1326,'Добавить немного молока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1326,'Всыпать муку, тесто хорошо размешать. В нем не должно быть комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1326,'Влить оставшееся молоко, оставить тесто на столе на два часа для набухания клейковины.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1326,'Хорошо разогреть сковороду и выпечь блины.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1327,'Репчатый лук и морковь измельчить, обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1327,'Всыпать немного муки, влить воду и пассату.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1327,'Смесь довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1327,'Выложить свинину, время тушения – от 10 до 15 минут, всыпать сладкую паприку, соль, сахар, черный молотый перец, базилик, положить лавровый лист',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1327,'Крупно нарезать свежий кабачок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1327,'Снять кожуру с помидоров, мякоть нарезать кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1327,'Все вместе потушить в течение часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1328,'В миске смешаем теплую воду, дрожжи и сахар. Размешаем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1328,'Теперь к дрожжам просеиваем муку и добавляем соль, перемешаем. Далее добавим растительное масло и замесим тесто для лаваша. Накроем миску с тестом пищевой пленкой и уберем в теплое место на 1 час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1328,'На противень положим пергаментную бумагу и выложим на нее наше дрожжевое тесто в форме лаваша.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1328,'Духовку разогреем до 200 градусов и готовим в ней лаваш 20-25 минут. Приятного Вам аппетита.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1329,'Обжарить измельченный репчатый лук, добавить чеснок, пропущенный через пресс, соль и молотый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1329,'Картофель очистить и нарезать тонкими кружками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1329,'На дно формы для выпекания налить растительное масло, выложить половину картофеля, затем слой мясного фарша, оставшийся картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1329,'Перемешать молоко с яйцом, залить блюдо. Жидкость должна покрыть картошку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1329,'Время запекания – один час, температура – 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1330,'Мягкое сливочное масло перемешать с сахарным песком, ванильным сахаром из пакетика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1330,'Смесь взбить при помощи миксера, добавить яйца и соль, еще раз взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1330,'Добавить пакетик ванильного или миндального пудинга, долить молоко, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1330,'Просеять муку с разрыхлителем, всыпать в основную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1330,'Тесто на лист выкладывать ложкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1330,'Время выпекания – от 15 до 20 минут, температура – 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1330,'Донышко готового печенья смазать лимонной глазурью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1331,'Соединить сметану с майонезом, добавить пищевую соду, соль, сырые куриные яйца муку, хорошо перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1331,'Нарезать репчатый лук, очищенный картофель натереть, лишнюю жидкость отжать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1331,'Открыть банку с консервированной сайрой или сардиной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1331,'В форму для выпекания вылить половину теста, разложить картофель, рыбу и лук, залить остатками теста.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1331,'Время выпекания – от 40 до 45 минут, температура – 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1332,'Приготовить маринад из кефира, сладкой паприки, черного молотого перца, соли, давленого чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1332,'Выложить кусочки курицы, оставить на полчаса или час для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1332,'Размолоть несладкие кукурузные хлопья.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1332,'Обмакивать кусочки мяса в панировку и выкладывать на противень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1332,'Время запекания – от 20 до 25 минут, температура приготовления – от 180 до 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1333,'Молоко налить в небольшую кастрюлю и поставить на огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1333,'Перемешать какао-порошок с сахарным песком и залить горячей водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1333,'В закипающее молоко влить шоколадную смесь, перемешать и дождаться еще одного закипания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1334,'В миске взбить яйцо с сахаром и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1334,'Добавить творог, перемешать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1334,'Сковороду разогреть на средне-сильном огне, добавить растительное масло.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1335,'Консервированный в собственном соку тунец нужно размять с помощью вилки до кашицы. Слить воду с консервированной кукурузы. Сладкий болгарский перец нарезать маленькими кубиками. Лук мелко нашинковать. Маринованный или соленый огурец тоже нужно нарезать мелко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1335,'Перемешать все продукты с майонезом, соком лимона. Добавить горчицу на кончике ножа, молотый перец и соль. Взять армянский лаваш и выложить на него готовую массу. Свернуть лист в виде рулета. После чего разрезать его на порционные куски и подать на стол украсив веточкой зелени. Закусочные рулетики с кукурузой и тунцом готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1336,'Подготовить все ингредиенты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1336,'Через 30 минут добавить вино, розмарин и продолжать тушить.','https://vkuso.ru/data/cache/data/eb/8adc1ba9a2dcaeb_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1336,'Добавить бульон, заправить по вкусу солью и перцем.','https://vkuso.ru/data/cache/data/5b/9bbb67ceb7d3c5b_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1336,'Сделать гренки с сыром.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1337,'Натираем тыкву на мелкой терке.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1337,'Яичные белки взбиваем с сахарной пудрой до устойчивых пиков.','https://vkuso.ru/data/cache/data/4f/b619071dfb70e4f_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1337,'Постепенно вмешиваем белки в массу из тыквы.','https://vkuso.ru/data/cache/data/a0/77f1ad9f4a217a0_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1337,'Выкладываем массу в формы (я слегка смазала их маслом), посыпаем корицей (можно украсить тыквенными семечками) и отправляем в духовку на температуру 180 градусов, примерно на 25 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1338,'Картофель нарезаем на равные дольки, перекладываем в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1338,'Солим, перчим, добавляем паприку и сушеный чеснок по вкусу, также слегка добавляем растительное масло, все хорошо перемешиваем. Перекладываем на противень и отправляем в разогретую духовку при 180°С на 25-30 минут. Спустя 25-30 минут картофель должен приготовиться!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1338,'Я заранее подготовил куриное филе. Я его распластал на 2 половины. И чуть подрезал, после слегка отбил.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1338,'Далее, его нужно посолить и поперчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1338,'Взбиваем 1 куриное яйцо. (так же можно добавить воды, или молоко).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1383,'Свернуть небольшие рулеты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1338,'Куриное филе обваливаем в муке, потом отпускаем в взбитое куриное яйцо. потом панируем в панировочных сухарях. Перекладываем на доску или тарелку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1338,'В сковородку примерно на 1 см, вливаем растительное масло, даем ему разогреться, и далее обжариваем шницель, до золотистой корочки. С каждой стороны нужно обжарить около 2 минут. Как только обжарили перекладываем на тарелку с бумажным полотенцем. Все готово.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1339,'Кабачки вымыть, нарезать полукольцами, посолить, поперчить, выложить на сковороду с маслом, добавить давленый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1339,'Тушить в течение восьми или десяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1339,'Отдельно развести сметану в воде, всыпать крахмал, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1339,'Смесью залить овощи, довести до кипения, огонь погасить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1340,'Сахарный песок всыпать в сырые куриные яйца, смесь взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1340,'Добавить сметану и еще раз взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1340,'Всыпать просеянную с пищевой содой муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1340,'Вымыть и нарезать яблоки, посыпать сахаром, молотой корицей, красиво разложить в форме, смазанной маслом, залить тестом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1340,'Время выпекания – 40 минут, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1341,'В емкость для блендера насыпать нарезанный кусочками репчатый лук, добавить картофель, зубчики чеснока, кусочек черствого мякиша. Хлеб должен быть белым и подсохшим.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1341,'Долить молоко, массу перемолоть, вбить сырое куриное яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1341,'Ингредиенты перемешать, влить смесь в готовый фарш. Соль и перец молотый – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1341,'Отбить рукой в миске.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1341,'Сформовать котлеты, обвалять в манной крупе, выложить на заранее разогретую сковороду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1341,'Жарить по очереди с двух сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1341,'Долить воду, накрыть крышкой, потушить блюдо в течение 15 или 20 минут, огонь – средний.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1342,'Замесить тесто из молока, простокваши или густого натурального йогурта, растительного масла, яйца, сахара, соли, муки, дрожжей и разрыхлителя.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1342,'Массу вымесить до гладкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1342,'Готовое тесто поделить на две части, скатать в шары, оставить на 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1342,'Массу не обминать, растянуть в лепешки, дать полежать еще 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1342,'Для смазки верха перемешать сырое куриное яйцо с простоквашей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1342,'Присыпать лепешки нигеллой или сыром «Фета».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1342,'Время выпекания – от 15 до 20 минут. Температура – от 180 до 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1343,'Капусту и морковь натереть на терке, посолить, перемешать, добавить немного сахарного песка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1343,'Для заправки перемешать сметану с готовой сладкой горчицей и соком лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1344,'Смешиваем муку, соль, масло.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1344,'Добавляем горячую воду.','https://vkuso.ru/data/cache/data/a4/ae0e180185782a4_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1344,'Вымешиваем тесто.','https://vkuso.ru/data/cache/data/a2/87e2349b7d0fca2_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1344,'Оставляем на 30 минут на расстойку.','https://vkuso.ru/data/cache/data/80/444a90796108f80_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1344,'Формируем лепешки.','https://vkuso.ru/data/cache/data/f1/2193e82c815b9f1_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1344,'Обжариваем 3 минуты.','https://vkuso.ru/data/cache/data/5e/385205fe88bbd5e_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1344,'Переворачиваем и обжариваем еще 3 минуты.','https://vkuso.ru/data/cache/data/84/ab3c1aa23843684_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1344,'Снова переворачиваем и жарим до образования воздушного кармана.','https://vkuso.ru/data/cache/data/76/f831ae2a4c37676_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1344,'Обрызгиваем водой. Складываем под влажное полотенце. Приятного аппетита!','https://vkuso.ru/data/cache/data/29/6f9e71fcc5fc029_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1345,'Смешиваем сухие ингредиенты: муку, разрыхлитель, соль, имбирь, корицу, мускатный орех.','https://vkuso.ru/data/cache/data/aa/bfc4dfd36c099aa_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1345,'Отдельно взбиваем сахар с яйцами.','https://vkuso.ru/data/cache/data/d0/50f0bca342333d0_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1345,'В кефире гасим соду и добавляем к яичной массе и добавляем растопленной сливочное масло.','https://vkuso.ru/data/cache/data/68/daf725bf14df368_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1345,'Смешиваем сухие ингредиенты с яичной массой. Замешиваем тесто.','https://vkuso.ru/data/cache/data/97/5c09f66e2809b97_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1345,'Груши нарезаем кубиком и вмешиваем в тесто.','https://vkuso.ru/data/cache/data/2e/9a043d8e571332e_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1383,'Разрезать наискосок пополам. Наколоть на шпажки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1345,'Готовим крамбл: холодное сливочное масло режем кусочками, добавляем сахар, муку и корицу и перетираем до образования крошки.','https://vkuso.ru/data/cache/data/54/394610127796a54_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1345,'Посыпаем верх пирога крамблом и отправляем его в разогретую духовку на температуру 180 градусов примерно на 30 минут, ориентируйтесь на свою духовку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1346,'В творожную массу вбить сырое куриное яйцо, посолить по вкусу, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1346,'Всыпать муку, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1346,'Готовое тесто нарезать кусочками, варить в подсоленной воде в течение трех минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1347,'Для теста необходимо взять размягченное сливочное масло перемешать с яйцом. Добавить соль, воду и уксус. Все тщательно перемешать.  Добавить муку и замесить эластичное тесто.  Готовое тесто убрать в холод, а в это время приготовить крем.  Творог нужно протереть через мелкое сито. После чего тщательно перемешать с сахаром, добавив туда ваниль и яйца.  Лишь после этого можно добавить размягченное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1347,'Массу поставить на огонь, где постоянно помешивая довести до кипения. Затем проварить еще пару минут, чтобы масса стала густой.  Важно не передержать крем, так как после остывания он еще немного загустеет. Тесто нужно разделить на 10 кусков, которые нужно очень тонко раскатать. Выпекать коржи на сковороде без масла. Выпекаются коржи очень быстро. Поэтому не нужно отходить далеко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1347,'Для того чтобы коржи получились ровными их необходимо проколоть вилкой.  Если коржи разного размера, их можно обрезать, приложив тарелку. Обрезки потом уйдут на украшения. Коржики промазать кремом и украсить обсыпкой из остатков. Дать пропитаться крему. Домашний торт «Лесная ягодка» на сковороде готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1348,'Сырое яйцо с солью и сахарным песком взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1348,'Влить кислый йогурт или кефир, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1348,'Всыпать пищевую соду, просеянную муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1348,'Массу перемешать и оставить для набухания клейковины на 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1348,'Печь на огне средней мощности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1349,'Добавить в кефир сахарный песок, соль, сырое куриное яйцо, сметану и пищевую соду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1349,'Массу перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1349,'Всыпать заранее просеянную муку, замесить тесто, дать ему полежать в течение 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1349,'Разделить тесто на две равные части, раскатать в пласты, порезать на прямоугольники, сделать надрезы и вывернуть, как хворост.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1349,'Жарить в глубокой сковороде во фритюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1350,'Сладкий болгарский перец очистить от хвостиков и семенных камер.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1350,'Отдельно обжарить нарезанный репчатый лук, всыпать рис, обжарить все вместе, добавить сырокопченое сало, нарезанное мелкими кусочками, приправу «Вегета» и паприку, мясной фарш и мелко нарезанный чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1350,'Массу посолить и поперчить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1350,'Наполнить смесью плоды, верх закрыть кружками свежей картошки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1350,'Переложить овощи в кастрюлю, вплотную друг к другу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1350,'Залить все водой и пассатой до верха. Время тушения – полтора часа, затем еще полчаса с открытой крышкой. Температура приготовления – от 180 до 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1351,'Прогреть на сковороде растительное масло, выложить перец, разрезанный на три или четыре части, красный, желтый или оранжевый.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1351,'Сверху посолить, посыпать приправой «Вегета», разложить кусочки сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1351,'Время жарки – от 10 до 12 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1352,'Сироп из сахара и воды довести до кипения, выложить заранее промытые ягоды, дать закипеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1352,'Огонь выключить, оставить на 10 – 12 часов для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1352,'Еще раз проварить в течение 15 минут, оставить еще на 10 – 12 часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1352,'Процедуру повторить еще раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1352,'Готовое варенье перелить в стерильные банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1353,'Перемешать творог со сметаной, вбить сырое куриное яйцо, влить молоко, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1353,'Всыпать сахарный песок, соль, добавить растительное масло, часть муки и пищевую соду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1353,'Массу перемешать, добавить оставшуюся муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1353,'Тесто должно постоять в течение 10 – 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1353,'Выпекать под крышкой на заранее разогретой сковороде с растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1354,'Помидоры нарезать и потушить с водой до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1354,'Массу перемолоть блендером, протереть через сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1354,'Варить с сахаром в течение 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1354,'Всыпать соль, специи, варить полчаса или дольше, часть влаги должна выпариться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1354,'Добавить уксус, огонь погасить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1354,'Массу перелить в стерильные бутылки, укупорить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1355,'Репчатый лук, морковь и чеснок нарезать и обжарить в кастрюле на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1355,'Добавить цветную капусту, кабачок, брокколи, все ингредиенты залить кипящей водой, потушить до полной готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1355,'Превратить массу в пюре при помощи блендера, посолить по вкусу, долить молоко, еще раз поставить на плиту и довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1355,'Подать с подсоленными гренками, обжаренными на оливковом масле с добавлением чеснока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1356,'Репчатый лук, чеснок, сельдерей и морковь нарезать, добавить кусочки тыквы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1356,'Овощи залить кипящей водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1356,'Варить до полной готовности, массу превратить в пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1356,'Долить молоко, соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1356,'Поставить на плиту, довести суп до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1356,'Оливковое масло прогреть с розмарином или другими душистыми травами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1356,'Обмакнуть кусочки в масло, выложить твердый сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1356,'Сначала обжарить сторону без сыра, а затем с сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1357,'5 яиц разбить в кастрюлю. Положить туда масло, молоко, соль и муку. После чего тщательно взбить венчиком или миксером. Крабовые палочки очистить от пленки и мелко порубить. Всыпать их к яичной смеси и перемешать. Укроп измельчить и всыпать в массу. Равномерно перемешать. На противень для выпечки постелить пекарскую бумагу, которая предварительно смазана маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1357,'Вылить готовую смесь и выпекать в разогретой до 180 градусов духовке. Через 15 минут омлет готов. Во время выпекания омлета нужно приготовить начинку, которая состоит из сыра и вареных яиц. Их нужно натереть на мелкой терке. Чеснок можно также протереть или раздавить при помощи пресса.  Посыпать измельченным укропом и тщательно перемешать с майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1357,'Омлет после извлечения из духовки нужно немного остудить. Затем снять с бумаги.  Аккуратно размазать начинку по всей поверхности омлета. Свернуть рулет. При необходимости закрепить ниткой или пленкой. Поставить закусочный рулет из крабовых палочек в холод на 5-6 часов. Перед подачей нарезать и украсить веточками зелени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1358,'Капусту (у меня савайская) мелко нашинкуем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1358,'Яйца отварим и нарежем их средним кубиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1358,'Крабовые палочки также нарежем как и яйца на кубики среднего размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1358,'Луковицу и зелень мелко нашинкуем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1358,'Смешиваем все ингредиенты в салатнике и добавляем горошек (предварительно слив из него всю жидкость).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1358,'Заправляем салат майонезом и посолив перемешаем наш салат из крабовых палочек.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1359,'Маринад.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1359,'Разрезаем курицу пополам. Делаем неглубокие надрезы и поливаем маринадом. Оставляем мариноваться на 2 часа.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1359,'Нанизываем курицу на шампура и жарим на углях 30-40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1360,'Для начала приготовим соус: в посуду добавим соевый соус, кунжутное масло и соус шрирача, перемешаем, оставим в сторонке',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1360,'В отдельной посуде разобьём 3 яйца, посолим и перемешаем, теперь разогреем масло в сковородке и приготовим омлет, далее, готовый омлет поломаем на маленькие кусочки и переложим в тарелку. В той же сковородке начнём жарить бекон, лук, морковь и горох',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1360,'Можно по желанию добавить немного масла, выдавим чеснок, слегка перемешаем и добавим рис, сверху польем соусом, перемешаем и добавить омлет. Рис готов, приятного аппетита, спасибо  за просмотр, посмотрите наши другие видео по ссылке в описании, не забывайте подписываться и написать комментарий',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1361,'Охлажденное масло порезать хлопьями. Добавить остальные продукты кроме джема и сахарной пудры, замесить тесто. Убрать в холодильник на 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1361,'Тесто раскатать в тонкий пласт на посыпанном мукой столе. Вырезать формочками печенье одинаковой формы, но разного размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1361,'Выпекать на выстланном пергаментной бумагой противне 12 минут в разогретой до 180°С духовке. Остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1361,'Соединить по два или три печенья разного размера при помощи джема. Посыпать сверху сахарной пудрой.','https://vkuso.ru/data/cache/data/1e/5ac8ba6f27dd61e_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1362,'Лук нарезать кубиками, нарезать чеснок слайсами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1362,'Помидоры разрезать на 4 части и выложить на противень, посолить, поперчить и сбрызнуть оливковым маслом. Выпекать помидоры 25 минут при 220°С.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1362,'В кастрюлю добавить оливковое масло и обжарить лук на средене-сильном огне до золотистого цвета. Добавить чеснок и жарить еще 1 минуту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1362,'Добавить помидоры в собственном соку и бульон, перемешать. Варить на среднем огне 20 минут. Через 20 минут добавить сушеный базилик, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1362,'С запеченных помидор снять шкурку. Переложить в кастрюлю. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1362,'Влить сливки, перемешать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1363,'Готовую горчицу перемешать с перцем, солью и рубленой зеленью. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1363,'Мясо хорошо промыть в холодной воде и обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1363,'Дольки чеснока очистить и разрезать пополам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1363,'Сделать в куске мяса надрезы, нашпиговать чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1363,'Обмазать продукт горчичным соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1363,'Мясо завернуть в лист фольги, запекать в духовке 120 минут. Температура приготовления – 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1363,'В мясе сделать надрез, если вытечет светлый бульон – продукт готов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1363,'Удалить фольгу, допечь до румяного оттенка.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1364,'Мясо вымыть, удалить пленки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1364,'Приготовить смесь из сметаны, молотой куркумы, перца, соли, давленого чеснока, добавить молотый мускатный орех.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1364,'Готовым соусом обмазать мясо, положить в рукав, влить немного куриного бульона, чтобы продукт получился сочным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1364,'Завязать рукав с двух сторон, выложить в духовку, рукав наколоть в нескольких местах для выхода пара. Печь в течение часа. Температура приготовления – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1364,'Готовность проверить по светлому соку, который должен вытекать при надрезе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1365,'Сварить рассол: в воду добавить соль, лавровый лист, перец-горошек, прованские травы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1365,'Довести до кипения, положить мясо на ночь. Продукт должен хорошо просолиться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1365,'Через десять-двенадцать часов мясо вынуть, начинить дольками чеснока, поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1365,'Обернуть продукт фольгой, выложить в духовой шкаф. Температура запекания – до 200 градусов, время – до готовности, но не меньше 120 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1365,'Мясо проверять, чтобы не пересушилось.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1366,'Сварить маринад из воды, лаврового листа, соли, перца-горошка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1366,'Выложить кусок молодой говядины на двенадцать часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1366,'Приготовить смесь из меда с давленым чесноком, солью, бальзамическим уксусом, соевым соусом. Ингредиенты хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1366,'Вынуть мясо из рассола, обсушить, намазать готовым соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1366,'Завернуть в фольгу, положить в духовой шкаф на два часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1367,'Вымыть куриное филе, удалить лишний жир и пленки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1367,'Приготовить пряную смесь из чеснока, пропущенного через пресс, сладкой горчицы, соевого соуса и бальзамического уксуса, приправ для куриного мяса. Соль – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1367,'Выложить мясо в соус на полтора часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1367,'Продукт завернуть в лист фольги, поставить на час в духовку, температура запекания – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1367,'Нежную буженину нарезать на порции.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1368,'Мясо говядины или свинины отварить в подсоленой воде. После чего слегка охладить и измельчить с помощью мясорубки. Нарезанный полукольцами лук замариновать в растворе воды и уксуса. Соотношение должно быть 1:1',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1368,'После 10 минут отжать лук. Сыр и отварные яйца каждый отдельно измельчить на терке. Салат нужно выложить слоями. Первый слой – это мясо, промазанное майонезом, затем идет лук, снова майонез. Протертые яйца также смазанные майонезом. Последний слой сыр. Мясной салат «Мужской каприз» с сыром готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1369,'Лук очистить и нарезать тонкими полукольцами. В сковороде разогреваем растительное масло. Обжариваем лук на среднем огне 5 минут, перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1369,'Шампиньоны вымыть, разрезать пополам и нарезать тонкими слайсами. Добавить к луку, готовим 10 минут на среднем огне, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1369,'В сотейник насыпать муку, немного прогреть, перемешивая, до появления легкого золотистого цвета. Добавить сливочное масло, греем пока растает масло – перемешивая. Сливки разогреть в микроволновке, чтобы стали теплые, вливаем в сотейник, перемешиваем и готовим пока не загустеет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1369,'Готовый соус выливаем к грибам с луком, добавляем мускатный орех и смесь перцев, перемешиваем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1370,'Свинину промыть холодной водой, вырезать лишний жир, удалить пленки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1370,'Приготовить маринад из острого молотого перца чили, соевого соуса, сухого молотого имбиря, зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1370,'Оставить мясо в маринаде на несколько часов, перемешивать три или четыре раза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1370,'Обжарить кунжутное семя.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1370,'Мясо вынуть из пряной смеси, выложить в фольгу, положить в духовку на полтора часа. Температура выпекания – 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1370,'Оставшийся маринад перелить в сковороду с толстыми стенками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1370,'Добавить мед натуральный, поварить, пока смесь не загустеет.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1370,'Буженину выложить на большое блюдо, полить маринадом, посыпать обжаренными семечками кунжута.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1371,'С курицы снять кожицу, удалить кости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1371,'Мясо замочить в маринаде из воды и соли на ночь или меньше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1371,'Другой вариант: майонез или темное пиво, разведенный водой кефир, лимонный сок или уксус, также разведенный водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1371,'Перемешать кетчуп с любыми приправами для куриного мяса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1371,'Готовым соусом обмазать курицу, наколоть вилкой в нескольких местах.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1371,'Накрыть противень листом фольги, завернуть грудки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1371,'Проделать сверху дырочки для выхода пара.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1371,'Продукт поставить в духовку на пятнадцать минут, температура приготовления – 250 градусов. Подержать в выключенной печи еще час.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1372,'Перемешать с оливковым маслом жгучий перец чили, измельченный сладкий болгарский перец, соль и чесночный порошок, черный молотый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1372,'Обмазать куриное мясо, завернуть в фольгу, выложить на противень. Время запекания – полчаса, температура – 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1372,'Вынуть из духовки, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1372,'Завернуть готовый продукт в пищевую пленку, подержать в холодильнике около двух часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1373,'Чеснок пропустить через пресс или мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1373,'Филе курицы нарезать тонкими большими полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1373,'Мясо посолить и поперчить, намазать чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1373,'Обвязать куриные кусочки нитками, выложить полученную колбасу в рукав, завязать, проколоть оболочку сверху. Время запекания – 45 минут, температура – 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1373,'Вынуть противень из духовки, остудить буженину, снять рукав и нитки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1374,'В глубокую сковороду выложить два слоя фольги.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1374,'Выложить перец-горошек, французскую горчицу, чернослив, лавровый лист, очищенный чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1374,'Куриные кусочки натереть солью, выложить на специи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1374,'Сверху посыпать остатками специй, нарезанным черносливом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1374,'Завернуть фольгу, влить воду, она не должна попасть к курице.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1374,'Сковороду накрыть крышкой, довести воду до кипения на большом огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1374,'Нагрев убавить, тушить блюдо под крышкой два часа. Воду можно подливать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1375,'Картофель, маринованные огурцы и селедку нарезать мелким кубиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1375,'Измельчаем зеленый лук. Часть отправляем в салат, а часть оставляем для украшения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1375,'Заправляем салат майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1375,'На крупной терке натираем свеклу, добавляем лимонный сок и растительное масло, перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1375,'Формируем салат. Выкладываем его на блюдо, формируем прямоугольник и помогая себе деревянными лопатками раздвигаем части, чтобы вложить свекольный слой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1375,'Салату нужно дать настояться 30-40 минут
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1376,'Соль перемешать с любыми специями для курицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1376,'Натереть грудки без костей, сделать проколы вилкой или ножом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1376,'Оставить для пропитывания на час или полтора.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1376,'Молоко в кастрюле довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1376,'Огонь уменьшить, выложить грудки, кипятить две минуты, газ погасить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1376,'Кастрюлю с крышкой завернуть в полотенце и одеяло на два с половиной или три часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1376,'Буженину охладить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1377,'Полутвердый сыр натереть, перемешать с давленым чесноком, майонезом и солью по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1377,'Палочки раскрутить аккуратно, смазать пластинки сырной начинкой, свернуть обратно. Закуску охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1378,'Овощи тщательно промыть в холодной воде. Перец очистить от семян. Огурцы порезать кубиками. Томаты небольшими ломтиками. Перец и очищенный лук полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1378,'Оливковое масло смешать с уксусом и приправами. При желании можно добавить немного сухой горчицы. Сыр фета также нужно измельчить в виде кубиков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1378,'Все перемешать в большой емкости с маслинами. После чего залить овощной салат по-гречески подготовленной заправкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1379,'Печень консервированной трески размять вилкой, добавить масло из консервной банки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1379,'Отварить и натереть куриные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1379,'Натереть подмороженный плавленый сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1379,'Начинку перемешать, посолить и поперчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1379,'Добавить сметану или майонез.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1379,'Палочки разморозить и развернуть, намазать смесью с печенью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1379,'Свернуть обратно, рулеты положить в холод на час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1380,'Приготовить кляр из теплого молока, соли, пищевой соды и молотого перца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1380,'Отдельно взбить сырое куриное яйцо и добавить в смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1380,'Всыпать муку порциями. Кляр должен получиться достаточно густым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1380,'Натереть охлажденный плавленый сыр, добавить майонез, рубленый укроп, давленый чеснок. Массу посолить и поперчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1380,'Палочки осторожно развернуть, намазать чесночной начинкой, завернуть обратно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1380,'Разрезать каждую заготовку на две части.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1380,'Обмакнуть в кляр, жарить с двух сторон на масле.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1380,'Выложить закуску на бумажные полотенца, чтобы удалить излишки жира.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1381,'Крабовые палочки аккуратно размотать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1381,'Измельчить при помощи терки плавленый охлажденный сыр и вареные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1381,'Посолить, заправить майонезом, давленый чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1381,'Начинку перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1381,'Намазать палочки сырной смесью, выложить по рыбке из банки, свернуть маленькие рулеты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1381,'Палочки выложить на тарелку, накрыть пищевой пленкой, убрать в холод.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1382,'Репчатый лук и шампиньоны нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1382,'Грибы – свежие, сырые.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1382,'Обжарить ингредиенты на прогретом масле, посолить начинку по вкусу. Любые приправы – по желанию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1382,'Добавить майонез и тертые отваренные яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1382,'Охлажденные крабовые палочки развернуть, покрыть грибной начинкой, свернуть обратно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1382,'Смазать закуску майонезом, обвалять в сухарной крошке, обжарить в масле, оставшемся от приготовления начинки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1383,'Творог растереть при помощи вилки со сметаной, она должна быть достаточно жирной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1383,'Добавить рубленую зелень, давленый чеснок, перец и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1383,'Развернуть крабовые палочки, выложить начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1384,'Плавленые сырки положить морозильную камеру, а затем натереть на терке с крупными или средними отверстиями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1384,'Зубчики чеснока очистить и пропустить через пресс.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1384,'Натереть вареное яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1384,'Ингредиенты перемешать, заправить майонезом, досолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1384,'Наполнить начинкой развернутые палочки, скрутить обратно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1385,'Чеснок почистить, натереть на мелкой тёрке или пропустить через пресс.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1385,'Ломтики чёрного хлеба натереть солью и чесноком, нарезать кубиками и подсушить на сковороде без масла. Куриное филе нарезать небольшими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1385,'Маринованные огурцы нарезать кубиками. С кукурузы слить жидкость. Сыр нарезать тонкими брусочками или соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1385,'Петрушку вымыть, обсушить, отрезать длинные стебли, зелень петрушки мелко нарезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1385,'В салатнике смешать куриное филе, фасоль, сыр, кукурузу, маринованные огурцы, петрушку и чесночные сухарики из чёрного хлеба, добавить майонез, салат ещё раз перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1386,'Нарезаем язык, свежий огурец, яйца кубиком, лук тонкими перышками, зелень петрушки мелко (немного оставляем для украшения).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1386,'Добавляем зеленый горошек, солим, перчим и перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1386,'Готовим заправку. Для этого в сметану добавляем измельченный вареный яичный желток и горчицу. Перемешиваем венчиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1386,'Добавляем к салату заправку, перемешиваем и украшаем зеленью.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Мелко нарезать репчатый лук, чеснок, лук-порей и сельдерей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Продукты обжарить на оливковом масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Очистить рыбу любых сортов, удалить плавники и головы, добавить в овощную обжарку, влить воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Жидкость должна покрыть рыбу, тушить все вместе две минуты под крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Бланшировать помидоры, снять кожицу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Мякоть превратить в пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Мелко нарезать еще одну луковицу, чеснок, фенхель, обжарить на масле, добавить томатное пюре.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Вынуть рыбу из бульона, жидкость процедить, гущу из овощей протереть через сито.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Остудить бульон, перемешать с протертыми и обжаренными овощами.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Выложить куски крупной рыбы.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Варить до мягкости основного продукта.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Рыбу вынуть, выложить на отдельное блюдо.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Приготовить соус «Руй» из чеснока, шафрана, соли, кайенского перца, сырых желтков и оливкового масла.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Специи с чесноком и солью растереть в ступке, добавить сырые желтки, перемешать, влить порциями оливковое масло.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1387,'Можно добавить лимонный сок, консистенция соуса напоминает майонез.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1388,'Мелкую рыбу, сардины и мойву, очистить и выложить в кастрюлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1388,'Залить водой, жидкость должна полностью покрыть рыбу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1388,'Варить смесь на тихом огне в течение часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1388,'Бульон отцедить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1388,'Мелко нарезать чеснок и репчатый лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1388,'Оливковое масло прогреть в кастрюле с толстым дном, обжарить овощи до мягкости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1388,'Бланшировать помидоры, снять кожуру, мякоть нарезать небольшими кубиками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1388,'Добавить в обжарку, влить белое вино.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1388,'Обжаривать до тех пор, пока жидкость не выпарится.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1388,'Положить лавровый лист, шафран, перец чили.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1388,'Влить воду, довести до кипения.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1388,'Очистить мидии и креветки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1388,'Филе крупной рыбы, например, трески нарезать крупными кусками.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1388,'Продукты выложить в суп, время варки – двадцать минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1389,'Очистить и нарезать чеснок и репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1389,'Мелко нарезать тимьян.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1389,'Прогреть в кастрюле с толстым дном оливковое масло, обжарить овощи до мягкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1389,'Всыпать порошок чили.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1389,'Добавить бланшированные помидоры без кожицы нарезанные кубиками, лавровый лист, чеснок, воду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1389,'Довести смесь до кипения, посолить по вкусу, варить на среднем огне в течение двадцати пяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1389,'Креветки очистить, мелкую рыбу нарезать кусками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1389,'Продукты выложить в кастрюлю, варить около пятнадцати минут, не перемешивать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1389,'Морепродукты вынуть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1389,'Овощи протереть через сито, пюре влить обратно в емкость.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1389,'Добавить масло, довести суп до кипения, вернуть готовые морепродукты, все вместе потушить пять минут. Снять блюдо с огня.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1389,'Приготовить соус из нарезанного чеснока, майонеза, томатной пасты и красного перца.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1390,'Все ингредиенты для теста кроме муки положить в емкость и перемешать. После чего поставить на водяную баню примерно на 5 минут. Снять с огня, всыпать муку и замесить тесто. Оно не должно быть жестким. Готовое тесто разделить на 5 кусков. Тонко раскатать его.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1390,'Процесс выпечки будет немного отличаться от обычных коржей. Нужно перевернуть лист для выпечки дном к верху и смазать его маслом. Это позволит без труда извлечь пропеченные коржи, не повредив их. Пока пекутся коржи нужно приготовить два крема. Для первого крема нужно смешать яйца, муку и сахар. В смесь медленно влить молоко. Поставить на огонь и варить при постоянном помешивании.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1390,'Приготовление второго крема значительно проще. Для этого нужно всего лишь перемешать масло со сгущенным молоком. После этого взбить оба крема в большой емкости вместе. Все готовые коржи промазать кремом. Верхний корж промазывать не нужно. Дать домашнему торту «Нутелла» пропитаться кремом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1391,'Из сибаса, форели и трески приготовить бульон, время варки – сорок минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1391,'Крупно нарезать лук-порей, морковь, корень сельдерея.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1391,'Выложить в кастрюлю, тушить семь минут. Емкость должна быть с толстым дном.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1391,'Влить бульон, варить до готовности, добавить в процессе приготовления, тимьян, шафран и бадьян.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1391,'Выложить крупно нарезанный картофель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1391,'Варить все вместе до мягкости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1391,'Выложить рыбу, нарезанную средними кусками, варить еще десять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1392,'Консервированные помидоры в собственном соку, фенхель, репчатый лук, корень сельдерея, морковь и чеснок нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1392,'Обжарить с петрушкой и семенами фенхеля, растертыми в ступке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1392,'Добавить лавровый лист.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1392,'Тушить все вместе на оливковом масле в толстостенной посуде на тихом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1392,'Накрыть кастрюлю пергаментом. Время варки – до готовности, пока овощи не станут мягкими.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1392,'Пергамент снять, добавить огонь, готовить смесь до изменения цвета.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1392,'Влить рыбный бульон, всыпать шафран, положить очищенные помидоры, куркуму.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1392,'Довести суп до кипения, огонь убавить, потомить в течение часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1392,'Перелить суп в блендер, измельчить в пюре.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1392,'Снова перелить в кастрюлю, прогреть до закипания, выложить леща и хек, нарезанный кусками.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1392,'Прогревать на тихом огне еще пятнадцать минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1392,'Подсушить нарезанную чиабатту, приготовить соус «Айоли».',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1392,'Для приготовления соуса растереть чеснок с солью и сырым желтком, добавить прованское масло. Соус должен напоминать майонез по консистенции.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1393,'Тыкву очистить от семян и кожуры, нарететь на крупной терке. Болгарский перец очистить от семечек и нарезать маленькими кубиками. Охотничьи колбаски нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1393,'В тарелке соединить тыкву, перец и колбаски, вбить 3 яйца и добавить муку. Все тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1393,'Форму для выпечки смазать растительным маслом. Выложить содержимое тарелки. В отдельной тарелке немного взбить оставшиеся яйца и залить ими овощи в форме для выпечки, много раздвинув овощи, чтобы яйца стекали. Отправляем в духовку на 30 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1394,'Телятину нарезать небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1394,'В глубокой сковороде разогреть растительное масло и отправить готовиться телятину. Готовим 4 минуты на сильном огне, затем накрываем крышкой, убавляем огонь до минимума и готовим 15 минут, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1427,'Вбить желток яйца, добавить мед, вымесить тесто, убрать на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1394,'Тыкву очистить от кожицы, нарезать небольшими кубиками, добавить к мясу, влить воду (50 мл), посолить, накрыть крышкой и готовить еще 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1394,'Спустя 15 минут помолоть черный перец, добавить зиру, булгур, влить горячую воду (400 мл), немного раздвинуть булгур, но не перемешивать. Готовим пока не впитается вода.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1394,'Добавить шпинат, перемешать, накрыть крышкой и оставить на 2 минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1395,'Тыкву очистить от семечек и кожуры, нарезать крупными кусочками, выложить в кастрюлю. Залить тыкву водой и добавить соль. Накрыть кастрюлю крышкой и поставить на огонь. Содержимое кастрюли довести до кипения и варить 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1395,'В это время очищенные креветки посыпать морской солью, смесью перцев и добавить оливковое масло (1 ч. л.) - перемешать. Креветки выложить на противень застеленный фольгой. Отправляем в разогретую духовку до 200 градусов на 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1395,'Когда содержимое кастрюли сварится, снимаем с огня и измельчаем все погружным блендером. Разливаем по тарелкам, в каждую порцию добавляем креветки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1395,'Готовим заправку для супа. Оливковое масло смешать с аджикой и перемешать до однородности. Заправить каждую порцию супа этой смесью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1396,'Картофель отварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1396,'Отдельно приготовить бульон из семги.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1396,'Развести шафран подогретой водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1396,'Очистить и натереть чеснок, добавить к картофелю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1396,'Добавить настойку шафрана и майонез, приготовить пюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1396,'Фенхель очистить, удалить сердцевину.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1396,'Мякоть мелко нарубить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1396,'Нарезать кубиками репчатый лук и чеснок, сельдерей.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1396,'Ингредиенты перемешать с фенхелем, прогреть смесь на сковороде с оливковым маслом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1396,'Добавить нарезанные помидоры, соль, лавровый лист, влить рыбный бульон.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1396,'Добавить креветки и мидии, кальмары, нарезанные кольцами, куски белой рыбы. Все вместе варить до готовности.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1397,'Разную рыбу очистить, удалить пленки и жабры, нарезать кусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1397,'Нарубить чеснок и петрушку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1397,'Прогреть масло в кастрюле, выложить овощи и приправы, цедру апельсина, приготовить обжарку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1397,'Добавить рыбную смесь, влить кипяток.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1397,'Варить суп в течение сорока минут на тихом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1397,'Рыбу вынуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1397,'Подсушить в духовом шкафу хлеб.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1397,'Выложить ломтики в тарелки, залить готовым горячим супом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1398,'Положить в кастрюлю морского окуня, влить воду, жидкость должна покрывать продукт на толщину пальца. Варить бульон до готовности, время – один час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1398,'Добавить осьминогов, время варки – еще сорок минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1398,'Нарезать репчатый лук, добавить гвоздику, обжарить до прозрачности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1398,'Крупно нарезать морковь, корень сельдерея.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1398,'Тушить вместе до мягкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1398,'Влить вино, потомить несколько минут, всыпать мелко нарезанный чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1398,'Влить готовый рыбный бульон, выложить осьминогов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1398,'Нарезать кусочками очищенные мидии, креветки, кальмары, мясо тунца. Выложить в суп.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1398,'На сковороде обжарить вяленые томаты и апельсин, фенхель, стебель сельдерея, чеснок, добавить томаты в собственном соку, размятые в пюре.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1398,'Продукты потомить, влить бульон, довести до кипения.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1398,'Добавить готовую рыбу, морепродукты. Все вместе поварить еще две минуты.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Вскипятить воду, замочить шафран в небольшом количестве жидкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Приготовить бульон из рыбных обрезков, моркови, лука, перца-горошка и лаврового листа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Жидкость отцедить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Прогреть в кастрюле оливковое масло, обжарить репчатый лук, фенхель, лук-порей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Нарезать кубиками картофель, добавить в кастрюлю.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Добавить консервированные томаты, давленый чеснок, порезанный тимьян.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Потушить на тихом огне в течение пяти минут. Влить вино.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Поварить до исчезновения алкогольного запаха.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Влить рыбный бульон, добавить настойку шафрана, перец-горошек, соль, томить пять минут. Лучше использовать морскую соль.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Выложить в кастрюлю нарезанную треску, камбалу, лосось и тигровые креветки. Довести до кипения на среднем огне, огонь уменьшить, всыпать петрушку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Тушить до готовности рыбы и морепродуктов под крышкой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Приготовить соус: запечь в духовке красный болгарский перец. Можно сделать это в пакете для запекания.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Вынуть семена, удалить шкурку.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Нарезать крупными кусочками.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Мелко покрошить красный острый перец.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Взбить сырой желток при помощи миксера, влить порциями оливковое масло, лимонный сок.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Превратить в пюре при помощи блендера мякиш размоченной в молоке булки, мякоть перца, чеснок – по вкусу.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Обе массы соединить, взбить до получения соуса.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1399,'Подсушить ломтики багета. Подать суп с багетом и соусом.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1400,'Морскую рыбу очистить и разделать на куски средней величины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1400,'Из обрезков сварить бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1400,'Мелко нарезать фенхель, помидоры, лук репчатый, сельдерей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1400,'Продукты обжарить на сильном огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1400,'Влить томатный соус, потушить. Овощи должны стать полумягкими.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1400,'Влить рыбный бульон, тушить еще двадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1400,'Положить кубик рыбного бульона, куски рыбы, варить все вместе три минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1400,'Готовый буайбес украсить кусочками крабового мяса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Лосось и сибас очистить, удалить кости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Очистить кальмара и креветки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Выложить в кастрюлю головы без жабр и глаз, кости, плавники, хвосты, головы и панцири креветок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Влить два литра кипящей воды, довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'В кипящий бульон выложить очищенную луковицу, морковь, стебли сельдерея, петрушку и черемшу, перец-горошек. Варить все вместе в течение сорока минут, огонь – средний.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Нарезать кубиками лук-шалот, оставшийся сельдерей, чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Прогреть оливковое масло в кастрюле с толстым дном. Выложить овощи, прогревать до мягкости.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Влить томаты в собственном соку, перемешать, тушить две минуты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Добавить процеженный рыбный бульон. Варить все вместе на тихом огне пятнадцать минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Нарезать кусками рыбное филе, кальмара – полукольцами.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Выложить порциями в основной бульон с овощами.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Первый этап – добавление лосося, белая рыба – через две минуты, еще через три минуты – кальмары и креветки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Варить две минуты, огонь погасить.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Поставить суп в тепло на десять или пятнадцать минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Приготовить соус: перемешать кайенский перец с сырым куриным желтком, шафраном, паприкой. Посолить по вкусу.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Взбить массу при помощи кулинарного венчика, ввести порциями оливковое масло. Готовая консистенция должна напоминать майонез.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Нарезать белый багет, побрызгать оливковым маслом, посушить в духовом шкафу при температуре 200 градусов.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1401,'Намазать соусом, украсить базиликом.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1402,'Сварить бульон мисо из комбу, даси и тунца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1402,'Добавить красную мисо-пасту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1402,'Разлить суп в тарелки, добавить нарезанный дайкон, цуккини, китайский салат, репчатый лук, грибы шитаке и шимиджи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1402,'Приправить специями, соусом «Тсую».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1402,'Положить по кусочку лосося и посыпать кинзой и зеленым луком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1403,'У креветок удалить панцири и головы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1403,'Морского петуха, сибас, дорадо, морского скорпиона, баррамунди очистить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1403,'Удалить жабры, глаза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1403,'Варить около сорока минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1403,'Запечь в духовом шкафу крупные креветки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1403,'Отдельно перемешать измельченный твердый сыр с шафраном и сметаной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1403,'Нарезать багет ломтиками, посушить в духовом шкафу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1492,'Тушить под крышкой в течение семи минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1403,'Большие сочные помидоры, корень сельдерея, лук выложить на противень, побрызгать оливковым маслом, запечь в духовке.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1403,'Выложить зелень на большое блюдо.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1403,'Выложить креветки, отварную рыбу разных сортов. Овощи – по краям.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1403,'Полить бальзамическим уксусом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1403,'На стол бульон, хлеб и соус подать в отдельных тарелках и мисочках.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1404,'Разделать несколько видов морских рыб: красную кефаль, камбалу, морской угорь, мерлан, морского петуха.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1404,'Крупно нарезать обычный лук и лук-порей, спассеровать на оливковом масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1404,'Долить вино и воду. Посолить, приправить прованскими травами, шафраном, добавить давленый чеснок и томаты, избавленные от кожуры и семян, перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1404,'Довести до кипения, варить на среднем огне в течение двадцати минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1404,'Добавить в бульон, хвосты, плавники, головы без жабр и глаз.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1404,'Выложить в сотейник слоями рыбу и лангустов, очищенные мидии.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1404,'Влить бульон, еще немного масла, варить пятнадцать минут на сильном огне.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1404,'В конце приготовления добавить муку и сливочное масло.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1404,'Хлеб «Джоко» вымочить в бульоне, обжарить на гриле. Натереть чесноком, подать к супу отдельно.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1405,'Приготовить наваристый бульон из семги, дорада и других морских рыб.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1405,'Прогреть оливковое масло в сотейнике. Обжарить на нем нарезанный лук, тимьян, перец чили, чеснок и розмарин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1405,'Томаты нарезать дольками, потушить с травами до выпаривания жидкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1405,'Стебли вынуть и выбросить, добавить в смесь томат-пасту, потушить в течение пяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1405,'В полученный соус добавить морепродукты, лимонный и лаймовый сок, процеженный рыбный бульон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1405,'Положить базилик и куски рыбы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1405,'Варить до готовности рыбы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1405,'В суп можно добавить мидии и креветки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1406,'Для начала нужно приготовить маринад. Для этого необходимо тщательно смешать сахар, соль, перец. Выдавить на приправы сок половинки лимона, влить масло и снова перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1406,'Заранее подготовленную рыбу нарезать на порционные куски и уложить во вместительную емкость. Насыпать рубленую зелень, и залить маринадом. Оставить так примерно на три часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1406,'Пока рыба маринуется можно приготовить кляр. Для этого взбить желтки с солью и сахаром. Влить молоко. По не многу ввести муку. Белки взбить в пену с парой капель сока лимона. Взбитые белки осторожно смешать с тестом. В последнюю очередь добавить гашеную соду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1406,'Вынуть рыбу из маринада и слегка обвалять в муке. Это позволить держаться тесту на куске.  Жарить сочную и нежную рыбу в кляре на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1407,'Морковь и репчатый лук измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1407,'Нарезать куриную печень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1407,'На жире до прозрачного состояния обжарить лук, добавить тертую морковь, печень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1407,'Влить подсоленную воду с добавлением приправ.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1407,'Тушить все вместе под крышкой около получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1407,'Снять крышку, потушить блюдо до испарения жидкости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1407,'Переложить массу в другую емкость, добавить сливочное масло, превратить в пюре.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1408,'Куриную печень промыть, удалить пленки, мякоть нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1408,'Нарезать репчатый лук кубиками, натереть морковь на мелкой терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1408,'Обжарить лук на масле, добавить морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1408,'При готовности овощей добавить печень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1408,'Все вместе тушить семь или восемь минут, огонь – средний.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1408,'По желанию и необходимости подлить воду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1408,'Добавить соль, сливочное масло, приправы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1408,'Массу перемешать, потушить еще пять или семь минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1408,'Взбить смесь при помощи блендера. Влить коньяк.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1408,'Готовый паштет выложить в небольшую емкость, залить топленым маслом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1409,'Печень промыть в холодной воде, удалить пленки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1409,'Крупно нарезать морковь и лук, обжарить до мягкого состояния на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1409,'Добавить нарезанный кубиками картофель, выложить печень, посолить по вкусу, добавить ароматные травы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1409,'Потушить продукты под крышкой в течение двадцати минут или чуть больше.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1409,'Массу остудить, печеночную массу измельчить блендером или пропустить через мясорубку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1409,'Добавить мягкое сливочное масло, хорошо перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1410,'Измельчить лук, спассеровать на сливочном масле в мультиварке, выставить режим «Выпечка» на пятнадцать минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1410,'Добавить кусочки очищенной от пленок печени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1410,'Все вместе прогревать еще пятнадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1410,'Влить нежирные сливки, добавить соль и мускат, еще немного масла, потушить продукты вместе в течение двенадцати минут без крышки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1410,'Приготовить пюре при помощи блендера. Соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1411,'Печень промыть, удалить жир и протоки, кусочки обжарить со всех сторон на масле до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1411,'В другой сковороде спассеровать крупно нарезанную морковь и лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1411,'При готовности добавить грибы, потушить все вместе, время – от пятнадцати до семнадцати минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1411,'Продукты переложить в блендер, добавить печень, превратить в пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1412,'Куриную печень промыть холодной водой, удалить пленки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1412,'Нарезать морковь, лук, стебель сельдерея.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1412,'Добавить к печени в кастрюлю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1412,'Залить водой, варить все вместе около получаса после закипания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1412,'Продукты откинуть на дуршлаг, дать стечь жидкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1412,'Измельчить овощи и субпродукты до однородного состояния.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1412,'Посолить по вкусу, всыпать ароматные травы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1413,'Раскалить сковороду, растопить сливочное масло, обжарить лук, нарезанный кольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1413,'Вымыть куриную печень, удалить жир, продукт обсушить бумажным полотенцем, нарезать, добавить в обжарку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1413,'Жарить до получения корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1413,'Всыпать соль, мускатный орех и паприку, другие приправы, влить коньяк.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1413,'Потомить ингредиенты на тихом огне в течение пятнадцати минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1413,'Влить жирные сливки, ингредиенты перемешать, снять с огня.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1413,'Массу немного остудить, превратить в пюре.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1414,'Репчатый лук и куриную печень нарезать крупными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1414,'Отварить продукты в подсоленной воде до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1414,'Откинуть на дуршлаг, дать воде стечь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1414,'Продукты пропустить через мясорубку или измельчить при помощи блендера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1414,'Добавить мягкое сливочное масло, тертый сыр. Перец и соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1415,'Варианты соуса или маринада для пропитывания мяса: перемешать оливковое масло со специями, вымочить грудки в рассоле с приправами, пропитать курицу кетчупом с приправами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1415,'Мясо завернуть в фольгу, выложить в смазанную маслом чашу мультиварки, выставить режим «Выпечка» на 35 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1415,'Перевернуть продукт, подержать еще 25 минут. Мясо остудить, затем поставить в холодильник на два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1416,'Поставить вариться очищенный картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1416,'Натереть морковь на средней терке, лук и грибы порезать кубиками, чеснок раздавить прессом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1416,'Грибы обжарить, когда влага из них почти испарится добавить морковку, чеснок, лук, приправить специями, перемешать, закрыть крышкой, жарить 10 минут на малом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1416,'Влить сметану, протушить все вместе еще четверть часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1416,'Слить из кастрюли с картофелем воду, добавить подогретое молоко, желток, подсолить, размять в однородную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1416,'Противень слегка смазать маслом, можно застелить пергаментом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1416,'Выложить на него пюре в форме гнездышек, серединку каждого заполнить грибной начинкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1416,'Поставить картофельные гнезда с шампиньонами в сметанном соусе в заранее разогретую духовку на 20 минут, готовое блюдо оформить на свой вкус.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1427,'Достать хорошо охлажденное тесто, раскатать, вырезать различные фигурки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1504,'Кубики тыквы залить водой, варить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1417,'Хорошо перемешать хлопья с солью, мукой и перцем, добавить масло, порезанное на кубики, влить молоко, вымесить тесто, всыпать в него натертый сыр, хорошо размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1417,'Раскатать в полусантиметровый пласт, нарезать его на полосы по 1 см шириной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1417,'Разложить простые овсяные палочки с сыром на выстланном пергаментом противне, присыпать  при желании кунжутом или крупной солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1417,'Выпекать 10 минут в прогретой до 220 градусов духовке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1418,'Смешать по стакану густой сметаны с манкой, дать постоять час, чтобы образовалась плотная масса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1418,'Добавить масло, взбить миксером.','https:https://st.vkuso.ru/data/cache/thumb/b1/c83266ef30d7ab1_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1418,'Яйца комнатной температуры взбить до побеления с сахаром на максимальной скорости, можно добавить по желанию еще и ванильный сахар.','https:https://st.vkuso.ru/data/cache/thumb/70/13a574c2cab3570_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1418,'Объединить обе смеси, перемешать миксером, влить соду, погашенную соком лимона, добавить просеянную муку, перемешать ложкой.','https:https://st.vkuso.ru/data/cache/thumb/08/66394aafb4daf08_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1418,'Заполнить полученной массой смазанную маслом форму, предварительно положить на дно пекарскую бумагу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1418,'Выпекать манник на сметане от Алии в предварительно прогретой до 180 градусов духовке до золотистого оттенка, остудить, присыпать сахарной пудрой.','https:https://st.vkuso.ru/data/cache/thumb/0d/8ccc81e24ae810d_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1419,'Баклажаны нужно промыть, дать высохнуть.  Разрезать их не тонкие полоски. Перемешать с солью и оставить на несколько минут. Нагреть гриль, или сухую сковородку. Баклажаны вынуть из сока и обмазать небольшим количеством масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1419,'Обжаривать на гриле по 5 минут с каждой стороны. Моцареллу и томаты нужно разрезать небольшими кусочками. Помидоры и сыр положить в одного края баклажана слегка приправить солью и перцем. Завернуть рулетик. Чтобы закусочные рулетики из баклажана не раскрылись можно скрепить их шпажкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1420,'Перемешать творог с размягченным маслом.','https:https://st.vkuso.ru/data/cache/thumb/0e/8b803fd7f022b0e_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1420,'Добавить сахар, влить сметану, всыпать ванильный сахар, взбить блендером в густую однородную массу.','https:https://st.vkuso.ru/data/cache/thumb/1c/ee6f1f31c72ee1c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1420,'Яблоко почистить, порезать тонко на дольки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1420,'Застелить разделочную доску пленкой, с боков оставить по 10 см.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1420,'Печенье обмакнуть на пару секунд в слегка подогретое молоко, выложить на доску в три ряда по 5 штук.','https:https://st.vkuso.ru/data/cache/thumb/3f/59205d3fe3ac53f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1420,'Смазать творожной начинкой, поверх уложить кусочки яблока.','https:https://st.vkuso.ru/data/cache/thumb/b7/36381f6eff2dfb7_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1420,'Выложить второй слой из печенья, тоже смазать творожной массой, а по центру положить банан.','https:https://st.vkuso.ru/data/cache/thumb/45/c38aeae8de3fd45_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1420,'Аккуратно приподнять края пленки, соединить крайние ряды печенья, чтобы получился пирог треугольной формы.','https:https://st.vkuso.ru/data/cache/thumb/fb/2bc48f2493c81fb_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1420,'Поставить творожный пирог с яблоками и бананами без выпечки в холодильник, можно оставить там и на ночь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1420,'Достать десерт, удалить пленку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1420,'Если осталась творожная масса, то можно еще промазать и верх пирога.','https:https://st.vkuso.ru/data/cache/thumb/71/94b0ebed0184f71_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1421,'Включить для разогрева до 180 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1421,'Смешать все яйца с сахаром, всыпать стружку кокоса, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1421,'Из получившейся массы сделать шарики не больше грецкого ореха, разложить на противне с пергаментной бумагой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1421,'Выпекать Кокосовые шарики без муки в духовке полчаса в уже нагретой духовке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1422,'Для приготовления печенья смешать с мукой соду и соль, сахар взбить около 3 минут с маслом до побеления.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1422,'Вбить яйца, добавить экстракт ванили, хорошо взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1422,'Объединить с мучной смесью, вымешать тесто до однородности, разделить его на две части, каждую завернуть в пленку и на час убрать в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1422,'Включить и прогреть духовку до 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1427,'Разложить новогодние имбирные пряники с корицей в глазури на противне, поместить в заранее прогретую до 180 градусов духовку примерно на 15 минут (зависит от толщины печенья).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1422,'Стол припудрить мукой, раскатать одну часть теста толщиной чуть меньше сантиметра, вырезать формочкой снежинки, переложить на застеленный пергаментом противень, поставить в холодильник на четверть часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1422,'Достать противень, поставить в уже прогретую духовку, выпекать Новогоднее печенье «Снежинки» в глазури 10 минут до изменения окраски по краям снежинок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1422,'Вынуть из духовки, дать остыть, все повторить с оставшейся порций теста.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1422,'Для глазури взбить белки с добавлением сока лимона, всыпать сахарную пудру, взбить все вместе на малой скорости блендера до образования массы однородного состава, перемешать ее с красителем, и сразу использовать пока она не затвердела.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1422,'Приготовить королевскую глазурь из смеси сахара и порошка безе, влить воду, взбить на максимальной скорости блендера около 5 минут, смесь должна стать на вид глянцевой, всыпать краситель, перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1422,'Смазать печенье глазурью, дать постоять ночь, переложить в герметичный контейнер, между слоями проложить пергамент.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1423,'Налить в сотейник воду, всыпать сахар, положить мед, нагреть до полного растворения сахара при небольшом нагреве, убрать с плиты, чуть подсолить, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1423,'Просеять муку с содой, объединить с сиропом, перемешать деревянной лопаточкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1423,'Скатать из теста шарик, завернуть в пленку, поместить в холодильник на 3 дня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1423,'Присыпать стол мукой, раскатать тесто примерно в 0,5 см толщиной, вырезать с помощью формочек фигурки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1423,'Переложить их на противень, застланный пекарской бумагой, смазать Новогодних имбирных человечков с медом водой, дать постоять 10 минут, это позволит пряникам не потерять форму при выпечке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1423,'Разогреть духовку до 180 градусов, поставить противень с пряниками на четверть часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1423,'Достать, дать остыть, оформить глазурью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1424,'Картофель вымыть, очистить и натереть на мелкой терке в пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1424,'Выложить картофельную массу на марлю и отжать картофельный сок.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1424,'Через 10 минут слить картофельный сок, на дне миске будет картофельный крахмал.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1424,'В миску с отжатым картофелем добавить картофельный крахмал, соль, перец, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1424,'Разогреть сковороду на среднем огне. Добавить растительное масло.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1424,'Перевернуть картофельный блин, добавить растительное масло и жарить еще 5 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1425,'Просеиваем муку, какао, разрыхлитель и соль.','https://vkuso.ru/data/cache/data/f6/64bc6f47da155f6_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1425,'Растворяем в воде сахар.','https://vkuso.ru/data/cache/data/46/b3b5e24b11d7a46_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1425,'К сухой смеси добавляем воду с сахаром и растительное масло. Замешиваем тесто.','https://vkuso.ru/data/cache/data/f2/0e49658f63ce9f2_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1425,'В тесто вмешиваем вишни и орехи (у меня миндальные лепестки, можно добавить любые, а можно не добавлять вовсе).','https://vkuso.ru/data/cache/data/d7/acccd6c8db256d7_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1425,'Форму выстилаем пергаментом, отправляем в нее тесто и отправляем в духовку на 180 градусов примерно на 35-40 минут.','https://vkuso.ru/data/cache/data/e3/58f1769b3bd16e3_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1425,'Даем пирогу остыть и посыпаем сахарной пудрой, потом разрезаем на квадратики.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1426,'Срезаем с ребер жир и выкладываем на дно горшочка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1426,'Нарезаем лук кольцами и выкладываем вторым слоем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1426,'Нарезаем ребрышки на порционные кусочки и выкладываем третьим слоем, сверху ещё слой лука.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1426,'Добавляем соль, черный молотый перец и хмели-сунели.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1426,'Нарезаем морковь и картофель колечками и выкладываем сверху.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1426,'Добавляем в горшочек порезанные крупно шампиньоны, острый перец, перец капи, чеснок,помидор и капусту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1426,'Добавляем зелень, соль, черный молотый перец, хмели-сунели и зиру.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1426,'Заворачиваем горшочек в фольгу и тушим на углях один час.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1427,'Перемешать сахар с мукой и специями, добавить масло, порезанное на кусочки, порубить все до состояния крошки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1427,'Белки комнатной температуры взбить в пену до устойчивых пиков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1427,'Добавить половину сахарной пудры, продолжить взбивать до гладкого состояния.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1427,'Всыпать вторую часть пудры, перемешать, оставить на 10 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1427,'Заполнить массой пакет, срезать у него уголок, выдавить узоры на пряниках.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1428,'В первую очередь нужно отварить яйца. Пока они варятся можно заняться рыбой. Копченные лосось нужно нарезать не очень тонкие ровные пластины. Формы для кексов нужно застелить пленкой. Она позволит извлечь закуску из формы. На дно каждой формочки нужно выложить по кусочку рыбы. Главное чтобы рыба слегка выступала за края.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1428,'Отварные охлажденные яйца нужно мелко порубить. Можно протереть их через терку. Чеснок мелко измельчить, перья зеленого лука порубить очень мелко. Все ингредиенты тщательно перемешать с тертым сыром и поперчить. Начинку нужно выложить поверх рыбы. Концы рыбы завернуть сверху начинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1428,'Пленкой обернуть закуску. Ничего страшного если она будет немного торчать из формочки. После того как все «кексики» готовы нужно положить сверху гнет. Это позволит начинке утрамбоваться. Форму нужно поставить на холод, примерно на 3-4 часа. Готовая закуска из копченого лосося и сливочного сыра без труда вынимается благодаря пленке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1429,'Рис отвариваем до готовности и промываем его через сито под холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1429,'Колбасу нарежем кубиком и пожарим ее на сковородке с растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1429,'Яйца варим до готовности и нарезаем их кубиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1429,'Огурец я нарезала мелкой соломкой, а помидоры небольшими кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1429,'Зелень мелко нашинкуем. Также мелко нарежем и репчатый лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1429,'Смешиваем все продукты и посолив по вкусу, заправляем майонезом и перемешиваем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1430,'Займёмся бульоном, и отправим вариться филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1430,'Лук крупно измельчить. У болгарского перец обрезать края с двух сторон, отделяем сердцевину, и теперь легко нарезаем его соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1430,'Бульон закипел, снимаем пену, посолить и поперчить',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1430,'В глубокой сковороде обжарить лук, к нему добавить болгарский перец и чеснок обжаривать на огне чуть ниже среднего около 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1430,'Добавить к овощам кукурузу и промытую фасоль. Потушим на медленном огне ещё несколько минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1430,'Из бульона достаем готовое куриное филе и измельчаем его. Возвращаем мясо в суп. Следом за ним отправляем овощи. Дать закипеть и варим минут 5-10, далее вливаем сливки, даём закипеть ещё раз и снимаем с огня.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1431,'Выдавливаем сок из лимонов и апельсина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1431,'Варим манку на воде с добавлением лимонного сока и сахара.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1431,'Даем манке остыть до теплого состояния и взбиваем миксером. Масса должна увеличиться в два раза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1431,'Добавляем апельсиновый сок и продолжаем взбивать, масса должна еще увеличиться в объеме.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1431,'Раскладываем по креманкам и отправляем в холодильник на 1 час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1431,'Украшаем цедрой или шоколадом, по желанию.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1432,'Нарезать яйца небольшим кубиком',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1432,'Отварное куриное филе так же нарезать небольшим кубиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1432,'Далее измельчаем листья пекинской капусты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1432,'Распаренный чернослив режем соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1432,'Твердый сыр натереть на крупной тёрке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1432,'В миску добавить кукурузу и перемешать. Добавить гранулированный чеснок. Несколько зубчиков чеснока, сметану или майонез и перемешать салат.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1433,'Подготовить все ингредиенты. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1433,'Сделать маринад, смешав все остальные ингредиенты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1445,'Нагрев уменьшить, продукт потушить еще двенадцать или пятнадцать минут под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1433,'Нанести маринад на курицу и поставить курицу в холодильник минимум на 1,5 часа.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1433,'Можно запекать в духовке, жарить на сковороде, на мангале или на гриле.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1434,'Картофель средних размеров отварить в соленой воде. Очистить и протереть через терку. Грибы промыть почистить и мелко порубить. Репчатый лук нашинковать мелкими кубиками. Обжарить грибочки с луком на растительном масле. Перемешать с картошкой. Добавить в массу яйца, соль и муку. Тщательно замесить вязкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1434,'В большой кастрюле вскипятить воду, куда положить лавровый лист и соль. Руки слегка намочить и сформировать шарики среднего размера. Каждый шар осторожно опустить в кипящую воду. В процессе варки нужно аккуратно двигать их ложкой, чтобы не прилипали ко дну. После всплытия шариков варить 4 минуты. Кнедлики из картофеля с шампиньонами готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1435,'Прогреть духовку до 190 градусов, выстлать противень пергаментом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1435,'Сахар взбить с маслом, всыпать ванильный сахар, вбить яйцо, всыпать муку, вымесить тесто, раскатать его в пласт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1435,'Формочками вырезать фигурки, переложить их на подготовленный противень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1435,'Выпекать новогодние ванильные пряники с глазурью минут 10 до золотистости, остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1435,'В предварительно взбитый до устойчивой пены белок всыпать половину сахарной пудры, взбить до гладкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1435,'Добавить вторую половину пудры, взбить, можно добавить краситель, оставить на 10 минут, украсить готовые пряники.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1436,'В глубокую миску просеять муку, вбить яичный белок, всыпать сахар, положить кубики масла, влить сок лимона, вымесить однородное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1436,'Отправить его на полчаса в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1436,'Раскатать тесто, вырезать фигурки, разложить их на противень, выстланный пергаментом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1436,'Вырезать трубочкой для коктейля на каждой отверстия для ленточек, чтобы потом повесить на елку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1436,'Выпекать новогоднее лимонное печенье на елку в прогретой до 180 градусов духовке 5 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1436,'Охлажденное печенье смазать хорошо взбитым желтком яйца, отверстия заполнить измельченными леденцами, вернуть в духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1436,'После ее расплавления достать печенье, дать остыть, оформить глазурью, вставить в отверстия ленточки и украсить елку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1437,'Хорошо промыть рис, нарезать кабачок и лук на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1437,'Прогреть мультиварку, налить масло, установить режим «Жарка» на четверть часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1437,'Обжарить лук в прогретом масле.','https:https://st.vkuso.ru/data/cache/thumb/56/bb0ede588fc8556_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1437,'Добавить специи.','https:https://st.vkuso.ru/data/cache/thumb/da/13efe602a30b3da_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1437,'Добавить помидоры, порезанные на дольки, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/f6/b9ac1d724bc2ff6_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1437,'Добавить кабачки, обжарить с открытой крышкой.','https:https://st.vkuso.ru/data/cache/thumb/dd/1d00a2e2f2f57dd_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1437,'После сигнала поставить режим «рис», время будет задано автоматически.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1437,'Всыпать рис, положить масло, подсолить.','https:https://st.vkuso.ru/data/cache/thumb/eb/5f23ad04b0966eb_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1437,'Содержимое мультиварки перемешать, влить полстакана кипятка, крышку закрыть.','https:https://st.vkuso.ru/data/cache/thumb/74/b6c8a661ed50b74_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1437,'После сигнала добавить порубленную петрушку, перемешать, сразу подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/d4/20374ce6f22a6d4_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1438,'С персиков снять кожицу, порезать на кусочки, положить в кастрюлю, засыпать сахаром, добавить сок лимона, перемешать, дать смеси закипеть, помешивая варить  минуты 4 на малом огне, убрать с плиты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1438,'Прогреть духовой шкаф до 190 градусов, форму смазать маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1438,'Перемешать муку, сахар, соль, разрыхлитель, влить молоко, перемешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1438,'Заполнить тестом подготовленную форму, сверху разложить персики, выпекать персиково-лимонный коблер с мороженым 35 минут до золотистости',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1438,'Дать остыть, подавать с мороженым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1439,'Кусок мяса порезать на куски толщиной по 1 см, подсолить, поперчить, разложить на разделочной доске, прикрыть полиэтиленовым пакетом, хорошо отбить.','https:https://st.vkuso.ru/data/cache/thumb/05/fac922510fed505_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1439,'Обмакнуть каждый кусочек в муку, потом в яйцо и затем в измельченные сухари.','https:https://st.vkuso.ru/data/cache/thumb/05/da9d036ea133b05_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1439,'Обжарить классический немецкий шницель во фритюре, либо на сковороде в смальце с обеих сторон около 8 минут.','https:https://st.vkuso.ru/data/cache/thumb/23/4b3832d18bffc23_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1440,'Засыпать в кастрюлю сахар с бутончиками гвоздики и корицей. Добавить ломтики одного апельсина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1440,'Залить вином, соком, нагреть практически до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1440,'Процедить Рождественский белый глинтвейн с корицей, разлить по стаканам, украсить ломтиками апельсина и палочками корицы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1441,'Из ингредиентов выпечь безе с орехами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1441,'Растереть с добавлением водки желтки с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1441,'Охлажденное масло порубить с мукой, перемешанной с разрыхлителем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1441,'Соединить с желтками, вымесить мягкое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1441,'Разделить на две части, каждую раскатать и выпечь 10 минут при температуре 200 градусов, дать коржам остыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1441,'Для крема закипятить половину молока.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1441,'Вторую половину взбить с мукой, перемешать с прогретым молоком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1441,'Прогреть перемешивания до кипения до образования прозрачного крема.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1441,'Убрать с плиты, взбить венчиком до исчезновения комочков.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1441,'Добавить белый шоколад, перелить его в мисочку, прикрыть пленкой, дать хорошо остыть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1441,'Взбить сахарную пудру с мягким маслом и ванильным сахаром, влить ром, перемешать с остывшим заварным кремом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1441,'Собрать киевский торт «Акилежна» с грецкими орехами в нижеследующем порядке.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1441,'Промазать песочный корж кремом, поверх выложить безе, смазать опять кремом, прикрыть вторым песочным коржом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1441,'Бока торта обмазать кремом, присыпать крошкой от песочных коржей и стружкой миндаля.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1442,'Шоколад натереть на терке и растопить. Для этого емкость с шоколадом поставить на водяную баню. Предварительно измельченные мюсли перемешать с шоколадом. Смесь вылить на форму, которая застелена пекарской бумагой. Форму с шоколадом убрать на холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1442,'Для крема нужно желатин растворить в теплой воде. В это время взбить творог с йогуртом и сахарной пудрой. Добавить сок лимона и тертую цедру. Сливки хорошо взбить. Важно чтобы они держали форму и не оседали.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1442,'После чего аккуратно перемешать с творожно-йогуртовым кремом. Всю смесь перемешать с желатином. Достать форму из холодильника и залить шоколад с мюсли готовым кремом. Снова поставить на холод на три часа. Воздушный торт из мюсли творожным кремом готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1443,'Куриное филе нарезать кубиками и обжарить на сковороде около 10 минут, посолить и поперчить по вкусу.','https://vkuso.ru/data/cache/data/25/e7a229b447d3125_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1443,'Далее нарезать грибы и лук. Выложить обжареную курицу в отдельную посуду. Далее 5 минут обжарить лук, добавить грибы и жарить 10 минут с луком.','https://vkuso.ru/data/cache/data/fb/5bfb721dcb5a4fb_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1443,'Посолить и поперчить по вкусу, высыпать муку и перемешать. Добавить сливки и обжареное куриное филе, и жарить 5 минут.','https://vkuso.ru/data/cache/data/d6/f28e76a01869ad6_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1443,'Далее поместить жульен в емкость для запекания и посыпать тертым сыром. Отправить в духовку на 20 минут. Жульен необходимо подавать на стол в горячем виде, приятного аппетита!','https://vkuso.ru/data/cache/data/bc/20f2919e40719bc_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1444,'Бананы размять вилкой в пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1444,'Добавить яйца и щепотку соли, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1444,'Добавить муку и перемешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1444,'Сковороду разогреть на слабом огне и смазать ее слегка растительным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1444,'С помощью половника зачерпнуть тесто и вылить на сковороду. Распределить тесто по сковороде и жарить 1 минуту.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1444,'Перевернуть панкейк и жарить еще 1 минуту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1445,'Куриную печень нарезать кусками, обжарить со всех сторон на жире на сильном огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1553,'Начинку выложить в гнезда, посыпать стружкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1445,'Готовую печень поперчить, посолить по вкусу, добавить любимые специи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1445,'Влить сливки, потушить несколько минут, обжарка должна загустеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1445,'Добавить мягкое сливочное масло, ингредиенты превратить в паштет блендером.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1446,'Подготовим орехи, слегка измельчить их ножом. У меня грецкие орехи и ядро абрикосовых косточек.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1446,'В большую миску отправляем пюре. Добавляем яйца, сахар, растительное масло, апельсиновый сок, цедру и хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1446,'В просеянную муку добавить разрыхлитель, соду, корицу, гвоздику, мускатный орех, соль, все перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1446,'Смешать сухие и жидкие ингредиенты, перемешать. По необходимости добавить немного муки. Тесто не должно быть жидким, но и не густым. Долго мешать не нужно, а то хлеб станет забитым и плотным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1446,'Добавить орехи и сухофрукты, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1446,'В форму смазанную маслом вылить тесто, разровнять и отправляем в духовку разогретую на 180-200° на 55-60 минут. Ориентируйтесь на свою духовку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1447,'В миску перекладываем 2 пачки творога добавляем сахар, соль и яйцо куриное. Все перемешиваем. Далее добавляем какао, перемешиваем. Добавляем постепенно муку. И замешиваем тесто. Тесто должно получится мягким и эластичным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1447,'Делим тесто на 2 части, одну из них раскатываем в колбаску. Потом нарезаем на равные части. И после этого катаем в шарики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1447,'В кипящую воду добавляем совершено немножко растительное масло, чтобы ленивые вареники не прилипли ко дну. Как только вареники взойдут варим еще 1 минуту и перекладываем их на тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1448,'Свиную печень очистить от пленок и протоков, промыть холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1448,'Влить свежую воду, довести до кипения, добавить лавровый лист. Варить около получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1448,'Нарезать репчатый лук, обжарить на сковороде, добавить печень, жарить пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1448,'Превратить ингредиенты в пюре при помощи комбайна или обычной мясорубки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1448,'Сливочное масло оттаять, взбить в пену, перемешать с основной массой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1448,'Паштет выложить в форму, полить небольшой порцией теплого сливочного масла, поставить в холод для застывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1449,'Печень промыть, нарезать кусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1449,'Нарезать соломкой морковь, репчатый лук – кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1449,'Нарезать сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1449,'Все продукты переложить в чашу мультиварки, добавить лавровый лист, подходящие специи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1449,'Перемешать. Выставить режим «Выпечка» на сорок минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1449,'По окончании отведенного времени перемолоть продукты в блендере.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1450,'Прогреть сковороду, обжарить шпик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1450,'Добавить свиную печень, тушить пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1450,'Нарезать репчатый лук и морковь, добавить к основным продуктам, влить немного воды, положить специи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1450,'Тушить все вместе двадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1450,'Массу остудить, пропустить через мясорубку или измельчить при помощи блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1450,'Добавить мягкое сливочное масло, перемешать, остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1451,'Печень нарезать кусочками, обжарить на сковороде до корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1451,'Огонь уменьшить, тушить до готовности под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1451,'Добавить специи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1451,'Измельчить морковь и лук, приготовить обжарку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1451,'Добавить чеснок по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1451,'Все ингредиенты перемешать, превратить в пюре при помощи блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1451,'Добавить мягкое сливочное масло, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1452,'Бублики нужно предварительно замочить в теплом молоке. Главное не упустить момент. Они не должны полностью развалиться. Филе куриной грудки, репчатый лук и черствый хлеб пропустить через мясорубку. Добавить специи, яйцо и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1486,'Противень застелить бумагой для выпекания, выложить тесто ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1452,'Бублики вынуть из молока и осторожно выложить на противень.  Внутрь каждого положить немного фарша. Поставить в духовку. Через некоторое время вынуть блюдо и посыпать его тертым сыром твердых сортов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1452,'Сверху полить майонезом или соусом, после чего посыпать рубленой зеленью и поставить бублики с куриным фаршем под сыром снова в духовой шкаф до полного приготовления.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1453,'Печень нарезать кусочками, обжарить на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1453,'Добавить нарезанный репчатый лук, все вместе жарить две минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1453,'Всыпать специи, тушить до готовности под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1453,'Массу остудить, пропустить через мясорубку или перемолоть при помощи комбайна.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1453,'Перемешать готовую массу с мягким сливочным маслом, поставить на некоторое время в холод.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1454,'Печень промыть, дать постоять в воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1454,'Обжарить на растительном масле рубленый репчатый лук, добавить печень, довести продукты до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1454,'Специи, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1454,'Перебить ингредиенты в блендере, добавить тертый сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1454,'Массу перемешать и убрать в холод.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1455,'Форму для подачи салата смазываем майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1455,'Все ингредиенты измельчаем и выкладываем слои в следующем порядке:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1455,'Украшаем салат: я сделала елочки из огурцов и выложила полукольца огурцов по периметру салата.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1455,'Салат получается сочным и свежим на вкус! Всех с Наступающим!)',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1456,'Капусту выбирайте по своему вкусу, я в этом рецепте буду использовать савойскую капусту. Мелко нашинкуем капусту в миску и немного посолим ее. Для того чтобы капуста стала мягкой я ее немного мну руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1456,'Свежий огурец и сырую морковь я натираю на терке для корейской моркови.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1456,'Предварительно отвариваем куриные яйца. Чистим остывшие яйца и натираем их на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1456,'Свежий укроп я буду мелко шинковать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1456,'В миске или салатнике смешиваем все приготовленные продукты. Солим салат по своему вкусу и заправив его майонезом перемешиваем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1457,'Печень вымыть, подержать в воде, довести до кипения с добавлением лаврового листа. Варить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1457,'Приготовить обжарку из нарезанной моркови и лука, чеснока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1457,'Готовые овощи перемешать с печенью, пропустить через мясорубку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1457,'Добавить в паштет мягкое сливочное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1457,'Перемешать и поставить в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1458,'Репчатый лук нарезать, обжарить на сковороде, добавить грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1458,'Потушить все вместе до полуготовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1458,'Добавить чеснок и нарезанную печень, прогревать до полной готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1458,'Всыпать любимые приправы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1458,'Приготовить однородную массу при помощи комбайна или мясорубки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1458,'Добавить мягкое сливочное масло, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1459,'Нарезать печень, морковь и лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1459,'Выложить в небольшую кастрюлю. Добавить перец-горошек, лавровый лист.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1459,'Влить холодную воду, варить в течение часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1459,'За пять минут до готовности посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1459,'Воду слить, продукты вынуть, перемолоть при помощи мясорубки с чесноком и салом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1459,'Добавить сливочное масло. Охладить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1460,'Выложить в чашу мультиварки сливочное масло, кубики репчатого лука, жарить пятнадцать минут без крышки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1460,'Далее режим «Выпечка», сорок минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1460,'Печень промыть, нарезать, добавить в чашу, все вместе готовить пятнадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1460,'Вылить сливки и специи, говорить ещё 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1460,'Продукты измельчить с помощью комбайна, перемешать с маслом, поставить в холод.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1461,'Чернослив промыть, обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1461,'Говяжью печень вымыть, удалить пленки, нарезать, обжарить пять минут на оливковом масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1461,'Добавить сливочное масло, сливки, потушить под крышкой пятнадцать минут, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1461,'Перемолоть при помощи комбайна печень с черносливом, поставить в холод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1462,'Печень нарезать кусочками, отварить в течение двадцати пяти минут. Продукт должен стать мягким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1462,'Добавить в воду луковицу и лавровый лист.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1462,'Потушить на сковороде рубленый репчатый лук с оливковым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1462,'Подлить немного бульона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1462,'Отварить морковь в мультиварке или в кастрюле на плите.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1462,'Приготовить пюре при помощи блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1462,'Влить оливковое и положить сливочное масло.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1462,'При необходимости подлить бульон от варки печени, если паштет получился слишком густым.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1463,'Печень залить водой, добавить пищевую соду, оставить продукт на два часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1463,'Нарезать сало, обжарить на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1463,'Натереть морковь, нарезать репчатый лук, добавить к салу. Жарить пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1463,'Выложить печень, жарить еще пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1463,'Всыпать специи, тушить под крышкой до полной готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1463,'Обжарку остудить, перемолоть в блендере.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1463,'Добавить мягкое сливочное масло, перемешать и охладить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1464,'Приготовить говяжий паштет по любому рецепту, например, с маслом или с сухофруктами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1464,'Расстелить на столе пищевую пленку, завернуть массу в виде колбасы, края завязать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1464,'Поставить закуску на ночь в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1464,'Пленку убрать, рулет порезать порциями, посыпать рубленым зеленым луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1465,'Печень нарезать кусками, залить водой на два часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1465,'Отварить в кастрюле морковь, добавить печень, не солить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1465,'Репчатый лук нарезать и обжарить на масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1465,'Продукты пропустить через мясорубку два раза или перемолоть в блендере.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1465,'Добавить сливочное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1465,'Перемешать, перец молотый и соль – по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1465,'Поставить в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1466,'Измельчить любые грибы и печень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1466,'Грибы отварить в течение получаса или чуть меньше, печень замочить в холодной воде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1466,'Грибы жарить до тех пор, пока жидкость испарится.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1466,'Добавить печень, нарезанный лук и тертую морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1466,'Массу посолить и поперчить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1466,'Добавить рубленую зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1466,'Продукты потушить на сковороде до готовности, приготовить пюре при помощи мясорубки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1466,'Добавить сливочное масло, вымешать и охладить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1467,'Для приготовления соуса нужно перемешать в равных пропорциях сметану и майонез. Натереть желток отварного яйца.  Добавить чуть горчицы.  Соленые огурцы протереть через мелкую терку. Солить соус «Тартар» не нужно, так как огурцы уже содержат нужное количество соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1468,'Подготовить все ингредиенты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1468,'Запарить желатин в горячей воде.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1468,'В форму залить творожную массу и мандарины.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1469,'Перемешать кефир с сырым куриным яйцом, солью и сахарным песком, любым алкоголем. Можно использовать бренди, коньяк, ром, водку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1469,'Порциями всыпать просеянную муку, смешанную с пищевой содой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1469,'Смесь перемешать до гладкости, в ней не должно быть комочков, влить кипящую воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1469,'В самом конце добавить растительное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1469,'Дать тесту постоять десять минут при комнатной температуре, должна набухнуть клейковина.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1469,'Выпечь тонкие блинчики.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1470,'Лимоны хорошо вымыть и снять цедру без белой части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1470,'Перетереть с сахарным песком так, чтобы он стал желтым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1470,'Отжать сок из мякоти.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1492,'Подлить немного горячей воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1470,'Перемешать все вместе: сахар с цедрой, теплую кипяченую воду, лимонный сок, процедить через сито.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1470,'Охладить в холодильнике или добавить кубики льда.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1471,'Томаты хорошо вымыть, нарезать, долить воду, потушить на тихом огне до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1471,'Массу перемолоть с помощью блендера, протереть через сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1471,'Варить от 15 до 20 минут, разлить в стерильные банки и закатать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1472,'Клубни нарезать дольками, переложить в форму для запекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1472,'Приготовить заливку из оливкового масла, лимонного сока, нарезанного мелкими кубиками чеснока и орегано.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1472,'Залить картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1472,'Молотый перец – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1472,'Время запекания – от 40 до 50 минут, температура – 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1473,'Подмороженное свиное мясо очень тонко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1473,'В кастрюле обжарить чеснок, паприку, молотый черный перец, острый перец с растительным маслом, солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1473,'Влить в смесь пассату из томатов и пиво.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1473,'Положить лавровый лист, довести до кипения, добавить мясо, соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1473,'Время тушения – от 25 до 30 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1474,'В миске соединить сливочное масло комнатной температуры, сахар (90 гр) и корицу (6 гр). Взбить венчиком. Вбить яйцо и снова взбить. Всыпать разрыхлитель и муку, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1474,'В отдельной тарелке смешать сахар (20 гр) и корицу (2/3 ч. л.). Противень застелить бумагой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1474,'Отщипнуть кусочек теста, скатать в шар (размером с грецкий орех), обвалять в сахарно-коричной смеси и выложить на противень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1474,'Выпекаем печенье в разогретой духовке до температуры 200 градусов 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1475,'В миску влить кефир, разбить яйца и добавить соль – перемешать до однородности. Добавить разрыхлитель и муку, снова перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1475,'Ветчину и сыр нарезать маленькими кубиками. Отправить в тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1475,'В форму для выпечки (я брала силиконовую форму для прямоугольного кекса) выложить половину теста. Распределить тесто по форме сделав небольшое углубление в середине.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1475,'Петрушку мелко нарезать. В углубление выложить петрушку и выложить оставшееся тесто.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1476,'Куриную грудку прокрутить через мясорубку, укроп мелко нарезать. Соединить куриную грудку и укроп, посолить, поперчить, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1476,'Сыр нарезать крупными кубиками. Кукурузные хлебцы измельчить в крошку. Яйцо взбить в пиале. В отдельную пиалу налить воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1476,'Руки смачиваем водой, берем немного куриного фарша, делаем из него лепешку, в середину кладем кубик сыра. Лепешку из курицы слепить в шарик, обмакнуть в яичко, а затем обвалять в измельченных хлебцах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1476,'Противень застелить фольгой, выложить куриные шарики. Разогреваем духовку до 200 градусов и затем отправить противень с шариками на 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1477,'Поставить на плиту широкую и глубокую кастрюлю с водой, довести до активного кипения. Пока вода греется нужно хорошо взбить яйца. Посолить по вкусу. Добавить к ним молоко и тоже взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1477,'Вложить 2 пакета друг в друга, вылить смесь для омлета в пакеты и хорошо завязать. Опустить пакет с омлетом в кипящую воду, закрыть крышкой и варить 20 минут. Вкусный омлет в кастрюле готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1478,'Свежий огурец и крабовые палочки мелко нарезаем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1478,'Вареные куриные яйца тоже мелко нарезаем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1478,'Вареный картофель и плавленные сырки я натираю на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1478,'Красный репчатый лук тонко нарезаем. Зелень укропа мелко нашинкуем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1478,'Отправляем все продукты в салатник. Заправляем салат майонезом и солим по своему вкусу. Перемешаем и наш салат готов. Приятного Вам аппетита.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1479,'Нарезать лук и замариновать в уксусе на 5 минут. Мелко нарезать заранее отвариную говядину. Смазать блюдо или салатник майонезом. Первым слоем уложить половину говядины.','https://vkuso.ru/data/cache/data/ca/f5619f1e2edc2ca_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1486,'Все перемешать, всыпать изюм или бруснику, оставить готовое тесто на столе на 10 – 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1479,'Следующим слоем маринованый лук. Затем два натертых яйца, соль и смазать майонезом. Далее немного тертого сыра.','https://vkuso.ru/data/cache/data/d3/ecc2db0b19371d3_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1479,'Повторяем слои: говядина, лук, яйца, соль, майонез и в завершении обильно посыпать тертым сыром. Приятного аппетита!','https://vkuso.ru/data/cache/data/0b/916d39e9cb3ab0b_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1480,'Взбить сахарный песок с мягким сливочным маслом, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1480,'Вбить сырые куриные яйца, добавить натуральный йогурт и ванилин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1480,'Отдельно размять вилкой мякоть бананов, добавить в основную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1480,'Всыпать муку и кукурузный крахмал, какао-порошок, пищевую соду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1480,'Ингредиенты перемешать, перелить в форму для выпекания, время приготовления в духовом шкафу – от 50 до 55 минут, температура – 175 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1480,'Остывающий кекс полить глазурью, приготовленной из какао-порошка, молока, сахарной пудры, сливочного масла и бренди.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1480,'По желанию можно добавить ванилин.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1481,'Белки отделить от желтков, первые взбить со щепоткой соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1481,'В сахарную пудру добавить сливочное масло, ванилин, все вместе взбить, всыпать муку, тесто взбить еще раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1481,'Аккуратно ввести взбитые белки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1481,'Выпечь вафли.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1482,'Блендером пюрировать сырок, яйца и майонез.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1482,'Вторую половину крабовых палочек натереть на мелкой тёрке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1482,'Займёмся бисквитом. Со шпината отжать сок. Добавить три желтка и перебить блендером. Добавить щепотку соли и муку. Хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1482,'В отдельной миске взбить белки до устойчивых пиков. Постепенно в 2-3 этапа вводим белки в шпинатную массу, и аккуратно перемешиваем лопаткой или ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1482,'На противень застеленный пергаментом распределяем равномерно тесто, в прямоугольник приблизительно 20 на 30 см. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1482,'Готовый бисквит достаем с духовки, даём остыть и снимаем с бумаги. Переворачиваем и начинаем собирать рулет.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1483,'Пирог очень простой. Смешайте все ингредиенты. Тщательно перемешайте. Консистенция теста должна быть густой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1483,'Залить тесто в форму для выпечки. Запечь в духовке при 180 градусов.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1483,'Сверху присыпать сахарной пудрой. Подавать к столу.','https://vkuso.ru/data/cache/data/99/8abc458674b8d99_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1484,'Прогреть молоко, добавить воду, соль, сахарный песок, сухие дрожжи, муку и растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1484,'Замесить тесто, оно должно быть гладким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1484,'Выложить в смазанную маслом емкость и оставить на час для набухания клейковины и подъема.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1484,'Готовое тесто поделить на части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1484,'Развести в воде солод, обжарить кунжут на сковороде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1484,'Сформовать бублики из раскатанных полосок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1484,'Изделия обмакнуть в воду с солодом и в обжаренные семечки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1484,'Оставить для подъема на 15 или 20 минут, затем выпечь при температуре 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1485,'Просеять муку, всыпать сухие дрожжи, ванильный и обычный сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1485,'Отдельно молоко перемешать с яйцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1485,'Смесь влить в муку, добавить соль и мягкое сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1485,'Тесто вымесить до гладкости в течение десяти минут, оставить на час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1485,'Раскатать в пласт средней толщины, вырезать пончики, дать им подойти в течение 10 – 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1485,'Обжарить изделия во фритюре при температуре от 160 до 170 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1486,'Соединить муку с овсяными хлопьями, разрыхлителем, ванильным сахаром, корицей и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1486,'В другой емкости соединить жидкие ингредиенты: сырое яйцо, молоко, мёд, мягкое сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1486,'Время приготовления – от 13 до 15 минут, температура – от 180 до 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1487,'В большую кастрюлю налить немного растительного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1487,'Куриную тушку вымыть, нарезать кусками, жарить несколько минут под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1487,'Влить немного воды и потушить десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1487,'Нарезать на четвертинки очищенную морковь, измельчить чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1487,'Молодую капусту нарезать крупными кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1487,'Сложить овощи в большую миску, залить холодной водой на десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1487,'Обжаренное мясо посолить и поперчить, добавить овощи, соль, молотый черный и душистый перец-горошек, лавровый лист, «Вегетту».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1487,'Залить ингредиенты горячей водой, не доверху, придавить продукты тарелкой, тушить в течение часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1488,'Говядину разрезать на куски толщиной 10–12 мм, чтобы она равномерно и быстро прожаривалась. Мясо нужно разрезать поперек волокон, а не вдоль. Мясо тогда не превратится в «жвачку» при готовке. Обрезки мяса можно оставить и приготовить из них фарш.  Порезать лук и чеснок для соуса заранее. Отмерить необходимое количество вина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1488,'Поставить сковородку на плиту, положить на ее дно оливковое и сливочное масло. Разогреть хорошо масло, определить это можно по тому, что сливочное масло перестанет пузыриться. Выложить мясо на сковородку, не трогая обжарить 1 минуту. Посолить и поперчить прямо на сковороде и потом перевернуть мясо. Посолить и поперчить другую сторону говядины. Жарить еще 1 минуту с другой стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1488,'Проверить готовность мяса: нажать на него пальцем. Если мясо мягкое – значит, сырое. Если упругое – значит, уже готово. А если потеряло упругость, то значит, мясо сильно прожарилось. Готовый бифштекс снять со сковороды и положить в тарелку. Сверху прикрыть другой тарелкой, чтобы мясо осталось теплым, пока готовится соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1488,'Соус готовить на той же сковородке, где готовилось мясо. Обжарить лук и чеснок, помешивая лопаткой. Влить бульон и вино. Перемешать и на большом огне уварить, пока соус не загустеет. Его останется совсем немного, примерно по одной ложке на каждый кусок говядины. Снять сковородку с соусом, кинуть сливочное масло в соус и перемешать. Полить сочный бифштекс из говядины соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1489,'Ветчину режем очень мелко, натираем на терке сыр и яйца. Добавляем майонез и тщательно перемешиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1489,'У маринованных грибов отделяем шляпки от ножек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1489,'Огурец нарезаем шайбочками толщиной примерно 1 см.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1489,'Формируем закуску: на шайбочки из огурцов выкладываем сформированные шарики из салатной массы и придаем им конусообразную форму, а сверху одеваем шляпку от маринованных грибов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1489,'Украсить закуску можно зеленью или салатными листьями.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1490,'Для приготовления рыбы понадобится маринад: добавить в воду соль и сахар, молотый и перец-горошек, лавровый лист, гвоздику.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1490,'Смесь вскипятить, остудить до комнатной температуры, добавить уксус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1490,'Рыбу очистить, промыть, залить готовым маринадом, поставить в холодильник на сутки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1490,'Жидкость слить, добавить свежий репчатый лук, нарезанный кольцами, подлить растительное масло, дать постоять в течение нескольких часов для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1491,'Подогреть молоко, добавить сахарный песок, соль, ванилин, половину сырого яйца и дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1491,'Всыпать просеянную муку, замесить тесто, в конце приготовления влить растопленное сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1491,'Массу оставить на час или полтора на расстойку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1491,'Сформовать булочки, каждый пласт смазывать маслом, посыпать сахарным песком, раскатывать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1491,'Операцию повторить несколько раз, чтобы получилось слоеное тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1491,'Сформованные изделия оставить еще на полчаса, смазать оставшимся яйцом, посыпать сахаром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1491,'Время выпекания – от 25 минут до получаса, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1492,'На сковороду налить оливковое масло, прогреть, обжарить репчатый лук, нарезанный кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1492,'Добавить полоски красного перца, смесь замороженных овощей: зеленого горошка, моркови, кукурузы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1492,'Добавить черный молотый перец, немного имбиря, карри, паприку, соль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1492,'Всыпать кус-кус, залить горячей водой, тушить под крышкой еще пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1493,'С помощью венчика взбить сырые куриные яйца с солью и сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1493,'Всыпать пищевую соду и овсяную муку, влить молоко, перемешать, добавить остатки молока и растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1493,'Оставить тесто для набухания на полчаса при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1493,'Выпечь тонкие блинчики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1494,'Мягкое сливочное масло взбить с сахарным песком, добавить сырые яйца по одному.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1494,'Всыпать ванилин из пакетика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1494,'В муку для тортов всыпать разрыхлитель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1494,'Треть смеси всыпать в яичную массу, перемешать, влить кефир.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1494,'Добавить оставшуюся муку с разрыхлителем, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1494,'Отдельно перемешать какао-порошок с кипящей водой, должна получиться густая паста.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1494,'Добавить ее в треть готовой массы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1494,'Выложить в форму, чередуя белое и шоколадное тесто.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1494,'Провести ножом или зубочисткой, чтобы получились разводы. Время выпекания – около часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1495,'Для начала приготовим соус. Сыр натираем на мелкой терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1495,'В глубокую тарелку добавляем 3 ст.л сметаны 1 ст.л майонеза, соль, перец по вкусу, выдавливаем чеснок через чеснокодавилку, и добавляем подготовленный сыр. Все хорошо перемешиваем. Убираем в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1495,'Подготавливаем ингредиенты для пиццы. Сыр натираем на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1495,'Колбасу нарезаем тонкими колечками .',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1495,'Помидор точно так же, как и колбасу. Чем тоньше тем лучше.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1495,'Красный болгарский перец нарезаем соломкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1495,'Лук зеленый мелко нарезаем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1495,'Лаваш нарезаем по размеру противня. У меня получилось 3 слоя.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1495,'Приготовление самой пиццы. На первый слой лаваша намазываем соусом, сверху укладываем второй слой, его посыпаем сыром, а так же слегка можно смазать соусом. Укладываем третий слой и снова смазываем соусом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1495,'Укладываем колбасу. Укладываем помидор. Укладываем красный болгарский перец. Посыпаем сыром. Посыпаем луком зеленым.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1495,'Отправляем в духовку при 180°С на 15 минут, до тех пор пока лаваш не подсушится, а сыр не подплавиться.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1496,'Картофель и морковь залить холодной водой, поставить на огонь, довести до кипения и варить 25 мин (готовность проверить ножом). Вытащить картофель и морковь из воды и дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1496,'Зеленый горошек залить горячей кипяченой водой и варить на среднем огне 10 мин, затем слить воду и дать горошку остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1496,'Картофель и морковь очистить от кожуры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1496,'Нарезать кубиками картофель, морковь, лук (нарезанный лук обдать кипятком и просушить бумажным полотенцем), зеленый болгарский перец. Оливки измельчить ножом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1496,'В миску выложить нарезанный овощи, добавить остывший зеленый горошек и все хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1496,'Разложить по тарелкам, подсолить, заправить майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1497,'Печень курицы отвариваем до готовности и даем ей остыть. Нарезаем печень небольшими кусочками (кубиками или поломками).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1497,'Очищенную морковь натираем на крупной терке. Репчатый лук мелко нарезаем. Обжариваем лук и морковь в сковороде на растительном масле. Даем остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1497,'Свежий укроп и чеснок измельчаем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1497,'Из белой консервированной фасоли сливаем всю жидкость.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1497,'Смешиваем в салатнике все подготовленные продукты, солим по вкусу и хорошо перемешиваем. При желании этот салат можете заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1498,'Тыкву очистить от семян и кожицы, мякоть нарезать кубиками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1498,'Высыпать кусочки в кастрюлю, залить водой, варить пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1498,'Очистить клубни картофеля от кожуры, отварить до готовности в другой кастрюле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1498,'Снять шелуху с репчатого лука, покрошить, спассеровать на подсолнечном масле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1498,'Добавить рубленый чеснок, жарить все вместе две минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1498,'Нарезать картофель, добавить к тыкве вместе с обжаркой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1498,'Овощи размять толкушкой или ложкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1498,'Прогреть сливки в микроволновой печи, влить в пюре.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1498,'Массу перемолоть с помощью блендера, соль и масло – по вкусу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1498,'Прогреть суп в кастрюле в течение семи минут на тихом огне.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1499,'Очистить тыкву, чеснок, картофель, лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1499,'Клубни картофеля и тыкву порезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1499,'В кастрюлю влить воду, выложить тыкву, добавить лавровый лист.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1499,'Потушить в течение десяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1499,'После закипания положить картофель, огонь убавить, варить десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1499,'Порубить лук и чеснок, обжарить на масле до золотистого цвета.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1499,'В картофель добавить обжарку, посолить по вкусу, всыпать молотый перец и паприку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1499,'Варить пять минут, огонь выключить, удалить лавровый лист.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1499,'Перемолоть массу при помощи блендера, выложить обратно в кастрюлю, огонь включить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1499,'Нарезать пластинками плавленый сыр, добавить в суп, варить до расплавления.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1499,'Блюдо снять с огня, дать постоять.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1499,'Нарезать кубиками хлеб, подсушить в духовом шкафу, подать к супу отдельно.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1500,'Тыкву очистить, нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1500,'Нарезать очищенные клубни картофеля.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1500,'Отварить кусочки индейки до готовности, мясо вынуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1500,'Добавить тыкву, картофель, соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1500,'Варить до мягкости, приготовить пюре при помощи блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1500,'Влить сливки, всыпать молотый базилик, размолоть массу блендером еще раз.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1500,'Довести до кипения, огонь погасить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1500,'Покрошить отваренную индейку, всыпать свежую рубленую зелень.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1501,'Желудки промыть и порезать тонкими полосками. Порезать лук полукольцами, а очищенный картофель кубиками. Равномерно обжарить лук до «золотого» цвета. В одну миску сложить картофель, желудки, лук и сметану, посолить, перемешать и разложить по горшочкам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1501,'Сверху содержимого горшочков выложить порезанные грибы, 2 горошка перца и по половинке веточки розмарина и полить все сливками.  Накрыть горшочки. Если нет подходящих крышек, то можно накрыть фольгой. Поставить их в духовку, включить температуру 200 градусов и, постепенно нагревая жаркое с куриными желудочками и грибами, готовить 1 час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1502,'Отвариваем до готовности рис, яйца и рыбу. Даем этим продуктам остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1502,'Из вареной рыбы удаляем все косточки и нарезаем ее на небольшие кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1502,'Рис после варки промываем под холодной водой и оставляем его в ситечке (чтобы ушла лишняя вода).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1502,'Вареные яйца нарезаем на небольшие кубики. Свежие огурец натираем на терке (я натираю на терке для корейской моркови).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1502,'Зелень укропа мелко шинкуем, а красный репчатый лук мелко нарезаем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1502,'Смешиваем все подготовленные продукты в салатнике и добавляем консервированный зеленый горошек (без жидкости). Я оставляю немного горошка для украшения рыбного салата.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1502,'Заправляем салат майонезом (у меня ушло 3 ст. ложки), солим по вкусу и перемешиваем. Выкладываем наш салат из вареной рыбы на тарелку и украшаем его горошком и зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1503,'Измельчаем печенье в мелкую крошку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1503,'К творогу добавляем 30 мл молока, сахар и все перемешиваем до однородной массы. Если у вас творог зернистый можно воспользоваться блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1503,'На пищевую пленку выкладываем ровным слоем смесь с печеньем. Посыпаем ореховой крошкой. Поверх выкладываем слой с творогом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1503,'Бананы очищаем от кожуры, и отрезаем края. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1503,'Отправляем десерт в холодильник на 1,5-2 часа, нарезаем ломтиками и можно подавать к столу!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1504,'Очистить и нарезать помидоры, тыкву, морковь, сладкий болгарский перец, чеснок, репчатый лук. Натереть имбирь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1504,'Морковь, лук и чеснок спассеровать на оливковом масле прозрачного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1504,'Добавить нарезанный перец и помидоры, положить немного сливочного масла, сахарный песок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1504,'Потушить смесь на тихом огне до мягкости, добавить имбирь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1504,'Обжарку добавить к тыкве, приготовить пюре при помощи блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1504,'Суп немного поварить, влить сливки, добавить соль по вкусу, всыпать карри. Перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1505,'Тыкву очистить, удалить семена, нарезать кусочками, прогреть в микроволновой печи в течение семи минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1505,'Сформовать фрикадельки из куриного фарша, сырого яйца, рубленой зелени, черного перца, базилика и соли. Масса должна получиться однородной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1505,'Отварить шарики в воде или в бульоне в течение пяти минут. Огонь – средний.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1505,'Мягкую тыкву переложить в чашу блендера, приготовить пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1505,'Переложить массу в куриный бульон, варить пять минут вместе с фрикадельками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1505,'Всыпать любимые специи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1505,'Влить сливки, перемешать, суп прогреть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1506,'Овощ очистить, нарезать, выложить в кастрюлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1506,'Всыпать сахарный песок, влить сливки, положить палочку корицы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1506,'Довести до кипения, потушить полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1506,'Вынуть корицу, продукты перемолоть при помощи блендера. Масса должна получиться однородной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1506,'Разлить суп в тарелки, украсить семечками, любыми ягодами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1507,'Тыкву, морковь, картофель, лук очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1507,'Прогреть оливковое масло в мультиварке, всыпать лук и морковь, нарезанные кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1507,'Выставить режим «Выпечка» на десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1507,'Добавить кусочки тыквы, картофель. Еще раз выставить ту же программу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1507,'Влить воду, варить пятнадцать минут в режиме «Тушение».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1507,'Массу перемолоть блендером, влить сливки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1507,'Еще раз перемолоть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1507,'Подать к столу в горячем виде, украсить свежей рубленой петрушкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1508,'Очистить картофель, лук, морковь и тыкву.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1508,'Нарезать овощи кубиками, потушить пять минут в масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1508,'Переложить обжарку в кастрюлю, влить бульон, время тушения – двадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1508,'Ошпарить помидоры, снять кожицу, мякоть нарезать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1508,'Добавить в основную массу, превратить в пюре блендером.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1508,'Нарезать кусочками копченое рыбное филе, половину выложить в суп.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1508,'Влить сливки, довести до кипения.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1508,'Всыпать смесь перцев, оставить блюдо на десять минут для настаивания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1508,'Разлить суп в тарелки, добавить рыбу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1509,'Очистить и натереть тыкву, морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1509,'Овощи перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1509,'Для измельчения можно использовать корейскую терку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1509,'Кислое яблоко очистить, удалить семена.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1509,'Мякоть нарезать мелкой соломкой, полить лимонным соком, чтобы продукт не почернел.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1509,'Отдельно приготовить заправку из жидкого меда и масла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1509,'Добавить корицу и рубленые грецкие орехи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1509,'Продукты перемешать. Заправить салат.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1510,'Картофель отварить до готовности, остудить, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1510,'Очистить тыкву, мякоть запечь в духовке в течение пятнадцати или семнадцати минут, нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1510,'Нашинковать белокочанную капусту, помять руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1510,'Нарезать зелень, помидоры, лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1510,'Продукты перемешать, посолить по вкусу, всыпать рубленый базилик, тмин, заправить оливковым маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1511,'Тыкву отварить до готовности, продукт должен стать мягким. Натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1511,'Порезать стебель сельдерея.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1511,'Приготовить заправку из оливкового масла, лимонного сока, жидкого натурального меда.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1511,'Перемешать, заправить салат, посыпать семенами кунжута.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1512,'Мякоть тыквы нарезать кубиками, отварить в воде с солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1512,'Продукт охладить, переложить в салатницу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1512,'Добавить кубики нарезанных соленых огурцов, дольки свежих томатов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1512,'Добавить тонко нарезанный полукольцами репчатый лук, зелень петрушки, горошек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1512,'Приготовить заправку из уксуса, масла, соли, полить салат.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1513,'Курицу отварить с солью до полной готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1513,'Мясо остудить, порвать на волокна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1513,'Измельчить тыкву и очищенную морковь при помощи корейской терки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1513,'Нарезать полукольцами красный лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1513,'Обжарить на масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1513,'Добавить остальные измельченные овощи, прогревать еще две или три минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1513,'Переложить обжарку в миску, посолить по вкусу, поперчить, полить уксусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1513,'Добавить курятину.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1514,'Тыкву очистить, мякоть нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1514,'Посолить, оставить на ночь в прохладном месте. Овощ должен дать сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1514,'Промыть холодной водой, обсушить, обжарить на сильном огне несколькими порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1514,'Измельчить чеснок, посолить, всыпать рубленую зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1514,'Нарезать полукольцами лук, морковь – полосками, тонкими и длинными.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1514,'Полить смесь горячим растительным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1514,'Добавить чеснок, мед, зелень, соевый соус, кориандр, черный и красный молотый перец, светлый кунжут, соль.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1514,'Посыпать светлым кунжутом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1514,'Всыпать тыкву.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1514,'Побрызгать салат уксусом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1515,'Тыкву очистить от семян и кожуры, натереть на мелкой терке или на корейской.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1515,'Отварить и покрошить яйца, добавить к тыкве.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1515,'Посолить по вкусу, добавить чеснок и любимые специи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1515,'Заправить салат жирным майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1516,'Салат руккола поделить на стебли, промыть в холодной воде, обсушить салфетками, выложить на большое плоское блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1516,'Можно заменить рукколу любым листовым салатом, в этом случае порвать его руками на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1516,'Тыкву очистить, нарезать лентами при помощи овощечистки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1516,'Полоски скрутить розочками, выложить на блюдо в любом порядке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1516,'Высыпать нарезанный кубиками копченый бекон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1516,'Блюдо посолить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1516,'Приготовить заправку из оливкового масла и лимонного сока, добавить сушеные ароматные травы. Полить овощи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1516,'Обжарить на сухой сковороде грецкие орехи, посыпать салат.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1517,'Просеять муку в большую глубокую миску. Влить молоко, непрерывно помешивая, чтобы не было комочков. Добавить к молочно-мучной смеси яйца, тоже хорошо перемешать венчиком. Кинуть щепотку соли, сахар, половину сливочного масла. Добавить водку, перемешать и оставить тесто на 1 час в теплом месте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1517,'На сковородке разогреть немного сливочного масла. Половник теста вылить на сковороду так, чтобы закрыть полностью дно тонким слоем. Жарить 1 минуту. Перевернуть, жарить еще 1 минуту. Испечь блины из всего теста. Очищенные яблоки порезать на 4 части, косточки и перегородки у них удалить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1517,'Сложить все яблоки в сотейник, залить 0,5 ст. воды. Тушить под крышкой примерно 10 минут на среднем огне. Добавить сметану, корицу, сахар, включить плиту на максимум и варить еще 3–4 минуты с открытой крышкой. Дать яблокам остыть. Взять прямоугольную форму, застелить ее пергаментом или пищевой пленкой. Два блина уложить на дно так, чтобы их края свешивались с боков наружу формы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1517,'На дно положить один или два блина, сложенных пополам (или больше, в зависимости от размеров выбранной формы). Распределить часть яблок сверху. Снова уложить блин, сложенный пополам. И так чередовать яблочную начинку с блинами. Свисающие края блинов завернуть сверху последнего блина, потом накрыть пленкой. Придавить пирог чем-то тяжелым и поставить на ночь в холодильник.  Нарезать блинный пирог с начинкой из сметаны и яблок перед подачей ломтиками 3 см шириной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1518,'Изюм замочить в заваренном крепком черном чае на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1518,'Тыкву очистить, нарезать тонкой соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1518,'Из слив вынуть косточки, мякоть нарезать кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1553,'Время запекания – около получаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1518,'Выложить в салатницу, сливу и тыкву, добавить отцеженный изюм.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1518,'Приготовить заправку из сметаны с сахарным песком и корицей. Полить салат.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1519,'Сливочное масло растопить, перемешать с сырым куриным яйцом, сахарным песком, всыпать муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1519,'Ингредиенты перемешать, поставить на полчаса в холодное место.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1519,'Снять кожицу с тыквы, нарезать мякоть кубиками, варить пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1519,'Добавить сахар, крахмал, дополнительные желтки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1519,'Массу взбить блендером до состояния пюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1519,'Еще часть желтков перемешать с сахарным песком и крахмалом, продукты добавить в творог.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1519,'Холодное тесто поместить в форму, выложить поверх начинку из творога и тыквы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1519,'Выпекать пирог при температуре 180 градусов около сорока минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1519,'Уменьшить нагрев до 160 градусов, печь еще полчаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1520,'Приготовить тесто из яиц, пищевой соды, муки, маргарина или сливочного масла, сметаны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1520,'Ингредиенты соединить, перемешать до однородного состояния, дать массе постоять в холоде десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1520,'Разделить на две неравные части, раскатать лепешки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1520,'Большую лепешку выложить в форму с бортиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1520,'Очистить тыкву, отварить мякоть, измельчить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1520,'Перемешать с яйцами, мягким сливочным маслом, творогом и отваренным рисом. Специи – по вкусу и желанию.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1520,'Выложить начинку в форму, накрыть меньшей лепешкой, скрепить края.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1520,'Печь в духовом шкафу в течение сорока минут, температура приготовления – 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1520,'Готовность проверить деревянной палочкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1521,'Перемешать муку с пищевой содой, нарезанным кусочками сливочным маслом, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1521,'Отдельно растереть яйцо с сахаром, добавить в тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1521,'Влить часть сметаны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1521,'Замесить тесто, накрыть пищевой пленкой, убрать на полчаса в холодное место.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1521,'Очистить и нарезать кубиками тыкву, отварить до готовности, потолочь до состояния пюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1521,'Другой способ – перебить блендером.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1521,'Яблоки очистить от семян и кожуры, перетереть, перемешать с тыквой, посыпать сахаром и крахмалом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1521,'Добавить оставшийся сахар и крахмал в творог, вбить яйца, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1521,'Тесто вынуть из холодильника, приготовить основу в форме с бортиками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1521,'Выложить начинку слоями, чередуя тыкву и творог.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1521,'Время приготовления – один час, время – 180 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1521,'Остудить, дать постоять в холодильнике.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1522,'Плод очистить, нарезать мякоть, отварить до мягкого состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1522,'Приготовить пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1522,'Добавить сахарный песок, всыпать крахмал, корицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1522,'Перемешать яйца с творогом, оставшимся сахаром и крахмалом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1522,'Мягкое сливочное масло растереть с яйцами и сахаром, влить сметану, всыпать соду и муку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1522,'Приготовить тесто, охладить в течение получаса, выложить в форму с бортиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1522,'Выложить творожную, а затем тыквенную начинку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1522,'Включить духовой шкаф, готовить сорок минут при температуре 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1523,'Тыкву очистить от кожуры, мякоть измельчить при помощи блендера, второй способ – натереть на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1523,'Приготовить тесто из сахарного песка, муки, разрыхлителя, сырых яиц. Тесто должно получиться однородным и полужидким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1523,'Выложить тыкву, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1523,'Чашу мультиварки смазать маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1523,'Выложить основную массу, сверху – творог. Начинка должна лежать островками, ее лучше выкладывать столовой ложкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1523,'Выставить режим «Выпечка» на тридцать пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1524,'Приготовить тесто из сахара, соды, кефира, яиц, муки, творога. Масса должна быть полужидкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1524,'Тыкву очистить, измельчить, отварить до мягкости или запечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1524,'Далее продукт перебить или перетереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1524,'Перемешать с творогом, добавить сахар, корицу и ванилин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1524,'Половину теста поместить в форму, выложить начинку из тыквы и творога, сверху – оставшееся тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1524,'Температура выпекания – 180 градусов, время – полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1525,'Обжариваем на растительном масле измельченные лук и грибы (солим и перчим по вкусу).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1525,'Измельчаем чернослив, куриное филе.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1525,'Формируем салат выкладывая слои в следующей очередности:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1525,'Из желтков и белков формируем лицо и бороду, чернослив выступит глазками, а помпон на шапке и нос можно сформировать из помидоров или красного сладкого перца.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1526,'Очистить тыкву, натереть мякоть на терке, перемешать с творогом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1526,'Добавить любое варенье и сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1526,'Тесто поделить на две части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1526,'Первую выложить на противень, сверху – начинка, вторая лепешка. Края соединить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1526,'Поставить в духовку на полчаса, температура выпекания – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1527,'Куриное мясо с костями нарезать крупными кусками, залить водой, добавить половину репчатой луковицы, четверть моркови.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1527,'Варить бульон на тихом огне, пену снимать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1527,'Картофель очистить, положить в суп целиком, добавить стебли укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1527,'Нарезать кубиками оставшуюся морковь и лук, обжарить на масле. Лук должен стать прозрачным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1527,'При готовности картофеля вынуть из бульона мясо, лук и укроп.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1527,'Положить кубики тыквы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1527,'Варить до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1527,'Часть бульона слить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1527,'Овощи должны остаться в супе.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1527,'Картофель и тыкву перебить блендером.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1527,'Все продукты объединить, перемешать, поставить на огонь и довести до кипения. Соль – по вкусу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1527,'Обжарить на сковороде тыквенные семечки, постоянно помешивать.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1527,'Добавить в суп курятину, семечки.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1528,'Куриную грудку промыть, удалить кости, филе нарезать кусками, отварить в воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1528,'То же самое проделать с картофелем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1528,'Нарезать кусочками репчатый лук и морковь, добавить в картошку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1528,'Нарезать мякоть тыквы кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1528,'Процедить куриный бульон, мясо выложить в овощи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1528,'Варить до полной готовности, жидкость слить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1528,'Перемолоть ингредиенты при помощи блендера, подлить бульон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1528,'Готовый суп-пюре посолить по вкусу, добавить кусочек сливочного масла и зелень – по желанию.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1529,'Куриное филе мелко нарезать, вымыть, очистить и произвольно нарезать картофель, лук, тыкву, яблоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1529,'Имбирь и чеснок натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1529,'Выставить режим «Жарка», влить в чашу подсолнечное масло, прогреть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1529,'Выложить лук и чеснок, имбирь, все вместе жарить десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1529,'Всыпать карри, прогреть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1529,'Добавить остальные ингредиенты, влить кипяток, всыпать соль, перемешать, подержать под крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1529,'Выставить режим «Суп».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1529,'Продукты переложить в посуду, перемолоть блендером в пюре.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1530,'Сварить бульон из курицы с костями, мясо вынуть, удалить кожу и кости, отложить в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1530,'Нарезать тыкву и картофель кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1530,'Часть бульона отлить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1530,'Овощи перемолоть при помощи блендера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1530,'Долить горячее молоко, разбавить бульоном, довести до кипения и снять с огня.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1530,'Положить в тарелку куриное мясо, зелень, нарезанный мелкими кусочками бекон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1531,'Апельсины и лимоны промыть хорошо в теплой воде, кожуру у них лучше даже почистить щеткой. Теркой или ножом тоненько срезать цедру с фруктов и отжать из них сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1538,'Нарезать селедку, смешать со сливочным сыром.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1553,'Репчатый лук и чеснок нашинковать, обжарить с фаршем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1531,'Сок и цедру положить в кастрюльку, всыпать к ним сахар и залить кипящей водой (негазированной). Кипятить 1–2 минуты, снять с огня и остудить. Поставить в холодильник на 5 часов. Смешать перед употреблением апельсиновую фанту с охлажденной газированной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1532,'Морковку надо почистить и помыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1532,'Далее на маленькой терке натираем морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1532,'Далее так же на меленькой терке натираем 70 грамм сыра. Сыр перекладываем к морковке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1532,'Через чеснокодавку выдавливаем 4 зубчика чеснока к морковке с сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1532,'Солим и перчим по вкусу, все хорошо перемешиваем. И у нас получилась намазка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1532,'Тостовый хлеб нарезаем на две части, и на намазываем хлеб нашей намазкой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1533,'Куриное мясо залить водой, варить двадцать минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1533,'Нарезать кубиками тыкву и репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1533,'Измельчить чеснок, обжарить ингредиенты на сливочном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1533,'Обжаренные овощи поварить в бульоне двадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1533,'Смесь взбить при помощи блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1533,'Влить сливки, снять с огня.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1533,'Блюдо снять с огня, подать на стол в горячем виде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1534,'Отделить кожу от куриного мяса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1534,'Филе варить в течение пяти минут, затем первый бульон слить, добавить холодную воду, еще раз поставить на огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1534,'Нарезать тыкву кубиками, выложить в кастрюлю с бульоном, варить до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1534,'Обжарить нарезанный репчатый лук на сковороде до прозрачности, добавить чеснок. Для обжарки использовать подсолнечное масло без запаха.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1534,'Отлить из кастрюли немного бульона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1534,'В оставшуюся жидкость положить обжарку с луком, ингредиенты перемолоть блендером.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1534,'Натереть твердый сыр на крупной терке, поделить пополам.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1534,'Часть высыпать в суп, вторую поставить на стол для заправки супа по желанию едоков.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1534,'Влить в суп сливки, всыпать кориандр, массу еще раз довести до кипения.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1535,'Тыкву промыть холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1535,'Нарезать дольками, срезать кожуру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1535,'Мякоть нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1535,'Налить в кастрюлю воду и молоко, развести сахарный песок, прогреть на плите.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1535,'Довести до кипения, выложить кубики из тыквы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1535,'Варить пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1535,'Продукт превратить в пюре при помощи толкушки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1535,'Пшенку промыть, перебрать, добавить в пюре и посолить по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1535,'Огонь уменьшить, варить все вместе под крышкой в течение двадцати минут, помешивать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1536,'Отварить рис до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1536,'Добавить обычный и ванильный сахарный песок, промыть изюм без косточек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1536,'Все вместе перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1536,'Тыкву промыть и очистить от семечек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1536,'Если плод большой – разрезать пополам, если маленький – снять крышку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1536,'Семена удалить ложкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1536,'Внутри плод смазать маслом, наполнить кашей, влить молоко, сверху – кусочек сливочного масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1536,'Поставить тыкву с начинкой на противень.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1536,'Прогреть духовку до 180 градусов. Выпекать в течение сорока пяти – шестидесяти минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1536,'Готовность проверить зубочисткой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1537,'Кукурузную крупу промыть, залить водой, поставить варить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1537,'Мякоть тыквы очистить от кожуры, ополоснуть, нарезать мелкими кубиками или ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1537,'Кашу помешивать, в ней не должно быть комочков, и она не должна пригореть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1537,'Добавить тыкву и сахарный песок, влить молоко, варить на тихом огне десять минут, продолжать помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1537,'Добавить масло, подержать кашу пять минут под крышкой, затем подать на стол.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1538,'Подготовить все ингредиенты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1538,'Замариновать лук.','https://vkuso.ru/data/cache/data/80/4cde4a517afd980_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1553,'Выложить на противень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1538,'Нафаршировать картофель, сверху украсить красным и зеленым луком.','https://vkuso.ru/data/cache/data/57/ae7074289ddf457_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1539,'Мякоть тыквы натереть на крупной терке, выложить в ковш, влить воду, поставить варить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1539,'Через пять минут влить молоко, перемешать, прогревать еще две минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1539,'Всыпать хлопья овсянки, соль и сахарный песок, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1539,'Продолжать варить кашу под крышкой на тихом огне в течение четырех или пяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1539,'Огонь погасить, оставить блюдо для настаивания на несколько минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1540,'Тыкву очистить, нарезать мякоть кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1540,'Промыть водой чернослив и курагу, залить кипящей водой. Жидкость должна покрыть плоды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1540,'Через три или пять минут воду слить, ингредиенты промыть повторно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1540,'Прогреть масло в сковороде или в кастрюле с толстым дном.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1540,'Выложить тыкву, оставить томиться на десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1540,'Дождаться, пока тыква размягчится, добавить сахарный песок, рис, воду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1540,'Подержать под крышкой около пятнадцати минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1540,'Сухофрукты нарезать, добавить в почти готовую кашу, перемешать, оставить на пять минут',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1540,'Огонь погасить, емкость накрыть полотенцем или пледом, оставить на полчаса для пропаривания.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1541,'Пшено промыть от грязи и пыли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1541,'Насыпать в небольшую емкость, влить воду. Крупа должна быть покрыта жидкостью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1541,'Поставить на огонь, довести до кипения, слить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1541,'Очистить тыкву от семечек и кожуры, промыть, нарезать дольками, натереть на терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1541,'В большой горшок или несколько маленьких выложить тыкву и кашу в несколько слоев.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1541,'Заполнить емкости на две трети объема.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1541,'Влить молоко, жидкость должна покрыть продукты на палец или два.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1541,'Прогреть духовку до двухсот градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1541,'Выставить горшочки с содержимым на решетку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1541,'Прогревать пять минут, затем еще около часа.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1541,'Тушить до полной готовности.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1542,'Курицу нарезать кусочками, положить в воду и сварить бульон. После закипания воды убрать аккуратно ложкой пену с бульона, убавить огонь и варить 5–10 минут. Очищенный картофель некрупно порезать. Добавить к бульону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1542,'В это время лук и морковь почистить. Лук измельчить ножом, морковку натереть крупно. Обжарить на растительном масле морковь и лук, пока овощи не станут золотистыми, и морковь не окрасит масло в оранжевый цвет. Добавить зажарку в бульон, посолить, добавить перец и варить еще примерно 7 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1542,'В мисочке взбить яйцо. Когда картофель будет готов, вылить яйцо тонкой струйкой в бульон, мешая ложкой суп. Поварить минуту и снять с огня. Зелень мелко покрошить ножницами прямо в тарелки с налитым простым куриным супом с яйцом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1543,'Поставить на огонь кастрюлю с водой, довести до закипания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1543,'Тыкву очистить, нарезать кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1543,'Выложить в воду, варить около пятнадцати минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1543,'Кипяток слить, из тыквы приготовить пюре при помощи толкушки или блендера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1543,'Влить молоко, поставить на огонь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1543,'Довести до кипения, всыпать небольшими порциями манную крупу, кашу помешивать, в ней не должно быть комочков.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1544,'Куриное филе промыть, нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1544,'Очистить имбирь, мелко нарезать, обжарить вместе с курицей на масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1544,'Продукты помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1544,'Всыпать соль и смесь перцев.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1544,'Через пять или семь минут, влить воду, оставить тушиться на двадцать минут под крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1544,'Крупу промыть, выложить в кастрюлю, довести до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1544,'Репчатый лук нашинковать, тыкву нарезать мелкими кубиками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1544,'Добавить подготовленные овощи в гречку, посолить, посыпать хмели-сунели, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1544,'Варить десять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1544,'Курятину выложить в кашу, перемешать еще раз, готовить на тихом огне пять или семь минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1553,'Натереть твердый сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1545,'Нарезать мякоть тыквы ломтиками, поставить вариться, влить немного воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1545,'Промыть круглозернистый рис.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1545,'Через десять минут после начала кипения перебить массу блендером, влить молоко, всыпать рис.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1545,'Все вместе варить двадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1545,'Вымыть яблоко, вырезать семенные камеры, кожицу, мякоть нарезать кубиками и выложить в кашу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1545,'Варить в течение десяти минут на тихом огне, добавить натуральный мед, дать каше постоять пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1546,'Продукты соединить в кастрюле, влить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1546,'Поставить кашу на огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1546,'Довести до кипения, посолить по вкусу, перемешать, прогревать пятнадцать минут на тихом огне под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1546,'Затем влить молоко, выложить сливочное масло, готовить десять или пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1546,'Готовность блюда проверить на вкус. Продукты должны стать мягкими.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1546,'Огонь погасить. Кашу заправить медом, перемешать, дать постоять двадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1547,'Тыкву очистить, вымыть, нарезать брусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1547,'Выложить в чашу мультиварки, всыпать сахарный песок, соль, ванилин, положить сливочное масло, влить молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1547,'Ингредиенты перемешать, закрыть крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1547,'Выбрать режим «Выпечка», «Тушение», «Каша» или «Мультиповар». Время приготовления – сорок пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1547,'Содержимое чаши перемешать, подержать под крышкой пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1548,'Натираем на терке сыр, яйца и чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1548,'Добавляем майонез и перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1548,'Выкладываем салат на ананасовые кольца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1548,'Украшаем по своему усмотрению, я использовала помидоры черри и петрушку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1549,'Репчатый лук нашинковать, натереть на терке сыр и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1549,'Приготовить фарш из свинины и говядины, всыпать часть измельченного сыра, соль, перец, вбить сырое куриное яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1549,'Отдельно отварить макароны до полуготовности, воду подсолить, не сливать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1549,'Выложить ложкой «гнезда» в форму для запекания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1549,'Внутрь положить мясную начинку, макароны раздвинуть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1549,'Приготовить обжарку из лука, моркови, сметаны, томатной пасты, воды. Можно использовать воду, оставшуюся после варки макарон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1549,'Добавить специи, соль и сахарный песок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1549,'Ингредиенты перемешать, варить пять минут, помешивать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1549,'Залить продукты соусом и посыпать сыром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1549,'Время запекания – двадцать пять минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1550,'Очистить и нарезать репчатый лук, добавить в фарш, посолить, поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1550,'На сковороду выложить «гнезда» из лапши, начинить фаршем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1550,'Приготовить соус из томатной пасты, с сахаром, солью, подсолнечным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1550,'Влить томатный сок, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1550,'Залить «гнезда». Готовить около получаса, огонь – средний. Крышка сковороды должна быть приоткрыта.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1551,'Грибы и лук нарезать, жарить на сковороде вместе с мясным фаршем до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1551,'Приправы, соль – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1551,'В кипящую воду выложить гнезда на три минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1551,'Выложить полуготовые изделия на смазанный маслом противень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1551,'Нафаршировать обжаркой с грибами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1551,'Натереть сыр, посыпать гнезда.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1551,'Время запекания – 12 минут, сыр должен расплавиться.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1552,'Макаронные гнезда выложить в сотейник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1552,'Креветки очистить, перемешать с тертым твердым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1552,'Готовую начинку выложить в гнезда.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1552,'Приготовить соус из сливок, воды, соли, перца, чеснока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1552,'Залить гнезда, уровень жидкости должен быть ниже начинки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1552,'Время тушения под крышкой – пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1553,'Отварить клубни картофеля.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1553,'Приготовить пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1553,'В остывшую массу добавить муку, масло, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1553,'Сформовать гнезда при помощи кондитерского шприца или столовой ложки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1553,'В качестве дополнительного ингредиента можно использовать перепелиные яйца.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1553,'При выкладывании в гнезда фарша сделать углубления для яиц.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1553,'Запекать пятнадцать минут, затем аккуратно вбить по яйцу в каждое гнездо.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1553,'Посыпать сыром, печь еще пятнадцать минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'Чернослив промыть, залить горячей водой, подержать час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'Превратить сухофрукты блендером в кашицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'Прогреть сковороду, всыпать, соль, гвоздику, кардамон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'Специи прогреть до появления аромата, протереть в ступке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'То же самое проделать с зирой, кориандром и фенхелем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'Далее – с корицей, мускатным орехом, анисом, куркумой, паприкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'Добавить оливковое масло на сковороду, обжарить стручок острого перца, не измельчать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'В новой порции масла обжарить нарезанный кубиками репчатый лук, добавить кашицу чеснока, имбирь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'Влить насыщенный куриный бульон, массу потушить в течение пяти или шести минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'Добавить в сковороду специи, прогретые ранее.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'Прогревать все вместе еще три или четыре минуты.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'Всыпать коричневый сахар, молотые сухофрукты.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'Долить воду.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'Прогревать соус десять или двенадцать минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'Массу остудить, перебить блендером, хорошо протереть через сито.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1554,'Смесь довести до кипения, снять с огня.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1555,'Ананасы вынуть из банки, отцедить сироп, нарезать кубиками, всыпать в чашу блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1555,'Репчатый лук порубить, добавить в ананасы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1555,'Заправить майонезом, карри, посолить по вкусу, всыпать свежемолотый перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1555,'Массу перебить до однородного состояния. Соус охладить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1556,'Оливковое масло прогреть, добавить томатную пасту, перемешать, оставить соус на огне на пять или шесть минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1556,'Влить апельсиновый фреш, всыпать карри, кайенский перец, перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1556,'Ингредиенты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1556,'Оставить на плите еще на десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1556,'Посолить по вкусу, влить бульон порциями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1556,'Массу прогревать две минуты, снять с огня.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1557,'Мелко порезать яйца, крабовое мясо, лук и шампиньоны. Грибы обжарить с луком на растительном масле. Перемешать яйца, крабовое мясо и жареные грибы. Заправить майонезом, перемешать хорошо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1557,'Салат плотно уложить в салатник или миску. Переложить на другую сервировочную тарелку, перевернув миску. Получившуюся горку вкусного салата с крабовым мясом и грибами украсить зеленым горошком или зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1558,'Репчатый лук очистить, нашинковать, жарить на масле до прозрачного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1558,'Шампиньоны промыть, срезать испорченные места, добавить к луку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1558,'Прогревать все вместе до испарения жидкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1558,'Всыпать соль, специи, рубленый чеснок, все вместе размять и потушить под крышкой. Остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1558,'Куриные яйца отварить вкрутую, нарезать кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1558,'Ингредиенты положить в чашу блендера, перемолоть вместе со сливочным маслом. Масса должна получиться однородной. Охладить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1558,'Намазать на тосты из свежего багета или черного хлеба.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1559,'Свежие шампиньоны вымыть, обсушить, разрезать на две или четыре части каждую шляпку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1559,'Противень застелить пекарской бумагой, побрызгать маслом, печь полчаса при температуре 150 градусов. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1559,'Спассеровать на масле нарезанный репчатый лук и тертый корнеплод моркови.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1559,'Порубить грибы, перемешать с обжаркой, влить соевый соус, добавить давленый чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1559,'По желанию в массу можно добавить сливочное масло или майонез, продукт хранить в холодильнике.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1560,'Кальмаров разморозить, отварить в течение четырех минут, очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1560,'Нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1560,'Нарезать такой же соломкой свежий очищенный огурец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1560,'Отварить куриные яйца, очистить, нарезать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1560,'Ингредиенты перемешать, посолить по вкусу, заправить сметаной или майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1560,'Разложить массу в тарталетки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1561,'Кальмаров очистить сразу или после недолгого отваривания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1561,'Держать морепродукты в кипящей воде не нужно более пяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1561,'Точно так же поступить с креветками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1561,'Часть отваренных морепродуктов отложить для финального украшения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1561,'Отварить куриные яйца вкрутую.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1561,'Остудить, очистить, нарезать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1561,'Разморозить крабовые палочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1561,'Продукты нарезать очень острым ножом, посолить по вкусу и заправить майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1561,'Разложить готовую начинку в корзинки-тарталетки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1561,'Украсить закуску целыми креветками и красной икрой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1562,'Нарезать шампиньоны кубиками, спассеровать на растительном масле до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1562,'Очистить и промыть кальмаров, нарезать минимально тонкой соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1562,'Выложить на сковороду, жарить не больше двух минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1562,'Посолить и поперчить, заправить сметаной и немного потушить под крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1562,'Выложить в готовые тарталетки, посыпать сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1562,'Поставить в духовой шкаф на десять минут, температура приготовления – 190 градусов. Должна образоваться румяная корочка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1562,'Подать закуску теплой или холодной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1563,'Куриную грудку промыть и отварить вместе с луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1563,'Луковицу целиком добавить в бульон через десять минут после начала кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1563,'Филе остудить, нарезать кусочками и превратить в пюре при помощи блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1563,'В массу влить бульон, посолить, всыпать специи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1563,'Все вместе еще раз взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1563,'Приготовить бутерброды, украсить зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1564,'Морковь и куриную грудку нарезать кусочками, отварить в течение получаса. Посолить в конце приготовления по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1564,'Репчатый лук измельчить и спассеровать вместе с пластинками чеснока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1564,'Перемешать продукты в блендере с оставшимся маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1564,'Массу взбить, посолить, всыпать специи, влить немного куриного бульона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1564,'Паштет охладить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1565,'Куриную грудку отварить, отделить кости, филе нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1565,'Лук репчатый нашинковать, спассеровать до получения золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1565,'Промыть печень, поделить на четыре части, обжарить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1565,'При прокалывании должен выделяться прозрачный сок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1565,'Яйца отварить, разрезать пополам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1565,'Все продукты пропустить через мясорубку два раза.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1565,'Печень должна быть горячей.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1565,'Паштет выложить в емкость с кусочком сливочного масла, оно должно растаять.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1565,'Перемешать массу руками, специи и соль добавить по вкусу и желанию.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1566,'Отваренное куриное мясо пропустить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1566,'Порубить острым ножом очищенные ядра грецких орехов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1566,'Растолочь чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1566,'Измельчить зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1566,'Ингредиенты перемешать, посолить, заправить нежирным йогуртом, оливковым маслом, лимонным соком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1567,'В кастрюлю влить воду, добавить лавровый лист, перец горошком, соль и прованские травы, перемешать. Поставить кастрюлю на огонь и довести до кипения, поварить 1 мин. Остудить рассол.  В остывший рассол опустить свинину, накрыть крышкой и убрать в холодильник на 2-3 дня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1567,'Через 2-3 дня, вытащить свинину из рассола и с помощью бумажных полотенец убрать лишнюю влагу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1567,'Нарубить мелко чеснок. В миске смешать чеснок, растительное масло и горчицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1567,'Мясо посолить и поперчить и намазать чесночно-горчичной смесью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1567,'Завернуть мясо в фольгу, положить на противень и отправить в разогретую до 190°С духовку на 2 часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1567,'Через 2 часа вытащить мясо из духовки, разрезать и раскрыть фольгу, отправить мясо в духовку и выпекать еще 10-15 мин при 240°С.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1568,'На терке натираем морковь, сыр, яйца и чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1568,'Добавляем орехи и майонез, тщательно перемешиваем салат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1568,'Для формирования елочек я буду использовать рюмки и пищевую пленку. Плотно утрамбовываю в них салат и отправляю на пару часов в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1568,'Измельчаю укроп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1568,'Извлекаю салат из рюмочек и обваливаю в измельченном укропе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1568,'Подаем на крекере.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1569,'Срезать с куриной грудки жир, снять кожицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1569,'Филе отварить с солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1569,'Очистить, измельчить репчатый лук, спассеровать на сковороде до мягкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1569,'Добавить грибы, нарезанные пластинками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1569,'Все вместе тушить восемь минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1569,'Растопить сливочное масло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1569,'Остудить мясо.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1569,'Все компоненты превратить в однородную массу при помощи комбайна, влить куриный бульон.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1569,'Массу взбить, добавить горчицу, молотый перец и рубленую зелень.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1570,'Куриное мясо отварить с солью, корнем петрушки, луком, морковью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1570,'Продукты остудить, нарезать кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1570,'Пропустить через мясорубку мясо, морковь и сваренные вкрутую куриные яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1570,'Развести желатин в курином бульоне так, как написано в инструкции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1570,'Залить паштет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1570,'Добавить соль, грецкие рубленые орехи, специи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1570,'Массу перебить при помощи блендера.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1570,'Поставить паштет в холод для застывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1571,'Измельчить репчатый лук и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1571,'Обжарить на масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1571,'Замочить чернослив в воде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1571,'Порубить любую зелень и очищенный чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1571,'Отварить куриное филе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1571,'Все ингредиенты перемолоть при помощи блендера, заправить смесью майонеза и сметаны в равных количествах.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1571,'Массу взбить еще раз, она должна насытиться кислородом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1572,'Заранее включить духовку на 230 градусов. Порезать тонкими кружочками помидоры и баклажаны. Порезать чеснок крупными ломтиками. Тонко порезать сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1572,'В жаропрочной посуде выкладываем, чередуя, овощи, посыпаем сверху чесноком, сухими травами и перцем, поливаем растительным маслом. Посуду с овощной запеканкой ставим в духовку на 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1573,'Морковь и репчатый лук очистить, промыть, нарезать квадратами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1573,'Утиную печень очистить от пленок, промыть, обсушить салфетками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1573,'Обжарить на масле овощи, добавить печень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1573,'Довести до готовности на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1573,'Всыпать специи, ввести сметану, все вместе потушить две минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1573,'Смесь остудить, перемолоть блендером до однородности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1573,'Выложить массу в контейнеры.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1574,'Мелко порезать куриное филе, как на куриные оладьи. Положить в форму, чуть-чуть намазанную маслом.','https:https://st.vkuso.ru/data/cache/thumb/21/fd178d3aee69f21_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1574,'Порезать кабачок на небольшие ломтики. Чуть-чуть обжарить.','https:https://st.vkuso.ru/data/cache/thumb/e6/19ade5283e620e6_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1574,'Порезать на ломтики моцареллу.','https:https://st.vkuso.ru/data/cache/thumb/32/f18b821c9cf2a32_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1574,'Потереть пармезан.','https:https://st.vkuso.ru/data/cache/thumb/44/b12242124241a44_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1574,'Порезать перец на кусочки.','https:https://st.vkuso.ru/data/cache/thumb/b1/3801fa6c88e11b1_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1574,'Посыпать куриное филе перцем, солью, положить кусочки обжаренного кабачка.','https:https://st.vkuso.ru/data/cache/thumb/27/d0817825e93e927_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1574,'На него порезанную моцареллу.','https:https://st.vkuso.ru/data/cache/thumb/d9/4fa86cf4a4475d9_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1574,'Посыпать пармезаном.','https:https://st.vkuso.ru/data/cache/thumb/8c/12eeffb767a138c_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1574,'Сверху положить порезанный болгарский перец, оливки.','https:https://st.vkuso.ru/data/cache/thumb/20/0dc8443f2fb2020_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1574,'Отправить на 20-30 минут в духовку, соблюдать температуру 180 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1575,'Мелко потереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1575,'Поместить в блендер сливочное масло, тертый сыр, муку, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1575,'Долить воду, взбить до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1575,'Завернуть тесто в полиэтилен, отправить на 30 минут в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1575,'Тонко раскатать холодное тесто, порезать на куски, положить на противень, застеленный специальной бумагой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1575,'Готовить Домашние сырные крекеры с солью 15 минут, соблюдать температуру 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1576,'Порезать охотничьи колбаски, обжарить на оливковом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1576,'Добавить к колбаскам измельченную морковь, чеснок, лук, острые специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1576,'Потереть помидоры, порезать болгарский перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1576,'Обжаривать 5-7 минут, пока колбаски не покроются золотистой корочкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1576,'Нагреть куриный бульон, положить порезанный картофель, колбаски с овощами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1576,'Посыпать специями, солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1576,'Добавить смесь красного и черного перцев, измельченную зелень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1576,'Довести острый испанский суп с охотничьими колбасками на курином бульоне до кипения, варить 10 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1577,'Вымыть листья шпината, подсушить бумажным полотенцем.','https:https://st.vkuso.ru/data/cache/thumb/18/0bd20338c285318_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1577,'Измельчить в блендере.','https:https://st.vkuso.ru/data/cache/thumb/7c/d4cc50be6a4967c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1577,'Вбить яйца, взбить. Посыпать перцем, солью.','https:https://st.vkuso.ru/data/cache/thumb/b1/82d5db6814e2bb1_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1577,'Добавить итальянские травы, тертый сыр, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/86/1e4dcf94d387986_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1577,'Положить массу на противень, застеленный бумагой, равномерно распределить.','https:https://st.vkuso.ru/data/cache/thumb/13/c06b8878c132313_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1577,'Отправить заготовку на 15-20 минут в духовку, соблюдать температуру 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1577,'Измельчить в блендере помидоры с итальянскими травами. Распределить по основе томатный соус.','https:https://st.vkuso.ru/data/cache/thumb/44/77fe2fdffbfb944_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1577,'Потом кусочки ветчины, сыр.','https:https://st.vkuso.ru/data/cache/thumb/50/59bcbbef80d1050_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1577,'Вернуть сырную пиццу на основе из шпината с ветчиной и сыром в духовку на 10-15 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1578,'Соединить сметану, яйца, специи и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1578,'Добавить прессованный чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1578,'Намазать лаваш смесью, тонким слоем мелко потереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1578,'Порезать произвольно на куски.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1578,'Выложить на сухой противень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1578,'Готовить чипсы из армянского лаваша с сыром в духовке 5-10 минут, соблюдать температуру 190 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1579,'Нагреть духовку до 220 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1579,'Намазать маслом форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1579,'Взбить белки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1579,'Отдельно соединить тертый пармезан и панировочные сухари.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1579,'Слепить из пюре 8 лепешек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1579,'Окунуть лепешку в белок, потом в сухари, положить в форму.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1579,'Готовить 15 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1579,'Перевернуть, готовить картофельные лепешки с чесноком из пюре 10-20 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1580,'Подготовить продукты. Порезать лук полукольцами, морковь – длинной соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1580,'Плов получится вкусней, если резать морковь вручную, не используя кухонный комбайн и терку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1580,'Промыть рис.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1580,'Залить холодной водой, отставить на 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1580,'Порезать баранину на куски по 3,5-5 сантиметров.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1580,'Нагреть масло на сковороде. Разрезать лук пополам, положить в сковороду. Достать лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1580,'Обжарить в этом масле мясо, переложить в отдельную емкость.','https:https://st.vkuso.ru/data/cache/thumb/ab/63548dd03b124ab_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1580,'Обжарить порезанный лук, положить морковь. Обжаривать с луком 7-8 минут.','https:https://st.vkuso.ru/data/cache/thumb/c9/853239fe28d67c9_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1580,'Добавить обжаренное мясо. В середину положить несколько головок чеснока. Насыпать специи.','https:https://st.vkuso.ru/data/cache/thumb/15/3f3752535015b15_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1580,'Добавить к ингредиентам рис. Налить воды на 0,5 сантиметров больше уровня рис.','https:https://st.vkuso.ru/data/cache/thumb/6e/a4ab8d3c48b926e_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1580,'Довести до кипения, накрыть крышкой, готовить на тихом огне 30 минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1581,'Укроп нужно помыть и измельчить.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1590,'Процедить настой через сито или марлю.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1581,'В глубокой чашке добавляем к сыру творог, измельченные орехи и чеснок. Немного солим и добавляем майонез. Все тщательно перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1581,'Затем нужно разделить получившуюся массу на несколько равных частей. Их количество и размер будут зависеть от диаметра крекеров, которые послужат основанием для елочек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1581,'Далее из шариков формируем конусы (лучше всего это делать смоченными в воде руками). 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1581,'Украшаем елочки гранатом и сыром. Также для украшения можно использовать яркую желтую кукурузу.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1582,'Нагреть духовку до 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1582,'Постелить на противень специальную бумагу, намазать оливковым маслом. Печенье не будет прилипать и пропитается ароматом оливкового масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1582,'Приготовить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1582,'Взбить холодные яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1582,'Насыпать сахар, просеянную муку, добавить анис и ванильный сахар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1582,'Размешать тесто до однородности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1582,'Положить на противень: взять маленькую ложку и выложить тесто на бумагу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1582,'Можно использовать кондитерский мешок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1582,'Получатся тоненькие маленькие блины. Отправить на 8 минут в духовку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'Залить молоком панировочные сухари. Отставить на 5 минут.','https:https://st.vkuso.ru/data/cache/thumb/83/bbea2d0ed378083_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'Почистить лук, измельчить, обжарить на оливковом масле.','https:https://st.vkuso.ru/data/cache/thumb/67/95259efc8fe0367_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'Почистить морковь, мелко потереть, обжарить на оливковом масле. Измельчить зелень.','https:https://st.vkuso.ru/data/cache/thumb/87/f596fdfcbbefb87_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'Отделить желтки от белков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'В емкости блендера соединить панировочные сухари, желтки, соевый соус, филе рыбы.','https:https://st.vkuso.ru/data/cache/thumb/5d/b01ee9de6da265d_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'Взбить белки и щепотку соли, отставить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'Разделить фарш на 3 одинаковые части.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'В одну часть положить зелень, осторожно добавить 1/3 белков, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/87/979ae93e4da6387_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'Положить фарш в форму прямоугольной формы. Накрыть листом нори.','https:https://st.vkuso.ru/data/cache/thumb/0a/a5610c7430a4a0a_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'Во вторую часть положить морковь, куркуму.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'Размешать, осторожно ввести 1/3 белков.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'Положить в форму второй слой. Накрыть листом нори.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'В последнюю часть фарша положить паприку. Перемешать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'Ввести оставшиеся белки. Положить третий слой в форму.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1583,'Готовить 40 минут, соблюдать температуру 180 градусов.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Сделать тесто. Соединить сливочное масло с мукой (600 г) и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Перемешать вилкой, чтобы смесь стала, как рыхлый песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Взбить желтки с сахарной пудрой миксером, добавить цедру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Когда масса станет однородной, медленно вылить жидкую массу в мучную.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Перемешивая миксером на низких оборотах. Мешать 3-4 минуты. Должно получиться эластичное, мягкое тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Поделить тесто пополам.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'В одну часть налить 3-5 больших ложек воды, насыпать 30 грамм муки, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Завернуть обе части в полиэтилен.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Сформировать шар, отправить на 60 минут в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Сделать из теста пласт в 2 миллиметра толщиной, отправить на 30 минут в холодильник.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Нагреть духовку до 190 градусов, положить тесто без воды в форму, сделать бортики.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Сделать вилкой проколы.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Сверху положить груз на пергамент.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Отправить тесто в духовку на 10 минут. Достать, остудить.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Растопить белый шоколад. При помощи кисточки намазать дно основы.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Отправить в холод на 2 минуты.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Сделать начинку. Соединить цедру лимона, сок, малину.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1620,'Сформовать пирожки, выпекать, как обычно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Посыпать песочную основу коричневым сахаром, равномерно выложить лимонно-ягодную смесь, посыпать коричневым сахаром.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Тесто с водой порезать на полоски толщиной 1 сантиметр.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Закрутить полоски в спирали, украсить пирог от середины к окружности.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Скрепить полоски между собой водой.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Отправить пирог с шоколадно-малиновой начинкой на 15-20 минут в духовку, соблюдать температуру 190 градусов.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1584,'Остудить пирог в формочке.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1585,'Измельчить лук и болгарский перец.','https:https://st.vkuso.ru/data/cache/thumb/35/3cdec93a8a88a35_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1585,'Отправить в сковороду на несколько минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1585,'Измельчить яйца, зеленый лук.','https:https://st.vkuso.ru/data/cache/thumb/1e/25f755f663c971e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1585,'Положить к печени трески.','https:https://st.vkuso.ru/data/cache/thumb/5c/abe485d0b27dd5c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1585,'Размять все.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1585,'Положить лук, болгарский перец.','https:https://st.vkuso.ru/data/cache/thumb/08/2f3164db888ed08_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1585,'Насыпать соль, перец.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1585,'Положить на блины, свернуть рулетики.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1586,'Намазать форму 23 на 23 сантиметра маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1586,'Соединить сахарную пудру, сгущенное молоко, сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1586,'Довести в кастрюле до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1586,'Положить клубнику, добавить сок лимона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1586,'Готовить, помешивая, пока температура не станет 112-115 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1586,'Если нет термометра, то капнуть смесь в емкость с холодной водой - должен получиться мягкий шарик.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1586,'Убрать с огня, сразу перелить массу в форму.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1586,'Когда масса чуть-чуть затвердеет, сделать ножом узоры.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1586,'Остудить клубничный фадж со сгущенкой, порезать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1587,'Взбить миксером все продукты для блинов до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1587,'Отправить на 30 минут в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1587,'Обжарить тоненькие блины с двух сторон на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1587,'Перед тем, как начинять, остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1587,'Нанести на блины Филадельфию.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1587,'Сверху положить полоску прошутто или ветчины и кусочки лосося.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1587,'Скрутить блины, завернуть в пленку, отправить на сутки в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1587,'Порезать на небольшие роллы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1587,'Закрепить блинные рулетики с прошутто и копченым лососем зубочисткой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1588,'Мелко порезать помидоры.','https:https://st.vkuso.ru/data/cache/thumb/ca/146e2bc3ed4e8ca_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1588,'Также мелко порезать салат.','https:https://st.vkuso.ru/data/cache/thumb/a2/f3cfeb97002ffa2_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1588,'Потереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1588,'Разделить куриную грудку на тонкие волокна, тушить 20 минут на минимальном огне, чтобы испарилась жидкость.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1588,'Обжарить.','https:https://st.vkuso.ru/data/cache/thumb/40/ea7664d3852e640_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1588,'Соединить все продукты в одной посуде, заправить сметаной или майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1588,'Перед подачей салат с куриным филе, фасолью и помидорами посыпать сухариками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1589,'Снять кожу с грудки, порезать мясо на куски, залить водой, варить 25 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1589,'Промывать рис, пока вода не будет прозрачной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1589,'Разрезать белую часть лука-порея вдоль на две части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1589,'Порезать его на тоненькие полукольца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1589,'Нагреть сливочное масло на сковороде, положить кусочки филе и лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1589,'Обжарить до румяного оттенка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1589,'Связать в пучок ниткой веточки петрушки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1589,'Довести до кипения бульон, положить рис, петрушку. Готовить 10 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1589,'Положить в бульон обжаренное мясо с луком, посыпать солью, перцем. Варить 5 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1589,'Достать петрушку, положить плавленый сыр.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1589,'Перемешивать суп, пока не растворится сыр.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1589,'Выключить огонь.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1590,'Взять 4 апельсина, помыть, обдать кипятком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1590,'Убрать в морозилку на 12-24 часа, чтобы убралась горечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1590,'Залить апельсины горячей водой, чтобы разморозить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1590,'Порезать все апельсины н 6-8 кусков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1590,'Пропустить через мясорубку, не снимая кожуры.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1590,'Залить смесь холодной кипяченой водой, отставить на 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1590,'Налить в настой 6-7 литров воды, добавить немного лимонного сока или лимонной кислоты и 0,7 килограммов сахара.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1590,'Отставить апельсиновый лимонад с лимонным соком на 60 минут, чтобы настоялся и приобрел насыщенный цвет и вкус.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1591,'Вымыть лимон, ½ порезать на четвертинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1591,'Поместить в кастрюлю лимон, сахар, налить воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1591,'Довести до кипения, готовить 10 минут на маленьком огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1591,'Почистить киви, порезать на кружочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1591,'Положить к лимону, добавить сахар и сок второй части лимона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1591,'Довести до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1591,'Переложить в емкость из стекла или керамики.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1591,'Накрыть пленкой, оставить на ночь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1591,'Положить варенье в кастрюлю, готовить 15-20 минут, помешивать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1591,'Разлить пикантное варенье из киви с лимоном по банкам, закатать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1592,'Избавить печень от жилок и пленок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1592,'Почистить овощи и пропустить все через мясорубку.','https:https://st.vkuso.ru/data/cache/thumb/26/6e7927104ee4e26_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1592,'Посыпать фарш перцем, солью, добавить чуть-чуть молотого мускатного ореха.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1592,'Перемешать, досыпать муку, чтобы получилась нужная консистенция.','https:https://st.vkuso.ru/data/cache/thumb/01/39da7031597cd01_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1592,'С помощью большой ложки сформировать котлетки, каждый раз окунать ложку в холодную воду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1592,'Обжарить печеночные котлеты с мускатным орехом под крышкой с двух сторон.','https:https://st.vkuso.ru/data/cache/thumb/9a/b33409dd288a19a_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1593,'Кастрюлю ополоснуть водой, влить молоко или смесь воды с молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1593,'Поставить на огонь, всыпать сахар и соль, в самом начале закипания всыпать крупу тонкой струйкой, помешивать. Время варки – две минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1594,'Сырые куриные яйца взбить с сахарным песком, долить растительное масло и йогурт, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1594,'Пудинг просеять, добавить муку и разрыхлитель, взбить все вместе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1594,'Форму смазать маслом и присыпать мукой, вылить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1594,'Время выпекания – 40 минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1595,'Белокочанную капусту и морковь нашинковать, перемешать и переложить в 10 литровое ведро.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1595,'Залить рассолом из холодной кипяченой воды, соли.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1595,'Положить гнет, накрыть тканью, оставить на трое суток для сбраживания, овощи периодически протыкать деревянной палочкой или длинным ножом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1595,'На третьи сутки всыпать сахарный песок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1595,'Если продукт планируется долго хранить, то норму можно увеличить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1595,'Через двое суток капусту переложить в чистые трехлитровые банки и поставить в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1596,'Небольшие банки простерилизовать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1596,'Разложить зубчики чеснока (по 2-3 шт. в каждую банку), горчицу, веточки укропа, вымытые мелкие огурцы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1596,'Приготовить маринад из воды, перца, сахарного песка, соли, лаврового листа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1596,'После начала кипения влить уксус, залить корнишоны до верха.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1596,'Время пастеризации – от 12 до 15 минут, закатать, завернуть в плед, оставить до полного остывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1597,'Включить духовку и оставить прогреваться до 180 градусов. Смешать в глубокой миске  сыпучие сухие ингредиенты: муку, какао-порошок, ванилин, соль и соду. Отдельно взбить растительное масло с сахаром на максимальных оборотах миксера. Туда же добавить яйца и продолжить взбивать до однородности. Влить горячую воду и немедленно взболтать всю смесь. Понемногу всыпать сухую смесь и размешивать, чтобы не образовалось комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1597,'Две разъемные формы выстелить пергаментной бумагой и смазать маслом. Разделить тесто на две части и выпекать в двух формах 30-40 минут на средней полке духовки. Если две формы не удается разместить на одном уровне из-за особенностей духовки, то в середине процесса выпекания их следует поменять местами, таким образом, дав пропечься одинаково равномерно. Готовые коржи оставить остывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1603,'Первый корж выложить в форму, намазать кремом, сверху – второй корж, заранее разрезанный на крупные квадраты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1603,'Оставить в холоде на два часа, по желанию верх посыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1597,'Сгущенное молоко взбить с желтками в небольшой кастрюльке  и добавив сливочное масло поставить на слабый огонь. Варить, постоянно помешивая до значительного уплотнения крема, около 5 минут, после чего снять с огня и всыпать в горячий крем кокосовую стружку и миндальные пластины и ванилин. Остывшим кремом смазать коржи, собрав из них торт. Бока и поверхность так же промазать кремом и оставить немецкий шоколадный торт с миндалем пропитываться на несколько часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1598,'Разминаем творог до однородности, чтобы избавиться от комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1598,'Добавить сахар и яйца, перемешать до однородной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1598,'Всыпать разрыхлитель, манку и овсяные хлопья, добавить ванилин. Тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1598,'Отставляем в сторону, чтобы набухла манка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1598,'С мандаринов снять очень мелкой теркой цедру, разломить на дольки, освободить от белых прожилок и пленочек и нарезать кусочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1598,'Добавить цедру и мандарины к творожной массе, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1598,'Форму для выпечки смазать сливочным маслом и присыпать мукой. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1599,'В миску перекладываем творог, добавляем масло и перетираем до однородной массы. Далее добавляем соль, ванилин и разрыхлитель, снова все перемешиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1599,'Постепенно добавляем муку и замешиваем тесто. Как только замешали тесто, убираем его в сторону. Тесто должно получиться мягким и легким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1599,'В другой миске нужно измельчить бананы до состояния «пюре».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1599,'Посыпаем стол мукой, делим тесто на две части, и раскатываем одну из них до 2-4 мм. Подрезаем неровные края и далее намазываем нашей начинкой. Закатываем в «трубочку». Нарезаем на равные кусочки. И перекладываем на противень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1599,'Взбиваем 1 куриное яйцо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1599,'Намазываем печенье взбитым яйцом, посыпаем кокосовой стружкой. И отправляем в духовку при 180°С на 20-30 минут. Рекомендую следить за печеньем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1600,'Отвариваем до готовности куриные яйца и картофель. Остужаем и чистим. Нарезаем картофель и яйца небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1600,'Сыр я натираю на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1600,'Свежий помидор и копченую курицу нарезаем произвольно, небольшими кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1600,'Красный лук и зелень укропа мелко нашинкуем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1600,'Смешиваем все продукты в салатнике и заправляем майонезом, солим и перемешиваем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1601,'Свинину тонко нарезать. Лук нарезать полукольцами. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1601,'В кастрюлю выложить кимчи, влить рассол от кимчи, сверху выложить лук и мясо. Добавить сахар, красный перец, перцовую пасту, кунжутное масло и воду. НЕ ПЕРЕМЕШИВАТЬ.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1601,'Поставить кастрюлю на средний огонь, накрыть крышкой и варить 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1601,'Через 10 минут все хорошо перемешать, добавить сверху тофу, накрыть крышкой и варить еще 15 минут. Подавать с рисом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1602,'В глубокую чашку высыпаем просеянную муку, соль, сахар, дрожжи и все хорошо перемешиваем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1602,'Готовое тесто аккуратно мнём около минуты, чтобы «выгнать» воздух изнутри. Затем равномерно распределяем его по предварительно смазанной маслом форме для выпечки, накрываем и оставляем минут на 30, снова даём подняться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1602,'Затем делаем выемки в тесте и кладем в каждую выемку начинку. У меня это оливки и помидоры черри. Сверху посыпаем итальянскими травами и поливаем оливковым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1602,'Выпекаем в разогретой до 200 градусов духовке 15-20 минут. До образования румяной корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1603,'Приобрести в магазине готовое слоеное тесто, понадобится два прямоугольника.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1603,'Наколоть пласты вилкой, время выпекания – 15 минут, температура – 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1603,'Для приготовления крема взбить сливки, затем добавить молоко и пудинг, ингредиенты еще раз взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1604,'Фасоль замочить холодной водой с вечера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1604,'Утром довести до кипения в той же воде, в которой продукт замачивался.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1604,'Жидкость слить, фасоль промыть и залить новой порцией воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1604,'Сварить без соли.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1604,'Готовый продукт посолить, добавить сладкую паприку, сушеную мяту и нарезанные кружками копченые колбаски.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1604,'Отдельно обжарить муку и чеснок на растительном масле.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1604,'Добавить смесь в отваренную фасоль, довести до кипения и подать на стол.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1605,'Яйцо перемешать с манной крупой и солью, дать постоять для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1605,'Опускать клецки чайной ложкой в кипящий бульон. Время варки – пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1606,'Немного согреть молоко, всыпать дрожжи, сахарный песок, смесь оставить на 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1606,'Муку просеять, всыпать молотую корицу, добавить мягкое сливочное масло комнатной температуры, ингредиенты перетереть в крошку, добавить дрожжи с молоком, вбить сырое яйцо. Тесто должно получиться гладким, вымешивать десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1606,'Оставить продукт на час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1606,'Сформовать круглые булочки, оставить еще на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1606,'Приготовить отдельно тесто для полосок из муки и воды.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1606,'Выложить кресты, булочки печь при температуре 220 градусов в течение 10 минут, затем еще от 15 до 20 минут при температуре 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1606,'Готовую выпечку полить горячим сиропом, приготовленным из сахарного песка, воды, мускатного ореха, имбиря, ванили и душистого перца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1607,'Мексиканскую тортилью нарезать на равные полоски, шириной около 3-4см. Смазать каждую полоску красным соусом для пиццы, выложить по несколько сырных ломтиков. Сыр лучше использовать козий Бри или итальянскую Моцареллу, они очень легко плавятся и придают блюду изысканный и неповторимый вкус. Сверху присыпать сыр молотым сухим тимьяном, можно добавить несколько тонких пластинок резаных маслин. Закрутить роллы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1607,'Разложить роллы на противень, сбрызнуть водой или смазать оливковым ароматным  маслом, слегка присыпать тимьяном или розмарином и поставить в разогретую до 180 градусов духовку. Время готовки 5-7 минут, пока сыр не начнет плавиться, поверхность тортильи должна зарумяниться. Легкие роллы-пицца из тортильи, отличная идея для быстрого перекуса, и просто вкусное угощение.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1608,'В кастрюлю влить кефир и молоко, поставить на тихий огонь, прогревать до тех пор, пока не отделится прозрачная сыворотка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1608,'Продукт оставить постоять на 10 минут, процедить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1609,'Для начала разогреем оливковое масло и положим немного сливочного. Начнём обжаривать порезанный лук, к нему начнём добавлять молотые кумин, кардамон, куркума и гвоздику.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1609,'Все хорошо перемешать и добавим рис, рис нужно обжарить и после добавить тёплую воду, положить пару листиков лаврового листа и посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1609,'Оставляем до готовности риса, периодически помешивая, при подаче посыпать немного зелени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1610,'Маринад.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1610,'Начинка.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1610,'Моем, чистим карпа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1610,'Смазываем рыбу внутри маринадом и наполняем брюшко начинкой. Скрепляем шпажками. Смазываем рыбу маринадом снаружи и жарим на углях 25-30 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1611,'Нарезать репчатый лук, добавить говяжий фарш, посолить и поперчить по вкусу, влить пассату, добавить сахар, соль, черный молотый перец, сухой чеснок, чабрец, базилик, майоран и орегано.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1611,'Долить оливковое масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1611,'Накрыть, потушить в течение 12 – 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1611,'Спагетти отварить так, как написано на упаковке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1611,'Процедить, добавить соус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1612,'Взбить сахарный песок с сырыми куриными яйцами, ванильным сахаром из пакетика. Готовый продукт должен побелеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1612,'Влить простоквашу и растительное масло порциями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1612,'Всыпать молотую корицу и муку, разрыхлитель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1620,'Всыпать муку, замесить тесто, оставить на полчаса в тепле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1612,'Готовое тесто перелить в форму, поставить в духовой шкаф на десять минут, температура приготовления – от 180 до 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1612,'Корж достать, выложить половинки слив без косточек, вернуть в духовку на полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1613,'Срезать крышку у лепешек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1613,'Сырые куриные яйца посолить по вкусу, добавить каймак, перемешать вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1613,'Смесь вылить на лепешки, переложить их на лист, поставить в заранее разогретую духовку на 10 или 12 минут, температура приготовления – 220 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1613,'Когда начинка схватится – накрыть лепешки крышечками, поставить в духовой шкаф еще на пять минут, температуру уменьшить до 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1614,'Прогреть молоко, всыпать дрожжи из пакетика, сахарный песок и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1614,'Добавить половинку сырого яйца, маргарин, почти всю муку, разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1614,'Ингредиенты перемешать, всыпать оставшуюся муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1614,'Замесить тесто, положить его в полиэтиленовый пакет завязать, оставить на час',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1614,'Готовое тесто поделить на части, обмять, сформовать пирожки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1614,'Поставить на расстойку на 15 минут, верх смазать остатками яйца, перемешанного с молоком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1614,'Время выпекания – 20 минут, температура – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1615,'Сырую печень не нужно солить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1615,'Продукт нарезать, обвалять в муке, обжарить на несильном огне, не допуская пересушивания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1615,'Готовую печень можно подать с нарезанным репчатым луком, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1616,'Сыр натереть на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1616,'Добавить к нему яйца и муку и замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1616,'Раскатать тесто в пласт толщиной в 1 см и нарезать на полоски такого же размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1616,'Обжарить хворост в большом количестве масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1617,'Лук репчатый мелко режем, шампиньоны режем пластиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1617,'На разогретую сковородку кладем сливочное масло и обжариваем лук до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1617,'Туда же кладем шампиньоны, обжариваем 5 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1617,'Картофель трем на мелкой терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1617,'Чеснок мелко режем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1617,'Картофель отжимаем, сливаем лишнюю жидкость.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1617,'В картофель добавляем чеснок,перец,яйца, перемешиваем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1617,'На разогретую сковородку наливаем растительное масло.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1618,'Сладкий болгарский перец очистить от семенных камер, промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1618,'Белокочанную капусту крупно нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1618,'Поставить воду на плиту, влить уксус, растительное масло, всыпать соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1618,'Положить перец, варить пять минут, вынуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1618,'Отварить в той же воде с уксусом острый перец в течение трех или пяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1618,'В последнюю очередь отварить капусту, время – от семи до восьми минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1618,'Чеснок очистить и размолоть в блендере, добавить уксус, масло, петрушку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1618,'Салат переложить в банки, чередуя слои – капуста с перцем, немного присыпать солью и чесночной смесью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1618,'Долить оставшийся рассол до плечиков, закрыть, оставить на пять или шесть часов, переставить в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1619,'Подогреть молоко, добавить соль и сахар, дрожжи, перемешать, влить растительное масло, всыпать муку, замесить тесто. Время вымешивания – семь минут, за это время продукт должен загустеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1619,'Скатать тесто в шар, переложить в заранее смазанную растительным маслом миску, затянуть пленкой, оставить на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1619,'Тесто обмять, разрезать на кусочки, раскатать их в лепешки. Каждую заготовку смазать растительным маслом, свернуть рулетом, а затем бубликом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1619,'Накрыть пленкой на 20 минут, смазать смесью из молока и желтка. Время выпекания – 25 минут, температура – от 180 до 190 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1620,'Прогреть кефир с растительным маслом, всыпать дрожжи из пакетика, соль и сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1621,'Сметану отвесить в марле на 10 или 12 часов, чтобы получился густой крем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1621,'Отдельно соединить сахар с мягким маргарином, яйцами, солью, натуральным медом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1621,'Поставить смесь на плиту, прогреть до растворения ингредиентов, с огня снять, всыпать пищевую соду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1621,'Добавить муку, замесить тесто, разделить его на части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1621,'Выпечь коржи, температура приготовления – 200 градусов, время – несколько минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1621,'Для пчел растопить шоколад, перемешать с медом, сформовать насекомых.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1621,'Нарисовать на брюшке полоски при помощи белого шоколада, крылышки сделать из миндаля.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1621,'Для приготовления крема густую сметану взбить с сахарной пудрой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1621,'Собрать торт, посыпать крошкой из обрезков, украсить пчелами.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1622,'Перемешать сырые куриные яйца с сахаром, ванилином из пакетика, молоком, растопленным сливочным маслом, солью, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1622,'Просеять муку, перемешать с разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1622,'Все ингредиенты соединить, взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1622,'Готовое тесто переложить в форму, сверху – половинки абрикосов. Время выпекания – от 35 до 40 минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1623,'Для начала отварим яйца и картофель. остужаем и почистив нарезаем небольшим кубиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1623,'Также нарезаем и крабовые палочки, а плавленый сырок натираем на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1623,'Свежий помидор мелко нарезаем, а 2 зубчика чеснока выдавливаем через чесногкодавку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1623,'Измельчаем зелень укропа и красный салатный лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1623,'Смешиваем все ингредиенты в салатнике и добавляем консервированный горошек предварительно слив из него жидкость.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1623,'Заправляем салат майонезом и посолив перемешиваем наш крабовый салат в салатнике.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1624,'Сделать разрез на одной стороне филе курицы, в виде кармана.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1624,'Отбить мясо с обеих сторон, натереть ароматными травами и посолить, одну сторону намазать столовой горчицей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1624,'Для приготовления начинки нарезать маринованные огурцы, сыр и ветчину.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1624,'Вывернуть грудку наизнанку через боковой разрез, начинка должна остаться внутри.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1624,'Придать филе форму крупной котлеты, смочить во взбитом яйце и в панировочных сухарях.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1624,'Жарить на сковороде с обеих сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1625,'Для приготовления нужно напечь полтора десятка блинов по любимому рецепту, тонких и несладких.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1625,'Приготовить начинку из пропущенной через мясорубку ветчины и очищенного чеснока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1625,'Вбить сырые куриные желтки, посолить и поперчить по вкусу, ввести взбитые отдельно белки и сливки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1625,'Уложить в форму блины, промазывать начинкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1625,'Верх торта полить растопленным сливочным маслом и сухарями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1625,'Время выпекания в духовом шкафу – от 25 до 30 минут, температура – около 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1626,'Заварить крепкий кофе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1626,'Перемешать муку, мед, сахарный песок, молотую корицу, тертый имбирь, соль и пищевую соду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1626,'Влить в массу остывший кофе, замесить тесто и добавить в него чернослив.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1626,'Время выпекания в духовке – около получаса, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1627,'Отцедить вишни от лишнего сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1627,'Приготовить тесто из яиц с сахарным песком, ванильным сахаром, сметаной, разрыхлителем, заранее растопленным сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1627,'Муку всыпать постепенно, порциями, замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1627,'Смазать маслом форму, переложить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1627,'В вишню всыпать крахмал и выложить ягоды поверх теста.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1627,'Время приготовления пирога – 45 минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1628,'Перемешать сгущенное молоко с сырыми куриными яйцами, всыпать пищевую соду, просеянную муку, соль. Замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1628,'Выложить массу на рабочую поверхность, присыпанную мукой, раскатать валики, каждый разделить на части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1628,'Скрепить концы, сформовать небольшие бублики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1669,'Вылить в форму из силикона, накрыть листом фольги.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1628,'Противень застелить бумагой для выпекания, выложить баранки, смазать оставшимся вбитым яйцом, присыпать маковым семенем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1628,'Время выпекания – от 15 до 20 минут, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1629,'Нашинковать капусту мелко. Проварить в малом количестве воды одну минуту после закипания. Отцедить жидкость, откинув капусту на металлическое сито. Нарезать мелко различную зелень: укроп, зеленый лук, петрушку. Говяжий фарш смешать с сухой смесью прованских трав и обжарить на растительном масле. Во время жарки, фарш сбивается в комочки и запекается благодаря содержанию белка, поэтому так важно размешивать фарш постоянно придавая ему рыхлую структуру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1629,'В конце жарки посолить фарш и отставить на время. В сковороде соединить рубленую зелень с фаршем и бланшированной капустой, хорошенько перемешать. В широкую миску влить кефир, добавить соду, майонез и вбить туда 3 яйца. Взбить массу до однородности. Просеянную муку небольшими порциями подмешивать в яично-кефирную смесь, взбить при помощи венчика в жидкое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1629,'Разъемную форму выстелить пергаментной бумагой или пищевой фольгой и смазать растительным маслом. Половину от общего количества теста вылить в форму и разровнять, постучав формой по столу. Сверху выложить начинку и вылить на нее вторую половину теста. Духовку включить, установив на 180 градусов и поставить туда форму с пирогом. Выпекать полчаса. Нежный пирог с капустой и говядиной готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1630,'Сыр натираем на мелкой терке (часть из него я использовал именно для соуса, другую часть для закуски). Часть сыра перекладываем в тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1630,'Чеснок при помощи чеснодавилки выдавливаем к сыру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1630,'Укроп мелко нарезаем и добавляем его к сыру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1630,'Соль, перец по вкусу,',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1630,'Далее добавляем сметану 4 ч.л. и майонез 1 ч.л. и все хорошо перемешиваем. И убираем в сторону.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1630,'Вареную колбасу или же вы можете использовать любую другую колбасу, нарезаем маленьким кубиком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1630,'Лаваш нарезаем на равные части. У меня получилось 8 частей,',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1630,'На лаваш намазываем соус, добавляем немного вареной колбасы, и сыра. Загибаем края, и заворачиваем в конверт.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1630,'Далее с двух сторон обжариваем данные конвертики до золотистой корочки. Все готово.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1631,'Заливаем кипятком 100 грамм изюма. В это время 500 грамм творога смешиваем с одним яйцом, двумя столовыми лодками сахара и одной упаковкой ванильного сахара до однородной массы. После чего запаренный изюм процеживаем через дуршлаг и выкладываем на полотенце чтобы убрать лишнюю влагу. Как только поверхность изюма высохла, добавляем его в творог и перемешиваем до равномерного распределения компонентов начинки.','https://vkuso.ru/data/cache/data/48/67b9240856d6348_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1631,'Заливаем в кастрюлю 700 грамм молока и ставим на огонь до закипания. В это время в оставшиеся 300 грамм молока добавляем 250 грамм крахмала, одно яйцо, пачку ванильного сахара и столовую ложку простого сахара. Все это перемешиваем до однородной массы, чтобы не было комочков. Как только молоко закипело вливаем в него тонкой струйкой крахмал разведенный в молоке, при этом интенсивно мешаем содержимое кастрюли ложкой. В кастрюле начнет образоваться вязкое тесто, которое нужно перемешивать пока не исчезнут все комочки. Полученное тесто выкладываем на коврик и продолжаем месить добавляя сухой крахмал. Месим до тех пор пока тесто не станет плотным и тягучим. Тесто укладываем в полиэтиленовый пакет чтобы оно быстро не остывало.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1631,'Лепить вареники можно пока тесто горячее иначе холодный крахмал не будет слипаться. С кусочка крахмального теста делаем блинчик и оборачиваем его вокруг начинки, сдавливаем края блинчика как при лепке простых вареников.','https://vkuso.ru/data/cache/data/e2/2b130a686ed47e2_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1631,'Вареники бросаем в закипевшую воду и варим пока крахмал приготовиться и станет упругим. Готовые вареники выкладываем в глубокую миску, добавляем 50 грамм сливочного масла и две ложки сметаны. Подавать вареники к столу нужно в горячем виде. Такое блюдо оценят все Ваши гости, потому как оно будет просто таять во рту.','https://vkuso.ru/data/cache/data/a9/b58bfe56be796a9_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1632,'Измельчаем овощи. Морковь нарезать кубиками. Так же измельчаем лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1632,'В кастрюлю налить подсолнечное масло, добавить сливочное. На среднем огне обжарить овощи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1632,'Тем временем куриное филе нарезать на небольшие кусочки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1632,'Картофель нарезать небольшими кубиками и отправить в кастрюлю.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1632,'Добавить специи. У меня универсальная овощная приправа (без усилителей вкуса!), мускатный орех, куркума, паприка, гранулированный чеснок, петрушка (у меня замороженная).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1632,'Добавить лапшу. Варить до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1632,'Влить сливки, посолить, довести до кипения и выключить.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1633,'Брокколи опускаем в кипящую воду на 3-5 минут. Затем сразу опускаем в ледяную воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1633,'Кунжут обжариваем на сухой сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1633,'Чеснок нарезаем пластинками и обжариваем в раскаленном масле несколько секунд.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1633,'Чеснок вынимаем и добавляем к маслу соевый соус и сразу выключаем огонь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1633,'Брокколи разбираем на соцветия, выкладываем сверху чесночные чипсы, поливаем заправкой и посыпаем кунжутом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1634,'Растопить в кастрюле сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1634,'Отдельно перемешать сахарный песок и какао-порошок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1634,'Всыпать сухие ингредиенты в масло, влить молоко, перемешать, прогреть на огне до растворения сахара.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1634,'Смесь нагреть до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1634,'Массу остудить, немного оставить для глазури, в остальную часть всыпать муку, соду, вбить сырые яйца, взбить миксером.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1634,'Тесто отправить выпекаться в духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1634,'Для крема перемешать вареное сгущенное молоко со сливочным маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1634,'Готовый корж разрезать по горизонтали на три части, каждый слой промазать кремом, верх полить оставшейся шоколадной глазурью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1635,'Перемешать сырые куриные яйца с молоком, солью, растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1635,'Всыпать поленту, пшеничную муку, разрыхлитель, ингредиенты перемешать, влить минеральную воду, а затем сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1635,'Выпечь массу в заранее смазанной маслом форме.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1635,'Время приготовления – 20 минут, температура – 220 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1636,'В мед добавить соду, перемешать. Оставить на 10-15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1636,'В миску вбить яйца, добавить щепотку соли. При помощи миксера взбивать около минуты. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1636,'Добавить оставшуюся половину сахара, взбивать до твердых пиков, около 10 мин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1636,'В мед добавить 1 ст.л. яичной смеси, перемешать, влить в миску к яйцам и аккуратно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1636,'Муку смешать с разрыхлителем. Просеять в 2 этапа в яичную смесь и аккуратно вмешать с помощью венчика.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1636,'Форму для выпечки смазать растительным маслом, дно застелить бумагой для выпечки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1636,'Выложить тесто в форму, разровнять. Прокрутить форму с тестом и обстучать, чтобы тесто распределилось равномерно.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1636,'Поставить в разогретую до 170°С духовку на 40 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1636,'Крем для выравнивания:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1636,'Крем для прослойки:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1636,'У остывшего бисквита срезать верхушку и затем разрезать его на 3 коржа. Грецкие орехи мелко нарубить ножом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1636,'Сборка торта:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1644,'Горячими переложить в кастрюлю, прикрыть крышкой на 10 или 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1684,'Накрыть оставшимся субпродуктом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1636,'Верхушку бисквита измельчить в крошку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1637,'Взбить сырые куриные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1637,'В отдельной посуде перемешать соду, муку и сухой кисель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1637,'Порциями ввести взбитые яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1637,'Нарезать кубиками свежие ягоды клубники, обвалять в муке и всыпать в тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1637,'Ингредиенты еще раз перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1637,'Смазать форму для выпекания, вылить тесто с ягодами, отправить в духовку на полчаса, температура приготовления – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1637,'Для приготовления желе залить пакетик продукта горячей водой, перемешать, оставить до остывания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1637,'Готовый пирог вынуть из духового шкафа, остудить, из формы не вынимать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1637,'Украсить пирог еще одной порцией клубники, залить желе.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1637,'Пирог поставить в холодильник на два часа.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1637,'Вынуть выпечку из формы, переложить на блюдо.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1638,'Сырые куриные белки взбить в пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1638,'Размешать творог с сахаром, желтками, молоком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1638,'Влить горячую воду в манную крупу, добавить в творожную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1638,'Добавить белки, осторожно перемешать, так, чтобы они не осели.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1638,'Перелить массу в форму, поставить ее в емкость большего размера с кипящей водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1638,'Печь при температуре 180 градусов, время – от получаса до 35 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1639,'Перемешать сахарный песок с сырым яйцом, молотой корицей, медом, мягким маргарином, поставить смесь на водяную баню.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1639,'Прогреть до растворения, всыпать соду и муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1639,'Разделить тесто на три части: две одинаковые и большие, одна маленькая, из нее слепить украшения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1639,'Сформовать пряник, промазать любым джемом, например, сливовым.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1639,'Сверху поместить фигурки из теста.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1639,'Время выпекания – 20 минут, температура – 180 градусов. Полить глазурью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1640,'В кефир или кислый йогурт добавить растительное масло, соль, муку, соду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1640,'В конце замешивания добавить оставшуюся муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1640,'Готовое тесто на 15 минут оставить на столе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1640,'Для приготовления начинки перемешать фарш с яйцом, соль и молотый черный перец – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1640,'Добавить перемолотый с помощью блендера репчатый лук, зелень – по желанию.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1640,'Тесто раскатать в овальную лепешку, выложить половину начинки, отваренные и очищенные куриные яйца и снова слой фарша.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1640,'Накрыть тестом, смазать желтком, посыпать семенами кунжута.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1640,'Время выпекания – от 40 до 50 минут, температура приготовления – от 190 до 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1641,'Взбить сырые куриные яйца с сахарным песком и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1641,'Добавить мягкое сливочное масло или маргарин, сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1641,'Всыпать муку и пищевую соду, замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1641,'Выложить массу в форму, слепить бортики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1641,'Выложить ягоды вишни без косточек, залить смесью сметаны, крахмала и сахара.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1641,'Время выпекания – от 35 до 40 минут, температура приготовления – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1642,'Просеять крахмал и муку, всыпать пищевую соду, сахарный песок и ванилин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1642,'В отдельной миске перемешать растительное масло с водой и уксусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1642,'Замесить тесто, дать ему постоять 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1642,'Затем раскатать и вырезать печенье при помощи формочек, наколоть вилкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1642,'Время выпекания – от 15 до 20 минут, температура – от 150 до 160 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1643,'Взбить сырые куриные яйца с сахарным песком, влить растительное масло и молоко, всыпать муку и разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1643,'Выпечь в вафельнице.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1644,'Болгарский перец промыть, наколоть вилкой или ножом в нескольких местах, выложить на противень. Время запекания – от 40 минут, температура приготовления – от 200 до 220 градусов, в процессе плоды переворачивать для равномерного прогрева.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1644,'Готовый перец очистить от кожицы, семян, посолить, добавить нарезанную петрушку и чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1644,'Полить растительным маслом, смешанным с уксусом, подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1645,'Для приготовления начинки нарезать репчатый лук или лук-порей, обжарить их на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1645,'Добавить мясной фарш, посолить и поперчить, жарить все вместе две минуты. Если мясо сухое – можно долить еще немного растительного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1645,'Смазать противень, выложить два листа готового теста «Фило» или «Коре», на него – немного начинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1645,'Еще слой теста, начинка, повторять несколько раз, сверху – тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1645,'Для приготовления заливки перемешать минеральную воду с йогуртом, солью, яйцами, залить полученной смесью пирог, заранее разрезанный на квадратные кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1645,'Оставить заготовку на пять или десять минут на столе для пропитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1645,'Время выпекания – от получаса до 35 минут, температура – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1646,'Взбить сахарный песок с мягким сливочным маслом и ванилином.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1646,'Всыпать какао-порошок, влить заранее растопленный на водяной бане шоколад, массу взбивать, добавляя сырые куриные яйца по одному.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1646,'Всыпать муку, должно получиться негустое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1646,'Поставить в холод на два часа для набухания клейковины.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1646,'Тесто зачерпывать ложкой, обмакивать в сахарную пудру и выкладывать на противень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1646,'Время выпекания – от 13 до 15 минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1647,'Соединить готовое накрошенное печенье с растопленным сливочным маслом и медом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1647,'Массу выложить в форму для выпекания, поставить в морозильную камеру на 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1647,'Взбить сливки и сахарную пудру, отдельно взбить пастообразный творог тоже с сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1647,'Замочить желатин в воде на 10 минут, затем ввести его в творог, влить сливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1647,'Ингредиенты перемешать при помощи венчика.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1647,'Вылить творожную массу на основу из печенья и поставить в холод для застывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1647,'На застывшую заготовку выложить слой нарезанных нектаринов, залить желе, приготовленным так, как написано на упаковке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1648,'Мягкое сливочное масло взбить с сахарным песком, добавить сырые куриные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1648,'Муку просеять, всыпать пищевую соду, крахмал, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1648,'Сухие ингредиенты перемешать с масляной смесью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1648,'Замесить тесто, консистенция должна быть мягкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1648,'Массу переложить в пакет, оставить в холодильнике на один или два часа или на 15 минут поместить в морозильную камеру.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1648,'Сформовать небольшие шарики, выложить их на противень на некотором расстоянии друг от друга, украсить конфетками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1648,'Время выпекания – от 15 до 17 минут, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1649,'Быстрорастворимый желатин залить стаканом апельсинового сока и оставить набухать. Нарезать кружками апельсины и обчистить с них кожуру. Готовый бисквит нарезать небольшими кусочками. Ананас  и банан, так же. Апельсиновый сок с желатином через некоторое время поставить на водяную баню и растворить при постоянном помешивании, но, не давая жидкости вскипеть. Влить чуть остывший желатин с соком в йогурт и тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1649,'Торт можно делать в силиконовой большой форме, но ее красивее смотрится в миске в форме полусферы. Если использовать миску, то предварительно необходимо выстелить ее пищевой пленкой. Дно и бока формы устелить апельсиновыми кружками, плотно. Сверху выложить вперемешку нарезанный бисквит и банан, либо ананас. Залить все йогуртом с желатином. Повторить процедуру, расставляя апельсиновые кружочки по бокам и прижимая их фруктово-бисквитной начинкой, если не позволяет высота или количество продуктов апельсиновые кружки можно разрезать пополам, так даже интереснее смотрится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1654,'Просеять половину муки, перемешать. Добавить соль, перемешать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1654,'Накрыть тесто пищевой пленкой или полотенцем и оставить в теплом месте на 1 час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1649,'Поставить форму в холодильник застывать, но не в морозильную камеру. Через время, когда желе застынет, перевернуть форму на блюдо и снять, сначала миску, а затем пленку. Силиконовую форму лучше сначала окунуть в горячую воду на секунду, но не более того, верхний слой желе от разогретой формы станет податливее и торт, можно легко вынуть, накрыв форму блюдом, а затем резко перевернуть, так, чтобы блюдо оказалось на столе. Готовый оригинальный желейный торт «Апельсины в йогурте», можно украсить листиками перечной мяты и ягодами ежевики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1650,'Крупно нарезать мясо, лук, морковь, помидоры, сладкий болгарский перец, картофель и капусту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1650,'Для приготовления блюда понадобится кастрюля с толстым дном.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1650,'Налить в нее немного растительного масла, выложить мясо, половину нормы картофеля, репчатый лук, капусту и морковь, сладкий и острый перец, зеленый горошек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1650,'Каждый слой посолить по вкусу, приправить специями: вегетой, черным молотым перцем, сладкой паприкой, петрушкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1650,'Томатную пасту развести водой, влить в кастрюлю.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1650,'Емкость затянуть листом фольги, сделать проколы, накрыть крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1650,'Время тушения – 1 час 45 минут, огонь – тихий.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1651,'Мясо моем, сушим бумажным полотенцем, далее избавляемся от жилок, сухожилий, жира. Далее лично я разрезал мясо пополам, и после чего нарезал его поперёк волокон на порционные кусочки, толщеной чуть больше 1 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1651,'После этого я каждый кусочек отбил, 5-7 мм. ( До какой толщины нарезать, и отбить, вы можете решить сами.) Потом посолил, поперчил и посыпал другими приправами. Переложил на тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1651,'Далее взбил 3 куриных яйца, подготовил муку и панировочные сухари.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1651,'Подготовленное мясо запанировал в муке, далее отпустил его в взбитое куриное яйцо, слега потряс, чтобы часть куриного яйца стекла, и запанировал в панировочных сухарях. Переложил на тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1651,'Растительное масло, и обжарил каждый кусочек до золотистой корочки. Обжаривал около 2 минут. Как только кусочки были обжарены, осторожно их достал и переложил на тарелку с бумажным полотенцем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1651,'Для подачи я нарезал огурец и помидор. Вы можете приготовить любой гарнир на ваш вкус. Все готово.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1652,'Обжарить измельченный репчатый лук, сельдерей, морковь и чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1652,'Всыпать муку, обжарку хорошо перемешать и влить белое вино.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1652,'Добавить черный перец, соль, острый перец, сладкую паприку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1652,'Влить горячую воду, после закипания добавить мясо курицы, тушить 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1652,'Выложить помидоры без кожицы и сладкий перец, всыпать немного сахара и посолить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1652,'Время тушения – от 45 до 50 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1652,'Незадолго до окончания приготовления добавить лавровый лист.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1653,'Чистим картошку режем ее помельче и варим в подсоленной воле до готовности.Сливаем воду и остужаем картофель. Немного растолчем картофель и добавив яйца и соль сделаем картофельное пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1653,'Лук нарежем и обжарим вместе с фаршем на растительном масле в сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1653,'В миску натрем сыр. Нашинкуем зелень укропа и оставим ее на доске.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1653,'Картофельные рулет я буду делать на пищевой пленке. Отрезаю два куска пищевой пленки подходящего размера. Выкладываю пленку на стол с небольшим нахлестом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1653,'Теперь на эту пленку раскладываю все картофельное пюре в виде прямоугольника.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1653,'Сверху на картофельную основу выкладываю фарш с луком, затем натертый сыр и посыпаю все нашинкованным укропом. Начинку я выкладываю немного не доходя до краев картофельной основы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1653,'С помощью пленки сворачиваю картофельный рулет и перекладываю его на застеленный пергаментом противень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1653,'Готовим рулет примерно 30-35 минут в заранее разогретой до 180 градусов духовке.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1654,'В теплое молоко добавить дрожжи и сахар, перемешать, оставить на 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1654,'Сметану смешать с теплой водой и растительным маслом. Вбить яйцо, перемешать. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1669,'Поставить в горячую духовку на час, температура приготовления – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1654,'Для начинки нарезать картофель кубиками, залить водой, добавить 1 ч.л. соли и поставить на огонь. После того, как вода закипит, варить картофель 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1654,'Размять вареный картофель вилкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1654,'Лук нарезать мелко. Шампиньоны нарезать небольшими кубиками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1654,'В сковороду добавить 1 ч.л. растительного масла и 5 гр сливочного. Обжарить лук на сильном огне и затем добавить обжаренный лук к картофелю.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1654,'На той же сковороде обжарить шампиньоны с 1 ч.л. растительного и 5 гр сливочного масла. Добавить шампиньоны в начинку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1654,'Начинку посолить, поперчить по вкусу, перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1654,'Тесто разделить на 15 равных частей.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1654,'Пальцами разровнять кусочек теста в круг, выложить в центр круга начинку и защипнуть края.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1654,'Пирожки выложить на противень, застеленный бумагой для выпечки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1654,'Выпекать пирожки в разогретой до 180°С духовке 20 минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1655,'Просеять муку, добавить соль, половину нормы сахарного песка и ванилин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1655,'Отдельно взбить сырые куриные белки с лимонной кислотой и остатками сахара, порциями ввести муку и кукурузный крахмал.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1655,'Тесто вылить в хорошо смазанную и присыпанную мукой форму для выпекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1655,'Время приготовления – от получаса до 35 минут, температура – от 170 до 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1656,'Просеять крахмал с мукой, всыпать сахарный песок, разрыхлитель, соль, ванилин из пакетика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1656,'Отдельно соединить молоко с растительным маслом и яйцом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1656,'Обе смеси соединить и замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1656,'Раскатать, нарезать квадратики, наколоть вилкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1656,'Время выпекания – от восьми до десяти минут, температура приготовления – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1657,'Муку просеять вместе с разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1657,'Соединить сырые куриные яйца с сахарным песком, солью, взбить массу при помощи миксера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1657,'Влить растительное масло и молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1657,'Всыпать большую часть муки, хорошо перемешать, затем добавить остатки муки с паприкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1657,'Добавить в тесто сыр «Фета», измельченный шпинат, разложить в формочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1657,'Время выпекания – от получаса до 35 минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1658,'Для приготовления понадобится форма среднего размера круглой формы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1658,'Взбить с помощью миксера сырые куриные яйца с сахарным песком, время взбивания – от пяти до семи минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1658,'Просеять муку и вмешать ее в три приема.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1658,'Добавить ванилин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1658,'Время выпекания в мультиварке – один час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1658,'Готовый корж разрезать по горизонтали и промазать любимым кремом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1659,'Подготовим продукты. Лук измельчить.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1659,'В сковородку налить растительного масла и половину сливочного масла. Когда масло начнет пениться, добавить лук и готовить часто помешивая, до мягкости лука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1659,'Добавить грибы и жарить до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1659,'Переложить лук с грибами на тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1659,'Отправить мясо на сковороду одним слоем, добавить сливочное масло и готовить до румяной корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1659,'Посолить. Добавить бренди, и жарить до испарения алкоголя. Если мясо недостаточно нежное, добавить 50 мл воды и немного подержать под крышкой. Если использовать стейк или вырезку, данный шаг можно смело пропустить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1659,'Добавить к мясу лук с грибами, добавить паприку, влить сливки, добавить сметану, тщательно перемешать. Посыпать мелко рубленой петрушкой. Довести до кипения и выключить.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1660,'Для приготовления посыпки порубить очищенные грецкие орехи, смешать с мукой, сахарным песком, молотой корицей, сливочным маслом или маргарином.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1660,'Очистить и нарезать яблоки, присыпать сахарным песком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1684,'Сверху выложить кусочки инжира.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1660,'Для приготовления теста взбить мягкое сливочное масло или маргарин с сахаром, добавить ванилин из пакетика, сметану, разрыхлитель, пищевую соду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1660,'Ингредиенты еще раз взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1660,'Ввести порциями муку и сырые куриные яйца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1660,'Готовое тесто вылить в прямоугольную форму, разложить по поверхности нарезанные яблоки, посыпать ореховым штрайзелем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1660,'Время выпекания – от 45 до 50 минут, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1661,'Всыпать дрожжи в теплую воду, добавить немного сахара, но можно обойтись и без него.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1661,'Всыпать муку, оставить смесь на несколько минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1661,'Оставшуюся муку перемешать с манной крупой и посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1661,'Вылить смесь из жидких ингредиентов в муку, добавить оливковое масло, замесить тесто. Оно должно быть гладким и не липнуть к рукам. При необходимости можно вмесить еще немного муки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1661,'Оставить массу в тепле на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1661,'Раскатать две одинаковые лепешки, выложить их на противень, накрыть пленкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1661,'Время расстойки – полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1661,'Приготовить смесь из сырого желтка с молоком, присыпать кунжутом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1661,'Время выпекания – 10 минут, температура – 240 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1661,'Затем снизить до 190 – 200 градусов, печь еще от 15 до 20 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1661,'Второй вариант проще – выпекать полчаса при температуре 190 градусов, но лепешки при этом получаются менее пышными.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1662,'Очищенный картофель положить в кипящую воду на две минуты, затем жидкость слить, добавить оливковое масло, сладкую красную паприку, черный перец, соль, сухой порошковый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1662,'Выложить овощи на лист, время запекания – 25 минут, температура – от 200 до 220 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1663,'Подогреть молоко и воду, добавить дрожжи и сахарный песок, соль, куркуму, влить растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1663,'Ингредиенты перемешать, всыпать муку, замесить тесто. Оно не должно быть слишком тугим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1663,'Скатать в шар, выложить в миску, смазанную растительным маслом, верх плотно затянуть пищевой пленкой, оставить на час в тепле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1663,'Подошедшее тесто разделить на десяток булочек, скатать шарики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1663,'Выложить на противень, накрыть пленкой, оставить еще на 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1663,'Приготовить глазурь из кукурузной или рисовой муки с какао-порошком, немного дрожжей смешать с сахаром, влить воду, растительное масло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1663,'Смазать булочки толстым слоем полученной смеси, оставить на пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1663,'Время выпекания – от 20 до 25 минут, температура – 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1663,'В процессе выпекания глазурь полопается, образуя пятна на поверхности выпечки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1664,'Приготовить бисквит: предварительно разогреть духовку до 180 градусов. Форму диаметром 22-26 см смазать сливочным маслом, если форма разъемная выстелить дно пергаментной бумагой с заходом на бортики. Яйца разделить на желтки и белки. Желтки взбить с сахаром до увеличения объема и растворения сахара, белки – в крутую пену. Соединить просеянную муку с разрыхлителем и порционно ввести во взбитые желтки. Аккуратно ложкой добавить белковую пену и вмешать в тесто, стараясь не повредить объем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1664,'Переложить тесто в форму, разровнять силиконовой лопаткой и выпекать в духовке полчаса. Духовку за это время не открывать, иначе бисквит опуститься. Выключить духовку и дождаться ее остывания, после чего вытащить форму. Осторожно поддеть ножом края остывшего бисквита, отделяя его от бортиков формы. Вынуть корж и разделить его на два или даже три коржа одинаковой высоты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1664,'Взбить яйцо с сахаром. Добавить три ложки молока. Ввести понемногу муку, хорошо взбить, чтобы исключить появления сгустков. Оставшееся количество молока вскипятить, убавить огонь и понемногу, тонкой струйкой ввести яично-мучную смесь. Постоянно помешивая варить на медленном огне до сгущения. В конце добавить ванилин. Остудить и ввести мягкое, взбитое масло. Масло должно быть непременно свежим. Крем еще раз взбить. Банан разрезать на диагональные тонкие слайсы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1669,'Ввести нежирную сметану, мелкую соль, мускатный орех, кориандр, черный молотый перец, взбитые столовые яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1664,'В зависимости от количества полученных коржей делим крем на две или три части с расчетом, что верхний корж, также смазывается заварным кремом, но немного меньшим его количеством, так как еще предполагается глазурь. Смазать нижний корж кремом, выложить на него банановые дольки, накрыть следующим коржом, желательно, чтобы срез коржа оказался на верхушке. Верхний корж торта «Чародейка» с бананом и шоколадом пропитать сиропом и смазать заварным кремом. Поставить торт на холод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1664,'Приготовить пропитку для верхнего коржа: 50мл молока вскипятить с 2 ч.л. сахара, добавить одну чайную ложку коньяка или бананового ликера и пропитать верхний корж. В эмалированной посуде смешать сметану с какао-порошком, сахаром. Добавить размягченное масло и поставить на медленный огонь. Постоянно перемешивать пока сахар не растопиться, но при этом глазурь не должна вскипеть иначе она карамелизируется и на поверхности торта образуется корка. Когда глазурь остынет, покрываем ею охлажденный торт и его края. Расправляем поверхность силиконовой лопаткой или широким лезвием ножа, смоченным холодной водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1665,'Перемешать сырые куриные яйца при помощи венчика, добавить пропущенный через пресс чеснок, тертый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1665,'Репчатый лук измельчить, обжарить до золотистого цвета, добавить нарезанный соломкой кабачок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1665,'Соль и перец молотый – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1665,'Жарить до готовности в течение шести минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1665,'Обжарку переложить в яичную смесь, ингредиенты перемешать, вылить массу в форму для запекания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1665,'Помидоры нарезать кружками и разложить сверху.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1665,'Время запекания – 15 минут, температура – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1666,'Сырые куриные яйца взбить с сахарным песком до изменения цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1666,'В процессе взбивания влить кислое молоко или простоквашу, растительное масло, всыпать ванильный сахар из пакетика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1666,'Просеять муку, добавить молотую корицу и разрыхлитель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1666,'Жидкие ингредиенты соединить с сухими, перемешивать миксером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1666,'Форму для выпекания смазать маслом или маргарином, присыпать мукой, перелить тесто, поставить в духовой шкаф. Температура приготовления – 180 градусов, время – от семи до десяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1666,'Инжир разрезать на части, каждый плод – на четыре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1666,'Присыпать ванильным и обычным сахаром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1666,'Выложить начинку поверх пирога, поставить в духовку на 20 или 25 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1667,'Отварить картофель и мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1667,'В картофель влить молоко, положить кусочек сливочного масла, приготовить пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1667,'Вбить сырое куриное яйцо, массу быстро перемешать, чтобы оно не свернулось.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1667,'Отваренное мясо измельчить при помощи блендера или пропустить через мясорубку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1667,'Посолить и поперчить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1667,'Репчатый лук мелко нарезать, потушить на сливочном масле, добавить мясо, долить кипяченую воду или бульон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1667,'Смазать маслом форму для запекания, посыпать панировочными сухарями, выложить половину приготовленного пюре, затем слой мяса, вторую половину пюре.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1667,'Верх запеканки посыпать сухарями.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1667,'Время запекания – полчаса, температура – 200 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1668,'Репчатый лук обжарить на сковороде, добавить вегету, рис, красный острый перец, чеснок, пропущенный через пресс.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1668,'Смесь в горячем виде влить в фарш, посолить и поперчить, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1668,'Перец очистить от семенных камер, нафаршировать, закрыть отверстие кружком помидора и картофеля, выложить на растительное масло, налитого в форму для запекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1668,'Залить водой и пассатой, досолить, запекать под крышкой в течение часа или больше, температура – 220 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1668,'Время зависит от возможностей духовки и величины плодов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1668,'Блюдо открыть и прогревать без крышки еще 20 или 30 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1669,'Вымыть печень холодной водой, удалить пленки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1669,'Продукт перемолоть при помощи блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1669,'Добавить рубленый репчатый лук, перемолоть все вместе еще раз. Масса должна напоминать жидкое пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1669,'Огонь погасить, дать паштету постоять десять минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1669,'Блюдо остудить, поставить в холод на десять часов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1670,'Печень очистить от пленок, прожилок, промыть холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1670,'Обсушить субпродукт бумажными полотенцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1670,'Нарезать пластинками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1670,'Прогреть оливковое масло в сотейнике, обжарить нарезанный лук-шалот до получения румяной корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1670,'Добавить печень, жарить все вместе три минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1670,'Посыпать прованскими травами, снять с огня.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1670,'Массу остудить, влить коньяк, перемолоть в комбайне два раза.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1670,'Выложить в формы, убрать в холод на три часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1671,'Печень промыть, удалить сосуды и пленки, продукт обсушить полотенцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1671,'Нарезать тонкими пластинками, обжарить на прогретом рафинированном масле до получения румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1671,'Остудить, два раза перемолоть в блендере, долить сливки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1671,'Шампиньоны вымыть, нарезать произвольно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1671,'Репчатый лук очистить, нарезать тонкими кольцами, жарить до золотистой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1671,'Добавить шампиньоны, жарить до готовности продуктов. Остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1671,'Перемолоть массу при помощи блендера.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1671,'Добавить специи, мягкое сливочное масло, вымешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1671,'Выложить массу в контейнер, поставить в холод на три часа для настаивания.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1672,'Чернослив промыть, замочить в горячей воде на три часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1672,'Жидкость слить, продукт обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1672,'Залить сухофрукты коньяком на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1672,'Печень промыть, удалить пленки, нарезать продукт произвольно, жарить в сотейнике в течение пяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1672,'Влить сливки, потушить все вместе пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1672,'Массу остудить, перемолоть в блендере, ввести чернослив.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1672,'Массу еще раз перемолоть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1672,'Всыпать специи, переложить в емкость небольшого объема, поставить в холодильник на два или три часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1673,'Печень промыть, нарезать небольшими брусками, замочить в холодной воде на два или три часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1673,'Очистить морковь, лук, нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1673,'Измельчить сало.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1673,'Все продукты перемолоть в блендере.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1673,'Приправить паштет специями, вымесить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1673,'Выложить паштет в стерильные банки, оставить сверху немного пространства, примерно на полтора или два сантиметра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1673,'Поставить емкости на противень, отправить в холодный духовой шкаф.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1673,'Выставить невысокую температуру, печь паштет два часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1673,'Банки достать, закатать крышками, перевернуть и укутать в плед.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1673,'Закуска будет полностью готова через десять дней.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1674,'Сливочное масло оттаять при комнатной температуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1674,'Очистить сельдь, удалить внутренности, голову, хвост, кожу, тушку промыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1674,'Обсушить филе бумажным полотенцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1674,'Нарезать кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1674,'Нарезать морковь произвольно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1674,'Продукты пропустить через мясорубку несколько раз, пока масса не превратится в пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1674,'Другой вариант – приготовить паштет при помощи блендера.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1674,'Вмесить масло порциями.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1674,'Посолить и поперчить по вкусу, можно добавить любимые специи.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1675,'Морковь отварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1675,'Подготовить тушку сельди: отрезать хвост и голову, снять кожу, вынуть внутренности, кости. Промыть холодной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1675,'Отваренную морковь нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1675,'Подготовленные ингредиенты и плавленые сырки пропустить два раза через мясорубку или перемолоть блендером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1675,'Ввести специи, травы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1675,'Хранить в холодильнике под крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1676,'Сливочное масло размягчить при комнатной температуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1676,'Отварить яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1676,'Рыбу очистить и вымыть, удалить кости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1676,'Нарезать ломтиками репчатый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1676,'Любые орехи очистить и прогреть на сковороде в течение нескольких минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1676,'Продукты несколько раз перемолоть блендером.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1676,'Добавить в пюре масло и любимые специи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1676,'Поставить паштет холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1677,'Очистить сельдь от кожицы и костей, нарезать ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1677,'Любые орехи обжарить на сковороде или запечь в духовом шкафу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1677,'Продукты пропустить через мясорубку два или три раза или один раз перемолоть блендером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1677,'Пасту взбить с мягким сливочным маслом, творогом, приправами, солью, рублеными травами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1677,'Поставить массу в холодильник на несколько часов для пропитывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1678,'Сельдь без кожи и костей нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1678,'Яблоки с кожицей нарезать ломтиками, побрызгать лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1678,'Пропустить через мясорубку рыбу, репчатый лук, яблоки и белок отваренного яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1678,'Готовую рыбную пасту перетереть с имбирем и мягким сливочным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1678,'Соль и пряности – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1678,'Оставить в холодильнике на некоторое время для пропитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1679,'Рыбное филе нарезать кусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1679,'Перебить при помощи блендера рыбу, лук репчатый, зелень, корень имбиря, цедру и сок лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1679,'Другой вариант – пропустить два раза через мясорубку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1679,'Вбить в готовую массу сливочное масло, соль и пряности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1679,'Паштет остудить, дать постоять в холодильнике.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1680,'Сельдь очистить от хвоста, плавников, головы, вынуть кости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1680,'Филе нарезать ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1680,'Морковь отварить в воде или запечь до мягкости, также нарезать кусками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1680,'Приготовить пасту при помощи блендера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1680,'Добавить мягкое сливочное масло, любые специи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1680,'Оставить в холоде для пропитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1680,'Подать с ломтиками черного хлеба.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1681,'Измельчить морковь и репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1681,'Обжарить овощи на свином сале.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1681,'В конце приготовления шкварки удалить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1681,'Нарезать гусиную печень, удалить пленки, сосуды, волокна.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1681,'Обжарить все вместе до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1681,'Массу остудить и превратить в пюре при помощи блендера или мясорубки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1681,'Влить молоко, всыпать соль и специи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1681,'Еще раз обжарить массу на сковороде. Остудить, поставить в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1682,'Из печени удалить сосуды, субпродукт промыть холодной водой, обсушить полотенцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1682,'Мелко порубить репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1682,'Обжарить печень на сковороде вместе с луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1682,'Массу посолить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1682,'Влить немного воды.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1682,'Тушить на тихом огне в течение десяти или двенадцати минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1682,'Влить немного коньяка, тушить две минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1682,'Снять сковороду с огня. Содержимое остудить, всыпать специи, соль.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1682,'Массу превратить в пюре.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1682,'Перемешать с размягченным сливочным маслом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1682,'Все вместе еще раз перебить блендером.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1683,'Бобовые промыть и отварить так, как написано в инструкции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1683,'Очистить и нарезать печень и репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1683,'На сковороде вытопить гусиный жир.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1683,'Обжарить на нем печень и лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1683,'Добавить сладкую паприку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1683,'Продукты должны стать мягкими, но не зарумяниться.',NULL,6);
